window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["应急管理部"] = {"yejinqiyeheyousejinshuqiyeanquanshengchanguiding":[{"i":1,"n":"第一条","txt":"为了加强冶金企业和有色金属企业安全生产工作，预防和减少生产安全事故与职业病，保障从业人员安全健康，根据《中华人民共和国安全生产法》《中华人民共和国职业病防治法》，制定本规定。"},{"i":2,"n":"第二条","txt":"冶金企业和有色金属企业（以下统称企业）的安全生产（含职业健康，下同）和监督管理，适用本规定。 机械铸造企业中金属冶炼活动的安全生产和监督管理参照本规定执行。"},{"i":3,"n":"第三条","txt":"本规定所称冶金企业，是指从事黑色金属冶炼及压延加工业等生产活动的企业。 本规定所称有色金属企业，是指从事有色金属冶炼及压延加工业等生产活动的企业。 本规定所称金属冶炼，是指冶金企业和有色金属企业从事达到国家规定规模（体量）的高温熔融金属及熔渣（以下统称高温熔融金属）的生产活动。 黑色金属冶炼及压延加工业、有色金属冶炼及压延加工业的具体目录，由国家安全生产监督管理总局参照《国民经济行业分类》（GB/T4754）制定并公布。"},{"i":4,"n":"第四条","txt":"企业是安全生产的责任主体。企业所属不具备法人资格的分支机构的安全生产工作，由企业承担管理责任。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局指导、监督全国冶金企业和有色金属企业安全生产工作。 县级以上地方人民政府安全生产监督管理部门和有关部门（以下统称负有冶金有色安全生产监管职责的部门）根据本级人民政府规定的职责，按照属地监管、分级负责的原则，对本行政区域内的冶金企业和有色金属企业的安全生产工作实施监督管理。"},{"i":6,"n":"第六条","txt":"企业应当遵守有关安全生产法律、行政法规、规章和国家标准或者行业标准的规定。 企业应当建立安全风险管控和事故隐患排查治理双重预防机制，落实从主要负责人到每一名从业人员的安全风险管控和事故隐患排查治理责任制。"},{"i":7,"n":"第七条","txt":"企业应当按照规定开展安全生产标准化建设工作，推进安全健康管理系统化、岗位操作行为规范化、设备设施本质安全化和作业环境器具定置化，并持续改进。"},{"i":8,"n":"第八条","txt":"企业应当建立健全全员安全生产责任制，主要负责人（包括法定代表人和实际控制人，下同）是本企业安全生产的第一责任人，对本企业的安全生产工作全面负责；其他负责人对分管范围内的安全生产工作负责；各职能部门负责人对职责范围内的安全生产工作负责。"},{"i":9,"n":"第九条","txt":"企业主要负责人应当每年向股东会或者职工代表大会报告本企业安全生产状况，接受股东和从业人员对安全生产工作的监督。"},{"i":10,"n":"第十条","txt":"企业存在金属冶炼工艺，从业人员在一百人以上的，应当设置安全生产管理机构或者配备不低于从业人员千分之三的专职安全生产管理人员，但最低不少于三人；从业人员在一百人以下的，应当设置安全生产管理机构或者配备专职安全生产管理人员。"},{"i":11,"n":"第十一条","txt":"企业主要负责人、安全生产管理人员应当接受安全生产教育和培训，具备与本企业生产经营活动相适应的安全生产知识和管理能力。其中，存在金属冶炼工艺的企业的主要负责人、安全生产管理人员自任职之日起六个月内，必须接受负有冶金有色安全生产监管职责的部门对其进行安全生产知识和管理能力考核，并考核合格。 企业应当按照国家有关规定对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，了解有关安全生产法律法规，熟悉本企业规章制度和安全技术操作规程，掌握本岗位安全操作技能，并建立培训档案，记录培训、考核等情况。未经安全生产教育培训合格的从业人员，不得上岗作业。 企业应当对新上岗从业人员进行厂（公司）、车间（职能部门）、班组三级安全生产教育和培训；对调整工作岗位、离岗半年以上重新上岗的从业人员，应当经车间(职能部门)、班组安全生产教育和培训合格后，方可上岗作业。 新工艺、新技术、新材料、新设备投"},{"i":12,"n":"第十二条","txt":"企业从事煤气生产、储存、输送、使用、维护检修作业的特种作业人员必须依法经专门的安全技术培训，并经考核合格，取得《中华人民共和国特种作业操作证》后，方可上岗作业。"},{"i":13,"n":"第十三条","txt":"企业新建、改建、扩建工程项目（以下统称建设项目）的安全设施和职业病防护设施应当严格执行国家有关安全生产、职业病防治法律、行政法规和国家标准或者行业标准的规定，并与主体工程同时设计、同时施工、同时投入生产和使用。安全设施和职业病防护设施的投资应当纳入建设项目概算。"},{"i":14,"n":"第十四条","txt":"金属冶炼建设项目在可行性研究阶段，建设单位应当依法进行安全评价。 建设项目在初步设计阶段，建设单位应当委托具备国家规定资质的设计单位对其安全设施进行设计，并编制安全设施设计。 建设项目竣工投入生产或者使用前，建设单位应当按照有关规定进行安全设施竣工验收。"},{"i":15,"n":"第十五条","txt":"国家安全生产监督管理总局负责实施国务院审批（核准、备案）的金属冶炼建设项目的安全设施设计审查。 省、自治区、直辖市人民政府负有冶金有色安全生产监管职责的部门对本行政区域内金属冶炼建设项目实施指导和监督管理，确定并公布本行政区域内有关部门对金属冶炼建设项目安全设施设计审查的管辖权限。"},{"i":16,"n":"第十六条","txt":"企业应当对本企业存在的各类危险因素进行辨识，在有较大危险因素的场所和设施、设备上，按照有关国家标准、行业标准的要求设置安全警示标志，并定期进行检查维护。 对于辨识出的重大危险源，企业应当登记建档、监测监控，定期检测、评估，制定应急预案并定期开展应急演练。 企业应当将重大危险源及有关安全措施、应急预案报有关地方人民政府负有冶金有色安全生产监管职责的部门备案。"},{"i":17,"n":"第十七条","txt":"企业应当建立应急救援组织。生产规模较小的，可以不建立应急救援组织，但应当指定兼职的应急救援人员，并且可以与邻近的应急救援队伍签订应急救援协议。 企业应当配备必要的应急救援器材、设备和物资，并进行经常性维护、保养，保证正常运转。"},{"i":18,"n":"第十八条","txt":"企业应当采取有效措施预防、控制和消除职业病危害，保证工作场所的职业卫生条件符合法律、行政法规和国家标准或者行业标准的规定。 企业应当定期对工作场所存在的职业病危害因素进行检测、评价，检测结果应当在本企业醒目位置进行公布。"},{"i":19,"n":"第十九条","txt":"企业应当按照有关规定加强职业健康监护工作，对接触职业病危害的从业人员，应当在上岗前、在岗期间和离岗时组织职业健康检查，将检查结果书面告知从业人员，并为其建立职业健康监护档案。"},{"i":20,"n":"第二十条","txt":"企业应当加强对施工、检修等重点工程和生产经营项目、场所的承包单位的安全管理，不得将有关工程、项目、场所发包给不具备安全生产条件或者相应资质的单位。企业和承包单位的承包协议应当明确约定双方的安全生产责任和义务。 企业应当对承包单位的安全生产进行统一协调、管理，对从事检修工程的承包单位检修方案中的安全措施和应急处置措施进行审核，监督承包单位落实。 企业应当对承包检修作业现场进行安全交底，并安排专人负责安全检查和协调。"},{"i":21,"n":"第二十一条","txt":"企业应当从合法的劳务公司录用劳务人员，并与劳务公司签订合同，对劳务人员进行统一的安全生产教育和培训。"},{"i":22,"n":"第二十二条","txt":"企业的正常生产活动与其他单位的建设施工或者检修活动同时在本企业同一作业区域内进行的，企业应当指定专职安全生产管理人员负责作业现场的安全检查工作，对有关作业活动进行统一协调、管理。"},{"i":23,"n":"第二十三条","txt":"企业应当建立健全设备设施安全管理制度，加强设备设施的检查、维护、保养和检修，确保设备设施安全运行。 对重要岗位的电气、机械等设备，企业应当实行操作牌制度。"},{"i":24,"n":"第二十四条","txt":"企业不得使用不符合国家标准或者行业标准的技术、工艺和设备；对现有工艺、设备进行更新或者改造的，不得降低其安全技术性能。"},{"i":25,"n":"第二十五条","txt":"企业的建（构）筑物应当按照国家标准或者行业标准规定，采取防火、防爆、防雷、防震、防腐蚀、隔热等防护措施，对承受重荷载、荷载发生变化或者受高温熔融金属喷溅、酸碱腐蚀等危害的建（构）筑物，应当定期对建（构）筑物结构进行安全检查。"},{"i":26,"n":"第二十六条","txt":"企业对起重设备进行改造并增加荷重的，应当同时对承重厂房结构进行荷载核定，并对承重结构采取必要的加固措施，确保承重结构具有足够的承重能力。"},{"i":27,"n":"第二十七条","txt":"企业的操作室、会议室、活动室、休息室、更衣室等场所不得设置在高温熔融金属吊运的影响范围内。进行高温熔融金属吊运时，吊炉与大型槽体、高压设备、高压管路、压力容器的安全距离应当符合有关国家标准或者行业标准的规定，并采取有效的防护措施。"},{"i":28,"n":"第二十八条","txt":"企业在进行高温熔融金属冶炼、保温、运输、吊运过程中，应当采取防止泄漏、喷溅、爆炸伤人的安全措施，其影响区域不得有非生产性积水。 高温熔融金属运输专用路线应当避开煤气、氧气、氢气、天然气、水管等管道及电缆；确需通过的，运输车辆与管道、电缆之间应当保持足够的安全距离，并采取有效的隔热措施。 严禁运输高温熔融金属的车辆在管道或者电缆下方，以及有易燃易爆物质的区域停留。"},{"i":29,"n":"第二十九条","txt":"企业对电炉、电解车间应当采取防雨措施和有效的排水设施，防止雨水进入槽下地坪，确保电炉、电解槽下没有积水。 企业对电炉、铸造熔炼炉、保温炉、倾翻炉、铸机、流液槽、熔盐电解槽等设备，应当设置熔融金属紧急排放和储存的设施，并在设备周围设置拦挡围堰，防止熔融金属外流。"},{"i":30,"n":"第三十条","txt":"吊运高温熔融金属的起重机，应当满足《起重机械安全技术监察规程--桥式起重机》(TSGQ002)和《起重机械定期检验规则》（TSGQ7015）的要求。 企业应当定期对吊运、盛装熔融金属的吊具、罐体（本体、耳轴）进行安全检查和探伤检测。"},{"i":31,"n":"第三十一条","txt":"生产、储存、使用煤气的企业应当建立煤气防护站（组），配备必要的煤气防护人员、煤气检测报警装置及防护设施，并且每年至少组织一次煤气事故应急演练。"},{"i":32,"n":"第三十二条","txt":"生产、储存、使用煤气的企业应当严格执行《工业企业煤气安全规程》（GB6222），在可能发生煤气泄漏、聚集的场所，设置固定式煤气检测报警仪和安全警示标志。 进入煤气区域作业的人员，应当携带便携式一氧化碳检测报警仪，配备空气呼吸器，并由企业安排专门人员进行安全管理。 煤气柜区域应当设有隔离围栏，安装在线监控设备，并由企业安排专门人员值守。煤气柜区域严禁烟火。"},{"i":33,"n":"第三十三条","txt":"企业对涉及煤气、氧气、氢气等易燃易爆危险化学品生产、输送、使用、储存的设施以及油库、电缆隧道（沟）等重点防火部位，应当按照有关规定采取有效、可靠的防火、防爆和防泄漏措施。 企业对具有爆炸危险环境的场所，应当按照《爆炸性气体环境用电气设备》（GB3836）及《爆炸危险环境电力装置设计规范》（GB50058）设置自动检测报警和防灭火装置。"},{"i":34,"n":"第三十四条","txt":"企业对反应槽、罐、池、釜和储液罐、酸洗槽应当采取防腐蚀措施，设置事故池，进行经常性安全检查、维护、保养，并定期检测，保证正常运转。 企业实施浸出、萃取作业时，应当采取防火防爆、防冒槽喷溅和防中毒等安全措施。"},{"i":35,"n":"第三十五条","txt":"企业从事产生酸雾危害的电解作业时，应当采取防止酸雾扩散及槽体、厂房防腐措施。电解车间应当保持厂房通风良好，防止电解产生的氢气聚集。"},{"i":36,"n":"第三十六条","txt":"企业在使用酸、碱的作业场所，应当采取防止人员灼伤的措施，并设置安全喷淋或者洗涤设施。 采用剧毒物品的电镀、钝化等作业，企业应当在电镀槽的下方设置事故池，并加强对剧毒物品的安全管理。"},{"i":37,"n":"第三十七条","txt":"企业对生产过程中存在二氧化硫、氯气、砷化氢、氟化氢等有毒有害气体的工作场所，应当采取防止人员中毒的措施。 企业对存在铅、镉、铬、砷、汞等重金属蒸气、粉尘的作业场所，应当采取预防重金属中毒的措施。"},{"i":38,"n":"第三十八条","txt":"企业应当建立有限空间、动火、高处作业、能源介质停送等较大危险作业和检修、维修作业审批制度，实施工作票（作业票）和操作票管理，严格履行内部审批手续，并安排专门人员进行现场安全管理，确保作业安全。"},{"i":39,"n":"第三十九条","txt":"企业在生产装置复产前，应当组织安全检查，进行安全条件确认。"},{"i":40,"n":"第四十条","txt":"负有冶金有色安全生产监管职责的部门应当依法加强对企业安全生产工作的监督检查，明确每个企业的安全生产监督管理主体，发现存在事故隐患的，应当及时处理；发现重大事故隐患的，实施挂牌督办。"},{"i":41,"n":"第四十一条","txt":"负有冶金有色安全生产监管职责的部门应当将企业安全生产标准化建设、安全生产风险管控和隐患排查治理双重预防机制的建立情况纳入安全生产年度监督检查计划，并按照计划检查督促企业开展工作。"},{"i":42,"n":"第四十二条","txt":"负有冶金有色安全生产监管职责的部门应当加强对监督检查人员的冶金和有色金属安全生产专业知识的培训，提高其行政执法能力。"},{"i":43,"n":"第四十三条","txt":"负有冶金有色安全生产监管职责的部门应当为进入有限空间等特定作业场所进行监督检查的人员，配备必需的个体防护用品和监测检查仪器。"},{"i":44,"n":"第四十四条","txt":"负有冶金有色安全生产监管职责的部门应当加强对本行政区域内企业应急预案的备案管理，并将重大事故应急救援纳入地方人民政府应急救援体系。"},{"i":45,"n":"第四十五条","txt":"监督检查人员在对企业进行监督检查时，滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"企业违反本规定第二十四条至第三十七条的规定，构成生产安全事故隐患的，责令立即消除或者限期消除事故隐患；企业拒不执行的，责令停产停业整顿，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"企业违反本规定的其他违法行为，分别依照《中华人民共和国安全生产法》《中华人民共和国职业病防治法》等的规定追究法律责任。"},{"i":48,"n":"第四十八条","txt":"本规定自2018年3月1日起施行。国家安全生产监督管理总局2009年9月8日公布的《冶金企业安全生产监督管理规定》（国家安全生产监督管理总局令第26号）同时废止。"}],"huaxuepinwuliweixianxingjiandingyufenleiguanlibanfc54707":[{"i":1,"n":"第一条","txt":"为了规范化学品物理危险性鉴定与分类工作，根据《危险化学品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"对危险特性尚未确定的化学品进行物理危险性鉴定与分类，以及安全生产监督管理部门对鉴定与分类工作实施监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称化学品，是指各类单质、化合物及其混合物。 化学品物理危险性鉴定，是指依据有关国家标准或者行业标准进行测试、判定，确定化学品的燃烧、爆炸、腐蚀、助燃、自反应和遇水反应等危险特性。 化学品物理危险性分类，是指依据有关国家标准或者行业标准，对化学品物理危险性鉴定结果或者相关数据资料进行评估，确定化学品的物理危险性类别。"},{"i":4,"n":"第四条","txt":"下列化学品应当进行物理危险性鉴定与分类： （一）含有一种及以上列入《危险化学品目录》的组分，但整体物理危险性尚未确定的化学品； （二）未列入《危险化学品目录》，且物理危险性尚未确定的化学品； （三）以科学研究或者产品开发为目的，年产量或者使用量超过1吨，且物理危险性尚未确定的化学品。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局负责指导和监督管理全国化学品物理危险性鉴定与分类工作，公告化学品物理危险性鉴定机构（以下简称鉴定机构）名单以及免予物理危险性鉴定与分类的化学品目录，设立化学品物理危险性鉴定与分类技术委员会（以下简称技术委员会）。 县级以上地方各级人民政府安全生产监督管理部门负责监督和检查本行政区域内化学品物理危险性鉴定与分类工作。"},{"i":6,"n":"第六条","txt":"技术委员会负责对有异议的鉴定或者分类结果进行仲裁，公布化学品物理危险性的鉴定情况。 国家安全生产监督管理总局化学品登记中心（以下简称登记中心）负责化学品物理危险性分类结果的评估与审核，建立国家化学品物理危险性鉴定与分类信息管理系统，为化学品物理危险性鉴定与分类工作提供技术支持，承担技术委员会的日常工作。"},{"i":7,"n":"第七条","txt":"鉴定机构应当依照有关法律法规和国家标准或者行业标准的规定，科学、公正、诚信地开展鉴定工作，保证鉴定结果真实、准确、客观，并对鉴定结果负责。"},{"i":8,"n":"第八条","txt":"化学品生产、进口单位（以下统称化学品单位）应当对本单位生产或者进口的化学品进行普查和物理危险性辨识，对其中符合本办法第四条规定的化学品向鉴定机构申请鉴定。 化学品单位在办理化学品物理危险性鉴定过程中，不得隐瞒化学品的危险性成分、含量等相关信息或者提供虚假材料。"},{"i":9,"n":"第九条","txt":"化学品物理危险性鉴定按照下列程序办理： （一）申请化学品物理危险性鉴定的化学品单位向鉴定机构提交化学品物理危险性鉴定申请表以及相关文件资料，提供鉴定所需要的样品，并对样品的真实性负责； （二）鉴定机构收到鉴定申请后，按照有关国家标准或者行业标准进行测试、判定。除与爆炸物、自反应物质、有机过氧化物相关的物理危险性外，对其他物理危险性应当在20个工作日内出具鉴定报告，特殊情况下由双方协商确定。 送检样品应当至少保存180日，有关档案材料应当至少保存5年。"},{"i":10,"n":"第十条","txt":"化学品物理危险性鉴定应当包括下列内容： （一）与爆炸物、易燃气体、气溶胶、氧化性气体、加压气体、易燃液体、易燃固体、自反应物质、自燃液体、自燃固体、自热物质、遇水放出易燃气体的物质、氧化性液体、氧化性固体、有机过氧化物、金属腐蚀物等相关的物理危险性； （二）与化学品危险性分类相关的蒸气压、自燃温度等理化特性，以及化学稳定性和反应性等。"},{"i":11,"n":"第十一条","txt":"化学品物理危险性鉴定报告应当包括下列内容： （一）化学品名称； （二）申请鉴定单位名称； （三）鉴定项目以及所用标准、方法； （四）仪器设备信息； （五）鉴定结果； （六）有关国家标准或者行业标准中规定的其他内容。"},{"i":12,"n":"第十二条","txt":"申请化学品物理危险性鉴定的化学品单位对鉴定结果有异议的，可以在收到鉴定报告之日起15个工作日内向原鉴定机构申请重新鉴定，或者向技术委员会申请仲裁。技术委员会应当在收到申请之日起20个工作日内作出仲裁决定。"},{"i":13,"n":"第十三条","txt":"化学品单位应当根据鉴定报告以及其他物理危险性数据资料，编制化学品物理危险性分类报告。 化学品物理危险性分类报告应当包括下列内容： （一）化学品名称； （二）重要成分信息； （三）物理危险性鉴定报告或者其他有关数据及其来源； （四）化学品物理危险性分类结果。"},{"i":14,"n":"第十四条","txt":"化学品单位应当向登记中心提交化学品物理危险性分类报告。登记中心应当对分类报告进行综合性评估，并在30个工作日内向化学品单位出具审核意见。"},{"i":15,"n":"第十五条","txt":"化学品单位对化学品物理危险性分类的审核意见有异议的，可以在收到审核意见之日起15个工作日内向技术委员会申请仲裁。技术委员会应当在收到申请之日起20个工作日内作出仲裁决定。"},{"i":16,"n":"第十六条","txt":"化学品单位应当建立化学品物理危险性鉴定与分类管理档案，内容应当包括： （一）已知物理危险性的化学品的危险特性等信息； （二）已经鉴定与分类化学品的物理危险性鉴定报告、分类报告和审核意见等信息； （三）未进行鉴定与分类化学品的名称、数量等信息。"},{"i":17,"n":"第十七条","txt":"化学品单位对确定为危险化学品的化学品以及国家安全生产监督管理总局公告的免予物理危险性鉴定与分类的危险化学品，应当编制化学品安全技术说明书和安全标签，根据《危险化学品登记管理办法》办理危险化学品登记，按照有关危险化学品的法律、法规和标准的要求，加强安全管理。"},{"i":18,"n":"第十八条","txt":"鉴定机构应当于每年1月31日前向国家安全生产监督管理总局上报上一年度鉴定的化学品品名和工作总结。"},{"i":19,"n":"第十九条","txt":"化学品单位有下列情形之一的，由安全生产监督管理部门责令限期改正，可以处1万元以下的罚款；拒不改正的，处1万元以上3万元以下的罚款： （一）未按照本办法规定对化学品进行物理危险性鉴定或者分类的； （二）未按照本办法规定建立化学品物理危险性鉴定与分类管理档案的； （三）在办理化学品物理危险性的鉴定过程中，隐瞒化学品的危险性成分、含量等相关信息或者提供虚假材料的。"},{"i":20,"n":"第二十条","txt":"鉴定机构在物理危险性鉴定过程中有下列行为之一的，处1万元以上3万元以下的罚款；情节严重的，由国家安全生产监督管理总局从鉴定机构名单中除名并公告： （一）伪造、篡改数据或者有其他弄虚作假行为的； （二）未通过安全生产监督管理部门的监督检查，仍从事鉴定工作的； （三）泄露化学品单位商业秘密的。"},{"i":21,"n":"第二十一条","txt":"对于用途相似、组分接近、物理危险性无显著差异的化学品，化学品单位可以向鉴定机构申请系列化学品鉴定。 多个化学品单位可以对同一化学品联合申请鉴定。"},{"i":22,"n":"第二十二条","txt":"对已经列入《危险化学品目录》的化学品，发现其有新的物理危险性的，化学品单位应当依照本办法进行物理危险性鉴定与分类。"},{"i":23,"n":"第二十三条","txt":"本办法自2013年9月1日起施行。"}],"weixianhuaxuepinanquanshiyongxukezhengshishibanfa":[{"i":1,"n":"第一条","txt":"为了严格使用危险化学品从事生产的化工企业安全生产条件，规范危险化学品安全使用许可证的颁发和管理工作，根据《危险化学品安全管理条例》和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于列入危险化学品安全使用许可适用行业目录、使用危险化学品从事生产并且达到危险化学品使用量的数量标准的化工企业（危险化学品生产企业除外，以下简称企业）。 使用危险化学品作为燃料的企业不适用本办法。"},{"i":3,"n":"第三条","txt":"企业应当依照本办法的规定取得危险化学品安全使用许可证（以下简称安全使用许可证）。"},{"i":4,"n":"第四条","txt":"安全使用许可证的颁发管理工作实行企业申请、市级发证、属地监管的原则。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局负责指导、监督全国安全使用许可证的颁发管理工作。 省、自治区、直辖市人民政府安全生产监督管理部门（以下简称省级安全生产监督管理部门）负责指导、监督本行政区域内安全使用许可证的颁发管理工作。 设区的市级人民政府安全生产监督管理部门（以下简称发证机关）负责本行政区域内安全使用许可证的审批、颁发和管理，不得再委托其他单位、组织或者个人实施。"},{"i":6,"n":"第六条","txt":"企业与重要场所、设施、区域的距离和总体布局应当符合下列要求，并确保安全： （一）储存危险化学品数量构成重大危险源的储存设施，与《危险化学品安全管理条例》第十九条第一款规定的八类场所、设施、区域的距离符合国家有关法律、法规、规章和国家标准或者行业标准的规定； （二）总体布局符合《工业企业总平面设计规范》（GB50187）、《化工企业总图运输设计规范》（GB50489）、《建筑设计防火规范》（GB50016）等相关标准的要求；石油化工企业还应当符合《石油化工企业设计防火规范》（GB50160）的要求； （三）新建企业符合国家产业政策、当地县级以上（含县级）人民政府的规划和布局。"},{"i":7,"n":"第七条","txt":"企业的厂房、作业场所、储存设施和安全设施、设备、工艺应当符合下列要求： （一）新建、改建、扩建使用危险化学品的化工建设项目（以下统称建设项目）由具备国家规定资质的设计单位设计和施工单位建设；其中，涉及国家安全生产监督管理总局公布的重点监管危险化工工艺、重点监管危险化学品的装置，由具备石油化工医药行业相应资质的设计单位设计； （二）不得采用国家明令淘汰、禁止使用和危及安全生产的工艺、设备；新开发的使用危险化学品从事化工生产的工艺（以下简称化工工艺），在小试、中试、工业化试验的基础上逐步放大到工业化生产；国内首次使用的化工工艺，经过省级人民政府有关部门组织的安全可靠性论证； （三）涉及国家安全生产监督管理总局公布的重点监管危险化工工艺、重点监管危险化学品的装置装设自动化控制系统；涉及国家安全生产监督管理总局公布的重点监管危险化工工艺的大型化工装置装设紧急停车系统；涉及易燃易爆、有毒有害气体"},{"i":8,"n":"第八条","txt":"企业应当依法设置安全生产管理机构，按照国家规定配备专职安全生产管理人员。配备的专职安全生产管理人员必须能够满足安全生产的需要。"},{"i":9,"n":"第九条","txt":"企业主要负责人、分管安全负责人和安全生产管理人员必须具备与其从事生产经营活动相适应的安全知识和管理能力，参加安全资格培训，并经考核合格，取得安全合格证书。 特种作业人员应当依照《特种作业人员安全技术培训考核管理规定》，经专门的安全技术培训并考核合格，取得特种作业操作证书。 本条第一款、第二款规定以外的其他从业人员应当按照国家有关规定，经安全教育培训合格。"},{"i":10,"n":"第十条","txt":"企业应当建立全员安全生产责任制，保证每位从业人员的安全生产责任与职务、岗位相匹配。"},{"i":11,"n":"第十一条","txt":"企业根据化工工艺、装置、设施等实际情况，至少应当制定、完善下列主要安全生产规章制度： （一）安全生产例会等安全生产会议制度； （二）安全投入保障制度； （三）安全生产奖惩制度； （四）安全培训教育制度； （五）领导干部轮流现场带班制度； （六）特种作业人员管理制度； （七）安全检查和隐患排查治理制度； （八）重大危险源的评估和安全管理制度； （九）变更管理制度； （十）应急管理制度； （十一）生产安全事故或者重大事件管理制度； （十二）防火、防爆、防中毒、防泄漏管理制度； （十三）工艺、设备、电气仪表、公用工程安全管理制度； （十四）动火、进入受限空间、吊装、高处、盲板抽堵、临时用电、动土、断路、设备检维修等作业安全管理制度； （十五）危险化学品安全管理制度； （十六）职业健康相关管理制度； （十七）劳动防护用品使用维护管理制度； （十八）承包商管理制度； （十九）安全管理制度及操作规"},{"i":12,"n":"第十二条","txt":"企业应当根据工艺、技术、设备特点和原辅料的危险性等情况编制岗位安全操作规程。"},{"i":13,"n":"第十三条","txt":"企业应当依法委托具备国家规定资质条件的安全评价机构进行安全评价，并按照安全评价报告的意见对存在的安全生产问题进行整改。"},{"i":14,"n":"第十四条","txt":"企业应当有相应的职业病危害防护设施，并为从业人员配备符合国家标准或者行业标准的劳动防护用品。"},{"i":15,"n":"第十五条","txt":"企业应当依据《危险化学品重大危险源辨识》（GB18218），对本企业的生产、储存和使用装置、设施或者场所进行重大危险源辨识。 对于已经确定为重大危险源的，应当按照《危险化学品重大危险源监督管理暂行规定》进行安全管理。"},{"i":16,"n":"第十六条","txt":"企业应当符合下列应急管理要求： （一）按照国家有关规定编制危险化学品事故应急预案，并报送有关部门备案； （二）建立应急救援组织，明确应急救援人员，配备必要的应急救援器材、设备设施，并按照规定定期进行应急预案演练。 储存和使用氯气、氨气等对皮肤有强烈刺激的吸入性有毒有害气体的企业，除符合本条第一款的规定外，还应当配备至少两套以上全封闭防化服；构成重大危险源的，还应当设立气体防护站（组）。"},{"i":17,"n":"第十七条","txt":"企业除符合本章规定的安全使用条件外，还应当符合有关法律、行政法规和国家标准或者行业标准规定的其他安全使用条件。"},{"i":18,"n":"第十八条","txt":"企业向发证机关申请安全使用许可证时，应当提交下列文件、资料，并对其内容的真实性负责： （一）申请安全使用许可证的文件及申请书； （二）新建企业的选址布局符合国家产业政策、当地县级以上人民政府的规划和布局的证明材料复制件； （三）安全生产责任制文件，安全生产规章制度、岗位安全操作规程清单； （四）设置安全生产管理机构，配备专职安全生产管理人员的文件复制件； （五）主要负责人、分管安全负责人、安全生产管理人员安全合格证和特种作业人员操作证复制件； （六）危险化学品事故应急救援预案的备案证明文件； （七）由供货单位提供的所使用危险化学品的安全技术说明书和安全标签； （八）工商营业执照副本或者工商核准文件复制件； （九）安全评价报告及其整改结果的报告； （十）新建企业的建设项目安全设施竣工验收报告； （十一）应急救援组织、应急救援人员，以及应急救援器材、设备设施清单。 有危险化学品重大危险源的"},{"i":19,"n":"第十九条","txt":"新建企业安全使用许可证的申请，应当在建设项目安全设施竣工验收通过之日起10个工作日内提出。"},{"i":20,"n":"第二十条","txt":"发证机关收到企业申请文件、资料后，应当按照下列情况分别作出处理： （一）申请事项依法不需要取得安全使用许可证的，当场告知企业不予受理； （二）申请材料存在可以当场更正的错误的，允许企业当场更正； （三）申请材料不齐全或者不符合法定形式的，当场或者在5个工作日内一次告知企业需要补正的全部内容，并出具补正告知书；逾期不告知的，自收到申请材料之日起即为受理； （四）企业申请材料齐全、符合法定形式，或者按照发证机关要求提交全部补正申请材料的，立即受理其申请。 发证机关受理或者不予受理行政许可申请，应当出具加盖本机关专用印章和注明日期的书面凭证。"},{"i":21,"n":"第二十一条","txt":"安全使用许可证申请受理后，发证机关应当组织人员对企业提交的申请文件、资料进行审查。对企业提交的文件、资料内容存在疑问，需要到现场核查的，应当指派工作人员对有关内容进行现场核查。工作人员应当如实提出书面核查意见。"},{"i":22,"n":"第二十二条","txt":"发证机关应当在受理之日起45日内作出是否准予许可的决定。发证机关现场核查和企业整改有关问题所需时间不计算在本条规定的期限内。"},{"i":23,"n":"第二十三条","txt":"发证机关作出准予许可的决定的，应当自决定之日起10个工作日内颁发安全使用许可证。 发证机关作出不予许可的决定的，应当在10个工作日内书面告知企业并说明理由。"},{"i":24,"n":"第二十四条","txt":"企业在安全使用许可证有效期内变更主要负责人、企业名称或者注册地址的，应当自工商营业执照变更之日起10个工作日内提出变更申请，并提交下列文件、资料： （一）变更申请书； （二）变更后的工商营业执照副本复制件； （三）变更主要负责人的，还应当提供主要负责人经安全生产监督管理部门考核合格后颁发的安全合格证复制件； （四）变更注册地址的，还应当提供相关证明材料。 对已经受理的变更申请，发证机关对企业提交的文件、资料审查无误后，方可办理安全使用许可证变更手续。 企业在安全使用许可证有效期内变更隶属关系的，应当在隶属关系变更之日起10日内向发证机关提交证明材料。"},{"i":25,"n":"第二十五条","txt":"企业在安全使用许可证有效期内，有下列情形之一的，发证机关按照本办法第二十条、第二十一条、第二十二条、第二十三条的规定办理变更手续： （一）增加使用的危险化学品品种，且达到危险化学品使用量的数量标准规定的； （二）涉及危险化学品安全使用许可范围的新建、改建、扩建建设项目的； （三）改变工艺技术对企业的安全生产条件产生重大影响的。 有本条第一款第一项规定情形的企业，应当在增加前提出变更申请。 有本条第一款第二项规定情形的企业，应当在建设项目安全设施竣工验收合格之日起10个工作日内向原发证机关提出变更申请，并提交建设项目安全设施竣工验收报告等相关文件、资料。 有本条第一款第一项、第三项规定情形的企业，应当进行专项安全验收评价，并对安全评价报告中提出的问题进行整改；在整改完成后，向原发证机关提出变更申请并提交安全验收评价报告。"},{"i":26,"n":"第二十六条","txt":"安全使用许可证有效期为3年。企业安全使用许可证有效期届满后需要继续使用危险化学品从事生产、且达到危险化学品使用量的数量标准规定的，应当在安全使用许可证有效期届满前3个月提出延期申请，并提交本办法第十八条规定的文件、资料。 发证机关按照本办法第二十条、第二十一条、第二十二条、第二十三条的规定进行审查，并作出是否准予延期的决定。"},{"i":27,"n":"第二十七条","txt":"企业取得安全使用许可证后，符合下列条件的，其安全使用许可证届满办理延期手续时，经原发证机关同意，可以不提交第十八条第一款第二项、第五项、第九项和第十八条第二款规定的文件、资料，直接办理延期手续： （一）严格遵守有关法律、法规和本办法的； （二）取得安全使用许可证后，加强日常安全管理，未降低安全使用条件，并达到安全生产标准化等级二级以上的； （三）未发生造成人员死亡的生产安全责任事故的。 企业符合本条第一款第二项、第三项规定条件的，应当在延期申请书中予以说明，并出具二级以上安全生产标准化证书复印件。"},{"i":28,"n":"第二十八条","txt":"安全使用许可证分为正本、副本，正本为悬挂式，副本为折页式，正、副本具有同等法律效力。 发证机关应当分别在安全使用许可证正、副本上注明编号、企业名称、主要负责人、注册地址、经济类型、许可范围、有效期、发证机关、发证日期等内容。其中，“许可范围”正本上注明“危险化学品使用”，副本上注明使用危险化学品从事生产的地址和对应的具体品种、年使用量。"},{"i":29,"n":"第二十九条","txt":"企业不得伪造、变造安全使用许可证，或者出租、出借、转让其取得的安全使用许可证，或者使用伪造、变造的安全使用许可证。"},{"i":30,"n":"第三十条","txt":"发证机关应当坚持公开、公平、公正的原则，依照本办法和有关行政许可的法律法规规定，颁发安全使用许可证。 发证机关工作人员在安全使用许可证颁发及其监督管理工作中，不得索取或者接受企业的财物，不得谋取其他非法利益。"},{"i":31,"n":"第三十一条","txt":"发证机关应当加强对安全使用许可证的监督管理，建立、健全安全使用许可证档案管理制度。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，发证机关应当撤销已经颁发的安全使用许可证： （一）滥用职权、玩忽职守颁发安全使用许可证的； （二）超越职权颁发安全使用许可证的； （三）违反本办法规定的程序颁发安全使用许可证的； （四）对不具备申请资格或者不符合法定条件的企业颁发安全使用许可证的； （五）以欺骗、贿赂等不正当手段取得安全使用许可证的。"},{"i":33,"n":"第三十三条","txt":"企业取得安全使用许可证后有下列情形之一的，发证机关应当注销其安全使用许可证： （一）安全使用许可证有效期届满未被批准延期的； （二）终止使用危险化学品从事生产的； （三）继续使用危险化学品从事生产，但使用量降低后未达到危险化学品使用量的数量标准规定的； （四）安全使用许可证被依法撤销的； （五）安全使用许可证被依法吊销的。 安全使用许可证注销后，发证机关应当在当地主要新闻媒体或者本机关网站上予以公告，并向省级和企业所在地县级安全生产监督管理部门通报。"},{"i":34,"n":"第三十四条","txt":"发证机关应当将其颁发安全使用许可证的情况及时向同级环境保护主管部门和公安机关通报。"},{"i":35,"n":"第三十五条","txt":"发证机关应当于每年1月10日前，将本行政区域内上年度安全使用许可证的颁发和管理情况报省级安全生产监督管理部门，并定期向社会公布企业取得安全使用许可证的情况，接受社会监督。 省级安全生产监督管理部门应当于每年1月15日前，将本行政区域内上年度安全使用许可证的颁发和管理情况报国家安全生产监督管理总局。"},{"i":36,"n":"第三十六条","txt":"发证机关工作人员在对危险化学品使用许可证的颁发管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":37,"n":"第三十七条","txt":"企业未取得安全使用许可证，擅自使用危险化学品从事生产，且达到危险化学品使用量的数量标准规定的，责令立即停止违法行为并限期改正，处10万元以上20万元以下的罚款；逾期不改正的，责令停产整顿。 企业在安全使用许可证有效期届满后未办理延期手续，仍然使用危险化学品从事生产，且达到危险化学品使用量的数量标准规定的，依照前款规定给予处罚。"},{"i":38,"n":"第三十八条","txt":"企业伪造、变造或者出租、出借、转让安全使用许可证，或者使用伪造、变造的安全使用许可证的，处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"企业在安全使用许可证有效期内主要负责人、企业名称、注册地址、隶属关系发生变更，未按照本办法第二十四条规定的时限提出安全使用许可证变更申请或者将隶属关系变更证明材料报发证机关的，责令限期办理变更手续，处1万元以上3万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"企业在安全使用许可证有效期内有下列情形之一，未按照本办法第二十五条的规定提出变更申请，继续从事生产的，责令限期改正，处1万元以上3万元以下的罚款： （一）增加使用的危险化学品品种，且达到危险化学品使用量的数量标准规定的； （二）涉及危险化学品安全使用许可范围的新建、改建、扩建建设项目，其安全设施已经竣工验收合格的； （三）改变工艺技术对企业的安全生产条件产生重大影响的。"},{"i":41,"n":"第四十一条","txt":"发现企业隐瞒有关情况或者提供虚假文件、资料申请安全使用许可证的，发证机关不予受理或者不予颁发安全使用许可证，并给予警告，该企业在1年内不得再次申请安全使用许可证。 企业以欺骗、贿赂等不正当手段取得安全使用许可证的，自发证机关撤销其安全使用许可证之日起3年内，该企业不得再次申请安全使用许可证。"},{"i":42,"n":"第四十二条","txt":"安全评价机构有下列情形之一的，给予警告，并处1万元以下的罚款；情节严重的，暂停资质6个月，并处1万元以上3万元以下的罚款；对相关责任人依法给予处理： （一）从业人员不到现场开展安全评价活动的； （二）安全评价报告与实际情况不符，或者安全评价报告存在重大疏漏，但尚未造成重大损失的； （三）未按照有关法律、法规、规章和国家标准或者行业标准的规定从事安全评价活动的。"},{"i":43,"n":"第四十三条","txt":"承担安全评价的机构出具虚假证明的，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与企业承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构，依法吊销其相应资质。"},{"i":44,"n":"第四十四条","txt":"本办法规定的行政处罚，由安全生产监督管理部门决定；但本办法第三十八条规定的行政处罚，由发证机关决定；第四十二条、第四十三条规定的行政处罚，依照《安全评价机构管理规定》执行。"},{"i":45,"n":"第四十五条","txt":"本办法下列用语的含义： （一）危险化学品安全使用许可适用行业目录，是指国家安全生产监督管理总局根据《危险化学品安全管理条例》和有关国家标准、行业标准公布的需要取得危险化学品安全使用许可的化工企业类别； （二）危险化学品使用量的数量标准，由国家安全生产监督管理总局会同国务院公安部门、农业主管部门根据《危险化学品安全管理条例》公布； （三）本办法所称使用量，是指企业使用危险化学品的年设计使用量和实际使用量的较大值； （四）本办法所称大型化工装置，是指按照原建设部《工程设计资质标准》（建市〔2007〕86号）中的《化工石化医药行业建设项目设计规模划分表》确定的大型项目的化工生产装置。"},{"i":46,"n":"第四十六条","txt":"危险化学品安全使用许可的文书、危险化学品安全使用许可证的样式、内容和编号办法，由国家安全生产监督管理总局另行规定。"},{"i":47,"n":"第四十七条","txt":"省级安全生产监督管理部门可以根据当地实际情况制定安全使用许可证管理的细则，并报国家安全生产监督管理总局备案。"},{"i":48,"n":"第四十八条","txt":"本办法施行前已经进行生产的企业，应当自本办法施行之日起18个月内，依照本办法的规定向发证机关申请办理安全使用许可证；逾期不申请办理安全使用许可证，或者经审查不符合本办法规定的安全使用条件，未取得安全使用许可证，继续进行生产的，依照本办法第三十七条的规定处罚。"},{"i":49,"n":"第四十九条","txt":"本办法自2013年5月1日起施行。"}],"weixianhuaxuepinjianshexiangmuanquanjianduguanliba170002":[{"i":1,"n":"第一条","txt":"为了加强危险化学品建设项目安全监督管理，规范危险化学品建设项目安全审查，根据《中华人民共和国安全生产法》和《危险化学品安全管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内新建、改建、扩建危险化学品生产、储存的建设项目以及伴有危险化学品产生的化工建设项目（包括危险化学品长输管道建设项目，以下统称建设项目），其安全管理及其监督管理，适用本办法。 危险化学品的勘探、开采及其辅助的储存，原油和天然气勘探、开采及其辅助的储存、海上输送，城镇燃气的输送及储存等建设项目，不适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称建设项目安全审查，是指建设项目安全条件审查、安全设施的设计审查。建设项目的安全审查由建设单位申请，安全生产监督管理部门根据本办法分级负责实施。 建设项目安全设施竣工验收由建设单位负责依法组织实施。 建设项目未经安全审查和安全设施竣工验收的，不得开工建设或者投入生产（使用）。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局指导、监督全国建设项目安全审查和建设项目安全设施竣工验收的实施工作，并负责实施下列建设项目的安全审查： （一）国务院审批（核准、备案）的； （二）跨省、自治区、直辖市的。 省、自治区、直辖市人民政府安全生产监督管理部门（以下简称省级安全生产监督管理部门）指导、监督本行政区域内建设项目安全审查和建设项目安全设施竣工验收的监督管理工作，确定并公布本部门和本行政区域内由设区的市级人民政府安全生产监督管理部门（以下简称市级安全生产监督管理部门）实施的前款规定以外的建设项目范围，并报国家安全生产监督管理总局备案。"},{"i":5,"n":"第五条","txt":"建设项目有下列情形之一的，应当由省级安全生产监督管理部门负责安全审查： （一）国务院投资主管部门审批（核准、备案）的； （二）生产剧毒化学品的； （三）省级安全生产监督管理部门确定的本办法第四条第一款规定以外的其他建设项目。"},{"i":6,"n":"第六条","txt":"负责实施建设项目安全审查的安全生产监督管理部门根据工作需要，可以将其负责实施的建设项目安全审查工作，委托下一级安全生产监督管理部门实施。委托实施安全审查的，审查结果由委托的安全生产监督管理部门负责。跨省、自治区、直辖市的建设项目和生产剧毒化学品的建设项目，不得委托实施安全审查。 建设项目有下列情形之一的，不得委托县级人民政府安全生产监督管理部门实施安全审查： （一）涉及国家安全生产监督管理总局公布的重点监管危险化工工艺的； （二）涉及国家安全生产监督管理总局公布的重点监管危险化学品中的有毒气体、液化气体、易燃液体、爆炸品，且构成重大危险源的。 接受委托的安全生产监督管理部门不得将其受托的建设项目安全审查工作再委托其他单位实施。"},{"i":7,"n":"第七条","txt":"建设项目的设计、施工、监理单位和安全评价机构应当具备相应的资质，并对其工作成果负责。 涉及重点监管危险化工工艺、重点监管危险化学品或者危险化学品重大危险源的建设项目，应当由具有石油化工医药行业相应资质的设计单位设计。"},{"i":8,"n":"第八条","txt":"建设单位应当在建设项目的可行性研究阶段，委托具备相应资质的安全评价机构对建设项目进行安全评价。 安全评价机构应当根据有关安全生产法律、法规、规章和国家标准、行业标准，对建设项目进行安全评价，出具建设项目安全评价报告。安全评价报告应当符合《危险化学品建设项目安全评价细则》的要求。"},{"i":9,"n":"第九条","txt":"建设项目有下列情形之一的，应当由甲级安全评价机构进行安全评价： （一）国务院及其投资主管部门审批（核准、备案）的； （二）生产剧毒化学品的； （三）跨省、自治区、直辖市的； （四）法律、法规、规章另有规定的。"},{"i":10,"n":"第十条","txt":"建设单位应当在建设项目开始初步设计前，向与本办法第四条、第五条规定相应的安全生产监督管理部门申请建设项目安全条件审查，提交下列文件、资料，并对其真实性负责： （一）建设项目安全条件审查申请书及文件； （二）建设项目安全评价报告； （三）建设项目批准、核准或者备案文件和规划相关文件（复制件）； （四）工商行政管理部门颁发的企业营业执照或者企业名称预先核准通知书（复制件）。"},{"i":11,"n":"第十一条","txt":"建设单位申请安全条件审查的文件、资料齐全，符合法定形式的，安全生产监督管理部门应当当场予以受理，并书面告知建设单位。 建设单位申请安全条件审查的文件、资料不齐全或者不符合法定形式的，安全生产监督管理部门应当自收到申请文件、资料之日起五个工作日内一次性书面告知建设单位需要补正的全部内容；逾期不告知的，收到申请文件、资料之日起即为受理。"},{"i":12,"n":"第十二条","txt":"对已经受理的建设项目安全条件审查申请，安全生产监督管理部门应当指派有关人员或者组织专家对申请文件、资料进行审查，并自受理申请之日起四十五日内向建设单位出具建设项目安全条件审查意见书。建设项目安全条件审查意见书的有效期为两年。 根据法定条件和程序，需要对申请文件、资料的实质内容进行核实的，安全生产监督管理部门应当指派两名以上工作人员对建设项目进行现场核查。 建设单位整改现场核查发现的有关问题和修改申请文件、资料所需时间不计算在本条规定的期限内。"},{"i":13,"n":"第十三条","txt":"建设项目有下列情形之一的，安全条件审查不予通过： （一）安全评价报告存在重大缺陷、漏项的，包括建设项目主要危险、有害因素辨识和评价不全或者不准确的； （二）建设项目与周边场所、设施的距离或者拟建场址自然条件不符合有关安全生产法律、法规、规章和国家标准、行业标准的规定的； （三）主要技术、工艺未确定，或者不符合有关安全生产法律、法规、规章和国家标准、行业标准的规定的； （四）国内首次使用的化工工艺，未经省级人民政府有关部门组织的安全可靠性论证的； （五）对安全设施设计提出的对策与建议不符合法律、法规、规章和国家标准、行业标准的规定的； （六）未委托具备相应资质的安全评价机构进行安全评价的； （七）隐瞒有关情况或者提供虚假文件、资料的。 建设项目未通过安全条件审查的，建设单位经过整改后可以重新申请建设项目安全条件审查。"},{"i":14,"n":"第十四条","txt":"已经通过安全条件审查的建设项目有下列情形之一的，建设单位应当重新进行安全评价，并申请审查： （一）建设项目周边条件发生重大变化的； （二）变更建设地址的； （三）主要技术、工艺路线、产品方案或者装置规模发生重大变化的； （四）建设项目在安全条件审查意见书有效期内未开工建设，期限届满后需要开工建设的。"},{"i":15,"n":"第十五条","txt":"设计单位应当根据有关安全生产的法律、法规、规章和国家标准、行业标准以及建设项目安全条件审查意见书，按照《化工建设项目安全设计管理导则》（AQ/T3033），对建设项目安全设施进行设计，并编制建设项目安全设施设计专篇。建设项目安全设施设计专篇应当符合《危险化学品建设项目安全设施设计专篇编制导则》的要求。"},{"i":16,"n":"第十六条","txt":"建设单位应当在建设项目初步设计完成后、详细设计开始前，向出具建设项目安全条件审查意见书的安全生产监督管理部门申请建设项目安全设施设计审查，提交下列文件、资料，并对其真实性负责： （一）建设项目安全设施设计审查申请书及文件； （二）设计单位的设计资质证明文件（复制件）； （三）建设项目安全设施设计专篇。"},{"i":17,"n":"第十七条","txt":"建设单位申请安全设施设计审查的文件、资料齐全，符合法定形式的，安全生产监督管理部门应当当场予以受理；未经安全条件审查或者审查未通过的，不予受理。受理或者不予受理的情况，安全生产监督管理部门应当书面告知建设单位。 安全设施设计审查申请文件、资料不齐全或者不符合要求的，安全生产监督管理部门应当自收到申请文件、资料之日起五个工作日内一次性书面告知建设单位需要补正的全部内容；逾期不告知的，收到申请文件、资料之日起即为受理。"},{"i":18,"n":"第十八条","txt":"对已经受理的建设项目安全设施设计审查申请，安全生产监督管理部门应当指派有关人员或者组织专家对申请文件、资料进行审查，并在受理申请之日起二十个工作日内作出同意或者不同意建设项目安全设施设计专篇的决定，向建设单位出具建设项目安全设施设计的审查意见书；二十个工作日内不能出具审查意见的，经本部门负责人批准，可以延长十个工作日，并应当将延长的期限和理由告知建设单位。 根据法定条件和程序，需要对申请文件、资料的实质内容进行核实的，安全生产监督管理部门应当指派两名以上工作人员进行现场核查。 建设单位整改现场核查发现的有关问题和修改申请文件、资料所需时间不计算在本条规定的期限内。"},{"i":19,"n":"第十九条","txt":"建设项目安全设施设计有下列情形之一的，审查不予通过： （一）设计单位资质不符合相关规定的； （二）未按照有关安全生产的法律、法规、规章和国家标准、行业标准的规定进行设计的； （三）对未采纳的建设项目安全评价报告中的安全对策和建议，未作充分论证说明的； （四）隐瞒有关情况或者提供虚假文件、资料的。 建设项目安全设施设计审查未通过的，建设单位经过整改后可以重新申请建设项目安全设施设计的审查。"},{"i":20,"n":"第二十条","txt":"已经审查通过的建设项目安全设施设计有下列情形之一的，建设单位应当向原审查部门申请建设项目安全设施变更设计的审查： （一）改变安全设施设计且可能降低安全性能的； （二）在施工期间重新设计的。"},{"i":21,"n":"第二十一条","txt":"建设项目安全设施施工完成后，建设单位应当按照有关安全生产法律、法规、规章和国家标准、行业标准的规定，对建设项目安全设施进行检验、检测，保证建设项目安全设施满足危险化学品生产、储存的安全要求，并处于正常适用状态。"},{"i":22,"n":"第二十二条","txt":"建设单位应当组织建设项目的设计、施工、监理等有关单位和专家，研究提出建设项目试生产（使用）（以下简称试生产〈使用〉）可能出现的安全问题及对策，并按照有关安全生产法律、法规、规章和国家标准、行业标准的规定，制定周密的试生产（使用）方案。试生产（使用）方案应当包括下列有关安全生产的内容： （一）建设项目设备及管道试压、吹扫、气密、单机试车、仪表调校、联动试车等生产准备的完成情况； （二）投料试车方案； （三）试生产（使用）过程中可能出现的安全问题、对策及应急预案； （四）建设项目周边环境与建设项目安全试生产（使用）相互影响的确认情况； （五）危险化学品重大危险源监控措施的落实情况； （六）人力资源配置情况； （七）试生产（使用）起止日期。 建设项目试生产期限应当不少于30日，不超过1年。"},{"i":23,"n":"第二十三条","txt":"建设单位在采取有效安全生产措施后，方可将建设项目安全设施与生产、储存、使用的主体装置、设施同时进行试生产（使用）。 试生产（使用）前，建设单位应当组织专家对试生产（使用）方案进行审查。 试生产（使用）时，建设单位应当组织专家对试生产（使用）条件进行确认，对试生产（使用）过程进行技术指导。"},{"i":24,"n":"第二十四条","txt":"建设项目安全设施施工完成后，施工单位应当编制建设项目安全设施施工情况报告。建设项目安全设施施工情况报告应当包括下列内容： （一）施工单位的基本情况，包括施工单位以往所承担的建设项目施工情况； （二）施工单位的资质情况（提供相关资质证明材料复印件）； （三）施工依据和执行的有关法律、法规、规章和国家标准、行业标准； （四）施工质量控制情况； （五）施工变更情况，包括建设项目在施工和试生产期间有关安全生产的设施改动情况。"},{"i":25,"n":"第二十五条","txt":"建设项目试生产期间，建设单位应当按照本办法的规定委托有相应资质的安全评价机构对建设项目及其安全设施试生产（使用）情况进行安全验收评价，且不得委托在可行性研究阶段进行安全评价的同一安全评价机构。 安全评价机构应当根据有关安全生产的法律、法规、规章和国家标准、行业标准进行评价。建设项目安全验收评价报告应当符合《危险化学品建设项目安全评价细则》的要求。"},{"i":26,"n":"第二十六条","txt":"建设项目投入生产和使用前，建设单位应当组织人员进行安全设施竣工验收，作出建设项目安全设施竣工验收是否通过的结论。参加验收人员的专业能力应当涵盖建设项目涉及的所有专业内容。 建设单位应当向参加验收人员提供下列文件、资料，并组织进行现场检查： （一）建设项目安全设施施工、监理情况报告； （二）建设项目安全验收评价报告； （三）试生产（使用）期间是否发生事故、采取的防范措施以及整改情况报告； （四）建设项目施工、监理单位资质证书（复制件）； （五）主要负责人、安全生产管理人员、注册安全工程师资格证书（复制件），以及特种作业人员名单； （六）从业人员安全教育、培训合格的证明材料； （七）劳动防护用品配备情况说明； （八）安全生产责任制文件，安全生产规章制度清单、岗位操作安全规程清单； （九）设置安全生产管理机构和配备专职安全生产管理人员的文件（复制件）； （十）为从业人员缴纳工伤保险费的证明材"},{"i":27,"n":"第二十七条","txt":"建设项目安全设施有下列情形之一的，建设项目安全设施竣工验收不予通过： （一）未委托具备相应资质的施工单位施工的； （二）未按照已经通过审查的建设项目安全设施设计施工或者施工质量未达到建设项目安全设施设计文件要求的； （三）建设项目安全设施的施工不符合国家标准、行业标准的规定的； （四）建设项目安全设施竣工后未按照本办法的规定进行检验、检测，或者经检验、检测不合格的； （五）未委托具备相应资质的安全评价机构进行安全验收评价的； （六）安全设施和安全生产条件不符合或者未达到有关安全生产法律、法规、规章和国家标准、行业标准的规定的； （七）安全验收评价报告存在重大缺陷、漏项，包括建设项目主要危险、有害因素辨识和评价不正确的； （八）隐瞒有关情况或者提供虚假文件、资料的； （九）未按照本办法规定向参加验收人员提供文件、材料，并组织现场检查的。 建设项目安全设施竣工验收未通过的，建设单位经过整改"},{"i":28,"n":"第二十八条","txt":"建设单位组织安全设施竣工验收合格后，应将验收过程中涉及的文件、资料存档，并按照有关法律法规及其配套规章的规定申请有关危险化学品的其他安全许可。"},{"i":29,"n":"第二十九条","txt":"建设项目在通过安全条件审查之后、安全设施竣工验收之前，建设单位发生变更的，变更后的建设单位应当及时将证明材料和有关情况报送负责建设项目安全审查的安全生产监督管理部门。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，负责审查的安全生产监督管理部门或者其上级安全生产监督管理部门可以撤销建设项目的安全审查： （一）滥用职权、玩忽职守的； （二）超越法定职权的； （三）违反法定程序的； （四）申请人不具备申请资格或者不符合法定条件的； （五）依法可以撤销的其他情形。 建设单位以欺骗、贿赂等不正当手段通过安全审查的，应当予以撤销。"},{"i":31,"n":"第三十一条","txt":"安全生产监督管理部门应当建立健全建设项目安全审查档案及其管理制度，并及时将建设项目的安全审查情况通报有关部门。"},{"i":32,"n":"第三十二条","txt":"各级安全生产监督管理部门应当按照各自职责，依法对建设项目安全审查情况进行监督检查，对检查中发现的违反本办法的情况，应当依法作出处理，并通报实施安全审查的安全生产监督管理部门。"},{"i":33,"n":"第三十三条","txt":"市级安全生产监督管理部门应当在每年1月31日前，将本行政区域内上一年度建设项目安全审查的实施情况报告省级安全生产监督管理部门。 省级安全生产监督管理部门应当在每年2月15日前，将本行政区域内上一年度建设项目安全审查的实施情况报告国家安全生产监督管理总局。"},{"i":34,"n":"第三十四条","txt":"安全生产监督管理部门工作人员徇私舞弊、滥用职权、玩忽职守，未依法履行危险化学品建设项目安全审查和监督管理职责的，依法给予处分。"},{"i":35,"n":"第三十五条","txt":"未经安全条件审查或者安全条件审查未通过，新建、改建、扩建生产、储存危险化学品的建设项目的，责令停止建设，限期改正；逾期不改正的，处50万元以上100万元以下的罚款；构成犯罪的，依法追究刑事责任。 建设项目发生本办法第十四条规定的变化后，未重新申请安全条件审查，以及审查未通过擅自建设的，依照前款规定处罚。"},{"i":36,"n":"第三十六条","txt":"建设单位有下列行为之一的，依照《中华人民共和国安全生产法》有关建设项目安全设施设计审查、竣工验收的法律责任条款给予处罚： （一）建设项目安全设施设计未经审查或者审查未通过，擅自建设的； （二）建设项目安全设施设计发生本办法第二十一条规定的情形之一，未经变更设计审查或者变更设计审查未通过，擅自建设的； （三）建设项目的施工单位未根据批准的安全设施设计施工的； （四）建设项目安全设施未经竣工验收或者验收不合格，擅自投入生产（使用）的。"},{"i":37,"n":"第三十七条","txt":"建设单位有下列行为之一的，责令改正，可以处1万元以下的罚款；逾期未改正的，处1万元以上3万元以下的罚款： （一）建设项目安全设施竣工后未进行检验、检测的； （二）在申请建设项目安全审查时提供虚假文件、资料的； （三）未组织有关单位和专家研究提出试生产（使用）可能出现的安全问题及对策，或者未制定周密的试生产（使用）方案，进行试生产（使用）的； （四）未组织有关专家对试生产（使用）方案进行审查、对试生产（使用）条件进行检查确认的。"},{"i":38,"n":"第三十八条","txt":"建设单位隐瞒有关情况或者提供虚假材料申请建设项目安全审查的，不予受理或者审查不予通过，给予警告，并自安全生产监督管理部门发现之日起一年内不得再次申请该审查。 建设单位采用欺骗、贿赂等不正当手段取得建设项目安全审查的，自安全生产监督管理部门撤销建设项目安全审查之日起三年内不得再次申请该审查。"},{"i":39,"n":"第三十九条","txt":"承担安全评价、检验、检测工作的机构出具虚假报告、证明的，依照《中华人民共和国安全生产法》的有关规定给予处罚。"},{"i":40,"n":"第四十条","txt":"对于规模较小、危险程度较低和工艺路线简单的建设项目，安全生产监督管理部门可以适当简化建设项目安全审查的程序和内容。"},{"i":41,"n":"第四十一条","txt":"建设项目分期建设的，可以分期进行安全条件审查、安全设施设计审查、试生产及安全设施竣工验收。"},{"i":42,"n":"第四十二条","txt":"本办法所称新建项目，是指有下列情形之一的项目： （一）新设立的企业建设危险化学品生产、储存装置（设施），或者现有企业建设与现有生产、储存活动不同的危险化学品生产、储存装置（设施）的； （二）新设立的企业建设伴有危险化学品产生的化学品生产装置（设施），或者现有企业建设与现有生产活动不同的伴有危险化学品产生的化学品生产装置（设施）的。"},{"i":43,"n":"第四十三条","txt":"本办法所称改建项目，是指有下列情形之一的项目： （一）企业对在役危险化学品生产、储存装置（设施），在原址更新技术、工艺、主要装置（设施）、危险化学品种类的； （二）企业对在役伴有危险化学品产生的化学品生产装置（设施），在原址更新技术、工艺、主要装置（设施）的。"},{"i":44,"n":"第四十四条","txt":"本办法所称扩建项目，是指有下列情形之一的项目： （一）企业建设与现有技术、工艺、主要装置（设施）、危险化学品品种相同，但生产、储存装置（设施）相对独立的； （二）企业建设与现有技术、工艺、主要装置（设施）相同，但生产装置（设施）相对独立的伴有危险化学品产生的。"},{"i":45,"n":"第四十五条","txt":"实施建设项目安全审查所需的有关文书的内容和格式，由国家安全生产监督管理总局另行规定。"},{"i":46,"n":"第四十六条","txt":"省级安全生产监督管理部门可以根据本办法的规定，制定和公布本行政区域内需要简化安全条件审查和分期安全条件审查的建设项目范围及其审查内容，并报国家安全生产监督管理总局备案。"},{"i":47,"n":"第四十七条","txt":"本办法施行后，负责实施建设项目安全审查的安全生产监督管理部门发生变化的（已通过安全设施竣工验收的建设项目除外），原安全生产监督管理部门应当将建设项目安全审查实施情况及档案移交根据本办法负责实施建设项目安全审查的安全生产监督管理部门。"},{"i":48,"n":"第四十八条","txt":"本办法自2012年4月1日起施行。国家安全生产监督管理总局2006年9月2日公布的《危险化学品建设项目安全许可实施办法》同时废止。"}],"weixianhuaxuepinshengchanqiyeanquanshengchanxukezh246dde":[{"i":1,"n":"第一条","txt":"为了严格规范危险化学品生产企业安全生产条件，做好危险化学品生产企业安全生产许可证的颁发和管理工作，根据《安全生产许可证条例》、《危险化学品安全管理条例》等法律、行政法规，制定本实施办法。"},{"i":2,"n":"第二条","txt":"本办法所称危险化学品生产企业（以下简称企业），是指依法设立且取得工商营业执照或者工商核准文件从事生产最终产品或者中间产品列入《危险化学品目录》的企业。"},{"i":3,"n":"第三条","txt":"企业应当依照本办法的规定取得危险化学品安全生产许可证（以下简称安全生产许可证）。未取得安全生产许可证的企业，不得从事危险化学品的生产活动。"},{"i":4,"n":"第四条","txt":"安全生产许可证的颁发管理工作实行企业申请、两级发证、属地监管的原则。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局指导、监督全国安全生产许可证的颁发管理工作。 省、自治区、直辖市安全生产监督管理部门（以下简称省级安全生产监督管理部门）负责本行政区域内中央企业及其直接控股涉及危险化学品生产的企业（总部）以外的企业安全生产许可证的颁发管理。"},{"i":6,"n":"第六条","txt":"省级安全生产监督管理部门可以将其负责的安全生产许可证颁发工作，委托企业所在地设区的市级或者县级安全生产监督管理部门实施。涉及剧毒化学品生产的企业安全生产许可证颁发工作，不得委托实施。国家安全生产监督管理总局公布的涉及危险化工工艺和重点监管危险化学品的企业安全生产许可证颁发工作，不得委托县级安全生产监督管理部门实施。 受委托的设区的市级或者县级安全生产监督管理部门在受委托的范围内，以省级安全生产监督管理部门的名义实施许可，但不得再委托其他组织和个人实施。 国家安全生产监督管理总局、省级安全生产监督管理部门和受委托的设区的市级或者县级安全生产监督管理部门统称实施机关。"},{"i":7,"n":"第七条","txt":"省级安全生产监督管理部门应当将受委托的设区的市级或者县级安全生产监督管理部门以及委托事项予以公告。 省级安全生产监督管理部门应当指导、监督受委托的设区的市级或者县级安全生产监督管理部门颁发安全生产许可证，并对其法律后果负责。"},{"i":8,"n":"第八条","txt":"企业选址布局、规划设计以及与重要场所、设施、区域的距离应当符合下列要求： （一）国家产业政策；当地县级以上（含县级）人民政府的规划和布局；新设立企业建在地方人民政府规划的专门用于危险化学品生产、储存的区域内； （二）危险化学品生产装置或者储存危险化学品数量构成重大危险源的储存设施，与《危险化学品安全管理条例》第十九条第一款规定的八类场所、设施、区域的距离符合有关法律、法规、规章和国家标准或者行业标准的规定； （三）总体布局符合《化工企业总图运输设计规范》（GB50489）、《工业企业总平面设计规范》（GB50187）、《建筑设计防火规范》（GB50016）等标准的要求。 石油化工企业除符合本条第一款规定条件外，还应当符合《石油化工企业设计防火规范》（GB50160）的要求。"},{"i":9,"n":"第九条","txt":"企业的厂房、作业场所、储存设施和安全设施、设备、工艺应当符合下列要求： （一）新建、改建、扩建建设项目经具备国家规定资质的单位设计、制造和施工建设；涉及危险化工工艺、重点监管危险化学品的装置，由具有综合甲级资质或者化工石化专业甲级设计资质的化工石化设计单位设计； （二）不得采用国家明令淘汰、禁止使用和危及安全生产的工艺、设备；新开发的危险化学品生产工艺必须在小试、中试、工业化试验的基础上逐步放大到工业化生产；国内首次使用的化工工艺，必须经过省级人民政府有关部门组织的安全可靠性论证； （三）涉及危险化工工艺、重点监管危险化学品的装置装设自动化控制系统；涉及危险化工工艺的大型化工装置装设紧急停车系统；涉及易燃易爆、有毒有害气体化学品的场所装设易燃易爆、有毒有害介质泄漏报警等安全设施； （四）生产区与非生产区分开设置，并符合国家标准或者行业标准规定的距离； （五）危险化学品生产装置和储存设施"},{"i":10,"n":"第十条","txt":"企业应当有相应的职业危害防护设施，并为从业人员配备符合国家标准或者行业标准的劳动防护用品。"},{"i":11,"n":"第十一条","txt":"企业应当依据《危险化学品重大危险源辨识》（GB18218），对本企业的生产、储存和使用装置、设施或者场所进行重大危险源辨识。 对已确定为重大危险源的生产和储存设施，应当执行《危险化学品重大危险源监督管理暂行规定》。"},{"i":12,"n":"第十二条","txt":"企业应当依法设置安全生产管理机构，配备专职安全生产管理人员。配备的专职安全生产管理人员必须能够满足安全生产的需要。"},{"i":13,"n":"第十三条","txt":"企业应当建立全员安全生产责任制，保证每位从业人员的安全生产责任与职务、岗位相匹配。"},{"i":14,"n":"第十四条","txt":"企业应当根据化工工艺、装置、设施等实际情况，制定完善下列主要安全生产规章制度： （一）安全生产例会等安全生产会议制度； （二）安全投入保障制度； （三）安全生产奖惩制度； （四）安全培训教育制度； （五）领导干部轮流现场带班制度； （六）特种作业人员管理制度； （七）安全检查和隐患排查治理制度； （八）重大危险源评估和安全管理制度； （九）变更管理制度； （十）应急管理制度； （十一）生产安全事故或者重大事件管理制度； （十二）防火、防爆、防中毒、防泄漏管理制度； （十三）工艺、设备、电气仪表、公用工程安全管理制度； （十四）动火、进入受限空间、吊装、高处、盲板抽堵、动土、断路、设备检维修等作业安全管理制度； （十五）危险化学品安全管理制度； （十六）职业健康相关管理制度； （十七）劳动防护用品使用维护管理制度； （十八）承包商管理制度； （十九）安全管理制度及操作规程定期修订制度。"},{"i":15,"n":"第十五条","txt":"企业应当根据危险化学品的生产工艺、技术、设备特点和原辅料、产品的危险性编制岗位操作安全规程。"},{"i":16,"n":"第十六条","txt":"企业主要负责人、分管安全负责人和安全生产管理人员必须具备与其从事的生产经营活动相适应的安全生产知识和管理能力，依法参加安全生产培训，并经考核合格，取得安全合格证书。 企业分管安全负责人、分管生产负责人、分管技术负责人应当具有一定的化工专业知识或者相应的专业学历，专职安全生产管理人员应当具备国民教育化工化学类（或安全工程）中等职业教育以上学历或者化工化学类中级以上专业技术职称。 企业应当有危险物品安全类注册安全工程师从事安全生产管理工作。 特种作业人员应当依照《特种作业人员安全技术培训考核管理规定》，经专门的安全技术培训并考核合格，取得特种作业操作证书。 本条第一、二、四款规定以外的其他从业人员应当按照国家有关规定，经安全教育培训合格。"},{"i":17,"n":"第十七条","txt":"企业应当按照国家规定提取与安全生产有关的费用，并保证安全生产所必须的资金投入。"},{"i":18,"n":"第十八条","txt":"企业应当依法参加工伤保险，为从业人员缴纳保险费。"},{"i":19,"n":"第十九条","txt":"企业应当依法委托具备国家规定资质的安全评价机构进行安全评价，并按照安全评价报告的意见对存在的安全生产问题进行整改。"},{"i":20,"n":"第二十条","txt":"企业应当依法进行危险化学品登记，为用户提供化学品安全技术说明书，并在危险化学品包装（包括外包装件）上粘贴或者拴挂与包装内危险化学品相符的化学品安全标签。"},{"i":21,"n":"第二十一条","txt":"企业应当符合下列应急管理要求： （一）按照国家有关规定编制危险化学品事故应急预案并报有关部门备案； （二）建立应急救援组织，规模较小的企业可以不建立应急救援组织，但应指定兼职的应急救援人员； （三）配备必要的应急救援器材、设备和物资，并进行经常性维护、保养，保证正常运转。 生产、储存和使用氯气、氨气、光气、硫化氢等吸入性有毒有害气体的企业，除符合本条第一款的规定外，还应当配备至少两套以上全封闭防化服；构成重大危险源的，还应当设立气体防护站（组）。"},{"i":22,"n":"第二十二条","txt":"企业除符合本章规定的安全生产条件，还应当符合有关法律、行政法规和国家标准或者行业标准规定的其他安全生产条件。"},{"i":23,"n":"第二十三条","txt":"中央企业及其直接控股涉及危险化学品生产的企业（总部）以外的企业向所在地省级安全生产监督管理部门或其委托的安全生产监督管理部门申请安全生产许可证。"},{"i":24,"n":"第二十四条","txt":"新建企业安全生产许可证的申请，应当在危险化学品生产建设项目安全设施竣工验收通过后10个工作日内提出。"},{"i":25,"n":"第二十五条","txt":"企业申请安全生产许可证时，应当提交下列文件、资料，并对其内容的真实性负责： （一）申请安全生产许可证的文件及申请书； （二）安全生产责任制文件，安全生产规章制度、岗位操作安全规程清单； （三）设置安全生产管理机构，配备专职安全生产管理人员的文件复制件； （四）主要负责人、分管安全负责人、安全生产管理人员和特种作业人员的安全合格证或者特种作业操作证复制件； （五）与安全生产有关的费用提取和使用情况报告，新建企业提交有关安全生产费用提取和使用规定的文件； （六）为从业人员缴纳工伤保险费的证明材料； （七）危险化学品事故应急救援预案的备案证明文件； （八）危险化学品登记证复制件； （九）工商营业执照副本或者工商核准文件复制件； （十）具备资质的中介机构出具的安全评价报告； （十一）新建企业的竣工验收报告； （十二）应急救援组织或者应急救援人员，以及应急救援器材、设备设施清单。 有危险化学品重"},{"i":26,"n":"第二十六条","txt":"实施机关收到企业申请文件、资料后，应当按照下列情况分别作出处理： （一）申请事项依法不需要取得安全生产许可证的，即时告知企业不予受理； （二）申请事项依法不属于本实施机关职责范围的，即时作出不予受理的决定，并告知企业向相应的实施机关申请； （三）申请材料存在可以当场更正的错误的，允许企业当场更正，并受理其申请； （四）申请材料不齐全或者不符合法定形式的，当场告知或者在5个工作日内出具补正告知书，一次告知企业需要补正的全部内容；逾期不告知的，自收到申请材料之日起即为受理； （五）企业申请材料齐全、符合法定形式，或者按照实施机关要求提交全部补正材料的，立即受理其申请。 实施机关受理或者不予受理行政许可申请，应当出具加盖本机关专用印章和注明日期的书面凭证。"},{"i":27,"n":"第二十七条","txt":"安全生产许可证申请受理后，实施机关应当组织对企业提交的申请文件、资料进行审查。对企业提交的文件、资料实质内容存在疑问，需要到现场核查的，应当指派工作人员就有关内容进行现场核查。工作人员应当如实提出现场核查意见。"},{"i":28,"n":"第二十八条","txt":"实施机关应当在受理之日起45个工作日内作出是否准予许可的决定。审查过程中的现场核查所需时间不计算在本条规定的期限内。"},{"i":29,"n":"第二十九条","txt":"实施机关作出准予许可决定的，应当自决定之日起10个工作日内颁发安全生产许可证。 实施机关作出不予许可的决定的，应当在10个工作日内书面告知企业并说明理由。"},{"i":30,"n":"第三十条","txt":"企业在安全生产许可证有效期内变更主要负责人、企业名称或者注册地址的，应当自工商营业执照或者隶属关系变更之日起10个工作日内向实施机关提出变更申请，并提交下列文件、资料： （一）变更后的工商营业执照副本复制件； （二）变更主要负责人的，还应当提供主要负责人经安全生产监督管理部门考核合格后颁发的安全合格证复制件； （三）变更注册地址的，还应当提供相关证明材料。 对已经受理的变更申请，实施机关应当在对企业提交的文件、资料审查无误后，方可办理安全生产许可证变更手续。 企业在安全生产许可证有效期内变更隶属关系的，仅需提交隶属关系变更证明材料报实施机关备案。"},{"i":31,"n":"第三十一条","txt":"企业在安全生产许可证有效期内，当原生产装置新增产品或者改变工艺技术对企业的安全生产产生重大影响时，应当对该生产装置或者工艺技术进行专项安全评价，并对安全评价报告中提出的问题进行整改；在整改完成后，向原实施机关提出变更申请，提交安全评价报告。实施机关按照本办法第三十条的规定办理变更手续。"},{"i":32,"n":"第三十二条","txt":"企业在安全生产许可证有效期内，有危险化学品新建、改建、扩建建设项目（以下简称建设项目）的，应当在建设项目安全设施竣工验收合格之日起10个工作日内向原实施机关提出变更申请，并提交建设项目安全设施竣工验收报告等相关文件、资料。实施机关按照本办法第二十七条、第二十八条和第二十九条的规定办理变更手续。"},{"i":33,"n":"第三十三条","txt":"安全生产许可证有效期为3年。企业安全生产许可证有效期届满后继续生产危险化学品的，应当在安全生产许可证有效期届满前3个月提出延期申请，并提交延期申请书和本办法第二十五条规定的申请文件、资料。 实施机关按照本办法第二十六条、第二十七条、第二十八条、第二十九条的规定进行审查，并作出是否准予延期的决定。"},{"i":34,"n":"第三十四条","txt":"企业在安全生产许可证有效期内，符合下列条件的，其安全生产许可证届满时，经原实施机关同意，可不提交第二十五条第一款第二、七、八、十、十一项规定的文件、资料，直接办理延期手续： （一）严格遵守有关安全生产的法律、法规和本办法的； （二）取得安全生产许可证后，加强日常安全生产管理，未降低安全生产条件，并达到安全生产标准化等级二级以上的； （三）未发生死亡事故的。"},{"i":35,"n":"第三十五条","txt":"安全生产许可证分为正、副本，正本为悬挂式，副本为折页式，正、副本具有同等法律效力。 实施机关应当分别在安全生产许可证正、副本上载明编号、企业名称、主要负责人、注册地址、经济类型、许可范围、有效期、发证机关、发证日期等内容。其中，正本上的“许可范围”应当注明“危险化学品生产”，副本上的“许可范围”应当载明生产场所地址和对应的具体品种、生产能力。 安全生产许可证有效期的起始日为实施机关作出许可决定之日，截止日为起始日至三年后同一日期的前一日。有效期内有变更事项的，起始日和截止日不变，载明变更日期。"},{"i":36,"n":"第三十六条","txt":"企业不得出租、出借、买卖或者以其他形式转让其取得的安全生产许可证，或者冒用他人取得的安全生产许可证、使用伪造的安全生产许可证。"},{"i":37,"n":"第三十七条","txt":"实施机关应当坚持公开、公平、公正的原则，依照本办法和有关安全生产行政许可的法律、法规规定，颁发安全生产许可证。 实施机关工作人员在安全生产许可证颁发及其监督管理工作中，不得索取或者接受企业的财物，不得谋取其他非法利益。"},{"i":38,"n":"第三十八条","txt":"实施机关应当加强对安全生产许可证的监督管理，建立、健全安全生产许可证档案管理制度。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，实施机关应当撤销已经颁发的安全生产许可证： （一）超越职权颁发安全生产许可证的； （二）违反本办法规定的程序颁发安全生产许可证的； （三）以欺骗、贿赂等不正当手段取得安全生产许可证的。"},{"i":40,"n":"第四十条","txt":"企业取得安全生产许可证后有下列情形之一的，实施机关应当注销其安全生产许可证： （一）安全生产许可证有效期届满未被批准延续的； （二）终止危险化学品生产活动的； （三）安全生产许可证被依法撤销的； （四）安全生产许可证被依法吊销的。 安全生产许可证注销后，实施机关应当在当地主要新闻媒体或者本机关网站上发布公告，并通报企业所在地人民政府和县级以上安全生产监督管理部门。"},{"i":41,"n":"第四十一条","txt":"省级安全生产监督管理部门应当在每年1月15日前，将本行政区域内上年度安全生产许可证的颁发和管理情况报国家安全生产监督管理总局。 国家安全生产监督管理总局、省级安全生产监督管理部门应当定期向社会公布企业取得安全生产许可的情况，接受社会监督。"},{"i":42,"n":"第四十二条","txt":"实施机关工作人员有下列行为之一的，给予降级或者撤职的处分；构成犯罪的，依法追究刑事责任： （一）向不符合本办法第二章规定的安全生产条件的企业颁发安全生产许可证的； （二）发现企业未依法取得安全生产许可证擅自从事危险化学品生产活动，不依法处理的； （三）发现取得安全生产许可证的企业不再具备本办法第二章规定的安全生产条件，不依法处理的； （四）接到对违反本办法规定行为的举报后，不及时依法处理的； （五）在安全生产许可证颁发和监督管理工作中，索取或者接受企业的财物，或者谋取其他非法利益的。"},{"i":43,"n":"第四十三条","txt":"企业取得安全生产许可证后发现其不具备本办法规定的安全生产条件的，依法暂扣其安全生产许可证1个月以上6个月以下；暂扣期满仍不具备本办法规定的安全生产条件的，依法吊销其安全生产许可证。"},{"i":44,"n":"第四十四条","txt":"企业出租、出借或者以其他形式转让安全生产许可证的，没收违法所得，处10万元以上50万元以下的罚款，并吊销安全生产许可证；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"企业有下列情形之一的，责令停止生产危险化学品，没收违法所得，并处10万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任： （一）未取得安全生产许可证，擅自进行危险化学品生产的； （二）接受转让的安全生产许可证的； （三）冒用或者使用伪造的安全生产许可证的。"},{"i":46,"n":"第四十六条","txt":"企业在安全生产许可证有效期届满未办理延期手续，继续进行生产的，责令停止生产，限期补办延期手续，没收违法所得，并处5万元以上10万元以下的罚款；逾期仍不办理延期手续，继续进行生产的，依照本办法第四十五条的规定进行处罚。"},{"i":47,"n":"第四十七条","txt":"企业在安全生产许可证有效期内主要负责人、企业名称、注册地址、隶属关系发生变更或者新增产品、改变工艺技术对企业安全生产产生重大影响，未按照本办法第三十条规定的时限提出安全生产许可证变更申请的，责令限期申请，处1万元以上3万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"企业在安全生产许可证有效期内，其危险化学品建设项目安全设施竣工验收合格后，未按照本办法第三十二条规定的时限提出安全生产许可证变更申请并且擅自投入运行的，责令停止生产，限期申请，没收违法所得，并处1万元以上3万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"发现企业隐瞒有关情况或者提供虚假材料申请安全生产许可证的，实施机关不予受理或者不予颁发安全生产许可证，并给予警告，该企业在1年内不得再次申请安全生产许可证。 企业以欺骗、贿赂等不正当手段取得安全生产许可证的，自实施机关撤销其安全生产许可证之日起3年内，该企业不得再次申请安全生产许可证。"},{"i":50,"n":"第五十条","txt":"安全评价机构有下列情形之一的，给予警告，并处1万元以下的罚款；情节严重的，暂停资质半年，并处1万元以上3万元以下的罚款；对相关责任人依法给予处理： （一）从业人员不到现场开展安全评价活动的； （二）安全评价报告与实际情况不符，或者安全评价报告存在重大疏漏，但尚未造成重大损失的； （三）未按照有关法律、法规、规章和国家标准或者行业标准的规定从事安全评价活动的。"},{"i":51,"n":"第五十一条","txt":"承担安全评价、检测、检验的机构出具虚假证明的，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与企业承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构，依法吊销其相应资质。"},{"i":52,"n":"第五十二条","txt":"本办法规定的行政处罚，由国家安全生产监督管理总局、省级安全生产监督管理部门决定。省级安全生产监督管理部门可以委托设区的市级或者县级安全生产监督管理部门实施。"},{"i":53,"n":"第五十三条","txt":"将纯度较低的化学品提纯至纯度较高的危险化学品的，适用本办法。购买某种危险化学品进行分装（包括充装）或者加入非危险化学品的溶剂进行稀释，然后销售或者使用的，不适用本办法。"},{"i":54,"n":"第五十四条","txt":"本办法下列用语的含义： （一）危险化学品目录，是指国家安全生产监督管理总局会同国务院工业和信息化、公安、环境保护、卫生、质量监督检验检疫、交通运输、铁路、民用航空、农业主管部门，依据《危险化学品安全管理条例》公布的危险化学品目录。 （二）中间产品，是指为满足生产的需要，生产一种或者多种产品为下一个生产过程参与化学反应的原料。 （三）作业场所，是指可能使从业人员接触危险化学品的任何作业活动场所，包括从事危险化学品的生产、操作、处置、储存、装卸等场所。"},{"i":55,"n":"第五十五条","txt":"安全生产许可证由国家安全生产监督管理总局统一印制。 危险化学品安全生产许可的文书、安全生产许可证的格式、内容和编号办法，由国家安全生产监督管理总局另行规定。"},{"i":56,"n":"第五十六条","txt":"省级安全生产监督管理部门可以根据当地实际情况制定安全生产许可证颁发管理的细则，并报国家安全生产监督管理总局备案。"},{"i":57,"n":"第五十七条","txt":"本办法自2011年12月1日起施行。原国家安全生产监督管理局（国家煤矿安全监察局）2004年5月17日公布的《危险化学品生产企业安全生产许可证实施办法》同时废止。"}],"weixianhuaxuepindengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对危险化学品的安全管理，规范危险化学品登记工作，为危险化学品事故预防和应急救援提供技术、信息支持，根据《危险化学品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于危险化学品生产企业、进口企业（以下统称登记企业）生产或者进口《危险化学品目录》所列危险化学品的登记和管理工作。"},{"i":3,"n":"第三条","txt":"国家实行危险化学品登记制度。危险化学品登记实行企业申请、两级审核、统一发证、分级管理的原则。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局负责全国危险化学品登记的监督管理工作。 县级以上地方各级人民政府安全生产监督管理部门负责本行政区域内危险化学品登记的监督管理工作。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局化学品登记中心（以下简称登记中心），承办全国危险化学品登记的具体工作和技术管理工作。 省、自治区、直辖市人民政府安全生产监督管理部门设立危险化学品登记办公室或者危险化学品登记中心（以下简称登记办公室），承办本行政区域内危险化学品登记的具体工作和技术管理工作。"},{"i":6,"n":"第六条","txt":"登记中心履行下列职责： （一）组织、协调和指导全国危险化学品登记工作； （二）负责全国危险化学品登记内容审核、危险化学品登记证的颁发和管理工作； （三）负责管理与维护全国危险化学品登记信息管理系统（以下简称登记系统）以及危险化学品登记信息的动态统计分析工作； （四）负责管理与维护国家危险化学品事故应急咨询电话，并提供24小时应急咨询服务； （五）组织化学品危险性评估，对未分类的化学品统一进行危险性分类； （六）对登记办公室进行业务指导，负责全国登记办公室危险化学品登记人员的培训工作； （七）定期将危险化学品的登记情况通报国务院有关部门，并向社会公告。"},{"i":7,"n":"第七条","txt":"登记办公室履行下列职责： （一）组织本行政区域内危险化学品登记工作； （二）对登记企业申报材料的规范性、内容一致性进行审查； （三）负责本行政区域内危险化学品登记信息的统计分析工作； （四）提供危险化学品事故预防与应急救援信息支持； （五）协助本行政区域内安全生产监督管理部门开展登记培训，指导登记企业实施危险化学品登记工作。"},{"i":8,"n":"第八条","txt":"登记中心和登记办公室（以下统称登记机构）从事危险化学品登记的工作人员（以下简称登记人员）应当具有化工、化学、安全工程等相关专业大学专科以上学历，并经统一业务培训，取得培训合格证，方可上岗作业。"},{"i":9,"n":"第九条","txt":"登记办公室应当具备下列条件： （一）有3名以上登记人员； （二）有严格的责任制度、保密制度、档案管理制度和数据库维护制度； （三）配备必要的办公设备、设施。"},{"i":10,"n":"第十条","txt":"新建的生产企业应当在竣工验收前办理危险化学品登记。 进口企业应当在首次进口前办理危险化学品登记。"},{"i":11,"n":"第十一条","txt":"同一企业生产、进口同一品种危险化学品的，按照生产企业进行一次登记，但应当提交进口危险化学品的有关信息。 进口企业进口不同制造商的同一品种危险化学品的，按照首次进口制造商的危险化学品进行一次登记，但应当提交其他制造商的危险化学品的有关信息。 生产企业、进口企业多次进口同一制造商的同一品种危险化学品的，只进行一次登记。"},{"i":12,"n":"第十二条","txt":"危险化学品登记应当包括下列内容： （一）分类和标签信息，包括危险化学品的危险性类别、象形图、警示词、危险性说明、防范说明等； （二）物理、化学性质，包括危险化学品的外观与性状、溶解性、熔点、沸点等物理性质，闪点、爆炸极限、自燃温度、分解温度等化学性质； （三）主要用途，包括企业推荐的产品合法用途、禁止或者限制的用途等； （四）危险特性，包括危险化学品的物理危险性、环境危害性和毒理特性； （五）储存、使用、运输的安全要求，其中，储存的安全要求包括对建筑条件、库房条件、安全条件、环境卫生条件、温度和湿度条件的要求，使用的安全要求包括使用时的操作条件、作业人员防护措施、使用现场危害控制措施等，运输的安全要求包括对运输或者输送方式的要求、危害信息向有关运输人员的传递手段、装卸及运输过程中的安全措施等； （六）出现危险情况的应急处置措施，包括危险化学品在生产、使用、储存、运输过程中发生火灾、爆炸"},{"i":13,"n":"第十三条","txt":"危险化学品登记按照下列程序办理： （一）登记企业通过登记系统提出申请； （二）登记办公室在3个工作日内对登记企业提出的申请进行初步审查，符合条件的，通过登记系统通知登记企业办理登记手续； （三）登记企业接到登记办公室通知后，按照有关要求在登记系统中如实填写登记内容，并向登记办公室提交有关纸质登记材料； （四）登记办公室在收到登记企业的登记材料之日起20个工作日内，对登记材料和登记内容逐项进行审查，必要时可进行现场核查，符合要求的，将登记材料提交给登记中心；不符合要求的，通过登记系统告知登记企业并说明理由； （五）登记中心在收到登记办公室提交的登记材料之日起15个工作日内，对登记材料和登记内容进行审核，符合要求的，通过登记办公室向登记企业发放危险化学品登记证；不符合要求的，通过登记系统告知登记办公室、登记企业并说明理由。 登记企业修改登记材料和整改问题所需时间，不计算在前款规定的期限内。"},{"i":14,"n":"第十四条","txt":"登记企业办理危险化学品登记时，应当提交下列材料，并对其内容的真实性负责： （一）危险化学品登记表一式2份； （二）生产企业的工商营业执照，进口企业的对外贸易经营者备案登记表、中华人民共和国进出口企业资质证书、中华人民共和国外商投资企业批准证书或者台港澳侨投资企业批准证书复制件1份； （三）与其生产、进口的危险化学品相符并符合国家标准的化学品安全技术说明书、化学品安全标签各1份； （四）满足本办法第二十二条规定的应急咨询服务电话号码或者应急咨询服务委托书复制件1份； （五）办理登记的危险化学品产品标准（采用国家标准或者行业标准的，提供所采用的标准编号）。"},{"i":15,"n":"第十五条","txt":"登记企业在危险化学品登记证有效期内，企业名称、注册地址、登记品种、应急咨询服务电话发生变化，或者发现其生产、进口的危险化学品有新的危险特性的，应当在15个工作日内向登记办公室提出变更申请，并按照下列程序办理登记内容变更手续： （一）通过登记系统填写危险化学品登记变更申请表，并向登记办公室提交涉及变更事项的证明材料1份； （二）登记办公室初步审查登记企业的登记变更申请，符合条件的，通知登记企业提交变更后的登记材料，并对登记材料进行审查，符合要求的，提交给登记中心；不符合要求的，通过登记系统告知登记企业并说明理由； （三）登记中心对登记办公室提交的登记材料进行审核，符合要求且属于危险化学品登记证载明事项的，通过登记办公室向登记企业发放登记变更后的危险化学品登记证并收回原证；符合要求但不属于危险化学品登记证载明事项的，通过登记办公室向登记企业提供书面证明文件。"},{"i":16,"n":"第十六条","txt":"危险化学品登记证有效期为3年。登记证有效期满后，登记企业继续从事危险化学品生产或者进口的，应当在登记证有效期届满前3个月提出复核换证申请，并按下列程序办理复核换证： （一）通过登记系统填写危险化学品复核换证申请表； （二）登记办公室审查登记企业的复核换证申请，符合条件的，通过登记系统告知登记企业提交本规定第十四条规定的登记材料；不符合条件的，通过登记系统告知登记企业并说明理由； （三）按照本办法第十三条第一款第三项、第四项、第五项规定的程序办理复核换证手续。"},{"i":17,"n":"第十七条","txt":"危险化学品登记证分为正本、副本，正本为悬挂式，副本为折页式。正本、副本具有同等法律效力。 危险化学品登记证正本、副本应当载明证书编号、企业名称、注册地址、企业性质、登记品种、有效期、发证机关、发证日期等内容。其中，企业性质应当注明危险化学品生产企业、危险化学品进口企业或者危险化学品生产企业（兼进口）。"},{"i":18,"n":"第十八条","txt":"登记企业应当对本企业的各类危险化学品进行普查，建立危险化学品管理档案。 危险化学品管理档案应当包括危险化学品名称、数量、标识信息、危险性分类和化学品安全技术说明书、化学品安全标签等内容。"},{"i":19,"n":"第十九条","txt":"登记企业应当按照规定向登记机构办理危险化学品登记，如实填报登记内容和提交有关材料，并接受安全生产监督管理部门依法进行的监督检查。"},{"i":20,"n":"第二十条","txt":"登记企业应当指定人员负责危险化学品登记的相关工作，配合登记人员在必要时对本企业危险化学品登记内容进行核查。 登记企业从事危险化学品登记的人员应当具备危险化学品登记相关知识和能力。"},{"i":21,"n":"第二十一条","txt":"对危险特性尚未确定的化学品，登记企业应当按照国家关于化学品危险性鉴定的有关规定，委托具有国家规定资质的机构对其进行危险性鉴定；属于危险化学品的，应当依照本办法的规定进行登记。"},{"i":22,"n":"第二十二条","txt":"危险化学品生产企业应当设立由专职人员24小时值守的国内固定服务电话，针对本办法第十二条规定的内容向用户提供危险化学品事故应急咨询服务，为危险化学品事故应急救援提供技术指导和必要的协助。专职值守人员应当熟悉本企业危险化学品的危险特性和应急处置技术，准确回答有关咨询问题。 危险化学品生产企业不能提供前款规定应急咨询服务的，应当委托登记机构代理应急咨询服务。 危险化学品进口企业应当自行或者委托进口代理商、登记机构提供符合本条第一款要求的应急咨询服务，并在其进口的危险化学品安全标签上标明应急咨询服务电话号码。 从事代理应急咨询服务的登记机构，应当设立由专职人员24小时值守的国内固定服务电话，建有完善的化学品应急救援数据库，配备在线数字录音设备和8名以上专业人员，能够同时受理3起以上应急咨询，准确提供化学品泄漏、火灾、爆炸、中毒等事故应急处置有关信息和建议。"},{"i":23,"n":"第二十三条","txt":"登记企业不得转让、冒用或者使用伪造的危险化学品登记证。"},{"i":24,"n":"第二十四条","txt":"安全生产监督管理部门应当将危险化学品登记情况纳入危险化学品安全执法检查内容，对登记企业未按照规定予以登记的，依法予以处理。"},{"i":25,"n":"第二十五条","txt":"登记办公室应当对本行政区域内危险化学品的登记数据及时进行汇总、统计、分析，并报告省、自治区、直辖市人民政府安全生产监督管理部门。"},{"i":26,"n":"第二十六条","txt":"登记中心应当定期向国务院工业和信息化、环境保护、公安、卫生、交通运输、铁路、质量监督检验检疫等部门提供危险化学品登记的有关信息和资料，并向社会公告。"},{"i":27,"n":"第二十七条","txt":"登记办公室应当在每年1月31日前向所属省、自治区、直辖市人民政府安全生产监督管理部门和登记中心书面报告上一年度本行政区域内危险化学品登记的情况。 登记中心应当在每年2月15日前向国家安全生产监督管理总局书面报告上一年度全国危险化学品登记的情况。"},{"i":28,"n":"第二十八条","txt":"登记机构的登记人员违规操作、弄虚作假、滥发证书，在规定限期内无故不予登记且无明确答复，或者泄露登记企业商业秘密的，责令改正，并追究有关责任人员的责任。"},{"i":29,"n":"第二十九条","txt":"登记企业不办理危险化学品登记，登记品种发生变化或者发现其生产、进口的危险化学品有新的危险特性不办理危险化学品登记内容变更手续的，责令改正，可以处5万元以下的罚款；拒不改正的，处5万元以上10万元以下的罚款；情节严重的，责令停产停业整顿。"},{"i":30,"n":"第三十条","txt":"登记企业有下列行为之一的，责令改正，可以处3万元以下的罚款： （一）未向用户提供应急咨询服务或者应急咨询服务不符合本办法第二十二条规定的； （二）在危险化学品登记证有效期内企业名称、注册地址、应急咨询服务电话发生变化，未按规定按时办理危险化学品登记变更手续的； （三）危险化学品登记证有效期满后，未按规定申请复核换证，继续进行生产或者进口的； （四）转让、冒用或者使用伪造的危险化学品登记证，或者不如实填报登记内容、提交有关材料的。 （五）拒绝、阻挠登记机构对本企业危险化学品登记情况进行现场核查的。"},{"i":31,"n":"第三十一条","txt":"本办法所称危险化学品进口企业，是指依法设立且取得工商营业执照，并取得下列证明文件之一，从事危险化学品进口的企业： （一）对外贸易经营者备案登记表； （二）中华人民共和国进出口企业资质证书； （三）中华人民共和国外商投资企业批准证书； （四）台港澳侨投资企业批准证书。"},{"i":32,"n":"第三十二条","txt":"登记企业在本办法施行前已经取得的危险化学品登记证，其有效期不变；有效期满后继续从事危险化学品生产、进口活动的，应当依照本办法的规定办理危险化学品登记证复核换证手续。"},{"i":33,"n":"第三十三条","txt":"危险化学品登记证由国家安全生产监督管理总局统一印制。"},{"i":34,"n":"第三十四条","txt":"本办法自2012年8月1日起施行。原国家经济贸易委员会2002年10月8日公布的《危险化学品登记管理办法》同时废止。"}],"weixianhuaxuepinjingyingxukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了严格危险化学品经营安全条件，规范危险化学品经营活动，保障人民群众生命、财产安全，根据《中华人民共和国安全生产法》和《危险化学品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事列入《危险化学品目录》的危险化学品的经营（包括仓储经营）活动，适用本办法。 民用爆炸物品、放射性物品、核能物质和城镇燃气的经营活动，不适用本办法。"},{"i":3,"n":"第三条","txt":"国家对危险化学品经营实行许可制度。经营危险化学品的企业，应当依照本办法取得危险化学品经营许可证（以下简称经营许可证）。未取得经营许可证，任何单位和个人不得经营危险化学品。 从事下列危险化学品经营活动，不需要取得经营许可证： （一）依法取得危险化学品安全生产许可证的危险化学品生产企业在其厂区范围内销售本企业生产的危险化学品的； （二）依法取得港口经营许可证的港口经营人在港区内从事危险化学品仓储经营的。"},{"i":4,"n":"第四条","txt":"经营许可证的颁发管理工作实行企业申请、两级发证、属地监管的原则。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局指导、监督全国经营许可证的颁发和管理工作。 省、自治区、直辖市人民政府安全生产监督管理部门指导、监督本行政区域内经营许可证的颁发和管理工作。 设区的市级人民政府安全生产监督管理部门（以下简称市级发证机关）负责下列企业的经营许可证审批、颁发： （一）经营剧毒化学品的企业； （二）经营易制爆危险化学品的企业； （三）经营汽油加油站的企业； （四）专门从事危险化学品仓储经营的企业； （五）从事危险化学品经营活动的中央企业所属省级、设区的市级公司（分公司）； （六）带有储存设施经营除剧毒化学品、易制爆危险化学品以外的其他危险化学品的企业。 县级人民政府安全生产监督管理部门（以下简称县级发证机关）负责本行政区域内本条第三款规定以外企业的经营许可证审批、颁发；没有设立县级发证机关的，其经营许可证由市级发证机关审批、颁发。"},{"i":6,"n":"第六条","txt":"从事危险化学品经营的单位（以下统称申请人）应当依法登记注册为企业，并具备下列基本条件： （一）经营和储存场所、设施、建筑物符合《建筑设计防火规范》（GB50016）、《石油化工企业设计防火规范》（GB50160）、《汽车加油加气站设计与施工规范》（GB50156）、《石油库设计规范》（GB50074）等相关国家标准、行业标准的规定； （二）企业主要负责人和安全生产管理人员具备与本企业危险化学品经营活动相适应的安全生产知识和管理能力，经专门的安全生产培训和安全生产监督管理部门考核合格，取得相应安全资格证书；特种作业人员经专门的安全作业培训，取得特种作业操作证书；其他从业人员依照有关规定经安全生产教育和专业技术培训合格； （三）有健全的安全生产规章制度和岗位操作规程； （四）有符合国家规定的危险化学品事故应急预案，并配备必要的应急救援器材、设备； （五）法律、法规和国家标准或者行业标准规定"},{"i":7,"n":"第七条","txt":"申请人经营剧毒化学品的，除符合本办法第六条规定的条件外，还应当建立剧毒化学品双人验收、双人保管、双人发货、双把锁、双本账等管理制度。"},{"i":8,"n":"第八条","txt":"申请人带有储存设施经营危险化学品的，除符合本办法第六条规定的条件外，还应当具备下列条件： （一）新设立的专门从事危险化学品仓储经营的，其储存设施建立在地方人民政府规划的用于危险化学品储存的专门区域内； （二）储存设施与相关场所、设施、区域的距离符合有关法律、法规、规章和标准的规定； （三）依照有关规定进行安全评价，安全评价报告符合《危险化学品经营企业安全评价细则》的要求； （四）专职安全生产管理人员具备国民教育化工化学类或者安全工程类中等职业教育以上学历，或者化工化学类中级以上专业技术职称，或者危险物品安全类注册安全工程师资格； （五）符合《危险化学品安全管理条例》、《危险化学品重大危险源监督管理暂行规定》、《常用危险化学品贮存通则》（GB15603）的相关规定。 申请人储存易燃、易爆、有毒、易扩散危险化学品的，除符合本条第一款规定的条件外，还应当符合《石油化工可燃气体和有毒气体检测报"},{"i":9,"n":"第九条","txt":"申请人申请经营许可证，应当依照本办法第五条规定向所在地市级或者县级发证机关（以下统称发证机关）提出申请，提交下列文件、资料，并对其真实性负责： （一）申请经营许可证的文件及申请书； （二）安全生产规章制度和岗位操作规程的目录清单； （三）企业主要负责人、安全生产管理人员、特种作业人员的相关资格证书（复制件）和其他从业人员培训合格的证明材料； （四）经营场所产权证明文件或者租赁证明文件（复制件）； （五）工商行政管理部门颁发的企业性质营业执照或者企业名称预先核准文件（复制件）； （六）危险化学品事故应急预案备案登记表（复制件）。 带有储存设施经营危险化学品的，申请人还应当提交下列文件、资料： （一）储存设施相关证明文件（复制件）；租赁储存设施的，需要提交租赁证明文件（复制件）；储存设施新建、改建、扩建的，需要提交危险化学品建设项目安全设施竣工验收报告； （二）重大危险源备案证明材料、专职"},{"i":10,"n":"第十条","txt":"发证机关收到申请人提交的文件、资料后，应当按照下列情况分别作出处理： （一）申请事项不需要取得经营许可证的，当场告知申请人不予受理； （二）申请事项不属于本发证机关职责范围的，当场作出不予受理的决定，告知申请人向相应的发证机关申请，并退回申请文件、资料； （三）申请文件、资料存在可以当场更正的错误的，允许申请人当场更正，并受理其申请； （四）申请文件、资料不齐全或者不符合要求的，当场告知或者在5个工作日内出具补正告知书，一次告知申请人需要补正的全部内容；逾期不告知的，自收到申请文件、资料之日起即为受理； （五）申请文件、资料齐全，符合要求，或者申请人按照发证机关要求提交全部补正材料的，立即受理其申请。 发证机关受理或者不予受理经营许可证申请，应当出具加盖本机关印章和注明日期的书面凭证。"},{"i":11,"n":"第十一条","txt":"发证机关受理经营许可证申请后，应当组织对申请人提交的文件、资料进行审查，指派2名以上工作人员对申请人的经营场所、储存设施进行现场核查，并自受理之日起30日内作出是否准予许可的决定。 发证机关现场核查以及申请人整改现场核查发现的有关问题和修改有关申请文件、资料所需时间，不计算在前款规定的期限内。"},{"i":12,"n":"第十二条","txt":"发证机关作出准予许可决定的，应当自决定之日起10个工作日内颁发经营许可证；发证机关作出不予许可决定的，应当在10个工作日内书面告知申请人并说明理由，告知书应当加盖本机关印章。"},{"i":13,"n":"第十三条","txt":"经营许可证分为正本、副本，正本为悬挂式，副本为折页式。正本、副本具有同等法律效力。 经营许可证正本、副本应当分别载明下列事项： （一）企业名称； （二）企业住所（注册地址、经营场所、储存场所）； （三）企业法定代表人姓名； （四）经营方式； （五）许可范围； （六）发证日期和有效期限； （七）证书编号； （八）发证机关； （九）有效期延续情况。"},{"i":14,"n":"第十四条","txt":"已经取得经营许可证的企业变更企业名称、主要负责人、注册地址或者危险化学品储存设施及其监控措施的，应当自变更之日起20个工作日内，向本办法第五条规定的发证机关提出书面变更申请，并提交下列文件、资料： （一）经营许可证变更申请书； （二）变更后的工商营业执照副本（复制件）； （三）变更后的主要负责人安全资格证书（复制件）； （四）变更注册地址的相关证明材料； （五）变更后的危险化学品储存设施及其监控措施的专项安全评价报告。"},{"i":15,"n":"第十五条","txt":"发证机关受理变更申请后，应当组织对企业提交的文件、资料进行审查，并自收到申请文件、资料之日起10个工作日内作出是否准予变更的决定。 发证机关作出准予变更决定的，应当重新颁发经营许可证，并收回原经营许可证；不予变更的，应当说明理由并书面通知企业。 经营许可证变更的，经营许可证有效期的起始日和截止日不变，但应当载明变更日期。"},{"i":16,"n":"第十六条","txt":"已经取得经营许可证的企业有新建、改建、扩建危险化学品储存设施建设项目的，应当自建设项目安全设施竣工验收合格之日起20个工作日内，向本办法第五条规定的发证机关提出变更申请，并提交危险化学品建设项目安全设施竣工验收报告等相关文件、资料。发证机关应当按照本办法第十条、第十五条的规定进行审查，办理变更手续。"},{"i":17,"n":"第十七条","txt":"已经取得经营许可证的企业，有下列情形之一的，应当按照本办法的规定重新申请办理经营许可证，并提交相关文件、资料： （一）不带有储存设施的经营企业变更其经营场所的； （二）带有储存设施的经营企业变更其储存场所的； （三）仓储经营的企业异地重建的； （四）经营方式发生变化的； （五）许可范围发生变化的。"},{"i":18,"n":"第十八条","txt":"经营许可证的有效期为3年。有效期满后，企业需要继续从事危险化学品经营活动的，应当在经营许可证有效期满3个月前，向本办法第五条规定的发证机关提出经营许可证的延期申请，并提交延期申请书及本办法第九条规定的申请文件、资料。 企业提出经营许可证延期申请时，可以同时提出变更申请，并向发证机关提交相关文件、资料。"},{"i":19,"n":"第十九条","txt":"符合下列条件的企业，申请经营许可证延期时，经发证机关同意，可以不提交本办法第九条规定的文件、资料： （一）严格遵守有关法律、法规和本办法； （二）取得经营许可证后，加强日常安全生产管理，未降低安全生产条件； （三）未发生死亡事故或者对社会造成较大影响的生产安全事故。 带有储存设施经营危险化学品的企业，除符合前款规定条件的外，还需要取得并提交危险化学品企业安全生产标准化二级达标证书（复制件）。"},{"i":20,"n":"第二十条","txt":"发证机关受理延期申请后，应当依照本办法第十条、第十一条、第十二条的规定，对延期申请进行审查，并在经营许可证有效期满前作出是否准予延期的决定；发证机关逾期未作出决定的，视为准予延期。 发证机关作出准予延期决定的，经营许可证有效期顺延3年。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人不得伪造、变造经营许可证，或者出租、出借、转让其取得的经营许可证，或者使用伪造、变造的经营许可证。"},{"i":22,"n":"第二十二条","txt":"发证机关应当坚持公开、公平、公正的原则，严格依照法律、法规、规章、国家标准、行业标准和本办法规定的条件及程序，审批、颁发经营许可证。 发证机关及其工作人员在经营许可证的审批、颁发和监督管理工作中，不得索取或者接受当事人的财物，不得谋取其他利益。"},{"i":23,"n":"第二十三条","txt":"发证机关应当加强对经营许可证的监督管理，建立、健全经营许可证审批、颁发档案管理制度，并定期向社会公布企业取得经营许可证的情况，接受社会监督。"},{"i":24,"n":"第二十四条","txt":"发证机关应当及时向同级公安机关、环境保护部门通报经营许可证的发放情况。"},{"i":25,"n":"第二十五条","txt":"安全生产监督管理部门在监督检查中，发现已经取得经营许可证的企业不再具备法律、法规、规章、国家标准、行业标准和本办法规定的安全生产条件，或者存在违反法律、法规、规章和本办法规定的行为的，应当依法作出处理，并及时告知原发证机关。"},{"i":26,"n":"第二十六条","txt":"发证机关发现企业以欺骗、贿赂等不正当手段取得经营许可证的，应当撤销已经颁发的经营许可证。"},{"i":27,"n":"第二十七条","txt":"已经取得经营许可证的企业有下列情形之一的，发证机关应当注销其经营许可证： （一）经营许可证有效期届满未被批准延期的； （二）终止危险化学品经营活动的； （三）经营许可证被依法撤销的； （四）经营许可证被依法吊销的。 发证机关注销经营许可证后，应当在当地主要新闻媒体或者本机关网站上发布公告，并通报企业所在地人民政府和县级以上安全生产监督管理部门。"},{"i":28,"n":"第二十八条","txt":"县级发证机关应当将本行政区域内上一年度经营许可证的审批、颁发和监督管理情况报告市级发证机关。 市级发证机关应当将本行政区域内上一年度经营许可证的审批、颁发和监督管理情况报告省、自治区、直辖市人民政府安全生产监督管理部门。 省、自治区、直辖市人民政府安全生产监督管理部门应当按照有关统计规定，将本行政区域内上一年度经营许可证的审批、颁发和监督管理情况报告国家安全生产监督管理总局。"},{"i":29,"n":"第二十九条","txt":"未取得经营许可证从事危险化学品经营的，依照《中华人民共和国安全生产法》有关未经依法批准擅自生产、经营、储存危险物品的法律责任条款并处罚款；构成犯罪的，依法追究刑事责任。 企业在经营许可证有效期届满后，仍然从事危险化学品经营的，依照前款规定给予处罚。"},{"i":30,"n":"第三十条","txt":"带有储存设施的企业违反《危险化学品安全管理条例》规定，有下列情形之一的，责令改正，处5万元以上10万元以下的罚款；拒不改正的，责令停产停业整顿；经停产停业整顿仍不具备法律、法规、规章、国家标准和行业标准规定的安全生产条件的，吊销其经营许可证： （一）对重复使用的危险化学品包装物、容器，在重复使用前不进行检查的； （二）未根据其储存的危险化学品的种类和危险特性，在作业场所设置相关安全设施、设备，或者未按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养的； （三）未将危险化学品储存在专用仓库内，或者未将剧毒化学品以及储存数量构成重大危险源的其他危险化学品在专用仓库内单独存放的； （四）未对其安全生产条件定期进行安全评价的； （五）危险化学品的储存方式、方法或者储存数量不符合国家标准或者国家有关规定的； （六）危险化学品专用仓库不符合国家标准、行业标准的要求的； （七"},{"i":31,"n":"第三十一条","txt":"伪造、变造或者出租、出借、转让经营许可证，或者使用伪造、变造的经营许可证的，处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"已经取得经营许可证的企业不再具备法律、法规和本办法规定的安全生产条件的，责令改正；逾期不改正的，责令停产停业整顿；经停产停业整顿仍不具备法律、法规、规章、国家标准和行业标准规定的安全生产条件的，吊销其经营许可证。"},{"i":33,"n":"第三十三条","txt":"已经取得经营许可证的企业出现本办法第十四条、第十六条规定的情形之一，未依照本办法的规定申请变更的，责令限期改正，处1万元以下的罚款；逾期仍不申请变更的，处1万元以上3万元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"安全生产监督管理部门的工作人员徇私舞弊、滥用职权、弄虚作假、玩忽职守，未依法履行危险化学品经营许可证审批、颁发和监督管理职责的，依照有关规定给予处分。"},{"i":35,"n":"第三十五条","txt":"承担安全评价的机构和安全评价人员出具虚假评价报告的，依照有关法律、法规、规章的规定给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"本办法规定的行政处罚，由安全生产监督管理部门决定。其中，本办法第三十一条规定的行政处罚和第三十条、第三十二条规定的吊销经营许可证的行政处罚，由发证机关决定。"},{"i":37,"n":"第三十七条","txt":"购买危险化学品进行分装、充装或者加入非危险化学品的溶剂进行稀释，然后销售的，依照本办法执行。 本办法所称储存设施，是指按照《危险化学品重大危险源辨识》（GB18218）确定，储存的危险化学品数量构成重大危险源的设施。"},{"i":38,"n":"第三十八条","txt":"本办法施行前已取得经营许可证的企业，在其经营许可证有效期内可以继续从事危险化学品经营；经营许可证有效期届满后需要继续从事危险化学品经营的，应当依照本办法的规定重新申请经营许可证。 本办法施行前取得经营许可证的非企业的单位或者个人，在其经营许可证有效期内可以继续从事危险化学品经营；经营许可证有效期届满后需要继续从事危险化学品经营的，应当先依法登记为企业，再依照本办法的规定申请经营许可证。"},{"i":39,"n":"第三十九条","txt":"经营许可证的式样由国家安全生产监督管理总局制定。"},{"i":40,"n":"第四十条","txt":"本办法自2012年9月1日起施行。原国家经济贸易委员会2002年10月8日公布的《危险化学品经营许可证管理办法》同时废止。"}],"weixianhuaxuepinshusongguandaoanquanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强危险化学品输送管道的安全管理，预防和减少危险化学品输送管道生产安全事故，保护人民群众生命财产安全，根据《中华人民共和国安全生产法》和《危险化学品安全管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"生产、储存危险化学品的单位在厂区外公共区域埋地、地面和架空的危险化学品输送管道及其附属设施（以下简称危险化学品管道）的安全管理，适用本规定。 原油、成品油、天然气、煤层气、煤制气长输管道安全保护和城镇燃气管道的安全管理，不适用本规定。"},{"i":3,"n":"第三条","txt":"对危险化学品管道享有所有权或者运行管理权的单位（以下简称管道单位）应当依照有关安全生产法律法规和本规定，落实安全生产主体责任，建立、健全有关危险化学品管道安全生产的规章制度和操作规程并实施，接受安全生产监督管理部门依法实施的监督检查。"},{"i":4,"n":"第四条","txt":"各级安全生产监督管理部门负责危险化学品管道安全生产的监督检查，并依法对危险化学品管道建设项目实施安全条件审查。"},{"i":5,"n":"第五条","txt":"任何单位和个人不得实施危害危险化学品管道安全生产的行为。 对危害危险化学品管道安全生产的行为，任何单位和个人均有权向安全生产监督管理部门举报。接受举报的安全生产监督管理部门应当依法予以处理。"},{"i":6,"n":"第六条","txt":"危险化学品管道建设应当遵循安全第一、节约用地和经济合理的原则，并按照相关国家标准、行业标准和技术规范进行科学规划。"},{"i":7,"n":"第七条","txt":"禁止光气、氯气等剧毒气体化学品管道穿（跨）越公共区域。 严格控制氨、硫化氢等其他有毒气体的危险化学品管道穿（跨）越公共区域。"},{"i":8,"n":"第八条","txt":"危险化学品管道建设的选线应当避开地震活动断层和容易发生洪灾、地质灾害的区域；确实无法避开的，应当采取可靠的工程处理措施，确保不受地质灾害影响。 危险化学品管道与居民区、学校等公共场所以及建筑物、构筑物、铁路、公路、航道、港口、市政设施、通讯设施、军事设施、电力设施的距离，应当符合有关法律、行政法规和国家标准、行业标准的规定。"},{"i":9,"n":"第九条","txt":"对新建、改建、扩建的危险化学品管道，建设单位应当依照国家安全生产监督管理总局有关危险化学品建设项目安全监督管理的规定，依法办理安全条件审查、安全设施设计审查和安全设施竣工验收手续。"},{"i":10,"n":"第十条","txt":"对新建、改建、扩建的危险化学品管道，建设单位应当依照有关法律、行政法规的规定，委托具备相应资质的设计单位进行设计。"},{"i":11,"n":"第十一条","txt":"承担危险化学品管道的施工单位应当具备有关法律、行政法规规定的相应资质。施工单位应当按照有关法律、法规、国家标准、行业标准和技术规范的规定，以及经过批准的安全设施设计进行施工，并对工程质量负责。 参加危险化学品管道焊接、防腐、无损检测作业的人员应当具备相应的操作资格证书。"},{"i":12,"n":"第十二条","txt":"负责危险化学品管道工程的监理单位应当对管道的总体建设质量进行全过程监督，并对危险化学品管道的总体建设质量负责。管道施工单位应当严格按照有关国家标准、行业标准的规定对管道的焊缝和防腐质量进行检查，并按照设计要求对管道进行压力试验和气密性试验。 对敷设在江、河、湖泊或者其他环境敏感区域的危险化学品管道，应当采取增加管道压力设计等级、增加防护套管等措施，确保危险化学品管道安全。"},{"i":13,"n":"第十三条","txt":"危险化学品管道试生产（使用）前，管道单位应当对有关保护措施进行安全检查，科学制定安全投入生产（使用）方案，并严格按照方案实施。"},{"i":14,"n":"第十四条","txt":"危险化学品管道试压半年后一直未投入生产（使用）的，管道单位应当在其投入生产（使用）前重新进行气密性试验；对敷设在江、河或者其他环境敏感区域的危险化学品管道，应当相应缩短重新进行气密性试验的时间间隔。"},{"i":15,"n":"第十五条","txt":"危险化学品管道应当设置明显标志。发现标志毁损的，管道单位应当及时予以修复或者更新。"},{"i":16,"n":"第十六条","txt":"管道单位应当建立、健全危险化学品管道巡护制度，配备专人进行日常巡护。巡护人员发现危害危险化学品管道安全生产情形的，应当立即报告单位负责人并及时处理。"},{"i":17,"n":"第十七条","txt":"管道单位对危险化学品管道存在的事故隐患应当及时排除；对自身排除确有困难的外部事故隐患，应当向当地安全生产监督管理部门报告。"},{"i":18,"n":"第十八条","txt":"管道单位应当按照有关国家标准、行业标准和技术规范对危险化学品管道进行定期检测、维护，确保其处于完好状态；对安全风险较大的区段和场所，应当进行重点监测、监控；对不符合安全标准的危险化学品管道，应当及时更新、改造或者停止使用，并向当地安全生产监督管理部门报告。对涉及更新、改造的危险化学品管道，还应当按照本办法第九条的规定办理安全条件审查手续。"},{"i":19,"n":"第十九条","txt":"管道单位发现下列危害危险化学品管道安全运行行为的，应当及时予以制止，无法处置时应当向当地安全生产监督管理部门报告： （一）擅自开启、关闭危险化学品管道阀门； （二）采用移动、切割、打孔、砸撬、拆卸等手段损坏管道及其附属设施； （三）移动、毁损、涂改管道标志； （四）在埋地管道上方和巡查便道上行驶重型车辆； （五）对埋地、地面管道进行占压，在架空管道线路和管桥上行走或者放置重物； （六）利用地面管道、架空管道、管架桥等固定其他设施缆绳悬挂广告牌、搭建构筑物； （七）其他危害危险化学品管道安全运行的行为。"},{"i":20,"n":"第二十条","txt":"禁止在危险化学品管道附属设施的上方架设电力线路、通信线路。"},{"i":21,"n":"第二十一条","txt":"在危险化学品管道及其附属设施外缘两侧各5米地域范围内，管道单位发现下列危害管道安全运行的行为的，应当及时予以制止，无法处置时应当向当地安全生产监督管理部门报告： （一）种植乔木、灌木、藤类、芦苇、竹子或者其他根系深达管道埋设部位可能损坏管道防腐层的深根植物； （二）取土、采石、用火、堆放重物、排放腐蚀性物质、使用机械工具进行挖掘施工、工程钻探； （三）挖塘、修渠、修晒场、修建水产养殖场、建温室、建家畜棚圈、建房以及修建其他建（构）筑物。"},{"i":22,"n":"第二十二条","txt":"在危险化学品管道中心线两侧及危险化学品管道附属设施外缘两侧5米外的周边范围内，管道单位发现下列建（构）筑物与管道线路、管道附属设施的距离不符合国家标准、行业标准要求的，应当及时向当地安全生产监督管理部门报告： （一）居民小区、学校、医院、餐饮娱乐场所、车站、商场等人口密集的建筑物； （二）加油站、加气站、储油罐、储气罐等易燃易爆物品的生产、经营、存储场所； （三）变电站、配电站、供水站等公用设施。"},{"i":23,"n":"第二十三条","txt":"在穿越河流的危险化学品管道线路中心线两侧500米地域范围内，管道单位发现有实施抛锚、拖锚、挖沙、采石、水下爆破等作业的，应当及时予以制止，无法处置时应当向当地安全生产监督管理部门报告。但在保障危险化学品管道安全的条件下，为防洪和航道通畅而实施的养护疏浚作业除外。"},{"i":24,"n":"第二十四条","txt":"在危险化学品管道专用隧道中心线两侧1000米地域范围内，管道单位发现有实施采石、采矿、爆破等作业的，应当及时予以制止，无法处置时应当向当地安全生产监督管理部门报告。 在前款规定的地域范围内，因修建铁路、公路、水利等公共工程确需实施采石、爆破等作业的，应当按照本规定第二十五条的规定执行。"},{"i":25,"n":"第二十五条","txt":"实施下列可能危及危险化学品管道安全运行的施工作业的，施工单位应当在开工的7日前书面通知管道单位，将施工作业方案报管道单位，并与管道单位共同制定应急预案，采取相应的安全防护措施，管道单位应当指派专人到现场进行管道安全保护指导： （一）穿（跨）越管道的施工作业； （二）在管道线路中心线两侧5米至50米和管道附属设施周边100米地域范围内，新建、改建、扩建铁路、公路、河渠，架设电力线路，埋设地下电缆、光缆，设置安全接地体、避雷接地体； （三）在管道线路中心线两侧200米和管道附属设施周边500米地域范围内，实施爆破、地震法勘探或者工程挖掘、工程钻探、采矿等作业。"},{"i":26,"n":"第二十六条","txt":"施工单位实施本规定第二十四条第二款、第二十五条规定的作业，应当符合下列条件： （一）已经制定符合危险化学品管道安全运行要求的施工作业方案； （二）已经制定应急预案； （三）施工作业人员已经接受相应的危险化学品管道保护知识教育和培训； （四）具有保障安全施工作业的设备、设施。"},{"i":27,"n":"第二十七条","txt":"危险化学品管道的专用设施、永工防护设施、专用隧道等附属设施不得用于其他用途；确需用于其他用途的，应当征得管道单位的同意，并采取相应的安全防护措施。"},{"i":28,"n":"第二十八条","txt":"管道单位应当按照有关规定制定本单位危险化学品管道事故应急预案，配备相应的应急救援人员和设备物资，定期组织应急演练。 发生危险化学品管道生产安全事故，管道单位应当立即启动应急预案及响应程序，采取有效措施进行紧急处置，消除或者减轻事故危害，并按照国家规定立即向事故发生地县级以上安全生产监督管理部门报告。"},{"i":29,"n":"第二十九条","txt":"对转产、停产、停止使用的危险化学品管道，管道单位应当采取有效措施及时妥善处置，并将处置方案报县级以上安全生产监督管理部门。"},{"i":30,"n":"第三十条","txt":"省级、设区的市级安全生产监督管理部门应当按照国家安全生产监督管理总局有关危险化学品建设项目安全监督管理的规定，对新建、改建、扩建管道建设项目办理安全条件审查、安全设施设计审查、试生产（使用）方案备案和安全设施竣工验收手续。"},{"i":31,"n":"第三十一条","txt":"安全生产监督管理部门接到管道单位依照本规定第十七条、第十九条、第二十一条、第二十二条、第二十三条、第二十四条提交的有关报告后，应当及时依法予以协调、移送有关主管部门处理或者报请本级人民政府组织处理。"},{"i":32,"n":"第三十二条","txt":"县级以上安全生产监督管理部门接到危险化学品管道生产安全事故报告后，应当按照有关规定及时上报事故情况，并根据实际情况采取事故处置措施。"},{"i":33,"n":"第三十三条","txt":"新建、改建、扩建危险化学品管道建设项目未经安全条件审查的，由安全生产监督管理部门责令停止建设，限期改正；逾期不改正的，处50万元以上100万元以下的罚款；构成犯罪的，依法追究刑事责任。 危险化学品管道建设单位将管道建设项目发包给不具备相应资质等级的勘察、设计、施工单位或者委托给不具有相应资质等级的工程监理单位的，由安全生产监督管理部门移送建设行政主管部门依照《建设工程质量管理条例》第五十四条规定予以处罚。"},{"i":34,"n":"第三十四条","txt":"管道单位未对危险化学品管道设置明显的安全警示标志的，由安全生产监督管理部门责令限期改正，可以处5万元以下的罚款；逾期未改正的，处5万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，由安全生产监督管理部门责令改正，可以处5万元以下的罚款；拒不改正的，处5万元以上10万元以下的罚款；情节严重的，责令停产停业整顿。 （一）管道单位未按照本规定对管道进行检测、维护的； （二）进行可能危及危险化学品管道安全的施工作业，施工单位未按照规定书面通知管道单位，或者未与管道单位共同制定应急预案并采取相应的防护措施，或者管道单位未指派专人到现场进行管道安全保护指导的。"},{"i":36,"n":"第三十六条","txt":"对转产、停产、停止使用的危险化学品管道，管道单位未采取有效措施及时、妥善处置的，由安全生产监督管理部门责令改正，处5万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。 对转产、停产、停止使用的危险化学品管道，管道单位未按照本规定将处置方案报县级以上安全生产监督管理部门的，由安全生产监督管理部门责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本规定，采用移动、切割、打孔、砸撬、拆卸等手段实施危害危险化学品管道安全行为，尚不构成犯罪的，由有关主管部门依法给予治安管理处罚。"},{"i":38,"n":"第三十八条","txt":"本规定所称公共区域是指厂区（包括化工园区、工业园区）以外的区域。"},{"i":39,"n":"第三十九条","txt":"本规定所称危险化学品管道附属设施包括： （一）管道的加压站、计量站、阀室、阀井、放空设施、储罐、装卸栈桥、装卸场、分输站、减压站等站场； （二）管道的水工保护设施、防风设施、防雷设施、抗震设施、通信设施、安全监控设施、电力设施、管堤、管桥以及管道专用涵洞、隧道等穿跨越设施； （三）管道的阴极保护站、阴极保护测试桩、阳极地床、杂散电流排流站等防腐设施； （四）管道的其他附属设施。"},{"i":40,"n":"第四十条","txt":"本规定施行前在管道保护距离内已经建成的人口密集场所和易燃易爆物品的生产、经营、存储场所，应当由所在地人民政府根据当地的实际情况，有计划、分步骤地搬迁、清理或者采取必要的防护措施。"},{"i":41,"n":"第四十一条","txt":"本规定自2012年3月1日起施行。"}],"weixianhuaxuepinzhongdaweixianyuanjianduguanlizanx5cb4f3":[{"i":1,"n":"第一条","txt":"为了加强危险化学品重大危险源的安全监督管理，防止和减少危险化学品事故的发生，保障人民群众生命财产安全，根据《中华人民共和国安全生产法》和《危险化学品安全管理条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"从事危险化学品生产、储存、使用和经营的单位（以下统称危险化学品单位）的危险化学品重大危险源的辨识、评估、登记建档、备案、核销及其监督管理，适用本规定。 城镇燃气、用于国防科研生产的危险化学品重大危险源以及港区内危险化学品重大危险源的安全监督管理，不适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称危险化学品重大危险源（以下简称重大危险源），是指按照《危险化学品重大危险源辨识》（GB18218）标准辨识确定，生产、储存、使用或者搬运危险化学品的数量等于或者超过临界量的单元（包括场所和设施）。"},{"i":4,"n":"第四条","txt":"危险化学品单位是本单位重大危险源安全管理的责任主体，其主要负责人对本单位的重大危险源安全管理工作负责，并保证重大危险源安全生产所必需的安全投入。"},{"i":5,"n":"第五条","txt":"重大危险源的安全监督管理实行属地监管与分级管理相结合的原则。 县级以上地方人民政府安全生产监督管理部门按照有关法律、法规、标准和本规定，对本辖区内的重大危险源实施安全监督管理。"},{"i":6,"n":"第六条","txt":"国家鼓励危险化学品单位采用有利于提高重大危险源安全保障水平的先进适用的工艺、技术、设备以及自动控制系统，推进安全生产监督管理部门重大危险源安全监管的信息化建设。"},{"i":7,"n":"第七条","txt":"危险化学品单位应当按照《危险化学品重大危险源辨识》标准，对本单位的危险化学品生产、经营、储存和使用装置、设施或者场所进行重大危险源辨识，并记录辨识过程与结果。"},{"i":8,"n":"第八条","txt":"危险化学品单位应当对重大危险源进行安全评估并确定重大危险源等级。危险化学品单位可以组织本单位的注册安全工程师、技术人员或者聘请有关专家进行安全评估，也可以委托具有相应资质的安全评价机构进行安全评估。 依照法律、行政法规的规定，危险化学品单位需要进行安全评价的，重大危险源安全评估可以与本单位的安全评价一起进行，以安全评价报告代替安全评估报告，也可以单独进行重大危险源安全评估。 重大危险源根据其危险程度，分为一级、二级、三级和四级，一级为最高级别。重大危险源分级方法由本规定附件1列示。"},{"i":9,"n":"第九条","txt":"重大危险源有下列情形之一的，应当委托具有相应资质的安全评价机构，按照有关标准的规定采用定量风险评价方法进行安全评估，确定个人和社会风险值： （一）构成一级或者二级重大危险源，且毒性气体实际存在（在线）量与其在《危险化学品重大危险源辨识》中规定的临界量比值之和大于或等于1的； （二）构成一级重大危险源，且爆炸品或液化易燃气体实际存在（在线）量与其在《危险化学品重大危险源辨识》中规定的临界量比值之和大于或等于1的。"},{"i":10,"n":"第十条","txt":"重大危险源安全评估报告应当客观公正、数据准确、内容完整、结论明确、措施可行，并包括下列内容： （一）评估的主要依据； （二）重大危险源的基本情况； （三）事故发生的可能性及危害程度； （四）个人风险和社会风险值（仅适用定量风险评价方法）； （五）可能受事故影响的周边场所、人员情况； （六）重大危险源辨识、分级的符合性分析； （七）安全管理措施、安全技术和监控措施； （八）事故应急措施； （九）评估结论与建议。 危险化学品单位以安全评价报告代替安全评估报告的，其安全评价报告中有关重大危险源的内容应当符合本条第一款规定的要求。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，危险化学品单位应当对重大危险源重新进行辨识、安全评估及分级： （一）重大危险源安全评估已满三年的； （二）构成重大危险源的装置、设施或者场所进行新建、改建、扩建的； （三）危险化学品种类、数量、生产、使用工艺或者储存方式及重要设备、设施等发生变化，影响重大危险源级别或者风险程度的； （四）外界生产安全环境因素发生变化，影响重大危险源级别和风险程度的； （五）发生危险化学品事故造成人员死亡，或者10人以上受伤，或者影响到公共安全的； （六）有关重大危险源辨识和安全评估的国家标准、行业标准发生变化的。"},{"i":12,"n":"第十二条","txt":"危险化学品单位应当建立完善重大危险源安全管理规章制度和安全操作规程，并采取有效措施保证其得到执行。"},{"i":13,"n":"第十三条","txt":"危险化学品单位应当根据构成重大危险源的危险化学品种类、数量、生产、使用工艺（方式）或者相关设备、设施等实际情况，按照下列要求建立健全安全监测监控体系，完善控制措施： （一）重大危险源配备温度、压力、液位、流量、组份等信息的不间断采集和监测系统以及可燃气体和有毒有害气体泄漏检测报警装置，并具备信息远传、连续记录、事故预警、信息存储等功能；一级或者二级重大危险源，具备紧急停车功能。记录的电子数据的保存时间不少于30天； （二）重大危险源的化工生产装置装备满足安全生产要求的自动化控制系统；一级或者二级重大危险源，装备紧急停车系统； （三）对重大危险源中的毒性气体、剧毒液体和易燃气体等重点设施，设置紧急切断装置；毒性气体的设施，设置泄漏物紧急处置装置。涉及毒性气体、液化气体、剧毒液体的一级或者二级重大危险源，配备独立的安全仪表系统（SIS）； （四）重大危险源中储存剧毒物质的场所或者设施，设置"},{"i":14,"n":"第十四条","txt":"通过定量风险评价确定的重大危险源的个人和社会风险值，不得超过本规定附件2列示的个人和社会可容许风险限值标准。 超过个人和社会可容许风险限值标准的，危险化学品单位应当采取相应的降低风险措施。"},{"i":15,"n":"第十五条","txt":"危险化学品单位应当按照国家有关规定，定期对重大危险源的安全设施和安全监测监控系统进行检测、检验，并进行经常性维护、保养，保证重大危险源的安全设施和安全监测监控系统有效、可靠运行。维护、保养、检测应当作好记录，并由有关人员签字。"},{"i":16,"n":"第十六条","txt":"危险化学品单位应当明确重大危险源中关键装置、重点部位的责任人或者责任机构，并对重大危险源的安全生产状况进行定期检查，及时采取措施消除事故隐患。事故隐患难以立即排除的，应当及时制定治理方案，落实整改措施、责任、资金、时限和预案。"},{"i":17,"n":"第十七条","txt":"危险化学品单位应当对重大危险源的管理和操作岗位人员进行安全操作技能培训，使其了解重大危险源的危险特性，熟悉重大危险源安全管理规章制度和安全操作规程，掌握本岗位的安全操作技能和应急措施。"},{"i":18,"n":"第十八条","txt":"危险化学品单位应当在重大危险源所在场所设置明显的安全警示标志，写明紧急情况下的应急处置办法。"},{"i":19,"n":"第十九条","txt":"危险化学品单位应当将重大危险源可能发生的事故后果和应急措施等信息，以适当方式告知可能受影响的单位、区域及人员。"},{"i":20,"n":"第二十条","txt":"危险化学品单位应当依法制定重大危险源事故应急预案，建立应急救援组织或者配备应急救援人员，配备必要的防护装备及应急救援器材、设备、物资，并保障其完好和方便使用；配合地方人民政府安全生产监督管理部门制定所在地区涉及本单位的危险化学品事故应急预案。 对存在吸入性有毒、有害气体的重大危险源，危险化学品单位应当配备便携式浓度检测设备、空气呼吸器、化学防护服、堵漏器材等应急器材和设备；涉及剧毒气体的重大危险源，还应当配备两套以上（含本数）气密型化学防护服；涉及易燃易爆气体或者易燃液体蒸气的重大危险源，还应当配备一定数量的便携式可燃气体检测设备。"},{"i":21,"n":"第二十一条","txt":"危险化学品单位应当制定重大危险源事故应急预案演练计划，并按照下列要求进行事故应急预案演练： （一）对重大危险源专项应急预案，每年至少进行一次； （二）对重大危险源现场处置方案，每半年至少进行一次。 应急预案演练结束后，危险化学品单位应当对应急预案演练效果进行评估，撰写应急预案演练评估报告，分析存在的问题，对应急预案提出修订意见，并及时修订完善。"},{"i":22,"n":"第二十二条","txt":"危险化学品单位应当对辨识确认的重大危险源及时、逐项进行登记建档。 重大危险源档案应当包括下列文件、资料： （一）辨识、分级记录； （二）重大危险源基本特征表； （三）涉及的所有化学品安全技术说明书； （四）区域位置图、平面布置图、工艺流程图和主要设备一览表； （五）重大危险源安全管理规章制度及安全操作规程； （六）安全监测监控系统、措施说明、检测、检验结果； （七）重大危险源事故应急预案、评审意见、演练计划和评估报告； （八）安全评估报告或者安全评价报告； （九）重大危险源关键装置、重点部位的责任人、责任机构名称； （十）重大危险源场所安全警示标志的设置情况； （十一）其他文件、资料。"},{"i":23,"n":"第二十三条","txt":"危险化学品单位在完成重大危险源安全评估报告或者安全评价报告后15日内，应当填写重大危险源备案申请表，连同本规定第二十二条规定的重大危险源档案材料（其中第二款第五项规定的文件资料只需提供清单），报送所在地县级人民政府安全生产监督管理部门备案。 县级人民政府安全生产监督管理部门应当每季度将辖区内的一级、二级重大危险源备案材料报送至设区的市级人民政府安全生产监督管理部门。设区的市级人民政府安全生产监督管理部门应当每半年将辖区内的一级重大危险源备案材料报送至省级人民政府安全生产监督管理部门。 重大危险源出现本规定第十一条所列情形之一的，危险化学品单位应当及时更新档案，并向所在地县级人民政府安全生产监督管理部门重新备案。"},{"i":24,"n":"第二十四条","txt":"危险化学品单位新建、改建和扩建危险化学品建设项目，应当在建设项目竣工验收前完成重大危险源的辨识、安全评估和分级、登记建档工作，并向所在地县级人民政府安全生产监督管理部门备案。"},{"i":25,"n":"第二十五条","txt":"县级人民政府安全生产监督管理部门应当建立健全危险化学品重大危险源管理制度，明确责任人员，加强资料归档。"},{"i":26,"n":"第二十六条","txt":"县级人民政府安全生产监督管理部门应当在每年1月15日前，将辖区内上一年度重大危险源的汇总信息报送至设区的市级人民政府安全生产监督管理部门。设区的市级人民政府安全生产监督管理部门应当在每年1月31日前，将辖区内上一年度重大危险源的汇总信息报送至省级人民政府安全生产监督管理部门。省级人民政府安全生产监督管理部门应当在每年2月15日前，将辖区内上一年度重大危险源的汇总信息报送至国家安全生产监督管理总局。"},{"i":27,"n":"第二十七条","txt":"重大危险源经过安全评价或者安全评估不再构成重大危险源的，危险化学品单位应当向所在地县级人民政府安全生产监督管理部门申请核销。 申请核销重大危险源应当提交下列文件、资料： （一）载明核销理由的申请书； （二）单位名称、法定代表人、住所、联系人、联系方式； （三）安全评价报告或者安全评估报告。"},{"i":28,"n":"第二十八条","txt":"县级人民政府安全生产监督管理部门应当自收到申请核销的文件、资料之日起30日内进行审查，符合条件的，予以核销并出具证明文书；不符合条件的，说明理由并书面告知申请单位。必要时，县级人民政府安全生产监督管理部门应当聘请有关专家进行现场核查。"},{"i":29,"n":"第二十九条","txt":"县级人民政府安全生产监督管理部门应当每季度将辖区内一级、二级重大危险源的核销材料报送至设区的市级人民政府安全生产监督管理部门。设区的市级人民政府安全生产监督管理部门应当每半年将辖区内一级重大危险源的核销材料报送至省级人民政府安全生产监督管理部门。"},{"i":30,"n":"第三十条","txt":"县级以上地方各级人民政府安全生产监督管理部门应当加强对存在重大危险源的危险化学品单位的监督检查，督促危险化学品单位做好重大危险源的辨识、安全评估及分级、登记建档、备案、监测监控、事故应急预案编制、核销和安全管理工作。 首次对重大危险源的监督检查应当包括下列主要内容： （一）重大危险源的运行情况、安全管理规章制度及安全操作规程制定和落实情况； （二）重大危险源的辨识、分级、安全评估、登记建档、备案情况； （三）重大危险源的监测监控情况； （四）重大危险源安全设施和安全监测监控系统的检测、检验以及维护保养情况； （五）重大危险源事故应急预案的编制、评审、备案、修订和演练情况； （六）有关从业人员的安全培训教育情况； （七）安全标志设置情况； （八）应急救援器材、设备、物资配备情况； （九）预防和控制事故措施的落实情况。 安全生产监督管理部门在监督检查中发现重大危险源存在事故隐患的，应当责令"},{"i":31,"n":"第三十一条","txt":"县级以上地方各级人民政府安全生产监督管理部门应当会同本级人民政府有关部门，加强对工业（化工）园区等重大危险源集中区域的监督检查，确保重大危险源与周边单位、居民区、人员密集场所等重要目标和敏感场所之间保持适当的安全距离。"},{"i":32,"n":"第三十二条","txt":"危险化学品单位有下列行为之一的，由县级以上人民政府安全生产监督管理部门责令限期改正，可以处10万元以下的罚款；逾期未改正的，责令停产停业整顿，并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未按照本规定要求对重大危险源进行安全评估或者安全评价的； （二）未按照本规定要求对重大危险源进行登记建档的； （三）未按照本规定及相关标准要求对重大危险源进行安全监测监控的； （四）未制定重大危险源事故应急预案的。"},{"i":33,"n":"第三十三条","txt":"危险化学品单位有下列行为之一的，由县级以上人民政府安全生产监督管理部门责令限期改正，可以处5万元以下的罚款；逾期未改正的，处5万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未在构成重大危险源的场所设置明显的安全警示标志的； （二）未对重大危险源中的设备、设施等进行定期检测、检验的。"},{"i":34,"n":"第三十四条","txt":"危险化学品单位有下列情形之一的，由县级以上人民政府安全生产监督管理部门给予警告，可以并处5000元以上3万元以下的罚款： （一）未按照标准对重大危险源进行辨识的； （二）未按照本规定明确重大危险源中关键装置、重点部位的责任人或者责任机构的； （三）未按照本规定建立应急救援组织或者配备应急救援人员，以及配备必要的防护装备及器材、设备、物资，并保障其完好的； （四）未按照本规定进行重大危险源备案或者核销的； （五）未将重大危险源可能引发的事故后果、应急措施等信息告知可能受影响的单位、区域及人员的； （六）未按照本规定要求开展重大危险源事故应急预案演练的。"},{"i":35,"n":"第三十五条","txt":"危险化学品单位未按照本规定对重大危险源的安全生产状况进行定期检查，采取措施消除事故隐患的，责令立即消除或者限期消除；危险化学品单位拒不执行的，责令停产停业整顿，并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"承担检测、检验、安全评价工作的机构，出具虚假证明的，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与危险化学品单位承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构，依法吊销其相应资质。"},{"i":37,"n":"第三十七条","txt":"本规定自2011年12月1日起施行。 附件：1．危险化学品重大危险源分级方法 2．可容许风险标准"}],"anquanshengchanshiguyinhuanpaichazhilizanxingguidi9ce7f1":[{"i":1,"n":"第一条","txt":"为了建立安全生产事故隐患排查治理长效机制，强化安全生产主体责任，加强事故隐患监督管理，防止和减少事故，保障人民群众生命财产安全，根据安全生产法等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"生产经营单位安全生产事故隐患排查治理和安全生产监督管理部门、煤矿安全监察机构（以下统称安全监管监察部门）实施监管监察，适用本规定。 有关法律、行政法规对安全生产事故隐患排查治理另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"本规定所称安全生产事故隐患（以下简称事故隐患），是指生产经营单位违反安全生产法律、法规、规章、标准、规程和安全生产管理制度的规定，或者因其他因素在生产经营活动中存在可能导致事故发生的物的危险状态、人的不安全行为和管理上的缺陷。 事故隐患分为一般事故隐患和重大事故隐患。一般事故隐患，是指危害和整改难度较小，发现后能够立即整改排除的隐患。重大事故隐患，是指危害和整改难度较大，应当全部或者局部停产停业，并经过一定时间整改治理方能排除的隐患，或者因外部因素影响致使生产经营单位自身难以排除的隐患。"},{"i":4,"n":"第四条","txt":"生产经营单位应当建立健全事故隐患排查治理制度。 生产经营单位主要负责人对本单位事故隐患排查治理工作全面负责。"},{"i":5,"n":"第五条","txt":"各级安全监管监察部门按照职责对所辖区域内生产经营单位排查治理事故隐患工作依法实施综合监督管理；各级人民政府有关部门在各自职责范围内对生产经营单位排查治理事故隐患工作依法实施监督管理。"},{"i":6,"n":"第六条","txt":"任何单位和个人发现事故隐患，均有权向安全监管监察部门和有关部门报告。 安全监管监察部门接到事故隐患报告后，应当按照职责分工立即组织核实并予以查处；发现所报告事故隐患应当由其他有关部门处理的，应当立即移送有关部门并记录备查。"},{"i":7,"n":"第七条","txt":"生产经营单位应当依照法律、法规、规章、标准和规程的要求从事生产经营活动。严禁非法从事生产经营活动。"},{"i":8,"n":"第八条","txt":"生产经营单位是事故隐患排查、治理和防控的责任主体。 生产经营单位应当建立健全事故隐患排查治理和建档监控等制度，逐级建立并落实从主要负责人到每个从业人员的隐患排查治理和监控责任制。"},{"i":9,"n":"第九条","txt":"生产经营单位应当保证事故隐患排查治理所需的资金，建立资金使用专项制度。"},{"i":10,"n":"第十条","txt":"生产经营单位应当定期组织安全生产管理人员、工程技术人员和其他相关人员排查本单位的事故隐患。对排查出的事故隐患，应当按照事故隐患的等级进行登记，建立事故隐患信息档案，并按照职责分工实施监控治理。"},{"i":11,"n":"第十一条","txt":"生产经营单位应当建立事故隐患报告和举报奖励制度，鼓励、发动职工发现和排除事故隐患，鼓励社会公众举报。对发现、排除和举报事故隐患的有功人员，应当给予物质奖励和表彰。"},{"i":12,"n":"第十二条","txt":"生产经营单位将生产经营项目、场所、设备发包、出租的，应当与承包、承租单位签订安全生产管理协议，并在协议中明确各方对事故隐患排查、治理和防控的管理职责。生产经营单位对承包、承租单位的事故隐患排查治理负有统一协调和监督管理的职责。"},{"i":13,"n":"第十三条","txt":"安全监管监察部门和有关部门的监督检查人员依法履行事故隐患监督检查职责时，生产经营单位应当积极配合，不得拒绝和阻挠。"},{"i":14,"n":"第十四条","txt":"生产经营单位应当每季、每年对本单位事故隐患排查治理情况进行统计分析，并分别于下一季度15日前和下一年1月31日前向安全监管监察部门和有关部门报送书面统计分析表。统计分析表应当由生产经营单位主要负责人签字。 对于重大事故隐患，生产经营单位除依照前款规定报送外，应当及时向安全监管监察部门和有关部门报告。重大事故隐患报告内容应当包括： （一）隐患的现状及其产生原因； （二）隐患的危害程度和整改难易程度分析； （三）隐患的治理方案。"},{"i":15,"n":"第十五条","txt":"对于一般事故隐患，由生产经营单位（车间、分厂、区队等）负责人或者有关人员立即组织整改。 对于重大事故隐患，由生产经营单位主要负责人组织制定并实施事故隐患治理方案。重大事故隐患治理方案应当包括以下内容： （一）治理的目标和任务； （二）采取的方法和措施； （三）经费和物资的落实； （四）负责治理的机构和人员； （五）治理的时限和要求； （六）安全措施和应急预案。"},{"i":16,"n":"第十六条","txt":"生产经营单位在事故隐患治理过程中，应当采取相应的安全防范措施，防止事故发生。事故隐患排除前或者排除过程中无法保证安全的，应当从危险区域内撤出作业人员，并疏散可能危及的其他人员，设置警戒标志，暂时停产停业或者停止使用；对暂时难以停产或者停止使用的相关生产储存装置、设施、设备，应当加强维护和保养，防止事故发生。"},{"i":17,"n":"第十七条","txt":"生产经营单位应当加强对自然灾害的预防。对于因自然灾害可能导致事故灾难的隐患，应当按照有关法律、法规、标准和本规定的要求排查治理，采取可靠的预防措施，制定应急预案。在接到有关自然灾害预报时，应当及时向下属单位发出预警通知；发生自然灾害可能危及生产经营单位和人员安全的情况时，应当采取撤离人员、停止作业、加强监测等安全措施，并及时向当地人民政府及其有关部门报告。"},{"i":18,"n":"第十八条","txt":"地方人民政府或者安全监管监察部门及有关部门挂牌督办并责令全部或者局部停产停业治理的重大事故隐患，治理工作结束后，有条件的生产经营单位应当组织本单位的技术人员和专家对重大事故隐患的治理情况进行评估；其他生产经营单位应当委托具备相应资质的安全评价机构对重大事故隐患的治理情况进行评估。 经治理后符合安全生产条件的，生产经营单位应当向安全监管监察部门和有关部门提出恢复生产的书面申请，经安全监管监察部门和有关部门审查同意后，方可恢复生产经营。申请报告应当包括治理方案的内容、项目和安全评价机构出具的评价报告等。"},{"i":19,"n":"第十九条","txt":"安全监管监察部门应当指导、监督生产经营单位按照有关法律、法规、规章、标准和规程的要求，建立健全事故隐患排查治理等各项制度。"},{"i":20,"n":"第二十条","txt":"安全监管监察部门应当建立事故隐患排查治理监督检查制度，定期组织对生产经营单位事故隐患排查治理情况开展监督检查；应当加强对重点单位的事故隐患排查治理情况的监督检查。对检查过程中发现的重大事故隐患，应当下达整改指令书，并建立信息管理台账。必要时，报告同级人民政府并对重大事故隐患实行挂牌督办。 安全监管监察部门应当配合有关部门做好对生产经营单位事故隐患排查治理情况开展的监督检查，依法查处事故隐患排查治理的非法和违法行为及其责任者。 安全监管监察部门发现属于其他有关部门职责范围内的重大事故隐患的，应该及时将有关资料移送有管辖权的有关部门，并记录备查。"},{"i":21,"n":"第二十一条","txt":"已经取得安全生产许可证的生产经营单位，在其被挂牌督办的重大事故隐患治理结束前，安全监管监察部门应当加强监督检查。必要时，可以提请原许可证颁发机关依法暂扣其安全生产许可证。"},{"i":22,"n":"第二十二条","txt":"安全监管监察部门应当会同有关部门把重大事故隐患整改纳入重点行业领域的安全专项整治中加以治理，落实相应责任。"},{"i":23,"n":"第二十三条","txt":"对挂牌督办并采取全部或者局部停产停业治理的重大事故隐患，安全监管监察部门收到生产经营单位恢复生产的申请报告后，应当在10日内进行现场审查。审查合格的，对事故隐患进行核销，同意恢复生产经营；审查不合格的，依法责令改正或者下达停产整改指令。对整改无望或者生产经营单位拒不执行整改指令的，依法实施行政处罚；不具备安全生产条件的，依法提请县级以上人民政府按照国务院规定的权限予以关闭。"},{"i":24,"n":"第二十四条","txt":"安全监管监察部门应当每季将本行政区域重大事故隐患的排查治理情况和统计分析表逐级报至省级安全监管监察部门备案。 省级安全监管监察部门应当每半年将本行政区域重大事故隐患的排查治理情况和统计分析表报国家安全生产监督管理总局备案。"},{"i":25,"n":"第二十五条","txt":"生产经营单位及其主要负责人未履行事故隐患排查治理职责，导致发生生产安全事故的，依法给予行政处罚。"},{"i":26,"n":"第二十六条","txt":"生产经营单位违反本规定，有下列行为之一的，由安全监管监察部门给予警告，并处三万元以下的罚款： （一）未建立安全生产事故隐患排查治理等各项制度的； （二）未按规定上报事故隐患排查治理统计分析表的； （三）未制定事故隐患治理方案的； （四）重大事故隐患不报或者未及时报告的； （五）未对事故隐患进行排查治理擅自生产经营的； （六）整改不合格或者未经安全监管监察部门审查同意擅自恢复生产经营的。"},{"i":27,"n":"第二十七条","txt":"承担检测检验、安全评价的中介机构，出具虚假评价证明，尚不够刑事处罚的，没收违法所得，违法所得在五千元以上的，并处违法所得二倍以上五倍以下的罚款，没有违法所得或者违法所得不足五千元的，单处或者并处五千元以上二万元以下的罚款，同时可对其直接负责的主管人员和其他直接责任人员处五千元以上五万元以下的罚款；给他人造成损害的，与生产经营单位承担连带赔偿责任。 对有前款违法行为的机构，撤销其相应的资质。"},{"i":28,"n":"第二十八条","txt":"生产经营单位事故隐患排查治理过程中违反有关安全生产法律、法规、规章、标准和规程规定的，依法给予行政处罚。"},{"i":29,"n":"第二十九条","txt":"安全监管监察部门的工作人员未依法履行职责的，按照有关规定处理。"},{"i":30,"n":"第三十条","txt":"省级安全监管监察部门可以根据本规定，制定事故隐患排查治理和监督管理实施细则。"},{"i":31,"n":"第三十一条","txt":"事业单位、人民团体以及其他经济组织的事故隐患排查治理，参照本规定执行。"},{"i":32,"n":"第三十二条","txt":"本规定自2008年2月1日起施行。"}],"anquanshengchanpeixunguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强安全生产培训管理，规范安全生产培训秩序，保证安全生产培训质量，促进安全生产培训工作健康发展，根据《中华人民共和国安全生产法》和有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"安全培训机构、生产经营单位从事安全生产培训（以下简称安全培训）活动以及安全生产监督管理部门、煤矿安全监察机构、地方人民政府负责煤矿安全培训的部门对安全培训工作实施监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称安全培训是指以提高安全监管监察人员、生产经营单位从业人员和从事安全生产工作的相关人员的安全素质为目的的教育培训活动。 前款所称安全监管监察人员是指县级以上各级人民政府安全生产监督管理部门、各级煤矿安全监察机构从事安全监管监察、行政执法的安全生产监管人员和煤矿安全监察人员；生产经营单位从业人员是指生产经营单位主要负责人、安全生产管理人员、特种作业人员及其他从业人员；从事安全生产工作的相关人员是指从事安全教育培训工作的教师、危险化学品登记机构的登记人员和承担安全评价、咨询、检测、检验的人员及注册安全工程师、安全生产应急救援人员等。"},{"i":4,"n":"第四条","txt":"安全培训工作实行统一规划、归口管理、分级实施、分类指导、教考分离的原则。 国家安全生产监督管理总局（以下简称国家安全监管总局）指导全国安全培训工作，依法对全国的安全培训工作实施监督管理。 国家煤矿安全监察局（以下简称国家煤矿安监局）指导全国煤矿安全培训工作，依法对全国煤矿安全培训工作实施监督管理。 国家安全生产应急救援指挥中心指导全国安全生产应急救援培训工作。 县级以上地方各级人民政府安全生产监督管理部门依法对本行政区域内的安全培训工作实施监督管理。 省、自治区、直辖市人民政府负责煤矿安全培训的部门、省级煤矿安全监察机构（以下统称省级煤矿安全培训监管机构）按照各自工作职责，依法对所辖区域煤矿安全培训工作实施监督管理。"},{"i":5,"n":"第五条","txt":"安全培训的机构应当具备从事安全培训工作所需要的条件。从事危险物品的生产、经营、储存单位以及矿山、金属冶炼单位的主要负责人和安全生产管理人员，特种作业人员以及注册安全工程师等相关人员培训的安全培训机构，应当将教师、教学和实习实训设施等情况书面报告所在地安全生产监督管理部门、煤矿安全培训监管机构。 安全生产相关社会组织依照法律、行政法规和章程，为生产经营单位提供安全培训有关服务，对安全培训机构实行自律管理，促进安全培训工作水平的提升。"},{"i":6,"n":"第六条","txt":"安全培训应当按照规定的安全培训大纲进行。 安全监管监察人员，危险物品的生产、经营、储存单位与非煤矿山、金属冶炼单位的主要负责人和安全生产管理人员、特种作业人员以及从事安全生产工作的相关人员的安全培训大纲，由国家安全监管总局组织制定。 煤矿企业的主要负责人和安全生产管理人员、特种作业人员的培训大纲由国家煤矿安监局组织制定。 除危险物品的生产、经营、储存单位和矿山、金属冶炼单位以外其他生产经营单位的主要负责人、安全生产管理人员及其他从业人员的安全培训大纲，由省级安全生产监督管理部门、省级煤矿安全培训监管机构组织制定。"},{"i":7,"n":"第七条","txt":"国家安全监管总局、省级安全生产监督管理部门定期组织优秀安全培训教材的评选。 安全培训机构应当优先使用优秀安全培训教材。"},{"i":8,"n":"第八条","txt":"国家安全监管总局负责省级以上安全生产监督管理部门的安全生产监管人员、各级煤矿安全监察机构的煤矿安全监察人员的培训工作。 省级安全生产监督管理部门负责市级、县级安全生产监督管理部门的安全生产监管人员的培训工作。 生产经营单位的从业人员的安全培训，由生产经营单位负责。 危险化学品登记机构的登记人员和承担安全评价、咨询、检测、检验的人员及注册安全工程师、安全生产应急救援人员的安全培训，按照有关法律、法规、规章的规定进行。"},{"i":9,"n":"第九条","txt":"对从业人员的安全培训，具备安全培训条件的生产经营单位应当以自主培训为主，也可以委托具备安全培训条件的机构进行安全培训。 不具备安全培训条件的生产经营单位，应当委托具有安全培训条件的机构对从业人员进行安全培训。 生产经营单位委托其他机构进行安全培训的，保证安全培训的责任仍由本单位负责。"},{"i":10,"n":"第十条","txt":"生产经营单位应当建立安全培训管理制度，保障从业人员安全培训所需经费，对从业人员进行与其所从事岗位相应的安全教育培训；从业人员调整工作岗位或者采用新工艺、新技术、新设备、新材料的，应当对其进行专门的安全教育和培训。未经安全教育和培训合格的从业人员，不得上岗作业。 生产经营单位使用被派遣劳动者的，应当将被派遣劳动者纳入本单位从业人员统一管理，对被派遣劳动者进行岗位安全操作规程和安全操作技能的教育和培训。劳务派遣单位应当对被派遣劳动者进行必要的安全生产教育和培训。 生产经营单位接收中等职业学校、高等学校学生实习的，应当对实习学生进行相应的安全生产教育和培训，提供必要的劳动防护用品。学校应当协助生产经营单位对实习学生进行安全生产教育和培训。 从业人员安全培训的时间、内容、参加人员以及考核结果等情况，生产经营单位应当如实记录并建档备查。"},{"i":11,"n":"第十一条","txt":"生产经营单位从业人员的培训内容和培训时间，应当符合《生产经营单位安全培训规定》和有关标准的规定。"},{"i":12,"n":"第十二条","txt":"中央企业的分公司、子公司及其所属单位和其他生产经营单位，发生造成人员死亡的生产安全事故的，其主要负责人和安全生产管理人员应当重新参加安全培训。 特种作业人员对造成人员死亡的生产安全事故负有直接责任的，应当按照《特种作业人员安全技术培训考核管理规定》重新参加安全培训。"},{"i":13,"n":"第十三条","txt":"国家鼓励生产经营单位实行师傅带徒弟制度。 矿山新招的井下作业人员和危险物品生产经营单位新招的危险工艺操作岗位人员，除按照规定进行安全培训外，还应当在有经验的职工带领下实习满2个月后，方可独立上岗作业。"},{"i":14,"n":"第十四条","txt":"国家鼓励生产经营单位招录职业院校毕业生。 职业院校毕业生从事与所学专业相关的作业，可以免予参加初次培训，实际操作培训除外。"},{"i":15,"n":"第十五条","txt":"安全培训机构应当建立安全培训工作制度和人员培训档案。安全培训相关情况，应当如实记录并建档备查。"},{"i":16,"n":"第十六条","txt":"安全培训机构从事安全培训工作的收费，应当符合法律、法规的规定。法律、法规没有规定的，应当按照行业自律标准或者指导性标准收费。"},{"i":17,"n":"第十七条","txt":"国家鼓励安全培训机构和生产经营单位利用现代信息技术开展安全培训，包括远程培训。"},{"i":18,"n":"第十八条","txt":"安全监管监察人员、从事安全生产工作的相关人员、依照有关法律法规应当接受安全生产知识和管理能力考核的生产经营单位主要负责人和安全生产管理人员、特种作业人员的安全培训的考核，应当坚持教考分离、统一标准、统一题库、分级负责的原则，分步推行有远程视频监控的计算机考试。"},{"i":19,"n":"第十九条","txt":"安全监管监察人员，危险物品的生产、经营、储存单位及非煤矿山、金属冶炼单位主要负责人、安全生产管理人员和特种作业人员，以及从事安全生产工作的相关人员的考核标准，由国家安全监管总局统一制定。 煤矿企业的主要负责人、安全生产管理人员和特种作业人员的考核标准，由国家煤矿安监局制定。 除危险物品的生产、经营、储存单位和矿山、金属冶炼单位以外其他生产经营单位主要负责人、安全生产管理人员及其他从业人员的考核标准，由省级安全生产监督管理部门制定。"},{"i":20,"n":"第二十条","txt":"国家安全监管总局负责省级以上安全生产监督管理部门的安全生产监管人员、各级煤矿安全监察机构的煤矿安全监察人员的考核；负责中央企业的总公司、总厂或者集团公司的主要负责人和安全生产管理人员的考核。 省级安全生产监督管理部门负责市级、县级安全生产监督管理部门的安全生产监管人员的考核；负责省属生产经营单位和中央企业分公司、子公司及其所属单位的主要负责人和安全生产管理人员的考核；负责特种作业人员的考核。 市级安全生产监督管理部门负责本行政区域内除中央企业、省属生产经营单位以外的其他生产经营单位的主要负责人和安全生产管理人员的考核。 省级煤矿安全培训监管机构负责所辖区域内煤矿企业的主要负责人、安全生产管理人员和特种作业人员的考核。 除主要负责人、安全生产管理人员、特种作业人员以外的生产经营单位的其他从业人员的考核，由生产经营单位按照省级安全生产监督管理部门公布的考核标准，自行组织考核。"},{"i":21,"n":"第二十一条","txt":"安全生产监督管理部门、煤矿安全培训监管机构和生产经营单位应当制定安全培训的考核制度，建立考核管理档案备查。"},{"i":22,"n":"第二十二条","txt":"接受安全培训人员经考核合格的，由考核部门在考核结束后10个工作日内颁发相应的证书。"},{"i":23,"n":"第二十三条","txt":"安全生产监管人员经考核合格后，颁发安全生产监管执法证；煤矿安全监察人员经考核合格后，颁发煤矿安全监察执法证；危险物品的生产、经营、储存单位和矿山、金属冶炼单位主要负责人、安全生产管理人员经考核合格后，颁发安全合格证；特种作业人员经考核合格后，颁发《中华人民共和国特种作业操作证》（以下简称特种作业操作证）；危险化学品登记机构的登记人员经考核合格后，颁发上岗证；其他人员经培训合格后，颁发培训合格证。"},{"i":24,"n":"第二十四条","txt":"安全生产监管执法证、煤矿安全监察执法证、安全合格证、特种作业操作证和上岗证的式样，由国家安全监管总局统一规定。培训合格证的式样，由负责培训考核的部门规定。"},{"i":25,"n":"第二十五条","txt":"安全生产监管执法证、煤矿安全监察执法证、安全合格证的有效期为3年。有效期届满需要延期的，应当于有效期届满30日前向原发证部门申请办理延期手续。 特种作业人员的考核发证按照《特种作业人员安全技术培训考核管理规定》执行。"},{"i":26,"n":"第二十六条","txt":"特种作业操作证和省级安全生产监督管理部门、省级煤矿安全培训监管机构颁发的主要负责人、安全生产管理人员的安全合格证，在全国范围内有效。"},{"i":27,"n":"第二十七条","txt":"承担安全评价、咨询、检测、检验的人员和安全生产应急救援人员的考核、发证，按照有关法律、法规、规章的规定执行。"},{"i":28,"n":"第二十八条","txt":"安全生产监督管理部门、煤矿安全培训监管机构应当依照法律、法规和本办法的规定，加强对安全培训工作的监督管理，对生产经营单位、安全培训机构违反有关法律、法规和本办法的行为，依法作出处理。 省级安全生产监督管理部门、省级煤矿安全培训监管机构应当定期统计分析本行政区域内安全培训、考核、发证情况，并报国家安全监管总局。"},{"i":29,"n":"第二十九条","txt":"安全生产监督管理部门和煤矿安全培训监管机构应当对安全培训机构开展安全培训活动的情况进行监督检查，检查内容包括： （一）具备从事安全培训工作所需要的条件的情况； （二）建立培训管理制度和教师配备的情况； （三）执行培训大纲、建立培训档案和培训保障的情况； （四）培训收费的情况； （五）法律法规规定的其他内容。"},{"i":30,"n":"第三十条","txt":"安全生产监督管理部门、煤矿安全培训监管机构应当对生产经营单位的安全培训情况进行监督检查，检查内容包括： （一）安全培训制度、年度培训计划、安全培训管理档案的制定和实施的情况； （二）安全培训经费投入和使用的情况； （三）主要负责人、安全生产管理人员接受安全生产知识和管理能力考核的情况； （四）特种作业人员持证上岗的情况； （五）应用新工艺、新技术、新材料、新设备以及转岗前对从业人员安全培训的情况； （六）其他从业人员安全培训的情况； （七）法律法规规定的其他内容。"},{"i":31,"n":"第三十一条","txt":"任何单位或者个人对生产经营单位、安全培训机构违反有关法律、法规和本办法的行为，均有权向安全生产监督管理部门、煤矿安全监察机构、煤矿安全培训监管机构报告或者举报。 接到举报的部门或者机构应当为举报人保密，并按照有关规定对举报进行核查和处理。"},{"i":32,"n":"第三十二条","txt":"监察机关依照《中华人民共和国行政监察法》等法律、行政法规的规定，对安全生产监督管理部门、煤矿安全监察机构、煤矿安全培训监管机构及其工作人员履行安全培训工作监督管理职责情况实施监察。"},{"i":33,"n":"第三十三条","txt":"安全生产监督管理部门、煤矿安全监察机构、煤矿安全培训监管机构的工作人员在安全培训监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"安全培训机构有下列情形之一的，责令限期改正，处1万元以下的罚款；逾期未改正的，给予警告，处1万元以上3万元以下的罚款： （一）不具备安全培训条件的； （二）未按照统一的培训大纲组织教学培训的； （三）未建立培训档案或者培训档案管理不规范的； 安全培训机构采取不正当竞争手段，故意贬低、诋毁其他安全培训机构的，依照前款规定处罚。"},{"i":35,"n":"第三十五条","txt":"生产经营单位主要负责人、安全生产管理人员、特种作业人员以欺骗、贿赂等不正当手段取得安全合格证或者特种作业操作证的，除撤销其相关证书外，处3000元以下的罚款，并自撤销其相关证书之日起3年内不得再次申请该证书。"},{"i":36,"n":"第三十六条","txt":"生产经营单位有下列情形之一的，责令改正，处3万元以下的罚款： （一）从业人员安全培训的时间少于《生产经营单位安全培训规定》或者有关标准规定的； （二）矿山新招的井下作业人员和危险物品生产经营单位新招的危险工艺操作岗位人员，未经实习期满独立上岗作业的； （三）相关人员未按照本办法第十二条规定重新参加安全培训的。"},{"i":37,"n":"第三十七条","txt":"生产经营单位存在违反有关法律、法规中安全生产教育培训的其他行为的，依照相关法律、法规的规定予以处罚。"},{"i":38,"n":"第三十八条","txt":"本办法自2012年3月1日起施行。2004年12月28日公布的《安全生产培训管理办法》（原国家安全生产监督管理局〈国家煤矿安全监察局〉令第20号）同时废止。"}],"anquanshengchanjianguanjianchazhizehexingzhengzhifead612":[{"i":1,"n":"第一条","txt":"为促进安全生产监督管理部门、煤矿安全监察机构及其行政执法人员依法履行职责，落实行政执法责任，保障公民、法人和其他组织合法权益，根据《公务员法》、《安全生产法》、《安全生产许可证条例》等法律法规和国务院有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上人民政府安全生产监督管理部门、煤矿安全监察机构（以下统称安全监管监察部门）及其内设机构、行政执法人员履行安全生产监管监察职责和实施行政执法责任追究，适用本规定；法律、法规对行政执法责任追究或者党政领导干部问责另有规定的，依照其规定。 本规定所称行政执法责任追究，是指对作出违法、不当的安全监管监察行政执法行为（以下简称行政执法行为），或者未履行法定职责的安全监管监察部门及其内设机构、行政执法人员，实施行政责任追究（以下简称责任追究）。"},{"i":3,"n":"第三条","txt":"责任追究应当遵循公正公平、有错必纠、责罚相当、惩教结合的原则，做到事实清楚、证据确凿、定性准确、处理适当、程序合法、手续完备。"},{"i":4,"n":"第四条","txt":"责任追究实行回避制度。与违法、不当行政执法行为或者责任人有利害关系，或者有其他特殊关系，可能影响公正处理的人员，实施责任追究时应当回避。 安全监管监察部门负责人的回避由该部门负责人集体讨论决定，其他人员的回避由该部门负责人决定。"},{"i":5,"n":"第五条","txt":"县级以上人民政府安全生产监督管理部门依法对本行政区域内安全生产工作实施综合监督管理，指导协调和监督检查本级人民政府有关部门依法履行安全生产监督管理职责；对本行政区域内没有其他行政主管部门负责安全生产监督管理的生产经营单位实施安全生产监督管理；对下级人民政府安全生产工作进行监督检查。 煤矿安全监察机构依法履行国家煤矿安全监察职责，实施煤矿安全监察行政执法，对煤矿安全进行重点监察、专项监察和定期监察，对地方人民政府依法履行煤矿安全生产监督管理职责的情况进行监督检查。"},{"i":6,"n":"第六条","txt":"安全监管监察部门应当依照《安全生产法》和其他有关法律、法规、规章和本级人民政府、上级安全监管监察部门规定的安全监管监察职责，根据各自的监管监察权限、行政执法人员数量、监管监察的生产经营单位状况、技术装备和经费保障等实际情况，制定本部门年度安全监管或者煤矿安全监察执法工作计划，并按照执法工作计划进行监管监察，发现事故隐患，应当依法及时处理。 安全监管执法工作计划应当报本级人民政府批准后实施，并报上一级安全监管部门备案；煤矿安全监察执法工作计划应当报上一级煤矿安全监察机构批准后实施。安全监管和煤矿安全监察执法工作计划因特殊情况需要作出重大调整或者变更的，应当及时报原批准单位批准，并按照批准后的计划执行。 安全监管和煤矿安全监察执法工作计划应当包括监管监察的对象、时间、次数、主要事项、方式和职责分工等内容。根据安全监管监察工作需要，安全监管监察部门可以按照安全监管和煤矿安全监察执法工作计划编"},{"i":7,"n":"第七条","txt":"安全监管监察部门应当按照各自权限，依照法律、法规、规章和国家标准或者行业标准规定的安全生产条件和程序，履行下列行政审批或者考核职责： （一）矿山、金属冶炼建设项目和用于生产、储存危险物品的建设项目安全设施的设计审查； （二）矿山企业、危险化学品和烟花爆竹生产企业的安全生产许可； （三）危险化学品经营许可； （四）非药品类易制毒化学品生产、经营许可； （五）烟花爆竹经营（批发、零售）许可； （六）矿山、危险化学品、烟花爆竹生产经营单位和金属冶炼单位主要负责人、安全生产管理人员的安全资格认定，特种作业人员（特种设备作业人员除外）操作资格认定； （七）涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备安全使用证或者安全标志的核发； （八）安全生产检测检验、安全评价机构资质的认可； （九）注册助理安全工程师资格、注册安全工程师执业资格的考试和注册； （十）法律、行政法规和国务院设"},{"i":8,"n":"第八条","txt":"安全监管监察部门应当按照年度安全监管和煤矿安全监察执法工作计划、现场检查方案，对生产经营单位是否具备有关法律、法规、规章和国家标准或者行业标准规定的安全生产条件进行监督检查，重点监督检查下列事项： （一）依法通过有关安全生产行政审批的情况； （二）有关人员的安全生产教育和培训、考核情况； （三）建立和落实安全生产责任制、安全生产规章制度和操作规程、作业规程的情况； （四）按照国家规定提取和使用安全生产费用，安排用于配备劳动防护用品、进行安全生产教育和培训的经费，以及其他安全生产投入的情况； （五）依法设置安全生产管理机构和配备安全生产管理人员的情况； （六）危险物品的生产、储存单位以及矿山、金属冶炼单位配备或者聘用注册安全工程师的情况； （七）从业人员、被派遣劳动者和实习学生受到安全生产教育、培训及其教育培训档案的情况； （八）新建、改建、扩建工程项目的安全设施与主体工程同时设计、同时"},{"i":9,"n":"第九条","txt":"安全监管监察部门在监督检查中，发现生产经营单位存在安全生产违法行为或者事故隐患的，应当依法采取下列现场处理措施： （一）当场予以纠正； （二）责令限期改正、责令限期达到要求； （三）责令立即停止作业（施工）、责令立即停止使用、责令立即排除事故隐患； （四）责令从危险区域撤出作业人员； （五）责令暂时停产停业、停止建设、停止施工或者停止使用相关设备、设施； （六）依法应当采取的其他现场处理措施。"},{"i":10,"n":"第十条","txt":"被责令限期改正、限期达到要求、暂时停产停业、停止建设、停止施工或者停止使用的生产经营单位提出复查申请或者整改、治理限期届满的，安全监管监察部门应当自收到申请或者限期届满之日起10日内进行复查，并填写复查意见书，由被复查单位和安全监管监察部门复查人员签名后存档。 煤矿安全监察机构依照有关规定将复查工作移交给县级以上地方人民政府负责煤矿安全生产监督管理的部门的，应当及时将相应的执法文书抄送该部门并备案。县级以上地方人民政府负责煤矿安全生产监督管理的部门应当自收到煤矿申请或者限期届满之日起10日内进行复查，并填写复查意见书，由被复查煤矿和复查人员签名后存档，并将复查意见书及时抄送移交复查的煤矿安全监察机构。 对逾期未整改、治理或者整改、治理不合格的生产经营单位，安全监管监察部门应当依法给予行政处罚，并依法提请县级以上地方人民政府按照规定的权限决定关闭。"},{"i":11,"n":"第十一条","txt":"安全监管监察部门在监督检查中，发现生产经营单位存在安全生产非法、违法行为的，有权依法采取下列行政强制措施： （一）对有根据认为不符合安全生产的国家标准或者行业标准的在用设施、设备、器材，违法生产、储存、使用、经营、运输的危险物品，以及违法生产、储存、使用、经营危险物品的作业场所予以查封或者扣押，并依法作出处理决定； （二）扣押相关的证据材料和违法物品，临时查封有关场所； （三）法律、法规规定的其他行政强制措施。 实施查封、扣押的，应当制作并当场交付查封、扣押决定书和清单。"},{"i":12,"n":"第十二条","txt":"安全监管监察部门依法对存在重大事故隐患的生产经营单位作出停产停业、停止施工、停止使用相关设施、设备的决定，生产经营单位应当依法执行，及时消除事故隐患。生产经营单位拒不执行，有发生生产安全事故的现实危险的，在保证安全的前提下，经本部门主要负责人批准，安全监管监察部门可以采取通知有关单位停止供电、停止供应民用爆炸物品等措施，强制生产经营单位履行决定。通知应当采用书面形式，有关单位应当予以配合。 安全监管监察部门依照前款规定采取停止供电措施，除有危及生产安全的紧急情形外，应当提前二十四小时通知生产经营单位。生产经营单位依法履行行政决定、采取相应措施消除事故隐患的，安全监管监察部门应当及时解除前款规定的措施。"},{"i":13,"n":"第十三条","txt":"安全监管监察部门在监督检查中，发现生产经营单位存在的安全问题涉及有关地方人民政府或其有关部门的，应当及时向有关地方人民政府报告或其有关部门通报。"},{"i":14,"n":"第十四条","txt":"安全监管监察部门应当严格依照法律、法规和规章规定的行政处罚的行为、种类、幅度和程序，按照各自的管辖权限，对监督检查中发现的生产经营单位及有关人员的安全生产非法、违法行为实施行政处罚。 对到期不缴纳罚款的，安全监管监察部门可以每日按罚款数额的百分之三加处罚款。 生产经营单位拒不执行安全监管监察部门行政处罚决定的，作出行政处罚决定的安全监管监察部门可以依法申请人民法院强制执行；拒不执行处罚决定可能导致生产安全事故的，应当及时向有关地方人民政府报告或其有关部门通报。"},{"i":15,"n":"第十五条","txt":"安全监管监察部门对生产经营单位及其从业人员作出现场处理措施、行政强制措施和行政处罚决定等行政执法行为前，应当充分听取当事人的陈述、申辩，对其提出的事实、理由和证据，应当进行复核。当事人提出的事实、理由和证据成立的，应当予以采纳。 安全监管监察部门对生产经营单位及其从业人员作出现场处理措施、行政强制措施和行政处罚决定等行政执法行为时，应当依法制作有关法律文书，并按照规定送达当事人。"},{"i":16,"n":"第十六条","txt":"安全监管监察部门应当依法履行下列生产安全事故报告和调查处理职责： （一）建立值班制度，并向社会公布值班电话，受理事故报告和举报； （二）按照法定的时限、内容和程序逐级上报和补报事故； （三）接到事故报告后，按照规定派人立即赶赴事故现场，组织或者指导协调事故救援； （四）按照规定组织或者参加事故调查处理； （五）对事故发生单位落实事故防范和整改措施的情况进行监督检查； （六）依法对事故责任单位和有关责任人员实施行政处罚； （七）依法应当履行的其他职责。"},{"i":17,"n":"第十七条","txt":"安全监管监察部门应当依法受理、调查和处理本部门法定职责范围内的举报事项，并形成书面材料。调查处理情况应当答复举报人，但举报人的姓名、名称、住址不清的除外。对不属于本部门职责范围的举报事项，应当依法予以登记，并告知举报人向有权机关提出。"},{"i":18,"n":"第十八条","txt":"安全监管监察部门应当依法受理行政复议申请，审理行政复议案件，并作出处理或者决定。"},{"i":19,"n":"第十九条","txt":"安全监管监察部门及其内设机构、行政执法人员履行本规定第二章规定的行政执法职责，有下列违法或者不当的情形之一，致使行政执法行为被撤销、变更、确认违法，或者被责令履行法定职责、承担行政赔偿责任的，应当实施责任追究： （一）超越、滥用法定职权的； （二）主要事实不清、证据不足的； （三）适用依据错误的； （四）行政裁量明显不当的； （五）违反法定程序的； （六）未按照年度安全监管或者煤矿安全监察执法工作计划、现场检查方案履行法定职责的； （七）其他违法或者不当的情形。 前款所称的行政执法行为被撤销、变更、确认违法，或者被责令履行法定职责、承担行政赔偿责任，是指行政执法行为被人民法院生效的判决、裁定，或者行政复议机关等有权机关的决定予以撤销、变更、确认违法或者被责令履行法定职责、承担行政赔偿责任的情形。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，安全监管监察部门及其内设机构、行政执法人员不承担责任： （一）因生产经营单位、中介机构等行政管理相对人的行为，致使安全监管监察部门及其内设机构、行政执法人员无法作出正确行政执法行为的； （二）因有关行政执法依据规定不一致，致使行政执法行为适用法律、法规和规章依据不当的； （三）因不能预见、不能避免并不能克服的不可抗力致使行政执法行为违法、不当或者未履行法定职责的； （四）违法、不当的行政执法行为情节轻微并及时纠正，没有造成不良后果或者不良后果被及时消除的； （五）按照批准、备案的安全监管或者煤矿安全监察执法工作计划、现场检查方案和法律、法规、规章规定的方式、程序已经履行安全生产监管监察职责的； （六）对发现的安全生产非法、违法行为和事故隐患已经依法查处，因生产经营单位及其从业人员拒不执行安全生产监管监察指令导致生产安全事故的； （七）生产经营单位非法生产或者经责令停产"},{"i":21,"n":"第二十一条","txt":"承办人直接作出违法或者不当行政执法行为的，由承办人承担责任。"},{"i":22,"n":"第二十二条","txt":"对安全监管监察部门应当经审核、批准作出的行政执法行为，分别按照下列情形区分并承担责任： （一）承办人未经审核人、批准人审批擅自作出行政执法行为，或者不按审核、批准的内容实施，致使行政执法行为违法或者不当的，由承办人承担责任； （二）承办人弄虚作假、徇私舞弊，或者承办人提出的意见错误，审核人、批准人没有发现或者发现后未予以纠正，致使行政执法行为违法或者不当的，由承办人承担主要责任，审核人、批准人承担次要责任； （三）审核人改变或者不采纳承办人的正确意见，批准人批准该审核意见，致使行政执法行为违法或者不当的，由审核人承担主要责任，批准人承担次要责任； （四）审核人未报请批准人批准而擅自作出决定，致使行政执法行为违法或者不当的，由审核人承担责任； （五）审核人弄虚作假、徇私舞弊，致使批准人作出错误决定的，由审核人承担责任； （六）批准人改变或者不采纳承办人、审核人的正确意见，致使行政执法行为"},{"i":23,"n":"第二十三条","txt":"因安全监管监察部门指派不具有行政执法资格的单位或者人员执法，致使行政执法行为违法或者不当的，由指派部门及其负责人承担责任。"},{"i":24,"n":"第二十四条","txt":"因安全监管监察部门负责人集体研究决定，致使行政执法行为违法或者不当的，主要负责人应当承担主要责任，参与作出决定的其他负责人应当分别承担相应的责任。 安全监管监察部门负责人擅自改变集体决定，致使行政执法行为违法或者不当的，由该负责人承担全部责任。"},{"i":25,"n":"第二十五条","txt":"两名以上行政执法人员共同作出违法或者不当行政执法行为的，由主办人员承担主要责任，其他人员承担次要责任；不能区分主要、次要责任人的，共同承担责任。 因安全监管监察部门内设机构单独决定，致使行政执法行为违法或者不当的，由该机构承担全部责任；因两个以上内设机构共同决定，致使行政执法行为违法或者不当的，由有关内设机构共同承担责任。"},{"i":26,"n":"第二十六条","txt":"经安全监管监察部门内设机构会签作出的行政执法行为，分别按照下列情形区分并承担责任： （一）主办机构提供的有关事实、证据不真实、不准确或者不完整，会签机构通过审查能够提出正确意见但没有提出，致使行政执法行为违法或者不当的，由主办机构承担主要责任，会签机构承担次要责任； （二）主办机构没有采纳会签机构提出的正确意见，致使行政执法行为违法或者不当的，由主办机构承担责任。"},{"i":27,"n":"第二十七条","txt":"因执行上级安全监管监察部门的指示、批复，致使行政执法行为违法或者不当的，由作出指示、批复的上级安全监管监察部门承担责任。 因请示、报告单位隐瞒事实或者未完整提供真实情况等原因，致使上级安全监管监察部门作出错误指示、批复的，由请示、报告单位承担责任。"},{"i":28,"n":"第二十八条","txt":"下级安全监管监察部门认为上级的决定或者命令有错误的，可以向上级提出改正、撤销该决定或者命令的意见；上级不改变该决定或者命令，或者要求立即执行的，下级安全监管监察部门应当执行该决定或者命令，其不当或者违法责任由上级安全监管监察部门承担。"},{"i":29,"n":"第二十九条","txt":"上级安全监管监察部门改变、撤销下级安全监管监察部门作出的行政执法行为，致使行政执法行为违法或者不当的，由上级安全监管监察部门及其有关内设机构、行政执法人员依照本章规定分别承担相应责任。"},{"i":30,"n":"第三十条","txt":"安全监管监察部门及其内设机构、行政执法人员不履行法定职责的，应当根据各自的职责分工，依照本章规定区分并承担责任。"},{"i":31,"n":"第三十一条","txt":"对安全监管监察部门及其内设机构的责任追究包括下列方式： （一）责令限期改正； （二）通报批评； （三）取消当年评优评先资格； （四）法律、法规和规章规定的其他方式。 对行政执法人员的责任追究包括下列方式： （一）批评教育； （二）离岗培训； （三）取消当年评优评先资格； （四）暂扣行政执法证件； （五）调离执法岗位； （六）法律、法规和规章规定的其他方式。 本条第一款和第二款规定的责任追究方式，可以单独或者合并适用。"},{"i":32,"n":"第三十二条","txt":"对安全监管监察部门及其内设机构、行政执法人员实施责任追究的时候，应当根据违法、不当行政执法行为的事实、性质、情节和对于社会的危害程度，依照本规定的有关条款决定。"},{"i":33,"n":"第三十三条","txt":"违法或者不当行政执法行为的情节较轻、危害较小的，对安全监管监察部门责令限期改正，对行政执法人员予以批评教育或者离岗培训，并取消当年评优评先资格。 违法或者不当行政执法行为的情节较重、危害较大的，对安全监管监察部门责令限期改正，予以通报批评，并取消当年评优评先资格；对行政执法人员予以调离执法岗位或者暂扣行政执法证件，并取消当年评优评先资格。"},{"i":34,"n":"第三十四条","txt":"安全监管监察部门及其内设机构在年度行政执法评议考核中被确定为不合格的，责令限期改正，并予以通报批评、取消当年评优评先资格。 行政执法人员在年度行政执法评议考核中被确定为不称职的，予以离岗培训、暂扣行政执法证件，并取消当年评优评先资格。"},{"i":35,"n":"第三十五条","txt":"一年内被申请行政复议或者被提起行政诉讼的行政执法行为中，被撤销、变更、确认违法的比例占20%以上（含本数，下同）的，应当责令有关安全监管监察部门限期改正，并取消当年评优评先资格。"},{"i":36,"n":"第三十六条","txt":"安全监管监察部门承担行政赔偿责任的，应当依照《国家赔偿法》第十四条的规定，责令有故意或者重大过失的行政执法人员承担全部或者部分行政赔偿费用。"},{"i":37,"n":"第三十七条","txt":"对实施违法或者不当的行政执法行为，或者未履行法定职责的行政执法人员，依照《公务员法》、《行政机关公务员处分条例》等的规定应当给予行政处分或者辞退处理的，依照其规定。"},{"i":38,"n":"第三十八条","txt":"行政执法人员的行政执法行为涉嫌犯罪的，移交司法机关处理。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，可以从轻或者减轻追究责任： （一）违反本规定第十一条至第十四条所规定的职责，未造成严重后果的； （二）主动采取措施，有效避免损失或者挽回影响的； （三）积极配合责任追究，并且主动承担责任的； （四）依法可以从轻的其他情形。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，应当从重追究责任： （一）因违法、不当行政执法行为或者不履行法定职责，严重损害国家声誉，或者造成恶劣社会影响，或者致使公共财产、国家和人民利益遭受重大损失的； （二）滥用职权、玩忽职守、徇私舞弊，致使行政执法行为违法、不当的； （三）弄虚作假、隐瞒真相，干扰、阻碍责任追究的； （四）对检举人、控告人、申诉人和实施责任追究的人员打击、报复、陷害的； （五）一年内出现两次以上应当追究责任的情形的； （六）依法应当从重追究责任的其他情形。"},{"i":41,"n":"第四十一条","txt":"安全生产监督管理部门及其负责人的责任，按照干部管理权限，由其上级安全生产监督管理部门或者本级人民政府行政监察机关追究；所属内设机构和其他行政执法人员的责任，由所在安全生产监督管理部门追究。 煤矿安全监察机构及其负责人的责任，按照干部管理权限，由其上级煤矿安全监察机构追究；所属内设机构及其行政执法人员的责任，由所在煤矿安全监察机构追究。"},{"i":42,"n":"第四十二条","txt":"安全监管监察部门进行责任追究，按照下列程序办理： （一）负责法制工作的机构自行政执法行为被确认违法、不当之日起15日内，将有关当事人的情况书面通报本部门负责行政监察工作的机构； （二）负责行政监察工作的机构自收到法制工作机构通报或者直接收到有关行政执法行为违法、不当的举报之日起60日内调查核实有关情况，提出责任追究的建议，报本部门领导班子集体讨论决定； （三）负责人事工作的机构自责任追究决定作出之日起15日内落实决定事项。 法律、法规对责任追究的程序另有规定的，依照其规定。"},{"i":43,"n":"第四十三条","txt":"安全监管监察部门实施责任追究应当制作《行政执法责任追究决定书》。《行政执法责任追究决定书》由负责行政监察工作的机构草拟，安全监管监察部门作出决定。 《行政执法责任追究决定书》应当写明责任追究的事实、依据、方式、批准机关、生效时间、当事人的申诉期限及受理机关等。离岗培训和暂扣行政执法证件的，还应当写明培训和暂扣的期限等。"},{"i":44,"n":"第四十四条","txt":"安全监管监察部门作出责任追究决定前，负责行政监察工作的机构应当将追究责任的有关事实、理由和依据告知当事人，并听取其陈述和申辩。对其合理意见，应当予以采纳。 《行政执法责任追究决定书》应当送到当事人，以及当事人所在的单位和内设机构。责任追究决定作出后，作出决定的安全监管监察部门应当派人与当事人谈话，做好思想工作，督促其做好工作交接等后续工作。 当事人对责任追究决定不服的，可以依照《公务员法》等规定申请复核和提出申诉。申诉期间，不停止责任追究决定的执行。"},{"i":45,"n":"第四十五条","txt":"对当事人的责任追究情况应当作为其考核、奖惩、任免的重要依据。安全监管监察部门负责人事工作的机构应当将责任追究的有关材料记入当事人个人档案。"},{"i":46,"n":"第四十六条","txt":"本规定所称的安全生产非法行为，是指公民、法人或者其他组织未依法取得安全监管监察部门的行政许可，擅自从事生产经营活动的行为，或者该行政许可已经失效，继续从事生产经营活动的行为。 本规定所称的安全生产违法行为，是指公民、法人或者其他组织违反有关安全生产的法律、法规、规章、国家标准、行业标准的规定，从事生产经营活动的行为。 本规定所称的违法的行政执法行为，是指违反法律、法规、规章规定的职责、程序所作出的具体行政行为。 本规定所称的不当的行政执法行为，是指违反客观、适度、公平、公正、合理等适用法律的一般原则所作出的具体行政行为。"},{"i":47,"n":"第四十七条","txt":"依法授权或者委托行使安全生产行政执法职责的单位及其行政执法人员的责任追究，参照本规定执行。"},{"i":48,"n":"第四十八条","txt":"本规定自2009年10月1日起施行。省、自治区、直辖市人民代表大会及其常务委员会或者省、自治区、直辖市人民政府对地方安全生产监督管理部门及其内设机构、行政执法人员的责任追究另有规定的，依照其规定。"}],"anquanshengchanjianguanjianchabumenxinxigongkaiban89b4a4":[{"i":1,"n":"第一条","txt":"为了深化政务公开，加强政务服务，保障公民、法人和其他组织依法获取安全生产监管监察部门信息，促进依法行政，依据《中华人民共和国政府信息公开条例》（以下简称《政府信息公开条例》）和有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"安全生产监督管理部门、煤矿安全监察机构（以下统称安全生产监管监察部门）公开本部门信息，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称安全生产监管监察部门信息（以下简称信息），是指安全生产监管监察部门在依法履行安全生产监管监察职责过程中，制作或者获取的，以一定形式记录、保存的信息。"},{"i":4,"n":"第四条","txt":"安全生产监管监察部门应当加强对信息公开工作的组织领导，建立健全安全生产政府信息公开制度。"},{"i":5,"n":"第五条","txt":"安全生产监管监察部门应当指定专门机构负责本部门信息公开的日常工作，具体职责是： （一）组织制定本部门信息公开的制度； （二）组织编制本部门信息公开指南、公开目录和公开工作年度报告； （三）组织、协调本部门内设机构的信息公开工作； （四）组织维护和更新本部门已经公开的信息； （五）统一受理和答复向本部门提出的信息公开申请； （六）负责对拟公开信息的保密审查工作进行程序审核； （七）本部门规定与信息公开有关的其他职责。 安全生产监管监察部门的其他内设机构应当依照本办法的规定，负责审核并主动公开本机构有关信息，并配合协助前款规定的专门机构做好本部门信息公开工作。"},{"i":6,"n":"第六条","txt":"安全生产监管监察部门应当依据有关法律、行政法规的规定加强对信息公开工作的保密审查，确保国家秘密信息安全。"},{"i":7,"n":"第七条","txt":"安全生产监管监察部门负责行政监察的机构应当加强对本部门信息公开工作的监督检查。"},{"i":8,"n":"第八条","txt":"安全生产监管监察部门应当建立健全信息公开的协调机制。安全生产监管监察部门拟发布的信息涉及其他行政机关或者与其他行政机关联合制作的，应当由负责发布信息的内设机构与其他行政机关进行沟通、确认，确保信息发布及时、准确。 安全生产监管监察部门拟发布的信息依照国家有关规定需要批准的，未经批准不得发布。"},{"i":9,"n":"第九条","txt":"安全生产监管监察部门应当遵循依法、公正、公开、便民的原则，及时、准确地公开信息，但危及国家安全、公共安全、经济安全和社会稳定的信息除外。 安全生产监管监察部门发现影响或者可能影响社会稳定、扰乱安全生产秩序的虚假或者不完整信息的，应当按照实事求是和审慎处理的原则，在职责范围内发布准确的信息予以澄清，及时回应社会关切，正确引导社会舆论。"},{"i":10,"n":"第十条","txt":"安全生产监管监察部门应当依照《政府信息公开条例》第九条的规定，在本部门职责范围内确定主动公开的信息的具体内容，并重点公开下列信息： （一）本部门基本信息，包括职能、内设机构、负责人姓名、办公地点、办事程序、联系方式等； （二）安全生产法律、法规、规章、标准和规范性文件； （三）安全生产的专项规划及相关政策； （四）安全生产行政许可的事项、负责承办的内设机构、依据、条件、数量、程序、期限以及申请行政许可需要提交的全部材料的目录及办理情况； （五）行政事业性收费的项目、依据、标准； （六）地方人民政府规定需要主动公开的财政信息； （七）开展安全生产监督检查的情况； （八）生产安全事故的发生情况，社会影响较大的生产安全事故的应急处置和救援情况，经过有关人民政府或者主管部门依法批复的事故调查和处理情况； （九）法律、法规和规章规定应当公开的其他信息。 安全生产有关决策、规定或者规划、计划、方案"},{"i":11,"n":"第十一条","txt":"除本办法第十条规定应当主动公开的信息外，公民、法人或者其他组织可以根据自身生产、生活、科研等特殊需要，申请获取相关信息。 公民、法人或者其他组织使用安全生产监管监察部门公开的信息，不得损害国家利益、公共利益和他人的合法权益。"},{"i":12,"n":"第十二条","txt":"安全生产监管监察部门的下列信息不予公开： （一）涉及国家秘密以及危及国家安全、公共安全、经济安全和社会稳定的； （二）属于商业秘密或者公开后可能导致商业秘密被泄露的； （三）属于个人隐私或者公开后可能导致对个人隐私权造成侵害的； （四）在日常工作中制作或者获取的内部管理信息； （五）尚未形成，需要进行汇总、加工、重新制作（作区分处理的除外），或者需要向其他行政机关、公民、法人或者其他组织搜集的信息； （六）处于讨论、研究或者审查中的过程性信息； （七）依照法律、法规和国务院规定不予公开的其他信息。 安全生产监管监察部门有证据证明与申请人生产、生活、科研等特殊需要无关的信息，可以不予提供。 与安全生产行政执法有关的信息，公开后可能影响检查、调查、取证等安全生产行政执法活动，或者危及公民、法人和其他组织人身或者财产安全的，安全生产监管监察部门可以暂时不予公开。在行政执法活动结束后，再依照本"},{"i":13,"n":"第十三条","txt":"安全生产监管监察部门应当通过政府网站、公报、新闻发布会或者报刊、广播、电视等便于公众知晓的方式主动公开本办法第十条规定的信息，并依照《政府信息公开条例》的规定及时向当地档案馆和公共图书馆提供主动公开的信息。具体办法由安全生产监管监察部门与当地档案馆、公共图书馆协商制定。 安全生产监管监察部门可以根据需要，在办公地点设立信息查阅室、信息公告栏、电子信息屏等场所、设施公开信息。"},{"i":14,"n":"第十四条","txt":"安全生产监管监察部门制作的信息，由制作该信息的部门负责公开；安全生产监管监察部门从公民、法人或者其他组织获取的信息，由保存该信息的行政机关负责公开。法律、法规对政府信息公开的权限另有规定的，从其规定。"},{"i":15,"n":"第十五条","txt":"安全生产监管监察部门在制作信息时，应当明确该信息的公开属性，包括主动公开、依申请公开或者不予公开。 对于需要主动公开的信息，安全生产监管监察部门应当自该信息形成或者变更之日起20个工作日内予以公开。法律、法规对公开期限另有规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"公民、法人或者其他组织依照本办法第十一条的规定申请获取信息的，应当按照“一事一申请”的原则填写《信息公开申请表》，向安全生产监管监察部门提出申请；填写《信息公开申请表》确有困难的，申请人可以口头提出，由受理该申请的安全生产监管监察部门代为填写，申请人签字确认。"},{"i":17,"n":"第十七条","txt":"安全生产监管监察部门收到《信息公开申请表》后，负责信息公开的专门机构应当进行审查，符合要求的，予以受理，并在收到《信息公开申请表》之日起3个工作日内向申请人出具申请登记回执；不予受理的，应当书面告知申请人不予受理的理由。"},{"i":18,"n":"第十八条","txt":"安全生产监管监察部门受理信息公开申请后，负责信息公开的专门机构能够当场答复的，应当当场答复；不能够当场答复的，应当及时转送本部门相关内设机构办理。 安全生产监管监察部门受理的信息公开申请，应当自收到《信息公开申请表》之日起15个工作日内按照本办法第十九条的规定予以答复；不能在15个工作日内作出答复的，经本部门负责信息公开的专门机构负责人同意，可以适当延长答复期限，并书面告知申请人，延长答复的期限最长不得超过15个工作日。 申请获取的信息涉及第三方权益的，受理申请的安全生产监管监察部门征求第三方意见所需时间不计算在前款规定的期限内。"},{"i":19,"n":"第十九条","txt":"对于已经受理的信息公开申请，安全生产监管监察部门应当根据下列情况分别予以答复： （一）属于本部门信息公开范围的，应当书面告知申请人获取该信息的方式、途径，或者直接向申请人提供该信息； （二）属于不予公开范围的，应当书面告知申请人不予公开的理由、依据； （三）依法不属于本部门职能范围或者信息不存在的，应当书面告知申请人，对能够确定该信息的公开机关的，应当告知申请人该行政机关的名称和联系方式； （四）申请内容不明确的，应当书面告知申请人作出更改、补充。 申请获取的信息中含有不应当公开的内容，但是能够作区分处理的，安全生产监管监察部门应当向申请人提供可以公开的信息内容。"},{"i":20,"n":"第二十条","txt":"申请获取的信息涉及商业秘密、个人隐私，或者公开后可能损害第三方合法权益的，受理申请的安全生产监管监察部门应当书面征求第三方的意见。第三方不同意公开的，不得公开；但是，受理申请的安全生产监管监察部门认为不公开可能对公共利益造成重大影响的，应当予以公开，并将决定公开的信息内容和理由书面通知第三方。"},{"i":21,"n":"第二十一条","txt":"公民、法人和其他组织有证据证明与其自身相关的信息不准确的，有权要求更正。受理申请的安全生产监管监察部门经核实后，应当予以更正，并将更正后的信息书面告知申请人；无权更正的，应当转送有权更正的部门或者其他行政机关处理，并告知申请人。"},{"i":22,"n":"第二十二条","txt":"对于依申请公开的信息，安全生产监管监察部门应当按照申请人要求的形式予以提供；无法按照申请人要求的形式提供的，可以通过安排申请人查阅相关资料、提供复制件或者其他适当的形式提供。"},{"i":23,"n":"第二十三条","txt":"安全生产监管监察部门依申请提供信息，除可以按照国家规定的标准向申请人收取检索、复制、邮寄等成本费用外，不得收取其他费用。 申请获取信息的公民确有经济困难的，经本人申请、安全生产监管监察部门负责信息公开的专门机构负责人审核同意，可以减免相关费用。"},{"i":24,"n":"第二十四条","txt":"安全生产监管监察部门应当建立健全信息发布保密审查制度，明确保密审查的人员、方法、程序和责任。 安全生产监管监察部门在公开信息前，应当依照《中华人民共和国保守国家秘密法》、《安全生产工作国家秘密范围的规定》等法律、行政法规和有关保密制度，对拟公开的信息进行保密审查。 安全生产监管监察部门在保密审查过程中不能确定是否涉及国家秘密的，应当说明信息来源和本部门的保密审查意见，报上级安全生产监管监察部门或者本级保密行政管理部门确定。"},{"i":25,"n":"第二十五条","txt":"安全生产监管监察部门应当编制、公布本部门信息公开指南及信息公开目录，并及时更新。 信息公开指南应当包括信息的分类、编排体系、获取方式和信息公开专门机构的名称、办公地址、办公时间、联系电话、传真号码、电子邮箱等内容。 信息公开目录应当包括信息的索引、名称、信息内容概述、生成日期、公开时间等内容。"},{"i":26,"n":"第二十六条","txt":"安全生产监管监察部门应当建立健全信息公开工作考核制度、社会评议制度和责任追究制度，定期对信息公开工作进行考核、评议。"},{"i":27,"n":"第二十七条","txt":"安全生产监管监察部门应当于每年3月31日前公布本部门上一年度信息公开工作年度报告。年度报告应当包括下列内容： （一）本部门主动公开信息的情况； （二）本部门依申请公开信息和不予公开信息的情况； （三）信息公开工作的收费及减免情况； （四）因信息公开申请行政复议、提起行政诉讼的情况； （五）信息公开工作存在的主要问题及改进情况； （六）其他需要报告的事项。"},{"i":28,"n":"第二十八条","txt":"公民、法人或者其他组织认为安全生产监管监察部门不依法履行信息公开义务的，可以向上级安全生产监管监察部门举报。收到举报的安全生产监管监察部门应当依照《信访条例》的规定予以处理，督促被举报的安全生产监管监察部门依法履行信息公开义务。"},{"i":29,"n":"第二十九条","txt":"公民、法人或者其他组织认为信息公开工作中的具体行政行为侵犯其合法权益的，可以依法申请行政复议或者提起行政诉讼。"},{"i":30,"n":"第三十条","txt":"安全生产监管监察部门及其工作人员违反本办法的规定，有下列情形之一的，由本部门负责行政监察的机构或者其上级安全生产监管监察部门责令改正；情节严重的，对部门主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）不依法履行信息公开义务的； （二）不及时更新公开的信息内容、信息公开指南和信息公开目录的； （三）违反规定收取费用的； （四）通过其他组织、个人以有偿服务方式提供信息的； （五）公开不应当公开的信息的； （六）故意提供虚假信息的； （七）违反有关法律法规和本办法规定的其他行为。"},{"i":31,"n":"第三十一条","txt":"国家安全生产监督管理总局管理的具有行政职能的事业单位的有关信息公开，参照本办法执行。"},{"i":32,"n":"第三十二条","txt":"本办法自2012年11月1日起施行。"}],"anquanshengchanxingzhengchufaziyoucailiangshiyongg886d2c":[{"i":1,"n":"第一条","txt":"为了正确适用安全生产法律、行政法规和部门规章，规范安全生产监督管理部门合法、适当地行使行政处罚自由裁量权，根据《行政处罚法》、《安全生产法》、《职业病防治法》等法律、行政法规和部门规章的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"县级以上安全生产监督管理部门或其委托实施行政处罚的组织或者机构（以下统称安全监管执法机关）依照安全生产法律、行政法规和部门规章作出行政处罚行使自由裁量权的，适用本规则；具体实施行政处罚需要自由裁量的，参照《安全生产行政处罚自由裁量标准》（以下简称《标准》）执行。 煤矿安全监察机构对煤矿安全生产违法行为作出行政处罚行使自由裁量权的，适用《煤矿安全监察行政处罚自由裁量实施标准（试行）》。 法律、行政法规和地方性法规对行政处罚自由裁量另有规定的，适用其规定；原国家安全监管局、国家安全监管总局公布的部门规章与本规则不一致的，适用本规则。"},{"i":3,"n":"第三条","txt":"本规则所称的行政处罚自由裁量权，是指安全监管执法机关在对安全生产违法行为实施行政处罚时，根据立法目的和行政处罚的原则，在法律、行政法规和部门规章规定的行政处罚的种类和幅度内，综合考量违法的事实、性质、手段、后果、情节和改正措施等因素，正确、适当地确定行政处罚的种类、幅度或者作出不予行政处罚决定的选择适用权限。"},{"i":4,"n":"第四条","txt":"各级安全监管执法机关应当加强对各自管辖范围内安全生产行政处罚自由裁量行为的监督检查。 上级安全监管执法机关有权对下级安全监管执法机关违法或者不当的行政处罚予以纠正或者撤销。"},{"i":5,"n":"第五条","txt":"行使行政处罚自由裁量权，应当遵循程序法定原则，严格遵守法律、行政法规和部门规章规定的程序。"},{"i":6,"n":"第六条","txt":"行使行政处罚自由裁量权，应当遵循合法、公平、公正、公开的原则，过罚相当的原则和处罚与教育相结合的原则，依法维护公民、法人和其他组织的合法权益，确保行政处罚自由裁量权行使的合法性和合理性。"},{"i":7,"n":"第七条","txt":"行使行政处罚自由裁量权，应当以事实为依据、以法律为准绳，全面分析违法行为的主体、客体、主观方面、客观方面等因素，综合裁量，合理确定应否给予行政处罚或者应当给予行政处罚的种类、幅度。给予行政处罚的种类、幅度应当与违法行为的事实、性质、情节、认知态度以及社会危害程度相当。 对同一类违法主体实施的性质相同、情节相近或者相似、危害后果基本相当的违法行为，在行使行政处罚自由裁量权时，适用的法律依据、处罚种类应当基本一致，处罚幅度应当基本相当。"},{"i":8,"n":"第八条","txt":"同一个违法行为违反不同法律、行政法规或者部门规章规定的，在适用具体法律条文时应当遵循下列原则： （一）优先适用法律效力高的规定； （二）法律效力相同，属于特别规定的优先适用； （三）法律效力相同，生效时间在后的优先适用。"},{"i":9,"n":"第九条","txt":"法律对同一个违法行为设定了行政处罚的，按照下列原则行使自由裁量权： （一）同一法律规定实施某个违法行为应当（可以）处以罚款的行政处罚确定的，参照《标准》对其罚款幅度予以细化； （二）同一法律规定实施某个违法行为应当（可以）处以不同种类（包括警告、没收违法所得、暂扣或者吊销许可证等）的行政处罚的，参照《标准》给予相应种类的行政处罚； （三）同一法律规定实施某个违法行为根据情节轻重不同处以不同种类的行政处罚的，参照《标准》确定的情节给予相应种类的行政处罚。"},{"i":10,"n":"第十条","txt":"生产经营单位及其有关人员违反不同的法律规定，或者违反同一条款的不同违法情形，有两个以上应当给予行政处罚的违法行为的，应当适用不同的法律规定或者同一法律条款规定的不同违法情形，分别裁量，合并处罚。"},{"i":11,"n":"第十一条","txt":"法律、行政法规或者部门规章规定应当先予责令改正或者责令限期改正的，应当先予书面责令当事人在规定期限内予以改正；当事人逾期不改正的，再依法决定行政处罚。"},{"i":12,"n":"第十二条","txt":"法律、行政法规或者部门规章规定的多种处罚应当并处的，不得选择适用；规定可以并处的，可以选择适用。 法律、行政法规或者部门规章明确规定的处罚种类可以单处也可以并处的，可以选择适用，但应分清主罚项和次罚项。 法律、行政法规规定应当先予没收物品、没收违法所得，再作其他处罚的，不得直接选择适用其他处罚。"},{"i":13,"n":"第十三条","txt":"法律、行政法规或者部门规章已经规定处罚种类的，实施自由裁量权时，不得改变行政处罚种类；对当事人实施罚款的，其罚款额不得高于法律、行政法规或者部门规章规定数额的上限，也不得低于其规定数额的下限。"},{"i":14,"n":"第十四条","txt":"当事人有下列情形之一的，应当依法从轻处罚： （一）已满14周岁不满18周岁的公民实施安全生产违法行为的； （二）主动消除或者减轻安全生产违法行为危害后果的； （三）受他人胁迫实施安全生产违法行为的； （四）配合安全监管执法机关查处安全生产违法行为，有立功表现的； （五）主动投案，向安全监管执法机关如实交待自己的违法行为的； （六）具有法律、行政法规规定的其他从轻处罚情形的。 有从轻处罚情节的，应当在法定处罚幅度的中档以下确定行政处罚标准，但不得低于法定处罚幅度的下限。 本条第一款第（四）项所称的立功表现，是指当事人有揭发他人安全生产违法行为，并经查证属实；或者提供查处其他安全生产违法行为的重要线索，并经查证属实；或者阻止他人实施安全生产违法行为；或者协助司法机关抓捕其他违法犯罪嫌疑人的行为。"},{"i":15,"n":"第十五条","txt":"当事人有下列情形之一的，应当依法从重处罚： （一）危及公共安全或者其他生产经营单位及其人员安全，经责令限期改正，逾期未改正的； （二）一年内因同一种安全生产违法行为受到两次以上行政处罚的； （三）拒不整改或者整改不力，其违法行为处于持续状态的； （四）拒绝、阻碍或者以暴力威胁行政执法人员的； （五）在处置突发事件期间实施安全生产违法行为的； （六）隐匿、销毁违法行为证据的； （七）违法行为情节恶劣，造成人身死亡（重伤、急性工业中毒）或者严重社会影响的； （八）故意实施违法行为的； （九）对举报人、证人打击报复的； （十）未依法排查治理事故隐患的； （十一）发生生产安全事故后逃匿或者瞒报、谎报的； （十二）具有法律、行政法规规定的其他从重处罚情形的。 有从重处罚情节的，应当在法定处罚幅度内选择较高或者最高幅度确定处罚标准，但不得高于法定处罚幅度上限。"},{"i":16,"n":"第十六条","txt":"当事人有下列情形之一的，不予处罚： （一）证据不足，安全生产违法事实不能成立的； （二）安全生产违法行为轻微并及时纠正，没有造成危害后果的； （三）不满14周岁的公民实施安全生产违法行为的； （四）精神病人在不能辨认或者不能控制自己行为时实施安全生产违法行为的； （五）安全生产违法行为在两年内未被发现的，法律另有规定的除外； （六）具有法律、行政法规、部门规章规定的其他情形的。 前款第五项规定的期限，从违法行为发生之日起计算，违法行为有连续或者继续状态的，从行为终了之日起计算。"},{"i":17,"n":"第十七条","txt":"《标准》所称的违法所得，按照下列规定计算： （一）生产、加工产品的，以生产、加工的产品及其销售收入作为违法所得； （二）销售商品的，以销售收入作为违法所得； （三）提供安全生产中介、租赁等服务的，以服务收入或者报酬作为违法所得； （四）销售收入无法计算的，按照当地同类同等规模的生产经营单位的平均销售收入计算； （五）服务收入、报酬无法计算的，按照当地同行业同种服务的平均收入或者报酬计算。"},{"i":18,"n":"第十八条","txt":"除当场行政处罚外，行政处罚自由裁量结果实行审核制度。 案件调查终结后，案件承办人员应当对拟作出行政处罚的种类和幅度提出建议，并说明行使自由裁量权的事实、理由和依据；案件审核人员应当对处罚依据、额度等提出审核意见，并将审核意见报送安全监管执法机关负责人审查决定；安全监管执法机关已经成立行政处罚案件审核委员会的，审核意见报案件审核委员会审查决定。 对安全生产违法行为给予从轻或者从重处罚的自由裁量结果，应当由安全监管执法机关的负责人集体讨论决定。"},{"i":19,"n":"第十九条","txt":"行政处罚案件实行备案审查制度。 各级安全监管执法机关负责法制工作的机构负责本机关行政处罚案件的备案审查工作，对各类安全生产行政处罚案件的实体内容、执法程序、自由裁量的合法性、适当性以及相关证据进行事后审查，并定期对行政执法案卷进行复查和监督。"},{"i":20,"n":"第二十条","txt":"行使安全生产行政处罚自由裁量权的裁量结果应当公开，允许社会公众查阅，但涉及国家秘密、商业秘密或者个人隐私的除外。"},{"i":21,"n":"第二十一条","txt":"行政监察机关对安全监管执法机关及其工作人员行使行政处罚自由裁量权实施监察。 安全监管执法机关及其工作人员行使行政处罚自由裁量权明显不当的，必须及时予以纠正；对有关责任人员依照《安全生产监管监察职责和行政执法责任追究的暂行规定》处理。"},{"i":22,"n":"第二十二条","txt":"违反《安全生产法》有关规定发生生产安全事故，应当给予生产经营单位的主要负责人、个人经营的投资人和其他责任人员罚款的，依照《安全生产法》第八十条、第八十一条的规定处罚。 违反《安全生产法》以外的有关法律、行政法规、部门规章的规定发生生产安全事故，应当给予生产经营单位的主要负责人、个人经营的投资人和其他责任人员罚款的，依照《生产安全事故报告和调查处理条例》的规定处罚。"},{"i":23,"n":"第二十三条","txt":"行政处罚自由裁量审查和备案审查的具体办法，由地方各级安全监管执法机关根据本机关实际制定，并报上一级安全监管执法机关备案。"},{"i":24,"n":"第二十四条","txt":"安全生产违法行为涉嫌构成刑事犯罪的，应当依据规定程序移交司法机关，不得以罚代刑。"},{"i":25,"n":"第二十五条","txt":"本规则自2010年10月1日起施行。"}],"anquanshengchanxingzhengfuyiguiding":[{"i":1,"n":"第一条","txt":"为了规范安全生产行政复议工作，解决行政争议，根据《中华人民共和国行政复议法》和《中华人民共和国行政复议法实施条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为安全生产监督管理部门、煤矿安全监察机构（以下统称安全监管监察部门）的具体行政行为侵犯其合法权益，向安全生产行政复议机关申请行政复议，安全生产行政复议机关受理行政复议申请，作出行政复议决定，适用本规定。"},{"i":3,"n":"第三条","txt":"依法履行行政复议职责的安全监管监察部门是安全生产行政复议机关。安全生产行政复议机关负责法制工作的机构是本机关的行政复议机构（以下简称安全生产行政复议机构）。 安全生产行政复议机关应当领导、支持本机关行政复议机构依法办理行政复议事项，并依照有关规定充实、配备专职行政复议人员，保证行政复议机构的办案能力与工作任务相适应。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局办理行政复议案件按照下列程序，统一受理，分工负责： （一）政策法规司按照本规定规定的期限，对行政复议申请进行初步审查，做出受理或者不予受理的决定。对决定受理的，将案卷材料转送相关业务司局分口承办； （二）相关业务司局收到案卷材料后，应当在30日内了解核实有关情况，提出处理意见； （三）政策法规司根据处理意见，在20日内拟定行政复议决定书，提交本局负责人集体讨论或者主管负责人审定； （四）本局负责人集体讨论通过或者主管负责人同意后，政策法规司制作行政复议决定书，并送达申请人、被申请人和第三人。 国家煤矿安全监察局和省级及省级以下安全监管监察部门办理行政复议案件参照上述程序执行。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织对安全监管监察部门作出的下列具体行政行为不服，可以申请行政复议： （一）行政处罚决定； （二）行政强制措施； （三）行政许可的变更、中止、撤销、撤回等决定； （四）认为符合法定条件，申请安全监管监察部门办理许可证、资格证等行政许可手续，安全监管监察部门没有依法办理的； （五）认为安全监管监察部门违法收费或者违法要求履行义务的； （六）认为安全监管监察部门其他具体行政行为侵犯其合法权益的。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织认为安全监管监察部门的具体行政行为所依据的规定不合法，在对具体行政行为申请行政复议时，可以依据行政复议法第七条的规定一并提出审查申请。"},{"i":7,"n":"第七条","txt":"安全监管监察部门作出的下列行政行为，不属于安全生产行政复议范围： （一）生产安全事故调查报告； （二）不具有强制力的行政指导行为和信访答复行为； （三）生产安全事故隐患认定； （四）公告信息发布； （五）法律、行政法规规定的非具体行政行为。"},{"i":8,"n":"第八条","txt":"对县级以上地方人民政府安全生产监督管理部门作出的具体行政行为不服的，可以向上一级安全生产监督管理部门申请行政复议，也可以向同级人民政府申请行政复议。已向同级人民政府提出行政复议申请，且同级人民政府已经受理的，上一级安全生产监督管理部门不再受理。 对国家安全生产监督管理总局作出的具体行政行为不服的，向国家安全生产监督管理总局申请行政复议。"},{"i":9,"n":"第九条","txt":"对煤矿安全监察分局作出的具体行政行为不服的，向该分局所隶属的省级煤矿安全监察局申请行政复议。 对省级煤矿安全监察机构作出的具体行政行为不服的，向国家安全生产监督管理总局申请行政复议。 对国家煤矿安全监察局作出的具体行政行为不服的，向国家煤矿安全监察局申请行政复议。"},{"i":10,"n":"第十条","txt":"安全监管监察部门设立的派出机构、内设机构或者其他组织，未经法律、行政法规授权，对外以自己名义作出具体行政行为的，该安全监管监察部门为被申请人。"},{"i":11,"n":"第十一条","txt":"对安全监管监察部门依法委托的机构，以委托的安全监管监察部门名义作出的具体行政行为不服的，依照本规定第八条和第九条的规定申请行政复议。"},{"i":12,"n":"第十二条","txt":"对安全监管监察部门与有关部门共同作出的具体行政行为不服的，可以向其共同的上一级行政机关申请行政复议。共同作出具体行政行为的安全监管监察部门与有关部门为共同被申请人。 对国家安全生产监督管理总局与国务院其他部门共同作出的具体行政行为不服的，可以向国家安全生产监督管理总局或者共同作出具体行政行为的其他任何一个部门提起行政复议申请，由作出具体行政行为的部门共同作出行政复议决定。"},{"i":13,"n":"第十三条","txt":"下级安全监管监察部门依照法律、行政法规、规章规定，经上级安全监管监察部门批准作出具体行政行为的，批准机关为被申请人。"},{"i":14,"n":"第十四条","txt":"安全监管监察部门作出具体行政行为，依法应当向有关公民、法人或者其他组织送达法律文书而未送达的，视为该公民、法人或者其他组织不知道该具体行政行为。 安全监管监察部门作出的具体行政行为对公民、法人或者其他组织的权利、义务可能产生不利影响的，应当告知其申请行政复议的权利、行政复议机关和行政复议申请期限。"},{"i":15,"n":"第十五条","txt":"行政复议可以书面申请，也可以当场口头申请。书面申请可以采取当面递交、邮寄或者传真等方式提出，并在行政复议申请书中载明《行政复议法实施条例》第十九条规定的事项。 当场口头申请的，安全生产行政复议机构应当按照第一款规定的事项，当场制作行政复议申请笔录交申请人核对或者向申请人宣读，并由申请人签字确认。"},{"i":16,"n":"第十六条","txt":"安全生产行政复议机构应当自收到行政复议申请之日起3日内对复议申请是否符合下列条件进行初步审查： （一）有明确的申请人和被申请人； （二）申请人与具体行政行为有利害关系； （三）有具体的行政复议请求和事实依据； （四）在法定申请期限内提出； （五）属于本规定第五条规定的行政复议范围； （六）属于收到行政复议申请的行政复议机关的职责范围； （七）其他行政复议机关尚未受理同一行政复议申请，人民法院尚未受理同一主体就同一事实提起的行政诉讼。"},{"i":17,"n":"第十七条","txt":"行政复议申请错列被申请人的，安全生产行政复议机构应当告知申请人变更被申请人。"},{"i":18,"n":"第十八条","txt":"行政复议申请材料不齐全或者表述不清楚的，安全生产行政复议机构可以自收到该行政复议申请之日起5日内书面通知申请人补正。补正通知应当载明需要补正的事项和合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请。补正申请材料所用时间不计入行政复议审理期限。"},{"i":19,"n":"第十九条","txt":"经初步审查后，安全生产行政复议机构应当自收到行政复议申请之日起5日内按下列规定作出处理： （一）符合本规定第十六条规定的，予以受理，并制发行政复议受理决定书； （二）不符合本规定第十六条规定的，决定不予受理，并制发行政复议申请不予受理决定书； （三）不属于本机关职责范围的，应当告知申请人向有权受理的行政复议机关提出。"},{"i":20,"n":"第二十条","txt":"行政复议期间，安全生产行政复议机构认为申请人以外的公民、法人或者其他组织与被审查的具体行政行为有利害关系的，可以通知其作为第三人参加行政复议。 行政复议期间，申请人以外的公民、法人或者其他组织与被审查的具体行政行为有利害关系的，可以向安全生产行政复议机构申请作为第三人参加行政复议。"},{"i":21,"n":"第二十一条","txt":"安全生产行政复议机构审理行政复议案件，应当由2名以上行政复议人员参加。"},{"i":22,"n":"第二十二条","txt":"安全生产行政复议机构应当自行政复议申请受理之日起7日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。 被申请人应当自收到申请书副本或者行政复议申请笔录复印件之日起10日内，按照复议机构要求的份数提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。 被申请人书面答复应当载明下列事项，并加盖单位公章： （一）作出具体行政行为的基本过程和情况； （二）作出具体行政行为的事实依据和有关证据材料； （三）作出具体行政行为所依据的法律、行政法规、规章和规范性文件的文号、具体条款和内容； （四）对申请人复议请求的意见和理由； （五）答复的年月日。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，被申请人经安全生产行政复议机构允许可以补充相关证据： （一）在作出具体行政行为时已经收集证据，但因不可抗力等正当理由不能提供的； （二）申请人或者第三人在行政复议过程中，提出了其在安全监管监察部门实施具体行政行为过程中没有提出的申辩理由或者证据的。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，申请人应当提供证明材料： （一）认为被申请人不履行法定职责的，提供曾经要求被申请人履行法定职责而被申请人未履行的证明材料，但被申请人依法应当主动履行的除外； （二）申请行政复议时一并提出行政赔偿请求的，提供受具体行政行为侵害而造成损害的证明材料； （三）申请人自己主张的事实； （四）法律、行政法规规定由申请人提供证据材料的其他情形。"},{"i":25,"n":"第二十五条","txt":"申请人、被申请人、第三人应当对其提交的证据材料分类编号，对证据材料的来源、证明对象和内容作简要说明，并在证据材料上签字或者盖章，注明提交日期。 证据材料是复印件的，应当经复议机构核对无误，并注明原件存放的单位和处所。"},{"i":26,"n":"第二十六条","txt":"行政复议原则上采取书面审理的方式，但对重大、复杂的案件，申请人提出要求或者安全生产行政复议机构认为必要时，可以采取听证的方式审理。 听证应当保障当事人平等的陈述、质证和辩论的权利。"},{"i":27,"n":"第二十七条","txt":"安全生产行政复议机构采取听证的方式审理复议案件，应当制作听证笔录并载明下列事项： （一）案由，听证的时间、地点； （二）申请人、被申请人、第三人及其代理人的基本情况； （三）听证主持人、听证员、书记员的姓名、职务等； （四）申请人、被申请人、第三人争议的焦点问题，有关事实、证据和依据； （五）其他应当记载的事项。 申请人、被申请人、第三人应当核对听证笔录并签字或者盖章。"},{"i":28,"n":"第二十八条","txt":"安全生产行政复议机构认为必要时，可以实地调查核实证据。调查核实时，行政复议人员不得少于2人，并应当向当事人或者有关人员出示证件。 需要现场勘验的，现场勘验所用时间不计入行政复议审理期限。"},{"i":29,"n":"第二十九条","txt":"安全生产行政复议期间涉及专门事项需要鉴定的，当事人可以自行委托鉴定机构进行鉴定，也可以申请行政复议机构委托鉴定机构进行鉴定。鉴定费用由当事人承担。鉴定所用时间不计入行政复议审理期限。"},{"i":30,"n":"第三十条","txt":"申请人在行政复议决定作出前自愿撤回行政复议申请的，经行政复议机构同意，可以撤回。 申请人撤回行政复议申请的，不得以同一事实和理由再次提出行政复议申请。但是，申请人能够证明撤回行政复议申请违背其真实意思表示的除外。"},{"i":31,"n":"第三十一条","txt":"行政复议申请由两个以上申请人共同提出，在行政复议决定作出前，部分申请人撤回行政复议申请的，安全生产行政复议机关应当就其他申请人未撤回的行政复议申请作出行政复议决定。"},{"i":32,"n":"第三十二条","txt":"被申请人在复议期间改变原具体行政行为的，应当书面告知复议机构。 被申请人改变原具体行政行为，申请人撤回复议申请的，行政复议终止；申请人不撤回复议申请的，安全生产行政复议机关经审查认为原具体行政行为违法的，应当作出确认其违法的复议决定；认为原具体行政行为合法的，应当作出维持的复议决定。"},{"i":33,"n":"第三十三条","txt":"公民、法人或者其他组织对安全监管监察部门行使法律、行政法规规定的自由裁量权作出的具体行政行为不服申请行政复议，申请人与被申请人在行政复议决定作出前自愿达成和解的，应当向安全生产行政复议机构提交书面和解协议；和解内容不损害社会公共利益和他人合法权益的，安全生产行政复议机构应当准许。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，安全生产行政复议机构可以按照自愿、合法的原则进行调解： （一）公民、法人或者其他组织对安全监管监察部门行使法律、行政法规规定的自由裁量权作出的具体行政行为不服申请行政复议的； （二）当事人之间的行政赔偿或者行政补偿的纠纷。 当事人经调解达成协议的，安全生产行政复议机关应当制作行政复议调解书。调解书应当载明行政复议请求、事实、理由和调解结果，并加盖安全生产行政复议机关印章。行政复议调解书经双方当事人签字，即具有法律效力。 调解未达成协议或者调解书生效前一方反悔的，安全生产行政复议机关应当及时作出行政复议决定。"},{"i":35,"n":"第三十五条","txt":"安全生产行政复议机构应当对被申请人作出的具体行政行为进行审查，提出意见，经安全生产行政复议机关集体讨论通过或者负责人同意后，依法作出行政复议决定。"},{"i":36,"n":"第三十六条","txt":"被申请人被责令重新作出具体行政行为的，应当在法律、行政法规、规章规定的期限内重新作出具体行政行为；法律、行政法规、规章未规定期限的，重新作出具体行政行为的期限为60日。 被申请人不得以同一事实和理由作出与原具体行政行为相同或者基本相同的具体行政行为。但因违反法定程序被责令重新作出具体行政行为的除外。"},{"i":37,"n":"第三十七条","txt":"申请人在申请行政复议时一并提出行政赔偿请求，安全生产行政复议机关对符合国家赔偿法有关规定应当给予赔偿的，在决定撤销、变更具体行政行为或者确认具体行政行为违法时，应当同时决定被申请人依法给予赔偿。 申请人在申请行政复议时没有提出行政赔偿请求的，安全生产行政复议机关在依法决定撤销或者变更原具体行政行为确定的罚款以及对设备、设施、器材的扣押、查封等强制措施时，应当同时责令被申请人返还罚款，解除对设备、设施、器材的扣押、查封等强制措施。"},{"i":38,"n":"第三十八条","txt":"安全生产行政复议机关在申请人的行政复议请求范围内，不得作出对申请人更为不利的行政复议决定。"},{"i":39,"n":"第三十九条","txt":"安全生产行政复议机关及其工作人员和被申请人在安全生产行政复议工作中违反本规定的，依照行政复议法及其实施条例的规定，追究法律责任。"},{"i":40,"n":"第四十条","txt":"行政复议期间的计算和行政复议文书的送达，依照民事诉讼法关于期间、送达的规定执行。 本规定关于行政复议期间有关“3日”、“5日”、“7日”的规定是指工作日，不含节假日。"},{"i":41,"n":"第四十一条","txt":"安全生产行政复议案件审理完毕，案件承办人应当将案件材料在10日内立卷、归档。 下一级安全生产行政复议机关应当在作出行政复议决定之日起15日内将行政复议决定书报上一级安全生产行政复议机构备案。"},{"i":42,"n":"第四十二条","txt":"安全监管行政复议机关办理行政复议案件，使用国家安全生产监督管理总局统一制定的文书式样。 煤矿安全监察行政复议机关办理行政复议案件，使用国家煤矿安全监察局统一制定的文书式样。"},{"i":43,"n":"第四十三条","txt":"本规定自2007年11月1日起施行。原国家经济贸易委员会2003年2月18日公布的《安全生产行政复议暂行办法》和原国家安全生产监督管理局（国家煤矿安全监察局）2003年6月20日公布的《煤矿安全监察行政复议规定》同时废止。"}],"anquanshengchanweifaxingweixingzhengchufabanfa":[{"i":1,"n":"第一条","txt":"为了制裁安全生产违法行为，规范安全生产行政处罚工作，依照行政处罚法、安全生产法及其他有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府安全生产监督管理部门对生产经营单位及其有关人员在生产经营活动中违反有关安全生产的法律、行政法规、部门规章、国家标准、行业标准和规程的违法行为（以下统称安全生产违法行为）实施行政处罚，适用本办法。 煤矿安全监察机构依照本办法和煤矿安全监察行政处罚办法，对煤矿、煤矿安全生产中介机构等生产经营单位及其有关人员的安全生产违法行为实施行政处罚。 有关法律、行政法规对安全生产违法行为行政处罚的种类、幅度或者决定机关另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"对安全生产违法行为实施行政处罚，应当遵循公平、公正、公开的原则。 安全生产监督管理部门或者煤矿安全监察机构（以下统称安全监管监察部门）及其行政执法人员实施行政处罚，必须以事实为依据。行政处罚应当与安全生产违法行为的事实、性质、情节以及社会危害程度相当。"},{"i":4,"n":"第四条","txt":"生产经营单位及其有关人员对安全监管监察部门给予的行政处罚，依法享有陈述权、申辩权和听证权；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼；因违法给予行政处罚受到损害的，有权依法申请国家赔偿。"},{"i":5,"n":"第五条","txt":"安全生产违法行为行政处罚的种类： （一）警告； （二）罚款； （三）没收违法所得、没收非法开采的煤炭产品、采掘设备； （四）责令停产停业整顿、责令停产停业、责令停止建设、责令停止施工； （五）暂扣或者吊销有关许可证，暂停或者撤销有关执业资格、岗位证书； （六）关闭； （七）拘留； （八）安全生产法律、行政法规规定的其他行政处罚。"},{"i":6,"n":"第六条","txt":"县级以上安全监管监察部门应当按照本章的规定，在各自的职责范围内对安全生产违法行为行政处罚行使管辖权。 安全生产违法行为的行政处罚，由安全生产违法行为发生地的县级以上安全监管监察部门管辖。中央企业及其所属企业、有关人员的安全生产违法行为的行政处罚，由安全生产违法行为发生地的设区的市级以上安全监管监察部门管辖。 暂扣、吊销有关许可证和暂停、撤销有关执业资格、岗位证书的行政处罚，由发证机关决定。其中，暂扣有关许可证和暂停有关执业资格、岗位证书的期限一般不得超过6个月；法律、行政法规另有规定的，依照其规定。 给予关闭的行政处罚，由县级以上安全监管监察部门报请县级以上人民政府按照国务院规定的权限决定。 给予拘留的行政处罚，由县级以上安全监管监察部门建议公安机关依照治安管理处罚法的规定决定。"},{"i":7,"n":"第七条","txt":"两个以上安全监管监察部门因行政处罚管辖权发生争议的，由其共同的上一级安全监管监察部门指定管辖。"},{"i":8,"n":"第八条","txt":"对报告或者举报的安全生产违法行为，安全监管监察部门应当受理；发现不属于自己管辖的，应当及时移送有管辖权的部门。 受移送的安全监管监察部门对管辖权有异议的，应当报请共同的上一级安全监管监察部门指定管辖。"},{"i":9,"n":"第九条","txt":"安全生产违法行为涉嫌犯罪的，安全监管监察部门应当将案件移送司法机关，依法追究刑事责任；尚不够刑事处罚但依法应当给予行政处罚的，由安全监管监察部门管辖。"},{"i":10,"n":"第十条","txt":"上级安全监管监察部门可以直接查处下级安全监管监察部门管辖的案件，也可以将自己管辖的案件交由下级安全监管监察部门管辖。 下级安全监管监察部门可以将重大、疑难案件报请上级安全监管监察部门管辖。"},{"i":11,"n":"第十一条","txt":"上级安全监管监察部门有权对下级安全监管监察部门违法或者不适当的行政处罚予以纠正或者撤销。"},{"i":12,"n":"第十二条","txt":"安全监管监察部门根据需要，可以在其法定职权范围内委托符合《行政处罚法》第十九条规定条件的组织或者乡、镇人民政府以及街道办事处、开发区管理机构等地方人民政府的派出机构实施行政处罚。受委托的单位在委托范围内，以委托的安全监管监察部门名义实施行政处罚。 委托的安全监管监察部门应当监督检查受委托的单位实施行政处罚，并对其实施行政处罚的后果承担法律责任。"},{"i":13,"n":"第十三条","txt":"安全生产行政执法人员在执行公务时，必须出示省级以上安全生产监督管理部门或者县级以上地方人民政府统一制作的有效行政执法证件。其中对煤矿进行安全监察，必须出示国家安全生产监督管理总局统一制作的煤矿安全监察员证。"},{"i":14,"n":"第十四条","txt":"安全监管监察部门及其行政执法人员在监督检查时发现生产经营单位存在事故隐患的，应当按照下列规定采取现场处理措施： （一）能够立即排除的，应当责令立即排除； （二）重大事故隐患排除前或者排除过程中无法保证安全的，应当责令从危险区域撤出作业人员，并责令暂时停产停业、停止建设、停止施工或者停止使用相关设施、设备，限期排除隐患。 隐患排除后，经安全监管监察部门审查同意，方可恢复生产经营和使用。 本条第一款第（二）项规定的责令暂时停产停业、停止建设、停止施工或者停止使用相关设施、设备的期限一般不超过6个月；法律、行政法规另有规定的，依照其规定。"},{"i":15,"n":"第十五条","txt":"对有根据认为不符合安全生产的国家标准或者行业标准的在用设施、设备、器材，违法生产、储存、使用、经营、运输的危险物品，以及违法生产、储存、使用、经营危险物品的作业场所，安全监管监察部门应当依照《行政强制法》的规定予以查封或者扣押。查封或者扣押的期限不得超过30日，情况复杂的，经安全监管监察部门负责人批准，最多可以延长30日，并在查封或者扣押期限内作出处理决定： （一）对违法事实清楚、依法应当没收的非法财物予以没收； （二）法律、行政法规规定应当销毁的，依法销毁； （三）法律、行政法规规定应当解除查封、扣押的，作出解除查封、扣押的决定。 实施查封、扣押，应当制作并当场交付查封、扣押决定书和清单。"},{"i":16,"n":"第十六条","txt":"安全监管监察部门依法对存在重大事故隐患的生产经营单位作出停产停业、停止施工、停止使用相关设施、设备的决定，生产经营单位应当依法执行，及时消除事故隐患。生产经营单位拒不执行，有发生生产安全事故的现实危险的，在保证安全的前提下，经本部门主要负责人批准，安全监管监察部门可以采取通知有关单位停止供电、停止供应民用爆炸物品等措施，强制生产经营单位履行决定。通知应当采用书面形式，有关单位应当予以配合。 安全监管监察部门依照前款规定采取停止供电措施，除有危及生产安全的紧急情形外，应当提前24小时通知生产经营单位。生产经营单位依法履行行政决定、采取相应措施消除事故隐患的，安全监管监察部门应当及时解除前款规定的措施。"},{"i":17,"n":"第十七条","txt":"生产经营单位被责令限期改正或者限期进行隐患排除治理的，应当在规定限期内完成。因不可抗力无法在规定限期内完成的，应当在进行整改或者治理的同时，于限期届满前10日内提出书面延期申请，安全监管监察部门应当在收到申请之日起5日内书面答复是否准予延期。 生产经营单位提出复查申请或者整改、治理限期届满的，安全监管监察部门应当自申请或者限期届满之日起10日内进行复查，填写复查意见书，由被复查单位和安全监管监察部门复查人员签名后存档。逾期未整改、未治理或者整改、治理不合格的，安全监管监察部门应当依法给予行政处罚。"},{"i":18,"n":"第十八条","txt":"安全监管监察部门在作出行政处罚决定前，应当填写行政处罚告知书，告知当事人作出行政处罚决定的事实、理由、依据，以及当事人依法享有的权利，并送达当事人。当事人应当在收到行政处罚告知书之日起3日内进行陈述、申辩，或者依法提出听证要求，逾期视为放弃上述权利。"},{"i":19,"n":"第十九条","txt":"安全监管监察部门应当充分听取当事人的陈述和申辩，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由和证据成立的，安全监管监察部门应当采纳。 安全监管监察部门不得因当事人陈述或者申辩而加重处罚。"},{"i":20,"n":"第二十条","txt":"安全监管监察部门对安全生产违法行为实施行政处罚，应当符合法定程序，制作行政执法文书。"},{"i":21,"n":"第二十一条","txt":"违法事实确凿并有法定依据，对个人处以50元以下罚款、对生产经营单位处以1千元以下罚款或者警告的行政处罚的，安全生产行政执法人员可以当场作出行政处罚决定。"},{"i":22,"n":"第二十二条","txt":"安全生产行政执法人员当场作出行政处罚决定，应当填写预定格式、编有号码的行政处罚决定书并当场交付当事人。 安全生产行政执法人员当场作出行政处罚决定后应当及时报告，并在5日内报所属安全监管监察部门备案。"},{"i":23,"n":"第二十三条","txt":"除依照简易程序当场作出的行政处罚外，安全监管监察部门发现生产经营单位及其有关人员有应当给予行政处罚的行为的，应当予以立案，填写立案审批表，并全面、客观、公正地进行调查，收集有关证据。对确需立即查处的安全生产违法行为，可以先行调查取证，并在5日内补办立案手续。"},{"i":24,"n":"第二十四条","txt":"对已经立案的案件，由立案审批人指定两名或者两名以上安全生产行政执法人员进行调查。 有下列情形之一的，承办案件的安全生产行政执法人员应当回避： （一）本人是本案的当事人或者当事人的近亲属的； （二）本人或者其近亲属与本案有利害关系的； （三）与本人有其他利害关系，可能影响案件的公正处理的。 安全生产行政执法人员的回避，由派出其进行调查的安全监管监察部门的负责人决定。进行调查的安全监管监察部门负责人的回避，由该部门负责人集体讨论决定。回避决定作出之前，承办案件的安全生产行政执法人员不得擅自停止对案件的调查。"},{"i":25,"n":"第二十五条","txt":"进行案件调查时，安全生产行政执法人员不得少于两名。当事人或者有关人员应当如实回答安全生产行政执法人员的询问，并协助调查或者检查，不得拒绝、阻挠或者提供虚假情况。 询问或者检查应当制作笔录。笔录应当记载时间、地点、询问和检查情况，并由被询问人、被检查单位和安全生产行政执法人员签名或者盖章；被询问人、被检查单位要求补正的，应当允许。被询问人或者被检查单位拒绝签名或者盖章的，安全生产行政执法人员应当在笔录上注明原因并签名。"},{"i":26,"n":"第二十六条","txt":"安全生产行政执法人员应当收集、调取与案件有关的原始凭证作为证据。调取原始凭证确有困难的，可以复制，复制件应当注明“经核对与原件无异”的字样和原始凭证存放的单位及其处所，并由出具证据的人员签名或者单位盖章。"},{"i":27,"n":"第二十七条","txt":"安全生产行政执法人员在收集证据时，可以采取抽样取证的方法；在证据可能灭失或者以后难以取得的情况下，经本单位负责人批准，可以先行登记保存，并应当在7日内作出处理决定： （一）违法事实成立依法应当没收的，作出行政处罚决定，予以没收；依法应当扣留或者封存的，予以扣留或者封存； （二）违法事实不成立，或者依法不应当予以没收、扣留、封存的，解除登记保存。"},{"i":28,"n":"第二十八条","txt":"安全生产行政执法人员对与案件有关的物品、场所进行勘验检查时，应当通知当事人到场，制作勘验笔录，并由当事人核对无误后签名或者盖章。当事人拒绝到场的，可以邀请在场的其他人员作证，并在勘验笔录中注明原因并签名；也可以采用录音、录像等方式记录有关物品、场所的情况后，再进行勘验检查。"},{"i":29,"n":"第二十九条","txt":"案件调查终结后，负责承办案件的安全生产行政执法人员应当填写案件处理呈批表，连同有关证据材料一并报本部门负责人审批。 安全监管监察部门负责人应当及时对案件调查结果进行审查，根据不同情况，分别作出以下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立，不得给予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关处理。 对严重安全生产违法行为给予责令停产停业整顿、责令停产停业、责令停止建设、责令停止施工、吊销有关许可证、撤销有关执业资格或者岗位证书、5万元以上罚款、没收违法所得、没收非法开采的煤炭产品或者采掘设备价值5万元以上的行政处罚的，应当由安全监管监察部门的负责人集体讨论决定。"},{"i":30,"n":"第三十条","txt":"安全监管监察部门依照本办法第二十九条的规定给予行政处罚，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址或者住址； （二）违法事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出行政处罚决定的安全监管监察部门的名称和作出决定的日期。 行政处罚决定书必须盖有作出行政处罚决定的安全监管监察部门的印章。"},{"i":31,"n":"第三十一条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，安全监管监察部门应当在7日内依照民事诉讼法的有关规定，将行政处罚决定书送达当事人或者其他的法定受送达人： （一）送达必须有送达回执，由受送达人在送达回执上注明收到日期，签名或者盖章； （二）送达应当直接送交受送达人。受送达人是个人的，本人不在交他的同住成年家属签收，并在行政处罚决定书送达回执的备注栏内注明与受送达人的关系； （三）受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织负责收件的人签收； （四）受送达人指定代收人的，交代收人签收并注明受当事人委托的情况； （五）直接送达确有困难的，可以挂号邮寄送达，也可以委托当地安全监管监察部门代为送达，代为送达的安全监管监察部门收到文书后，必须立即交受送达人签收； （六）当事人或者他的同住成年家属拒绝接收的，送达人应当邀请有关基层组织或者所在单"},{"i":32,"n":"第三十二条","txt":"行政处罚案件应当自立案之日起30日内作出行政处罚决定；由于客观原因不能完成的，经安全监管监察部门负责人同意，可以延长，但不得超过90日；特殊情况需进一步延长的，应当经上一级安全监管监察部门批准，可延长至180日。"},{"i":33,"n":"第三十三条","txt":"安全监管监察部门作出责令停产停业整顿、责令停产停业、吊销有关许可证、撤销有关执业资格、岗位证书或者较大数额罚款的行政处罚决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，安全监管监察部门应当组织听证，不得向当事人收取听证费用。 前款所称较大数额罚款，为省、自治区、直辖市人大常委会或者人民政府规定的数额；没有规定数额的，其数额对个人罚款为2万元以上，对生产经营单位罚款为5万元以上。"},{"i":34,"n":"第三十四条","txt":"当事人要求听证的，应当在安全监管监察部门依照本办法第十七条规定告知后3日内以书面方式提出。"},{"i":35,"n":"第三十五条","txt":"当事人提出听证要求后，安全监管监察部门应当在收到书面申请之日起15日内举行听证会，并在举行听证会的7日前，通知当事人举行听证的时间、地点。 当事人应当按期参加听证。当事人有正当理由要求延期的，经组织听证的安全监管监察部门负责人批准可以延期1次；当事人未按期参加听证，并且未事先说明理由的，视为放弃听证权利。"},{"i":36,"n":"第三十六条","txt":"听证参加人由听证主持人、听证员、案件调查人员、当事人及其委托代理人、书记员组成。 听证主持人、听证员、书记员应当由组织听证的安全监管监察部门负责人指定的非本案调查人员担任。 当事人可以委托1至2名代理人参加听证，并提交委托书。"},{"i":37,"n":"第三十七条","txt":"除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。"},{"i":38,"n":"第三十八条","txt":"当事人在听证中的权利和义务： （一）有权对案件涉及的事实、适用法律及有关情况进行陈述和申辩； （二）有权对案件调查人员提出的证据质证并提出新的证据； （三）如实回答主持人的提问； （四）遵守听证会场纪律，服从听证主持人指挥。"},{"i":39,"n":"第三十九条","txt":"听证按照下列程序进行： （一）书记员宣布听证会场纪律、当事人的权利和义务。听证主持人宣布案由，核实听证参加人名单，宣布听证开始； （二）案件调查人员提出当事人的违法事实、出示证据，说明拟作出的行政处罚的内容及法律依据； （三）当事人或者其委托代理人对案件的事实、证据、适用的法律等进行陈述和申辩，提交新的证据材料； （四）听证主持人就案件的有关问题向当事人、案件调查人员、证人询问； （五）案件调查人员、当事人或者其委托代理人相互辩论； （六）当事人或者其委托代理人作最后陈述； （七）听证主持人宣布听证结束。 听证笔录应当当场交当事人核对无误后签名或者盖章。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，应当中止听证： （一）需要重新调查取证的； （二）需要通知新证人到场作证的； （三）因不可抗力无法继续进行听证的。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，应当终止听证： （一）当事人撤回听证要求的； （二）当事人无正当理由不按时参加听证的； （三）拟作出的行政处罚决定已经变更，不适用听证程序的。"},{"i":42,"n":"第四十二条","txt":"听证结束后，听证主持人应当依据听证情况，填写听证会报告书，提出处理意见并附听证笔录报安全监管监察部门负责人审查。安全监管监察部门依照本办法第二十九条的规定作出决定。"},{"i":43,"n":"第四十三条","txt":"生产经营单位的决策机构、主要负责人、个人经营的投资人（包括实际控制人，下同）未依法保证下列安全生产所必需的资金投入之一，致使生产经营单位不具备安全生产条件的，责令限期改正，提供必需的资金，可以对生产经营单位处1万元以上3万元以下罚款，对生产经营单位的主要负责人、个人经营的投资人处5000元以上1万元以下罚款；逾期未改正的，责令生产经营单位停产停业整顿： （一）提取或者使用安全生产费用； （二）用于配备劳动防护用品的经费； （三）用于安全生产教育和培训的经费； （四）国家规定的其他安全生产所必须的资金投入。 生产经营单位主要负责人、个人经营的投资人有前款违法行为，导致发生生产安全事故的，依照《生产安全事故罚款处罚规定（试行）》的规定给予处罚。"},{"i":44,"n":"第四十四条","txt":"生产经营单位的主要负责人未依法履行安全生产管理职责，导致生产安全事故发生的，依照《生产安全事故罚款处罚规定（试行）》的规定给予处罚。"},{"i":45,"n":"第四十五条","txt":"生产经营单位及其主要负责人或者其他人员有下列行为之一的，给予警告，并可以对生产经营单位处1万元以上3万元以下罚款，对其主要负责人、其他有关人员处1千元以上1万元以下的罚款： （一）违反操作规程或者安全管理规定作业的； （二）违章指挥从业人员或者强令从业人员违章、冒险作业的； （三）发现从业人员违章作业不加制止的； （四）超过核定的生产能力、强度或者定员进行生产的； （五）对被查封或者扣押的设施、设备、器材、危险物品和作业场所，擅自启封或者使用的； （六）故意提供虚假情况或者隐瞒存在的事故隐患以及其他安全问题的； （七）拒不执行安全监管监察部门依法下达的安全监管监察指令的。"},{"i":46,"n":"第四十六条","txt":"危险物品的生产、经营、储存单位以及矿山、金属冶炼单位有下列行为之一的，责令改正，并可以处1万元以上3万元以下的罚款： （一）未建立应急救援组织或者生产经营规模较小、未指定兼职应急救援人员的； （二）未配备必要的应急救援器材、设备和物资，并进行经常性维护、保养，保证正常运转的。"},{"i":47,"n":"第四十七条","txt":"生产经营单位与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效；对生产经营单位的主要负责人、个人经营的投资人按照下列规定处以罚款： （一）在协议中减轻因生产安全事故伤亡对从业人员依法应承担的责任的，处2万元以上5万元以下的罚款； （二）在协议中免除因生产安全事故伤亡对从业人员依法应承担的责任的，处5万元以上10万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"生产经营单位不具备法律、行政法规和国家标准、行业标准规定的安全生产条件，经责令停产停业整顿仍不具备安全生产条件的，安全监管监察部门应当提请有管辖权的人民政府予以关闭；人民政府决定关闭的，安全监管监察部门应当依法吊销其有关许可证。"},{"i":49,"n":"第四十九条","txt":"生产经营单位转让安全生产许可证的，没收违法所得，吊销安全生产许可证，并按照下列规定处以罚款： （一）接受转让的单位和个人未发生生产安全事故的，处10万元以上30万元以下的罚款； （二）接受转让的单位和个人发生生产安全事故但没有造成人员死亡的，处30万元以上40万元以下的罚款； （三）接受转让的单位和个人发生人员死亡生产安全事故的，处40万元以上50万元以下的罚款。"},{"i":50,"n":"第五十条","txt":"知道或者应当知道生产经营单位未取得安全生产许可证或者其他批准文件擅自从事生产经营活动，仍为其提供生产经营场所、运输、保管、仓储等条件的，责令立即停止违法行为，有违法所得的，没收违法所得，并处违法所得1倍以上3倍以下的罚款，但是最高不得超过3万元；没有违法所得的，并处5千元以上1万元以下的罚款。"},{"i":51,"n":"第五十一条","txt":"生产经营单位及其有关人员弄虚作假，骗取或者勾结、串通行政审批工作人员取得安全生产许可证书及其他批准文件的，撤销许可及批准文件，并按照下列规定处以罚款： （一）生产经营单位有违法所得的，没收违法所得，并处违法所得1倍以上3倍以下的罚款，但是最高不得超过3万元；没有违法所得的，并处5千元以上1万元以下的罚款； （二）对有关人员处1千元以上1万元以下的罚款。 有前款规定违法行为的生产经营单位及其有关人员在3年内不得再次申请该行政许可。 生产经营单位及其有关人员未依法办理安全生产许可证书变更手续的，责令限期改正，并对生产经营单位处1万元以上3万元以下的罚款，对有关人员处1千元以上5千元以下的罚款。"},{"i":52,"n":"第五十二条","txt":"未取得相应资格、资质证书的机构及其有关人员从事安全评价、认证、检测、检验工作，责令停止违法行为，并按照下列规定处以罚款： （一）机构有违法所得的，没收违法所得，并处违法所得1倍以上3倍以下的罚款，但是最高不得超过3万元；没有违法所得的，并处5千元以上1万元以下的罚款； （二）有关人员处5千元以上1万元以下的罚款。"},{"i":53,"n":"第五十三条","txt":"生产经营单位及其有关人员触犯不同的法律规定，有两个以上应当给予行政处罚的安全生产违法行为的，安全监管监察部门应当适用不同的法律规定，分别裁量，合并处罚。"},{"i":54,"n":"第五十四条","txt":"对同一生产经营单位及其有关人员的同一安全生产违法行为，不得给予两次以上罚款的行政处罚。"},{"i":55,"n":"第五十五条","txt":"生产经营单位及其有关人员有下列情形之一的，应当从重处罚： （一）危及公共安全或者其他生产经营单位安全的，经责令限期改正，逾期未改正的； （二）一年内因同一违法行为受到两次以上行政处罚的； （三）拒不整改或者整改不力，其违法行为呈持续状态的； （四）拒绝、阻碍或者以暴力威胁行政执法人员的。"},{"i":56,"n":"第五十六条","txt":"生产经营单位及其有关人员有下列情形之一的，应当依法从轻或者减轻行政处罚： （一）已满14周岁不满18周岁的公民实施安全生产违法行为的； （二）主动消除或者减轻安全生产违法行为危害后果的； （三）受他人胁迫实施安全生产违法行为的； （四）配合安全监管监察部门查处安全生产违法行为，有立功表现的； （五）主动投案，向安全监管部门如实交待自己的违法行为的； （六）具有法律、行政法规规定的其他从轻或者减轻处罚情形的。 有从轻处罚情节的，应当在法定处罚幅度的中档以下确定行政处罚标准，但不得低于法定处罚幅度的下限。 本条第一款第四项所称的立功表现，是指当事人有揭发他人安全生产违法行为，并经查证属实；或者提供查处其他安全生产违法行为的重要线索，并经查证属实；或者阻止他人实施安全生产违法行为；或者协助司法机关抓捕其他违法犯罪嫌疑人的行为。 安全生产违法行为轻微并及时纠正，没有造成危害后果的，不予行政处罚"},{"i":57,"n":"第五十七条","txt":"安全监管监察部门实施行政处罚时，应当同时责令生产经营单位及其有关人员停止、改正或者限期改正违法行为。"},{"i":58,"n":"第五十八条","txt":"本办法所称的违法所得，按照下列规定计算： （一）生产、加工产品的，以生产、加工产品的销售收入作为违法所得； （二）销售商品的，以销售收入作为违法所得； （三）提供安全生产中介、租赁等服务的，以服务收入或者报酬作为违法所得； （四）销售收入无法计算的，按当地同类同等规模的生产经营单位的平均销售收入计算； （五）服务收入、报酬无法计算的，按照当地同行业同种服务的平均收入或者报酬计算。"},{"i":59,"n":"第五十九条","txt":"行政处罚决定依法作出后，当事人应当在行政处罚决定的期限内，予以履行；当事人逾期不履行的，作出行政处罚决定的安全监管监察部门可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的3%加处罚款，但不得超过罚款数额； （二）根据法律规定，将查封、扣押的设施、设备、器材拍卖所得价款抵缴罚款； （三）申请人民法院强制执行。 当事人对行政处罚决定不服申请行政复议或者提起行政诉讼的，行政处罚不停止执行，法律另有规定的除外。"},{"i":60,"n":"第六十条","txt":"安全生产行政执法人员当场收缴罚款的，应当出具省、自治区、直辖市财政部门统一制发的罚款收据；当场收缴的罚款，应当自收缴罚款之日起2日内，交至所属安全监管监察部门；安全监管监察部门应当在2日内将罚款缴付指定的银行。"},{"i":61,"n":"第六十一条","txt":"除依法应当予以销毁的物品外，需要将查封、扣押的设施、设备、器材和危险物品拍卖抵缴罚款的，依照法律或者国家有关规定处理。销毁物品，依照国家有关规定处理；没有规定的，经县级以上安全监管监察部门负责人批准，由两名以上安全生产行政执法人员监督销毁，并制作销毁记录。处理物品，应当制作清单。"},{"i":62,"n":"第六十二条","txt":"罚款、没收违法所得的款项和没收非法开采的煤炭产品、采掘设备，必须按照有关规定上缴，任何单位和个人不得截留、私分或者变相私分。"},{"i":63,"n":"第六十三条","txt":"县级安全生产监督管理部门处以5万元以上罚款、没收违法所得、没收非法生产的煤炭产品或者采掘设备价值5万元以上、责令停产停业、停止建设、停止施工、停产停业整顿、吊销有关资格、岗位证书或者许可证的行政处罚的，应当自作出行政处罚决定之日起10日内报设区的市级安全生产监督管理部门备案。"},{"i":64,"n":"第六十四条","txt":"设区的市级安全生产监管监察部门处以10万元以上罚款、没收违法所得、没收非法生产的煤炭产品或者采掘设备价值10万元以上、责令停产停业、停止建设、停止施工、停产停业整顿、吊销有关资格、岗位证书或者许可证的行政处罚的，应当自作出行政处罚决定之日起10日内报省级安全监管监察部门备案。"},{"i":65,"n":"第六十五条","txt":"省级安全监管监察部门处以50万元以上罚款、没收违法所得、没收非法生产的煤炭产品或者采掘设备价值50万元以上、责令停产停业、停止建设、停止施工、停产停业整顿、吊销有关资格、岗位证书或者许可证的行政处罚的，应当自作出行政处罚决定之日起10日内报国家安全生产监督管理总局或者国家煤矿安全监察局备案。 对上级安全监管监察部门交办案件给予行政处罚的，由决定行政处罚的安全监管监察部门自作出行政处罚决定之日起10日内报上级安全监管监察部门备案。"},{"i":66,"n":"第六十六条","txt":"行政处罚执行完毕后，案件材料应当按照有关规定立卷归档。 案卷立案归档后，任何单位和个人不得擅自增加、抽取、涂改和销毁案卷材料。未经安全监管监察部门负责人批准，任何单位和个人不得借阅案卷。"},{"i":67,"n":"第六十七条","txt":"安全生产监督管理部门所用的行政处罚文书式样，由国家安全生产监督管理总局统一制定。 煤矿安全监察机构所用的行政处罚文书式样，由国家煤矿安全监察局统一制定。"},{"i":68,"n":"第六十八条","txt":"本办法所称的生产经营单位，是指合法和非法从事生产或者经营活动的基本单元，包括企业法人、不具备企业法人资格的合伙组织、个体工商户和自然人等生产经营主体。"},{"i":69,"n":"第六十九条","txt":"本办法自2008年1月1日起施行。原国家安全生产监督管理局（国家煤矿安全监察局）2003年5月19日公布的《安全生产违法行为行政处罚办法》、2001年4月27日公布的《煤矿安全监察程序暂行规定》同时废止。"}],"anquanpingjiajiancejianyanjigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强安全评价机构、安全生产检测检验机构（以下统称安全评价检测检验机构）的管理，规范安全评价、安全生产检测检验行为，依据《中华人民共和国安全生产法》《中华人民共和国行政许可法》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内申请安全评价检测检验机构资质，从事法定的安全评价、检测检验服务（附件1），以及应急管理部门、煤矿安全生产监督管理部门实施安全评价检测检验机构资质认可和监督管理适用本办法。 从事海洋石油天然气开采的安全评价检测检验机构的管理办法，另行制定。"},{"i":3,"n":"第三条","txt":"国务院应急管理部门负责指导全国安全评价检测检验机构管理工作，建立安全评价检测检验机构信息查询系统，完善安全评价、检测检验标准体系。 省级人民政府应急管理部门、煤矿安全生产监督管理部门（以下统称资质认可机关）按照各自的职责，分别负责安全评价检测检验机构资质认可和监督管理工作。 设区的市级人民政府、县级人民政府应急管理部门、煤矿安全生产监督管理部门按照各自的职责，对安全评价检测检验机构执业行为实施监督检查，并对发现的违法行为依法实施行政处罚。"},{"i":4,"n":"第四条","txt":"安全评价检测检验机构及其从业人员应当依照法律、法规、规章、标准，遵循科学公正、独立客观、安全准确、诚实守信的原则和执业准则，独立开展安全评价和检测检验，并对其作出的安全评价和检测检验结果负责。"},{"i":5,"n":"第五条","txt":"国家支持发展安全评价、检测检验技术服务的行业组织，鼓励有关行业组织建立安全评价检测检验机构信用评定制度，健全技术服务能力评定体系，完善技术仲裁工作机制，强化行业自律，规范执业行为，维护行业秩序。"},{"i":6,"n":"第六条","txt":"申请安全评价机构资质应当具备下列条件： （一）独立法人资格，固定资产不少于八百万元； （二）工作场所建筑面积不少于一千平方米，其中档案室不少于一百平方米，设施、设备、软件等技术支撑条件满足工作需求； （三）承担矿山、金属冶炼、危险化学品生产和储存、烟花爆竹等业务范围安全评价的机构，其专职安全评价师不低于本办法规定的配备标准（附件1）； （四）承担单一业务范围的安全评价机构，其专职安全评价师不少于二十五人；每增加一个行业（领域），按照专业配备标准至少增加五名专职安全评价师；专职安全评价师中，一级安全评价师比例不低于百分之二十，一级和二级安全评价师的总数比例不低于百分之五十，且中级及以上注册安全工程师比例不低于百分之三十； （五）健全的内部管理制度和安全评价过程控制体系； （六）法定代表人出具知悉并承担安全评价的法律责任、义务、权利和风险的承诺书； （七）配备专职技术负责人和过程控制负责人"},{"i":7,"n":"第七条","txt":"申请安全生产检测检验机构资质应当具备下列条件： （一）独立法人资格，固定资产不少于一千万元； （二）工作场所建筑面积不少于一千平方米，有与从事安全生产检测检验相适应的设施、设备和环境，检测检验设施、设备原值不少于八百万元； （三）承担单一业务范围的安全生产检测检验机构，其专业技术人员不少于二十五人；每增加一个行业（领域），至少增加五名专业技术人员；专业技术人员中，中级及以上注册安全工程师比例不低于百分之三十，中级及以上技术职称比例不低于百分之五十，且高级技术职称人员比例不低于百分之二十五； （四）专业技术人员具有与承担安全生产检测检验相适应的专业技能，以及在本行业领域工作两年以上； （五）法定代表人出具知悉并承担安全生产检测检验的法律责任、义务、权利和风险的承诺书； （六）主持安全生产检测检验工作的负责人、技术负责人、质量负责人具有高级技术职称，在本行业领域工作八年以上； （七）符合安"},{"i":8,"n":"第八条","txt":"下列机构不得申请安全评价检测检验机构资质： （一）本办法第三条规定部门所属的事业单位及其出资设立的企业法人； （二）本办法第三条规定部门主管的社会组织及其出资设立的企业法人； （三）本条第一项、第二项中的企业法人出资设立（含控股、参股）的企业法人。"},{"i":9,"n":"第九条","txt":"符合本办法第六条、第七条规定条件的申请人申请安全评价检测检验机构资质的，应当将申请材料报送其注册地的资质认可机关。 申请材料清单目录由国务院应急管理部门另行规定。"},{"i":10,"n":"第十条","txt":"资质认可机关自收到申请材料之日起五个工作日内，对材料齐全、符合规定形式的申请，应当予以受理，并出具书面受理文书；对材料不齐全或者不符合规定形式的，应当当场或者五个工作日内一次性告知申请人需要补正的全部内容；对不予受理的，应当说明理由并出具书面凭证。"},{"i":11,"n":"第十一条","txt":"资质认可机关应当自受理之日起二十个工作日内，对审查合格的，在本部门网站予以公告，公开有关信息（附件2、附件3），颁发资质证书，并将相关信息纳入安全评价检测检验机构信息查询系统；对审查不合格的，不予颁发资质证书，说明理由并出具书面凭证。 需要专家评审的，专家评审时间不计入本条第一款规定的审查期限内，但最长不超过三个月。 资质证书的式样和编号规则由国务院应急管理部门另行规定。"},{"i":12,"n":"第十二条","txt":"安全评价检测检验机构的名称、注册地址、实验室条件、法定代表人、专职技术负责人、授权签字人发生变化的，应当自发生变化之日起三十日内向原资质认可机关提出书面变更申请。资质认可机关经审查后符合条件的，在本部门网站予以公告，并及时更新安全评价检测检验机构信息查询系统相关信息。 安全评价检测检验机构因改制、分立或者合并等原因发生变化的，应当自发生变化之日起三十日内向原资质认可机关书面申请重新核定资质条件和业务范围。 安全评价检测检验机构取得资质一年以上，需要变更业务范围的，应当向原资质认可机关提出书面申请。资质认可机关收到申请后应当按照本办法第九条至第十一条的规定办理。"},{"i":13,"n":"第十三条","txt":"安全评价检测检验机构资质证书有效期五年。资质证书有效期届满需要延续的，应当在有效期届满三个月前向原资质认可机关提出申请。原资质认可机关应当按照本办法第九条至第十一条的规定办理。"},{"i":14,"n":"第十四条","txt":"安全评价检测检验机构有下列情形之一的，原资质认可机关应当注销其资质，在本部门网站予以公告，并纳入安全评价检测检验机构信息查询系统： （一）法人资格终止； （二）资质证书有效期届满未延续； （三）自行申请注销； （四）被依法撤销、撤回、吊销资质； （五）法律、行政法规规定的应当注销资质的其他情形。 安全评价检测检验机构资质注销后无资质承继单位的，原安全评价检测检验机构及相关人员应当对注销前作出的安全评价检测检验结果继续负责。"},{"i":15,"n":"第十五条","txt":"生产经营单位可以自主选择具备本办法规定资质的安全评价检测检验机构，接受其资质认可范围内的安全评价、检测检验服务。"},{"i":16,"n":"第十六条","txt":"生产经营单位委托安全评价检测检验机构开展技术服务时，应当签订委托技术服务合同，明确服务对象、范围、权利、义务和责任。 生产经营单位委托安全评价检测检验机构为其提供安全生产技术服务的，保证安全生产的责任仍由本单位负责。应急管理部门、煤矿安全生产监督管理部门以安全评价报告、检测检验报告为依据，作出相关行政许可、行政处罚决定的，应当对其决定承担相应法律责任。"},{"i":17,"n":"第十七条","txt":"安全评价检测检验机构应当建立信息公开制度，加强内部管理，严格自我约束。专职技术负责人和过程控制负责人应当按照法规标准的规定，加强安全评价、检测检验活动的管理。 安全评价项目组组长应当具有与业务相关的二级以上安全评价师资格，并在本行业领域工作三年以上。项目组其他组成人员应当符合安全评价项目专职安全评价师专业能力配备标准。"},{"i":18,"n":"第十八条","txt":"安全评价检测检验机构开展技术服务时，应当如实记录过程控制、现场勘验和检测检验的情况，并与现场图像影像等证明资料一并及时归档。 安全评价检测检验机构应当按照有关规定在网上公开安全评价报告、安全生产检测检验报告相关信息及现场勘验图像影像。"},{"i":19,"n":"第十九条","txt":"安全评价检测检验机构应当在开展现场技术服务前七个工作日内，书面告知（附件4）项目实施地资质认可机关，接受资质认可机关及其下级部门的监督抽查。"},{"i":20,"n":"第二十条","txt":"生产经营单位应当对本单位安全评价、检测检验过程进行监督，并对本单位所提供资料、安全评价和检测检验对象的真实性、可靠性负责，承担有关法律责任。 生产经营单位对安全评价检测检验机构提出的事故预防、隐患整改意见，应当及时落实。"},{"i":21,"n":"第二十一条","txt":"安全评价、检测检验的技术服务收费按照有关规定执行。实行政府指导价或者政府定价管理的，严格执行政府指导价或者政府定价政策；实行市场调节价的，由委托方和受托方通过合同协商确定。安全评价检测检验机构应当主动公开服务收费标准，方便用户和社会公众查询。 审批部门在审批过程中委托开展的安全评价检测检验技术服务，服务费用一律由审批部门支付并纳入部门预算，对审批对象免费。"},{"i":22,"n":"第二十二条","txt":"安全评价检测检验机构及其从业人员不得有下列行为： （一）违反法规标准的规定开展安全评价、检测检验的； （二）不再具备资质条件或者资质过期从事安全评价、检测检验的； （三）超出资质认可业务范围，从事法定的安全评价、检测检验的； （四）出租、出借安全评价检测检验资质证书的； （五）出具虚假或者重大疏漏的安全评价、检测检验报告的； （六）违反有关法规标准规定，更改或者简化安全评价、检测检验程序和相关内容的； （七）专职安全评价师、专业技术人员同时在两个以上安全评价检测检验机构从业的； （八）安全评价项目组组长及负责勘验人员不到现场实际地点开展勘验等有关工作的； （九）承担现场检测检验的人员不到现场实际地点开展设备检测检验等有关工作的； （十）冒用他人名义或者允许他人冒用本人名义在安全评价、检测检验报告和原始记录中签名的； （十一）不接受资质认可机关及其下级部门监督抽查的。 本办法所称虚假报告"},{"i":23,"n":"第二十三条","txt":"资质认可机关应当建立健全安全评价检测检验机构资质认可、监督检查、属地管理的相关制度和程序，加强事中事后监管，并向社会公开监督检查情况和处理结果。 国务院应急管理部门可以对资质认可机关开展资质认可等工作情况实施综合评估，发现涉及重大生产安全事故、存在违法违规认可等问题的，可以采取约谈、通报，撤销其资质认可决定，以及暂停其资质认可权等措施。"},{"i":24,"n":"第二十四条","txt":"资质认可机关应当将其认可的安全评价检测检验机构纳入年度安全生产监督检查计划范围。按照国务院有关“双随机、一公开”的规定实施监督检查，并确保每三年至少覆盖一次。 安全评价检测检验机构从事跨区域技术服务的，项目实施地资质认可机关应当及时核查其资质有效性、认可范围等信息，并对其技术服务实施抽查。 资质认可机关及其下级部门应当对本行政区域内登记注册的安全评价检测检验机构资质条件保持情况、接受行政处罚和投诉举报等情况进行重点监督检查。"},{"i":25,"n":"第二十五条","txt":"资质认可机关及其下级部门、煤矿安全监察机构、事故调查组在安全生产行政许可、建设项目安全设施“三同时”审查、监督检查和事故调查中，发现生产经营单位和安全评价检测检验机构在安全评价、检测检验活动中有违法违规行为的，应当依法实施行政处罚。 吊销、撤销安全评价检测检验机构资质的，由原资质认可机关决定。 对安全评价检测检验机构作出行政处罚等决定，决定机关应当将有关情况及时纳入安全评价检测检验机构信息查询系统。"},{"i":26,"n":"第二十六条","txt":"负有安全生产监督管理职责的部门及其工作人员不得干预安全评价检测检验机构正常活动。除政府采购的技术服务外，不得要求生产经营单位接受指定的安全评价检测检验机构的技术服务。 没有法律法规依据或者国务院规定，不得以备案、登记、年检、换证、要求设立分支机构等形式，设置或者变相设置安全评价检测检验机构准入障碍。"},{"i":27,"n":"第二十七条","txt":"申请人隐瞒有关情况或者提供虚假材料申请资质（包括资质延续、资质变更、增加业务范围等）的，资质认可机关不予受理或者不予行政许可，并给予警告。该申请人在一年内不得再次申请。"},{"i":28,"n":"第二十八条","txt":"申请人以欺骗、贿赂等不正当手段取得资质（包括资质延续、资质变更、增加业务范围等）的，应当予以撤销。该申请人在三年内不得再次申请；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"未取得资质的机构及其有关人员擅自从事安全评价、检测检验服务的，责令立即停止违法行为，依照下列规定给予处罚： （一）机构有违法所得的，没收其违法所得，并处违法所得一倍以上三倍以下的罚款，但最高不得超过三万元；没有违法所得的，处五千元以上一万元以下的罚款； （二）有关人员处五千元以上一万元以下的罚款。 对有前款违法行为的机构及其人员，由资质认可机关记入有关机构和人员的信用记录，并依照有关规定予以公告。"},{"i":30,"n":"第三十条","txt":"安全评价检测检验机构有下列情形之一的，责令改正或者责令限期改正，给予警告，可以并处一万元以下的罚款；逾期未改正的，处一万元以上三万元以下的罚款，对相关责任人处一千元以上五千元以下的罚款；情节严重的，处一万元以上三万元以下的罚款，对相关责任人处五千元以上一万元以下的罚款： （一）未依法与委托方签订技术服务合同的； （二）违反法规标准规定更改或者简化安全评价、检测检验程序和相关内容的； （三）未按规定公开安全评价报告、安全生产检测检验报告相关信息及现场勘验图像影像资料的； （四）未在开展现场技术服务前七个工作日内，书面告知项目实施地资质认可机关的； （五）机构名称、注册地址、实验室条件、法定代表人、专职技术负责人、授权签字人发生变化之日起三十日内未向原资质认可机关提出变更申请的； （六）未按照有关法规标准的强制性规定从事安全评价、检测检验活动的； （七）出租、出借安全评价检测检验资质证书的"},{"i":31,"n":"第三十一条","txt":"承担安全评价、检测检验工作的机构，出具虚假证明的，没收违法所得；违法所得在十万元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；给他人造成损害的，与生产经营单位承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构，由资质认可机关吊销其相应资质，向社会公告，按照国家有关规定对相关机构及其责任人员实行行业禁入，纳入不良记录“黑名单”管理，以及安全评价检测检验机构信息查询系统。"},{"i":32,"n":"第三十二条","txt":"本办法自2019年5月1日起施行。原国家安全生产监督管理总局2007年1月31日公布、2015年5月29日修改的《安全生产检测检验机构管理规定》（原国家安全生产监督管理总局令第12号），2009年7月1日公布、2013年8月29日、2015年5月29日修改的《安全评价机构管理规定》（原国家安全生产监督管理总局令第22号）同时废止。 附件1：安全评价机构业务范围与专职安全评价师专业能力配备标准 附件2：安全评价机构信息公开表（样式） 附件3：安全生产检测检验机构信息公开表（样式） 附件4：安全评价检测检验机构从业告知书（样式） 附件1： 安全评价机构业务范围与专职安全评价师专业能力配备标准 备注：1.安全评价师专业能力与学科基础专业对照表另行制定。 2.安全生产检测检验资质认可业务范围以矿山井下特种设备目录为准。 附件2： 安全评价机构信息公开表 附件3： 安全生产检测检验机构信息公开表"}],"xiaoxinglutiancaishichanganquanguanliyujiandujianc010803":[{"i":1,"n":"第一条","txt":"为预防和减少小型露天采石场生产安全事故，保障从业人员的安全与健康，根据《安全生产法》、《矿山安全法》、《安全生产许可证条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"年生产规模不超过50万吨的山坡型露天采石作业单位（以下统称小型露天采石场）的安全生产及对其监督管理，适用本规定。 开采型材和金属矿产资源的小型露天矿山的安全生产及对其监督管理，不适用本规定。"},{"i":3,"n":"第三条","txt":"县级以上地方人民政府安全生产监督管理部门对小型露天采石场的安全生产实施监督管理。所辖区域内有小型露天采石场的乡（镇）应当明确负责安全生产工作的管理人员及其职责。"},{"i":4,"n":"第四条","txt":"小型露天采石场主要负责人对本单位的安全生产工作负总责，应当组织制定和落实安全生产责任制，改善劳动条件和作业环境，保证安全生产投入的有效实施。 小型露天采石场主要负责人应当经安全生产监督管理部门考核合格并取得安全资格证书。"},{"i":5,"n":"第五条","txt":"小型露天采石场应当建立健全安全生产管理制度和岗位安全操作规程，至少配备一名专职安全生产管理人员。 安全生产管理人员应当按照国家有关规定经安全生产监督管理部门考核合格并取得安全资格证书。"},{"i":6,"n":"第六条","txt":"小型露天采石场应当至少配备一名专业技术人员，或者聘用专业技术人员、注册安全工程师、委托相关技术服务机构为其提供安全生产管理服务。"},{"i":7,"n":"第七条","txt":"小型露天采石场新进矿山的作业人员应当接受不少于40小时的安全培训，已在岗的作业人员应当每年接受不少于20小时的安全再培训。 特种作业人员必须按照国家有关规定经专门的安全技术培训并考核合格，取得特种作业操作证书后，方可上岗作业。"},{"i":8,"n":"第八条","txt":"小型露天采石场必须参加工伤保险，按照国家有关规定提取和使用安全生产费用。"},{"i":9,"n":"第九条","txt":"新建、改建、扩建小型露天采石场应当由具有建设主管部门认定资质的设计单位编制开采设计或者开采方案。采石场布置和开采方式发生重大变化时，应当重新编制开采设计或者开采方案，并由原审查部门审查批准。"},{"i":10,"n":"第十条","txt":"小型露天采石场新建、改建、扩建工程项目安全设施应当按照规定履行设计审查程序。"},{"i":11,"n":"第十一条","txt":"小型露天采石场应当依法取得非煤矿矿山企业安全生产许可证。未取得安全生产许可证的，不得从事生产活动。 在安全生产许可证有效期内采矿许可证到期失效的，小型露天采石场应当在采矿许可证到期前15日内向原安全生产许可证颁发管理机关报告，并交回安全生产许可证正本和副本。"},{"i":12,"n":"第十二条","txt":"相邻的采石场开采范围之间最小距离应当大于300米。对可能危及对方生产安全的，双方应当签订安全生产管理协议，明确各自的安全生产管理职责和应当采取的安全措施，指定专门人员进行安全检查与协调。"},{"i":13,"n":"第十三条","txt":"小型露天采石场应当采用中深孔爆破，严禁采用扩壶爆破、掏底崩落、掏挖开采和不分层的“一面墙”等开采方式。 不具备实施中深孔爆破条件的，由所在地安全生产监督管理部门聘请有关专家进行论证，经论证符合要求的，方可采用浅孔爆破开采。 小型露天采石场实施中深孔爆破条件的审核办法，由省级安全生产监督管理部门制定。"},{"i":14,"n":"第十四条","txt":"不采用爆破方式直接使用挖掘机进行采矿作业的，台阶高度不得超过挖掘机最大挖掘高度。"},{"i":15,"n":"第十五条","txt":"小型露天采石场应当采用台阶式开采。不能采用台阶式开采的，应当自上而下分层顺序开采。 分层开采的分层高度、最大开采高度（第一分层的坡顶线到最后一分层的坡底线的垂直距离）和最终边坡角由设计确定，实施浅孔爆破作业时，分层数不得超过6个，最大开采高度不得超过30米；实施中深孔爆破作业时，分层高度不得超过20米，分层数不得超过3个，最大开采高度不得超过60米。 分层开采的凿岩平台宽度由设计确定，最小凿岩平台宽度不得小于4米。 分层开采的底部装运平台宽度由设计确定，且应当满足调车作业所需的最小平台宽度要求。"},{"i":16,"n":"第十六条","txt":"小型露天采石场应当遵守国家有关民用爆炸物品和爆破作业的安全规定，由具有相应资格的爆破作业人员进行爆破，设置爆破警戒范围，实行定时爆破制度。不得在爆破警戒范围内避炮。 禁止在雷雨、大雾、大风等恶劣天气条件下进行爆破作业。雷电高发地区应当选用非电起爆系统。"},{"i":17,"n":"第十七条","txt":"对爆破后产生的大块矿岩应当采用机械方式进行破碎，不得使用爆破方式进行二次破碎。"},{"i":18,"n":"第十八条","txt":"承包爆破作业的专业服务单位应当取得爆破作业单位许可证，承包采矿和剥离作业的采掘施工单位应当持有非煤矿矿山企业安全生产许可证。"},{"i":19,"n":"第十九条","txt":"采石场上部需要剥离的，剥离工作面应当超前于开采工作面4米以上。"},{"i":20,"n":"第二十条","txt":"小型露天采石场在作业前和作业中以及每次爆破后，应当对坡面进行安全检查。发现工作面有裂痕，或者在坡面上有浮石、危石和伞檐体可能塌落时，应当立即停止作业并撤离人员至安全地点，采取安全措施和消除隐患。 采石场的入口道路及相关危险源点应当设置安全警示标志，严禁任何人员在边坡底部休息和停留。"},{"i":21,"n":"第二十一条","txt":"在坡面上进行排险作业时，作业人员应当系安全带，不得站在危石、浮石上及悬空作业。严禁在同一坡面上下双层或者多层同时作业。 距工作台阶坡底线50米范围内不得从事碎石加工作业。"},{"i":22,"n":"第二十二条","txt":"小型露天采石场应当采用机械铲装作业，严禁使用人工装运矿岩。 同一工作面有两台铲装机械作业时，最小间距应当大于铲装机械最大回转半径的2倍。 严禁自卸汽车运载易燃、易爆物品；严禁超载运输；装载与运输作业时，严禁在驾驶室外侧、车斗内站人。"},{"i":23,"n":"第二十三条","txt":"废石、废碴应当排放到废石场。废石场的设置应当符合设计要求和有关安全规定。顺山或顺沟排放废石、废碴的，应当有防止泥石流的具体措施。"},{"i":24,"n":"第二十四条","txt":"电气设备应当有接地、过流、漏电保护装置。变电所应当有独立的避雷系统和防火、防潮与防止小动物窜入带电部位的措施。"},{"i":25,"n":"第二十五条","txt":"小型露天采石场应当制定完善的防洪措施。对开采境界上方汇水影响安全的，应当设置截水沟。"},{"i":26,"n":"第二十六条","txt":"小型露天采石场应当制定应急救援预案，建立兼职救援队伍，明确救援人员的职责，并与邻近的矿山救护队或者其他具备救护条件的单位签订救护协议。发生生产安全事故时，应当立即组织抢救，并在1小时内向当地安全生产监督管理部门报告。"},{"i":27,"n":"第二十七条","txt":"小型露天采石场应当加强粉尘检测和防治工作，采取有效措施防治职业危害，建立职工健康档案，为从业人员提供符合国家标准或者行业标准的劳动防护用品和劳动保护设施，并指导监督其正确使用。"},{"i":28,"n":"第二十八条","txt":"小型露天采石场应当在每年年末测绘采石场开采现状平面图和剖面图，并归档管理。"},{"i":29,"n":"第二十九条","txt":"安全生产监督管理部门应当加强对小型露天采石场的监督检查，对检查中发现的事故隐患和安全生产违法违规行为，依法作出现场处理或者实施行政处罚。"},{"i":30,"n":"第三十条","txt":"安全生产监督管理部门应当建立健全本行政区域内小型露天采石场的安全生产档案，记录监督检查结果、生产安全事故和违法行为查处等情况。"},{"i":31,"n":"第三十一条","txt":"对于未委托具备相应资质的设计单位编制开采设计或者开采方案，以及周边300米范围内存在生产生活设施的小型露天采石场，不得对其进行审查和验收。"},{"i":32,"n":"第三十二条","txt":"安全生产监督管理部门应当加强对小型露天采石场实施中深孔爆破条件的监督检查。严格限制小型露天采石场采用浅孔爆破开采方式。"},{"i":33,"n":"第三十三条","txt":"安全生产监督管理部门应当督促小型露天采石场加强对承包作业的采掘施工单位的管理，明确双方安全生产责任。"},{"i":34,"n":"第三十四条","txt":"安全生产监督管理部门应当加强本行政区域内小型露天采石场应急预案的管理，督促乡（镇）人民政府做好事故应急救援的协调工作。"},{"i":35,"n":"第三十五条","txt":"安全生产监督管理部门及其工作人员违反法律法规和本规定，未依法履行对小型露天采石场安全生产监督检查职责的，依法给予行政处分。"},{"i":36,"n":"第三十六条","txt":"违反本规定第六条规定的，责令限期改正，并处1万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本规定第十条规定的，责令停止建设或者停产停业整顿，限期改正；逾期未改正的，处50万元以上100万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"违反本规定第十一条第一款规定的，责令停止生产，没收违法所得，并处10万元以上50万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"违反本规定第十二条、第十三条第一、二款、第十四条、第十五条、第十六条、第十七条、第十九条、第二十条第一款、第二十一条、第二十二条规定的，给予警告，并处1万元以上3万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"违反本规定第二十三条、第二十四条、第二十五条、第二十八条规定的，给予警告，并处2万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"本规定规定的行政处罚由安全生产监督管理部门决定。法律、行政法规对行政处罚另有规定的，依照其规定。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市人民政府安全生产监督管理部门可以根据本规定制定实施细则，报国家安全生产监督管理总局备案。"},{"i":43,"n":"第四十三条","txt":"本规定自2011年7月1日起施行。2004年12月28日原国家安全生产监督管理局（国家煤矿安全监察局）公布的《小型露天采石场安全生产暂行规定》（原国家安全生产监督管理局<国家煤矿安全监察局>令第19号）同时废止。"}],"weikuangkuanquanjianduguanliguiding":[{"i":1,"n":"第一条","txt":"为了预防和减少尾矿库生产安全事故，保障人民群众生命和财产安全，根据《安全生产法》、《矿山安全法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"尾矿库的建设、运行、回采、闭库及其安全管理与监督工作，适用本规定。 核工业矿山尾矿库、电厂灰渣库的安全监督管理工作，不适用本规定。"},{"i":3,"n":"第三条","txt":"尾矿库建设、运行、回采、闭库的安全技术要求以及尾矿库等别划分标准，按照《尾矿库安全技术规程》（AQ2006-2005）执行。"},{"i":4,"n":"第四条","txt":"尾矿库生产经营单位（以下简称生产经营单位）应当建立健全尾矿库安全生产责任制，建立健全安全生产规章制度和安全技术操作规程，对尾矿库实施有效的安全管理。"},{"i":5,"n":"第五条","txt":"生产经营单位应当保证尾矿库具备安全生产条件所必需的资金投入，建立相应的安全管理机构或者配备相应的安全管理人员、专业技术人员。"},{"i":6,"n":"第六条","txt":"生产经营单位主要负责人和安全管理人员应当依照有关规定经培训考核合格并取得安全资格证书。 直接从事尾矿库放矿、筑坝、巡坝、排洪和排渗设施操作的作业人员必须取得特种作业操作证书，方可上岗作业。"},{"i":7,"n":"第七条","txt":"国家安全生产监督管理总局负责在国务院规定的职责范围内对有关尾矿库建设项目进行安全设施设计审查。 前款规定以外的其他尾矿库建设项目安全设施设计审查，由省级安全生产监督管理部门按照分级管理的原则作出规定。"},{"i":8,"n":"第八条","txt":"鼓励生产经营单位应用尾矿库在线监测、尾矿充填、干式排尾、尾矿综合利用等先进适用技术。 一等、二等、三等尾矿库应当安装在线监测系统。 鼓励生产经营单位将尾矿回采再利用后进行回填。"},{"i":9,"n":"第九条","txt":"尾矿库建设项目包括新建、改建、扩建以及回采、闭库的尾矿库建设工程。 尾矿库建设项目安全设施设计审查与竣工验收应当符合有关法律、行政法规的规定。"},{"i":10,"n":"第十条","txt":"尾矿库的勘察单位应当具有矿山工程或者岩土工程类勘察资质。设计单位应当具有金属非金属矿山工程设计资质。安全评价单位应当具有尾矿库评价资质。施工单位应当具有矿山工程施工资质。施工监理单位应当具有矿山工程监理资质。 尾矿库的勘察、设计、安全评价、施工、监理等单位除符合前款规定外，还应当按照尾矿库的等别符合下列规定： （一）一等、二等、三等尾矿库建设项目，其勘察、设计、安全评价、监理单位具有甲级资质，施工单位具有总承包一级或者特级资质； （二）四等、五等尾矿库建设项目，其勘察、设计、安全评价、监理单位具有乙级或者乙级以上资质，施工单位具有总承包三级或者三级以上资质，或者专业承包一级、二级资质。"},{"i":11,"n":"第十一条","txt":"尾矿库建设项目应当进行安全设施设计，对尾矿库库址及尾矿坝稳定性、尾矿库防洪能力、排洪设施和安全观测设施的可靠性进行充分论证。"},{"i":12,"n":"第十二条","txt":"尾矿库库址应当由设计单位根据库容、坝高、库区地形条件、水文地质、气象、下游居民区和重要工业构筑物等情况，经科学论证后，合理确定。"},{"i":13,"n":"第十三条","txt":"尾矿库建设项目应当进行安全设施设计并经安全生产监督管理部门审查批准后方可施工。无安全设施设计或者安全设施设计未经审查批准的，不得施工。 严禁未经设计并审查批准擅自加高尾矿库坝体。"},{"i":14,"n":"第十四条","txt":"尾矿库施工应当执行有关法律、行政法规和国家标准、行业标准的规定，严格按照设计施工，确保工程质量，并做好施工记录。 生产经营单位应当建立尾矿库工程档案和日常管理档案，特别是隐蔽工程档案、安全检查档案和隐患排查治理档案，并长期保存。"},{"i":15,"n":"第十五条","txt":"施工中需要对设计进行局部修改的，应当经原设计单位同意；对涉及尾矿库库址、等别、排洪方式、尾矿坝坝型等重大设计变更的，应当报原审批部门批准。"},{"i":16,"n":"第十六条","txt":"尾矿库建设项目安全设施试运行应当向安全生产监督管理部门书面报告，试运行时间不得超过6个月，且尾砂排放不得超过初期坝坝顶标高。试运行结束后，建设单位应当组织安全设施竣工验收，并形成书面报告备查。 安全生产监督管理部门应当加强对建设单位验收活动和验收结果的监督核查。"},{"i":17,"n":"第十七条","txt":"尾矿库建设项目安全设施经验收合格后，生产经营单位应当及时按照《非煤矿矿山企业安全生产许可证实施办法》的有关规定，申请尾矿库安全生产许可证。未依法取得安全生产许可证的尾矿库，不得投入生产运行。 生产经营单位在申请尾矿库安全生产许可证时，对于验收申请时已提交的符合颁证条件的文件、资料可以不再提交；安全生产监督管理部门在审核颁发安全生产许可证时，可以不再审查。"},{"i":18,"n":"第十八条","txt":"对生产运行的尾矿库，未经技术论证和安全生产监督管理部门的批准，任何单位和个人不得对下列事项进行变更： （一）筑坝方式； （二）排放方式； （三）尾矿物化特性； （四）坝型、坝外坡坡比、最终堆积标高和最终坝轴线的位置； （五）坝体防渗、排渗及反滤层的设置； （六）排洪系统的型式、布置及尺寸； （七）设计以外的尾矿、废料或者废水进库等。"},{"i":19,"n":"第十九条","txt":"尾矿库应当每三年至少进行一次安全现状评价。安全现状评价应当符合国家标准或者行业标准的要求。 尾矿库安全现状评价工作应当有能够进行尾矿坝稳定性验算、尾矿库水文计算、构筑物计算的专业技术人员参加。 上游式尾矿坝堆积至二分之一至三分之二最终设计坝高时，应当对坝体进行一次全面勘察，并进行稳定性专项评价。"},{"i":20,"n":"第二十条","txt":"尾矿库经安全现状评价或者专家论证被确定为危库、险库和病库的，生产经营单位应当分别采取下列措施： （一）确定为危库的，应当立即停产，进行抢险，并向尾矿库所在地县级人民政府、安全生产监督管理部门和上级主管单位报告； （二）确定为险库的，应当立即停产，在限定的时间内消除险情，并向尾矿库所在地县级人民政府、安全生产监督管理部门和上级主管单位报告； （三）确定为病库的，应当在限定的时间内按照正常库标准进行整治，消除事故隐患。"},{"i":21,"n":"第二十一条","txt":"生产经营单位应当建立健全防汛责任制，实施24小时监测监控和值班值守，并针对可能发生的垮坝、漫顶、排洪设施损毁等生产安全事故和影响尾矿库运行的洪水、泥石流、山体滑坡、地震等重大险情制定并及时修订应急救援预案，配备必要的应急救援器材、设备，放置在便于应急时使用的地方。 应急预案应当按照规定报相应的安全生产监督管理部门备案，并每年至少进行一次演练。"},{"i":22,"n":"第二十二条","txt":"生产经营单位应当编制尾矿库年度、季度作业计划，严格按照作业计划生产运行，做好记录并长期保存。"},{"i":23,"n":"第二十三条","txt":"生产经营单位应当建立尾矿库事故隐患排查治理制度，按照本规定和《尾矿库安全技术规程》的规定，及时发现并消除事故隐患。事故隐患排查治理情况应当如实记录，建立隐患排查治理档案，并向从业人员通报。"},{"i":24,"n":"第二十四条","txt":"尾矿库出现下列重大险情之一的，生产经营单位应当按照安全监管权限和职责立即报告当地县级安全生产监督管理部门和人民政府，并启动应急预案，进行抢险： （一）坝体出现严重的管涌、流土等现象的； （二）坝体出现严重裂缝、坍塌和滑动迹象的； （三）库内水位超过限制的最高洪水位的； （四）在用排水井倒塌或者排水管（洞）坍塌堵塞的； （五）其他危及尾矿库安全的重大险情。"},{"i":25,"n":"第二十五条","txt":"尾矿库发生坝体坍塌、洪水漫顶等事故时，生产经营单位应当立即启动应急预案，进行抢险，防止事故扩大，避免和减少人员伤亡及财产损失，并立即报告当地县级安全生产监督管理部门和人民政府。"},{"i":26,"n":"第二十六条","txt":"未经生产经营单位进行技术论证并同意，以及尾矿库建设项目安全设施设计原审批部门批准，任何单位和个人不得在库区从事爆破、采砂、地下采矿等危害尾矿库安全的作业。"},{"i":27,"n":"第二十七条","txt":"尾矿回采再利用工程应当进行回采勘察、安全预评价和回采设计，回采设计应当包括安全设施设计，并编制安全专篇。 回采安全设施设计应当报安全生产监督管理部门审查批准。 生产经营单位应当按照回采设计实施尾矿回采，并在尾矿回采期间进行日常安全管理和检查，防止尾矿回采作业对尾矿坝安全造成影响。 尾矿全部回采后不再进行排尾作业的，生产经营单位应当及时报安全生产监督管理部门履行尾矿库注销手续。具体办法由省级安全生产监督管理部门制定。"},{"i":28,"n":"第二十八条","txt":"尾矿库运行到设计最终标高或者不再进行排尾作业的，应当在一年内完成闭库。特殊情况不能按期完成闭库的，应当报经相应的安全生产监督管理部门同意后方可延期，但延长期限不得超过6个月。 库容小于10万立方米且总坝高低于10米的小型尾矿库闭库程序，由省级安全生产监督管理部门根据本地实际制定。"},{"i":29,"n":"第二十九条","txt":"尾矿库运行到设计最终标高的前12个月内，生产经营单位应当进行闭库前的安全现状评价和闭库设计，闭库设计应当包括安全设施设计。 闭库安全设施设计应当经有关安全生产监督管理部门审查批准。"},{"i":30,"n":"第三十条","txt":"尾矿库闭库工程安全设施验收，应当具备下列条件： （一）尾矿库已停止使用； （二）尾矿库闭库工程安全设施设计已经有关安全生产监督管理部门审查批准； （三）有完备的闭库工程安全设施施工记录、竣工报告、竣工图和施工监理报告等； （四）法律、行政法规和国家标准、行业标准规定的其他条件。"},{"i":31,"n":"第三十一条","txt":"尾矿库闭库工程安全设施验收应当审查下列内容及资料： （一）尾矿库库址所在行政区域位置、占地面积及尾矿库下游村庄、居民等情况； （二）尾矿库建设和运行时间以及在建设和运行中曾经出现过的重大问题及其处理措施； （三）尾矿库主要技术参数，包括初期坝结构、筑坝材料、堆坝方式、坝高、总库容、尾矿坝外坡坡比、尾矿粒度、尾矿堆积量、防洪排水型式等； （四）闭库工程安全设施设计及审批文件； （五）闭库工程安全设施设计的主要工程措施和闭库工程施工概况； （六）闭库工程安全验收评价报告； （七）闭库工程安全设施竣工报告及竣工图； （八）施工监理报告； （九）其他相关资料。"},{"i":32,"n":"第三十二条","txt":"尾矿库闭库工作及闭库后的安全管理由原生产经营单位负责。对解散或者关闭破产的生产经营单位，其已关闭或者废弃的尾矿库的管理工作，由生产经营单位出资人或其上级主管单位负责；无上级主管单位或者出资人不明确的，由安全生产监督管理部门提请县级以上人民政府指定管理单位。"},{"i":33,"n":"第三十三条","txt":"安全生产监督管理部门应当严格按照有关法律、行政法规、国家标准、行业标准以及本规定要求和“分级属地”的原则，进行尾矿库建设项目安全设施设计审查；不符合规定条件的，不得批准。审查不得收取费用。"},{"i":34,"n":"第三十四条","txt":"安全生产监督管理部门应当建立本行政区域内尾矿库安全生产监督检查档案，记录监督检查结果、生产安全事故及违法行为查处等情况。"},{"i":35,"n":"第三十五条","txt":"安全生产监督管理部门应当加强对尾矿库生产经营单位安全生产的监督检查，对检查中发现的事故隐患和违法违规生产行为，依法作出处理。"},{"i":36,"n":"第三十六条","txt":"安全生产监督管理部门应当建立尾矿库安全生产举报制度，公开举报电话、信箱或者电子邮件地址，受理有关举报；对受理的举报，应当认真调查核实；经查证属实的，应当依法作出处理。"},{"i":37,"n":"第三十七条","txt":"安全生产监督管理部门应当加强本行政区域内生产经营单位应急预案的备案管理，并将尾矿库事故应急救援纳入地方各级人民政府应急救援体系。"},{"i":38,"n":"第三十八条","txt":"安全生产监督管理部门的工作人员，未依法履行尾矿库安全监督管理职责的，依照有关规定给予行政处分。"},{"i":39,"n":"第三十九条","txt":"生产经营单位或者尾矿库管理单位违反本规定第八条第二款、第十九条、第二十条、第二十一条、第二十二条、第二十四条、第二十六条、第二十九条第一款规定的，给予警告，并处1万元以上3万元以下的罚款；对主管人员和直接责任人员由其所在单位或者上级主管单位给予行政处分；构成犯罪的，依法追究刑事责任。 生产经营单位或者尾矿库管理单位违反本规定第二十三条规定的，依照《安全生产法》实施处罚。"},{"i":40,"n":"第四十条","txt":"生产经营单位或者尾矿库管理单位违反本规定第十八条规定的，给予警告，并处3万元的罚款；情节严重的，依法责令停产整顿或者提请县级以上地方人民政府按照规定权限予以关闭。"},{"i":41,"n":"第四十一条","txt":"生产经营单位违反本规定第二十八条第一款规定不主动实施闭库的，给予警告，并处3万元的罚款。"},{"i":42,"n":"第四十二条","txt":"本规定规定的行政处罚由安全生产监督管理部门决定。 法律、行政法规对行政处罚决定机关和处罚种类、幅度另有规定的，依照其规定。"},{"i":43,"n":"第四十三条","txt":"本规定自2011年7月1日起施行。国家安全生产监督管理总局2006年公布的《尾矿库安全监督管理规定》（国家安全生产监督管理总局令第6号）同时废止。"}],"gongmaoqiyeyouxiankongjianzuoyeanquanguanliyujiand481743":[{"i":1,"n":"第一条","txt":"为了加强对冶金、有色、建材、机械、轻工、纺织、烟草、商贸企业（以下统称工贸企业）有限空间作业的安全管理与监督，预防和减少生产安全事故，保障作业人员的安全与健康，根据《中华人民共和国安全生产法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"工贸企业有限空间作业的安全管理与监督，适用本规定。 本规定所称有限空间，是指封闭或者部分封闭，与外界相对隔离，出入口较为狭窄，作业人员不能长时间在内工作，自然通风不良，易造成有毒有害、易燃易爆物质积聚或者氧含量不足的空间。工贸企业有限空间的目录由国家安全生产监督管理总局确定、调整并公布。"},{"i":3,"n":"第三条","txt":"工贸企业是本企业有限空间作业安全的责任主体，其主要负责人对本企业有限空间作业安全全面负责，相关负责人在各自职责范围内对本企业有限空间作业安全负责。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局对全国工贸企业有限空间作业安全实施监督管理。 县级以上地方各级安全生产监督管理部门按照属地监管、分级负责的原则，对本行政区域内工贸企业有限空间作业安全实施监督管理。省、自治区、直辖市人民政府对工贸企业有限空间作业的安全生产监督管理职责另有规定的，依照其规定。"},{"i":5,"n":"第五条","txt":"存在有限空间作业的工贸企业应当建立下列安全生产制度和规程： （一）有限空间作业安全责任制度； （二）有限空间作业审批制度； （三）有限空间作业现场安全管理制度； （四）有限空间作业现场负责人、监护人员、作业人员、应急救援人员安全培训教育制度； （五）有限空间作业应急管理制度； （六）有限空间作业安全操作规程。"},{"i":6,"n":"第六条","txt":"工贸企业应当对从事有限空间作业的现场负责人、监护人员、作业人员、应急救援人员进行专项安全培训。专项安全培训应当包括下列内容： （一）有限空间作业的危险有害因素和安全防范措施； （二）有限空间作业的安全操作规程； （三）检测仪器、劳动防护用品的正确使用； （四）紧急情况下的应急处置措施。 安全培训应当有专门记录，并由参加培训的人员签字确认。"},{"i":7,"n":"第七条","txt":"工贸企业应当对本企业的有限空间进行辨识，确定有限空间的数量、位置以及危险有害因素等基本情况，建立有限空间管理台账，并及时更新。"},{"i":8,"n":"第八条","txt":"工贸企业实施有限空间作业前，应当对作业环境进行评估，分析存在的危险有害因素，提出消除、控制危害的措施，制定有限空间作业方案，并经本企业安全生产管理人员审核，负责人批准。"},{"i":9,"n":"第九条","txt":"工贸企业应当按照有限空间作业方案，明确作业现场负责人、监护人员、作业人员及其安全职责。"},{"i":10,"n":"第十条","txt":"工贸企业实施有限空间作业前，应当将有限空间作业方案和作业现场可能存在的危险有害因素、防控措施告知作业人员。现场负责人应当监督作业人员按照方案进行作业准备。"},{"i":11,"n":"第十一条","txt":"工贸企业应当采取可靠的隔断（隔离）措施，将可能危及作业安全的设施设备、存在有毒有害物质的空间与作业地点隔开。"},{"i":12,"n":"第十二条","txt":"有限空间作业应当严格遵守“先通风、再检测、后作业”的原则。检测指标包括氧浓度、易燃易爆物质（可燃性气体、爆炸性粉尘）浓度、有毒有害气体浓度。检测应当符合相关国家标准或者行业标准的规定。 未经通风和检测合格，任何人员不得进入有限空间作业。检测的时间不得早于作业开始前30分钟。"},{"i":13,"n":"第十三条","txt":"检测人员进行检测时，应当记录检测的时间、地点、气体种类、浓度等信息。检测记录经检测人员签字后存档。 检测人员应当采取相应的安全防护措施，防止中毒窒息等事故发生。"},{"i":14,"n":"第十四条","txt":"有限空间内盛装或者残留的物料对作业存在危害时，作业人员应当在作业前对物料进行清洗、清空或者置换。经检测，有限空间的危险有害因素符合《工作场所有害因素职业接触限值第一部分化学有害因素》（GBZ2.1）的要求后，方可进入有限空间作业。"},{"i":15,"n":"第十五条","txt":"在有限空间作业过程中，工贸企业应当采取通风措施，保持空气流通，禁止采用纯氧通风换气。 发现通风设备停止运转、有限空间内氧含量浓度低于或者有毒有害气体浓度高于国家标准或者行业标准规定的限值时，工贸企业必须立即停止有限空间作业，清点作业人员，撤离作业现场。"},{"i":16,"n":"第十六条","txt":"在有限空间作业过程中，工贸企业应当对作业场所中的危险有害因素进行定时检测或者连续监测。 作业中断超过30分钟，作业人员再次进入有限空间作业前，应当重新通风、检测合格后方可进入。"},{"i":17,"n":"第十七条","txt":"有限空间作业场所的照明灯具电压应当符合《特低电压限值》（GB/T3805）等国家标准或者行业标准的规定；作业场所存在可燃性气体、粉尘的，其电气设施设备及照明灯具的防爆安全要求应当符合《爆炸性环境第一部分：设备通用要求》（GB3836.1）等国家标准或者行业标准的规定。"},{"i":18,"n":"第十八条","txt":"工贸企业应当根据有限空间存在危险有害因素的种类和危害程度，为作业人员提供符合国家标准或者行业标准规定的劳动防护用品，并教育监督作业人员正确佩戴与使用。"},{"i":19,"n":"第十九条","txt":"工贸企业有限空间作业还应当符合下列要求： （一）保持有限空间出入口畅通； （二）设置明显的安全警示标志和警示说明； （三）作业前清点作业人员和工器具； （四）作业人员与外部有可靠的通讯联络； （五）监护人员不得离开作业现场，并与作业人员保持联系； （六）存在交叉作业时，采取避免互相伤害的措施。"},{"i":20,"n":"第二十条","txt":"有限空间作业结束后，作业现场负责人、监护人员应当对作业现场进行清理，撤离作业人员。"},{"i":21,"n":"第二十一条","txt":"工贸企业应当根据本企业有限空间作业的特点，制定应急预案，并配备相关的呼吸器、防毒面罩、通讯设备、安全绳索等应急装备和器材。有限空间作业的现场负责人、监护人员、作业人员和应急救援人员应当掌握相关应急预案内容，定期进行演练，提高应急处置能力。"},{"i":22,"n":"第二十二条","txt":"工贸企业将有限空间作业发包给其他单位实施的，应当发包给具备国家规定资质或者安全生产条件的承包方，并与承包方签订专门的安全生产管理协议或者在承包合同中明确各自的安全生产职责。工贸企业应当对承包单位的安全生产工作统一协调、管理，定期进行安全检查，发现安全问题的，应当及时督促整改。 工贸企业对其发包的有限空间作业安全承担主体责任。承包方对其承包的有限空间作业安全承担直接责任。"},{"i":23,"n":"第二十三条","txt":"有限空间作业中发生事故后，现场有关人员应当立即报警，禁止盲目施救。应急救援人员实施救援时，应当做好自身防护，佩戴必要的呼吸器具、救援器材。"},{"i":24,"n":"第二十四条","txt":"安全生产监督管理部门应当加强对工贸企业有限空间作业的监督检查，将检查纳入年度执法工作计划。对发现的事故隐患和违法行为，依法作出处理。"},{"i":25,"n":"第二十五条","txt":"安全生产监督管理部门对工贸企业有限空间作业实施监督检查时，应当重点抽查有限空间作业安全管理制度、有限空间管理台账、检测记录、劳动防护用品配备、应急救援演练、专项安全培训等情况。"},{"i":26,"n":"第二十六条","txt":"安全生产监督管理部门应当加强对行政执法人员的有限空间作业安全知识培训，并为检查有限空间作业安全的行政执法人员配备必需的劳动防护用品、检测仪器。"},{"i":27,"n":"第二十七条","txt":"安全生产监督管理部门及其行政执法人员发现有限空间作业存在重大事故隐患的，应当责令立即或者限期整改；重大事故隐患排除前或者排除过程中无法保证安全的，应当责令暂时停止作业，撤出作业人员；重大事故隐患排除后，经审查同意，方可恢复作业。"},{"i":28,"n":"第二十八条","txt":"工贸企业有下列行为之一的，由县级以上安全生产监督管理部门责令限期改正，可以处5万元以下的罚款；逾期未改正的，处5万元以上20万元以下的罚款，其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；情节严重的，责令停产停业整顿： （一）未在有限空间作业场所设置明显的安全警示标志的； （二）未按照本规定为作业人员提供符合国家标准或者行业标准的劳动防护用品的。"},{"i":29,"n":"第二十九条","txt":"工贸企业有下列情形之一的，由县级以上安全生产监督管理部门责令限期改正，可以处5万元以下的罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款： （一）未按照本规定对有限空间的现场负责人、监护人员、作业人员和应急救援人员进行安全培训的； （二）未按照本规定对有限空间作业制定应急预案，或者定期进行演练的。"},{"i":30,"n":"第三十条","txt":"工贸企业有下列情形之一的，由县级以上安全生产监督管理部门责令限期改正，可以处3万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以下的罚款： （一）未按照本规定对有限空间作业进行辨识、提出防范措施、建立有限空间管理台账的； （二）未按照本规定对有限空间作业制定作业方案或者方案未经审批擅自作业的； （三）有限空间作业未按照本规定进行危险有害因素检测或者监测，并实行专人监护作业的。"},{"i":31,"n":"第三十一条","txt":"本规定自2013年7月1日起施行。"}],"gongmaoqiyefenchenfangbaoanquanguiding":[{"i":1,"n":"第一条","txt":"为了加强工贸企业粉尘防爆安全工作，预防和减少粉尘爆炸事故，保障从业人员生命安全，根据《中华人民共和国安全生产法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"存在可燃性粉尘爆炸危险的冶金、有色、建材、机械、轻工、纺织、烟草、商贸等工贸企业（以下简称粉尘涉爆企业）的粉尘防爆安全工作及其监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称可燃性粉尘，是指在大气条件下，能与气态氧化剂（主要是空气）发生剧烈氧化反应的粉尘、纤维或者飞絮。 本规定所称粉尘爆炸危险场所，是指存在可燃性粉尘和气态氧化剂（主要是空气）的场所，根据爆炸性环境出现的频率或者持续的时间，可划分为不同危险区域。"},{"i":4,"n":"第四条","txt":"粉尘涉爆企业对粉尘防爆安全工作负主体责任，应当具备有关法律法规、规章、国家标准或者行业标准规定的粉尘防爆安全生产条件，建立健全全员安全生产责任制和相关规章制度，加强安全生产标准化、信息化建设，构建安全风险分级管控和隐患排查治理双重预防机制，健全风险防范化解机制，确保安全生产。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府负责粉尘涉爆企业安全生产监督管理的部门（以下统称负责粉尘涉爆企业安全监管的部门），根据本级人民政府规定的职责，按照分级属地的原则，对本行政区域内粉尘涉爆企业的粉尘防爆安全工作实施监督管理。 国务院应急管理部门应当加强指导监督。"},{"i":6,"n":"第六条","txt":"粉尘涉爆企业主要负责人是粉尘防爆安全工作的第一责任人，其他负责人在各自职责范围内对粉尘防爆安全工作负责。 粉尘涉爆企业应当在本单位安全生产责任制中明确主要负责人、相关部门负责人、生产车间负责人及粉尘作业岗位人员粉尘防爆安全职责。"},{"i":7,"n":"第七条","txt":"粉尘涉爆企业应当结合企业实际情况建立和落实粉尘防爆安全管理制度。粉尘防爆安全管理制度应当包括下列内容： （一）粉尘爆炸风险辨识评估和管控； （二）粉尘爆炸事故隐患排查治理； （三）粉尘作业岗位安全操作规程； （四）粉尘防爆专项安全生产教育和培训； （五）粉尘清理和处置； （六）除尘系统和相关安全设施设备运行、维护及检修、维修管理； （七）粉尘爆炸事故应急处置和救援。"},{"i":8,"n":"第八条","txt":"粉尘涉爆企业应当组织对涉及粉尘防爆的生产、设备、安全管理等有关负责人和粉尘作业岗位等相关从业人员进行粉尘防爆专项安全生产教育和培训，使其了解作业场所和工作岗位存在的爆炸风险，掌握粉尘爆炸事故防范和应急措施；未经教育培训合格的，不得上岗作业。 粉尘涉爆企业应当如实记录粉尘防爆专项安全生产教育和培训的时间、内容及考核等情况，纳入员工教育和培训档案。"},{"i":9,"n":"第九条","txt":"粉尘涉爆企业应当为粉尘作业岗位从业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育从业人员按照使用规则佩戴、使用。"},{"i":10,"n":"第十条","txt":"粉尘涉爆企业应当制定有关粉尘爆炸事故应急救援预案，并依法定期组织演练。发生火灾或者粉尘爆炸事故后，粉尘涉爆企业应当立即启动应急响应并撤离疏散全部作业人员至安全场所，不得采用可能引起扬尘的应急处置措施。"},{"i":11,"n":"第十一条","txt":"粉尘涉爆企业应当定期辨识粉尘云、点燃源等粉尘爆炸危险因素，确定粉尘爆炸危险场所的位置、范围，并根据粉尘爆炸特性和涉粉作业人数等关键要素，评估确定有关危险场所安全风险等级，制定并落实管控措施，明确责任部门和责任人员，建立安全风险清单，及时维护安全风险辨识、评估、管控过程的信息档案。 粉尘涉爆企业应当在粉尘爆炸较大危险因素的工艺、场所、设施设备和岗位，设置安全警示标志。 涉及粉尘爆炸危险的工艺、场所、设施设备等发生变更的，粉尘涉爆企业应当重新进行安全风险辨识评估。"},{"i":12,"n":"第十二条","txt":"粉尘涉爆企业应当根据《粉尘防爆安全规程》等有关国家标准或者行业标准，结合粉尘爆炸风险管控措施，建立事故隐患排查清单，明确和细化排查事项、具体内容、排查周期及责任人员，及时组织开展事故隐患排查治理，如实记录隐患排查治理情况，并向从业人员通报。 构成工贸行业重大事故隐患判定标准规定的重大事故隐患的，应当按照有关规定制定治理方案，落实措施、责任、资金、时限和应急预案，及时消除事故隐患。"},{"i":13,"n":"第十三条","txt":"粉尘涉爆企业新建、改建、扩建涉及粉尘爆炸危险的工程项目安全设施的设计、施工应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准，在安全设施设计文件、施工方案中明确粉尘防爆的相关内容。 设计单位应当对安全设施粉尘防爆相关的设计负责，施工单位应当按照设计进行施工，并对施工质量负责。"},{"i":14,"n":"第十四条","txt":"粉尘涉爆企业存在粉尘爆炸危险场所的建（构）筑物的结构和布局应当符合《粉尘防爆安全规程》等有关国家标准或者行业标准要求，采取防火防爆、防雷等措施，单层厂房屋顶一般应当采用轻型结构，多层厂房应当为框架结构，并设置符合有关标准要求的泄压面积。 粉尘涉爆企业应当严格控制粉尘爆炸危险场所内作业人员数量，在粉尘爆炸危险场所内不得设置员工宿舍、休息室、办公室、会议室等，粉尘爆炸危险场所与其他厂房、仓库、民用建筑的防火间距应当符合《建筑设计防火规范》的规定。"},{"i":15,"n":"第十五条","txt":"粉尘涉爆企业应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准规定，将粉尘爆炸危险场所除尘系统按照不同工艺分区域相对独立设置，可燃性粉尘不得与可燃气体等易加剧爆炸危险的介质共用一套除尘系统，不同防火分区的除尘系统禁止互联互通。存在粉尘爆炸危险的工艺设备应当采用泄爆、隔爆、惰化、抑爆、抗爆等一种或者多种控爆措施，但不得单独采取隔爆措施。禁止采用粉尘沉降室除尘或者采用巷道式构筑物作为除尘风道。铝镁等金属粉尘应当采用负压方式除尘，其他粉尘受工艺条件限制，采用正压方式吹送时，应当采取可靠的防范点燃源的措施。 采用干式除尘系统的粉尘涉爆企业应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准规定，结合工艺实际情况，安装使用锁气卸灰、火花探测熄灭、风压差监测等装置，以及相关安全设备的监测预警信息系统，加强对可能存在点燃源和粉尘云的粉尘爆炸危险场所的实时监控。铝镁等金属粉尘湿式除尘系统应当安装"},{"i":16,"n":"第十六条","txt":"针对粉碎、研磨、造粒、砂光等易产生机械点燃源的工艺，粉尘涉爆企业应当规范采取杂物去除或者火花探测消除等防范点燃源措施，并定期清理维护，做好相关记录。"},{"i":17,"n":"第十七条","txt":"粉尘防爆相关的泄爆、隔爆、抑爆、惰化、锁气卸灰、除杂、监测、报警、火花探测消除等安全设备的设计、制造、安装、使用、检测、维修、改造和报废，应当符合《粉尘防爆安全规程》等有关国家标准或者行业标准，相关设计、制造、安装单位应当提供相关设备安全性能和使用说明等资料，对安全设备的安全性能负责。 粉尘涉爆企业应当对粉尘防爆安全设备进行经常性维护、保养，并按照《粉尘防爆安全规程》等有关国家标准或者行业标准定期检测或者检查，保证正常运行，做好相关记录，不得关闭、破坏直接关系粉尘防爆安全的监控、报警、防控等设备、设施，或者篡改、隐瞒、销毁其相关数据、信息。粉尘涉爆企业应当规范选用与爆炸危险区域相适应的防爆型电气设备。"},{"i":18,"n":"第十八条","txt":"粉尘涉爆企业应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准，制定并严格落实粉尘爆炸危险场所的粉尘清理制度，明确清理范围、清理周期、清理方式和责任人员，并在相关粉尘爆炸危险场所醒目位置张贴。相关责任人员应当定期清理粉尘并如实记录，确保可能积尘的粉尘作业区域和设备设施全面及时规范清理。粉尘作业区域应当保证每班清理。 铝镁等金属粉尘和镁合金废屑的收集、贮存等处置环节，应当避免粉尘废屑大量堆积或者装袋后多层堆垛码放；需要临时存放的，应当设置相对独立的暂存场所，远离作业现场等人员密集场所，并采取防水防潮、通风、氢气监测等必要的防火防爆措施。含水镁合金废屑应当优先采用机械压块处理方式，镁合金粉尘应当优先采用大量水浸泡方式暂存。"},{"i":19,"n":"第十九条","txt":"粉尘涉爆企业对粉尘爆炸危险场所设备设施或者除尘系统的检修维修作业，应当实行专项作业审批。作业前，应当制定专项方案；对存在粉尘沉积的除尘器、管道等设施设备进行动火作业前，应当清理干净内部积尘和作业区域的可燃性粉尘。作业时，生产设备应当处于停止运行状态，检修维修工具应当采用防止产生火花的防爆工具。作业后，应当妥善清理现场，作业点最高温度恢复到常温后方可重新开始生产。"},{"i":20,"n":"第二十条","txt":"粉尘涉爆企业应当做好粉尘爆炸危险场所设施设备的维护保养，加强对检修承包单位的安全管理，在承包协议中明确规定双方的安全生产权利义务，对检修承包单位的检修方案中涉及粉尘防爆的安全措施和应急处置措施进行审核，并监督承包单位落实。"},{"i":21,"n":"第二十一条","txt":"安全生产技术服务机构为粉尘涉爆企业提供粉尘防爆相关的安全评价、检测、检验、风险评估、隐患排查等安全生产技术服务，应当按照法律、法规、规章和《粉尘防爆安全规程》等有关国家标准或者行业标准开展工作，保证其出具的报告和作出的结果真实、准确、完整，不得弄虚作假。"},{"i":22,"n":"第二十二条","txt":"负责粉尘涉爆企业安全监管的部门应当按照分级属地原则，加强对企业粉尘防爆安全工作的监督检查，制定并落实年度监督检查计划，将粉尘作业人数多、爆炸风险较高的企业作为重点检查对象。"},{"i":23,"n":"第二十三条","txt":"负责粉尘涉爆企业安全监管的部门对企业实施监督检查时，应当重点检查下列内容: （一）粉尘防爆安全生产责任制和相关安全管理制度的建立、落实情况; （二）粉尘爆炸风险清单和辨识管控信息档案; （三）粉尘爆炸事故隐患排查治理台账; （四）粉尘清理和处置记录; （五）粉尘防爆专项安全生产教育和培训记录； （六）粉尘爆炸危险场所检修、维修、动火等作业安全管理情况； （七）安全设备定期维护保养、检测或者检查等情况； （八）涉及粉尘爆炸危险的安全设施与主体工程同时设计、同时施工、同时投入生产和使用情况； （九）应急预案的制定、演练情况。"},{"i":24,"n":"第二十四条","txt":"负责粉尘涉爆企业安全监管的部门应当按照工贸行业重大事故隐患判定标准、执法检查重点事项等有关标准和规定，对企业除尘系统、防火防爆、粉尘清理处置等重点部位和关键环节的粉尘防爆安全措施落实情况进行监督检查，督促企业落实粉尘防爆安全生产主体责任。"},{"i":25,"n":"第二十五条","txt":"负责粉尘涉爆企业安全监管的部门可以根据需要，委托安全生产技术服务机构提供安全评价、检测、检验、隐患排查等技术服务，并承担相关费用。安全生产技术服务机构对其出具的有关报告和作出的结果负责。 安全生产技术服务机构出具的有关报告或者作出的结果可以作为行政执法的依据之一。 粉尘涉爆企业不得拒绝、阻挠负责粉尘涉爆企业安全监管的部门委托的安全生产技术服务机构开展技术服务工作。"},{"i":26,"n":"第二十六条","txt":"负责粉尘涉爆企业安全监管的部门应当加强对监督检查人员的粉尘防爆专业知识培训，使其了解相关法律法规和标准要求，掌握执法检查重点事项和重大事故隐患判定标准，提高其行政执法能力。"},{"i":27,"n":"第二十七条","txt":"粉尘涉爆企业有下列行为之一的，由负责粉尘涉爆企业安全监管的部门依照《中华人民共和国安全生产法》有关规定，责令限期改正，处5万元以下的罚款；逾期未改正的，处5万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未在产生、输送、收集、贮存可燃性粉尘，并且有较大危险因素的场所、设施和设备上设置明显的安全警示标志的； （二）粉尘防爆安全设备的安装、使用、检测、改造和报废不符合国家标准或者行业标准的； （三）未对粉尘防爆安全设备进行经常性维护、保养和定期检测或者检查的； （四）未为粉尘作业岗位相关从业人员提供符合国家标准或者行业标准的劳动防护用品的； （五）关闭、破坏直接关系粉尘防爆安全的监控、报警、防控等设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的。"},{"i":28,"n":"第二十八条","txt":"粉尘涉爆企业有下列行为之一的，由负责粉尘涉爆企业安全监管的部门依照《中华人民共和国安全生产法》有关规定，责令限期改正，处10万元以下的罚款；逾期未改正的，责令停产停业整顿，并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款： （一）未按照规定对有关负责人和粉尘作业岗位相关从业人员进行粉尘防爆专项安全生产教育和培训，或者未如实记录专项安全生产教育和培训情况的； （二）未如实记录粉尘防爆隐患排查治理情况或者未向从业人员通报的； （三）未制定有关粉尘爆炸事故应急救援预案或者未定期组织演练的。"},{"i":29,"n":"第二十九条","txt":"粉尘涉爆企业违反本规定第十四条、第十五条、第十六条、第十八条、第十九条的规定，同时构成事故隐患，未采取措施消除的，依照《中华人民共和国安全生产法》有关规定，由负责粉尘涉爆企业安全监管的部门责令立即消除或者限期消除，处5万元以下的罚款；企业拒不执行的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":30,"n":"第三十条","txt":"粉尘涉爆企业有下列情形之一的，由负责粉尘涉爆企业安全监管的部门责令限期改正，处3万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以下的罚款： （一）企业新建、改建、扩建工程项目安全设施没有进行粉尘防爆安全设计，或者未按照设计进行施工的； （二）未按照规定建立粉尘防爆安全管理制度或者内容不符合企业实际的； （三）未按照规定辨识评估管控粉尘爆炸安全风险，未建立安全风险清单或者未及时维护相关信息档案的； （四）粉尘防爆安全设备未正常运行的。"},{"i":31,"n":"第三十一条","txt":"安全生产技术服务机构接受委托开展技术服务工作，出具失实报告的，依照《中华人民共和国安全生产法》有关规定，责令停业整顿，并处3万元以上10万元以下的罚款；给他人造成损害的，依法承担赔偿责任。 安全生产技术服务机构接受委托开展技术服务工作，出具虚假报告的，依照《中华人民共和国安全生产法》有关规定，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款；给他人造成损害的，与粉尘涉爆企业承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的安全生产技术服务机构及其直接责任人员，吊销其相应资质和资格，5年内不得从事安全评价、认证、检测、检验等工作，情节严重的，实行终身行业和职业禁入。"},{"i":32,"n":"第三十二条","txt":"本规定自2021年9月1日起施行。"}],"jianshexiangmuanquansheshisantongshijianduguanliba2c9a62":[{"i":1,"n":"第一条","txt":"为加强建设项目安全管理，预防和减少生产安全事故，保障从业人员生命和财产安全，根据《中华人民共和国安全生产法》和《国务院关于进一步加强企业安全生产工作的通知》等法律、行政法规和规定，制定本办法。"},{"i":2,"n":"第二条","txt":"经县级以上人民政府及其有关主管部门依法审批、核准或者备案的生产经营单位新建、改建、扩建工程项目（以下统称建设项目）安全设施的建设及其监督管理，适用本办法。 法律、行政法规及国务院对建设项目安全设施建设及其监督管理另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"本办法所称的建设项目安全设施，是指生产经营单位在生产经营活动中用于预防生产安全事故的设备、设施、装置、构（建）筑物和其他技术措施的总称。"},{"i":4,"n":"第四条","txt":"生产经营单位是建设项目安全设施建设的责任主体。建设项目安全设施必须与主体工程同时设计、同时施工、同时投入生产和使用（以下简称“三同时”）。安全设施投资应当纳入建设项目概算。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局对全国建设项目安全设施“三同时”实施综合监督管理，并在国务院规定的职责范围内承担有关建设项目安全设施“三同时”的监督管理。 县级以上地方各级安全生产监督管理部门对本行政区域内的建设项目安全设施“三同时”实施综合监督管理，并在本级人民政府规定的职责范围内承担本级人民政府及其有关主管部门审批、核准或者备案的建设项目安全设施“三同时”的监督管理。 跨两个及两个以上行政区域的建设项目安全设施“三同时”由其共同的上一级人民政府安全生产监督管理部门实施监督管理。 上一级人民政府安全生产监督管理部门根据工作需要，可以将其负责监督管理的建设项目安全设施“三同时”工作委托下一级人民政府安全生产监督管理部门实施监督管理。"},{"i":6,"n":"第六条","txt":"安全生产监督管理部门应当加强建设项目安全设施建设的日常安全监管，落实有关行政许可及其监管责任，督促生产经营单位落实安全设施建设责任。"},{"i":7,"n":"第七条","txt":"下列建设项目在进行可行性研究时，生产经营单位应当按照国家规定，进行安全预评价： （一）非煤矿矿山建设项目； （二）生产、储存危险化学品（包括使用长输管道输送危险化学品，下同）的建设项目； （三）生产、储存烟花爆竹的建设项目； （四）金属冶炼建设项目； （五）使用危险化学品从事生产并且使用量达到规定数量的化工建设项目（属于危险化学品生产的除外，下同）； （六）法律、行政法规和国务院规定的其他建设项目。"},{"i":8,"n":"第八条","txt":"生产经营单位应当委托具有相应资质的安全评价机构，对其建设项目进行安全预评价，并编制安全预评价报告。 建设项目安全预评价报告应当符合国家标准或者行业标准的规定。 生产、储存危险化学品的建设项目和化工建设项目安全预评价报告除符合本条第二款的规定外，还应当符合有关危险化学品建设项目的规定。"},{"i":9,"n":"第九条","txt":"本办法第七条规定以外的其他建设项目，生产经营单位应当对其安全生产条件和设施进行综合分析，形成书面报告备查。"},{"i":10,"n":"第十条","txt":"生产经营单位在建设项目初步设计时，应当委托有相应资质的设计单位对建设项目安全设施同时进行设计，编制安全设施设计。 安全设施设计必须符合有关法律、法规、规章和国家标准或者行业标准、技术规范的规定，并尽可能采用先进适用的工艺、技术和可靠的设备、设施。本办法第七条规定的建设项目安全设施设计还应当充分考虑建设项目安全预评价报告提出的安全对策措施。 安全设施设计单位、设计人应当对其编制的设计文件负责。"},{"i":11,"n":"第十一条","txt":"建设项目安全设施设计应当包括下列内容： （一）设计依据； （二）建设项目概述； （三）建设项目潜在的危险、有害因素和危险、有害程度及周边环境安全分析； （四）建筑及场地布置； （五）重大危险源分析及检测监控； （六）安全设施设计采取的防范措施； （七）安全生产管理机构设置或者安全生产管理人员配备要求； （八）从业人员安全生产教育和培训要求； （九）工艺、技术和设备、设施的先进性和可靠性分析； （十）安全设施专项投资概算； （十一）安全预评价报告中的安全对策及建议采纳情况； （十二）预期效果以及存在的问题与建议； （十三）可能出现的事故预防及应急救援措施； （十四）法律、法规、规章、标准规定需要说明的其他事项。"},{"i":12,"n":"第十二条","txt":"本办法第七条第（一）项、第（二）项、第（三）项、第（四）项规定的建设项目安全设施设计完成后，生产经营单位应当按照本办法第五条的规定向安全生产监督管理部门提出审查申请，并提交下列文件资料： （一）建设项目审批、核准或者备案的文件； （二）建设项目安全设施设计审查申请； （三）设计单位的设计资质证明文件； （四）建设项目安全设施设计； （五）建设项目安全预评价报告及相关文件资料； （六）法律、行政法规、规章规定的其他文件资料。 安全生产监督管理部门收到申请后，对属于本部门职责范围内的，应当及时进行审查，并在收到申请后5个工作日内作出受理或者不予受理的决定，书面告知申请人；对不属于本部门职责范围内的，应当将有关文件资料转送有审查权的安全生产监督管理部门，并书面告知申请人。"},{"i":13,"n":"第十三条","txt":"对已经受理的建设项目安全设施设计审查申请，安全生产监督管理部门应当自受理之日起20个工作日内作出是否批准的决定，并书面告知申请人。20个工作日内不能作出决定的，经本部门负责人批准，可以延长10个工作日，并应当将延长期限的理由书面告知申请人。"},{"i":14,"n":"第十四条","txt":"建设项目安全设施设计有下列情形之一的，不予批准，并不得开工建设： （一）无建设项目审批、核准或者备案文件的； （二）未委托具有相应资质的设计单位进行设计的； （三）安全预评价报告由未取得相应资质的安全评价机构编制的； （四）设计内容不符合有关安全生产的法律、法规、规章和国家标准或者行业标准、技术规范的规定的； （五）未采纳安全预评价报告中的安全对策和建议，且未作充分论证说明的； （六）不符合法律、行政法规规定的其他条件的。 建设项目安全设施设计审查未予批准的，生产经营单位经过整改后可以向原审查部门申请再审。"},{"i":15,"n":"第十五条","txt":"已经批准的建设项目及其安全设施设计有下列情形之一的，生产经营单位应当报原批准部门审查同意；未经审查同意的，不得开工建设： （一）建设项目的规模、生产工艺、原料、设备发生重大变更的； （二）改变安全设施设计且可能降低安全性能的； （三）在施工期间重新设计的。"},{"i":16,"n":"第十六条","txt":"本办法第七条第（一）项、第（二）项、第（三）项和第（四）项规定以外的建设项目安全设施设计，由生产经营单位组织审查，形成书面报告备查。"},{"i":17,"n":"第十七条","txt":"建设项目安全设施的施工应当由取得相应资质的施工单位进行，并与建设项目主体工程同时施工。 施工单位应当在施工组织设计中编制安全技术措施和施工现场临时用电方案，同时对危险性较大的分部分项工程依法编制专项施工方案，并附具安全验算结果，经施工单位技术负责人、总监理工程师签字后实施。 施工单位应当严格按照安全设施设计和相关施工技术标准、规范施工，并对安全设施的工程质量负责。"},{"i":18,"n":"第十八条","txt":"施工单位发现安全设施设计文件有错漏的，应当及时向生产经营单位、设计单位提出。生产经营单位、设计单位应当及时处理。 施工单位发现安全设施存在重大事故隐患时，应当立即停止施工并报告生产经营单位进行整改。整改合格后，方可恢复施工。"},{"i":19,"n":"第十九条","txt":"工程监理单位应当审查施工组织设计中的安全技术措施或者专项施工方案是否符合工程建设强制性标准。 工程监理单位在实施监理过程中，发现存在事故隐患的，应当要求施工单位整改；情况严重的，应当要求施工单位暂时停止施工，并及时报告生产经营单位。施工单位拒不整改或者不停止施工的，工程监理单位应当及时向有关主管部门报告。 工程监理单位、监理人员应当按照法律、法规和工程建设强制性标准实施监理，并对安全设施工程的工程质量承担监理责任。"},{"i":20,"n":"第二十条","txt":"建设项目安全设施建成后，生产经营单位应当对安全设施进行检查，对发现的问题及时整改。"},{"i":21,"n":"第二十一条","txt":"本办法第七条规定的建设项目竣工后，根据规定建设项目需要试运行（包括生产、使用，下同）的，应当在正式投入生产或者使用前进行试运行。 试运行时间应当不少于30日，最长不得超过180日，国家有关部门有规定或者特殊要求的行业除外。 生产、储存危险化学品的建设项目和化工建设项目，应当在建设项目试运行前将试运行方案报负责建设项目安全许可的安全生产监督管理部门备案。"},{"i":22,"n":"第二十二条","txt":"本办法第七条规定的建设项目安全设施竣工或者试运行完成后，生产经营单位应当委托具有相应资质的安全评价机构对安全设施进行验收评价，并编制建设项目安全验收评价报告。 建设项目安全验收评价报告应当符合国家标准或者行业标准的规定。 生产、储存危险化学品的建设项目和化工建设项目安全验收评价报告除符合本条第二款的规定外，还应当符合有关危险化学品建设项目的规定。"},{"i":23,"n":"第二十三条","txt":"建设项目竣工投入生产或者使用前，生产经营单位应当组织对安全设施进行竣工验收，并形成书面报告备查。安全设施竣工验收合格后，方可投入生产和使用。 安全监管部门应当按照下列方式之一对本办法第七条第（一）项、第（二）项、第（三）项和第（四）项规定建设项目的竣工验收活动和验收结果的监督核查： （一）对安全设施竣工验收报告按照不少于总数10%的比例进行随机抽查； （二）在实施有关安全许可时，对建设项目安全设施竣工验收报告进行审查。 抽查和审查以书面方式为主。对竣工验收报告的实质内容存在疑问，需要到现场核查的，安全监管部门应当指派两名以上工作人员对有关内容进行现场核查。工作人员应当提出现场核查意见，并如实记录在案。"},{"i":24,"n":"第二十四条","txt":"建设项目的安全设施有下列情形之一的，建设单位不得通过竣工验收，并不得投入生产或者使用： （一）未选择具有相应资质的施工单位施工的； （二）未按照建设项目安全设施设计文件施工或者施工质量未达到建设项目安全设施设计文件要求的； （三）建设项目安全设施的施工不符合国家有关施工技术标准的； （四）未选择具有相应资质的安全评价机构进行安全验收评价或者安全验收评价不合格的； （五）安全设施和安全生产条件不符合有关安全生产法律、法规、规章和国家标准或者行业标准、技术规范规定的； （六）发现建设项目试运行期间存在事故隐患未整改的； （七）未依法设置安全生产管理机构或者配备安全生产管理人员的； （八）从业人员未经过安全生产教育和培训或者不具备相应资格的； （九）不符合法律、行政法规规定的其他条件的。"},{"i":25,"n":"第二十五条","txt":"生产经营单位应当按照档案管理的规定，建立建设项目安全设施“三同时”文件资料档案，并妥善保存。"},{"i":26,"n":"第二十六条","txt":"建设项目安全设施未与主体工程同时设计、同时施工或者同时投入使用的，安全生产监督管理部门对与此有关的行政许可一律不予审批，同时责令生产经营单位立即停止施工、限期改正违法行为，对有关生产经营单位和人员依法给予行政处罚。"},{"i":27,"n":"第二十七条","txt":"建设项目安全设施“三同时”违反本办法的规定，安全生产监督管理部门及其工作人员给予审批通过或者颁发有关许可证的，依法给予行政处分。"},{"i":28,"n":"第二十八条","txt":"生产经营单位对本办法第七条第（一）项、第（二）项、第（三）项和第（四）项规定的建设项目有下列情形之一的，责令停止建设或者停产停业整顿，限期改正；逾期未改正的，处50万元以上100万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未按照本办法规定对建设项目进行安全评价的； （二）没有安全设施设计或者安全设施设计未按照规定报经安全生产监督管理部门审查同意，擅自开工的； （三）施工单位未按照批准的安全设施设计施工的； （四）投入生产或者使用前，安全设施未经验收合格的。"},{"i":29,"n":"第二十九条","txt":"已经批准的建设项目安全设施设计发生重大变更，生产经营单位未报原批准部门审查同意擅自开工建设的，责令限期改正，可以并处1万元以上3万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"本办法第七条第（一）项、第（二）项、第（三）项和第（四）项规定以外的建设项目有下列情形之一的，对有关生产经营单位责令限期改正，可以并处5000元以上3万元以下的罚款： （一）没有安全设施设计的； （二）安全设施设计未组织审查，并形成书面审查报告的； （三）施工单位未按照安全设施设计施工的； （四）投入生产或者使用前，安全设施未经竣工验收合格，并形成书面报告的。"},{"i":31,"n":"第三十一条","txt":"承担建设项目安全评价的机构弄虚作假、出具虚假报告，尚未构成犯罪的，没收违法所得，违法所得在10万元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与生产经营单位承担连带赔偿责任。 对有前款违法行为的机构，吊销其相应资质。"},{"i":32,"n":"第三十二条","txt":"本办法规定的行政处罚由安全生产监督管理部门决定。法律、行政法规对行政处罚的种类、幅度和决定机关另有规定的，依照其规定。 安全生产监督管理部门对应当由其他有关部门进行处理的“三同时”问题，应当及时移送有关部门并形成记录备查。"},{"i":33,"n":"第三十三条","txt":"本办法自2011年2月1日起施行。"}],"zhuceanquangongchengshiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强注册安全工程师的管理，保障注册安全工程师依法执业，根据《安全生产法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"取得中华人民共和国注册安全工程师执业资格证书的人员注册以及注册后的执业、继续教育及其监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称注册安全工程师是指取得中华人民共和国注册安全工程师执业资格证书（以下简称资格证书），在生产经营单位从事安全生产管理、安全技术工作或者在安全生产中介机构从事安全生产专业服务工作，并按照本规定注册取得中华人民共和国注册安全工程师执业证（以下简称执业证）和执业印章的人员。"},{"i":4,"n":"第四条","txt":"注册安全工程师应当严格执行国家法律、法规和本规定，恪守职业道德和执业准则。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局（以下简称安全监管总局）对全国注册安全工程师的注册、执业活动实施统一监督管理。国务院有关主管部门（以下简称部门注册机构）对本系统注册安全工程师的注册、执业活动实施监督管理。 省、自治区、直辖市人民政府安全生产监督管理部门对本行政区域内注册安全工程师的注册、执业活动实施监督管理。 省级煤矿安全监察机构（以下与省、自治区、直辖市人民政府安全生产监督管理部门统称省级注册机构）对所辖区域内煤矿安全注册安全工程师的注册、执业活动实施监督管理。"},{"i":6,"n":"第六条","txt":"从业人员300人以上的煤矿、非煤矿矿山、建筑施工单位和危险物品生产、经营单位，应当按照不少于安全生产管理人员15%的比例配备注册安全工程师；安全生产管理人员在7人以下的，至少配备1名。 前款规定以外的其他生产经营单位，应当配备注册安全工程师或者委托安全生产中介机构选派注册安全工程师提供安全生产服务。 安全生产中介机构应当按照不少于安全生产专业服务人员30%的比例配备注册安全工程师。 生产经营单位和安全生产中介机构（以下统称聘用单位）应当为本单位专业技术人员参加注册安全工程师执业资格考试以及注册安全工程师注册、继续教育提供便利。"},{"i":7,"n":"第七条","txt":"取得资格证书的人员，经注册取得执业证和执业印章后方可以注册安全工程师的名义执业。"},{"i":8,"n":"第八条","txt":"申请注册的人员，必须同时具备下列条件： （一）取得资格证书； （二）在生产经营单位从事安全生产管理、安全技术工作或者在安全生产中介机构从事安全生产专业服务工作。"},{"i":9,"n":"第九条","txt":"注册安全工程师实行分类注册，注册类别包括： （一）煤矿安全； （二）非煤矿矿山安全； （三）建筑施工安全； （四）危险物品安全； （五）其他安全。"},{"i":10,"n":"第十条","txt":"取得资格证书的人员申请注册，按照下列程序办理： （一）申请人向聘用单位提出申请，聘用单位同意后，将申请人按本规定第十一条、第十三条、第十四条规定的申请材料报送部门、省级注册机构；中央企业总公司（总厂、集团公司）经安全监管总局认可，可以将本企业申请人的申请材料直接报送安全监管总局；申请人和聘用单位应当对申请材料的真实性负责； （二）部门、省级注册机构在收到申请人的申请材料后，应当作出是否受理的决定，并向申请人出具书面凭证；申请材料不齐全或者不符合要求，应当当场或者在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。部门、省级注册机构自受理申请之日起20日内将初步核查意见和全部申请材料报送安全监管总局； （三）安全监管总局自收到部门、省级注册机构以及中央企业总公司（总厂、集团公司）报送的材料之日起20日内完成复审并作出书面决定。准予注册的，自作出决定之日"},{"i":11,"n":"第十一条","txt":"申请初始注册应当提交下列材料： （一）注册申请表； （二）申请人资格证书（复印件）； （三）申请人与聘用单位签订的劳动合同或者聘用文件（复印件）； （四）申请人有效身份证件或者身份证明（复印件）。"},{"i":12,"n":"第十二条","txt":"申请人有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）在申请注册过程中有弄虚作假行为的； （三）同时在两个或者两个以上聘用单位申请注册的； （四）安全监管总局规定的不予注册的其他情形。"},{"i":13,"n":"第十三条","txt":"注册有效期为3年，自准予注册之日起计算。 注册有效期满需要延续注册的，申请人应当在有效期满30日前，按照本规定第十条规定的程序提出申请。注册审批机关应当在有效期满前作出是否准予延续注册的决定；逾期未作决定的，视为准予延续。 申请延续注册，应当提交下列材料： （一）注册申请表； （二）申请人执业证； （三）申请人与聘用单位签订的劳动合同或者聘用文件（复印件）； （四）聘用单位出具的申请人执业期间履职情况证明材料； （五）注册有效期内达到继续教育要求的证明材料。"},{"i":14,"n":"第十四条","txt":"在注册有效期内，注册安全工程师变更执业单位，应当按照本规定第十条规定的程序提出申请，办理变更注册手续。变更注册后仍延续原注册有效期。 申请变更注册，应当提交下列材料： （一）注册申请表； （二）申请人执业证； （三）申请人与原聘用单位合同到期或解聘证明（复印件）； （四）申请人与新聘用单位签订的劳动合同或者聘用文件（复印件）。 注册安全工程师在办理变更注册手续期间不得执业。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，注册安全工程师应当及时告知执业证和执业印章颁发机关；重新具备条件的，按照本规定第十一条、第十四条申请重新注册或者变更注册： （一）注册有效期满未延续注册的； （二）聘用单位被吊销营业执照的； （三）聘用单位被吊销相应资质证书的； （四）与聘用单位解除劳动关系的。"},{"i":16,"n":"第十六条","txt":"执业证颁发机关发现有下列情形之一的，应当将执业证和执业印章收回，并办理注销注册手续： （一）注册安全工程师受到刑事处罚的； （二）有本规定第十五条规定情形之一未申请重新注册或者变更注册的； （三）法律、法规规定的其他情形。"},{"i":17,"n":"第十七条","txt":"注册安全工程师的执业范围包括： （一）安全生产管理； （二）安全生产检查； （三）安全评价或者安全评估； （四）安全检测检验； （五）安全生产技术咨询、服务； （六）安全生产教育和培训； （七）法律、法规规定的其他安全生产技术服务。"},{"i":18,"n":"第十八条","txt":"注册安全工程师应当由聘用单位委派，并按照注册类别在规定的执业范围内执业，同时在出具的各种文件、报告上签字和加盖执业印章。"},{"i":19,"n":"第十九条","txt":"生产经营单位的下列安全生产工作，应有注册安全工程师参与并签署意见： （一）制定安全生产规章制度、安全技术操作规程和作业规程； （二）排查事故隐患，制定整改方案和安全措施； （三）制定从业人员安全培训计划； （四）选用和发放劳动防护用品； （五）生产安全事故调查； （六）制定重大危险源检测、评估、监控措施和应急救援预案； （七）其他安全生产工作事项。"},{"i":20,"n":"第二十条","txt":"聘用单位应当为注册安全工程师建立执业活动档案，并保证档案内容的真实性。"},{"i":21,"n":"第二十一条","txt":"注册安全工程师享有下列权利： （一）使用注册安全工程师称谓； （二）从事规定范围内的执业活动； （三）对执业中发现的不符合安全生产要求的事项提出意见和建议； （四）参加继续教育； （五）使用本人的执业证和执业印章； （六）获得相应的劳动报酬； （七）对侵犯本人权利的行为进行申诉； （八）法律、法规规定的其他权利。"},{"i":22,"n":"第二十二条","txt":"注册安全工程师应当履行下列义务： （一）保证执业活动的质量，承担相应的责任； （二）接受继续教育，不断提高执业水准； （三）在本人执业活动所形成的有关报告上署名； （四）维护国家、公众的利益和受聘单位的合法权益； （五）保守执业活动中的秘密； （六）不得出租、出借、涂改、变造执业证和执业印章； （七）不得同时在两个或者两个以上单位受聘执业； （八）法律、法规规定的其他义务。"},{"i":23,"n":"第二十三条","txt":"继续教育按照注册类别分类进行。 注册安全工程师在每个注册周期内应当参加继续教育，时间累计不得少于48学时。"},{"i":24,"n":"第二十四条","txt":"继续教育由部门、省级注册机构按照统一制定的大纲组织实施。中央企业注册安全工程师的继续教育可以由中央企业总公司（总厂、集团公司）组织实施。 继续教育应当由具备安全培训条件的机构承担。"},{"i":25,"n":"第二十五条","txt":"煤矿安全、非煤矿矿山安全、危险物品安全（民用爆破器材安全除外）和其他安全类注册安全工程师继续教育大纲，由安全监管总局组织制定；建筑施工安全、民用爆破器材安全注册安全工程师继续教育大纲，由安全监管总局会同国务院有关主管部门组织制定。"},{"i":26,"n":"第二十六条","txt":"安全生产监督管理部门、煤矿安全监察机构和有关主管部门的工作人员应当坚持公开、公正、公平的原则，严格按照法律、行政法规和本规定，对申请注册的人员进行资格审查，颁发执业证和执业印章。"},{"i":27,"n":"第二十七条","txt":"安全监管总局对准予注册以及注销注册、撤销注册、吊销执业证的人员名单向社会公告，接受社会监督。"},{"i":28,"n":"第二十八条","txt":"对注册安全工程师的执业活动，安全生产监督管理部门、煤矿安全监察机构和有关主管部门应当进行监督检查。"},{"i":29,"n":"第二十九条","txt":"安全生产监督管理部门、煤矿安全监察机构或者有关主管部门发现申请人、聘用单位隐瞒有关情况或者提供虚假材料申请注册的，应当不予受理或者不予注册；申请人一年内不得再次申请注册。"},{"i":30,"n":"第三十条","txt":"未经注册擅自以注册安全工程师名义执业的，由县级以上安全生产监督管理部门、有关主管部门或者煤矿安全监察机构责令其停止违法活动，没收违法所得，并处三万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":31,"n":"第三十一条","txt":"注册安全工程师以欺骗、贿赂等不正当手段取得执业证的，由县级以上安全生产监督管理部门、有关主管部门或者煤矿安全监察机构处三万元以下的罚款；由执业证颁发机关撤销其注册，当事人三年内不得再次申请注册。"},{"i":32,"n":"第三十二条","txt":"注册安全工程师有下列行为之一的，由县级以上安全生产监督管理部门、有关主管部门或者煤矿安全监察机构处三万元以下的罚款；由执业证颁发机关吊销其执业证，当事人五年内不得再次申请注册；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）准许他人以本人名义执业的； （二）以个人名义承接业务、收取费用的； （三）出租、出借、涂改、变造执业证和执业印章的； （四）泄漏执业过程中应当保守的秘密并造成严重后果的； （五）利用执业之便，贪污、索贿、受贿或者谋取不正当利益的； （六）提供虚假执业活动成果的； （七）超出执业范围或者聘用单位业务范围从事执业活动的； （八）法律、法规、规章规定的其他违法行为。"},{"i":33,"n":"第三十三条","txt":"在注册工作中，工作人员有下列行为之一的，依照有关规定给予行政处分： （一）利用职务之便，索取或者收受他人财物或者谋取不正当利益的； （二）对发现不符合条件的申请人准予注册的； （三）对符合条件的申请人不予注册的。"},{"i":34,"n":"第三十四条","txt":"获准在中华人民共和国境内就业的外籍人员及香港特别行政区、澳门特别行政区、台湾地区的专业人员，符合本规定要求的，按照本规定执行。"},{"i":35,"n":"第三十五条","txt":"本规定自2007年3月1日起施行。原国家安全生产监督管理局2004年公布的《注册安全工程师注册管理办法》同时废止。"}],"haiyangshiyouanquanshengchanguiding":[{"i":1,"n":"第一条","txt":"为了加强海洋石油安全生产工作，防止和减少海洋石油生产安全事故和职业危害，保障从业人员生命和财产安全，根据《安全生产法》及有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国的内水、领海、毗连区、专属经济区、大陆架以及中华人民共和国管辖的其他海域内的海洋石油开采活动的安全生产，适用本规定。"},{"i":3,"n":"第三条","txt":"海洋石油作业者和承包者是海洋石油安全生产的责任主体。 本规定所称作业者是指负责实施海洋石油开采活动的企业，或者按照石油合同的约定负责实施海洋石油开采活动的实体。 本规定所称承包者是指向作业者提供服务的企业或者实体。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局（以下简称安全监管总局）对海洋石油安全生产实施综合监督管理。 安全监管总局设立海洋石油作业安全办公室（以下简称海油安办）作为实施海洋石油安全生产综合监督管理的执行机构。海油安办根据需要设立分部，各分部依照有关规定实施具体的安全监督管理。"},{"i":5,"n":"第五条","txt":"作业者和承包者应当遵守有关安全生产的法律、行政法规、部门规章、国家标准和行业标准，具备安全生产条件。"},{"i":6,"n":"第六条","txt":"作业者应当加强对承包者的安全监督和管理，并在承包合同中约定各自的安全生产管理职责。"},{"i":7,"n":"第七条","txt":"作业者和承包者的主要负责人对本单位的安全生产工作全面负责。 作业者和从事物探、钻井、测井、录井、试油、井下作业等活动的承包者及海洋石油生产设施的主要负责人、安全管理人员应当按照安全监管总局的规定，经过安全资格培训，具备相应的安全生产知识和管理能力，经考核合格取得安全资格证书。"},{"i":8,"n":"第八条","txt":"作业者和承包者应当对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，熟悉有关的安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能。"},{"i":9,"n":"第九条","txt":"出海作业人员应当接受海洋石油作业安全救生培训，经考核合格后方可出海作业。 临时出海人员应接受必要的安全教育。"},{"i":10,"n":"第十条","txt":"特种作业人员应当按照安全监管总局有关规定经专门的安全技术培训，考核合格取得特种作业操作资格证书后方可上岗作业。"},{"i":11,"n":"第十一条","txt":"海洋石油建设项目在可行性研究阶段或者总体开发方案编制阶段应当进行安全预评价。 在设计阶段，海洋石油生产设施的重要设计文件及安全专篇，应当经海洋石油生产设施发证检验机构（以下简称发证检验机构）审查同意。发证检验机构应当在审查同意的设计文件、图纸上加盖印章。"},{"i":12,"n":"第十二条","txt":"海洋石油生产设施应当由具有相应资质或者能力的专业单位施工，施工单位应当按照审查同意的设计方案或者图纸施工。"},{"i":13,"n":"第十三条","txt":"海洋石油生产设施试生产前，应当经发证检验机构检验合格，取得最终检验证书或者临时检验证书，并制订试生产的安全措施，于试生产前45日报海油安办有关分部备案。 海油安办有关分部应对海洋石油生产设施的状况及安全措施的落实情况进行检查。"},{"i":14,"n":"第十四条","txt":"海洋石油生产设施试生产正常后，应当由作业者或者承包者负责组织对其安全设施进行竣工验收，并形成书面报告备查。 经验收合格并办理安全生产许可证后，方可正式投入生产使用。"},{"i":15,"n":"第十五条","txt":"作业者和承包者应当向作业人员如实告知作业现场和工作岗位存在的危险因素和职业危害因素，以及相应的防范措施和应急措施。"},{"i":16,"n":"第十六条","txt":"作业者和承包者应当为作业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育作业人员按照使用规则佩戴、使用。"},{"i":17,"n":"第十七条","txt":"作业者和承包者应当制定海洋石油作业设施、生产设施及其专业设备的安全检查、维护保养制度，建立安全检查、维护保养档案，并指定专人负责。"},{"i":18,"n":"第十八条","txt":"作业者和承包者应当加强防火防爆管理，按照有关规定划分和标明安全区与危险区；在危险区作业时，应当对作业程序和安全措施进行审查。"},{"i":19,"n":"第十九条","txt":"作业者和承包者应当加强对易燃、易爆、有毒、腐蚀性等危险物品的管理，按国家有关规定进行装卸、运输、储存、使用和处置。"},{"i":20,"n":"第二十条","txt":"海洋石油的专业设备应当由专业设备检验机构检验合格，方可投入使用。专业设备检验机构对检验结果负责。"},{"i":21,"n":"第二十一条","txt":"海洋石油作业设施首次投入使用前或者变更作业区块前，应当制订作业计划和安全措施。 作业计划和安全措施应当在开始作业前15日报海油安办有关分部备案。 外国海洋石油作业设施进入中华人民共和国管辖海域前按照上述要求执行。"},{"i":22,"n":"第二十二条","txt":"作业者和承包者应当建立守护船值班制度，在海洋石油生产设施和移动式钻井船（平台）周围应备有守护船值班。无人值守的生产设施和陆岸结构物除外。"},{"i":23,"n":"第二十三条","txt":"作业者或者承包者在编制钻井、采油和井下作业等作业计划时，应当根据地质条件与海域环境确定安全可靠的井控程序和防硫化氢措施。 打开油（气）层前，作业者或者承包者应当确认井控和防硫化氢措施的落实情况。"},{"i":24,"n":"第二十四条","txt":"作业者和承包者应当保存安全生产的相关资料，主要包括作业人员名册、工作日志、培训记录、事故和险情记录、安全设备维修记录、海况和气象情况等。"},{"i":25,"n":"第二十五条","txt":"在海洋石油生产设施的设计、建造、安装以及生产的全过程中，实施发证检验制度。 海洋石油生产设施的发证检验包括建造检验、生产过程中的定期检验和临时检验。"},{"i":26,"n":"第二十六条","txt":"发证检验工作由作业者委托具有资质的发证检验机构进行。"},{"i":27,"n":"第二十七条","txt":"发证检验机构应当依照有关法律、行政法规、部门规章和国家标准、行业标准或者作业者选定的技术标准实施审查、检验，并对审查、检验结果负责。 作业者选定的技术标准不得低于国家标准和行业标准。 海油安办对发证检验机构实施的设计审查程序、检验程序进行监督。"},{"i":28,"n":"第二十八条","txt":"海油安办及其各分部对海洋石油安全生产履行以下监督管理职责： （一）　组织起草海洋石油安全生产法规、规章、标准； （二）　监督检查作业者和承包者安全生产条件、设备设施安全和劳动防护用品使用情况； （三）　监督检查作业者和承包者安全生产教育培训情况；负责作业者，从事物探、钻井、测井、录井、试油、井下作业等的承包者和海洋石油生产设施的主要负责人、安全管理人员和特种作业人员的安全培训考核工作； （四）监督核查海洋石油建设项目生产设施安全竣工验收工作，负责安全生产许可证的发放工作。 （五）负责海洋石油生产设施发证检验、专业设备检测检验、安全评价和安全咨询等社会中介服务机构的资质审查； （六）　组织生产安全事故的调查处理；协调事故和险情的应急救援工作。"},{"i":29,"n":"第二十九条","txt":"监督检查人员必须熟悉海洋石油安全法律法规和安全技术知识，能胜任海洋石油安全检查工作，经考核合格，取得相应的执法资格。"},{"i":30,"n":"第三十条","txt":"海油安办及其各分部依法对作业者和承包者执行有关安全生产的法律、行政法规和国家标准或者行业标准的情况进行监督检查，行使以下职权： （一）　对作业者和承包者进行安全检查，调阅有关资料，向有关单位和人员了解情况； （二）　对检查中发现的安全生产违法行为，当场予以纠正或者要求限期改正； （三）　对检查中发现的事故隐患，应当责令立即排除；重大事故隐患排除前或者排除过程中无法保证安全的，应当责令从危险区域内撤出作业人员，责令暂时停产停业或者停止使用；重大事故隐患排除后，经审查同意，方可恢复生产和使用； （四）　对有根据认为不符合保障安全生产的国家标准或者行业标准的设施、设备、器材予以查封或者扣押，并应当在15日内依法作出处理决定。"},{"i":31,"n":"第三十一条","txt":"监督检查人员进行监督检查时，应履行以下义务： （一）　忠于职守，坚持原则，秉公执法； （二）　执行监督检查任务时，必须出示有效的监督执法证件，使用统一的行政执法文书； （三）　遵守作业者和承包者的有关现场管理规定，不得影响正常生产活动； （四）保守作业者和承包者的有关技术秘密和商业秘密。"},{"i":32,"n":"第三十二条","txt":"监督检查人员在进行安全监督检查期间，作业者或者承包者应当免费提供必要的交通工具、防护用品等工作条件。"},{"i":33,"n":"第三十三条","txt":"承担海洋石油生产设施发证检验、专业设备检测检验、安全评价和安全咨询的中介机构应当具备国家规定的资质。"},{"i":34,"n":"第三十四条","txt":"作业者应当建立应急救援组织，配备专职或者兼职救援人员，或者与专业救援组织签订救援协议，并在实施作业前编制应急预案。 承包者在实施作业前应编制应急预案。 应急预案应当报海油安办有关分部和其他有关政府部门备案。"},{"i":35,"n":"第三十五条","txt":"应急预案应当包括以下主要内容：作业者和承包者的基本情况、危险特性、可利用的应急救援设备；应急组织机构、职责划分、通讯联络；应急预案启动、应急响应、信息处理、应急状态中止、后续恢复等处置程序；应急演习与训练。"},{"i":36,"n":"第三十六条","txt":"应急预案应充分考虑作业内容、作业海区的环境条件、作业设施的类型、自救能力和可以获得的外部支援等因素，应能够预防和处置各类突发性事故和可能引发事故的险情，并随实际情况的变化及时修改或者补充。 事故和险情包括以下情况：井喷失控、火灾与爆炸、平台遇险、飞机或者直升机失事、船舶海损、油（气）生产设施与管线破损/泄漏、有毒有害物质泄漏、放射性物质遗散、潜水作业事故；人员重伤、死亡、失踪及暴发性传染病、中毒；溢油事故、自然灾害以及其他紧急情况等。"},{"i":37,"n":"第三十七条","txt":"当发生事故或者出现可能引发事故的险情时，作业者和承包者应当按应急预案的规定实施应急措施，防止事态扩大，减少人员伤亡和财产损失。 当发生应急预案中未规定的事件时，现场工作人员应当及时向主要负责人报告。主要负责人应当及时采取相应的措施。"},{"i":38,"n":"第三十八条","txt":"事故和险情发生后，当事人、现场人员、作业者和承包者负责人、各分部和海油安办根据有关规定逐级上报。"},{"i":39,"n":"第三十九条","txt":"海油安办及其有关分部、有关部门接到重大事故报告后，应当立即赶到事故现场，组织事故抢救、事故调查。"},{"i":40,"n":"第四十条","txt":"无人员伤亡事故、轻伤、重伤事故由作业者和承包者负责人或其指定的人员组织生产、技术、安全等有关人员及工会代表参加的事故调查组进行调查。 其他事故的调查处理，按有关规定执行。"},{"i":41,"n":"第四十一条","txt":"作业者应当建立事故统计和分析制度，定期对事故进行统计和分析。事故统计年报应当报海油安办有关分部、政府有关部门。 承包者在提供服务期间发生的事故由作业者负责统计。"},{"i":42,"n":"第四十二条","txt":"监督检查人员在海洋石油安全生产监督检查中滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"作业者和承包者有下列行为之一的，给予警告，并处3万元以下的罚款： （一）未按规定执行发证检验或者用非法手段获取检验证书的； （二）未按规定配备守护船，或者使用不满足有关规定要求的船舶做守护船，或者守护船未按规定履行登记手续的； （三）未按照本规定第三十四条的规定履行备案手续的； （四）未按有关规定制订井控措施和防硫化氢措施，或者井控措施和防硫化氢措施不落实的。"},{"i":44,"n":"第四十四条","txt":"本规定所列行政处罚，由海油安办及其各分部实施。 《安全生产法》等法律、行政法规对安全生产违法行为的行政处罚另有规定的，依照其规定。"},{"i":45,"n":"第四十五条","txt":"本规定下列用语的定义： （一）石油，是指蕴藏在地下的、正在采出的和已经采出的原油和天然气。 （二）石油合同，是指中国石油企业与外国企业为合作开采中华人民共和国海洋石油资源，依法订立的石油勘探、开发和生产的合同。 （三）海洋石油开采活动，是指在本规定第二条所述海域内从事的石油勘探、开发、生产、储运、油田废弃及其有关的活动。 （四）海洋石油作业设施，是指用于海洋石油作业的海上移动式钻井船（平台）、物探船、铺管船、起重船、固井船、酸化压裂船等设施。 （五）海洋石油生产设施，是指以开采海洋石油为目的的海上固定平台、单点系泊、浮式生产储油装置、海底管线、海上输油码头、滩海陆岸、人工岛和陆岸终端等海上和陆岸结构物。 （六）专业设备，是指海洋石油开采过程中使用的危险性较大或者对安全生产有较大影响的设备，包括海上结构、采油设备、海上锅炉和压力容器、钻井和修井设备、起重和升降设备、火灾和可燃气体探测、报"},{"i":46,"n":"第四十六条","txt":"内陆湖泊的石油开采的安全生产监督管理，参照本规定相应条款执行。"},{"i":47,"n":"第四十七条","txt":"本规定自2006年5月1日起施行，原石油工业部1986年颁布的《海洋石油作业安全管理规定》同时废止。"}],"haiyangshiyouanquanguanlixize":[{"i":1,"n":"第一条","txt":"为了加强海洋石油安全管理工作，保障从业人员生命和财产安全，防止和减少海洋石油生产安全事故，根据安全生产法等法律、法规和标准，制定本细则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国的内水、领海、毗连区、专属经济区、大陆架，以及中华人民共和国管辖的其他海域内从事海洋石油（含天然气，下同）开采活动的安全生产及其监督管理，适用本细则。"},{"i":3,"n":"第三条","txt":"海洋石油作业者和承包者是海洋石油安全生产的责任主体，对其安全生产工作负责。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局海洋石油作业安全办公室（以下简称海油安办）对全国海洋石油安全生产工作实施监督管理；海油安办驻中国海洋石油总公司、中国石油化工集团公司、中国石油天然气集团公司分部（以下统称海油安办有关分部）分别负责中国海洋石油总公司、中国石油化工集团公司、中国石油天然气集团公司的海洋石油安全生产的监督管理。"},{"i":5,"n":"第五条","txt":"海洋石油生产设施应当进行试生产。作业者或者承包者应当在试生产前45日报生产设施所在地的海油安办有关分部备案，并提交生产设施试生产备案申请书、海底长输油（气）管线投用备案申请书和下列资料： （一）发证检验机构对生产设施的最终检验证书（或者临时检验证书）和检验报告； （二）试生产安全保障措施； （三）建设阶段资料登记表； （四）安全设施设计审查合格、设计修改及审查合格的有关文件； （五）施工单位资质证明； （六）施工期间发生的生产安全事故及其他重大工程质量事故情况； （七）生产设施有关证书和文件登记表； （八）生产设施主要技术说明、总体布置图和工艺流程图； （九）生产设施运营的主要负责人和安全生产管理人员安全资格证书； （十）生产设施所属设备的取证分类表及有关证书、证件； （十一）生产设施运营安全手册； （十二）生产设施运营安全应急预案。 生产设施是浮式生产储油装置的，除提交第一款规定的资"},{"i":6,"n":"第六条","txt":"海油安办有关分部对作业者或者承包者提交的生产设施资料，应当进行严格审查。必要时，应当进行现场检查。 需要进行现场检查的，海油安办有关分部应当提前10日与作业者或承包者商定现场检查的具体事宜。作业者或承包者应当配合海油安办有关分部进行现场检查，并提供以下资料： （一）人员安全培训证书登记表； （二）消防和救生设备实际布置图和应变部署表； （三）安全管理文件，主要包括：安全生产责任制、安全操作规程、工作许可制度、安全检查制度、船舶系泊装卸制度、直升机管理制度、危险物品管理制度、无人驻守平台遥控检测程序和油（气）外输管理制度等； （四）对于滩海陆岸，还应准备通海路及沿通海路安装的设施设备合格文件、发证检验机构检验证书和安装后的试验报告。 经审查和现场检查符合规定的，海油安办有关分部向作业者或者承包者颁发生产设施试生产备案通知书；备案资料、设施现场安全状况等不符合规定的，及时书面通知作业者或者"},{"i":7,"n":"第七条","txt":"作业者或者承包者应当严格按照备案文件中所列试生产安全保障措施组织试生产，生产设施试生产期限不得超过12个月。试生产正常后，作业者或者承包者应当组织安全竣工验收。 经竣工验收合格并办理安全生产许可证后，方可正式投入生产使用。"},{"i":8,"n":"第八条","txt":"生产设施有下列情形之一的，作业者或者承包者应当及时向海油安办有关分部报告： （一）更换或者拆卸井上和井下安全阀、火灾及可燃和有毒有害气体探测与报警系统、消防和救生设备等主要安全设施的； （二）变动应急预案有关内容的； （三）中断采油（气）作业10日以上或者终止采油（气）作业的； （四）改变海底长输油（气）管线原设计用途的； （五）超过海底长输油（气）管线设计允许最大输送量或者输送压力的； （六）海底长输油（气）管线发生严重的损伤、断裂、爆破等事故的； （七）海底长输油（气）管线输送的油（气）发生泄漏导致重大污染事故的； （八）位置失稳、水平或者垂直移动、悬空、沉陷、漂浮等超出海底长输油（气）管线设计允许偏差值的； （九）介质堵塞造成海底长输油（气）管线停产的； （十） 海底长输油（气）管线需进行大修和改造的； （十一）海底长输油（气）管线安全保护系统（如紧急放空装置、定点截断装置等）长"},{"i":9,"n":"第九条","txt":"海洋石油作业设施从事物探、钻（修）井、铺管、起重和生活支持等活动应当向海油安办有关分部备案。作业者或者承包者应当在作业前15日向海油安办有关分部提交作业设施备案申请书和下列资料： （一）作业设施备案申请有关证书登记表； （二）作业设施所属设备的取证分类表及有关证书； （三）操船手册； （四）作业合同； （五）作业设施运营安全手册； （六）作业设施安全应急预案。 用作钻（修）井的作业设施，除提交第一款规定的资料外，还应当提交下列资料： （一）钻（修）井专用设备、防喷器组、防喷器控制系统、阻流管汇及其控制盘、压井管汇、固井设备、测试设备的发证检验机构证书、出厂及修理后的合格证和安装后的试验报告； （二）设施主要负责人和安全管理人员的安全资格证书； （三）有自航能力的作业设施的船长、轮机长的适任证书。 对于自升式移动平台，除提交第一款规定的资料外，还应当提交稳性计算书、升降设备的发证检验机构"},{"i":10,"n":"第十条","txt":"海油安办有关分部对作业者或者承包者提交的作业设施资料，应当进行严格审查。必要时，进行现场检查。 需要进行现场检查的，海油安办有关分部应当提前10日与作业者或承包者商定现场检查的具体事宜。作业者或承包者应当配合海油安办有关分部进行现场检查，并提供以下资料： （一）人员安全培训证书登记表； （二）防火控制图、消防、救生设备实际布置图和应变部署表； （三）安全管理文件，主要包括：安全管理机构的设置、安全生产责任制、安全操作规程、安全检查制度、工作许可制度等； （四）安全活动、应急演习记录。 经审查和现场检查符合规定的，海油安办有关分部向作业者或者承包者颁发海洋石油作业设施备案通知书；备案资料、设施现场安全状况等不符合规定的，及时书面通知作业者或者承包者进行整改。"},{"i":11,"n":"第十一条","txt":"通常情况下，海洋石油作业设施从事物探、钻（修）井、铺管、起重和生活支持等活动期限不超过1年。确需延期时，作业者或者承包者应当于期满前15日向海油安办有关分部提出延期申请，延期时间不得超过3个月。"},{"i":12,"n":"第十二条","txt":"作业设施有下列情形之一的，作业者或者承包者应当及时向海油安办有关分部报告： （一）改动井控系统的； （二）更换或者拆卸火灾及可燃和有毒有害气体探测与报警系统、消防和救生设备等主要安全设施的； （三）变更作业合同、作业者或者作业海区的； （四）改变应急预案有关内容的； （五）中断作业10日以上或者终止作业的； （六）其他对作业安全生产有重大影响的。"},{"i":13,"n":"第十三条","txt":"海上油田（井）进行延长测试前，作业者或者承包者应当提前15日向海油安办有关分部提交延长测试设施的书面报告和下列资料： （一）延长测试设施备案有关证书和文件登记表； （二）延长测试的工艺流程图、总体布置图及技术说明； （三）增加的作业设施、生产设施主要负责人和安全管理人员安全资格证书； （四）延长测试作业应急预案； （五）油轮或者浮式生产储油装置的系泊点、锚、锚链、快速解脱装置、系缆张力和距离测量装置的证书和资料； （六）延长测试专用设备或者系统的出厂合格证、发证检验机构的检验证书、安装后的试验报告。 前款所称延长测试专用设备或者系统，包括油气加热器、油气分离器、原油外输泵、天然气火炬分液包及凝析油泵、蒸汽锅炉、换热器、废油回收设备、井口装置、污油处理装置、机械采油装置、井上和井下防喷装置、防硫化氢的井口装置、检测设施及防护器具、惰气系统、柴油置换系统、火灾及可燃和有毒有害气体探测与报警"},{"i":14,"n":"第十四条","txt":"海油安办有关分部对作业者或者承包者提交的延长测试设施资料，应当进行严格审查。必要时，可进行现场检查。 需要进行现场检查的，海油安办有关分部应当提前10日与作业者或承包者商定现场检查的具体事宜。作业者或承包者应当配合海油安办有关分部进行现场检查，并提供以下资料： （一）原钻井装置增加的延长测试作业人员、油轮或浮式储油装置人员的安全培训证书登记表； （二）原钻井装置新加装设备后，其消防和救生设备、火灾及可燃和有毒有害气体探测报警系统布置图、危险区域划分图和应变部署表； （三）安全管理文件，主要包括：安全管理机构的设置、安全生产责任制、安全操作规程、安全检查制度、工作许可制度、船舶系泊装卸和油（气）外输管理制度等。 经审查和现场检查符合规定的，向作业者或者承包者颁发海上油田（井）延长测试设施通知书；有关资料、设施现场安全状况等不符合规定的，及时书面通知作业者或者承包者进行整改。"},{"i":15,"n":"第十五条","txt":"通常情况下，海上油田（井）延长测试作业期限不超过1年。确需延期时，作业者或者承包者应当提前15日向海油安办有关分部提出延期申请，延期时间不得超过6个月。"},{"i":16,"n":"第十六条","txt":"海上油田（井）延长测试设施有下列情形之一的，作业者或者承包者应当及时向海油安办有关分部报告： （一）改动组成延长测试设施的主要结构、设备和井控系统的； （二）更换火灾及可燃和有毒有害气体探测与报警系统、消防和救生设备等主要安全设施的； （三）改变应急预案有关内容的； （四）其他对生产作业安全有重大影响的。"},{"i":17,"n":"第十七条","txt":"在海洋石油生产作业中，作业者和承包者应当确保海洋石油生产、作业设施（以下简称设施）安全条件符合法律、法规、规章和相关国家标准、行业标准的要求，并建立完善的安全管理体系。设施主要负责人对设施的安全管理全面负责。"},{"i":18,"n":"第十八条","txt":"按照设施不同区域的危险性，划分三个等级的危险区： （一）0类危险区，是指在正常操作条件下，连续出现达到引燃或者爆炸浓度的可燃性气体或者蒸气的区域； （二）1类危险区，是指在正常操作条件下，断续地或者周期性地出现达到引燃或者爆炸浓度的可燃性气体或者蒸气的区域； （三）2类危险区，是指在正常操作条件下，不可能出现达到引燃或者爆炸浓度的可燃性气体或者蒸气；但在不正常操作条件下，有可能出现达到引燃或者爆炸浓度的可燃性气体或者蒸气的区域。 设施的作业者或者承包者应当将危险区等级准确地标注在设施操作手册的附图上。对于通往危险区的通道口、门或者舱口，应当在其外部标注清晰可见的中英文“危险区域”、“禁止烟火”和“禁带火种”等标志。"},{"i":19,"n":"第十九条","txt":"设施的作业者或者承包者应当建立动火、电工作业、受限空间作业、高空作业和舷（岛）外作业等审批制度。 从事前款规定的作业前，作业单位应当提出书面申请，说明作业的性质、地点、期限及采取的安全措施等，经设施负责人批准签发作业通知单后，方可进行作业。作业通知单应当包含作业内容、有关检测报告、作业要求、安全程序、个体防护用品、安全设备和作业通知单有效期限等内容。 作业单位接到作业通知单后，应当按通知单的要求采取有关措施，并制定详细的检查和作业程序。 作业期间，如果施工条件发生重大变化的，应当暂停施工并立即报告设施负责人，得到准予施工的指令后方可继续施工。 作业完成后，作业负责人应当在作业通知单上填写完成时间、工作质量和安全情况，并交付设施负责人保存。作业通知单的保存期限至少1年。"},{"i":20,"n":"第二十条","txt":"设施上所有通往救生艇（筏）、直升机平台的应急撤离通道和通往消防设备的通道应当设置明显标志，并保持畅通。"},{"i":21,"n":"第二十一条","txt":"设施上的各种设备应当符合下列规定： （一）符合国家有关法律、法规、规章、标准的安全要求，有出厂合格证书或者检验合格证书； （二）对裸露且危及人身安全的运转部分要安装防护罩或者其他安全保护装置； （三）建立设备运转记录、设备缺陷和故障记录报告制度； （四）制定设备安全操作规程和定期维护、保养、检验制度，制定设备的定人定岗管理制度； （五）增加、拆除重要设备设施，或者改变其性能前，进行风险分析。属于改建、扩建项目的，按照有关规定向政府有关部门办理审批手续。"},{"i":22,"n":"第二十二条","txt":"设施配备的救生艇、救助艇、救生筏、救生圈、救生衣、保温救生服及属具等救生设备，应当符合《国际海上人命安全公约》的规定，并经海油安办认可的发证检验机构检验合格。 海上石油设施配备救生设备的数量应当满足下列要求： （一）配备的刚性全封闭机动耐火救生艇能够容纳自升式和固定式设施上的总人数，或者浮式设施上总人数的200%。无人驻守设施可以不配备刚性全封闭机动耐火救生艇。在设施建造、安装或者停产检修期间，通过风险分析，可以用救生筏代替救生艇； （二）气胀式救生筏能够容纳设施上的总人数，其放置点应满足距水面高度的要求。无人驻守设施可以按定员12人考虑； （三）至少配备并合理分布8个救生圈，其中2个带自亮浮灯，4个带自亮浮灯和自发烟雾信号。每个带自亮浮灯和自发烟雾信号的救生圈配备1根可浮救生索，可浮救生索的长度为从救生圈的存放位置至最低天文潮位水面高度的1.5倍，并至少长30米。 （四）救生衣按总人"},{"i":23,"n":"第二十三条","txt":"设施上的消防设备应当符合下列规定： （一）根据国家有关规定，针对设施可能发生的火灾性质和危险程度，分别装设水消防系统、泡沫灭火系统、气体灭火系统和干粉灭火系统等固定灭火设备和装置，并经发证检验机构认可。无人驻守的简易平台，可以不设置水消防等灭火设备和装置； （二）设置自动和手动火灾、可燃和有毒有害气体探测报警系统，总控制室内设总的报警和控制系统； （三）配备4套消防员装备，包括隔热防护服、消防靴和手套、头盔、正压式空气呼吸器、消防斧以及可以连续使用3个小时的手提式安全灯。根据平台性质和工作人数，经发证检验机构同意，可以适当减少配备数量； （四）滩海陆岸石油设施现场管理单位至少配备2套消防员装备，包括消防头盔、防护服、消防靴、安全灯、消防斧等，至少配备3套带气瓶的正压式空气呼吸器和可移动式消防泵1台； （五）所有的消防设备都存放在易于取用的位置，并定期检查，始终保持完好状态。检查应当有检"},{"i":24,"n":"第二十四条","txt":"在设施的危险区内进行测试、测井、修井等作业的设备应当采用防爆型，室内有非防爆电气的活动房应当采用正压防爆型。"},{"i":25,"n":"第二十五条","txt":"起重作业应当符合下列规定： （一）操作人员持有特种作业人员资格证书，熟悉起重设备的操作规程，并按规程操作； （二）起重设备明确标识安全起重负荷；若为活动吊臂，标识吊臂在不同角度时的安全起重负荷； （三）按规定对起重设备进行维护保养，保证刹车、限位、起重负荷指示、报警等装置齐全、准确、灵活、可靠； （四）起重机及吊物附件按规定定期检验，并记录在起重设备检验簿上。 设施的载人吊篮作业，除符合第一款规定的要求外，还应当符合下列规定： （一）限定乘员人数； （二）乘员按规定穿救生背心或者救生衣； （三）只允许用于起吊人员及随身物品； （四）指定专人维护和检查，定期组织检验机构对其进行检验； （五）当风速超过15米/秒或者影响吊篮安全起放时，立即停止使用； （六）起吊人员时，尽量将载人吊篮移至水面上方再升降，并尽可能减少回转角度。"},{"i":26,"n":"第二十六条","txt":"高处及舷（岛）外作业应当符合下列规定： （一）高处及舷（岛）外作业人员佩戴安全帽和安全带，舷（岛）外作业人员穿救生衣，并采取其他必要的安全措施； （二）风速超过15米/秒等恶劣天气时，立即停止作业。"},{"i":27,"n":"第二十七条","txt":"危险物品管理应当符合下列规定： （一）设施上任何危险物品（包括爆炸品、压缩气体和液化气体、易燃液体、易燃固体、自燃物品和遇湿易燃物品、氧化剂和有机过氧化物、有毒品和腐蚀品等）必须存放在远离危险区和生活区的指定地点和容器内，并将存放地点标注在设施操作手册的附图上；个人不得私自存放危险物品； （二）设有专人负责危险物品的管理，并建立和保存危险物品入库、消耗和使用的记录； （三）在通往危险物品存放地点的通道口、舱口处，设有醒目的中英文“危险物品”标识。"},{"i":28,"n":"第二十八条","txt":"直升机起降管理应当符合下列规定： （一）指定直升机起降联络负责人，负责指挥和配合直升机起降工作； （二）配备与直升机起降有关的应急设备和工具，并注明中英文“直升机应急工具”字样； （三）设施与机场的往返距离所需油量超过直升机自身储存油量的，按有关规定配备安全有效的直升机加油用储油罐、燃油质量检验设备和加油设备； （四）直升机与设施建立联络后，经设施主要负责人准许，方可起飞或者降落（紧急情况除外）； （五）直升机机长或者机组人员提出降落要求的，起降联络负责人立即向直升机提供风速、风向、能见度、海况等数据和资料； （六）无线电报务员一直保持监听来自直升机的无线电信号，直至其降落为止； （七）机组人员开启舱门后，起降联络负责人方可指挥乘机人员上下直升机、装卸物品或者进行加油作业。 直升机起飞或者降落前，起降联络负责人应当组织做好下列准备工作： （一）清除直升机甲板的障碍物和易燃物； （二）检"},{"i":29,"n":"第二十九条","txt":"劳动防护应当符合下列规定： （一）设施上所有工作人员配备符合相关安全标准的劳动防护用品； （二）设施上的工作场所按照国家有关规定和设计要求配备劳动防护设备，并定期进行检测； （三）按照国家有关职业病防治的规定，定期对从事有毒有害作业的人员进行职业健康体检，对职业病患者进行康复治疗。"},{"i":30,"n":"第三十条","txt":"医务室应当符合下列规定： （一）在有人驻守的设施上，配备具有基础医疗抢救条件的医务室。作业人员超过15人的，配备专职医务人员；低于15人的，可以配备兼职医务人员； （二）按照国家有关规定配备常用药品、急救药品和氧气、医疗器械、病床等； （三）按照国家有关规定，制定有关疫情病情的报告、处理和卫生检验制度； （四）按照国家有关规定，制定应急抢救程序。"},{"i":31,"n":"第三十一条","txt":"滩海陆岸应急避难房应当符合下列规定： （一）能够容纳全部生产作业人员； （二）结构强度比滩海陆岸井台高一个安全等级； （三）地面高出挡浪墙1米； （四）采用基础稳定、结构可靠的固定式钢筋混凝土结构，或者采用可移动式钢结构； （五）配备可以供避难人员5日所需的救生食品和饮用水； （六）配备急救箱，至少装有2套救生衣、防水手电及配套电池、简单的医疗包扎用品和常用药品； （七）配备应急通讯装置。"},{"i":32,"n":"第三十二条","txt":"滩海陆岸值班车应当符合下列规定： （一）接受滩海陆岸石油设施作业负责人的指挥，不得擅自进入或者离开； （二）配备的通讯工具保证随时与滩海陆岸石油设施和陆岸基地通话； （三）能够容纳所服务的滩海陆岸石油设施的全部人员，并配备100%的救生衣； （四）具有在应急救助和人员撤离等复杂情况下作业的能力； （五）参加滩海陆岸石油设施上的营救演习。"},{"i":33,"n":"第三十三条","txt":"承担设施守护任务的船舶（以下简称守护船）在开始承担守护作业前，其所属单位应当向海油安办有关分部提交守护船登记表和守护船有关证书登记表，办理守护船登记手续。经海油安办有关分部审查合格后，予以登记，并签发守护船登记证明。守护船登记后，其原申报条件发生变化或者终止承担守护任务的，应当向原负责守护船登记的海油安办有关分部报告。"},{"i":34,"n":"第三十四条","txt":"守护船应当在距离所守护设施5海里之内的海区执行守护任务，不得擅自离开。在守护船的守护能力范围内，多座被守护设施可以共用一条守护船。"},{"i":35,"n":"第三十五条","txt":"守护船应当服从被守护设施负责人的指挥，能够接纳所守护设施全部人员，并配备可以供守护设施全部人员1日所需的救生食品和饮用水。"},{"i":36,"n":"第三十六条","txt":"守护船应当符合下列规定： （一）船舶证书齐全、有效； （二）具备守护海区的适航能力； （三）在船舶的两舷设有营救区，并尽可能远离推进器，营救区应当有醒目标志。营救区长度不小于载货甲板长度的1/3，宽度不小于3米； （四）甲板上设有露天空间，便于直升机绞车提升、平台吊篮下放等营救操作； （五）营救区及甲板露天空间处于守护船船长视野之内，便于指挥操作和营救。"},{"i":37,"n":"第三十七条","txt":"守护船应当配备能够满足应急救助和撤离人员需要的下列设备和器具： （一）1副吊装担架和1副铲式担架； （二）2副救助用长柄钩； （三）至少1套抛绳器； （四）4只带自亮浮灯、逆向反光带和绳子的救生圈，绳子长度不少于30米； （五）用于简易包扎和急救的医疗用品； （六）营救区舷侧的落水人员攀登用网； （七）1艘符合《国际海上人命安全公约》要求的救助艇； （八）至少2只探照灯，可以提供营救作业区及周围海区照明； （九）至少配备两种通讯工具，保证守护船与被守护设施和陆岸基地随时通话。"},{"i":38,"n":"第三十八条","txt":"守护船船员应当符合下列条件： （一）具有船员服务簿和适任证书等有效证件； （二）至少有3名船员从事落水人员营救工作； （三）至少有2名船员可以操纵救助艇； （四）至少有2名船员经过医疗急救培训，能够承担急救处置、包扎和人工呼吸等工作； （五）定期参加营救演习。"},{"i":39,"n":"第三十九条","txt":"守护船的登记证明有效期为3年，有效期满前15日内应当重新办理登记手续。"},{"i":40,"n":"第四十条","txt":"作业者或者承包者应当对提供直升机的公司进行安全条件审查和监督。"},{"i":41,"n":"第四十一条","txt":"直升机公司应当符合下列条件： （一）直升机持有中国民用航空局颁发的飞机适航证，并具备有效的飞机登记证和无线电台执照； （二）具有符合安全飞行条件的直升机，并达到该机型最低设备放行清单的标准； （三）具有符合安全飞行条件的驾驶员、机务维护人员和技术检查人员； （四）对直升机驾驶员进行夜航和救生训练，保证完成规定的训练小时数； （五）需要应急救援时，备有可以调用的直升机； （六）完善和落实飞行安全的各种规章制度，杜绝超气象条件和不按规定的航线和高度飞行。"},{"i":42,"n":"第四十二条","txt":"直升机应当配备下列应急救助设备： （一）直升机应急浮筒； （二）携带可以供机上所有人员使用的海上救生衣（在水温低于10℃的海域应当配备保温救生服）、救生筏及救生包，并备有可以供直升机使用的救生绞车； （三）直升机两侧有能够投弃的舱门或者具备足够的紧急逃生舱口。"},{"i":43,"n":"第四十三条","txt":"在额定载荷条件下，直升机应当具有航行于飞行基地与海上石油设施之间的适航能力和夜航能力。"},{"i":44,"n":"第四十四条","txt":"飞行作业前，直升机所属公司应当制定安全应急程序，并与作业者或者承包者编制的应急预案相协调。"},{"i":45,"n":"第四十五条","txt":"直升机在飞行作业中必须配有2名驾驶员，并指定其中1人为责任机长；由中外籍驾驶员合作驾驶的直升机，2名驾驶员应当有相应的语言技能水平，能够直接交流对话。"},{"i":46,"n":"第四十六条","txt":"作业者或者承包者及直升机所属公司必须确保飞行基地（或者备用机场）和海上石油设施上的直升机起降设备处于安全和适用状态。"},{"i":47,"n":"第四十七条","txt":"作业者或者承包者及直升机所属公司，应当通过协商制订飞行条件与应急飞行、乘机安全、载物安全和飞行故障、飞行事故报告等制度。"},{"i":48,"n":"第四十八条","txt":"设施应当制定电气设备检修前后的安全检查、日常运行检查、安全技术检查、定期安全检查等制度，建立健全电气设备的维修操作、电焊操作和手持电动工具操作等安全规程，并严格执行。"},{"i":49,"n":"第四十九条","txt":"电气管理应当符合下列规定： （一）按照国家规定配备和使用电工安全用具，并按规定定期检查和校验； （二）遇停电、送电、倒闸、带电作业和临时用电等情况，按照有关作业许可制度进行审批。临时用电作业结束后，立即拆除增加的电气设备和线路； （三）按照国家标准规定的颜色和图形，对电气设备和线路作出明显、准确的标识； （四）电气设备作业期间，至少有1名电气作业经验丰富的监护人进行实时监护； （五）电气设备按照铭牌上规定的额定参数（电压、电流、功率、频率等）运行，安装必要的过载、短路和漏电保护装置并定期校验。金属外壳（安全电压除外）有可靠的接地装置； （六）在触电危险性较大的场所，手提灯、便携式电气设备、电动工具等设备工具按照国家标准的规定使用安全电压。确实无法使用安全电压的，经设施负责人批准，并采用有效的防触电措施； （七）安装在不同等级危险区域的电气设备符合该等级的防爆类型。防爆电气设备上的部件不"},{"i":50,"n":"第五十条","txt":"设施必须配备必要的应急电源。应急电源应当符合下列规定： （一）能够满足通讯、信号、照明、基本生存条件（包括生活区、救生艇、撤离通道、直升机甲板等）和其他动力（包括消防系统、井控系统、火灾及可燃和有毒有害气体检测报警系统、应急关断系统等）的电源要求； （二）在主电源失电后，应急电源能够在45秒内自动安全启动供电； （三）应急电源远离危险区和主电源。"},{"i":51,"n":"第五十一条","txt":"作业者或者承包者应当制定油（气）井井控安全措施和防井喷应急预案。"},{"i":52,"n":"第五十二条","txt":"钻井作业应当符合下列规定： （一）钻井装置在新井位就位前，作业者和承包者应收集和分析相应的地质资料。如有浅层气存在，安装分流系统等； （二）钻井作业期间，在钻台上备有与钻杆相匹配的内防喷装置； （三）下套管时，防喷器尺寸与所下套管尺寸相匹配，并备有与所下套管丝扣相匹配的循环接头； （四）防喷器所用的橡胶密封件应当按厂商的技术要求进行维护和储存，不得将失效和技术条件不符的密封件安装到防喷器中； （五）水龙头下部安装方钻杆上旋塞，方钻杆下部安装下旋塞，并配备开关旋塞的扳手。顶部驱动装置下部安装手动和自动内防喷器（考克）并配备开关防喷器的扳手； （六）防喷器组由环形防喷器和闸板防喷器组成，闸板防喷器的闸板关闭尺寸与所使用钻杆或者管柱的尺寸相符。防喷器的额定工作压力，不得低于钻井设计压力，用于探井的不得低于70MPa； （七）防喷器及相应设备的安装、维护和试验，满足井控要求； （八）经常对防喷"},{"i":53,"n":"第五十三条","txt":"防喷器组控制系统的安装应当符合下列规定： （一）1套液压控制系统的储能器液体压力保持21MPa，储能器压力液体积为关闭全部防喷器并打开液动闸阀所需液体体积的1.5倍以上； （二）除钻台安装1台控制盘（台）外，另1台辅助控制盘（台）安装在远离钻台、便于操作的位置； （三）防喷器组配备与其额定工作压力相一致的防喷管汇、节流管汇和压井管汇； （四）压井管汇和节流管汇的防喷管线上，分别安装2个控制阀。其中一个为手动，处于常开位置；另一个必须是远程控制；（五）安装自动灌井液系统。"},{"i":54,"n":"第五十四条","txt":"水下防喷器组应当符合下列规定： （一）若有浅层气或者地质情况不清时，导管上安装分流系统； （二）在表层套管和中间（技术）套管上安装1个或者2个环形防喷器、2个双闸板防喷器，其中1副闸板为全封剪切闸板防喷器； （三）安装1组水下储能器，便于就近迅速提供液压能，以尽快开关各防喷器及其闸门。同时，采用互为备用的双控制盒系统，当一个控制盒系统正在使用时，另一个控制盒系统保持良好的工作状态作为备用； （四）如需修理或者更换防喷器组，必须保证井眼安全，尽量在下完套管固井后或者未钻穿水泥塞前进行。必要时，打1个水泥塞或者下桥塞后再进行修理或者更换； （五）使用复合式钻柱的，装有可变闸板，以适应不同的钻具尺寸。"},{"i":55,"n":"第五十五条","txt":"水上防喷器组应当符合下列基本规定： （一）若有浅层气或者地质情况不清时，隔水（导）管上安装分流系统； （二）表层套管上安装1个环形防喷器，1个双闸板防喷器；大于13〞3/8表层套管上可以只安装1个环形防喷器； （三）中间（技术）套管上安装1个环形、1个双闸板（或者2个单闸板）和1个剪切全封闭闸板防喷器； （四）使用复合式钻柱的，装有可变闸板，以适应不同的钻具尽寸。"},{"i":56,"n":"第五十六条","txt":"水上防喷器组的开关活动，应当符合下列规定： （一）闸板防喷器定期进行开关活动； （二）全封闸板防喷器每次起钻后进行开关活动。若每日多次起钻，只开关活动一次即可； （三）每起下钻一次，2个防喷器控制盘（台）交换动作一次。如果控制盘（台）失去动作功能，在恢复功能后，才能进行钻井作业； （四）节流管汇的阀门、方钻杆旋塞和钻杆内防喷装置，每周开关活动一次。 水下防喷器的开关活动，除了闸板防喷器1日进行开关活动一次外，其他开关活动次数与水上防喷器组开关活动次数相同。"},{"i":57,"n":"第五十七条","txt":"防喷器系统的试压，应当符合下列规定： （一）所有的防喷器及管汇在进行高压试验之前，进行2.1MPa的低压试验； （二）防喷器安装前或者更换主要配件后，进行整体压力试验； （三）按照井控车间（基地）组装、现场安装、钻开油气层前及更换井控装置部件的次序进行防喷器试压。试压的间隔不超过14日； （四）对于水上防喷器组，防喷器组在井控车间（基地）组装后，按额定工作压力进行试验。现场安装后，试验压力在不超过套管抗内压强度80%的前提下，环形防喷器的试验压力为额定工作压力的70%，闸板防喷器和相应控制设备的试验压力为额定工作压力； （五）对于水下防喷器组，水下防喷器和所有有关井控设备的试验压力为其额定工作压力的70%。防喷器组在现场安装完成后，控制设备和防喷器闸板按照水上防喷器组试压的规定进行。"},{"i":58,"n":"第五十八条","txt":"防喷器系统的检查与维护，应当符合下列规定： （一）整套防喷器系统、隔水（导）管和配套设备，按照制造厂商推荐的程序进行检查和维护； （二）在海况及气候条件允许的情况下，防喷器系统和隔水（导）管至少每日外观检查一次，水下设备的检查可以通过水下电视等工具完成。"},{"i":59,"n":"第五十九条","txt":"井液池液面和气体检测装置应当具备声光报警功能，其报警仪安装在钻台和综合录井室内；应当配备井液性能试验仪器。井液量应当符合下列规定： （一）开钻前，计算井液材料最小需要量，落实紧急情况补充井液的储备计划； （二）记录并保存井液材料（包括加重材料）的每日储存量。若储存量达不到所规定的最小数量时，停止钻井作业； （三）作业时，当返出井液密度比进口井液密度小0.02g/cm3时，将环形空间井液循环到地面，并对井液性能进行气体或者液体侵入的检查和处理； （四）起钻时，向井内灌注井液。当井内静止液面下降或者每起出3至5柱钻具之后应当灌满井液； （五）从井内起出钻杆测试工具前，井液应当进行循环或者反循环。"},{"i":60,"n":"第六十条","txt":"完井、试油和修井作业应当符合下列规定： （一）配备与作业相适应的防喷器及其控制系统； （二）按计划储备井液材料，其性能符合作业要求； （三）井控要求参照钻井作业有关规定执行； （四）滩海陆岸井控装置至少配备1套控制系统。"},{"i":61,"n":"第六十一条","txt":"气井、自喷井、自溢井应当安装井下封隔器；在海床面30米以下，应当安装井下安全阀，并符合下列规定： （一）定期进行水上控制的井下安全阀现场试验，试验间隔不得超过6个月。新安装或者重新安装的也应当进行试验； （二）海床完井的单井、卫星井或者多井基盘上，每口井安装水下控制的井下安全阀； （三）地面安全阀保持良好的工作状态； （四）配备适用的井口测压防喷盒。 紧急关闭系统应当保持良好的工作状态。作业者应当妥善保存各种水下安全装置的安装和调试记录等资料。"},{"i":62,"n":"第六十二条","txt":"进行电缆射孔、生产测井、钢丝作业时，在工具下井前，应当对防喷管汇进行压力试验。"},{"i":63,"n":"第六十三条","txt":"钻开油气层前100米时，应当通过钻井循环通道和节流管汇做一次低泵冲泵压试验。"},{"i":64,"n":"第六十四条","txt":"放喷管线应当使用专用管线。 在寒冷季节，应当对井控装备、防喷管汇、节流管汇、压力管汇和仪表等进行防冻保温。"},{"i":65,"n":"第六十五条","txt":"钻遇未知含硫化氢地层时，应当提前采取防范措施；钻遇已知含硫化氢地层时，应当实施检测和控制。 硫化氢探测、报警系统应当符合下列规定： （一）钻井装置上安装硫化氢报警系统。当空气中硫化氢的浓度超过15mg/m3（10ppm）时，系统即能以声光报警方式工作；固定式探头至少应当安装在喇叭口、钻台、振动筛、井液池、生活区、发电及配电房进风口等位置； （二）至少配备探测范围0～30mg/m3（0～20ppm）和0～150mg/m3（0～100ppm）的便携式硫化氢探测器各1套； （三）探测器件的灵敏度达到7.5mg/m3（5ppm）； （四）储备足够数量的硫化氢检测样品，以便随时检测探头。 人员保护器具应当符合下列规定： （一）通常情况下，钻井装置上配备15～20套正压式空气呼吸器。其中，生活区6～9套，钻台上5～6套，井液池附近（泥浆舱）2套，录井房2～3套。钻进已知含硫化氢地层前，或者临时钻遇"},{"i":66,"n":"第六十六条","txt":"在可能含有硫化氢地层进行钻井作业时，应当采取下列硫化氢防护措施： （一）在可能含有硫化氢地区的钻井设计中，标明含硫化氢地层及其深度，估算硫化氢的可能含量，以提醒有关作业人员注意，并制定必要的安全和应急措施； （二）当空气中硫化氢浓度达到15mg/m3（10ppm）时，及时通知所有平台人员注意，加密观察和测量硫化氢浓度的次数，检查并准备好正压式空气呼吸器； （三）当空气中硫化氢浓度达到30mg/m3（20ppm）时，在岗人员迅速取用正压式空气呼吸器，其他人员到达安全区。通知守护船在平台上风向海域起锚待命； （四）当空气中含硫化氢浓度达到150mg/m3（100ppm）时，组织所有人员撤离平台； （五）使用适合于钻遇含硫化氢地层的井液，钻井液的pH值保持在10以上。净化剂、添加剂和防腐剂等有适当的储备。钻井液中脱出的硫化氢气体集中排放，有条件情况下，可以点火燃烧； （六）钻遇含硫化氢地层，"},{"i":67,"n":"第六十七条","txt":"在可能含有硫化氢地层进行钻进作业时，其钻井设备、器具应当符合下列规定： （一）钻井设备具备抗硫应力开裂的性能； （二）管材具有在硫化氢环境中使用的性能，并按照国家有关标准的要求使用； （三）对所使用作业设备、管材、生产流程及附件等，定期进行安全检查和检测检验。"},{"i":68,"n":"第六十八条","txt":"完井和修井作业的硫化氢防护，参照钻井作业的有关要求执行。"},{"i":69,"n":"第六十九条","txt":"在可能含有硫化氢地层进行生产作业时，应当采取下列硫化氢防护措施： （一）生产设施上配备6套正压式空气呼吸器。在已知存在含硫油气生产设施上，全员配备正压式空气呼吸器，并配备一定数量的备用气瓶及1台呼吸器空气压缩机； （二）生产设施上配备2至3套便携式硫化氢探测仪、1套便携式比色指示管探测仪和1套便携式二氧化硫探测仪。在已知存在硫化氢的生产装置上，安装硫化氢报警装置； （三）当空气中硫化氢达到15mg/m3（10ppm）或者二氧化硫达到5.4mg/m3（2ppm）时，作业人员佩戴正压式空气呼吸器； （四）装置上配有用于处理硫化氢中毒的医疗用品、心肺复苏器和氧气瓶； （五）在油气井投产前，采取有效措施，加强对硫化氢、二氧化硫和二氧化碳的防护； （六）用于油气生产的设备、设施和管道等具有抗硫化氢腐蚀的性能。"},{"i":70,"n":"第七十条","txt":"作业者和承包者应当加强系泊和起重作业过程中系物器具和被系器具的安全管理。"},{"i":71,"n":"第七十一条","txt":"作业者和承包者应当制定系物器具和被系器具的安全管理责任制，明确各岗位和各工种责任制；应当制定系物器具和被系器具的使用管理规定，对系物器具和被系器具进行经常性维护、保养，保证正常使用。维护、保养应当作好记录，并由有关人员签字。"},{"i":72,"n":"第七十二条","txt":"系物器具应当按照有关规定由海油安办认可的检验机构对其定期进行检验，并作出标记。作业者和承包者为满足特殊需要，自行加工制造系物器具和被系器具的，系物器具和被系器具必须经海油安办认可的检验机构检验合格后，方可投入使用。"},{"i":73,"n":"第七十三条","txt":"箱件的使用，除了符合本细则第七十一条和第七十二条规定要求外，还应当满足下列要求： （一）箱外有明显的尺寸、自重和额定安全载重标记； （二）定期对其主要受力部位进行检验。"},{"i":74,"n":"第七十四条","txt":"吊网的使用，除了符合第七十一条和第七十二条规定外，还应当符合下列要求： （一）标有安全工作负荷标记； （二）非金属网不得超过其使用范围和环境。"},{"i":75,"n":"第七十五条","txt":"乘人吊篮必须专用，并标有额定载重和限乘人数的标记；应当按产品说明书的规定定期进行技术检验。"},{"i":76,"n":"第七十六条","txt":"系物器具和被系器具有下列情形之一的，应当停止使用： （一）已达到报废标准而未报废，或者已经报废的； （二）未标明检验日期的； （三）超过规定检验期限的。"},{"i":77,"n":"第七十七条","txt":"作业者、承包者应当建立放射性、爆炸性物品（以下简称危险物品）的领取和归还制度。危险物品的领取和归还应当遵守下列规定： （一）领取人持有领取单领取相应的危险物品。领取单详细记载危险物品的种类和数量； （二）领取和归还危险物品时，使用专用的工具。放射性源盛装在罐内，爆炸性物品存放在箱内； （三）出入库的放射性源罐，配有浮标或者其他示位器具； （四）危险物品出入库有记录，领取人和库管员在出入库单上签字； （五）未用完的危险物品，及时归还。"},{"i":78,"n":"第七十八条","txt":"危险物品的运输，应当符合下列规定： （一）符合国家有关法律、法规、规章、标准的要求，并有专人押运； （二）有可靠的安全措施和应急措施； （三）符合有关运输手续，有明显的危险物品运输标识。"},{"i":79,"n":"第七十九条","txt":"危险物品的使用，应当符合下列规定： （一）作业前，按照有关规定申请使用许可证。取得使用许可证后，方可使用危险物品。使用有详细记录。使用后，及时将未使用完的危险物品回收入库； （二）作业时，制定安全可靠的作业规程。有关作业人员熟悉并遵守作业规程； （三）现场设有明显、清晰的危险标识，以防止非作业人员进入作业区； （四）现场至少配备1台便携式放射性强度测量仪； （五）按照国家有关标准的要求，对放射源与载源设备的性能进行检验。"},{"i":80,"n":"第八十条","txt":"危险物品的存放，应当符合下列规定： （一）存放场所远离生活区、人员密集区及危险区，并标有明显的“危险品”标识； （二）采取有效的防火安全措施； （三）不得将爆炸性物品中的炸药与雷管或者放射性物品存放在同一储存室内。"},{"i":81,"n":"第八十一条","txt":"对失效的或者外壳泄漏试验不合格（超过185Bq）的放射源，应当采取安全的方式妥善处置。"},{"i":82,"n":"第八十二条","txt":"作业人员使用放射性物品的，应当采取下列防护措施： （一）配有个人辐照剂量检测用具，并建立辐照剂量档案； （二）每年至少进行一次体检，体检结果存档； （三）发现作业人员受到放射性伤害的，立即调离其工作岗位，并按照有关规定进行治疗和康复； （三）作业人员调动工作的，其辐照剂量档案和体检档案随工作岗位一起调动。"},{"i":83,"n":"第八十三条","txt":"作业者或者承包者在进行弃井作业或者清除井口遗留物30日前，应当向海油安办有关分部报送下列材料： （一）弃井作业或者清除井口遗留物安全风险评价报告； （二）弃井或者清除井口遗留物施工方案、作业程序、时间安排、井液性能等。 海油安办有关分部应当对作业者或者承包者报送的材料进行审核；材料内容不符合技术要求的，通知作业者或者承包者进行完善。"},{"i":84,"n":"第八十四条","txt":"弃井作业或者清除井口遗留物施工作业期间，海油安办有关分部认为必要时，进行现场监督。 施工作业完成后15日内，作业者或者承包者应当向海油安办有关分部提交下列资料： （一）弃井或者清除井口遗留物作业完工图； （二）弃井作业最终报告表。"},{"i":85,"n":"第八十五条","txt":"对于永久性弃井的，应当符合下列要求： （一）在裸露井眼井段，对油、气、水等渗透层进行全封，在其上部打至少50米水泥塞，以封隔油、气、水等渗透层，防止互窜或者流出海底。裸眼井段无油、气、水时，在最后一层套管的套管鞋以下和以上各打至少30米水泥塞； （二）已下尾管的，在尾管顶部上下30米的井段各打至少30米水泥塞； （三）已在套管或者尾管内进行了射孔试油作业的，对射孔层进行全封，在其上部打至少50米的水泥塞； （四）已切割的每层套管内，保证切割处上下各有至少20米的水泥塞； （五）表层套管内水泥塞长度至少有45米，且水泥塞顶面位于海底泥面下4米至30米之间。 对于临时弃井的，应当符合下列要求： （一）在最深层套管柱的底部至少打50米水泥塞； （二）在海底泥面以下4米的套管柱内至少打30米水泥塞。"},{"i":86,"n":"第八十六条","txt":"永久弃井时，所有套管、井口装置或者桩应当按照国家有关规定实施清除作业。对保留在海底的水下井口装置或者井口帽，应当按照国家有关规定向海油安办有关分部进行报告。"},{"i":87,"n":"第八十七条","txt":"作业者和承包者的主要负责人和安全生产管理人员应当具备相应的安全生产知识和管理能力，经海油安办考核合格。"},{"i":88,"n":"第八十八条","txt":"作业者和承包者应当组织对海上石油作业人员进行安全生产培训。未经培训并取得培训合格证书的作业人员，不得上岗作业。 作业者和承包者应当建立海上石油作业人员的培训档案，加强对出海作业人员（包括在境外培训的人员）的培训证书的审查。未取得培训合格证书的，一律不得出海作业。"},{"i":89,"n":"第八十九条","txt":"出海人员必须接受“海上石油作业安全救生”的专门培训，并取得培训合格证书。 安全培训的内容和时间应当符合下列要求： （一）长期出海人员接受“海上石油作业安全救生”全部内容的培训，培训时间不少于40课时。每5年进行一次再培训； （二）短期出海人员接受“海上石油作业安全救生”综合内容的培训，培训时间不少于24课时。每3年进行一次再培训； （三）临时出海人员接受“海上石油作业安全救生”电化教学的培训，培训时间不少于4课时。每1年进行一次再培训； （四）不在设施上留宿的临时出海人员可以只接受作业者或者承包者现场安全教育； （五）没有直升机平台或者已明确不使用直升机倒班的海上设施人员，可以免除“直升机遇险水下逃生”内容的培训； （六）没有配备救生艇筏的海上设施作业人员，可以免除“救生艇筏操纵”的培训。"},{"i":90,"n":"第九十条","txt":"海上油气生产设施兼职消防队员应当接受“油气消防”的培训，培训时间不少于24课时。每4年应当进行一次再培训。"},{"i":91,"n":"第九十一条","txt":"从事钻井、完井、修井、测试作业的监督、经理、高级队长、领班，以及司钻、副司钻和井架工、安全监督等人员应当接受“井控技术”的培训，培训时间不少于56课时，并取得培训合格证书。每4年应当进行一次再培训。"},{"i":92,"n":"第九十二条","txt":"稳性压载人员（含钻井平台、浮式生产储油装置的稳性压载、平台升降的技术人员）应当接受“稳性与压载技术”的培训，培训时间不少于36课时，并取得培训合格证书。每4年应当进行一次再培训。"},{"i":93,"n":"第九十三条","txt":"在作业过程中已经出现或者可能出现硫化氢的场所从事钻井、完井、修井、测试、采油及储运作业的人员，应当进行“防硫化氢技术”的专门培训，培训时间不少于16课时，并取得培训合格证书。每4年应当进行一次再培训。"},{"i":94,"n":"第九十四条","txt":"无线电技术操作人员应当按政府有关主管部门的要求进行培训，取得相应的资格证书。"},{"i":95,"n":"第九十五条","txt":"属于特种作业人员范围的特种作业人员应当按照有关法律法规的要求进行专门培训，取得特种作业操作资格证书。"},{"i":96,"n":"第九十六条","txt":"外方人员在国外合法注册和政府认可的培训机构取得的证书和证件，经中方作业者或者承包者确认后在中国继续有效。"},{"i":97,"n":"第九十七条","txt":"作业者和承包者应当按照有关法律、法规、规章和标准的要求，结合生产实际编制应急预案，并报海油安办有关分部备案。 作业者和承包者应当根据海洋石油作业的变化，及时对应急预案进行修改、补充和完善。"},{"i":98,"n":"第九十八条","txt":"根据海洋石油作业的特点，作业者和承包者编制的应急预案应当包括下列内容： （一）作业者和承包者的基本情况、危险特性、可以利用的应急救援设备； （二）应急组织机构、职责划分、通讯联络； （三）应急预案启动、应急响应、信息处理、应急状态中止、后续恢复等处置程序； （四）应急演习与训练。"},{"i":99,"n":"第九十九条","txt":"应急预案的应急范围包括井喷失控、火灾与爆炸、平台遇险、直升机失事、船舶海损、油（气）生产设施与管线破损和泄漏、有毒有害物品泄漏、放射性物品遗散、潜水作业事故；人员重伤、死亡、失踪及暴发性传染病、中毒；溢油事故、自然灾害以及其他紧急情况。"},{"i":100,"n":"第一百条","txt":"除作业者和承包者编制的公司一级应急预案外，针对每个生产和作业设施应当结合工作实际，编制应急预案。应急预案包括主件和附件两个部分内容。 主件部分应当包括下列主要内容： （一）生产或者作业设施名称、作业海区、编写者和编写日期； （二）生产或者作业设施的应急组织机构、指挥系统、医疗机构及各级应急岗位人员职责； （三）处置各类突发性事故或者险情的措施和联络报告程序； （四）生产或者作业设施上所具有的通讯设备类型、能力以及应急通讯频率； （五）应急组织、上级主管部门和有关部门的负责人通讯录，包括通讯地址、电话和传真等； （六）与有关部门联络的应急工作联系程序图或者网络图； （七）应急训练内容、频次和要求； （八）其他需要明确的内容。 附件部分应当包括下列主要内容： （一）生产或者作业设施的主要基础数据； （二）生产或者作业设施所处自然环境的描述，包括：作业海区的气象资料，可能出现的灾害性天气（如"},{"i":101,"n":"第一百零一条","txt":"作业者和承包者应当组织生产和作业设施的相关人员定期开展应急预案的演练，演练期限不超过下列时间间隔的要求： （一）消防演习：每倒班期一次。 （二）弃平台演习：每倒班期一次。 （三）井控演习：每倒班期一次。 （四）人员落水救助演习：每季度一次。 （五）硫化氢演习：钻遇含硫化氢地层前和对含硫化氢油气井进行试油或者修井作业前，必须组织一次防硫化氢演习；对含硫化氢油气井进行正常钻井、试油或者修井作业，每隔7日组织一次演习；含硫化氢油气井正常生产时，每倒班期组织一次演习。不含硫化氢的，每半年组织一次。 各类应急演练的记录文件应当至少保存1年。"},{"i":102,"n":"第一百零二条","txt":"事故发生后，作业现场有关人员应当及时向所属作业者和承包者报告；接到报告后，应当立即启动相应的应急预案，组织开展救援活动，防止事故扩大，减少人员伤亡和财产损失。"},{"i":103,"n":"第一百零三条","txt":"针对海洋石油作业过程中发生事故的特点，在实施应急救援过程中，作业者和承包者应当做好下列工作： （一）立即组织现场疏散，保护作业人员安全； （二）立即调集作业现场的应急力量进行救援，同时向有关方面发出求助信息，动员有关力量，保证应急队伍、设备、器材、物资及必要的后勤支持； （三）制订现场救援方案并组织实施； （四）确定警戒及防控区域，实行区域管制； （五）采取相应的保护措施，防止事故扩大和引发次生灾害； （六）迅速组织医疗救援力量，抢救受伤人员； （七）尽力防止出现石油大面积泄漏和扩散。"},{"i":104,"n":"第一百零四条","txt":"在海上石油天然气勘探、开发、生产、储运及油田废弃等作业中，发生下列生产安全事故，作业现场有关人员应当立即向所属作业者和承包者报告；作业者和承包者接到报告后，应当立即按规定向海油安办有关分部的地区监督处、当地政府和海事部门报告： （一）井喷失控； （二）火灾与爆炸； （三）平台遇险（包括平台失控漂移、拖航遇险、被碰撞或者翻沉）； （四）飞机事故； （五）船舶海损（包括碰撞、搁浅、触礁、翻沉、断损）； （六）油（气）生产设施与管线破损（包括单点系泊、电气管线、海底油气管线等的破损、泄漏、断裂）； （七）有毒有害物品和气体泄漏或者遗散； （八）急性中毒； （九）潜水作业事故； （十）大型溢油事故（溢油量大于100吨）； （十一）其他造成人员伤亡或者直接经济损失的事故。"},{"i":105,"n":"第一百零五条","txt":"海油安办有关分部的地区监督处接到事故报告后，应当立即上报海油安办有关分部。海油安办有关分部接到较大事故及以上的事故报告后，应当在1小时内上报国家安全生产监督管理总局。 飞机事故、船舶海损、大型溢油除报告海油安办外，还应当按规定报告有关政府主管部门。"},{"i":106,"n":"第一百零六条","txt":"海洋石油的生产安全事故按照下列规定进行调查： （一）没有人员伤亡的一般事故，海油安办有关分部可以委托作业者和承包者组织生产、技术、安全等有关人员及工会成员组成事故调查组进行调查； （二）造成人员伤亡的一般事故，由海油安办有关分部牵头组织有关部门及工会成立事故调查组进行调查，并邀请人民检察院派人参加； （三）造成较大事故，由海油安办牵头组织有关部门成立事故调查组进行调查，并邀请人民检察院派人参加； （四）重大事故，由国家安全生产监督管理总局牵头组织有关部门成立事故调查组进行调查，并邀请人民检察院派人参加； （五）特别重大事故，按照国务院有关规定执行。 飞机失事、船舶海损、放射性物品遗散和大型溢油等海洋石油生产安全事故依法由民航、海事、环保等有关部门组织调查处理。"},{"i":107,"n":"第一百零七条","txt":"海洋石油的生产安全事故调查报告按照下列规定批复： （一）一般事故的调查报告，在征得海油安办同意后，由海油安办有关分部批复； （二）较大、重大事故的调查报告由国家安全生产监督管理总局批复； （三）特别重大事故调查报告的批复按照国务院有关规定执行。"},{"i":108,"n":"第一百零八条","txt":"作业者和承包者应当按照事故调查报告的批复，对负有责任的人员进行处理。 事故发生单位应当认真吸取事故教训，落实防范和整改措施，防止事故再次发生。"},{"i":109,"n":"第一百零九条","txt":"海油安办及其有关分部应当按照法律、行政法规、规章和标准的规定，依法对海洋石油生产经营单位的安全生产实施监督检查。"},{"i":110,"n":"第一百一十条","txt":"海油安办有关分部应当建立生产设施、作业设施的备案档案管理制度，并于每年1月31日前将上一年度的备案情况报海油安办。备案档案应当至少保存3年。"},{"i":111,"n":"第一百一十一条","txt":"海油安办有关分部应当对安全培训机构、作业者和承包者安全教育培训情况进行监督检查。"},{"i":112,"n":"第一百一十二条","txt":"海油安办及其有关分部应当按照生产安全事故的批复，依照有关法律、行政法规和规章的规定，对事故发生单位和有关人员进行行政处罚；对负有事故责任的国家工作人员，按照干部管理权限交由有关单位和行政监察机关追究。"},{"i":113,"n":"第一百一十三条","txt":"作业者和承包者有下列行为之一的，给予警告，可以并处3万元以下的罚款： （一）生产设施、作业设施未按规定备案的； （二）未配备守护船，或者未按规定登记的； （三）海洋石油专业设备未按期进行检验的； （四）拒绝、阻碍海油安办及有关分部依法监督检查的。"},{"i":114,"n":"第一百一十四条","txt":"作业者和承包者有下列行为之一的，依法责令停产整顿，给予相应的行政处罚： （一）未履行新建、改建、扩建项目“三同时”程序的； （二）对存在的重大事故隐患，不按期进行整改的。"},{"i":115,"n":"第一百一十五条","txt":"海油安办及有关分部监督检查人员在海洋石油监督检查中滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予行政处分。"},{"i":116,"n":"第一百一十六条","txt":"本细则中下列用语的含义： （一）海洋石油作业设施，是指用于海洋石油作业的海上移动式钻井船（平台）、物探船、铺管船、起重船、固井船、酸化压裂船等设施； （二）海洋石油生产设施，是指以开采海洋石油为目的的海上固定平台、单点系泊、浮式生产储油装置（FPSO）、海底管线、海上输油码头、滩海陆岸、人工岛和陆岸终端等海上和陆岸结构物； （三）滩海陆岸石油设施，是指最高天文潮位以下滩海区域内，采用筑路或者栈桥等方式与陆岸相连接，从事石油作业活动中修筑的滩海通井路、滩海井台及有关石油设施； （四）专业设备，是指海洋石油开采过程中使用的危险性较大或者对安全生产有较大影响的设备，包括海上结构、采油设备、海上锅炉和压力容器、钻井和修井设备、起重和升降设备、火灾和可燃气体探测、报警及控制系统、安全阀、救生设备、消防器材、钢丝绳等系物及被系物、电气仪表等； （五）海底长输油（气）管线，是指从一个海上油（气）田外"},{"i":117,"n":"第一百一十七条","txt":"本细则所规定的有关文书格式，由海油安办统一式样。"},{"i":118,"n":"第一百一十八条","txt":"从事内陆湖泊的石油开采活动，参照本细则有关规定执行。"},{"i":119,"n":"第一百一十九条","txt":"本细则自2009年12月1日起施行。"}],"huozaishigudiaochaguiding":[{"i":1,"n":"第一条","txt":"为了规范火灾事故调查，保障公安机关消防机构依法履行职责，保护火灾当事人的合法权益，根据《中华人民共和国消防法》，制定本规定。"},{"i":2,"n":"第二条","txt":"公安机关消防机构调查火灾事故，适用本规定。"},{"i":3,"n":"第三条","txt":"火灾事故调查的任务是调查火灾原因，统计火灾损失，依法对火灾事故作出处理，总结火灾教训。"},{"i":4,"n":"第四条","txt":"火灾事故调查应当坚持及时、客观、公正、合法的原则。 任何单位和个人不得妨碍和非法干预火灾事故调查。"},{"i":5,"n":"第五条","txt":"火灾事故调查由县级以上人民政府公安机关主管，并由本级公安机关消防机构实施；尚未设立公安机关消防机构的，由县级人民政府公安机关实施。 公安派出所应当协助公安机关火灾事故调查部门维护火灾现场秩序，保护现场，控制火灾肇事嫌疑人。 铁路、港航、民航公安机关和国有林区的森林公安机关消防机构负责调查其消防监督范围内发生的火灾。"},{"i":6,"n":"第六条","txt":"火灾事故调查由火灾发生地公安机关消防机构按照下列分工进行： （一）一次火灾死亡十人以上的，重伤二十人以上或者死亡、重伤二十人以上的，受灾五十户以上的，由省、自治区人民政府公安机关消防机构负责组织调查； （二）一次火灾死亡一人以上的，重伤十人以上的，受灾三十户以上的，由设区的市或者相当于同级的人民政府公安机关消防机构负责组织调查； （三）一次火灾重伤十人以下或者受灾三十户以下的，由县级人民政府公安机关消防机构负责调查。 直辖市人民政府公安机关消防机构负责组织调查一次火灾死亡三人以上的，重伤二十人以上或者死亡、重伤二十人以上的，受灾五十户以上的火灾事故，直辖市的区、县级人民政府公安机关消防机构负责调查其他火灾事故。 仅有财产损失的火灾事故调查，由省级人民政府公安机关结合本地实际作出管辖规定，报公安部备案。"},{"i":7,"n":"第七条","txt":"跨行政区域的火灾，由最先起火地的公安机关消防机构按照本规定第六条的分工负责调查，相关行政区域的公安机关消防机构予以协助。 对管辖权发生争议的，报请共同的上一级公安机关消防机构指定管辖。县级人民政府公安机关负责实施的火灾事故调查管辖权发生争议的，由共同的上一级主管公安机关指定。"},{"i":8,"n":"第八条","txt":"上级公安机关消防机构应当对下级公安机关消防机构火灾事故调查工作进行监督和指导。 上级公安机关消防机构认为必要时，可以调查下级公安机关消防机构管辖的火灾。"},{"i":9,"n":"第九条","txt":"公安机关消防机构接到火灾报警，应当及时派员赶赴现场，并指派火灾事故调查人员开展火灾事故调查工作。"},{"i":10,"n":"第十条","txt":"具有下列情形之一的，公安机关消防机构应当立即报告主管公安机关通知具有管辖权的公安机关刑侦部门，公安机关刑侦部门接到通知后应当立即派员赶赴现场参加调查；涉嫌放火罪的，公安机关刑侦部门应当依法立案侦查，公安机关消防机构予以协助： （一）有人员死亡的火灾； （二）国家机关、广播电台、电视台、学校、医院、养老院、托儿所、幼儿园、文物保护单位、邮政和通信、交通枢纽等部门和单位发生的社会影响大的火灾； （三）具有放火嫌疑的火灾。"},{"i":11,"n":"第十一条","txt":"军事设施发生火灾需要公安机关消防机构协助调查的，由省级人民政府公安机关消防机构或者公安部消防局调派火灾事故调查专家协助。"},{"i":12,"n":"第十二条","txt":"同时具有下列情形的火灾，可以适用简易调查程序： （一）没有人员伤亡的； （二）直接财产损失轻微的； （三）当事人对火灾事故事实没有异议的； （四）没有放火嫌疑的。 前款第二项的具体标准由省级人民政府公安机关确定，报公安部备案。"},{"i":13,"n":"第十三条","txt":"适用简易调查程序的，可以由一名火灾事故调查人员调查，并按照下列程序实施： （一）表明执法身份，说明调查依据； （二）调查走访当事人、证人，了解火灾发生过程、火灾烧损的主要物品及建筑物受损等与火灾有关的情况； （三）查看火灾现场并进行照相或者录像； （四）告知当事人调查的火灾事故事实，听取当事人的意见，当事人提出的事实、理由或者证据成立的，应当采纳； （五）当场制作火灾事故简易调查认定书，由火灾事故调查人员、当事人签字或者捺指印后交付当事人。 火灾事故调查人员应当在二日内将火灾事故简易调查认定书报所属公安机关消防机构备案。"},{"i":14,"n":"第十四条","txt":"除依照本规定适用简易调查程序的外，公安机关消防机构对火灾进行调查时，火灾事故调查人员不得少于两人。必要时，可以聘请专家或者专业人员协助调查。"},{"i":15,"n":"第十五条","txt":"公安部和省级人民政府公安机关应当成立火灾事故调查专家组，协助调查复杂、疑难的火灾。专家组的专家协助调查火灾的，应当出具专家意见。"},{"i":16,"n":"第十六条","txt":"火灾发生地的县级公安机关消防机构应当根据火灾现场情况，排除现场险情，保障现场调查人员的安全，并初步划定现场封闭范围，设置警戒标志，禁止无关人员进入现场，控制火灾肇事嫌疑人。 公安机关消防机构应当根据火灾事故调查需要，及时调整现场封闭范围，并在现场勘验结束后及时解除现场封闭。"},{"i":17,"n":"第十七条","txt":"封闭火灾现场的，公安机关消防机构应当在火灾现场对封闭的范围、时间和要求等予以公告。"},{"i":18,"n":"第十八条","txt":"公安机关消防机构应当自接到火灾报警之日起三十日内作出火灾事故认定；情况复杂、疑难的，经上一级公安机关消防机构批准，可以延长三十日。 火灾事故调查中需要进行检验、鉴定的，检验、鉴定时间不计入调查期限。"},{"i":19,"n":"第十九条","txt":"火灾事故调查人员应当根据调查需要，对发现、扑救火灾人员，熟悉起火场所、部位和生产工艺人员，火灾肇事嫌疑人和被侵害人等知情人员进行询问。对火灾肇事嫌疑人可以依法传唤。必要时，可以要求被询问人到火灾现场进行指认。 询问应当制作笔录，由火灾事故调查人员和被询问人签名或者捺指印。被询问人拒绝签名和捺指印的，应当在笔录中注明。"},{"i":20,"n":"第二十条","txt":"勘验火灾现场应当遵循火灾现场勘验规则，采取现场照相或者录像、录音，制作现场勘验笔录和绘制现场图等方法记录现场情况。 对有人员死亡的火灾现场进行勘验的，火灾事故调查人员应当对尸体表面进行观察并记录，对尸体在火灾现场的位置进行调查。 现场勘验笔录应当由火灾事故调查人员、证人或者当事人签名。证人、当事人拒绝签名或者无法签名的，应当在现场勘验笔录上注明。现场图应当由制图人、审核人签字。"},{"i":21,"n":"第二十一条","txt":"现场提取痕迹、物品，应当按照下列程序实施： （一）量取痕迹、物品的位置、尺寸，并进行照相或者录像； （二）填写火灾痕迹、物品提取清单，由提取人、证人或者当事人签名；证人、当事人拒绝签名或者无法签名的，应当在清单上注明； （三）封装痕迹、物品，粘贴标签，标明火灾名称和封装痕迹、物品的名称、编号及其提取时间，由封装人、证人或者当事人签名；证人、当事人拒绝签名或者无法签名的，应当在标签上注明。 提取的痕迹、物品，应当妥善保管。"},{"i":22,"n":"第二十二条","txt":"根据调查需要，经负责火灾事故调查的公安机关消防机构负责人批准，可以进行现场实验。现场实验应当照相或者录像，制作现场实验报告，并由实验人员签字。现场实验报告应当载明下列事项： （一）实验的目的； （二）实验时间、环境和地点； （三）实验使用的仪器或者物品； （四）实验过程； （五）实验结果； （六）其他与现场实验有关的事项。"},{"i":23,"n":"第二十三条","txt":"现场提取的痕迹、物品需要进行专门性技术鉴定的，公安机关消防机构应当委托依法设立的鉴定机构进行，并与鉴定机构约定鉴定期限和鉴定检材的保管期限。 公安机关消防机构可以根据需要委托依法设立的价格鉴证机构对火灾直接财产损失进行鉴定。"},{"i":24,"n":"第二十四条","txt":"有人员死亡的火灾，为了确定死因，公安机关消防机构应当立即通知本级公安机关刑事科学技术部门进行尸体检验。公安机关刑事科学技术部门应当出具尸体检验鉴定文书，确定死亡原因。"},{"i":25,"n":"第二十五条","txt":"卫生行政主管部门许可的医疗机构具有执业资格的医生出具的诊断证明，可以作为公安机关消防机构认定人身伤害程度的依据。但是，具有下列情形之一的，应当由法医进行伤情鉴定： （一）受伤程度较重，可能构成重伤的； （二）火灾受伤人员要求作鉴定的； （三）当事人对伤害程度有争议的； （四）其他应当进行鉴定的情形。"},{"i":26,"n":"第二十六条","txt":"对受损单位和个人提供的由价格鉴证机构出具的鉴定意见，公安机关消防机构应当审查下列事项： （一）鉴证机构、鉴证人是否具有资质、资格； （二）鉴证机构、鉴证人是否盖章签名； （三）鉴定意见依据是否充分； （四）鉴定是否存在其他影响鉴定意见正确性的情形。 对符合规定的，可以作为证据使用；对不符合规定的，不予采信。"},{"i":27,"n":"第二十七条","txt":"受损单位和个人应当于火灾扑灭之日起七日内向火灾发生地的县级公安机关消防机构如实申报火灾直接财产损失，并附有效证明材料。"},{"i":28,"n":"第二十八条","txt":"公安机关消防机构应当根据受损单位和个人的申报、依法设立的价格鉴证机构出具的火灾直接财产损失鉴定意见以及调查核实情况，按照有关规定，对火灾直接经济损失和人员伤亡进行如实统计。"},{"i":29,"n":"第二十九条","txt":"公安机关消防机构应当根据现场勘验、调查询问和有关检验、鉴定意见等调查情况，及时作出起火原因的认定。"},{"i":30,"n":"第三十条","txt":"对起火原因已经查清的，应当认定起火时间、起火部位、起火点和起火原因；对起火原因无法查清的，应当认定起火时间、起火点或者起火部位以及有证据能够排除和不能排除的起火原因。"},{"i":31,"n":"第三十一条","txt":"公安机关消防机构在作出火灾事故认定前，应当召集当事人到场，说明拟认定的起火原因，听取当事人意见；当事人不到场的，应当记录在案。"},{"i":32,"n":"第三十二条","txt":"公安机关消防机构应当制作火灾事故认定书，自作出之日起七日内送达当事人，并告知当事人申请复核的权利。无法送达的，可以在作出火灾事故认定之日起七日内公告送达。公告期为二十日，公告期满即视为送达。"},{"i":33,"n":"第三十三条","txt":"对较大以上的火灾事故或者特殊的火灾事故，公安机关消防机构应当开展消防技术调查，形成消防技术调查报告，逐级上报至省级人民政府公安机关消防机构，重大以上的火灾事故调查报告报公安部消防局备案。调查报告应当包括下列内容： （一）起火场所概况； （二）起火经过和火灾扑救情况； （三）火灾造成的人员伤亡、直接经济损失统计情况； （四）起火原因和灾害成因分析； （五）防范措施。 火灾事故等级的确定标准按照公安部的有关规定执行。"},{"i":34,"n":"第三十四条","txt":"公安机关消防机构作出火灾事故认定后，当事人可以申请查阅、复制、摘录火灾事故认定书、现场勘验笔录和检验、鉴定意见，公安机关消防机构应当自接到申请之日起七日内提供，但涉及国家秘密、商业秘密、个人隐私或者移交公安机关其他部门处理的依法不予提供，并说明理由。"},{"i":35,"n":"第三十五条","txt":"当事人对火灾事故认定有异议的，可以自火灾事故认定书送达之日起十五日内，向上一级公安机关消防机构提出书面复核申请；对省级人民政府公安机关消防机构作出的火灾事故认定有异议的，向省级人民政府公安机关提出书面复核申请。 复核申请应当载明申请人的基本情况，被申请人的名称，复核请求，申请复核的主要事实、理由和证据，申请人的签名或者盖章，申请复核的日期。"},{"i":36,"n":"第三十六条","txt":"复核机构应当自收到复核申请之日起七日内作出是否受理的决定并书面通知申请人。有下列情形之一的，不予受理： （一）非火灾当事人提出复核申请的； （二）超过复核申请期限的； （三）复核机构维持原火灾事故认定或者直接作出火灾事故复核认定的； （四）适用简易调查程序作出火灾事故认定的。 公安机关消防机构受理复核申请的，应当书面通知其他当事人，同时通知原认定机构。"},{"i":37,"n":"第三十七条","txt":"原认定机构应当自接到通知之日起十日内，向复核机构作出书面说明，并提交火灾事故调查案卷。"},{"i":38,"n":"第三十八条","txt":"复核机构应当对复核申请和原火灾事故认定进行书面审查，必要时，可以向有关人员进行调查；火灾现场尚存且未被破坏的，可以进行复核勘验。 复核审查期间，复核申请人撤回复核申请的，公安机关消防机构应当终止复核。"},{"i":39,"n":"第三十九条","txt":"复核机构应当自受理复核申请之日起三十日内，作出复核决定，并按照本规定第三十二条规定的时限送达申请人、其他当事人和原认定机构。对需要向有关人员进行调查或者火灾现场复核勘验的，经复核机构负责人批准，复核期限可以延长三十日。 原火灾事故认定主要事实清楚、证据确实充分、程序合法，起火原因认定正确的，复核机构应当维持原火灾事故认定。 原火灾事故认定具有下列情形之一的，复核机构应当直接作出火灾事故复核认定或者责令原认定机构重新作出火灾事故认定，并撤销原认定机构作出的火灾事故认定： （一）主要事实不清，或者证据不确实充分的； （二）违反法定程序，影响结果公正的； （三）认定行为存在明显不当，或者起火原因认定错误的； （四）超越或者滥用职权的。"},{"i":40,"n":"第四十条","txt":"原认定机构接到重新作出火灾事故认定的复核决定后，应当重新调查，在十五日内重新作出火灾事故认定。 复核机构直接作出火灾事故认定和原认定机构重新作出火灾事故认定前，应当向申请人、其他当事人说明重新认定情况；原认定机构重新作出的火灾事故认定书，应当按照本规定第三十二条规定的时限送达当事人，并报复核机构备案。 复核以一次为限。当事人对原认定机构重新作出的火灾事故认定，可以按照本规定第三十五条的规定申请复核。"},{"i":41,"n":"第四十一条","txt":"公安机关消防机构在火灾事故调查过程中，应当根据下列情况分别作出处理： （一）涉嫌失火罪、消防责任事故罪的，按照《公安机关办理刑事案件程序规定》立案侦查；涉嫌其他犯罪的，及时移送有关主管部门办理； （二）涉嫌消防安全违法行为的，按照《公安机关办理行政案件程序规定》调查处理；涉嫌其他违法行为的，及时移送有关主管部门调查处理； （三）依照有关规定应当给予处分的，移交有关主管部门处理。 对经过调查不属于火灾事故的，公安机关消防机构应当告知当事人处理途径并记录在案。"},{"i":42,"n":"第四十二条","txt":"公安机关消防机构向有关主管部门移送案件的，应当在本级公安机关消防机构负责人批准后的二十四小时内移送，并根据案件需要附下列材料： （一）案件移送通知书； （二）案件调查情况； （三）涉案物品清单； （四）询问笔录，现场勘验笔录，检验、鉴定意见以及照相、录像、录音等资料； （五）其他相关材料。 构成放火罪需要移送公安机关刑侦部门处理的，火灾现场应当一并移交。"},{"i":43,"n":"第四十三条","txt":"公安机关其他部门应当自接受公安机关消防机构移送的涉嫌犯罪案件之日起十日内，进行审查并作出决定。依法决定立案的，应当书面通知移送案件的公安机关消防机构；依法不予立案的，应当说明理由，并书面通知移送案件的公安机关消防机构，退回案卷材料。"},{"i":44,"n":"第四十四条","txt":"公安机关消防机构及其工作人员有下列行为之一的，依照有关规定给予责任人员处分；构成犯罪的，依法追究刑事责任： （一）指使他人错误认定或者故意错误认定起火原因的； （二）瞒报火灾、火灾直接经济损失、人员伤亡情况的； （三）利用职务上的便利，索取或者非法收受他人财物的； （四）其他滥用职权、玩忽职守、徇私舞弊的行为。"},{"i":45,"n":"第四十五条","txt":"本规定中下列用语的含义： （一）“当事人”，是指与火灾发生、蔓延和损失有直接利害关系的单位和个人。 （二）“户”，用于统计居民、村民住宅火灾，按照公安机关登记的家庭户统计。 （三）本规定中十五日以内（含本数）期限的规定是指工作日，不含法定节假日。 （四）本规定所称的“以上”含本数、本级，“以下”不含本数。"},{"i":46,"n":"第四十六条","txt":"火灾事故调查中有关回避、证据、调查取证、鉴定等要求，本规定没有规定的，按照《公安机关办理行政案件程序规定》执行。"},{"i":47,"n":"第四十七条","txt":"执行本规定所需要的法律文书式样，由公安部制定。"},{"i":48,"n":"第四十八条","txt":"本规定自2009年5月1日起施行。1999年3月15日发布施行的《火灾事故调查规定》（公安部令第37号）和2008年3月18日发布施行的《火灾事故调查规定修正案》（公安部令第100号）同时废止。"}],"yanhuabaozhushengchanqiyeanquanshengchanxukezhengsa6d7d4":[{"i":1,"n":"第一条","txt":"为了严格烟花爆竹生产企业安全生产准入条件，规范烟花爆竹安全生产许可证的颁发和管理工作，根据《安全生产许可证条例》、《烟花爆竹安全管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称烟花爆竹生产企业（以下简称企业），是指依法设立并取得工商营业执照或者企业名称工商预先核准文件，从事烟花爆竹生产的企业。"},{"i":3,"n":"第三条","txt":"企业应当依照本办法的规定取得烟花爆竹安全生产许可证（以下简称安全生产许可证）。 未取得安全生产许可证的，不得从事烟花爆竹生产活动。"},{"i":4,"n":"第四条","txt":"安全生产许可证的颁发和管理工作实行企业申请、一级发证、属地监管的原则。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局负责指导、监督全国安全生产许可证的颁发和管理工作，并对安全生产许可证进行统一编号。 省、自治区、直辖市人民政府安全生产监督管理部门按照全国统一配号，负责本行政区域内安全生产许可证的颁发和管理工作。"},{"i":6,"n":"第六条","txt":"企业的设立应当符合国家产业政策和当地产业结构规划，企业的选址应当符合当地城乡规划。 企业与周边建筑、设施的安全距离必须符合国家标准、行业标准的规定。"},{"i":7,"n":"第七条","txt":"企业的基本建设项目应当依照有关规定经县级以上人民政府或者有关部门批准，并符合下列条件： （一）建设项目的设计由具有乙级以上军工行业的弹箭、火炸药、民爆器材工程设计类别工程设计资质或者化工石化医药行业的有机化工、石油冶炼、石油产品深加工工程设计类型工程设计资质的单位承担； （二）建设项目的设计符合《烟花爆竹工程设计安全规范》（GB50161）的要求，并依法进行安全设施设计审查和竣工验收。"},{"i":8,"n":"第八条","txt":"企业的厂房和仓库等基础设施、生产设备、生产工艺以及防火、防爆、防雷、防静电等安全设备设施必须符合《烟花爆竹工程设计安全规范》（GB50161）、《烟花爆竹作业安全技术规程》（GB11652）等国家标准、行业标准的规定。 从事礼花弹生产的企业除符合前款规定外，还应当符合礼花弹生产安全条件的规定。"},{"i":9,"n":"第九条","txt":"企业的药物和成品总仓库、药物和半成品中转库、机械混药和装药工房、晾晒场、烘干房等重点部位应当根据《烟花爆竹企业安全监控系统通用技术条件》（AQ4101）的规定安装视频监控和异常情况报警装置，并设置明显的安全警示标志。"},{"i":10,"n":"第十条","txt":"企业的生产厂房数量和储存仓库面积应当与其生产品种及规模相适应。"},{"i":11,"n":"第十一条","txt":"企业生产的产品品种、类别、级别、规格、质量、包装、标志应当符合《烟花爆竹安全与质量》（GB10631）等国家标准、行业标准的规定。"},{"i":12,"n":"第十二条","txt":"企业应当设置安全生产管理机构，配备专职安全生产管理人员，并符合下列要求： （一）确定安全生产主管人员； （二）配备占本企业从业人员总数1%以上且至少有2名专职安全生产管理人员； （三）配备占本企业从业人员总数5%以上的兼职安全员。"},{"i":13,"n":"第十三条","txt":"企业应当建立健全主要负责人、分管负责人、安全生产管理人员、职能部门、岗位的安全生产责任制，制定下列安全生产规章制度和操作规程： （一）符合《烟花爆竹作业安全技术规程》（GB11652）等国家标准、行业标准规定的岗位安全操作规程； （二）药物存储管理、领取管理和余（废）药处理制度； （三）企业负责人及涉裸药生产线负责人值（带）班制度； （四）特种作业人员管理制度； （五）从业人员安全教育培训制度； （六）安全检查和隐患排查治理制度； （七）产品购销合同和销售流向登记管理制度； （八）新产品、新药物研发管理制度； （九）安全设施设备维护管理制度； （十）原材料购买、检验、储存及使用管理制度； （十一）职工出入厂（库）区登记制度； （十二）厂（库）区门卫值班（守卫）制度； （十三）重大危险源（重点危险部位）监控管理制度； （十四）安全生产费用提取和使用制度； （十五）劳动防护用品配备、使用和"},{"i":14,"n":"第十四条","txt":"企业主要负责人、分管安全生产负责人和专职安全生产管理人员应当经专门的安全生产培训和安全生产监督管理部门考核合格，取得安全资格证。 从事药物混合、造粒、筛选、装药、筑药、压药、切引、搬运等危险工序和烟花爆竹仓库保管、守护的特种作业人员，应当接受专业知识培训，并经考核合格取得特种作业操作证。 其他岗位从业人员应当依照有关规定经本岗位安全生产知识教育和培训合格。"},{"i":15,"n":"第十五条","txt":"企业应当依法参加工伤保险，为从业人员缴纳保险费。"},{"i":16,"n":"第十六条","txt":"企业应当依照国家有关规定提取和使用安全生产费用，不得挪作他用。"},{"i":17,"n":"第十七条","txt":"企业必须为从业人员配备符合国家标准或者行业标准的劳动防护用品，并依照有关规定对从业人员进行职业健康检查。"},{"i":18,"n":"第十八条","txt":"企业应当建立生产安全事故应急救援组织，制定事故应急预案，并配备应急救援人员和必要的应急救援器材、设备。"},{"i":19,"n":"第十九条","txt":"企业应当根据《烟花爆竹流向登记通用规范》（AQ4102）和国家有关烟花爆竹流向信息化管理的规定，建立并应用烟花爆竹流向管理信息系统。"},{"i":20,"n":"第二十条","txt":"企业应当依法进行安全评价。安全评价报告应当包括本办法第六条、第七条、第八条、第九条、第十条、第十七条、第十八条规定条件的符合性评价内容。"},{"i":21,"n":"第二十一条","txt":"企业申请安全生产许可证，应当向所在地设区的市级人民政府安全生产监督管理部门（以下统称初审机关）提出安全审查申请，提交下列文件、资料，并对其真实性负责： （一）安全生产许可证申请书（一式三份）； （二）工商营业执照或者企业名称工商预先核准文件（复制件）； （三）建设项目安全设施设计审查和竣工验收的证明材料； （四）安全生产管理机构及安全生产管理人员配备情况的书面文件； （五）各种安全生产责任制文件（复制件）； （六）安全生产规章制度和岗位安全操作规程目录清单； （七）企业主要负责人、分管安全生产负责人、专职安全生产管理人员名单和安全资格证（复制件）； （八）特种作业人员的特种作业操作证（复制件）和其他从业人员安全生产教育培训合格的证明材料； （九）为从业人员缴纳工伤保险费的证明材料； （十）安全生产费用提取和使用情况的证明材料； （十一）具备资质的中介机构出具的安全评价报告。"},{"i":22,"n":"第二十二条","txt":"新建企业申请安全生产许可证，应当在建设项目竣工验收通过之日起20个工作日内向所在地初审机关提出安全审查申请。"},{"i":23,"n":"第二十三条","txt":"初审机关收到企业提交的安全审查申请后，应当对企业的设立是否符合国家产业政策和当地产业结构规划、企业的选址是否符合城乡规划以及有关申请文件、资料是否符合要求进行初步审查，并自收到申请之日起20个工作日内提出初步审查意见（以下简称初审意见），连同申请文件、资料一并报省、自治区、直辖市人民政府安全生产监督管理部门（以下简称发证机关）。 初审机关在审查过程中，可以就企业的有关情况征求企业所在地县级人民政府的意见。"},{"i":24,"n":"第二十四条","txt":"发证机关收到初审机关报送的申请文件、资料和初审意见后，应当按照下列情况分别作出处理： （一）申请文件、资料不齐全或者不符合要求的，当场告知或者在5个工作日内出具补正通知书，一次告知企业需要补正的全部内容；逾期不告知的，自收到申请材料之日起即为受理； （二）申请文件、资料齐全，符合要求或者按照发证机关要求提交全部补正材料的，自收到申请文件、资料或者全部补正材料之日起即为受理。 发证机关应当将受理或者不予受理决定书面告知申请企业和初审机关。"},{"i":25,"n":"第二十五条","txt":"发证机关受理申请后，应当结合初审意见，组织有关人员对申请文件、资料进行审查。需要到现场核查的，应当指派2名以上工作人员进行现场核查；对从事黑火药、引火线、礼花弹生产的企业，应当指派2名以上工作人员进行现场核查。 发证机关应当自受理之日起45个工作日内作出颁发或者不予颁发安全生产许可证的决定。 对决定颁发的，发证机关应当自决定之日起10个工作日内送达或者通知企业领取安全生产许可证；对不予颁发的，应当在10个工作日内书面通知企业并说明理由。 现场核查所需时间不计算在本条规定的期限内。"},{"i":26,"n":"第二十六条","txt":"安全生产许可证分为正副本，正本为悬挂式，副本为折页式。正本、副本具有同等法律效力。"},{"i":27,"n":"第二十七条","txt":"企业在安全生产许可证有效期内有下列情形之一的，应当按照本办法第二十八条的规定申请变更安全生产许可证： （一）改建、扩建烟花爆竹生产（含储存）设施的； （二）变更产品类别、级别范围的； （三）变更企业主要负责人的； （四）变更企业名称的。"},{"i":28,"n":"第二十八条","txt":"企业有本办法第二十七条第一项情形申请变更的，应当自建设项目通过竣工验收之日起20个工作日内向所在地初审机关提出安全审查申请，并提交安全生产许可证变更申请书（一式三份）和建设项目安全设施设计审查和竣工验收的证明材料。 企业有本办法第二十七条第二项情形申请变更的，应当向所在地初审机关提出安全审查申请，并提交安全生产许可证变更申请书（一式三份）和专项安全评价报告（减少生产产品品种的除外）。 企业有本办法第二十七条第三项情形申请变更的，应当向所在地发证机关提交安全生产许可证变更申请书（一式三份）和主要负责人安全资格证（复制件）。 企业有本办法第二十七条第四项情形申请变更的，应当自取得变更后的工商营业执照或者企业名称工商预先核准文件之日起10个工作日内，向所在地发证机关提交安全生产许可证变更申请书（一式三份）和工商营业执照或者企业名称工商预先核准文件（复制件）。"},{"i":29,"n":"第二十九条","txt":"对本办法第二十七条第一项、第二项情形的安全生产许可证变更申请，初审机关、发证机关应当按照本办法第二十三条、第二十四条、第二十五条的规定进行审查，并办理变更手续。 对本办法第二十七条第三项、第四项情形的安全生产许可证变更申请，发证机关应当自收到变更申请材料之日起5个工作日内完成审查，并办理变更手续。"},{"i":30,"n":"第三十条","txt":"安全生产许可证有效期为3年。安全生产许可证有效期满需要延期的，企业应当于有效期届满前3个月向原发证机关申请办理延期手续。"},{"i":31,"n":"第三十一条","txt":"企业提出延期申请的，应当向发证机关提交下列文件、资料： （一）安全生产许可证延期申请书（一式三份）； （二）本办法第二十一条第四项至第十一项规定的文件、资料； （三）达到安全生产标准化三级的证明材料。 发证机关收到延期申请后，应当按照本办法第二十四条、第二十五条的规定办理延期手续。"},{"i":32,"n":"第三十二条","txt":"企业在安全生产许可证有效期内符合下列条件，在许可证有效期届满时，经原发证机关同意，不再审查，直接办理延期手续： （一）严格遵守有关安全生产法律、法规和本办法； （二）取得安全生产许可证后，加强日常安全生产管理，不断提升安全生产条件，达到安全生产标准化二级以上； （三）接受发证机关及所在地人民政府安全生产监督管理部门的监督检查； （四）未发生生产安全死亡事故。"},{"i":33,"n":"第三十三条","txt":"对决定批准延期、变更安全生产许可证的，发证机关应当收回原证，换发新证。"},{"i":34,"n":"第三十四条","txt":"安全生产许可证发证机关和初审机关应当坚持公开、公平、公正的原则，严格依照有关行政许可的法律法规和本办法，审查、颁发安全生产许可证。 发证机关和初审机关工作人员在安全生产许可证审查、颁发、管理工作中，不得索取或者接受企业的财物，不得谋取其他不正当利益。"},{"i":35,"n":"第三十五条","txt":"发证机关及所在地人民政府安全生产监督管理部门应当加强对烟花爆竹生产企业的监督检查，督促其依照法律、法规、规章和国家标准、行业标准的规定进行生产。"},{"i":36,"n":"第三十六条","txt":"发证机关发现企业以欺骗、贿赂等不正当手段取得安全生产许可证的，应当撤销已颁发的安全生产许可证。"},{"i":37,"n":"第三十七条","txt":"取得安全生产许可证的企业有下列情形之一的，发证机关应当注销其安全生产许可证： （一）安全生产许可证有效期满未被批准延期的； （二）终止烟花爆竹生产活动的； （三）安全生产许可证被依法撤销的； （四）安全生产许可证被依法吊销的。 发证机关注销安全生产许可证后，应当在当地主要媒体或者本机关政府网站上及时公告被注销安全生产许可证的企业名单，并通报同级人民政府有关部门和企业所在地县级人民政府。"},{"i":38,"n":"第三十八条","txt":"发证机关应当建立健全安全生产许可证档案管理制度，并应用信息化手段管理安全生产许可证档案。"},{"i":39,"n":"第三十九条","txt":"发证机关应当每6个月向社会公布一次取得安全生产许可证的企业情况，并于每年1月15日前将本行政区域内上一年度安全生产许可证的颁发和管理情况报国家安全生产监督管理总局。"},{"i":40,"n":"第四十条","txt":"企业取得安全生产许可证后，不得出租、转让安全生产许可证，不得将企业、生产线或者工（库）房转包、分包给不具备安全生产条件或者相应资质的其他任何单位或者个人，不得多股东各自独立进行烟花爆竹生产活动。 企业不得从其他企业购买烟花爆竹半成品加工后销售或者购买其他企业烟花爆竹成品加贴本企业标签后销售，不得向其他企业销售烟花爆竹半成品。从事礼花弹生产的企业不得将礼花弹销售给未经公安机关批准的燃放活动。"},{"i":41,"n":"第四十一条","txt":"任何单位或者个人对违反《安全生产许可证条例》、《烟花爆竹安全管理条例》和本办法规定的行为，有权向安全生产监督管理部门或者监察机关等有关部门举报。"},{"i":42,"n":"第四十二条","txt":"发证机关、初审机关及其工作人员有下列行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任： （一）向不符合本办法规定的安全生产条件的企业颁发安全生产许可证的； （二）发现企业未依法取得安全生产许可证擅自从事烟花爆竹生产活动，不依法处理的； （三）发现取得安全生产许可证的企业不再具备本办法规定的安全生产条件，不依法处理的； （四）接到违反本办法规定行为的举报后，不及时处理的； （五）在安全生产许可证颁发、管理和监督检查工作中，索取或者接受企业财物、帮助企业弄虚作假或者谋取其他不正当利益的。"},{"i":43,"n":"第四十三条","txt":"企业有下列行为之一的，责令停止违法活动或者限期改正，并处1万元以上3万元以下的罚款： （一）变更企业主要负责人或者名称，未办理安全生产许可证变更手续的； （二）从其他企业购买烟花爆竹半成品加工后销售，或者购买其他企业烟花爆竹成品加贴本企业标签后销售，或者向其他企业销售烟花爆竹半成品的。"},{"i":44,"n":"第四十四条","txt":"企业有下列行为之一的，依法暂扣其安全生产许可证： （一）多股东各自独立进行烟花爆竹生产活动的； （二）从事礼花弹生产的企业将礼花弹销售给未经公安机关批准的燃放活动的； （三）改建、扩建烟花爆竹生产（含储存）设施未办理安全生产许可证变更手续的； （四）发生较大以上生产安全责任事故的； （五）不再具备本办法规定的安全生产条件的。 企业有前款第一项、第二项、第三项行为之一的，并处1万元以上3万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"企业有下列行为之一的，依法吊销其安全生产许可证： （一）出租、转让安全生产许可证的； （二）被暂扣安全生产许可证，经停产整顿后仍不具备本办法规定的安全生产条件的。 企业有前款第一项行为的，没收违法所得，并处10万元以上50万元以下的罚款。"},{"i":46,"n":"第四十六条","txt":"企业有下列行为之一的，责令停止生产，没收违法所得，并处10万元以上50万元以下的罚款： （一）未取得安全生产许可证擅自进行烟花爆竹生产的； （二）变更产品类别或者级别范围未办理安全生产许可证变更手续的。"},{"i":47,"n":"第四十七条","txt":"企业取得安全生产许可证后，将企业、生产线或者工（库）房转包、分包给不具备安全生产条件或者相应资质的其他单位或者个人，依照《中华人民共和国安全生产法》的有关规定给予处罚。"},{"i":48,"n":"第四十八条","txt":"本办法规定的行政处罚，由安全生产监督管理部门决定，暂扣、吊销安全生产许可证的行政处罚由发证机关决定。"},{"i":49,"n":"第四十九条","txt":"安全生产许可证由国家安全生产监督管理总局统一印制。"},{"i":50,"n":"第五十条","txt":"本办法自2012年8月1日起施行。原国家安全生产监督管理局、国家煤矿安全监察局2004年5月17日公布的《烟花爆竹生产企业安全生产许可证实施办法》同时废止。"}],"yanhuabaozhushengchanjingyinganquanguiding":[{"i":1,"n":"第一条","txt":"为了加强烟花爆竹生产经营安全工作，预防和减少生产安全事故，根据《中华人民共和国安全生产法》和《烟花爆竹安全管理条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"烟花爆竹生产企业（以下简称生产企业）、烟花爆竹批发企业（以下简称批发企业）和烟花爆竹零售经营者（以下简称零售经营者）的安全生产及其监督管理，适用本规定。 生产企业、批发企业、零售经营者统称生产经营单位。"},{"i":3,"n":"第三条","txt":"生产经营单位应当落实安全生产主体责任，其主要负责人（包括法定代表人、实际控制人，下同）是本单位安全生产工作的第一责任人，对本单位的安全生产工作全面负责。其他负责人在各自职责范围内对本单位安全生产工作负责。"},{"i":4,"n":"第四条","txt":"县级以上地方人民政府安全生产监督管理部门按照属地监管、分类分级负责的原则，对本行政区域内生产经营单位安全生产工作实施监督管理。 地方各级人民政府安全生产监督管理部门在本级人民政府的统一领导下，按照职责分工，会同其他有关部门依法查处非法生产经营烟花爆竹行为。"},{"i":5,"n":"第五条","txt":"生产经营单位应当具备有关法律、行政法规和国家标准或者行业标准规定的安全生产条件，并依法取得相应行政许可。"},{"i":6,"n":"第六条","txt":"生产企业、批发企业应当建立健全全员安全生产责任制，建立健全安全生产工作责任体系，制定并落实符合法律、行政法规和国家标准或者行业标准的安全生产规章制度和操作规程。"},{"i":7,"n":"第七条","txt":"生产企业、批发企业应当不断完善安全生产基础设施，持续保障和提升安全生产条件。 生产企业、批发企业的防雷设施应当经具有相应资质的机构设计、施工，确保符合相关国家标准或者行业标准的规定；防范静电危害的措施应当符合相关国家标准或者行业标准的规定。 生产企业、批发企业在工艺技术条件发生变化和扩大生产储存规模投入生产前，应当对企业的总体布局、工艺流程、危险性工（库）房、安全防护屏障、防火防雷防静电等基础设施进行安全评价。 新的国家标准、行业标准公布后，生产企业、批发企业应当对企业的总体布局、工艺流程、危险性工（库）房、安全防护屏障、防火防雷防静电等基础设施以及安全管理制度进行符合性检查，并依据新的国家标准、行业标准采取相应的改进、完善措施。 鼓励生产企业、批发企业制定并实施严于国家标准、行业标准的企业标准。"},{"i":8,"n":"第八条","txt":"生产企业应当积极推进烟花爆竹生产工艺技术进步，采用本质安全、性能可靠、自动化程度高的机械设备和生产工艺，使用安全、环保的生产原材料。禁止使用国家明令禁止或者淘汰的生产工艺、机械设备及原材料。禁止从业人员自行携带工具、设备进入企业从事生产作业。"},{"i":9,"n":"第九条","txt":"生产企业的涉药生产环节采用新工艺、使用新设备前，应当组织具有相应能力的机构、专家进行安全性能、安全技术要求论证。"},{"i":10,"n":"第十条","txt":"生产企业、批发企业应当保证下列事项所需安全生产资金投入： （一）安全设备设施维修维护； （二）工（库）房按国家标准、行业标准规定的条件改造； （三）重点部位和库房监控； （四）安全风险管控与隐患排查治理； （五）风险评估与安全评价； （六）安全生产教育培训； （七）劳动防护用品配备； （八）应急救援器材和物资配备； （九）应急救援训练及演练； （十）投保安全生产责任保险等其他需要投入资金的安全生产事项。"},{"i":11,"n":"第十一条","txt":"生产企业、批发企业的生产区、总仓库区、工（库）房及其他有较大危险因素的生产经营场所和有关设施设备上，应当设置明显的安全警示标志；所有工（库）房应当按照国家标准或者行业标准的规定设置准确、清晰、醒目的定员、定量、定级标识。 零售经营场所应当设置清晰、醒目的易燃易爆以及周边严禁烟火、严禁燃放烟花爆竹的安全标志。"},{"i":12,"n":"第十二条","txt":"生产经营单位应当对本单位从业人员进行烟花爆竹安全知识、岗位操作技能等培训，未经安全生产教育和培训的从业人员，不得上岗作业。危险工序作业等特种作业人员应当依法取得相应资格，方可上岗作业。 生产经营单位的主要负责人和安全生产管理人员应当由安全生产监督管理部门对其进行安全生产知识和管理能力考核合格。考核不得收费。"},{"i":13,"n":"第十三条","txt":"生产企业可以依法申请设立批发企业和零售经营场所。批发企业可以依法申请设立零售经营场所。 生产经营单位应当严格按照安全生产许可或者经营许可批准的范围，组织开展生产经营活动。禁止在许可证载明的场所外从事烟花爆竹生产、经营、储存活动，禁止许可证过期继续从事生产经营活动。禁止销售超标、违禁烟花爆竹产品或者非法烟花爆竹产品。 生产企业不得向其他企业销售烟花爆竹含药半成品，不得从其他企业购买烟花爆竹含药半成品加工后销售，不得购买其他企业烟花爆竹成品加贴本企业标签后销售。 批发企业不得向零售经营者或者个人销售专业燃放类烟花爆竹产品。 零售经营者不得在居民居住场所同一建筑物内经营、储存烟花爆竹。"},{"i":14,"n":"第十四条","txt":"生产企业、批发企业应当在权责明晰的组织架构下统一组织开展生产经营活动。禁止分包、转包工（库）房、生产线、生产设备设施或者出租、出借、转让许可证。"},{"i":15,"n":"第十五条","txt":"生产企业、批发企业应当依法建立安全风险分级管控和事故隐患排查治理双重预防机制，采取技术、管理等措施，管控安全风险，及时消除事故隐患，建立安全风险分级管控和事故隐患排查治理档案，如实记录安全风险分级管控和事故隐患排查治理情况，并向本企业从业人员通报。"},{"i":16,"n":"第十六条","txt":"生产企业、批发企业必须建立值班制度和现场巡查制度，全面掌握当日各岗位人员数量及药物分布等安全生产情况，确保不超员超量，并及时处置异常情况。 生产企业、批发企业的危险品生产区、总仓库区，应当确保二十四小时有人值班，并保持监控设施有效、通信畅通。"},{"i":17,"n":"第十七条","txt":"生产企业、批发企业应当建立从业人员、外来人员、车辆进出厂（库）区登记制度，对进出厂（库）区的从业人员、外来人员、车辆如实登记记录，随时掌握厂（库）区人员和车辆的情况。禁止无关人员和车辆进入厂（库）区。禁止未安装阻火装置等不符合国家标准或者行业标准规定安全条件的机动车辆进入生产区和仓库区。"},{"i":18,"n":"第十八条","txt":"生产企业和经营黑火药、引火线的批发企业应当要求供货单位提供并查验购进的黑火药、引火线及化工原材料的质检报告或者产品合格证，确保其安全性能符合国家标准或者行业标准的规定；对总仓库和中转库的黑火药、引火线、烟火药及裸药效果件，应当建立并实施由专人管理、登记、分发的安全管理制度。"},{"i":19,"n":"第十九条","txt":"生产企业、批发企业应当加强日常安全检查，采取安全监控、巡查检查等措施，及时发现、纠正违反安全操作规程和规章制度的行为。禁止工（库）房超员、超量作业，禁止擅自改变工（库）房设计用途，禁止作业人员随意串岗、换岗、离岗。"},{"i":20,"n":"第二十条","txt":"生产企业、批发企业应当按照设计用途、危险等级、核定药量使用药物总库和成品总库，并按规定堆码，分类分级存放，保持仓库内通道畅通，准确记录药物和产品数量。 禁止在仓库内进行拆箱、包装作业。禁止将性质不相容的物质混存。禁止将高危险等级物品储存在危险等级低的仓库。禁止在烟花爆竹仓库储存不属于烟花爆竹的其他危险物品。"},{"i":21,"n":"第二十一条","txt":"生产企业的中转库数量、核定存药量、药物储存时间，应当符合国家标准或者行业标准规定，确保药物、半成品、成品合理中转，保障生产流程顺畅。禁止在中转库内超量或者超时储存药物、半成品、成品。"},{"i":22,"n":"第二十二条","txt":"生产企业、批发企业应当定期检查工（库）房、安全设施、电气线路、机械设备等的运行状况和作业环境，及时维护保养；对有药物粉尘的工房，应当按照操作规程及时清理冲洗。 对工（库）房、安全设施、电气线路、机械设备等进行检测、检修、维修、改造作业前，生产企业、批发企业应当制定安全作业方案，停止相关生产经营活动，转移烟花爆竹成品、半成品和原材料，清除残存药物和粉尘，切断被检测、检修、维修、改造的电气线路和机械设备电源，严格控制检修、维修作业人员数量，撤离无关的人员。"},{"i":23,"n":"第二十三条","txt":"生产企业、批发企业在烟花爆竹购销活动中，应当依法签订规范的烟花爆竹买卖合同，建立烟花爆竹买卖合同和流向管理制度，使用全国统一的烟花爆竹流向管理信息系统，如实登记烟花爆竹流向。 生产企业应当在专业燃放类产品包装（包括运输包装和销售包装）及个人燃放类产品运输包装上张贴流向登记标签，并在产品入库和销售出库时登记录入。 批发企业购进烟花爆竹时，应当查验流向登记标签，并在产品入库和销售出库时登记录入。"},{"i":24,"n":"第二十四条","txt":"生产企业、批发企业所生产、销售烟花爆竹的质量、包装、标志应当符合国家标准或者行业标准的规定。"},{"i":25,"n":"第二十五条","txt":"在生产企业、批发企业内部及生产区、库区之间运输烟花爆竹成品、半成品及原材料时，应当使用符合国家标准或者行业标准规定安全条件的车辆、工具。企业内部运输应当严格按照规定路线、速度行驶。 生产企业、批发企业装卸烟花爆竹成品、半成品及原材料时，应当严格遵守作业规程。禁止碰撞、拖拉、抛摔、翻滚、摩擦、挤压等不安全行为。"},{"i":26,"n":"第二十六条","txt":"生产企业、批发企业应当及时妥善处置生产经营过程中产生的各类危险性废弃物。不得留存过期的烟花爆竹成品、半成品、原材料及各类危险性废弃物。"},{"i":27,"n":"第二十七条","txt":"批发企业应当向零售经营者及零售经营场所提供烟花爆竹配送服务。配送烟花爆竹抵达零售经营场所装卸作业时，应当轻拿轻放、妥善码放，禁止碰撞、拖拉、抛摔、翻滚、摩擦、挤压等不安全行为。"},{"i":28,"n":"第二十八条","txt":"零售经营者应当向批发企业采购烟花爆竹并接受批发企业配送服务，不得到企业仓库自行提取烟花爆竹。"},{"i":29,"n":"第二十九条","txt":"地方各级安全生产监督管理部门应当加强对本行政区域内生产经营单位的监督检查，明确每个生产经营单位的安全生产监督管理主体，制定并落实年度监督检查计划，对生产经营单位的安全生产违法行为，依法实施行政处罚。"},{"i":30,"n":"第三十条","txt":"安全生产监督管理部门可以根据需要，委托专业技术服务机构对生产经营单位的安全设施等进行检验检测，并承担检验检测费用，不得向企业收取。专业技术服务机构对其作出的检验检测结果负责。委托检验检测结果可以作为行政执法的依据。 生产经营单位不得拒绝、阻挠安全生产监督管理部门委托的专业技术服务机构开展检验检测工作。"},{"i":31,"n":"第三十一条","txt":"安全生产监督管理部门应当为进入企业现场的监督检查人员配备必要的执法装备、检测检验设备及个人防护用品，确保执法检查人员人身安全。"},{"i":32,"n":"第三十二条","txt":"安全生产监督管理部门监督检查中发现生产经营单位存在不属于本部门职责范围的违法行为的，应当及时移送有关部门处理。"},{"i":33,"n":"第三十三条","txt":"生产企业、批发企业有下列行为之一的，责令限期改正；逾期未改正的，处一万元以上三万元以下的罚款： （一）工（库）房没有设置准确、清晰、醒目的定员、定量、定级标识的； （二）未向零售经营者或者零售经营场所提供烟花爆竹配送服务的。"},{"i":34,"n":"第三十四条","txt":"生产企业、批发企业有下列行为之一的，责令限期改正，可以处五万元以下的罚款；逾期未改正的，处五万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；情节严重的，责令停产停业整顿： （一）防范静电危害的措施不符合相关国家标准或者行业标准规定的； （二）使用新安全设备，未进行安全性论证的； （三）在生产区、工（库）房等有药区域对安全设备进行检测、改造作业时，未将工（库）房内的药物、有药半成品、成品搬走并清理作业现场的。"},{"i":35,"n":"第三十五条","txt":"生产企业、批发企业有下列行为之一的，责令限期改正，可以处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款： （一）未建立从业人员、外来人员、车辆出入厂（库）区登记制度的； （二）未制定专人管理、登记、分发黑火药、引火线、烟火药及库存和中转效果件的安全管理制度的； （三）未建立烟花爆竹买卖合同管理制度的； （四）未按规定建立烟花爆竹流向管理制度的。"},{"i":36,"n":"第三十六条","txt":"零售经营者有下列行为之一的，责令其限期改正，可以处一千元以上五千元以下的罚款；逾期未改正的，处五千元以上一万元以下的罚款： （一）超越许可证载明限量储存烟花爆竹的； （二）到批发企业仓库自行提取烟花爆竹的。"},{"i":37,"n":"第三十七条","txt":"生产经营单位有下列行为之一的，责令改正；拒不改正的，处一万元以上三万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五千元以上一万元以下的罚款： （一）对工（库）房、安全设施、电气线路、机械设备等进行检测、检修、维修、改造作业前，未制定安全作业方案，或者未切断被检修、维修的电气线路和机械设备电源的； （二）拒绝、阻挠受安全生产监督管理部门委托的专业技术服务机构开展检验、检测的。"},{"i":38,"n":"第三十八条","txt":"生产经营单位未采取措施消除下列事故隐患的，责令立即消除或者限期消除；生产经营单位拒不执行的，责令停产停业整顿，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款： （一）工（库）房超过核定人员、药量或者擅自改变设计用途使用工（库）房的； （二）仓库内堆码、分类分级储存等违反国家标准或者行业标准规定的； （三）在仓库内进行拆箱、包装作业，将性质不相容的物质混存的； （四）在中转库、中转间内，超量、超时储存药物、半成品、成品的； （五）留存过期及废弃的烟花爆竹成品、半成品、原材料等危险废弃物的； （六）企业内部及生产区、库区之间运输烟花爆竹成品、半成品及原材料的车辆、工具不符合国家标准或者行业标准规定安全条件的； （七）允许未安装阻火装置等不具备国家标准或者行业标准规定安全条件的机动车辆进入生产区和仓库区的； （八）其他事故隐患。"},{"i":39,"n":"第三十九条","txt":"违反本规定，构成《中华人民共和国安全生产法》及其他法律、行政法规规定的其他违法行为的，依照《中华人民共和国安全生产法》等法律、行政法规的规定处理。涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":40,"n":"第四十条","txt":"本规定中的行政处罚，由县级以上安全生产监督管理部门决定。"},{"i":41,"n":"第四十一条","txt":"本规定自2018年3月1日起施行。"}],"yanhuabaozhujingyingxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范烟花爆竹经营单位安全条件和经营行为，做好烟花爆竹经营许可证颁发和管理工作，加强烟花爆竹经营安全监督管理，根据《烟花爆竹安全管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"烟花爆竹经营许可证的申请、审查、颁发及其监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"从事烟花爆竹批发的企业（以下简称批发企业）和从事烟花爆竹零售的经营者（以下简称零售经营者）应当按照本办法的规定，分别取得《烟花爆竹经营（批发）许可证》（以下简称批发许可证）和《烟花爆竹经营（零售）许可证》（以下简称零售许可证）。 从事烟花爆竹进出口的企业，应当按照本办法的规定申请办理批发许可证。 未取得烟花爆竹经营许可证的，任何单位或者个人不得从事烟花爆竹经营活动。"},{"i":4,"n":"第四条","txt":"烟花爆竹经营单位的布点，应当按照保障安全、统一规划、合理布局、总量控制、适度竞争的原则审批；对从事黑火药、引火线批发和烟花爆竹进出口的企业，应当按照严格许可条件、严格控制数量的原则审批。 批发企业不得在城市建成区内设立烟花爆竹储存仓库，不得在批发（展示）场所摆放有药样品；严格控制城市建成区内烟花爆竹零售点数量，且烟花爆竹零售点不得与居民居住场所设置在同一建筑物内。"},{"i":5,"n":"第五条","txt":"烟花爆竹经营许可证的颁发和管理，实行企业申请、分级发证、属地监管的原则。 国家安全生产监督管理总局（以下简称安全监管总局）负责指导、监督全国烟花爆竹经营许可证的颁发和管理工作。 省、自治区、直辖市人民政府安全生产监督管理部门（以下简称省级安全监管局）负责制定本行政区域的批发企业布点规划，统一批发许可编号，指导、监督本行政区域内烟花爆竹经营许可证的颁发和管理工作。 设区的市级人民政府安全生产监督管理部门（以下简称市级安全监管局）根据省级安全监管局的批发企业布点规划和统一编号，负责本行政区域内烟花爆竹批发许可证的颁发和管理工作。 县级人民政府安全生产监督管理部门（以下简称县级安全监管局，与市级安全监管局统称发证机关）负责本行政区域内零售经营布点规划与零售许可证的颁发和管理工作。"},{"i":6,"n":"第六条","txt":"批发企业应当符合下列条件： （一）具备企业法人条件； （二）符合所在地省级安全监管局制定的批发企业布点规划； （三）具有与其经营规模和产品相适应的仓储设施。仓库的内外部安全距离、库房布局、建筑结构、疏散通道、消防、防爆、防雷、防静电等安全设施以及电气设施等，符合《烟花爆竹工程设计安全规范》（GB50161）等国家标准和行业标准的规定。仓储区域及仓库安装有符合《烟花爆竹企业安全监控系统通用技术条件》（AQ4101）规定的监控设施，并设立符合《烟花爆竹安全生产标志》（AQ4114）规定的安全警示标志和标识牌； （四）具备与其经营规模、产品和销售区域范围相适应的配送服务能力； （五）建立安全生产责任制和各项安全管理制度、操作规程。安全管理制度和操作规程至少包括：仓库安全管理制度、仓库保管守卫制度、防火防爆安全管理制度、安全检查和隐患排查治理制度、事故应急救援与事故报告制度、买卖合同管理制度、"},{"i":7,"n":"第七条","txt":"从事黑火药、引火线批发的企业，除具备本办法第六条规定的条件外，还应当具备必要的黑火药、引火线安全保管措施，自有的专用运输车辆能够满足其配送服务需要，且符合国家相关标准。"},{"i":8,"n":"第八条","txt":"批发企业申请领取批发许可证时，应当向发证机关提交下列申请文件、资料，并对其真实性负责： （一）批发许可证申请书（一式三份）； （二）企业法人营业执照副本或者企业名称工商预核准文件复制件； （三）安全生产责任制文件、事故应急救援预案备案登记文件、安全管理制度和操作规程的目录清单； （四）主要负责人、分管安全生产负责人、安全生产管理人员和仓库保管员、守护员的相关资格证书复制件； （五）具备相应资质的设计单位出具的库区外部安全距离实测图和库区仓储设施平面布置图； （六）具备相应资质的安全评价机构出具的安全评价报告，安全评价报告至少包括本办法第六条第三项、第四项、第八项、第九项和第七条规定条件的符合性评价内容； （七）建设项目安全设施设计审查和竣工验收的证明材料； （八）从事黑火药、引火线批发的企业自有专用运输车辆以及驾驶员、押运员的相关资质（资格）证书复制件； （九）法律、法规规定的其他文件"},{"i":9,"n":"第九条","txt":"发证机关对申请人提交的申请书及文件、资料，应当按照下列规定分别处理： （一）申请事项不属于本发证机关职责范围的，应当即时作出不予受理的决定，并告知申请人向相应发证机关申请； （二）申请材料存在可以当场更改的错误的，应当允许或者要求申请人当场更正，并在更正后即时出具受理的书面凭证； （三）申请材料不齐全或者不符合要求的，应当当场或者在5个工作日内书面一次告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合要求或者按照要求全部补正的，自收到申请材料或者全部补正材料之日起即为受理。"},{"i":10,"n":"第十条","txt":"发证机关受理申请后，应当对申请材料进行审查。需要对经营储存场所的安全条件进行现场核查的，应当指派2名以上工作人员组织技术人员进行现场核查。对烟花爆竹进出口企业和设有1.1级仓库的企业，应当指派2名以上工作人员组织技术人员进行现场核查。负责现场核查的人员应当提出书面核查意见。"},{"i":11,"n":"第十一条","txt":"发证机关应当自受理申请之日起30个工作日内作出颁发或者不予颁发批发许可证的决定。 对决定不予颁发的，应当自作出决定之日起10个工作日内书面通知申请人并说明理由；对决定颁发的，应当自作出决定之日起10个工作日内送达或者通知申请人领取批发许可证。 发证机关在审查过程中，现场核查和企业整改所需时间，不计算在本办法规定的期限内。"},{"i":12,"n":"第十二条","txt":"批发许可证的有效期限为3年。 批发许可证有效期满后，批发企业拟继续从事烟花爆竹批发经营活动的，应当在有效期届满前3个月向原发证机关提出延期申请，并提交下列文件、资料： （一）批发许可证延期申请书（一式三份）； （二）本办法第八条第三项、第四项、第五项、第八项规定的文件、资料； （三）安全生产标准化达标的证明材料。"},{"i":13,"n":"第十三条","txt":"发证机关受理延期申请后，应当按照本办法第十条、第十一条规定，办理批发许可证延期手续。"},{"i":14,"n":"第十四条","txt":"批发企业符合下列条件的，经发证机关同意，可以不再现场核查，直接办理批发许可证延期手续： （一）严格遵守有关法律、法规和本办法规定，无违法违规经营行为的； （二）取得批发许可证后，持续加强安全生产管理，不断提升安全生产条件，达到安全生产标准化二级以上的； （三）接受发证机关及所在地人民政府安全生产监督管理部门的监督检查的； （四）未发生生产安全伤亡事故的。"},{"i":15,"n":"第十五条","txt":"批发企业在批发许可证有效期内变更企业名称、主要负责人和注册地址的，应当自变更之日起10个工作日内向原发证机关提出变更，并提交下列文件、资料： （一）批发许可证变更申请书（一式三份）； （二）变更后的企业名称工商预核准文件或者工商营业执照副本复制件； （三）变更后的主要负责人安全资格证书复制件。 批发企业变更经营许可范围、储存仓库地址和仓储设施新建、改建、扩建的，应当重新申请办理许可手续。"},{"i":16,"n":"第十六条","txt":"零售经营者应当符合下列条件： （一）符合所在地县级安全监管局制定的零售经营布点规划； （二）主要负责人经过安全培训合格，销售人员经过安全知识教育； （三）春节期间零售点、城市长期零售点实行专店销售。乡村长期零售点在淡季实行专柜销售时，安排专人销售，专柜相对独立，并与其他柜台保持一定的距离，保证安全通道畅通； （四）零售场所的面积不小于10平方米，其周边50米范围内没有其他烟花爆竹零售点，并与学校、幼儿园、医院、集贸市场等人员密集场所和加油站等易燃易爆物品生产、储存设施等重点建筑物保持100米以上的安全距离； （五）零售场所配备必要的消防器材，张贴明显的安全警示标志； （六）法律、法规规定的其他条件。"},{"i":17,"n":"第十七条","txt":"零售经营者申请领取零售许可证时，应当向所在地发证机关提交申请书、零售点及其周围安全条件说明和发证机关要求提供的其他材料。"},{"i":18,"n":"第十八条","txt":"发证机关受理申请后，应当对申请材料和零售场所的安全条件进行现场核查。负责现场核查的人员应当提出书面核查意见。"},{"i":19,"n":"第十九条","txt":"发证机关应当自受理申请之日起20个工作日内作出颁发或者不予颁发零售许可证的决定，并书面告知申请人。对决定不予颁发的，应当书面说明理由。"},{"i":20,"n":"第二十条","txt":"零售许可证上载明的储存限量由发证机关根据国家标准或者行业标准的规定，结合零售点及其周围安全条件确定。"},{"i":21,"n":"第二十一条","txt":"零售许可证的有效期限由发证机关确定，最长不超过2年。零售许可证有效期满后拟继续从事烟花爆竹零售经营活动，或者在有效期内变更零售点名称、主要负责人、零售场所和许可范围的，应当重新申请取得零售许可证。"},{"i":22,"n":"第二十二条","txt":"批发企业、零售经营者不得采购和销售非法生产、经营的烟花爆竹和产品质量不符合国家标准或者行业标准规定的烟花爆竹。 批发企业不得向未取得零售许可证的单位或者个人销售烟花爆竹，不得向零售经营者销售礼花弹等应当由专业燃放人员燃放的烟花爆竹；从事黑火药、引火线批发的企业不得向无《烟花爆竹安全生产许可证》的单位或者个人销售烟火药、黑火药、引火线。 零售经营者应当向批发企业采购烟花爆竹，不得采购、储存和销售礼花弹等应当由专业燃放人员燃放的烟花爆竹，不得采购、储存和销售烟火药、黑火药、引火线。"},{"i":23,"n":"第二十三条","txt":"禁止在烟花爆竹经营许可证载明的储存（零售）场所以外储存烟花爆竹。 烟花爆竹仓库储存的烟花爆竹品种、规格和数量，不得超过国家标准或者行业标准规定的危险等级和核定限量。 零售点存放的烟花爆竹品种和数量，不得超过烟花爆竹经营许可证载明的范围和限量。"},{"i":24,"n":"第二十四条","txt":"批发企业对非法生产、假冒伪劣、过期、含有违禁药物以及其他存在严重质量问题的烟花爆竹，应当及时、妥善销毁。 对执法检查收缴的前款规定的烟花爆竹，不得与正常的烟花爆竹产品同库存放。"},{"i":25,"n":"第二十五条","txt":"批发企业应当建立并严格执行合同管理、流向登记制度，健全合同管理和流向登记档案，并留存3年备查。 黑火药、引火线批发企业的采购、销售记录，应当自购买或者销售之日起3日内报所在地县级安全监管局备案。"},{"i":26,"n":"第二十六条","txt":"烟花爆竹经营单位不得出租、出借、转让、买卖、冒用或者使用伪造的烟花爆竹经营许可证。"},{"i":27,"n":"第二十七条","txt":"烟花爆竹经营单位应当在经营（办公）场所显著位置悬挂烟花爆竹经营许可证正本。批发企业应当在储存仓库留存批发许可证副本。"},{"i":28,"n":"第二十八条","txt":"对违反本办法规定的程序、超越职权或者不具备本办法规定的安全条件颁发的烟花爆竹经营许可证，发证机关应当依法撤销其经营许可证。 取得烟花爆竹经营许可证的单位依法终止烟花爆竹经营活动的，发证机关应当依法注销其经营许可证。"},{"i":29,"n":"第二十九条","txt":"发证机关应当坚持公开、公平、公正的原则，严格依照本办法的规定审查、核发烟花爆竹经营许可证，建立健全烟花爆竹经营许可证的档案管理制度和信息化管理系统，并定期向社会公告取证企业的名单。 省级安全监管局应当加强烟花爆竹经营许可工作的监督检查，并于每年3月15日前，将本行政区域内上年度烟花爆竹经营许可证的颁发和管理情况报告安全监管总局。"},{"i":30,"n":"第三十条","txt":"任何单位或者个人对违反《烟花爆竹安全管理条例》和本办法规定的行为，有权向安全生产监督管理部门或者监察机关等有关部门举报。"},{"i":31,"n":"第三十一条","txt":"对未经许可经营、超许可范围经营、许可证过期继续经营烟花爆竹的，责令其停止非法经营活动，处2万元以上10万元以下的罚款，并没收非法经营的物品及违法所得。"},{"i":32,"n":"第三十二条","txt":"批发企业有下列行为之一的，责令其限期改正，处5000元以上3万元以下的罚款： （一）在城市建成区内设立烟花爆竹储存仓库，或者在批发（展示）场所摆放有药样品的； （二）采购和销售质量不符合国家标准或者行业标准规定的烟花爆竹的； （三）在仓库内违反国家标准或者行业标准规定储存烟花爆竹的； （四）在烟花爆竹经营许可证载明的仓库以外储存烟花爆竹的； （五）对假冒伪劣、过期、含有超量、违禁药物以及其他存在严重质量问题的烟花爆竹未及时销毁的； （六）未执行合同管理、流向登记制度或者未按照规定应用烟花爆竹流向管理信息系统的； （七）未将黑火药、引火线的采购、销售记录报所在地县级安全监管局备案的； （八）仓储设施新建、改建、扩建后，未重新申请办理许可手续的； （九）变更企业名称、主要负责人、注册地址，未申请办理许可证变更手续的； （十）向未取得零售许可证的单位或者个人销售烟花爆竹的。"},{"i":33,"n":"第三十三条","txt":"批发企业有下列行为之一的，责令其停业整顿，依法暂扣批发许可证，处2万元以上10万元以下的罚款，并没收非法经营的物品及违法所得；情节严重的，依法吊销批发许可证： （一）向未取得烟花爆竹安全生产许可证的单位或者个人销售烟火药、黑火药、引火线的； （二）向零售经营者供应非法生产、经营的烟花爆竹的； （三）向零售经营者供应礼花弹等按照国家标准规定应当由专业人员燃放的烟花爆竹的。"},{"i":34,"n":"第三十四条","txt":"零售经营者有下列行为之一的，责令其停止违法行为，处1000元以上5000元以下的罚款，并没收非法经营的物品及违法所得；情节严重的，依法吊销零售许可证： （一）销售非法生产、经营的烟花爆竹的； （二）销售礼花弹等按照国家标准规定应当由专业人员燃放的烟花爆竹的。"},{"i":35,"n":"第三十五条","txt":"零售经营者有下列行为之一的，责令其限期改正，处1000元以上5000元以下的罚款；情节严重的，处5000元以上30000元以下的罚款： （一）变更零售点名称、主要负责人或者经营场所，未重新办理零售许可证的； （二）存放的烟花爆竹数量超过零售许可证载明范围的。"},{"i":36,"n":"第三十六条","txt":"烟花爆竹经营单位出租、出借、转让、买卖烟花爆竹经营许可证的，责令其停止违法行为，处1万元以上3万元以下的罚款，并依法撤销烟花爆竹经营许可证。 冒用或者使用伪造的烟花爆竹经营许可证的，依照本办法第三十一条的规定处罚。"},{"i":37,"n":"第三十七条","txt":"申请人隐瞒有关情况或者提供虚假材料申请烟花爆竹经营许可证的，发证机关不予受理，该申请人1年内不得再次提出烟花爆竹经营许可申请。 以欺骗、贿赂等不正当手段取得烟花爆竹经营许可证的，应当予以撤销，该经营单位3年内不得再次提出烟花爆竹经营许可申请。"},{"i":38,"n":"第三十八条","txt":"安全生产监督管理部门工作人员在实施烟花爆竹经营许可和监督管理工作中，滥用职权、玩忽职守、徇私舞弊，未依法履行烟花爆竹经营许可证审查、颁发和监督管理职责的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"本办法规定的行政处罚，由安全生产监督管理部门决定，暂扣、吊销经营许可证的行政处罚由发证机关决定。"},{"i":40,"n":"第四十条","txt":"烟花爆竹经营许可证分为正本、副本，正本为悬挂式，副本为折页式，具有同等法律效力。 烟花爆竹经营许可证由安全监管总局统一规定式样。"},{"i":41,"n":"第四十一条","txt":"省级安全监管局可以依据国家有关法律、行政法规和本办法的规定制定实施细则。"},{"i":42,"n":"第四十二条","txt":"本办法自2013年12月1日起施行，安全监管总局2006年8月26日公布的《烟花爆竹经营许可实施办法》同时废止。"}],"meicengqidimiankaicaianquanguicheng":[{"i":1,"n":"第一条","txt":"为了加强煤层气地面开采的安全管理，预防和减少生产安全事故，保障从业人员生命健康和财产安全，根据《中华人民共和国安全生产法》等法律、行政法规，制定本规程。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事煤层气地面开采及有关设计、钻井、固井、测井、压裂、排采、集输、压缩等活动的安全生产，适用本规程。 国家标准、行业标准对煤矿井下瓦斯抽采和低浓度瓦斯输送安全另行规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"煤层气地面开采企业以及承包单位（以下统称煤层气企业）应当遵守国家有关安全生产的法律、行政法规、规章、标准和技术规范，依法取得安全生产许可证，接受煤矿安全监察机构的监察。 国家鼓励煤矿企业采用科学方法抽采煤层气。依法设立的煤矿企业地面抽采本企业煤层气应当遵守本规程，但不需要另行取得安全生产许可证。"},{"i":4,"n":"第四条","txt":"煤层气企业应当建立安全生产管理机构，配备相应的专职安全生产管理人员；建立健全安全管理制度和操作规程，落实安全生产责任制，配备满足需要的安全设备和装备。"},{"i":5,"n":"第五条","txt":"煤层气企业的主要负责人对本单位的安全生产工作全面负责。 煤层气企业的主要负责人和安全生产管理人员应当按照有关规定经专门培训并考核合格取得安全资格证书。"},{"i":6,"n":"第六条","txt":"煤层气企业应当制定安全生产教育和培训计划，对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，熟悉有关的安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能。未经安全生产教育和培训合格的从业人员，不得上岗作业。 煤层气企业的特种作业人员，应当按照有关规定经专门的安全作业培训，取得特种作业操作资格证书，方可上岗作业。"},{"i":7,"n":"第七条","txt":"煤层气企业应当按照有关规定提取、使用满足安全生产需要的安全生产费用，保障煤层气地面开采的安全。"},{"i":8,"n":"第八条","txt":"煤层气企业应当按照有关规定制定生产安全事故应急预案，组织定期演练，并根据安全生产条件的变化及时修订。 发生生产安全事故后，煤层气企业应当立即采取有效措施组织救援，防止事故扩大，避免人员伤亡和减少财产损失，并按照有关规定及时报告安全生产监管监察部门。"},{"i":9,"n":"第九条","txt":"煤层气地面开采区域存在煤矿矿井的，煤层气企业应当与煤矿企业进行沟通，统筹考虑煤层气地面开采项目方案和煤矿开采计划，共享有关地质资料和工程资料，确保煤层气地面开采安全和煤矿井下安全。"},{"i":10,"n":"第十条","txt":"煤层气地面开采项目应当按照有关规定进行安全条件论证和安全预评价。"},{"i":11,"n":"第十一条","txt":"新建、改建、扩建煤层气开采项目的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"},{"i":12,"n":"第十二条","txt":"煤层气地面开采项目的总体开发方案和煤层气集输管线、站场、供电等工程设计应当由具有相应资质的单位承担。煤层气井钻井、压裂、排采、修井等施工方案，由煤层气企业负责。 煤层气企业应当建立健全施工方案的审查制度，严格安全条件的审查。施工方案未经煤层气企业主要负责人审查同意的，施工单位不得施工。"},{"i":13,"n":"第十三条","txt":"煤层气地面开采项目的工程施工应当由具有相应资质的监理单位进行监督。监理单位应当按照国家建设工程监理规范的要求对工程施工质量进行监督。"},{"i":14,"n":"第十四条","txt":"煤层气企业进行工程发包时，应当对承包单位的资质条件和安全生产业绩进行审查，与承包单位签订专门的安全生产管理协议，或者在承包合同中约定各自的安全生产管理职责。煤层气企业对承包单位的安全生产工作统一协调、管理。"},{"i":15,"n":"第十五条","txt":"煤层气企业应当经常开展安全生产检查及事故隐患排查，对发现的安全生产问题和事故隐患，应当立即采取措施进行整改；不能立即整改的，应当制定整改方案限期处理。"},{"i":16,"n":"第十六条","txt":"煤层气企业应当对安全阀、压力表、传感器和监测设备进行定期校验、检定。煤层气企业的特种设备应当按照有关规定定期检测。"},{"i":17,"n":"第十七条","txt":"煤层气企业应当建立相应的消防机构，配备专职或者兼职消防人员和必要的装备、器材，或者与所在地消防、应急救援机构签订消防救援合同。"},{"i":18,"n":"第十八条","txt":"煤层气企业应当建立劳动防护用品配备、使用和管理制度，为从业人员提供符合国家标准或者行业标准的劳动防护用品。 煤层气企业应当对从业人员进行劳动防护用品使用的培训，指导、教育从业人员正确佩戴和使用劳动防护用品。"},{"i":19,"n":"第十九条","txt":"煤层气企业进行电焊、气焊（割）等明火作业或其他可能产生火花的作业，应当编制专门的安全技术措施，并经本企业技术负责人审查批准。井场、站场内禁止烟火。"},{"i":20,"n":"第二十条","txt":"煤层气企业应当建立设备管理专人负责制度。设备管理应当符合下列要求： （一）安全标志正确、齐全、清晰，设置位置合理； （二）定期进行巡检、维护和保养，确保设备始终处于完好状态； （三）机械传动部位安装安全防护栏或者防护罩； （四）按照有关规定对设备进行换季维护保养，防止设备锈蚀、冻裂； （五）带压设备定期进行试压，合格后方可使用。"},{"i":21,"n":"第二十一条","txt":"站场控制室内的气体探测控制仪超限断电后，煤层气企业应当立即组织专人对相应的设备和室内环境进行检查。严禁强行送电、开机。"},{"i":22,"n":"第二十二条","txt":"在含硫化氢矿区进行施工作业和煤层气生产前，煤层气企业应当对所有生产作业人员和现场监督人员进行硫化氢防护的培训。培训内容应当包括课堂防护知识和现场实际操作，并符合培训时间规定。 对于临时作业人员和其他非定期派遣人员，在施工作业和煤层气生产前，煤层气企业应当对其进行硫化氢防护知识的教育。"},{"i":23,"n":"第二十三条","txt":"在含硫化氢环境中进行生产作业，应当配备固定式和携带式硫化氢监测仪。硫化氢监测仪应当按照有关规定进行定期校验和鉴定。硫化氢重点监测区域应当设有醒目的标志，并设置硫化氢监测探头和报警器。 硫化氢监测仪发出不同级别报警时，煤层气企业应当按照行业标准《含硫化氢油气井安全钻井推荐作法》（SY/T5087）的规定采取相应的措施。"},{"i":24,"n":"第二十四条","txt":"煤层气企业在含硫化氢环境中进行生产作业，应当配备相应的防护装备，并符合下列要求： （一）在钻井、试井、修井、井下作业以及站场作业中，配备正压式空气呼吸器及与其匹配的空气压缩机； （二）有专人管理硫化氢防护装置，确保处于备用状态； （三）进行检修和抢险作业时，携带硫化氢监测仪和正压式空气呼吸器。"},{"i":25,"n":"第二十五条","txt":"在含硫化氢的矿区，场地及设备的布置应当考虑季节风向。在有可能形成硫化氢和二氧化硫的聚集处，应当确保有良好的通风条件，设置警示标志，使用防爆通风设备，并设置逃生通道及安全区。"},{"i":26,"n":"第二十六条","txt":"在含硫化氢环境中进行钻井、井下作业和煤层气生产以及气体处理所使用的材料及设备，应当适合用于含硫化氢环境。"},{"i":27,"n":"第二十七条","txt":"在含硫化氢环境中进行生产作业时，煤层气企业应当制定防硫化氢应急预案。钻井、井下作业的防硫化氢应急预案，应当规定煤层气井点火程序和决策人。"},{"i":28,"n":"第二十八条","txt":"煤层气企业在含硫化氢的矿区进行煤层气井钻井，应当符合下列要求： （一）地质及工程设计考虑硫化氢防护的特殊要求； （二）采取防喷措施，防喷器组及其管线闸门和附件能够满足预期的井口压力； （三）井场内禁止烟火，并采取控制硫化氢着火的措施； （四）使用适合于含硫化氢地层的钻井液，并监测、控制钻井液pH值； （五）在含硫化氢地层取芯和进行测试作业时，采取有效的防硫化氢措施。"},{"i":29,"n":"第二十九条","txt":"在煤层气企业含硫化氢的煤层气井进行井下作业，应当符合下列要求： （一）采取防喷措施； （二）采取控制硫化氢着火的措施； （三）当发生修井液气侵，硫化氢气体逸出时，立即通过分离系统分离或者采取其他处理措施； （四）进入盛放修井液的密闭空间或者限制通风区域，可能产生硫化氢气体时，采取相应的人身安全防护措施； （五）进行对射孔作业、压裂作业等特殊作业时，采取硫化氢防护措施。"},{"i":30,"n":"第三十条","txt":"在进行含硫化氢的煤层气生产和气体处理作业时，煤层气企业应当对煤层气处理装置的腐蚀进行监测和控制，对可能的硫化氢泄漏进行检测，制定硫化氢防护措施。 作业人员进入可能有硫化氢泄漏的井场、站场、低凹区、污水区及其他硫化氢易于积聚的区域时，以及进入煤层气净化厂的脱硫、再生、硫回收、排污放空区进行检修和抢险时，应当携带正压式空气呼吸器。"},{"i":31,"n":"第三十一条","txt":"含硫化氢煤层气井废弃时，煤层气企业应当考虑废弃方法和封井的条件，使用水泥封隔产出硫化氢的地层。 埋地管线、地面流程管线废弃时，应当经过吹扫净化、封堵塞或者加盖帽。容器应当用清水冲洗、吹扫并排干，敞开在大气中，并采取防止铁的硫化物燃烧的措施。"},{"i":32,"n":"第三十二条","txt":"煤层气企业编写工程设计方案前，应当充分收集有关资料，对作业现场及其周边环境进行调研，并进行危险源辨识和风险评价。"},{"i":33,"n":"第三十三条","txt":"煤层气井不得布置在滑坡、崩塌、泥石流等地质灾害易发地带。"},{"i":34,"n":"第三十四条","txt":"气井井口与周围建（构）筑物、设施的间距应当符合行业标准《煤层气地面开采防火防爆安全规程》（AQ1081）的规定。"},{"i":35,"n":"第三十五条","txt":"钻井作业时，生活区、值班房应当置于井架侧面，且处于最小频率风向的下风侧，与井口的间距不小于10米。井场发电房与柴油罐的间距应当不小于5米。"},{"i":36,"n":"第三十六条","txt":"井控装置的远程控制台应当安装在井架大门侧前方、距井口不少于25米的专用活动房内，并在周围保持2米以上的行人通道。"},{"i":37,"n":"第三十七条","txt":"钻井工程地质设计应当收集区域地质资料，确定各含水层组深度，制定相应的安全措施。"},{"i":38,"n":"第三十八条","txt":"钻机及配套设备应当满足钻井设计的要求。钻机的额定钻进深度应当大于钻井深度。井架提升能力应当满足钻具重量、地质条件的要求。 动力设施应当满足钻机、泥浆泵、排水泵等设施所需功率。"},{"i":39,"n":"第三十九条","txt":"钻井工艺技术应当有利于保护煤储层，并制定井漏、井涌、井喷、井塌、卡钻、防斜等复杂情况的安全技术措施。"},{"i":40,"n":"第四十条","txt":"探井设计应当参考本地区钻井所采用的井身结构。井径应当留有余地。套管系列设计应当能够保证施工安全。表层套管应当至少下到稳定基岩内10米。"},{"i":41,"n":"第四十一条","txt":"固井作业设计应当保证后续增产作业施工的安全。 套管柱应当进行强度设计，综合考虑内应力、挤应力和拉应力，以满足后续作业的需要。"},{"i":42,"n":"第四十二条","txt":"设计方案应当对各种复杂情况提出预防和处理措施。"},{"i":43,"n":"第四十三条","txt":"煤层气企业应当建立测井安全操作管理和事故处理措施。煤层气企业应当对放射源等危险物品的储存、运输、使用和防护作出特别规定。"},{"i":44,"n":"第四十四条","txt":"煤层气企业应当建立爆炸物品运输和使用、爆炸器材存储和销毁、废旧爆炸物品安全销毁的管理制度。 煤层气企业应当建立防止地面爆炸、施工深度错误、炸枪（卡枪）及炸坏套管的安全防范和处理措施。"},{"i":45,"n":"第四十五条","txt":"所选压裂井口的耐压等级应当大于设计的最高井口压力，泵车组安全阀的设定压力值不得超过生产套管抗内压强度的80%。煤层气企业应当建立砂堵、砂卡、设备损坏等事故的应急处理措施。"},{"i":46,"n":"第四十六条","txt":"排采设备地基、底座基础应当满足载荷要求。电缆、变速箱、其他电气设备、连接设施配套设备应当与电机功率匹配。抽油杆柱应当满足疲劳应力强度要求。"},{"i":47,"n":"第四十七条","txt":"排采泵的防冲距合理值应当根据下泵深度、泵型号、抽油杆的规格及机械性能确定，避免正常工作时柱塞碰泵。"},{"i":48,"n":"第四十八条","txt":"井口应当设置排采沉淀池，煤层气井排出的水经过沉淀后，满足有关规定要求后方可进行排放；水管线应当以一定的坡度通向排采沉淀池，保证水流畅通。"},{"i":49,"n":"第四十九条","txt":"煤层气企业对可能产生静电危险的下列设备和管线应当设置防静电装置： （一）进出装置或者设施处； （二）爆炸危险场所的边界； （三）煤层气储罐、过滤器、脱水装置、缓冲器等及其连接部分； （四）管道分支处以及直线段每隔200～300米处； （五）压缩机的吸入口和加气机本身及槽车与加气机连接环节。 在站场入口和主要的操作场所，煤层气企业应当安装人体静电导除装置，防静电接地装置的接地电阻应当不大于100欧姆。 在连接管线的法兰连接处，煤层气企业应当设置金属跨接线（绝缘法兰除外）。当法兰用5根以上螺栓连接时，法兰可以不用金属线跨接，但必须构成电气通路。"},{"i":50,"n":"第五十条","txt":"工程和设备的防静电接地应当符合下列要求： （一）设施设备和车辆的防静电接地，不得使用链条类导体连线； （二）防静电接地、防感应雷接地和电气设备接地共同设置的，其接地电阻不大于10欧姆； （三）防静电接地装置单独设置的，接地电阻不大于100欧姆，埋设周围情况良好； （四）防静电接地不得使用防直击雷引下线和电气工作零线，测量点位置不得设在爆炸危险区域内； （五）检修设备、管线可能导致防静电接地系统断路时，预先设置临时性接地，检修完毕后及时恢复。"},{"i":51,"n":"第五十一条","txt":"进站槽车的防静电应当符合下列要求： （一）槽车及槽车驾驶员、押运员持有合法有效的证件； （二）槽车设置汽车专用静电接地装置，接地电阻不大于100欧姆； （三）槽车的防静电接地线连接在作业场所的专用防静电接地点上，且不得采用缠绕等不可靠的连接方法； （四）槽车的防静电接地连线采用专用导静电橡胶拖地线或者铜芯软绞线。"},{"i":52,"n":"第五十二条","txt":"防雷应当符合下列安全要求： （一）建（构）筑物、工艺设备、架空管线、各种罐体、电气设备等设置防雷接地装置； （二）进入变（配）电室的高压电路安装与设备耐压水平相适应的过电压（电涌）保护器； （三）信息系统配电线路的首、末端与电子器件连接时，装设与电子器件耐压水平相适应的过电压（电涌）保护器； （四）防雷接地电阻不得大于10欧姆，引下线地面以下0.3米至地面以上1.7米无破坏，接地测试断接点接触良好，埋设周围情况良好； （五）防雷装置保护范围不得缩小； （六）防雷击接地措施不得影响输气管线阴级保护效果； （七）接地装置定期由具备资质的单位进行测试。"},{"i":53,"n":"第五十三条","txt":"煤层气企业应当在站场内设置风向标，并悬挂在有关人员可以看到的位置。"},{"i":54,"n":"第五十四条","txt":"压缩机房应当符合下列要求： （一）压缩机房设置防爆应急照明系统； （二）采用封闭式厂房时，有煤层气泄露的报警装置、良好的机械通风设施和足够的泄压面积； （三）压缩机房电缆沟使用软土或者沙子埋实，并与配电间的电缆沟严密隔开； （四）压缩机房有醒目的安全警示标志。"},{"i":55,"n":"第五十五条","txt":"井场应当平整、坚固。井架地基填方部分不得超过四分之一面积。填方部分应当采取加固措施。 煤层气企业在山坡上修筑井场时，当地层坚硬、稳固时，井场边坡坡度不得大于85度；当地层松软时，井场边坡坡度不得大于60度。必要时，砌筑护坡、挡土墙。"},{"i":56,"n":"第五十六条","txt":"煤层气企业应当对井场的井架、油罐安装防雷防静电接地装置，其接地电阻应当不大于10欧姆。"},{"i":57,"n":"第五十七条","txt":"暴雨、洪水季节，在山沟、洼陷等低凹地带施工时，煤层气企业应当加高地基，修筑防洪设施。"},{"i":58,"n":"第五十八条","txt":"煤层气企业应当在井场配备足够数量的消防器材。消防器材应当由专人管理，定期维护保养，不得挪作他用。消防器材摆放处应当保持通道畅通，确保取用方便。"},{"i":59,"n":"第五十九条","txt":"煤层气企业应当在井场、钻台及井架梯子的入口处，钻台上、高空作业区和绞车、柴油机、发电机等机械设备处，以及油罐区、消防器材房、消防器材箱等场所和设备设施上设置相应的安全警示标志。"},{"i":60,"n":"第六十条","txt":"煤层气企业进行立、放井架及吊装作业，应当与架空线路保持安全距离，并采取措施防止损害架空线路。"},{"i":61,"n":"第六十一条","txt":"井架绷绳安设不少于4根，绷绳强度应当与钻机匹配，地锚牢固可靠。"},{"i":62,"n":"第六十二条","txt":"钻机水龙头和高压水龙带应当设有保险绳。"},{"i":63,"n":"第六十三条","txt":"钻台地板铺设应当平整、紧密、牢固。井架2层以上平台应当安装可靠防护栏杆，防护栏高度应当大于1.2米，采用防滑钢板。 活动工作台应当安装制动、防坠、防窜、行程限制、安全挂钩、手动定位器等安全装置。"},{"i":64,"n":"第六十四条","txt":"钻机钢丝绳安全系数应当大于7；吊卡处于井口时，绞车滚筒钢丝绳圈数不少于7圈；钢丝绳固定连接绳卡应当不少于3个。"},{"i":65,"n":"第六十五条","txt":"发电机应当配备超载保护装置。电动机应当配备短路、过载保护装置。"},{"i":66,"n":"第六十六条","txt":"柴油机排气管应当无破损、无积炭，其出口不得指向循环罐，不得指向油罐区。井场油罐阀门应当无渗漏，罐口封闭上锁，并有专人管理。"},{"i":67,"n":"第六十七条","txt":"井场电气设备应当设保护接零或者保护接地，保护接地电阻应当小于4欧姆。"},{"i":68,"n":"第六十八条","txt":"井场电力线路应当采用电缆，并架空架设；经过通道、设备处应当增加防护套。井场电器安装技术要求参照国家对井场电气安装技术的要求执行。"},{"i":69,"n":"第六十九条","txt":"煤层气企业安装、拆卸井架时，井架上下不得同时作业。"},{"i":70,"n":"第七十条","txt":"施工现场应当有可靠的通信联络，并保持24小时畅通。"},{"i":71,"n":"第七十一条","txt":"煤层气企业安装井控装置时，放喷管线的布局应当考虑当地季节风向、居民区、道路、油罐区、电力线及各种设施等情况。"},{"i":72,"n":"第七十二条","txt":"钻进施工应当符合下列要求： （一）符合国家标准、行业标准有关常规钻进安全技术的要求； （二）一开、二开、钻目标煤层前等重要工序，由钻井监理进行全面的安全检查，经验收合格后方可作业； （三）钻井队按照规定程序和操作规程进行操作，执行钻井作业设计中有关防火防爆的安全技术要求； （四）选择适当的钻井液； （五）钻进施工中如出现异常情况，及时采取应急措施，立即启动应急预案。"},{"i":73,"n":"第七十三条","txt":"下套管作业应当符合下列要求： （一）吊套管上钻台，使用适当的钢丝绳，不得使用棕绳； （二）套管上扣时推荐使用套管动力钳，下放套管时密切观察指重表读数变化并按程序操作，发现异常及时处理； （三）套管串总重量不得大于钻机或者井架的提升能力，否则需采取相应的减重措施。套管下放时，需边下放边灌注钻井液，以免将浮鞋、浮箍压坏。"},{"i":74,"n":"第七十四条","txt":"固井作业应当符合下列要求： （一）摆车时设专人指挥，下完套管需先灌满套管，不得直接开泵洗井； （二）开泵顶水泥浆时，所有人员不得靠近井口、泵房、高压管汇、安全阀及放压管线。"},{"i":75,"n":"第七十五条","txt":"煤层气企业进行测井施工前，应当召开安全会，提出作业安全要求。 测井施工现场不具备安全生产条件的，不得进行测井作业。"},{"i":76,"n":"第七十六条","txt":"井场钻台前方10米以外应当有摆放测井车辆的开阔地带。器材堆置不得影响车辆的进出及就位。"},{"i":77,"n":"第七十七条","txt":"车载仪器及专用器具上井前，煤层气企业应当妥善包装和固定，运输中禁止与有碍安全的货物混装。车载计算机必须采取防震、防尘措施。 测井车辆行车前及长途行车途中，应当做好车况、放射源及仪器设备安全检查。途中留宿的，必须将车辆停放在安全场所。"},{"i":78,"n":"第七十八条","txt":"测井人员不得擅离职守，不允许在井架、钻台上进行与测井无关的其他作业，未经许可不得动用非本岗位的仪器设备。"},{"i":79,"n":"第七十九条","txt":"摆放测井设备应当充分考虑风向。测井仪器车等工作场所的电源、温度、湿度应当符合安全需要，并做好相应消防措施。测井车应当接地良好，电路系统不得有短路和漏电现象。 当钻井井口一定区域内可能有煤层气积聚时，煤层气企业应当停止测井作业。"},{"i":80,"n":"第八十条","txt":"测井前，煤层气企业应当将井口附近的无关物品移开，及时清除钻台转盘及钻台作业面上的钻井液。冬季测井施工时，应当及时清除深度丈量轮和电缆上的结冰。在井口装卸放射源或者其他仪器时，应当先将井口盖好，不得将工具放在转盘上。 仪器开机前，煤层气企业应当对电源、仪器接线及接地、各部件及计算机、需固定装置的安装状况、绞车的刹车及变速装置进行复查。测井过程中，操作人员应当观察仪器、设备的工作状态，发现异常情况及时处理。"},{"i":81,"n":"第八十一条","txt":"下井仪器应当正确连接，牢固可靠。出入井口时，煤层气企业应当有专人在井口指挥。"},{"i":82,"n":"第八十二条","txt":"绞车启动后，电缆提升和下放过程中，应当避免紧急刹车和骤然加速，工作人员应当避开绞车和电缆活动影响区，严禁触摸和跨越电缆。"},{"i":83,"n":"第八十三条","txt":"仪器起下速度应当均匀，不得超过4000米/小时，距井底200米时应当减速慢下；进入套管鞋时，起速不得超过600米/小时，仪器上起离井口约300米时，应当有专人在井口指挥，减速慢行。"},{"i":84,"n":"第八十四条","txt":"下井仪器遇阻时，操作人员应当将仪器提出井口，通井后再进行测井作业。严禁遇阻强冲。"},{"i":85,"n":"第八十五条","txt":"下井仪器遇卡时，操作人员应当立即停车，缓慢上下活动；如仍未解脱，应当迅速研究具体的处理措施。"},{"i":86,"n":"第八十六条","txt":"仪器在井底及裸眼井段静止时间不得超过1分钟，对停留时间有特殊要求的测井项目除外。"},{"i":87,"n":"第八十七条","txt":"仪器工作结束后，操作人员应当将各操纵部件恢复到安全位置。严禁在通电状态下搬运仪器设备和拔、插接线。"},{"i":88,"n":"第八十八条","txt":"夜间施工时，井场应当保障照明良好。"},{"i":89,"n":"第八十九条","txt":"遇有七级以上大风、暴雨、雷电、大雾等恶劣天气，煤层气企业应当暂停测井作业。如正在测井作业，应当将仪器起入套管内，并关闭仪器电源。"},{"i":90,"n":"第九十条","txt":"测井作业时，井内产出硫化氢或者其他有毒、有害气体的，煤层气企业应当按照有关规定采取相应防护措施，并制定测井方案，待批准后方可进行测井作业。"},{"i":91,"n":"第九十一条","txt":"放射源必须存放在专用源库中，源库的设计及源库内外的剂量当量率应当符合国家有关油（气）田测井用密封型放射源卫生防护标准的要求。煤层气企业应当建立健全放射源的使用档案及领用、保管制度。 施工区应当建立临时源库，源库应当设有警戒标志并有防盗、防丢失措施。"},{"i":92,"n":"第九十二条","txt":"运输放射源的防护容器应当加锁。容器外表面除应当标示放射性核素名称、活度、电离辐射警告标志外，还应当标示容器的编号。防护容器、运源车内及车附近的剂量当量率应当符合国家有关油（气）田测井用密封型放射源卫生防护标准的要求。"},{"i":93,"n":"第九十三条","txt":"放射源必须专车运输、专人押运，中途停车、住宿时应当有专人监护。 运源车严禁搭乘无关人员和押运生活消费品。未采取足够安全防护措施的运源车不得进入人口密集区和在公共停车场停留。"},{"i":94,"n":"第九十四条","txt":"在室外、野外从事放射源工作时，煤层气企业必须根据辐射水平或者放射性污染的可能范围划出警戒区，在醒目位置设置电离辐射警告标志，设专人监护，防止无关人员进入警戒区。"},{"i":95,"n":"第九十五条","txt":"煤层气企业应当定期对从事放射性工作的人员进行个人剂量监测和职业健康检查，建立个人剂量档案和职业健康监护档案。如被确认为放射损伤者，煤层气企业应当将其调离放射性工作并及时治疗。 拟参加放射性工作的人员，必须经过体检；有不适应症者，不得参加此项工作。测井施工人员应当按照辐射防护的时间、距离、屏蔽原则，采取最优化的辐射防护方式，进行装、卸放射源作业，禁止直接接触放射源。"},{"i":96,"n":"第九十六条","txt":"严禁打开放射源的密封外壳，严禁使用密封破坏的可溶性放射源测井。必须裸露使用放射源时，应当使用专用工具。放射性液体和固体废物应当收集在贮存设施内封存，定期上交当地环境保护行政主管部门处理。"},{"i":97,"n":"第九十七条","txt":"放射源的调拨、处理、转让、废弃处理，以及遇有放射源被盗、遗失等放射性事故时，煤层气企业必须按照《放射性同位素与射线装置安全和防护条例》和《放射事故管理规定》的规定进行妥善处理。 放射源掉入井内的，煤层气企业应当及时打捞，并指定专人负责实施；打捞失败的，应当检测放射源所在位置，并按照有关规定打水泥塞封固。"},{"i":98,"n":"第九十八条","txt":"严禁在放射工作场所吸烟、进食和饮水。"},{"i":99,"n":"第九十九条","txt":"射孔作业前应当通井。 射孔作业现场周围的车辆、人员不得使用无线电通信设备；装配现场除工作人员外，严禁其他人员进入，严禁吸烟和使用明火。装配时，操作人员应当站在射孔枪的安全方位。"},{"i":100,"n":"第一百条","txt":"煤层气企业在井口进行接线时，应当将枪身全部下入井内，电缆芯对地短路放电后方可接通。未起爆的枪身应当在断开引线并做好绝缘后，方可起出井口。未起爆的枪身或者已装好的枪身不再进行施工时，应当在圈闭相应的作业区域内及时拆除雷管和射孔弹。 使用过的射孔弹、雷管不得再次使用。"},{"i":101,"n":"第一百零一条","txt":"撞击式井壁取心器炸药的使用，应当遵守国家有关火工品安全管理的规定。"},{"i":102,"n":"第一百零二条","txt":"检测雷管时，检测人员应当使用爆破欧姆表测量，下深超过70米时方可接通电源。"},{"i":103,"n":"第一百零三条","txt":"大雾、雷雨、七级风以上（含七级）天气及夜间不得进行射孔和井壁取心作业。"},{"i":104,"n":"第一百零四条","txt":"施工结束返回后，施工人员应当直接将剩余火工品送交库房，并与保管员办理交接手续。 爆炸物品的销毁，应当符合国家有关石油射孔和井壁取心用爆炸物品销毁标准的规定。"},{"i":105,"n":"第一百零五条","txt":"井场应当具备能摆放压裂设备并方便作业的足够面积，设有明确的安全警示标志。"},{"i":106,"n":"第一百零六条","txt":"施工作业前，施工人员应当详细了解井场内地下管线及电缆分布情况，并按照设计要求做好施工前准备。"},{"i":107,"n":"第一百零七条","txt":"新井、一年内未进行任何作业的老井均应当进行通井。通井时遇到异常情况的，施工人员应当在采取有效措施后方可继续作业。"},{"i":108,"n":"第一百零八条","txt":"压裂设备、井口装置和地面管汇应当满足压裂施工工艺和压力要求。 压裂施工所用高压泵安全销子的剪断压力不得超过高压泵额定最高工作压力。井口应当用专用支架或者其他方式固定。高压管线长度每间隔8米时应当有固定高压管线的措施。 以井口10米为半径，沿泵车出口至井口地面流程两侧10米为边界，设定为高压危险区，并使用专用安全带设置封闭的安全警戒线。"},{"i":109,"n":"第一百零九条","txt":"摆放设备时，煤层气企业应当安排好混砂车与管汇车、管汇车与压裂泵车、压裂泵车距井口的距离。仪表车应当安放在能看到井口、视野开阔的地点。"},{"i":110,"n":"第一百一十条","txt":"压裂施工必须在白天进行。煤层气企业应当对压裂施工进行统一指挥，指挥员应当随时掌握施工动态，保持通讯系统畅通。"},{"i":111,"n":"第一百一十一条","txt":"煤层气企业在施工前应当召开安全会，提出安全要求，明确安全阀限定值，同时进行下列安全检查： （一）检查压裂设备、校对仪表，确保压裂主机及辅机的工作状况良好，待修或者未达到施工要求的设备不得参加施工； （二）按照设计要求试压合格，各部阀门应当灵活好用。设备和管线泄漏时，应当在停泵、泄压后方可检修； （三）压裂车逐台逐挡充分循环排空，排净残液、余砂。"},{"i":112,"n":"第一百一十二条","txt":"施工期间煤层气企业应当派专人负责巡视边界，严禁非施工人员进入井场。高压区必须设有警戒，无关人员不得进入。"},{"i":113,"n":"第一百一十三条","txt":"施工中进出井场的车辆排气管应当安装阻火器。施工车辆通过井场地面裸露的油、气管线及电缆时，煤层气企业应当采取防止碾压的保护措施。"},{"i":114,"n":"第一百一十四条","txt":"泵车操作应当平稳，严禁无故换档或者停车。出现故障必须停车时，操作人员应当及时通知指挥员采取措施。"},{"i":115,"n":"第一百一十五条","txt":"压裂期间，煤层气企业必须有专人监测剩余压裂液液面、支撑剂剩余量和供应情况，确保连续供液和供砂。"},{"i":116,"n":"第一百一十六条","txt":"加砂过程中，压力突然上升或者发生砂堵时，煤层气企业应当及时研究处理，不得强行憋压。 使用放射性示踪剂的，应当按照有关规定采取相应的防护措施，并定期对放射性示踪剂的活度、存储装置是否完好进行检测，对接触人员进行体检。"},{"i":117,"n":"第一百一十七条","txt":"压裂施工后，煤层气企业应当对设备的气路系统、液压系统、吸入排出系统、仪表系统、混合系统、柱塞泵、卡车、燃料系统等进行安全检查和维修保养。"},{"i":118,"n":"第一百一十八条","txt":"排采井场应当符合下列要求： （一）平整、清洁、无杂草； （一）井场周围应当设围栏，围栏高度不得低于1.7米，并有明确的警示标识； （三）井场内所有可能对人体产生碰伤、挤伤或者其他伤害的危险物体均应当涂以红色标记，以示警告。"},{"i":119,"n":"第一百一十九条","txt":"煤层气企业应当将排采沉淀池布置在井场围栏范围内；布置在排采围栏范围外时，应当设独立围栏。"},{"i":120,"n":"第一百二十条","txt":"选择放空火炬的位置应当考虑当地全年主风向，置于全年最小频率风向的上风侧。"},{"i":121,"n":"第一百二十一条","txt":"排采设备应当置于远离放空火炬的一侧摆放，发电机排气筒方向不得正对井口。煤层气企业应当定期用可燃气体检测仪检测阀门、管线是否漏气，发现漏气应当立即检修处理。 气、水管线应当分别安装气、水阀门，气管线应当涂成黄色，水管线应当涂成绿色。"},{"i":122,"n":"第一百二十二条","txt":"煤层气企业应当定期检查气水分离器（如有）的阀门、安全阀是否灵活好用。"},{"i":123,"n":"第一百二十三条","txt":"煤层气企业应当对气水分离器（如有）定期排水，防止造成水堵或者积聚。"},{"i":124,"n":"第一百二十四条","txt":"抽油机的安装应当符合下列要求： （一）地基夯实，水泥基础坐落在土质均匀的原土上，冰冻地区应当开挖至冰冻层以下； （二）基础表面没有裂纹、变形现象； （三）抽油机底座与基础墩接触面紧密贴实，地角螺栓不得悬空； （四）平衡块与曲柄的装配面及曲柄燕尾槽内严禁夹入杂物。"},{"i":125,"n":"第一百二十五条","txt":"抽油机启动前，煤层气企业应当确保抽油机各部位牢固可靠、刹车及皮带松紧适宜、供电系统正常。"},{"i":126,"n":"第一百二十六条","txt":"工作人员巡检时应当与抽油机保持一定的安全距离，刹车操作后应当合上保险装置。抽油机运转或者未停稳时，不得接触、靠近抽油机的运转部位，也不得进行润滑、加油或者调整皮带等操作。"},{"i":127,"n":"第一百二十七条","txt":"进行调整冲程、更换悬绳器等高空作业时，操作人员应当系好安全带并站稳，防止滑落跌伤和工具掉落伤人。"},{"i":128,"n":"第一百二十八条","txt":"更换井口装置时，煤层气企业应当在施工现场配备防火、防爆设施。割焊井口时，煤层气企业必须制定相应的安全技术措施。"},{"i":129,"n":"第一百二十九条","txt":"螺杆泵设备运行期间，应当确保各连接部位无松动、减速箱不漏（缺）油、皮带无松弛、光杆不下滑、机体无过热现象。"},{"i":130,"n":"第一百三十条","txt":"欠载跳闸时，工作人员应当排除方卡子松动、传动部分打滑、断杆卸载等原因后方可开机；过载跳闸时，应当排除短路、缺相现象后方可开机。"},{"i":131,"n":"第一百三十一条","txt":"排采设备的控制柜应当有防护措施，埋地电缆处应当有明显标记。"},{"i":132,"n":"第一百三十二条","txt":"测量电潜泵机组参数时，测量人员必须把控制柜总电源断开，并悬挂警示牌。"},{"i":133,"n":"第一百三十三条","txt":"电潜泵停机时，不得带负荷拉闸。电潜泵出现故障停机时，如未查明原因并排除故障，不得二次启动。"},{"i":134,"n":"第一百三十四条","txt":"动液面测试前，必须在关闭套管阀门并释放压力后，方可安装井口连接器。测试动液面时，应当采用氮气进行击发，严禁采用声弹进行击发。"},{"i":135,"n":"第一百三十五条","txt":"连接器安装完毕后，连接器上的放空阀应当关严，缓慢打开套管阀门。 对有套压井，有关人员必须在套管阀门打开时无异常情况下方可装接信号线。"},{"i":136,"n":"第一百三十六条","txt":"测试结束后，测试人员应当关严套管阀门，打开放空阀门，拆除各连接电缆后，方可卸下井口连接器。"},{"i":137,"n":"第一百三十七条","txt":"示功图测试前，抽油机驴头必须停在下死点，拉住刹车；操作人员应当选择安全的操作位置安装仪器；仪器安装后，必须确保挂上保险装置。"},{"i":138,"n":"第一百三十八条","txt":"修井时，探砂面、冲砂起下管柱应当按照国家有关常规修井作业规程的安全规定执行。"},{"i":139,"n":"第一百三十九条","txt":"冲砂前，水龙带必须拴保险绳，循环管线应当不刺不漏。冲砂时，禁止人员穿越高压区。"},{"i":140,"n":"第一百四十条","txt":"下泵时，井口应当安装防掉、防碰装置，严防井下落物和因碰撞产生火花。禁止挂单吊环操作。 修井机绷绳强度应当与修井机匹配，并确保地锚牢固可靠。"},{"i":141,"n":"第一百四十一条","txt":"洗井时，泵车、水罐车等设备的摆放场地应当处于便于操作的安全位置，出口管线连接应当平直，末端用地锚固定。"},{"i":142,"n":"第一百四十二条","txt":"洗井前必须试压合格，各部阀门应当灵活好用。"},{"i":143,"n":"第一百四十三条","txt":"洗井期间，提升动力设备应当连续运转，不得熄火。泵压升高，洗井不通时，应当及时分析处理，不得强行憋泵；设备和管线泄漏时，应当在停泵、泄压后方可检修。 发生严重漏失时，应当采取有效堵漏措施后再进行施工。"},{"i":144,"n":"第一百四十四条","txt":"煤层气企业应当对报废的煤层气井进行封井处理，建立报废煤层气井的档案，并有施工单位和煤层气企业等有关部门的验收意见。"},{"i":145,"n":"第一百四十五条","txt":"报废的煤层气井的井筒必须用水泥浆或者水泥砂浆封固，封固高度为从井底到最上面一个可采煤层顶板以上100米。废弃的井筒必须在井口打水泥塞，并将地面以下1.5米套管割掉，用钢板将套管焊住，然后填土至与地面平齐。"},{"i":146,"n":"第一百四十六条","txt":"煤层气集输管线线路走向应当根据地形、工程地质、沿线井场（站场）的地理位置以及交通运输、动力等条件，确定最优线路。 管线线路的选择应当符合下列要求： （一）线路顺直、平缓，减少与天然和人工障碍物的交叉； （二）避开重要的军事设施、易燃易爆仓库、国家重点文物保护单位等区域； （三）避开城镇规划区、大型站场、飞机场、火车站和国家级自然保护区等区域。当受条件限制，管线需要在上述区域内通过时，必须征得有关部门同意，留出足够的安全距离，并采取相应的安全保护措施； （四）严禁管线通过铁路或者公路的隧道、桥梁（管线专用公路的隧道、桥梁除外）以及铁路编组站、大型客运站和变电所； （五）避开地下杂散电流干扰大的区域；当避开确有困难时，需采取符合标准、规范的排流措施； （六）避开不良工程地质地段；需选择合适的位置和方式穿越。"},{"i":147,"n":"第一百四十七条","txt":"煤层气管线及管线组件的材质选择，应当综合考虑使用压力、温度、煤层气特性、使用地区、经济性等因素。 煤层气管线及管线组件的材质选择应当符合下列要求： （一）采用材料的强度、寿命满足安全要求，煤层气集输钢质管道的设计符合《油气集输设计规范》（GB50350）的有关规定，煤层气采气聚乙烯管道的设计符合《聚乙烯燃气管道工程技术规程》（CJJ63）的有关规定； （二）材料生产企业按照相应标准生产，并提供产品质量证明书； （三）选用的管线组件符合安全标准并有质量证明书； （四）管线材质满足当地的抗震要求； （五）采用钢管和钢质组件时，应当根据强度等级、管径、壁厚、焊接方式及使用环境温度等因素提出材料韧性要求； （六）穿越铁路、公路、大型河流及人口稠密区时，采用钢管，管线组件严禁使用铸铁件。"},{"i":148,"n":"第一百四十八条","txt":"煤层气集输管线应当采用埋地方式敷设，特殊地段也可以采用土堤、地面、架空等方式敷设。管线敷设应当满足抗震要求。"},{"i":149,"n":"第一百四十九条","txt":"埋地管线坡度应当根据地形的要求，采用弹性敷设，管线埋地深度应当在冻土层以下。覆土层最小厚度、管沟边坡和沟底宽度应当符合国家有关输气管道工程设计规范标准的规定。 管线与其他管线交叉时，其垂直净距一般不得小于0.3米；当小于0.3米时，两管间应当设置坚固的绝缘隔离物。管线与电力、通信电缆交叉时，其垂直净距不得小于0.5米。管线在交叉点两侧各延伸10米以上的管段，应当采用相应的最高绝缘等级。 管线改变方向时，应当优先采用弹性敷设（曲率半径应当大于或者等于管线直径的1000倍），垂直面上弹性敷设管线的曲率半径应当大于管线在自重作用下产生的挠度曲线的曲率半径。曲率半径的计算应当符合国家有关输气管道工程设计规范标准的规定。"},{"i":150,"n":"第一百五十条","txt":"用于改变管线走向的弯头的曲率半径应当大于或者等于外直径的4倍，并便于清管器或者检测仪器顺利通过。现场冷弯弯管的最小曲率半径应当符合国家有关输气管道工程设计规范标准的规定。弯管上的环向焊缝应当进行X射线检查。 管线不得采用斜口连接，不允许采用褶皱弯或者虾米弯，管子对接偏差不得大于3度。"},{"i":151,"n":"第一百五十一条","txt":"管线穿、跨越铁路、公路、河流时，应当符合国家油气输送管道穿越工程设计规范标准和油气输送管道跨越工程设计规范标准的有关规定。"},{"i":152,"n":"第一百五十二条","txt":"管线沿线应当设置里程桩、转角桩、标志桩和警示牌等永久性标志。里程桩应当沿气流前进方向从管线起点至终点每500米连续设置。里程桩可以与阴极保护测试桩结合设置。"},{"i":153,"n":"第一百五十三条","txt":"钢制埋地集输管线的设计应当符合国家有关防腐绝缘与阴极保护标准的有关规定。 管线阴级保护达不到规定要求的，经检测确认防腐层发生老化时，煤层气企业应当及时进行防腐层大修。"},{"i":154,"n":"第一百五十四条","txt":"裸露或者架空的管线应当有良好的防腐绝缘层，带保温层的，采取保温和防水措施。管线应当定期排水，防止造成水堵、冰堵。 站场的进出站两端管线，应当加装绝缘接头，确保干线阴极保护可靠性。"},{"i":155,"n":"第一百五十五条","txt":"煤层气企业应当依据煤层气田地面建设总体规划以及所在地区城镇规划、集输管线走向，结合地形、地貌、工程和水文地质条件，统一规划站场的选址及布局，并远离地质灾害易发区，在站场服务年限内避免受采空区、采动区的影响，确保站场安全。"},{"i":156,"n":"第一百五十六条","txt":"站场应当布置在人员集中场所及明火或者散发火花地点全年最小频率风向的上风侧，站场主要设施与周边有关设施的安全距离应当符合下列要求： （一）与居民区、村镇、公共设施的防火间距不小于30米； （二）与相邻厂矿企业、35千伏及以上变电所的防火间距不小于30米； （三）与公路的间距不小于10米； （四）与铁路线的间距不小于20米； （五）与架空通信线、架空电力线的间距不小于1.5倍杆高； （六）与采石场等爆炸作业场地的间距不小于300米。"},{"i":157,"n":"第一百五十七条","txt":"站场内平面布置、防火安全、场内道路交通及与外界公路的连接应当符合《石油天然气工程设计防火规范》（GB50183）的有关规定。"},{"i":158,"n":"第一百五十八条","txt":"站场的防洪设计标准，应当综合考虑站场规模和受淹损失等因素，集气站重现期为10年至25年，中心处理站重现期为25年至50年。"},{"i":159,"n":"第一百五十九条","txt":"放空管应当位于站场生产区最小频率风向的上风侧，且处于站场外地势较高处，其高度应当比附近建（构）筑物高出2米以上，且总高度不得小于10米。放空管距站场的距离一般不小于10米；当放空量大于12000立方米/小时且等于或者小于40000立方米/小时时，放空管距站场的距离应当不小于40米。"},{"i":160,"n":"第一百六十条","txt":"站场设备应当由具备国家规定资质的企业生产，有产品合格证书并满足安全要求。"},{"i":161,"n":"第一百六十一条","txt":"煤层气企业应当定时记录设备的运转状况，定期分析主要设备的运行状态。安全阀和压力表应当定期进行校验。调节阀、减压阀、高（低）压泄压阀等主要阀门应当按照相应运行和维护规程进行操作和维护，并按照规定定期校验。"},{"i":162,"n":"第一百六十二条","txt":"煤层气企业应当在站场的进口处设置明显的安全警示牌、进站须知和逃生路线图，并应当向进入站场的外来人员告知安全注意事项等。 站场应当设置不低于1.7米的非燃烧材料围墙或者围栏，并设置安全警示标志。 站场内大于或者等于35千伏的变配电站应当设置不低于1.5米的围栏。"},{"i":163,"n":"第一百六十三条","txt":"站场的供电负荷和供电电源应当根据《石油天然气安全规程》（AQ2012）的有关规定确定。用电设备及线路走向应当合理，导体选择及线路敷设应当符合安全规定，线路应当无老化、破损和裸露现象。"},{"i":164,"n":"第一百六十四条","txt":"配电室应当有应急照明，配电室门应当外开，保持通风良好，并安装挡鼠板。电缆沟应当无积水，地沟应当封堵。地沟可燃气体浓度应当定期检验，避免沟内窜气。"},{"i":165,"n":"第一百六十五条","txt":"站场内对管线进行吹扫、试压时，煤层气企业应当编制作业方案，制定安全技术措施。 强度试验和气密试验时发现管线泄漏的，煤层气企业应当查明原因，制定修理方案和安全措施后方可进行修理。"},{"i":166,"n":"第一百六十六条","txt":"压缩机应当允许煤层气组分、进气压力、进气温度和进气量有一定的波动范围。"},{"i":167,"n":"第一百六十七条","txt":"压缩机启动及事故停车安全联锁应当完好。 压缩机的吸入口应当有防止空气进入的措施；压缩机的各级进口应当设凝液分离器或者机械杂质过滤器。分离器应当有排液、液位控制和高液位报警及放空等设施。"},{"i":168,"n":"第一百六十八条","txt":"在煤层气脱水装置前应当设置分离器。 脱水器前及压缩机的出口管线上的截断阀前应当分别设置安全阀。"},{"i":169,"n":"第一百六十九条","txt":"煤层气脱水装置中，气体管线应当选用全启式安全阀，液体管线应当选用微启式安全阀。安全阀弹簧应当具有可靠的防腐蚀性能或者必要的防腐保护措施。"},{"i":170,"n":"第一百七十条","txt":"含硫化氢的煤层气应当脱硫、脱水。距煤层气处理厂较远的酸性煤层气，如因管输产生游离水，应当先脱水、后脱硫。"},{"i":171,"n":"第一百七十一条","txt":"在煤层气处理及输送过程中使用化学药剂时，煤层气企业应当严格执行技术操作规程和措施要求，并落实防冻伤、防中毒和防化学伤害等措施。"},{"i":172,"n":"第一百七十二条","txt":"煤层气企业应当在脱硫溶液系统中设过滤器。"},{"i":173,"n":"第一百七十三条","txt":"进脱硫装置的原料气总管线和再生塔应当设安全阀，液硫储罐最高液位之上应当设置灭火蒸汽管。储罐四周应当设置闭合的不燃烧材料防护墙，墙高应当为1米，四周应当设置相应的消防设施。"},{"i":174,"n":"第一百七十四条","txt":"在含硫容器内作业时，煤层气企业应当进行有毒气体测试，并备有正压式空气呼吸器。"},{"i":175,"n":"第一百七十五条","txt":"集输系统投产应当符合下列要求： （一）管线与设备的严密性试验合格； （二）各单体设备、分系统试运行正常，设备工作状态良好，集输系统整体联合试运行正常； （三）集气管线全线进行试压、清管； （四）制定安全措施和应急预案。"},{"i":176,"n":"第一百七十六条","txt":"管线投运前，煤层气企业应当对管线内的空气进行置换，避免空气与煤层气混合。 置换过程中的混合气体应当利用放空系统放空，并以放空口为中心设立隔离区并禁止烟火。进行氮气置换时，进入管线的氮气温度应当不低于5摄氏度；排放氮气时应当防止大量氮气聚集造成人员窒息，管线中氮气量过大时应当提前进行多点排放。"},{"i":177,"n":"第一百七十七条","txt":"对管线的监控应当遵守下列规定： （一）对重要工艺参数及工作状态进行连续检测和记录； （二）根据沿线情况定期对集输管线进行巡线检查，但每季度至少徒步巡查一次； （三）定时巡查线路分水器，及时排放污水，并有防止冰冻的措施； （四）在雨季、汛期或者其他灾害发生后加密巡查； （五）定期对装有阴极保护设施的管线保护电位进行测试。"},{"i":178,"n":"第一百七十八条","txt":"对站场的监控应当遵守下列规定： （一）压力、计量仪表灵敏准确，设备、管汇无渗漏。根据集输流程分布情况，在站场设置限压放空和压力高、低限报警设施； （二）定时巡查站场内的分离器，及时将污水排放，并有防止冰冻的措施； （三）站场工艺装置区、计量工作间等位于爆炸危险区域内的电气设备及照明采用防爆电器，其选型、安装和电气线路的布置符合《爆炸和火灾危险环境电力装置设计规范》（GB50058）的规定。"},{"i":179,"n":"第一百七十九条","txt":"维护与抢修时，应当制定相应的维护与抢修安全措施和实施方案，合理配备专职维护与抢修队伍，抢修物资装备。"},{"i":180,"n":"第一百八十条","txt":"维护与抢修现场应当采取保护措施，划分安全界限，设置警戒线、警示牌。进入作业场地的人员应当穿戴劳动防护用品。与作业无关的人员不得进入警戒区内。"},{"i":181,"n":"第一百八十一条","txt":"压缩站厂房建筑应当符合下列要求： （一）压缩机地基基础满足设计载荷要求； （二）阀组间、压缩机等厂房使用耐火材料，采用不发火地面； （三）阀组间、压缩机等厂房的门窗向外开启，建筑面积大于100平方米的厂房至少有两个疏散门，并保持通道畅通； （四）阀组间、压缩机等厂房设置通风设备。"},{"i":182,"n":"第一百八十二条","txt":"压缩工艺流程设计应当根据输气系统工艺要求，满足气体的除尘、分液、增压、冷却和机组的启动、停机、正常操作及安全保护等要求。 煤层气处理后应当符合压缩机组对气质的技术要求。"},{"i":183,"n":"第一百八十三条","txt":"压缩机应当符合下列安全要求： （一）压缩机组有紧急停车和安全保护联锁装置； （二）压缩机控制系统设置压力、温度显示与保护联动装置； （三）压缩机前设置缓冲罐； （四）煤层气压缩机单排布置； （五）在高寒地区或者风沙地区压缩机组采用封闭式厂房，其他地区采用敞开式或者半敞开式厂房。"},{"i":184,"n":"第一百八十四条","txt":"新安装或者检修投运压缩机系统装置前，煤层气企业应当对机泵、管线、容器、装置进行系统氮气置换，置换合格后方可投运。"},{"i":185,"n":"第一百八十五条","txt":"设置压缩机组的吸气、排气和泄气管线时，应当避免管线的振动对建筑物造成有害影响；应当有防止空气进入吸气管线的措施，必要时高压排出管线应当设单向阀。"},{"i":186,"n":"第一百八十六条","txt":"压缩机与站内其他建（构）筑物的防火间距应当符合《石油天然气工程设计防火规范》的规定。"},{"i":187,"n":"第一百八十七条","txt":"压缩机组运行时应当符合下列安全保护要求： （一）压缩机级间设置安全阀，安全阀的泄放能力不得小于压缩机的安全泄放量； （二）压缩机进、出口设置高、低压报警和停机装置，冷却系统设置温度报警及停车装置，润滑油系统设置低压报警及停机装置。"},{"i":188,"n":"第一百八十八条","txt":"压缩机气液处理应当符合下列要求： （一）压缩机的卸载排气不得对外放散； （二）回收气可以输送至压缩机进口缓冲罐； （三）对压缩机排出的冷凝液进行集中处理。"},{"i":189,"n":"第一百八十九条","txt":"压缩煤层气储气设备应当符合下列安全要求： （一）储气瓶符合国家有关安全规定和标准； （二）储气井的设计、建造和检验符合国家有关高压气地下储气井标准的规定； （三）储气瓶组或者储气井与站内汽车通道相邻一侧，设置安全防撞拦或者采取其他防撞设施； （四）储气瓶组（储气井）进气总管上设置安全阀及紧急放空管、压力表；每个储气瓶（井）出口设置截止阀。"},{"i":190,"n":"第一百九十条","txt":"煤层气压力储罐（球罐、卧式罐）应当安装紧急放空、安全泄压设施及压力仪表。煤层气储罐（柜）检修动火时，应当经放空、清洗、强制通风，并检验气体中甲烷浓度（低于0.5%为合格）。"},{"i":191,"n":"第一百九十一条","txt":"煤层气企业应当对煤层气储罐定期检测。煤层气储罐区应当有明显的安全警示标志。"},{"i":192,"n":"第一百九十二条","txt":"固定式储罐应当有喷淋水或者遮阳设施。冬季应当有保温防冻措施。"},{"i":193,"n":"第一百九十三条","txt":"压缩煤层气加气机不得设在室内，加气机附近应当设置防撞柱（栏）。 在寒冷地区应当选用适合当地环境温度条件的加气机。"},{"i":194,"n":"第一百九十四条","txt":"加气机的加气软管及软管接头应当选用具有抗腐蚀性能的材料。加气软管上应当设置拉断阀，拉断阀在外力作用下分开后，两端应当自行密封。"},{"i":195,"n":"第一百九十五条","txt":"进站管线上应当设置紧急截断阀，手动紧急截断阀的位置应当便于发生事故时及时切断气源。储气瓶组（储气井）与加气枪之间应当设储气瓶组（储气井）截断阀、主截断阀、紧急截断阀和加气截断阀。"},{"i":196,"n":"第一百九十六条","txt":"工艺安全及监控系统应当符合下列要求： （一）在站场压力设备和容器上设置安全阀； （二）当工艺管线、设备或者容器排污可能释放出大量气体时，将其引入分离设备，分出的气体引入气体放空系统，液体引入储罐或者处理系统； （三）每台压缩机有独立的温度和压力保护装置； （四）压缩站在管线进站截断阀上游和出站截断阀下游设置限压泄放设施。"},{"i":197,"n":"第一百九十七条","txt":"站场供电和电气安全应当符合下列要求： （一）站场的消防、通信、控制、仪表等使用不间断电源或者双回路供电，消防、控制、配电等重要场所设置应急照明； （二）站场内管汇、阀组、压缩机等爆炸危险区域必须使用防爆电气设施，电气线路使用阻燃电缆，线路的敷设采取防爆安全措施； （三）配电室有防水、防鼠措施，安装挡鼠板，安全通道畅通，指示标志明显。"},{"i":198,"n":"第一百九十八条","txt":"压缩站的防爆应当符合下列要求： （一）压缩站按照防爆安全要求划分爆炸危险场所； （二）使用防爆电气设备前，检查其产品合格证、产品安全标志及其安全性能，检查合格并签发合格证后方可使用； （三）防爆电气设备安装、检查、保养、检修由具有专业资格的人员操作，并在机房、调配区设置“爆炸危险场所”标志牌； （四）固定电气设备安装稳固，防止外力碰撞、损伤。"},{"i":199,"n":"第一百九十九条","txt":"压缩站内电气设备应当符合下列防爆要求： （一）整洁，部件齐全紧固，无松动、无损伤、无机械变形，场所清洁、无杂物和易燃物品； （二）选型符合《爆炸和火灾危险环境有关电力设计规范》的要求； （三）电缆进线装置密封可靠，空余接线孔封闭符合要求； （四）设备保护、联锁、检测、报警、接地等装置齐全完整； （五）防爆灯具的防爆结构、保护罩保持完整； （六）接地端子接触良好，无松动、无折断、无腐蚀； （七）应急照明设施符合防爆要求。"},{"i":200,"n":"第二百条","txt":"防爆电气设备检查检修时应当符合下列要求： （一）日常检查中严禁带电打开设备的密封盒、接线盒、进线装置、隔离密封盒等； （二）禁止带电检修或者移动电气设备、线路、拆装防爆灯具和更换防爆灯泡、灯管； （三）断电处悬挂警告牌； （四）禁止用水冲洗防爆电气设备； （五）对检修现场的电源电缆线头进行防爆处理； （六）检修带有电容、电感、探测头等储能元件的防爆设备时，在按照规定放尽能量后方可作业； （七）检修过程中不得损伤防爆设备的隔爆面； （八）紧固螺栓不得任意调换或者缺少； （九）记录检修项目、内容、测试结果、零部件更换、缺陷处理等情况，并归档保存。"},{"i":201,"n":"第二百零一条","txt":"操作压缩机时应当符合下列要求： （一）定时进行设备和仪表的日常巡检与维护，确保其完好； （二）定期校验安全阀、压力表，确保其准确性； （三）开机前检查注油器和机身的油量是否达到开机要求，电气设备是否完好，煤层气泄露监测系统自检有无问题，管线是否松动，阀门及法兰是否有漏气、漏水现象，阀门是否在正确位置，电机有无卡塞情况； （四）操作时严格执行设备操作规程，注意高温管线，防止烫伤，防止超压、超温及机件损坏； （五）机器运转过程中随时检查气压、水压、电压、排气温度以及压缩机的振动强度，发现问题及时处理； （六）压缩机运转过程中观察每一级的气体温度和循环水的温度； （七）压缩机运转过程中按照规定排污，并密切注意末级排气压力；当压力达到一定值时，及时告知加气工；发生不正常的响声或者压力、温度超出允许范围时，立即停机检查，排除故障；出现紧急情况时，按照事故紧急处理预案进行处理。"},{"i":202,"n":"第二百零二条","txt":"清洗设备、器具时应当符合下列要求： （一）严禁使用汽油、苯等易燃品清洗设备、器具和地坪； （二）严禁使用压缩气体清扫储存易燃油品油罐； （三）严禁使用化纤、塑料、丝绸等容易产生静电的制品擦拭物体及设备； （四）清洗设备时，作业人员按照规定着装并消除人体静电。"},{"i":203,"n":"第二百零三条","txt":"人员着装和防静电应当符合下列要求： （一）进入爆炸危险场所，穿着有劳动安全标志的防静电服、棉布工作服和防静电鞋； （二）进入爆炸危险场所前，预先触摸人体消静电球； （三）严禁在爆炸危险场所穿衣、脱衣、拍打服装以及梳头、打闹等； （四）爆炸危险场所的地坪不得涂刷绝缘油漆，或者铺设非导静电的材料。"},{"i":204,"n":"第二百零四条","txt":"人员操作应当符合下列要求： （一）经过本工种专业安全培训，通过考试取得合格证后，持证上岗； （二）掌握岗位应急预案的执行程序，遇到紧急情况，能够按照应急措施迅速作出处理； （三）熟悉本岗位装置的工作原理、构造、性能、技术特征、零部件的名称和作用； （四）熟悉本岗位电气控制设备的操作方法和有关的电气基本知识； （五）按照规定穿好工作服，并佩戴有关劳动防护用品； （六）排污时严禁操作人员将手伸向排污口； （七）排污时发现异常情况立即报告，由专业人员处理。"},{"i":205,"n":"第二百零五条","txt":"本规程下列用语的含义： 煤层气，是指赋存在煤层中以甲烷为主要成分、以吸附在煤基质颗粒表面为主、部分游离于煤孔隙中或者溶解于煤层水中的烃类气体。 煤层气地面开采，是指煤层气井的钻井、测井、压裂等施工环节及后期的排采管理、管线集输和压缩工程。 煤层气企业，是指专门从事煤层气地面开采的企业。 井位，是指为了进行煤层气开采而综合各种地质资料进行设计和优选出来的井的布置位置。 排采，是指通过抽排煤层及其围岩中的地下水来降低煤储层的压力，诱导甲烷从煤层中解吸出来。 煤层气井，是指通过地面钻井进入煤层，利用煤层气自身赋存压力与钻井空间的压力差释放煤层气的井孔。 裸眼井，是指在煤层顶部下套管后，一直钻进煤层至设计深度终孔，使煤层裸露的煤层气井。 站场，是指收集煤层气气源，进行净化处理，压缩输送的站场。 阈限值，是指长期暴露的工作人员不会受到不利影响的某种有毒物质在空气中的最大浓度。 安全临界浓度，是指"},{"i":206,"n":"第二百零六条","txt":"本规程自2012年4月1日起施行。煤层气地面开采活动施行的其他规程、规范与本规程相抵触的，依照本规程执行。"}],"meikuangqiyeanquanshengchanxukezhengshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范煤矿企业安全生产条件，加强煤矿企业安全生产许可证的颁发管理工作，根据《安全生产许可证条例》和有关法律、行政法规，制定本实施办法。"},{"i":2,"n":"第二条","txt":"煤矿企业必须依照本实施办法的规定取得安全生产许可证。未取得安全生产许可证的，不得从事生产活动。 煤层气地面开采企业安全生产许可证的管理办法，另行制定。"},{"i":3,"n":"第三条","txt":"煤矿企业除本企业申请办理安全生产许可证外，其所属矿（井、露天坑）也应当申请办理安全生产许可证，一矿（井、露天坑）一证。 煤矿企业实行多级管理的，其上级煤矿企业也应当申请办理安全生产许可证。"},{"i":4,"n":"第四条","txt":"安全生产许可证的颁发管理工作实行企业申请、两级发证、属地监管的原则。"},{"i":5,"n":"第五条","txt":"国家煤矿安全监察局指导、监督全国煤矿企业安全生产许可证的颁发管理工作，负责符合本办法第三条规定的中央管理的煤矿企业总部（总公司、集团公司）安全生产许可证的颁发和管理。 省级煤矿安全监察局负责前款规定以外的其他煤矿企业安全生产许可证的颁发和管理；未设立煤矿安全监察机构的省、自治区，由省、自治区人民政府指定的部门（以下与省级煤矿安全监察局统称省级安全生产许可证颁发管理机关）负责本行政区域内煤矿企业安全生产许可证的颁发和管理。 国家煤矿安全监察局和省级安全生产许可证颁发管理机关统称安全生产许可证颁发管理机关。"},{"i":6,"n":"第六条","txt":"煤矿企业取得安全生产许可证，应当具备下列安全生产条件： （一）建立、健全主要负责人、分管负责人、安全生产管理人员、职能部门、岗位安全生产责任制；制定安全目标管理、安全奖惩、安全技术审批、事故隐患排查治理、安全检查、安全办公会议、地质灾害普查、井下劳动组织定员、矿领导带班下井、井工煤矿入井检身与出入井人员清点等安全生产规章制度和各工种操作规程； （二）安全投入满足安全生产要求，并按照有关规定足额提取和使用安全生产费用； （三）设置安全生产管理机构，配备专职安全生产管理人员；煤与瓦斯突出矿井、水文地质类型复杂矿井还应设置专门的防治煤与瓦斯突出管理机构和防治水管理机构； （四）主要负责人和安全生产管理人员的安全生产知识和管理能力经考核合格； （五）参加工伤保险，为从业人员缴纳工伤保险费； （六）制定重大危险源检测、评估和监控措施； （七）制定应急救援预案，并按照规定设立矿山救护队，配备救护装"},{"i":7,"n":"第七条","txt":"煤矿除符合本实施办法第六条规定的条件外，还必须符合下列条件： （一）特种作业人员经有关业务主管部门考核合格，取得特种作业操作资格证书； （二）从业人员进行安全生产教育培训，并经考试合格； （三）制定职业危害防治措施、综合防尘措施，建立粉尘检测制度，为从业人员配备符合国家标准或者行业标准的劳动防护用品； （四）依法进行安全评价； （五）制定矿井灾害预防和处理计划； （六）依法取得采矿许可证，并在有效期内。"},{"i":8,"n":"第八条","txt":"井工煤矿除符合本实施办法第六条、第七条规定的条件外，其安全设施、设备、工艺还必须符合下列条件： （一）矿井至少有2个能行人的通达地面的安全出口，各个出口之间的距离不得小于30米；井下每一个水平到上一个水平和各个采（盘）区至少有两个便于行人的安全出口，并与通达地面的安全出口相连接；采煤工作面有两个畅通的安全出口，一个通到进风巷道，另一个通到回风巷道。在用巷道净断面满足行人、运输、通风和安全设施及设备安装、检修、施工的需要； （二）按规定进行瓦斯等级、煤层自燃倾向性和煤尘爆炸危险性鉴定； （三）矿井有完善的独立通风系统。矿井、采区和采掘工作面的供风能力满足安全生产要求，矿井使用安装在地面的矿用主要通风机进行通风，并有同等能力的备用主要通风机，主要通风机按规定进行性能检测；生产水平和采区实行分区通风；高瓦斯和煤与瓦斯突出矿井、开采容易自燃煤层的矿井、煤层群联合布置矿井的每个采区设置专用回风巷"},{"i":9,"n":"第九条","txt":"露天煤矿除符合本实施办法第六条、第七条规定的条件外，其安全设施、设备、工艺还必须符合下列条件： （一）按规定设置栅栏、安全挡墙、警示标志； （二）露天采场最终边坡的台阶坡面角和边坡角符合最终边坡设计要求； （三）配电线路、电动机、变压器的保护符合安全要求； （四）爆炸物品的领用、保管和使用符合规定； （五）有边坡工程、地质勘探工程、岩土物理力学试验和稳定性分析，有边坡监测措施； （六）有防排水设施和措施； （七）地面和采场内的防灭火措施符合规定；开采有自然发火倾向的煤层或者开采范围内存在火区时，制定专门防灭火措施； （八）有反映实际情况的图纸：地形地质图，工程地质平面图、断面图、综合水文地质图，采剥、排土工程平面图和运输系统图，供配电系统图，通信系统图，防排水系统图，边坡监测系统平面图，井工采空区与露天矿平面对照图。"},{"i":10,"n":"第十条","txt":"煤矿企业依据本实施办法第五条的规定向安全生产许可证颁发管理机关申请领取安全生产许可证。"},{"i":11,"n":"第十一条","txt":"申请领取安全生产许可证应当提供下列文件、资料： （一）煤矿企业提供的文件、资料： 1.安全生产许可证申请书； 2.主要负责人安全生产责任制（复制件），各分管负责人、安全生产管理人员以及职能部门负责人安全生产责任制目录清单； 3.安全生产规章制度目录清单； 4.设置安全生产管理机构、配备专职安全生产管理人员的文件（复制件）； 5.主要负责人、安全生产管理人员安全生产知识和管理能力考核合格的证明材料； 6.特种作业人员培训计划，从业人员安全生产教育培训计划； 7.为从业人员缴纳工伤保险费的有关证明材料； 8.重大危险源检测、评估和监控措施； 9.事故应急救援预案，设立矿山救护队的文件或者与专业救护队签订的救护协议。 （二）煤矿提供的文件、资料和图纸： 1.安全生产许可证申请书； 2.采矿许可证（复制件）； 3.主要负责人安全生产责任制（复制件），各分管负责人、安全生产管理人员以及职能部门负"},{"i":12,"n":"第十二条","txt":"安全生产许可证颁发管理机关对申请人提交的申请书及文件、资料，应当按照下列规定处理： （一）申请事项不属于本机关职权范围的，即时作出不予受理的决定，并告知申请人向有关行政机关申请； （二）申请材料存在可以当场更正的错误的，允许或者要求申请人当场更正，并即时出具受理的书面凭证，通过互联网申请的，符合要求后即时提供电子受理回执； （三）申请材料不齐全或者不符合要求的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合要求或者按照要求全部补正的，自收到申请材料或者全部补正材料之日起为受理。"},{"i":13,"n":"第十三条","txt":"煤矿企业应当对其向安全生产许可证颁发管理机关提交的文件、资料和图纸的真实性负责。 从事安全评价、检测检验的机构应当对其出具的安全评价报告、检测检验结果负责。"},{"i":14,"n":"第十四条","txt":"对已经受理的申请，安全生产许可证颁发管理机关应当指派有关人员对申请材料进行审查；对申请材料实质内容存在疑问，认为需要到现场核查的，应当到现场进行核查。"},{"i":15,"n":"第十五条","txt":"负责审查的有关人员提出审查意见。 安全生产许可证颁发管理机关应当对有关人员提出的审查意见进行讨论，并在受理申请之日起45个工作日内作出颁发或者不予颁发安全生产许可证的决定。 对决定颁发的，安全生产许可证颁发管理机关应当自决定之日起10个工作日内送达或者通知申请人领取安全生产许可证；对不予颁发的，应当在10个工作日内书面通知申请人并说明理由。"},{"i":16,"n":"第十六条","txt":"经审查符合本实施办法规定的，安全生产许可证颁发管理机关应当分别向煤矿企业及其所属煤矿颁发安全生产许可证。"},{"i":17,"n":"第十七条","txt":"安全生产许可证的有效期为3年。安全生产许可证有效期满需要延期的，煤矿企业应当于期满前3个月按照本实施办法第十条的规定，向原安全生产许可证颁发管理机关提出延期申请，并提交本实施办法第十一条规定的文件、资料和安全生产许可证正本、副本。"},{"i":18,"n":"第十八条","txt":"对已经受理的延期申请，安全生产许可证颁发管理机关应当按照本实施办法的规定办理安全生产许可证延期手续。"},{"i":19,"n":"第十九条","txt":"煤矿企业在安全生产许可证有效期内符合下列条件，在安全生产许可证有效期届满时，经原安全生产许可证颁发管理机关同意，不再审查，直接办理延期手续： （一）严格遵守有关安全生产的法律法规和本实施办法； （二）接受安全生产许可证颁发管理机关及煤矿安全监察机构的监督检查； （三）未因存在严重违法行为纳入安全生产不良记录“黑名单”管理； （四）未发生生产安全死亡事故； （五）煤矿安全质量标准化等级达到二级及以上。"},{"i":20,"n":"第二十条","txt":"煤矿企业在安全生产许可证有效期内有下列情形之一的，应当向原安全生产许可证颁发管理机关申请变更安全生产许可证： （一）变更主要负责人的； （二）变更隶属关系的； （三）变更经济类型的； （四）变更煤矿企业名称的； （五）煤矿改建、扩建工程经验收合格的。 变更本条第一款第一、二、三、四项的，自工商营业执照变更之日起10个工作日内提出申请；变更本条第一款第五项的，应当在改建、扩建工程验收合格后10个工作日内提出申请。 申请变更本条第一款第一项的，应提供变更后的工商营业执照副本和主要负责人任命文件（或者聘书）；申请变更本条第一款第二、三、四项的，应提供变更后的工商营业执照副本；申请变更本条第一款第五项的，应提供改建、扩建工程安全设施及条件竣工验收合格的证明材料。"},{"i":21,"n":"第二十一条","txt":"对于本实施办法第二十条第一款第一、二、三、四项的变更申请，安全生产许可证颁发管理机关在对申请人提交的相关文件、资料审核后，即可办理安全生产许可证变更。 对于本实施办法第二十条第一款第五项的变更申请，安全生产许可证颁发管理机关应当按照本实施办法第十四条、第十五条的规定办理安全生产许可证变更。"},{"i":22,"n":"第二十二条","txt":"经安全生产许可证颁发管理机关审查同意延期、变更安全生产许可证的，安全生产许可证颁发管理机关应当收回原安全生产许可证正本，换发新的安全生产许可证正本；在安全生产许可证副本上注明延期、变更内容，并加盖公章。"},{"i":23,"n":"第二十三条","txt":"煤矿企业停办、关闭的，应当自停办、关闭决定之日起10个工作日内向原安全生产许可证颁发管理机关申请注销安全生产许可证，并提供煤矿开采现状报告、实测图纸和遗留事故隐患的报告及防治措施。"},{"i":24,"n":"第二十四条","txt":"安全生产许可证分为正本和副本，具有同等法律效力，正本为悬挂式，副本为折页式。 安全生产许可证颁发管理机关应当在安全生产许可证正本、副本上载明煤矿企业名称、主要负责人、注册地址、隶属关系、经济类型、有效期、发证机关、发证日期等内容。 安全生产许可证正本、副本的式样由国家煤矿安全监察局制定。 安全生产许可证相关的行政许可文书由国家煤矿安全监察局规定统一的格式。"},{"i":25,"n":"第二十五条","txt":"煤矿企业取得安全生产许可证后，应当加强日常安全生产管理，不得降低安全生产条件。"},{"i":26,"n":"第二十六条","txt":"煤矿企业不得转让、冒用、买卖、出租、出借或者使用伪造的安全生产许可证。"},{"i":27,"n":"第二十七条","txt":"安全生产许可证颁发管理机关应当坚持公开、公平、公正的原则，严格依照本实施办法的规定审查、颁发安全生产许可证。 安全生产许可证颁发管理机关工作人员在安全生产许可证颁发、管理和监督检查工作中，不得索取或者接受煤矿企业的财物，不得谋取其他利益。"},{"i":28,"n":"第二十八条","txt":"安全生产许可证颁发管理机关发现有下列情形之一的，应当撤销已经颁发的安全生产许可证： （一）超越职权颁发安全生产许可证的； （二）违反本实施办法规定的程序颁发安全生产许可证的； （三）不具备本实施办法规定的安全生产条件颁发安全生产许可证的； （四）以欺骗、贿赂等不正当手段取得安全生产许可证的。"},{"i":29,"n":"第二十九条","txt":"取得安全生产许可证的煤矿企业有下列情形之一的，安全生产许可证颁发管理机关应当注销其安全生产许可证： （一）终止煤炭生产活动的； （二）安全生产许可证被依法撤销的； （三）安全生产许可证被依法吊销的； （四）安全生产许可证有效期满未申请办理延期手续的。"},{"i":30,"n":"第三十条","txt":"煤矿企业隐瞒有关情况或者提供虚假材料申请安全生产许可证的，安全生产许可证颁发管理机关不予受理，且在一年内不得再次申请安全生产许可证。"},{"i":31,"n":"第三十一条","txt":"安全生产许可证颁发管理机关应当每年向社会公布一次煤矿企业取得安全生产许可证的情况。"},{"i":32,"n":"第三十二条","txt":"安全生产许可证颁发管理机关应当将煤矿企业安全生产许可证颁发管理情况通报煤矿企业所在地市级以上人民政府及其指定的负责煤矿安全监管工作的部门。"},{"i":33,"n":"第三十三条","txt":"安全生产许可证颁发管理机关应当建立、健全安全生产许可证档案管理制度。"},{"i":34,"n":"第三十四条","txt":"省级安全生产许可证颁发管理机关应当于每年1月15日前将所负责行政区域内上年度煤矿企业安全生产许可证颁发和管理情况报国家煤矿安全监察局，同时通报本级安全生产监督管理部门。"},{"i":35,"n":"第三十五条","txt":"任何单位或者个人对违反《安全生产许可证条例》和本实施办法规定的行为，有权向安全生产许可证颁发管理机关或者监察机关等有关部门举报。"},{"i":36,"n":"第三十六条","txt":"安全生产许可证颁发管理机关工作人员有下列行为之一的，给予降级或者撤职的处分；构成犯罪的，依法追究刑事责任： （一）向不符合本实施办法规定的安全生产条件的煤矿企业颁发安全生产许可证的； （二）发现煤矿企业未依法取得安全生产许可证擅自从事生产活动不依法处理的； （三）发现取得安全生产许可证的煤矿企业不再具备本实施办法规定的安全生产条件不依法处理的； （四）接到对违反本实施办法规定行为的举报后，不依法处理的； （五）在安全生产许可证颁发、管理和监督检查工作中，索取或者接受煤矿企业的财物，或者谋取其他利益的。"},{"i":37,"n":"第三十七条","txt":"承担安全评价、检测、检验工作的机构，出具虚假安全评价、检测、检验报告或者证明的，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款，没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与煤矿企业承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构，依法吊销其相应资质。"},{"i":38,"n":"第三十八条","txt":"安全生产许可证颁发管理机关应当加强对取得安全生产许可证的煤矿企业的监督检查，发现其不再具备本实施办法规定的安全生产条件的，应当责令限期整改，依法暂扣安全生产许可证；经整改仍不具备本实施办法规定的安全生产条件的，依法吊销安全生产许可证。"},{"i":39,"n":"第三十九条","txt":"取得安全生产许可证的煤矿企业，倒卖、出租、出借或者以其他形式非法转让安全生产许可证的，没收违法所得，处10万元以上50万元以下的罚款，吊销其安全生产许可证；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"发现煤矿企业有下列行为之一的，责令停止生产，没收违法所得，并处10万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任： （一）未取得安全生产许可证，擅自进行生产的； （二）接受转让的安全生产许可证的； （三）冒用安全生产许可证的； （四）使用伪造安全生产许可证的。"},{"i":41,"n":"第四十一条","txt":"在安全生产许可证有效期满未申请办理延期手续，继续进行生产的，责令停止生产，限期补办延期手续，没收违法所得，并处5万元以上10万元以下的罚款；逾期仍不申请办理延期手续，依照本实施办法第二十九条、第四十条的规定处理。"},{"i":42,"n":"第四十二条","txt":"在安全生产许可证有效期内，主要负责人、隶属关系、经济类型、煤矿企业名称发生变化，未按本实施办法申请办理变更手续的，责令限期补办变更手续，并处1万元以上3万元以下罚款。 改建、扩建工程已经验收合格，未按本实施办法规定申请办理变更手续擅自投入生产的，责令停止生产，限期补办变更手续，并处1万元以上3万元以下罚款；逾期仍不办理变更手续，继续进行生产的，依照本实施办法第四十条的规定处罚。"},{"i":43,"n":"第四十三条","txt":"本实施办法规定的行政处罚，由安全生产许可证颁发管理机关决定。除吊销安全生产许可证外，安全生产许可证颁发管理机关可以委托有关省级煤矿安全监察局、煤矿安全监察分局实施行政处罚。"},{"i":44,"n":"第四十四条","txt":"本实施办法自2016年4月1日起施行。原国家安全生产监督管理局（国家煤矿安全监察局）2004年5月17日公布、国家安全生产监督管理总局2015年6月8日修改的《煤矿企业安全生产许可证实施办法》同时废止。"}],"meikuanganquanpeixunguiding":[{"i":1,"n":"第一条","txt":"为了加强和规范煤矿安全培训工作，提高从业人员安全素质，防止和减少伤亡事故，根据《中华人民共和国安全生产法》《中华人民共和国职业病防治法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"煤矿企业从业人员安全培训、考核、发证及监督管理工作适用本规定。 本规定所称煤矿企业，是指在依法批准的矿区范围内从事煤炭资源开采活动的企业，包括集团公司、上市公司、总公司、矿务局、煤矿。 本规定所称煤矿企业从业人员，是指煤矿企业主要负责人、安全生产管理人员、特种作业人员和其他从业人员。"},{"i":3,"n":"第三条","txt":"国家煤矿安全监察局负责指导和监督管理全国煤矿企业从业人员安全培训工作。 省、自治区、直辖市人民政府负责煤矿安全培训的主管部门（以下简称省级煤矿安全培训主管部门）负责指导和监督管理本行政区域内煤矿企业从业人员安全培训工作。 省级及以下煤矿安全监察机构对辖区内煤矿企业从业人员安全培训工作依法实施监察。"},{"i":4,"n":"第四条","txt":"煤矿企业是安全培训的责任主体，应当依法对从业人员进行安全生产教育和培训，提高从业人员的安全生产意识和能力。 煤矿企业主要负责人对本企业从业人员安全培训工作全面负责。"},{"i":5,"n":"第五条","txt":"国家鼓励煤矿企业变招工为招生。煤矿企业新招井下从业人员，应当优先录用大中专学校、职业高中、技工学校煤矿相关专业的毕业生。"},{"i":6,"n":"第六条","txt":"煤矿企业应当建立完善安全培训管理制度，制定年度安全培训计划，明确负责安全培训工作的机构，配备专职或者兼职安全培训管理人员，按照国家规定的比例提取教育培训经费。其中，用于安全培训的资金不得低于教育培训经费总额的百分之四十。"},{"i":7,"n":"第七条","txt":"对从业人员的安全技术培训，具备《安全培训机构基本条件》（AQ/T8011）规定的安全培训条件的煤矿企业应当以自主培训为主，也可以委托具备安全培训条件的机构进行安全培训。 不具备安全培训条件的煤矿企业应当委托具备安全培训条件的机构进行安全培训。 从事煤矿安全培训的机构，应当将教师、教学和实习与实训设施等情况书面报告所在地省级煤矿安全培训主管部门。"},{"i":8,"n":"第八条","txt":"煤矿企业应当建立健全从业人员安全培训档案，实行一人一档。煤矿企业从业人员安全培训档案的内容包括： （一）学员登记表，包括学员的文化程度、职务、职称、工作经历、技能等级晋升等情况； （二）身份证复印件、学历证书复印件； （三）历次接受安全培训、考核的情况； （四）安全生产违规违章行为记录，以及被追究责任，受到处分、处理的情况； （五）其他有关情况。 煤矿企业从业人员安全培训档案应当按照《企业文件材料归档范围和档案保管期限规定》（国家档案局令第10号）保存。"},{"i":9,"n":"第九条","txt":"煤矿企业除建立从业人员安全培训档案外，还应当建立企业安全培训档案，实行一期一档。煤矿企业安全培训档案的内容包括： （一）培训计划； （二）培训时间、地点； （三）培训课时及授课教师； （四）课程讲义； （五）学员名册、考勤、考核情况； （六）综合考评报告等； （七）其他有关情况。 对煤矿企业主要负责人和安全生产管理人员的煤矿企业安全培训档案应当保存三年以上，对特种作业人员的煤矿企业安全培训档案应当保存六年以上，其他从业人员的煤矿企业安全培训档案应当保存三年以上。"},{"i":10,"n":"第十条","txt":"本规定所称煤矿企业主要负责人，是指煤矿企业的董事长、总经理，矿务局局长，煤矿矿长等人员。 本规定所称煤矿企业安全生产管理人员，是指煤矿企业分管安全、采煤、掘进、通风、机电、运输、地测、防治水、调度等工作的副董事长、副总经理、副局长、副矿长，总工程师、副总工程师和技术负责人，安全生产管理机构负责人及其管理人员，采煤、掘进、通风、机电、运输、地测、防治水、调度等职能部门（含煤矿井、区、科、队）负责人。"},{"i":11,"n":"第十一条","txt":"煤矿矿长、副矿长、总工程师、副总工程师应当具备煤矿相关专业大专及以上学历，具有三年以上煤矿相关工作经历。 煤矿安全生产管理机构负责人应当具备煤矿相关专业中专及以上学历，具有二年以上煤矿安全生产相关工作经历。"},{"i":12,"n":"第十二条","txt":"煤矿企业应当每年组织主要负责人和安全生产管理人员进行新法律法规、新标准、新规程、新技术、新工艺、新设备和新材料等方面的安全培训。"},{"i":13,"n":"第十三条","txt":"国家煤矿安全监察局组织制定煤矿企业主要负责人和安全生产管理人员安全生产知识和管理能力考核的标准，建立国家级考试题库。 省级煤矿安全培训主管部门应当根据前款规定的考核标准，建立省级考试题库，并报国家煤矿安全监察局备案。"},{"i":14,"n":"第十四条","txt":"煤矿企业主要负责人考试应当包括下列内容： （一）国家安全生产方针、政策和有关安全生产的法律、法规、规章及标准； （二）安全生产管理、安全生产技术和职业健康基本知识； （三）重大危险源管理、重大事故防范、应急管理和事故调查处理的有关规定； （四）国内外先进的安全生产管理经验； （五）典型事故和应急救援案例分析； （六）其他需要考试的内容。"},{"i":15,"n":"第十五条","txt":"煤矿企业安全生产管理人员考试应当包括下列内容： （一）国家安全生产方针、政策和有关安全生产的法律、法规、规章及标准； （二）安全生产管理、安全生产技术、职业健康等知识； （三）伤亡事故报告、统计及职业危害的调查处理方法； （四）应急管理的内容及其要求； （五）国内外先进的安全生产管理经验； （六）典型事故和应急救援案例分析； （七）其他需要考试的内容。"},{"i":16,"n":"第十六条","txt":"国家煤矿安全监察局负责中央管理的煤矿企业总部（含所属在京一级子公司）主要负责人和安全生产管理人员考核工作。 省级煤矿安全培训主管部门负责本行政区域内前款以外的煤矿企业主要负责人和安全生产管理人员考核工作。 国家煤矿安全监察局和省级煤矿安全培训主管部门（以下统称考核部门）应当定期组织考核，并提前公布考核时间。"},{"i":17,"n":"第十七条","txt":"煤矿企业主要负责人和安全生产管理人员应当自任职之日起六个月内通过考核部门组织的安全生产知识和管理能力考核，并持续保持相应水平和能力。 煤矿企业主要负责人和安全生产管理人员应当自任职之日起三十日内，按照本规定第十六条的规定向考核部门提出考核申请，并提交其任职文件、学历、工作经历等相关材料。 考核部门接到煤矿企业主要负责人和安全生产管理人员申请及其材料后，经审核符合条件的，应当及时组织相应的考试；发现申请人不符合本规定第十一条规定的，不得对申请人进行安全生产知识和管理能力考试，并书面告知申请人及其所在煤矿企业或其任免机关调整其工作岗位。"},{"i":18,"n":"第十八条","txt":"煤矿企业主要负责人和安全生产管理人员的考试应当在规定的考点采用计算机方式进行。考试试题从国家级考试题库和省级考试题库随机抽取，其中抽取国家级考试题库试题比例占百分之八十以上。考试满分为一百分，八十分以上为合格。 考核部门应当自考试结束之日起五个工作日内公布考试成绩。"},{"i":19,"n":"第十九条","txt":"煤矿企业主要负责人和安全生产管理人员考试合格后，考核部门应当在公布考试成绩之日起十个工作日内颁发安全生产知识和管理能力考核合格证明（以下简称考核合格证明）。考核合格证明在全国范围内有效。 煤矿企业主要负责人和安全生产管理人员考试不合格的，可以补考一次；经补考仍不合格的，一年内不得再次申请考核。考核部门应当告知其所在煤矿企业或其任免机关调整其工作岗位。"},{"i":20,"n":"第二十条","txt":"考核部门对煤矿企业主要负责人和安全生产管理人员的安全生产知识和管理能力每三年考核一次。"},{"i":21,"n":"第二十一条","txt":"煤矿特种作业人员及其工种由国家安全生产监督管理总局会同国家煤矿安全监察局确定，并适时调整；其他任何单位或者个人不得擅自变更其范围。"},{"i":22,"n":"第二十二条","txt":"煤矿特种作业人员应当具备初中及以上文化程度（自2018年6月1日起新上岗的煤矿特种作业人员应当具备高中及以上文化程度），具有煤矿相关工作经历，或者职业高中、技工学校及中专以上相关专业学历。"},{"i":23,"n":"第二十三条","txt":"国家煤矿安全监察局组织制定煤矿特种作业人员培训大纲和考核标准，建立统一的考试题库。 省级煤矿安全培训主管部门负责本行政区域内煤矿特种作业人员的考核、发证工作，也可以委托设区的市级人民政府煤矿安全培训主管部门实施煤矿特种作业人员的考核、发证工作。 省级煤矿安全培训主管部门及其委托的设区的市级人民政府煤矿安全培训主管部门以下统称考核发证部门。"},{"i":24,"n":"第二十四条","txt":"煤矿特种作业人员必须经专门的安全技术培训和考核合格，由省级煤矿安全培训主管部门颁发《中华人民共和国特种作业操作证》（以下简称特种作业操作证）后，方可上岗作业。"},{"i":25,"n":"第二十五条","txt":"煤矿特种作业人员在参加资格考试前应当按照规定的培训大纲进行安全生产知识和实际操作能力的专门培训。其中，初次培训的时间不得少于九十学时。 已经取得职业高中、技工学校及中专以上学历的毕业生从事与其所学专业相应的特种作业，持学历证明经考核发证部门审核属实的，免予初次培训，直接参加资格考试。"},{"i":26,"n":"第二十六条","txt":"参加煤矿特种作业操作资格考试的人员，应当填写考试申请表，由本人或其所在煤矿企业持身份证复印件、学历证书复印件或者培训机构出具的培训合格证明向其工作地或者户籍所在地考核发证部门提出申请。 考核发证部门收到申请及其有关材料后，应当在六十日内组织考试。对不符合考试条件的，应当书面告知申请人或其所在煤矿企业。"},{"i":27,"n":"第二十七条","txt":"煤矿特种作业操作资格考试包括安全生产知识考试和实际操作能力考试。安全生产知识考试合格后，进行实际操作能力考试。 煤矿特种作业操作资格考试应当在规定的考点进行，安全生产知识考试应当使用统一的考试题库，使用计算机考试，实际操作能力考试采用国家统一考试标准进行考试。考试满分均为一百分，八十分以上为合格。 考核发证部门应当在考试结束后十个工作日内公布考试成绩。 申请人考试合格的，考核发证部门应当自考试合格之日起二十个工作日内完成发证工作。 申请人考试不合格的，可以补考一次；经补考仍不合格的，重新参加相应的安全技术培训。"},{"i":28,"n":"第二十八条","txt":"特种作业操作证有效期六年，全国范围内有效。 特种作业操作证由国家安全生产监督管理总局统一式样、标准和编号。"},{"i":29,"n":"第二十九条","txt":"特种作业操作证有效期届满需要延期换证的，持证人应当在有效期届满六十日前参加不少于二十四学时的专门培训，持培训合格证明由本人或其所在企业向当地考核发证部门或者原考核发证部门提出考试申请。经安全生产知识和实际操作能力考试合格的，考核发证部门应当在二十个工作日内予以换发新的特种作业操作证。"},{"i":30,"n":"第三十条","txt":"离开特种作业岗位六个月以上、但特种作业操作证仍在有效期内的特种作业人员，需要重新从事原特种作业的，应当重新进行实际操作能力考试，经考试合格后方可上岗作业。"},{"i":31,"n":"第三十一条","txt":"特种作业操作证遗失或者损毁的，应当及时向原考核发证部门提出书面申请，由原考核发证部门补发。 特种作业操作证所记载的信息发生变化的，应当向原考核发证部门提出书面申请，经原考核发证部门审查确认后，予以更新。"},{"i":32,"n":"第三十二条","txt":"煤矿其他从业人员应当具备初中及以上文化程度。 本规定所称煤矿其他从业人员，是指除煤矿主要负责人、安全生产管理人员和特种作业人员以外，从事生产经营活动的其他从业人员，包括煤矿其他负责人、其他管理人员、技术人员和各岗位的工人、使用的被派遣劳动者和临时聘用人员。"},{"i":33,"n":"第三十三条","txt":"煤矿企业应当对其他从业人员进行安全培训，保证其具备必要的安全生产知识、技能和事故应急处理能力，知悉自身在安全生产方面的权利和义务。"},{"i":34,"n":"第三十四条","txt":"省级煤矿安全培训主管部门负责制定煤矿企业其他从业人员安全培训大纲和考核标准。"},{"i":35,"n":"第三十五条","txt":"煤矿企业或者具备安全培训条件的机构应当按照培训大纲对其他从业人员进行安全培训。其中，对从事采煤、掘进、机电、运输、通风、防治水等工作的班组长的安全培训，应当由其所在煤矿的上一级煤矿企业组织实施；没有上一级煤矿企业的，由本单位组织实施。 煤矿企业其他从业人员的初次安全培训时间不得少于七十二学时，每年再培训的时间不得少于二十学时。 煤矿企业或者具备安全培训条件的机构对其他从业人员安全培训合格后，应当颁发安全培训合格证明；未经培训并取得培训合格证明的，不得上岗作业。"},{"i":36,"n":"第三十六条","txt":"煤矿企业新上岗的井下作业人员安全培训合格后，应当在有经验的工人师傅带领下，实习满四个月，并取得工人师傅签名的实习合格证明后，方可独立工作。 工人师傅一般应当具备中级工以上技能等级、三年以上相应工作经历和没有发生过违章指挥、违章作业、违反劳动纪律等条件。"},{"i":37,"n":"第三十七条","txt":"企业井下作业人员调整工作岗位或者离开本岗位一年以上重新上岗前，以及煤矿企业采用新工艺、新技术、新材料或者使用新设备的，应当对其进行相应的安全培训，经培训合格后，方可上岗作业。"},{"i":38,"n":"第三十八条","txt":"省级煤矿安全培训主管部门应当将煤矿企业主要负责人、安全生产管理人员考核合格证明、特种作业人员特种作业操作证的发放、注销等情况在本部门网站上公布，接受社会监督。"},{"i":39,"n":"第三十九条","txt":"煤矿安全培训主管部门和煤矿安全监察机构应当对煤矿企业安全培训的下列情况进行监督检查，发现违法行为的，依法给予行政处罚： （一）建立安全培训管理制度，制定年度培训计划，明确负责安全培训管理工作的机构，配备专职或者兼职安全培训管理人员的情况； （二）按照本规定投入和使用安全培训资金的情况； （三）实行自主培训的煤矿企业的安全培训条件； （四）煤矿企业及其从业人员安全培训档案的情况； （五）主要负责人、安全生产管理人员考核的情况； （六）特种作业人员持证上岗的情况； （七）应用新工艺、新技术、新材料、新设备以及离岗、转岗时对从业人员安全培训的情况； （八）其他从业人员安全培训的情况。"},{"i":40,"n":"第四十条","txt":"考核部门应当建立煤矿企业安全培训随机抽查制度，制定现场抽考办法，加强对煤矿安全培训的监督检查。 考核部门对煤矿企业主要负责人和安全生产管理人员现场抽考不合格的，应当责令其重新参加安全生产知识和管理能力考核；经考核仍不合格的，考核部门应当书面告知其所在煤矿企业或其任免机关调整其工作岗位。"},{"i":41,"n":"第四十一条","txt":"省级及以下煤矿安全监察机构应当按照年度监察执法计划，采用现场抽考等多种方式对煤矿企业安全培训情况实施严格监察；对监察中发现的突出问题和共性问题，应当向本级人民政府煤矿安全培训主管部门或者下级人民政府提出有关安全培训工作的监察建议函。"},{"i":42,"n":"第四十二条","txt":"省级煤矿安全培训主管部门发现下列情形之一的，应当撤销特种作业操作证： （一）特种作业人员对发生生产安全事故负有直接责任的； （二）特种作业操作证记载信息虚假的。 特种作业人员违反上述规定被撤销特种作业操作证的，三年内不得再次申请特种作业操作证。"},{"i":43,"n":"第四十三条","txt":"煤矿企业从业人员在劳动合同期满变更工作单位或者依法解除劳动合同的，原工作单位不得以任何理由扣押其考核合格证明或者特种作业操作证。"},{"i":44,"n":"第四十四条","txt":"省级煤矿安全培训主管部门应当将煤矿企业主要负责人、安全生产管理人员和特种作业人员的考核情况，及时抄送省级煤矿安全监察局。 煤矿安全监察机构应当将煤矿企业主要负责人、安全生产管理人员和特种作业人员的行政处罚决定及时抄送同级煤矿安全培训主管部门。"},{"i":45,"n":"第四十五条","txt":"煤矿安全培训主管部门应当建立煤矿安全培训举报制度，公布举报电话、电子信箱，依法受理并调查处理有关举报，并将查处结果书面反馈给实名举报人。"},{"i":46,"n":"第四十六条","txt":"煤矿安全培训主管部门的工作人员在煤矿安全考核工作中滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"煤矿企业有下列行为之一的，由煤矿安全培训主管部门或者煤矿安全监察机构责令其限期改正，可以处五万元以下的罚款；逾期未改正的，责令停产停业整顿，并处五万元以上十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款： （一）主要负责人和安全生产管理人员未按照规定经考核合格的； （二）未按照规定对从业人员进行安全生产培训的； （三）未如实记录安全生产培训情况的； （四）特种作业人员未经专门的安全培训并取得相应资格，上岗作业的。"},{"i":48,"n":"第四十八条","txt":"煤矿安全培训主管部门或者煤矿安全监察机构发现煤矿企业有下列行为之一的，责令其限期改正，可以处一万元以上三万元以下的罚款： （一）未建立安全培训管理制度或者未制定年度安全培训计划的； （二）未明确负责安全培训工作的机构，或者未配备专兼职安全培训管理人员的； （三）用于安全培训的资金不符合本规定的； （四）未按照统一的培训大纲组织培训的； （五）不具备安全培训条件进行自主培训，或者委托不具备安全培训条件机构进行培训的。 具备安全培训条件的机构未按照规定的培训大纲进行安全培训，或者未经安全培训并考试合格颁发有关培训合格证明的，依照前款规定给予行政处罚。"},{"i":49,"n":"第四十九条","txt":"煤矿企业主要负责人和安全生产管理人员考核不得收费，所需经费由煤矿安全培训主管部门列入同级财政年度预算。 煤矿特种作业人员培训、考试经费可以列入同级财政年度预算，也可由省级煤矿安全培训主管部门制定收费标准，报同级人民政府物价部门、财政部门批准后执行。证书工本费由考核发证机关列入同级财政年度预算。"},{"i":50,"n":"第五十条","txt":"本规定自2018年3月1日起施行。国家安全生产监督管理总局2012年5月28日公布、2013年8月29日修正的《煤矿安全培训规定》（国家安全生产监督管理总局令第52号）同时废止。"}],"meikuanganquanjianchayuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强和规范煤矿安全监察员管理工作，保障煤矿安全监察员依法行政，根据《公务员法》、《安全生产法》、《煤矿安全监察条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"煤矿安全监察机构实行煤矿安全监察员制度。煤矿安全监察员是从事煤矿安全监察和行政执法工作的国家公务员。"},{"i":3,"n":"第三条","txt":"国家安全生产监督管理总局、省级煤矿安全监察局按干部管理权限对煤矿安全监察员实行分级管理。"},{"i":4,"n":"第四条","txt":"煤矿安全监察员除符合国家公务员的条件外，还应当具备下列条件： （一）热爱煤矿安全监察工作，熟悉国家有关煤矿安全的方针、政策、法律、法规、规章、标准、规程； （二）熟悉煤矿安全监察业务，具有煤矿安全方面的专业知识； （三）具有大学专科以上学历； （四）符合国家煤矿安全监察机构规定的工作经历和年龄要求； （五）身体健康，适应煤矿安全监察工作需要。"},{"i":5,"n":"第五条","txt":"煤矿安全监察员由国家安全生产监督管理总局考核，并颁发煤矿安全监察执法证。"},{"i":6,"n":"第六条","txt":"煤矿安全监察员按照法律行政法规规定的职责实施煤矿安全监察，不受任何组织和个人的非法干涉，煤矿及其有关人员不得拒绝、阻挠。"},{"i":7,"n":"第七条","txt":"煤矿安全监察员依法履行下列职责： （一）依照安全生产法、煤矿安全监察条例和其他有关安全生产的法律、法规、规章、标准，对煤矿安全实施监察； （二）对划定区域内的煤矿安全情况实施经常性安全检查和重点检查； （三）查处煤矿安全违法行为，依法作出现场处理决定或提出实施行政处罚的意见； （四）参与煤矿建设项目安全设施设计审查以及对建设单位竣工验收活动和验收结果的监督核查； （五）监督检查煤矿职业危害的防治工作； （六）参加煤矿伤亡事故的应急救援、调查和处理工作； （七）法律、法规规定由煤矿安全监察员履行的其他职责。"},{"i":8,"n":"第八条","txt":"煤矿安全监察员履行安全监察职责，具有下列权力： （一）有权随时进入煤矿作业场所进行检查，调阅有关资料，参加煤矿安全生产会议，向有关单位或者人员了解情况； （二）在检查中发现影响煤矿安全的违法行为，有权当场予以纠正或者要求限期改正； （三）进行现场检查时，发现存在事故隐患的，有权要求煤矿立即消除或者限期解决；发现威胁职工生命安全的紧急情况时，有权要求立即停止作业，下达立即从危险区域内撤出作业人员的命令，并立即将紧急情况和处理措施报告煤矿安全监察机构； （四）发现煤矿作业场所的瓦斯、粉尘或者其他有毒有害气体的浓度超过国家安全标准或者行业安全标准的，煤矿擅自开采保安煤柱的，或者采用危及相邻煤矿生产安全的决水、爆破、贯通巷道等危险方法进行采矿作业的，有权责令立即停止作业，并将有关情况报告煤矿安全监察机构； （五）发现煤矿矿长或者其他主管人员违章指挥工人或者强令工人违章、冒险作业，或者发现工人违"},{"i":9,"n":"第九条","txt":"煤矿安全监察机构应当为煤矿安全监察员提供履行职责所需的装备和劳动防护用品。 煤矿安全监察员下井工作，享受井下工作津贴。"},{"i":10,"n":"第十条","txt":"煤矿安全监察员履行安全监察职责，应当向当事人和有关人员出示煤矿安全监察员证。 煤矿安全监察员证只限本人使用，不得伪造、买卖或转借他人。"},{"i":11,"n":"第十一条","txt":"煤矿安全监察员在执行公务时，涉及本人或者涉及本人有关亲属的利害关系的，应当回避。"},{"i":12,"n":"第十二条","txt":"煤矿安全监察员发现煤矿存在事故隐患或危及煤矿安全的违法行为应当及时处理或者向煤矿安全监察机构报告。 煤矿安全监察员对每次安全检查的时间、地点、内容、发现的问题及其处理情况，应当作详细记录、填写执法文书，并由参加检查的煤矿安全监察员签名后归档。 煤矿安全监察员发出安全监察指令，应当填写执法文书并送达行政相对人。"},{"i":13,"n":"第十三条","txt":"煤矿安全监察员应当依法履行煤矿安全监察职责，保守国家秘密和工作秘密，维护国家利益和当事人的合法权益。"},{"i":14,"n":"第十四条","txt":"煤矿安全监察员不得接受煤矿的任何馈赠、报酬、福利待遇，不得在煤矿报销任何费用，不得参加煤矿安排、组织或者支付费用的宴请、娱乐、旅游、出访等活动，不得借煤矿安全监察工作在煤矿为自己、亲友或者他人谋取利益。"},{"i":15,"n":"第十五条","txt":"煤矿安全监察机构负责制定煤矿安全监察员培训规划和办法，组织实施对煤矿安全监察员的岗前培训、年度轮训、特殊培训。煤矿安全监察员每三年应当接受不少于一个月的脱产培训。"},{"i":16,"n":"第十六条","txt":"煤矿安全监察机构应当建立健全煤矿安全监察员的监督约束制度。 煤矿安全监察机构的行政监察部门依照行政监察法的规定，对煤矿安全监察员履行工作职责实施行政监察。 煤矿安全监察机构应当及时受理任何单位和个人对煤矿安全监察员违法违纪行为的检举和控告。 煤矿安全监察员应当自觉接受有关部门、煤矿及其职工和社会的监督。"},{"i":17,"n":"第十七条","txt":"煤矿安全监察员实行定期交流轮岗制度。"},{"i":18,"n":"第十八条","txt":"煤矿安全监察机构按照管理权限和国家有关规定对煤矿安全监察员的德、能、勤、绩、廉进行日常考核和年度考核。考核结果作为煤矿安全监察员使用和奖惩的依据。"},{"i":19,"n":"第十九条","txt":"煤矿安全监察员有下列表现之一的，由煤矿安全监察机构按照国家有关规定予以奖励： （一）在煤矿安全监察工作中成绩突出，有重大贡献的； （二）在防止或者抢救煤矿事故中，使国家、煤矿和群众利益免受或者减少损失的； （三）在煤矿安全监察工作中依法履行职责，使煤矿安全状况有明显好转的； （四）在煤矿抢险救灾等工作中奋不顾身、作出贡献的； （五）在煤矿安全技术装备开发与推广方面做出显著成绩的； （六）同违法违纪行为作斗争有功绩的； （七）有其他功绩的。"},{"i":20,"n":"第二十条","txt":"煤矿安全监察员有下列行为之一的，由煤矿安全监察机构按国家有关规定给予行政处分；构成犯罪的，依法追究刑事责任。 （一）接受煤矿的馈赠、报酬、礼品、现金、有价证券； （二）参加煤矿安排、组织或者支付费用的宴请、娱乐、旅游、出访等活动的； （三）利用职务便利为本人及亲友谋取私利的； （四）滥施行政处罚或者擅自改变行政处罚决定的； （五）徇私枉法，包庇、纵容违法单位和个人的； （六）对被监察的单位和个人进行刁难或者打击报复的； （七）有其他违法违纪行为的。"},{"i":21,"n":"第二十一条","txt":"煤矿安全监察员滥用职权、玩忽职守、徇私舞弊，有下列行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任。 （一）对不符合法定安全生产条件的煤矿予以批准或验收通过的； （二）发现未依法取得批准、验收的煤矿擅自从事生产活动或者接到举报后不依法予以处理的； （三）对已经取得批准的煤矿不履行安全监察职责，发现其不再具备安全生产条件而不撤销原批准的； （四）发现事故隐患或影响煤矿安全的违法行为不依法及时处理或报告的。"},{"i":22,"n":"第二十二条","txt":"本办法自2003年8月1日起施行。2000年12月9日国家煤矿安全监察局发布的《煤矿安全监察员管理暂行办法》同时废止。"}],"meikuanganquanjianchafakuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范煤矿安全监察罚款管理工作，依法实施煤矿安全监察，根据安全生产法、煤矿安全监察条例、罚款决定与罚款收缴分离实施办法和财政部关于做好煤矿安全监察罚没收入管理工作的通知（以下简称财政部《通知》）等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"煤矿安全监察机构依照安全生产法、煤矿安全监察条例和安全生产违法行为处罚办法、煤矿安全监察行政处罚办法等有关法律、法规和规章的规定，对煤矿安全违法行为依法实施罚款，适用本办法。"},{"i":3,"n":"第三条","txt":"省级煤矿安全监察机构按照财政部《通知》的规定，统一到省级财政部门和相关部门办理煤矿安全监察罚款许可证。"},{"i":4,"n":"第四条","txt":"省级煤矿安全监察机构商财政部驻各地财政监察专员办事处、省财政厅后，可与一至二个国有商业银行签订煤矿安全监察罚款代收代缴协议，并将代收代缴协议报国家煤矿安全监察局和财政部驻各地财政监察专员办事处备案。 罚款代收银行的确定以及会计科目的使用应严格按照财政部《罚款代收代缴管理办法》的规定办理。代收银行的代收手续费按照财政部、中国人民银行关于代收罚款手续费有关问题的通知规定执行。"},{"i":5,"n":"第五条","txt":"罚款票据使用财政部门统一印制的代收罚款收据，并由代收银行负责管理。 煤矿安全监察机构可领取小额当场罚款票据，并负责管理。当场罚款票据的使用，应当符合当场处罚罚款票据管理暂行规定。"},{"i":6,"n":"第六条","txt":"煤矿安全监察罚款收入纳入中央预算，实行“收支两条线”管理。 煤矿安全监察罚款的缴库由代收银行按照财政部有关规定办理。"},{"i":7,"n":"第七条","txt":"煤矿安全监察罚款按照财政部《通知》的要求，由银行内部交款单分列，并直接缴入中央和地方金库。"},{"i":8,"n":"第八条","txt":"煤矿安全罚款实行处罚决定与罚款收缴分离。 煤矿安全监察机构依法对有关煤矿安全违法行为实施罚款，制作煤矿安全监察行政处罚决定书；被处罚人持煤矿安全监察行政处罚决定书到指定的代收银行及其分支机构缴纳罚款。 煤矿安全监察机构财务人员定期到代收银行索取缴款票据，并进行核对、登记和统计。"},{"i":9,"n":"第九条","txt":"各煤矿安全监察办事处每月终了后5日内将煤矿安全监察罚款统计表报省级煤矿安全监察机构。 省级煤矿安全监察机构将本省区煤矿安全监察罚款统计表汇总后，在每月终了后8日内报国家煤矿安全监察局。"},{"i":10,"n":"第十条","txt":"煤矿安全监察机构罚款收入的缴库情况，应接受财政部驻各地财政监察专员办事处的检查和监督。"},{"i":11,"n":"第十一条","txt":"煤矿安全监察罚款应严格执行国家有关罚款收支管理的有关规定，对违反“收支两条线”管理的机构和个人，依照国务院违反行政事业性收费和罚没款收入收支两条线管理规定行政处分暂行规定追究责任。"},{"i":12,"n":"第十二条","txt":"本办法自2003年8月1日起施行。国家煤矿安全监察局发布的《煤矿安全监察罚款管理暂行办法》同时废止。"}],"meikuanganquanjianchaxingzhengchufabanfa":[{"i":1,"n":"第一条","txt":"为了制裁煤矿安全违法行为，规范煤矿安全监察行政处罚工作，保障煤矿依法进行生产，根据煤矿安全监察条例及其他有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家煤矿安全监察局、省级煤矿安全监察局和煤矿安全监察分局（以下简称煤矿安全监察机构），对煤矿及其有关人员违反有关安全生产的法律、行政法规、部门规章、国家标准、行业标准和规程的行为（以下简称煤矿安全违法行为）实施行政处罚，适用本办法。本办法未作规定的，适用安全生产违法行为行政处罚办法。 有关法律、行政法规对行政处罚另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"省级煤矿安全监察局、煤矿安全监察分局实施行政处罚按照属地原则进行管辖。 国家煤矿安全监察局认为应由其实施行政处罚的，由国家煤矿安全监察局管辖。 两个以上煤矿安全监察机构因行政处罚管辖权发生争议的，由其共同的上一级煤矿安全监察机构指定管辖。"},{"i":4,"n":"第四条","txt":"当事人对煤矿安全监察机构所给予的行政处罚，享有陈述、申辩权；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。 当事人因煤矿安全监察机构违法给予行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":5,"n":"第五条","txt":"煤矿安全监察员执行公务时，应当出示煤矿安全监察执法证件。"},{"i":6,"n":"第六条","txt":"煤矿安全监察机构及其煤矿安全监察员对检查中发现的煤矿安全违法行为，可以作出下列现场处理决定： （一）当场予以纠正或者要求限期改正； （二）责令限期达到要求； （三）责令立即停止作业（施工）或者立即停止使用； 经现场处理决定后拒不改正，或者依法应当给予行政处罚的煤矿安全违法行为，依法作出行政处罚决定。"},{"i":7,"n":"第七条","txt":"煤矿或者施工单位有下列行为之一的，责令停止建设或者停产停业整顿，限期改正；逾期未改正的，处50万元以上100万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未按照规定对煤矿建设项目进行安全评价的； （二）煤矿建设项目没有安全设施设计或者安全设施设计未按照规定报经有关部门审查同意的； （三）煤矿建设项目的施工单位未按照批准的安全设施设计施工的； （四）煤矿建设项目竣工投入生产或者使用前，安全设施未经验收合格的。"},{"i":8,"n":"第八条","txt":"煤矿矿井通风、防火、防水、防瓦斯、防毒、防尘等安全设施不符合法定要求的，责令限期达到要求；逾期仍达不到要求的，责令停产整顿。"},{"i":9,"n":"第九条","txt":"煤矿作业场所有下列情形之一的，责令限期改正；逾期不改正的，责令停产整顿，并处3万元以下的罚款： （一）未使用专用防爆电器设备的； （二）未使用专用放炮器的； （三）未使用人员专用升降容器的； （四）使用明火明电照明的。"},{"i":10,"n":"第十条","txt":"煤矿未依法提取或者使用煤矿安全技术措施专项费用的，责令限期改正，提供必需的资金；逾期不改正的，处5万元以下的罚款，责令停产整顿。 有前款违法行为，导致发生生产安全事故的，对煤矿主要负责人给予撤职处分，对个人经营的投资人处2万元以上20万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":11,"n":"第十一条","txt":"煤矿使用不符合国家安全标准或者行业安全标准的设备、器材、仪器、仪表、防护用品的，责令限期改正或者责令立即停止使用；逾期不改正或者不立即停止使用的，处5万元以下的罚款；情节严重的，责令停产整顿。"},{"i":12,"n":"第十二条","txt":"煤矿企业的机电设备、安全仪器，未按照下列规定操作、检查、维修和建立档案的，责令改正，可以并处2万元以下的罚款： （一）未定期对机电设备及其防护装置、安全检测仪器检查、维修和建立技术档案的； （二）非负责设备运行人员操作设备的； （三）非值班电气人员进行电气作业的； （四）操作电气设备的人员，没有可靠的绝缘保护和检修电气设备带电作业的。"},{"i":13,"n":"第十三条","txt":"煤矿井下采掘作业，未按照作业规程的规定管理顶帮；通过地质破碎带或者其他顶帮破碎地点时，未加强支护；露天采剥作业，未按照设计规定，控制采剥工作面的阶段高度、宽度、边坡角和最终边坡角；采剥作业和排土作业，对深部或者邻近井巷造成危害的，责令改正，可以并处2万元以下的罚款。"},{"i":14,"n":"第十四条","txt":"煤矿未严格执行瓦斯检查制度，入井人员携带烟草和点火用具下井的，责令改正，可以并处2万元以下的罚款。"},{"i":15,"n":"第十五条","txt":"煤矿在有瓦斯突出、冲击地压条件下从事采掘作业；在未加保护的建筑物、构筑物和铁路、水体下面开采；在地温异常或者热水涌出的地区开采，未编制专门设计文件和报主管部门批准的，责令改正，可以并处2万元以下的罚款。"},{"i":16,"n":"第十六条","txt":"煤矿作业场所的瓦斯、粉尘或者其他有毒有害气体的浓度超过国家安全标准或者行业安全标准的，责令立即停止作业；拒不停止作业的，责令停产整顿，可以并处10万元以下的罚款。"},{"i":17,"n":"第十七条","txt":"有自然发火可能性的矿井，未按规定采取有效的预防自然发火措施的，责令改正，可以并处2万元以下的罚款。"},{"i":18,"n":"第十八条","txt":"煤矿在有可能发生突水危险的地区从事采掘作业，未采取探放水措施的，责令改正，可以并处2万元以下的罚款。"},{"i":19,"n":"第十九条","txt":"煤矿井下风量、风质、风速和作业环境的气候，不符合煤矿安全规程的规定的，责令改正，可以并处2万元以下的罚款。"},{"i":20,"n":"第二十条","txt":"煤矿对产生粉尘的作业场所，未采取综合防尘措施，或者未按规定对粉尘进行检测的，责令改正，可以并处2万元以下的罚款。"},{"i":21,"n":"第二十一条","txt":"擅自开采保安煤柱，或者采用危及相邻煤矿生产安全的决水、爆破、贯通巷道等危险方法进行采矿作业，责令立即停止作业；拒不停止作业的，由煤矿安全监察机构决定吊销安全生产许可证，并移送地质矿产主管部门依法吊销采矿许可证。"},{"i":22,"n":"第二十二条","txt":"煤矿违反有关安全生产法律、行政法规的规定，拒绝、阻碍煤矿安全监察机构依法实施监督检查的，责令改正；拒不改正的，处2万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。 煤矿提供虚假情况，或者隐瞒存在的事故隐患以及其他安全问题的，由煤矿安全监察机构给予警告，可以并处5万元以上10万元以下的罚款；情节严重的，责令停产整顿。"},{"i":23,"n":"第二十三条","txt":"煤矿发生事故，对煤矿、煤矿主要负责人以及其他有关责任单位、人员依照《安全生产法》及有关法律、行政法规的规定予以行政处罚；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"经停产整顿仍不具备法定安全生产条件给予关闭的行政处罚，由煤矿安全监察机构报请县级以上人民政府按照国务院规定的权限决定。"},{"i":25,"n":"第二十五条","txt":"煤矿安全监察机构及其煤矿安全监察员实施行政处罚时，应当符合《安全生产违法行为行政处罚办法》规定的程序并使用统一的煤矿安全监察行政执法文书。"},{"i":26,"n":"第二十六条","txt":"未设立省级煤矿安全监察局的省、自治区，由省、自治区人民政府指定的负责煤矿安全监察工作的部门依照本办法的规定对本行政区域内的煤矿安全违法行为实施行政处罚。"},{"i":27,"n":"第二十七条","txt":"本办法自2003年8月15日起施行。《煤矿安全监察行政处罚暂行办法》同时废止。"}],"meikuanganquanguicheng":[],"meikuangjianshexiangmuanquansheshijianchaguiding":[{"i":1,"n":"第一条","txt":"为了规范煤矿建设工程安全设施监察工作，保障煤矿安全生产，根据安全生产法、煤矿安全监察条例以及有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"煤矿安全监察机构对煤矿新建、改建和扩建工程项目（以下简称煤矿建设项目）的安全设施进行监察，适用本规定。"},{"i":3,"n":"第三条","txt":"煤矿建设项目应当进行安全评价，其初步设计应当按规定编制安全专篇。安全专篇应当包括安全条件的论证、安全设施的设计等内容。"},{"i":4,"n":"第四条","txt":"煤矿建设项目的安全设施的设计、施工应当符合工程建设强制性标准、煤矿安全规程和行业技术规范。"},{"i":5,"n":"第五条","txt":"煤矿建设项目施工前，其安全设施设计应当经煤矿安全监察机构审查同意；竣工投入生产或使用前，其安全设施和安全条件应当经煤矿建设单位验收合格。煤矿安全监察机构应当加强对建设单位验收活动和验收结果的监督核查。"},{"i":6,"n":"第六条","txt":"煤矿建设项目安全设施的设计审查，由煤矿安全监察机构按照设计或者新增的生产能力，实行分级负责。 （一）设计或者新增的生产能力在300万吨/年及以上的井工煤矿建设项目和1000万吨/年及以上的露天煤矿建设项目，由国家煤矿安全监察局负责设计审查。 （二）设计或者新增的生产能力在300万吨/年以下的井工煤矿建设项目和1000万吨/年以下的露天煤矿建设项目，由省级煤矿安全监察局负责设计审查。”"},{"i":7,"n":"第七条","txt":"未设立煤矿安全监察机构的省、自治区，由省、自治区人民政府指定的负责煤矿安全监察工作的部门负责本规定第六条第二项规定的设计审查。"},{"i":8,"n":"第八条","txt":"经省级煤矿安全监察局审查同意的项目，应及时报国家煤矿安全监察局备案。"},{"i":9,"n":"第九条","txt":"煤矿建设项目的安全评价包括安全预评价和安全验收评价。 煤矿建设项目在可行性研究阶段，应当进行安全预评价；在投入生产或者使用前，应当进行安全验收评价。"},{"i":10,"n":"第十条","txt":"煤矿建设项目的安全评价应由具有国家规定资质的安全中介机构承担。承担煤矿建设项目安全评价的安全中介机构对其作出的安全评价结果负责。"},{"i":11,"n":"第十一条","txt":"煤矿企业应与承担煤矿建设项目安全评价的安全中介机构签订书面委托合同，明确双方各自的权利和义务。"},{"i":12,"n":"第十二条","txt":"承担煤矿建设项目安全评价的安全中介机构，应当按照规定的标准和程序进行评价，提出评价报告。"},{"i":13,"n":"第十三条","txt":"煤矿建设项目安全预评价报告应当包括以下内容： （一）主要危险、有害因素和危害程度以及对公共安全影响的定性、定量评价； （二）预防和控制的可能性评价； （三）建设项目可能造成职业危害的评价； （四）安全对策措施、安全设施设计原则； （五）预评价结论； （六）其他需要说明的事项。"},{"i":14,"n":"第十四条","txt":"煤矿建设项目安全验收评价报告应当包括以下内容： （一）安全设施符合法律、法规、标准和规程规定以及设计文件的评价； （二）安全设施在生产或使用中的有效性评价； （三）职业危害防治措施的有效性评价； （四）建设项目的整体安全性评价； （五）存在的安全问题和解决问题的建议； （六）验收评价结论； （七）有关试运转期间的技术资料、现场检测、检验数据和统计分析资料； （八）其他需要说明的事项。"},{"i":15,"n":"第十五条","txt":"煤矿建设项目的安全设施设计应经煤矿安全监察机构审查同意；未经审查同意的，不得施工。"},{"i":16,"n":"第十六条","txt":"煤矿建设项目的安全设施设计，应由具有相应资质的设计单位承担。设计单位对安全设施设计负责。"},{"i":17,"n":"第十七条","txt":"煤矿建设项目的安全设施设计应当包括煤矿水、火、瓦斯、煤尘、顶板等主要灾害的防治措施，所确定的设施、设备、器材等应当符合国家标准和行业标准。"},{"i":18,"n":"第十八条","txt":"煤矿建设项目的安全设施设计审查前，煤矿企业应当按照本规定第六条的规定，向煤矿安全监察机构提出书面申请。"},{"i":19,"n":"第十九条","txt":"申请煤矿建设项目的安全设施设计审查，应当提交下列资料： （一）安全设施设计审查申请报告及申请表； （二）建设项目审批、核准或者备案的文件； （三）采矿许可证或者矿区范围批准文件； （四）安全预评价报告书； （五）初步设计及安全专篇； （六）其他需要说明的材料。"},{"i":20,"n":"第二十条","txt":"煤矿安全监察机构接到审查申请后，应当对上报资料进行审查。有下列情形之一的，为设计审查不合格： （一）安全设施设计未由具备相应资质的设计单位承担的； （二）煤矿水、火、瓦斯、煤尘、顶板等主要灾害防治措施不符合规定的； （三）安全设施设计不符合工程建设强制性标准、煤矿安全规程和行业技术规范的； （四）所确定的设施、设备、器材不符合国家标准和行业标准的； （五）不符合国家煤矿安全监察局规定的其他条件的。"},{"i":21,"n":"第二十一条","txt":"煤矿安全监察机构审查煤矿建设项目的安全设施设计，应当自收到审查申请起30日内审查完毕。经审查同意的，应当以文件形式批复；不同意的，应当提出审查意见，并以书面形式答复。"},{"i":22,"n":"第二十二条","txt":"煤矿企业对已批准的煤矿建设项目安全设施设计需作重大变更的，应经原审查机构审查同意。"},{"i":23,"n":"第二十三条","txt":"煤矿建设项目的安全设施应由具有相应资质的施工单位承担。 施工单位应当按照批准的安全设施设计施工，并对安全设施的工程质量负责。"},{"i":24,"n":"第二十四条","txt":"施工单位在施工期间，发现煤矿建设项目的安全设施设计不合理或者存在重大事故隐患时，应当立即停止施工，并报告煤矿企业。煤矿企业需对安全设施设计作重大变更的，应当按照本规定第二十二条的规定重新审查。"},{"i":25,"n":"第二十五条","txt":"煤矿安全监察机构对煤矿建设工程安全设施的施工情况进行监察。"},{"i":26,"n":"第二十六条","txt":"煤矿建设项目在竣工完成后，应当在正式投入生产或使用前进行联合试运转。联合试运转的时间一般为1至6个月，有特殊情况需要延长的，总时长不得超过12个月。 煤矿建设项目联合试运转，应按规定经有关主管部门批准。"},{"i":27,"n":"第二十七条","txt":"煤矿建设项目联合试运转期间，煤矿企业应当制定可靠的安全措施，做好现场检测、检验，收集有关数据，并编制联合试运转报告。"},{"i":28,"n":"第二十八条","txt":"煤矿建设项目联合试运转正常后，应当进行安全验收评价。"},{"i":29,"n":"第二十九条","txt":"煤矿建设项目的安全设施和安全条件验收应当由煤矿建设单位负责组织；未经验收合格的，不得投入生产和使用。 煤矿建设单位实行多级管理的，应当由具体负责建设项目施工建设单位的上一级具有法人资格的公司（单位）负责组织验收。"},{"i":30,"n":"第三十条","txt":"煤矿建设单位或者其上一级具有法人资格的公司（单位）组织验收时，应当对有关资料进行审查并组织现场验收。有下列情形之一的，为验收不合格： （一）安全设施和安全条件不符合设计要求，或未通过工程质量认证的； （二）安全设施和安全条件不能满足正常生产和使用的； （三）未按规定建立安全生产管理机构和配备安全生产管理人员的； （四）矿长和特种作业人员不具备相应资格的； （五）不符合国家煤矿安全监察局规定的其他条件的。"},{"i":31,"n":"第三十一条","txt":"违反本规定的，由煤矿安全监察机构或者省、自治区人民政府指定的负责煤矿安全监察工作的部门依照《安全生产法》及有关法律、行政法规的规定予以行政处罚；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"煤矿建设项目的安全设施设计审查申请表的样式，由国家煤矿安全监察局制定。"},{"i":33,"n":"第三十三条","txt":"本规定自2003年8月15日起施行。《煤矿建设工程安全设施设计审查与竣工验收暂行办法》同时废止。"}],"meikuangzhongdashiguyinhuanpandingbiaozhun":[{"i":1,"n":"第一条","txt":"为了准确认定、及时消除煤矿重大事故隐患，根据《中华人民共和国安全生产法》和《国务院关于预防煤矿生产安全事故的特别规定》（国务院令第446号）等法律、行政法规，制定本标准。"},{"i":2,"n":"第二条","txt":"本标准适用于判定各类煤矿重大事故隐患。"},{"i":3,"n":"第三条","txt":"煤矿重大事故隐患包括下列15个方面： （一）超能力、超强度或者超定员组织生产； （二）瓦斯超限作业； （三）煤与瓦斯突出矿井，未依照规定实施防突出措施； （四）高瓦斯矿井未建立瓦斯抽采系统和监控系统，或者系统不能正常运行； （五）通风系统不完善、不可靠； （六）有严重水患，未采取有效措施； （七）超层越界开采； （八）有冲击地压危险，未采取有效措施； （九）自然发火严重，未采取有效措施； （十）使用明令禁止使用或者淘汰的设备、工艺； （十一）煤矿没有双回路供电系统； （十二）新建煤矿边建设边生产，煤矿改扩建期间，在改扩建的区域生产，或者在其他区域的生产超出安全设施设计规定的范围和规模； （十三）煤矿实行整体承包生产经营后，未重新取得或者及时变更安全生产许可证而从事生产，或者承包方再次转包，以及将井下采掘工作面和井巷维修作业进行劳务承包； （十四）煤矿改制期间，未明确安全生产责任人和安全"},{"i":4,"n":"第四条","txt":"“超能力、超强度或者超定员组织生产”重大事故隐患，是指有下列情形之一的： （一）煤矿全年原煤产量超过核定（设计）生产能力幅度在10%以上，或者月原煤产量大于核定（设计）生产能力的10%的； （二）煤矿或其上级公司超过煤矿核定（设计）生产能力下达生产计划或者经营指标的； （三）煤矿开拓、准备、回采煤量可采期小于国家规定的最短时间，未主动采取限产或者停产措施，仍然组织生产的（衰老煤矿和地方人民政府计划停产关闭煤矿除外）； （四） 煤矿井下同时生产的水平超过2个，或者一个采（盘）区内同时作业的采煤、煤（半煤岩）巷掘进工作面个数超过《煤矿安全规程》规定的； （五）瓦斯抽采不达标组织生产的； （六）煤矿未制定或者未严格执行井下劳动定员制度，或者采掘作业地点单班作业人数超过国家有关限员规定20%以上的。"},{"i":5,"n":"第五条","txt":"“瓦斯超限作业”重大事故隐患，是指有下列情形之一的： （一）瓦斯检查存在漏检、假检情况且进行作业的； （二）井下瓦斯超限后继续作业或者未按照国家规定处置继续进行作业的； （三）井下排放积聚瓦斯未按照国家规定制定并实施安全技术措施进行作业的。"},{"i":6,"n":"第六条","txt":"“煤与瓦斯突出矿井，未依照规定实施防突出措施”重大事故隐患，是指有下列情形之一的： （一）未设立防突机构并配备相应专业人员的； （二）未建立地面永久瓦斯抽采系统或者系统不能正常运行的； （三）未按照国家规定进行区域或者工作面突出危险性预测的（直接认定为突出危险区域或者突出危险工作面的除外）； （四）未按照国家规定采取防治突出措施的； （五）未按照国家规定进行防突措施效果检验和验证，或者防突措施效果检验和验证不达标仍然组织生产建设，或者防突措施效果检验和验证数据造假的； （六）未按照国家规定采取安全防护措施的； （七）使用架线式电机车的。"},{"i":7,"n":"第七条","txt":"“高瓦斯矿井未建立瓦斯抽采系统和监控系统，或者系统不能正常运行”重大事故隐患，是指有下列情形之一的： （一）按照《煤矿安全规程》规定应当建立而未建立瓦斯抽采系统或者系统不正常使用的； （二）未按照国家规定安设、调校甲烷传感器，人为造成甲烷传感器失效，或者瓦斯超限后不能报警、断电或者断电范围不符合国家规定的。"},{"i":8,"n":"第八条","txt":"“通风系统不完善、不可靠”重大事故隐患，是指有下列情形之一的： （一）矿井总风量不足或者采掘工作面等主要用风地点风量不足的； （二）没有备用主要通风机，或者两台主要通风机不具有同等能力的； （三）违反《煤矿安全规程》规定采用串联通风的； （四）未按照设计形成通风系统，或者生产水平和采（盘）区未实现分区通风的； （五）高瓦斯、煤与瓦斯突出矿井的任一采（盘）区，开采容易自燃煤层、低瓦斯矿井开采煤层群和分层开采采用联合布置的采（盘）区，未设置专用回风巷，或者突出煤层工作面没有独立的回风系统的； （六）进、回风井之间和主要进、回风巷之间联络巷中的风墙、风门不符合《煤矿安全规程》规定，造成风流短路的； （七）采区进、回风巷未贯穿整个采区，或者虽贯穿整个采区但一段进风、一段回风，或者采用倾斜长壁布置，大巷未超前至少2个区段构成通风系统即开掘其他巷道的； （八）煤巷、半煤岩巷和有瓦斯涌出的岩巷掘进未"},{"i":9,"n":"第九条","txt":"“有严重水患，未采取有效措施”重大事故隐患，是指有下列情形之一的： （一）未查明矿井水文地质条件和井田范围内采空区、废弃老窑积水等情况而组织生产建设的； （二）水文地质类型复杂、极复杂的矿井未设置专门的防治水机构、未配备专门的探放水作业队伍，或者未配齐专用探放水设备的； （三）在需要探放水的区域进行采掘作业未按照国家规定进行探放水的； （四）未按照国家规定留设或者擅自开采（破坏）各种防隔水煤（岩）柱的； （五）有突（透、溃）水征兆未撤出井下所有受水患威胁地点人员的； （六）受地表水倒灌威胁的矿井在强降雨天气或其来水上游发生洪水期间未实施停产撤人的； （七）建设矿井进入三期工程前，未按照设计建成永久排水系统，或者生产矿井延深到设计水平时，未建成防、排水系统而违规开拓掘进的； （八）矿井主要排水系统水泵排水能力、管路和水仓容量不符合《煤矿安全规程》规定的； （九）开采地表水体、老空水淹区域"},{"i":10,"n":"第十条","txt":"“超层越界开采”重大事故隐患，是指有下列情形之一的： （一）超出采矿许可证载明的开采煤层层位或者标高进行开采的； （二）超出采矿许可证载明的坐标控制范围进行开采的； （三）擅自开采（破坏）安全煤柱的。"},{"i":11,"n":"第十一条","txt":"“有冲击地压危险，未采取有效措施”重大事故隐患，是指有下列情形之一的： （一）未按照国家规定进行煤层（岩层）冲击倾向性鉴定，或者开采有冲击倾向性煤层未进行冲击危险性评价，或者开采冲击地压煤层，未进行采区、采掘工作面冲击危险性评价的； （二）有冲击地压危险的矿井未设置专门的防冲机构、未配备专业人员或者未编制专门设计的； （三）未进行冲击地压危险性预测，或者未进行防冲措施效果检验以及防冲措施效果检验不达标仍组织生产建设的； （四）开采冲击地压煤层时，违规开采孤岛煤柱，采掘工作面位置、间距不符合国家规定，或者开采顺序不合理、采掘速度不符合国家规定、违反国家规定布置巷道或者留设煤（岩）柱造成应力集中的； （五）未制定或者未严格执行冲击地压危险区域人员准入制度的。"},{"i":12,"n":"第十二条","txt":"“自然发火严重，未采取有效措施”重大事故隐患，是指有下列情形之一的： （一）开采容易自燃和自燃煤层的矿井，未编制防灭火专项设计或者未采取综合防灭火措施的； （二）高瓦斯矿井采用放顶煤采煤法不能有效防治煤层自然发火的； （三）有自然发火征兆没有采取相应的安全防范措施继续生产建设的； （四）违反《煤矿安全规程》规定启封火区的。"},{"i":13,"n":"第十三条","txt":"“使用明令禁止使用或者淘汰的设备、工艺”重大事故隐患，是指有下列情形之一的： （一）使用被列入国家禁止井工煤矿使用的设备及工艺目录的产品或者工艺的； （二）井下电气设备、电缆未取得煤矿矿用产品安全标志的； （三）井下电气设备选型与矿井瓦斯等级不符，或者采（盘）区内防爆型电气设备存在失爆，或者井下使用非防爆无轨胶轮车的； （四）未按照矿井瓦斯等级选用相应的煤矿许用炸药和雷管、未使用专用发爆器，或者裸露爆破的； （五）采煤工作面不能保证2个畅通的安全出口的； （六）高瓦斯矿井、煤与瓦斯突出矿井、开采容易自燃和自燃煤层（薄煤层除外）矿井，采煤工作面采用前进式采煤方法的。"},{"i":14,"n":"第十四条","txt":"“煤矿没有双回路供电系统”重大事故隐患，是指有下列情形之一的： （一）单回路供电的； （二）有两回路电源线路但取自一个区域变电所同一母线段的； （三）进入二期工程的高瓦斯、煤与瓦斯突出、水文地质类型为复杂和极复杂的建设矿井，以及进入三期工程的其他建设矿井，未形成两回路供电的。"},{"i":15,"n":"第十五条","txt":"“新建煤矿边建设边生产，煤矿改扩建期间，在改扩建的区域生产，或者在其他区域的生产超出安全设施设计规定的范围和规模”重大事故隐患，是指有下列情形之一的： （一）建设项目安全设施设计未经审查批准，或者审查批准后作出重大变更未经再次审查批准擅自组织施工的； （二）新建煤矿在建设期间组织采煤的（经批准的联合试运转除外）； （三）改扩建矿井在改扩建区域生产的； （四）改扩建矿井在非改扩建区域超出设计规定范围和规模生产的。"},{"i":16,"n":"第十六条","txt":"“煤矿实行整体承包生产经营后，未重新取得或者及时变更安全生产许可证而从事生产，或者承包方再次转包，以及将井下采掘工作面和井巷维修作业进行劳务承包”重大事故隐患，是指有下列情形之一的： （一）煤矿未采取整体承包形式进行发包，或者将煤矿整体发包给不具有法人资格或者未取得合法有效营业执照的单位或者个人的； （二）实行整体承包的煤矿，未签订安全生产管理协议，或者未按照国家规定约定双方安全生产管理职责而进行生产的； （三）实行整体承包的煤矿，未重新取得或者变更安全生产许可证进行生产的； （四）实行整体承包的煤矿，承包方再次将煤矿转包给其他单位或者个人的； （五）井工煤矿将井下采掘作业或者井巷维修作业（井筒及井下新水平延深的井底车场、主运输、主通风、主排水、主要机电硐室开拓工程除外）作为独立工程发包给其他企业或者个人的，以及转包井下新水平延深开拓工程的。"},{"i":17,"n":"第十七条","txt":"“煤矿改制期间，未明确安全生产责任人和安全管理机构，或者在完成改制后，未重新取得或者变更采矿许可证、安全生产许可证和营业执照”重大事故隐患，是指有下列情形之一的： （一）改制期间，未明确安全生产责任人进行生产建设的； （二）改制期间，未健全安全生产管理机构和配备安全管理人员进行生产建设的； （三）完成改制后，未重新取得或者变更采矿许可证、安全生产许可证、营业执照而进行生产建设的。"},{"i":18,"n":"第十八条","txt":"“其他重大事故隐患”，是指有下列情形之一的： （一）未分别配备专职的矿长、总工程师和分管安全、生产、机电的副矿长，以及负责采煤、掘进、机电运输、通风、地测、防治水工作的专业技术人员的； （二）未按照国家规定足额提取或者未按照国家规定范围使用安全生产费用的； （三）未按照国家规定进行瓦斯等级鉴定，或者瓦斯等级鉴定弄虚作假的； （四）出现瓦斯动力现象，或者相邻矿井开采的同一煤层发生了突出事故，或者被鉴定、认定为突出煤层，以及煤层瓦斯压力达到或者超过0.74MPa的非突出矿井，未立即按照突出煤层管理并在国家规定期限内进行突出危险性鉴定的（直接认定为突出矿井的除外）； （五）图纸作假、隐瞒采掘工作面，提供虚假信息、隐瞒下井人数，或者矿长、总工程师（技术负责人）履行安全生产岗位责任制及管理制度时伪造记录，弄虚作假的； （六）矿井未安装安全监控系统、人员位置监测系统或者系统不能正常运行，以及对系统"},{"i":19,"n":"第十九条","txt":"本标准所称的国家规定，是指有关法律、行政法规、部门规章、国家标准、行业标准，以及国务院及其应急管理部门、国家矿山安全监察机构依法制定的行政规范性文件。"},{"i":20,"n":"第二十条","txt":"本标准自2021年1月1日起施行。原国家安全生产监督管理总局2015年12月3日公布的《煤矿重大生产安全事故隐患判定标准》（国家安全生产监督管理总局令第85号）同时废止。"}],"meikuanglingdaodaibanxiajingjianquanjiandujianchag5fe200":[{"i":1,"n":"第一条","txt":"为落实煤矿领导带班下井制度，根据《国务院关于进一步加强企业安全生产工作的通知》（国发〔2010〕23号）和有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"煤矿领导带班下井和县级以上地方人民政府煤炭行业管理部门、煤矿安全生产监督管理部门（以下分别简称为煤炭行业管理部门、煤矿安全监管部门），以及煤矿安全监察机构对其实施监督检查，适用本规定。"},{"i":3,"n":"第三条","txt":"煤炭行业管理部门是落实煤矿领导带班下井制度的主管部门，负责督促煤矿抓好有关制度的建设和落实。 煤矿安全监管部门对煤矿领导带班下井进行日常性的监督检查，对煤矿违反带班下井制度的行为依法作出现场处理或者实施行政处罚。 煤矿安全监察机构对煤矿领导带班下井实施国家监察，对煤矿违反带班下井制度的行为依法作出现场处理或者实施行政处罚。"},{"i":4,"n":"第四条","txt":"本规定所称的煤矿，是指煤矿生产矿井和新建、改建、扩建、技术改造、资源整合重组等建设矿井及其施工单位。 本规定所称煤矿领导，是指煤矿的主要负责人、领导班子成员和副总工程师。 建设矿井的领导，是指煤矿建设单位和从事煤矿建设的施工单位的主要负责人、领导班子成员和副总工程师。"},{"i":5,"n":"第五条","txt":"煤矿是落实领导带班下井制度的责任主体，每班必须有矿领导带班下井，并与工人同时下井、同时升井。 煤矿的主要负责人对落实领导带班下井制度全面负责。 煤矿集团公司应当加强对所属煤矿领导带班下井的情况实施监督检查。"},{"i":6,"n":"第六条","txt":"任何单位和个人对煤矿领导未按照规定带班下井或者弄虚作假的，均有权向煤炭行业管理部门、煤矿安全监管部门、煤矿安全监察机构举报和报告。"},{"i":7,"n":"第七条","txt":"煤矿应当建立健全领导带班下井制度，并严格考核。带班下井制度应当明确带班下井人员、每月带班下井的个数、在井下工作时间、带班下井的任务、职责权限、群众监督和考核奖惩等内容。 煤矿的主要负责人每月带班下井不得少于5个。 煤矿领导带班下井时，其领导姓名应当在井口明显位置公示。煤矿领导每月带班下井工作计划的完成情况，应当在煤矿公示栏公示，接受群众监督。"},{"i":8,"n":"第八条","txt":"煤矿领导带班下井制度应当按照煤矿的隶属关系报送所在地煤炭行业管理部门，同时抄送煤矿安全监管部门和驻地煤矿安全监察机构。"},{"i":9,"n":"第九条","txt":"煤矿领导带班下井时，应当履行下列职责： （一）加强对采煤、掘进、通风等重点部位、关键环节的检查巡视，全面掌握当班井下的安全生产状况； （二）及时发现和组织消除事故隐患和险情，及时制止违章违纪行为，严禁违章指挥，严禁超能力组织生产； （三）遇到险情时，立即下达停产撤人命令，组织涉险区域人员及时、有序撤离到安全地点。"},{"i":10,"n":"第十条","txt":"煤矿领导带班下井实行井下交接班制度。 上一班的带班领导应当在井下向接班的领导详细说明井下安全状况、存在的问题及原因、需要注意的事项等，并认真填写交接班记录簿。"},{"i":11,"n":"第十一条","txt":"煤矿应当建立领导带班下井档案管理制度。 煤矿领导升井后，应当及时将下井的时间、地点、经过路线、发现的问题及处理情况、意见等有关情况进行登记，并由专人负责整理和存档备查。 煤矿领导带班下井的相关记录和煤矿井下人员定位系统存储信息保存期不少于一年。"},{"i":12,"n":"第十二条","txt":"煤矿没有领导带班下井的，煤矿从业人员有权拒绝下井作业。煤矿不得因此降低从业人员工资、福利等待遇或者解除与其订立的劳动合同。"},{"i":13,"n":"第十三条","txt":"煤炭行业管理部门应当加强对煤矿领导带班下井的日常管理和督促检查。煤矿安全监管部门应当将煤矿建立并执行领导带班下井制度作为日常监督检查的重要内容，每季度至少对所辖区域煤矿领导带班下井执行情况进行一次监督检查。 煤矿领导带班下井执行情况应当在当地主要媒体向社会公布，接受社会监督。"},{"i":14,"n":"第十四条","txt":"煤矿安全监察机构应当将煤矿领导带班下井制度执行情况纳入年度监察执法计划，每年至少进行两次专项监察或者重点监察。 煤矿领导带班下井的专项监察或者重点监察的情况应当报告上一级煤矿安全监察机构，并通报有关地方人民政府。"},{"i":15,"n":"第十五条","txt":"煤炭行业管理部门、煤矿安全监管部门、煤矿安全监察机构对煤矿领导带班下井情况进行监督检查，可以采取现场随机询问煤矿从业人员、查阅井下交接班及下井档案记录、听取煤矿从业人员反映、调阅煤矿井下人员定位系统监控记录等方式。"},{"i":16,"n":"第十六条","txt":"煤炭行业管理部门、煤矿安全监管部门、煤矿安全监察机构对煤矿领导带班下井情况进行监督检查时，重点检查下列内容： （一）是否建立健全煤矿领导带班下井制度，包括井下交接班制度和带班下井档案管理制度； （二）煤矿领导特别是煤矿主要负责人带班下井情况； （三）是否制订煤矿领导每月轮流带班下井工作计划以及工作计划执行、公示、考核和奖惩等情况； （四）煤矿领导带班下井在井下履行职责情况，特别是重大事故隐患和险情的处置情况； （五）煤矿领导井下交接班记录、带班下井档案等情况； （六）群众举报有关问题的查处情况。"},{"i":17,"n":"第十七条","txt":"煤炭行业管理部门、煤矿安全监管部门、煤矿安全监察机构应当建立举报制度，公开举报电话、信箱或者电子邮件地址，受理有关举报；对于受理的举报，应当认真调查核实；经查证属实的，依法从重处罚。"},{"i":18,"n":"第十八条","txt":"煤矿有下列情形之一的，给予警告，并处3万元罚款；对煤矿主要负责人处1万元罚款： （一）未建立健全煤矿领导带班下井制度的； （二）未建立煤矿领导井下交接班制度的； （三）未建立煤矿领导带班下井档案管理制度的； （四）煤矿领导每月带班下井情况未按照规定公示的； （五）未按规定填写煤矿领导下井交接班记录簿、带班下井记录或者保存带班下井相关记录档案的。"},{"i":19,"n":"第十九条","txt":"煤矿领导未按规定带班下井，或者带班下井档案虚假的，责令改正，并对该煤矿处15万元的罚款，对违反规定的煤矿领导按照擅离职守处理，对煤矿主要负责人处1万元的罚款。"},{"i":20,"n":"第二十条","txt":"对发生事故而没有煤矿领导带班下井的煤矿，依法责令停产整顿，暂扣或者吊销煤矿安全生产许可证，并依照下列规定处以罚款；情节严重的，提请有关人民政府依法予以关闭： （一）发生一般事故的，处50万元的罚款； （二）发生较大事故的，处100万元的罚款； （三）发生重大事故的，处500万元的罚款； （四）发生特别重大事故的，处2000万元的罚款。"},{"i":21,"n":"第二十一条","txt":"对发生事故而没有煤矿领导带班下井的煤矿，对其主要负责人依法暂扣或者吊销其安全资格证，并依照下列规定处以罚款： （一）发生一般事故的，处上一年年收入30%的罚款； （二）发生较大事故的，处上一年年收入40%的罚款； （三）发生重大事故的，处上一年年收入60%的罚款； （四）发生特别重大事故的，处上一年年收入80%的罚款。 煤矿的主要负责人未履行《安全生产法》规定的安全生产管理职责，导致发生生产安全事故，受到刑事处罚或者撤职处分的，自刑罚执行完毕或者受处分之日起，5年内不得担任任何生产经营单位的主要负责人；对重大、特别重大生产安全事故负有责任的，终身不得担任煤矿的主要负责人"},{"i":22,"n":"第二十二条","txt":"本规定的行政处罚，由煤矿安全监管部门、煤矿安全监察机构依照各自的法定职权决定。"},{"i":23,"n":"第二十三条","txt":"省级煤炭行业管理部门会同煤矿安全监管部门可以依照本规定制定实施细则，报国家安全生产监督管理总局、国家煤矿安监局备案。"},{"i":24,"n":"第二十四条","txt":"中央企业所属煤矿按照分级属地管理原则，由省（市、区）、设区的市人民政府煤炭行业管理部门、煤矿安全监管部门和煤矿安全监察机构负责监督监察。"},{"i":25,"n":"第二十五条","txt":"露天煤矿领导带班下井参照本规定执行。"},{"i":26,"n":"第二十六条","txt":"本规定自2010年10月7日起施行。"}],"tezhongzuoyerenyuananquanjishupeixunkaoheguanligui416569":[{"i":1,"n":"第一条","txt":"为了规范特种作业人员的安全技术培训考核工作，提高特种作业人员的安全技术水平，防止和减少伤亡事故，根据《安全生产法》、《行政许可法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"生产经营单位特种作业人员的安全技术培训、考核、发证、复审及其监督管理工作，适用本规定。 有关法律、行政法规和国务院对有关特种作业人员管理另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"本规定所称特种作业，是指容易发生事故，对操作者本人、他人的安全健康及设备、设施的安全可能造成重大危害的作业。特种作业的范围由特种作业目录规定。 本规定所称特种作业人员，是指直接从事特种作业的从业人员。"},{"i":4,"n":"第四条","txt":"特种作业人员应当符合下列条件： （一）年满18周岁，且不超过国家法定退休年龄； （二）经社区或者县级以上医疗机构体检健康合格，并无妨碍从事相应特种作业的器质性心脏病、癫痫病、美尼尔氏症、眩晕症、癔病、震颤麻痹症、精神病、痴呆症以及其他疾病和生理缺陷； （三）具有初中及以上文化程度； （四）具备必要的安全技术知识与技能； （五）相应特种作业规定的其他条件。 危险化学品特种作业人员除符合前款第一项、第二项、第四项和第五项规定的条件外，应当具备高中或者相当于高中及以上文化程度。"},{"i":5,"n":"第五条","txt":"特种作业人员必须经专门的安全技术培训并考核合格，取得《中华人民共和国特种作业操作证》（以下简称特种作业操作证）后，方可上岗作业。"},{"i":6,"n":"第六条","txt":"特种作业人员的安全技术培训、考核、发证、复审工作实行统一监管、分级实施、教考分离的原则。"},{"i":7,"n":"第七条","txt":"国家安全生产监督管理总局（以下简称安全监管总局）指导、监督全国特种作业人员的安全技术培训、考核、发证、复审工作；省、自治区、直辖市人民政府安全生产监督管理部门指导、监督本行政区域特种作业人员的安全技术培训工作，负责本行政区域特种作业人员的考核、发证、复审工作；县级以上地方人民政府安全生产监督管理部门负责监督检查本行政区域特种作业人员的安全技术培训和持证上岗工作。 国家煤矿安全监察局（以下简称煤矿安监局）指导、监督全国煤矿特种作业人员（含煤矿矿井使用的特种设备作业人员）的安全技术培训、考核、发证、复审工作；省、自治区、直辖市人民政府负责煤矿特种作业人员考核发证工作的部门或者指定的机构指导、监督本行政区域煤矿特种作业人员的安全技术培训工作，负责本行政区域煤矿特种作业人员的考核、发证、复审工作。 省、自治区、直辖市人民政府安全生产监督管理部门和负责煤矿特种作业人员考核发证工作的部门或者指定的"},{"i":8,"n":"第八条","txt":"对特种作业人员安全技术培训、考核、发证、复审工作中的违法行为，任何单位和个人均有权向安全监管总局、煤矿安监局和省、自治区、直辖市及设区的市人民政府安全生产监督管理部门、负责煤矿特种作业人员考核发证工作的部门或者指定的机构举报。"},{"i":9,"n":"第九条","txt":"特种作业人员应当接受与其所从事的特种作业相应的安全技术理论培训和实际操作培训。 已经取得职业高中、技工学校及中专以上学历的毕业生从事与其所学专业相应的特种作业，持学历证明经考核发证机关同意，可以免予相关专业的培训。 跨省、自治区、直辖市从业的特种作业人员，可以在户籍所在地或者从业所在地参加培训。"},{"i":10,"n":"第十条","txt":"对特种作业人员的安全技术培训，具备安全培训条件的生产经营单位应当以自主培训为主，也可以委托具备安全培训条件的机构进行培训。 不具备安全培训条件的生产经营单位，应当委托具备安全培训条件的机构进行培训。 生产经营单位委托其他机构进行特种作业人员安全技术培训的，保证安全技术培训的责任仍由本单位负责。"},{"i":11,"n":"第十一条","txt":"从事特种作业人员安全技术培训的机构（以下统称培训机构），应当制定相应的培训计划、教学安排，并按照安全监管总局、煤矿安监局制定的特种作业人员培训大纲和煤矿特种作业人员培训大纲进行特种作业人员的安全技术培训。"},{"i":12,"n":"第十二条","txt":"特种作业人员的考核包括考试和审核两部分。考试由考核发证机关或其委托的单位负责；审核由考核发证机关负责。 安全监管总局、煤矿安监局分别制定特种作业人员、煤矿特种作业人员的考核标准，并建立相应的考试题库。 考核发证机关或其委托的单位应当按照安全监管总局、煤矿安监局统一制定的考核标准进行考核。"},{"i":13,"n":"第十三条","txt":"参加特种作业操作资格考试的人员，应当填写考试申请表，由申请人或者申请人的用人单位持学历证明或者培训机构出具的培训证明向申请人户籍所在地或者从业所在地的考核发证机关或其委托的单位提出申请。 考核发证机关或其委托的单位收到申请后，应当在60日内组织考试。 特种作业操作资格考试包括安全技术理论考试和实际操作考试两部分。考试不及格的，允许补考1次。经补考仍不及格的，重新参加相应的安全技术培训。"},{"i":14,"n":"第十四条","txt":"考核发证机关委托承担特种作业操作资格考试的单位应当具备相应的场所、设施、设备等条件，建立相应的管理制度，并公布收费标准等信息。"},{"i":15,"n":"第十五条","txt":"考核发证机关或其委托承担特种作业操作资格考试的单位，应当在考试结束后10个工作日内公布考试成绩。"},{"i":16,"n":"第十六条","txt":"符合本规定第四条规定并经考试合格的特种作业人员，应当向其户籍所在地或者从业所在地的考核发证机关申请办理特种作业操作证，并提交身份证复印件、学历证书复印件、体检证明、考试合格证明等材料。"},{"i":17,"n":"第十七条","txt":"收到申请的考核发证机关应当在5个工作日内完成对特种作业人员所提交申请材料的审查，作出受理或者不予受理的决定。能够当场作出受理决定的，应当当场作出受理决定；申请材料不齐全或者不符合要求的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，视为自收到申请材料之日起即已被受理。"},{"i":18,"n":"第十八条","txt":"对已经受理的申请，考核发证机关应当在20个工作日内完成审核工作。符合条件的，颁发特种作业操作证；不符合条件的，应当说明理由。"},{"i":19,"n":"第十九条","txt":"特种作业操作证有效期为6年，在全国范围内有效。 特种作业操作证由安全监管总局统一式样、标准及编号。"},{"i":20,"n":"第二十条","txt":"特种作业操作证遗失的，应当向原考核发证机关提出书面申请，经原考核发证机关审查同意后，予以补发。 特种作业操作证所记载的信息发生变化或者损毁的，应当向原考核发证机关提出书面申请，经原考核发证机关审查确认后，予以更换或者更新。"},{"i":21,"n":"第二十一条","txt":"特种作业操作证每3年复审1次。 特种作业人员在特种作业操作证有效期内，连续从事本工种10年以上，严格遵守有关安全生产法律法规的，经原考核发证机关或者从业所在地考核发证机关同意，特种作业操作证的复审时间可以延长至每6年1次。"},{"i":22,"n":"第二十二条","txt":"特种作业操作证需要复审的，应当在期满前60日内，由申请人或者申请人的用人单位向原考核发证机关或者从业所在地考核发证机关提出申请，并提交下列材料： （一）社区或者县级以上医疗机构出具的健康证明； （二）从事特种作业的情况； （三）安全培训考试合格记录。 特种作业操作证有效期届满需要延期换证的，应当按照前款的规定申请延期复审。"},{"i":23,"n":"第二十三条","txt":"特种作业操作证申请复审或者延期复审前，特种作业人员应当参加必要的安全培训并考试合格。 安全培训时间不少于8个学时，主要培训法律、法规、标准、事故案例和有关新工艺、新技术、新装备等知识。"},{"i":24,"n":"第二十四条","txt":"申请复审的，考核发证机关应当在收到申请之日起20个工作日内完成复审工作。复审合格的，由考核发证机关签章、登记，予以确认；不合格的，说明理由。 申请延期复审的，经复审合格后，由考核发证机关重新颁发特种作业操作证。"},{"i":25,"n":"第二十五条","txt":"特种作业人员有下列情形之一的，复审或者延期复审不予通过： （一）健康体检不合格的； （二）违章操作造成严重后果或者有2次以上违章行为，并经查证确实的； （三）有安全生产违法行为，并给予行政处罚的； （四）拒绝、阻碍安全生产监管监察部门监督检查的； （五）未按规定参加安全培训，或者考试不合格的； （六）具有本规定第三十条、第三十一条规定情形的。"},{"i":26,"n":"第二十六条","txt":"特种作业操作证复审或者延期复审符合本规定第二十五条第二项、第三项、第四项、第五项情形的，按照本规定经重新安全培训考试合格后，再办理复审或者延期复审手续。 再复审、延期复审仍不合格，或者未按期复审的，特种作业操作证失效。"},{"i":27,"n":"第二十七条","txt":"申请人对复审或者延期复审有异议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":28,"n":"第二十八条","txt":"考核发证机关或其委托的单位及其工作人员应当忠于职守、坚持原则、廉洁自律，按照法律、法规、规章的规定进行特种作业人员的考核、发证、复审工作，接受社会的监督。"},{"i":29,"n":"第二十九条","txt":"考核发证机关应当加强对特种作业人员的监督检查，发现其具有本规定第三十条规定情形的，及时撤销特种作业操作证；对依法应当给予行政处罚的安全生产违法行为，按照有关规定依法对生产经营单位及其特种作业人员实施行政处罚。 考核发证机关应当建立特种作业人员管理信息系统，方便用人单位和社会公众查询；对于注销特种作业操作证的特种作业人员，应当及时向社会公告。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，考核发证机关应当撤销特种作业操作证： （一）超过特种作业操作证有效期未延期复审的； （二）特种作业人员的身体条件已不适合继续从事特种作业的； （三）对发生生产安全事故负有责任的； （四）特种作业操作证记载虚假信息的； （五）以欺骗、贿赂等不正当手段取得特种作业操作证的。 特种作业人员违反前款第四项、第五项规定的，3年内不得再次申请特种作业操作证。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，考核发证机关应当注销特种作业操作证： （一）特种作业人员死亡的； （二）特种作业人员提出注销申请的； （三）特种作业操作证被依法撤销的。"},{"i":32,"n":"第三十二条","txt":"离开特种作业岗位6个月以上的特种作业人员，应当重新进行实际操作考试，经确认合格后方可上岗作业。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市人民政府安全生产监督管理部门和负责煤矿特种作业人员考核发证工作的部门或者指定的机构应当每年分别向安全监管总局、煤矿安监局报告特种作业人员的考核发证情况。"},{"i":34,"n":"第三十四条","txt":"生产经营单位应当加强对本单位特种作业人员的管理，建立健全特种作业人员培训、复审档案，做好申报、培训、考核、复审的组织工作和日常的检查工作。"},{"i":35,"n":"第三十五条","txt":"特种作业人员在劳动合同期满后变动工作单位的，原工作单位不得以任何理由扣押其特种作业操作证。 跨省、自治区、直辖市从业的特种作业人员应当接受从业所在地考核发证机关的监督管理。"},{"i":36,"n":"第三十六条","txt":"生产经营单位不得印制、伪造、倒卖特种作业操作证，或者使用非法印制、伪造、倒卖的特种作业操作证。 特种作业人员不得伪造、涂改、转借、转让、冒用特种作业操作证或者使用伪造的特种作业操作证。"},{"i":37,"n":"第三十七条","txt":"考核发证机关或其委托的单位及其工作人员在特种作业人员考核、发证和复审工作中滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"生产经营单位未建立健全特种作业人员档案的，给予警告，并处1万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"生产经营单位使用未取得特种作业操作证的特种作业人员上岗作业的，责令限期改正，可以处5万元以下的罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款。 煤矿企业使用未取得特种作业操作证的特种作业人员上岗作业的，依照《国务院关于预防煤矿生产安全事故的特别规定》的规定处罚。"},{"i":40,"n":"第四十条","txt":"生产经营单位非法印制、伪造、倒卖特种作业操作证，或者使用非法印制、伪造、倒卖的特种作业操作证的，给予警告，并处1万元以上3万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"特种作业人员伪造、涂改特种作业操作证或者使用伪造的特种作业操作证的，给予警告，并处1000元以上5000元以下的罚款。 特种作业人员转借、转让、冒用特种作业操作证的，给予警告，并处2000元以上1万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"特种作业人员培训、考试的收费标准，由省、自治区、直辖市人民政府安全生产监督管理部门会同负责煤矿特种作业人员考核发证工作的部门或者指定的机构统一制定，报同级人民政府物价、财政部门批准后执行，证书工本费由考核发证机关列入同级财政预算。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市人民政府安全生产监督管理部门和负责煤矿特种作业人员考核发证工作的部门或者指定的机构可以结合本地区实际，制定实施细则，报安全监管总局、煤矿安监局备案。"},{"i":44,"n":"第四十四条","txt":"本规定自2010年7月1日起施行。1999年7月12日原国家经贸委发布的《特种作业人员安全技术培训考核管理办法》（原国家经贸委令第13号）同时废止。 附件： 特种作业目录 1电工作业 指对电气设备进行运行、维护、安装、检修、改造、施工、调试等作业（不含电力系统进网作业）。 1.1高压电工作业 指对1千伏（kV）及以上的高压电气设备进行运行、维护、安装、检修、改造、施工、调试、试验及绝缘工、器具进行试验的作业。 1.2低压电工作业 指对1千伏（kV）以下的低压电器设备进行安装、调试、运行操作、维护、检修、改造施工和试验的作业。 1.3防爆电气作业 指对各种防爆电气设备进行安装、检修、维护的作业。 适用于除煤矿井下以外的防爆电气作业。 2焊接与热切割作业 指运用焊接或者热切割方法对材料进行加工的作业（不含《特种设备安全监察条例》规定的有关作业）。 2.1熔化焊接与热切割作业 指使用局部加热"}],"shengchananquanshiguxinxibaogaohechuzhibanfa":[{"i":1,"n":"第一条","txt":"为了规范生产安全事故信息的报告和处置工作，根据《安全生产法》、《生产安全事故报告和调查处理条例》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"生产经营单位报告生产安全事故信息和安全生产监督管理部门、煤矿安全监察机构对生产安全事故信息的报告和处置工作，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法规定的应当报告和处置的生产安全事故信息（以下简称事故信息），是指已经发生的生产安全事故和较大涉险事故的信息。"},{"i":4,"n":"第四条","txt":"事故信息的报告应当及时、准确和完整，信息的处置应当遵循快速高效、协同配合、分级负责的原则。 安全生产监督管理部门负责各类生产经营单位的事故信息报告和处置工作。煤矿安全监察机构负责煤矿的事故信息报告和处置工作。"},{"i":5,"n":"第五条","txt":"安全生产监督管理部门、煤矿安全监察机构应当建立事故信息报告和处置制度，设立事故信息调度机构，实行24小时不间断调度值班，并向社会公布值班电话，受理事故信息报告和举报。"},{"i":6,"n":"第六条","txt":"生产经营单位发生生产安全事故或者较大涉险事故，其单位负责人接到事故信息报告后应当于1小时内报告事故发生地县级安全生产监督管理部门、煤矿安全监察分局。 发生较大以上生产安全事故的，事故发生单位在依照第一款规定报告的同时，应当在1小时内报告省级安全生产监督管理部门、省级煤矿安全监察机构。 发生重大、特别重大生产安全事故的，事故发生单位在依照本条第一款、第二款规定报告的同时，可以立即报告国家安全生产监督管理总局、国家煤矿安全监察局。"},{"i":7,"n":"第七条","txt":"安全生产监督管理部门、煤矿安全监察机构接到事故发生单位的事故信息报告后，应当按照下列规定上报事故情况，同时书面通知同级公安机关、劳动保障部门、工会、人民检察院和有关部门： （一）一般事故和较大涉险事故逐级上报至设区的市级安全生产监督管理部门、省级煤矿安全监察机构； （二）较大事故逐级上报至省级安全生产监督管理部门、省级煤矿安全监察机构； （三）重大事故、特别重大事故逐级上报至国家安全生产监督管理总局、国家煤矿安全监察局。 前款规定的逐级上报，每一级上报时间不得超过2小时。安全生产监督管理部门依照前款规定上报事故情况时，应当同时报告本级人民政府。"},{"i":8,"n":"第八条","txt":"发生较大生产安全事故或者社会影响重大的事故的，县级、市级安全生产监督管理部门或者煤矿安全监察分局接到事故报告后，在依照本办法第七条规定逐级上报的同时，应当在1小时内先用电话快报省级安全生产监督管理部门、省级煤矿安全监察机构，随后补报文字报告；乡镇安监站（办）可以根据事故情况越级直接报告省级安全生产监督管理部门、省级煤矿安全监察机构。"},{"i":9,"n":"第九条","txt":"发生重大、特别重大生产安全事故或者社会影响恶劣的事故的，县级、市级安全生产监督管理部门或者煤矿安全监察分局接到事故报告后，在依照本办法第七条规定逐级上报的同时，应当在1小时内先用电话快报省级安全生产监督管理部门、省级煤矿安全监察机构，随后补报文字报告；必要时，可以直接用电话报告国家安全生产监督管理总局、国家煤矿安全监察局。 省级安全生产监督管理部门、省级煤矿安全监察机构接到事故报告后，应当在1小时内先用电话快报国家安全生产监督管理总局、国家煤矿安全监察局，随后补报文字报告。 国家安全生产监督管理总局、国家煤矿安全监察局接到事故报告后，应当在1小时内先用电话快报国务院总值班室，随后补报文字报告。"},{"i":10,"n":"第十条","txt":"报告事故信息，应当包括下列内容： （一）事故发生单位的名称、地址、性质、产能等基本情况； （二）事故发生的时间、地点以及事故现场情况； （三）事故的简要经过（包括应急救援情况）； （四）事故已经造成或者可能造成的伤亡人数（包括下落不明、涉险的人数）和初步估计的直接经济损失； （五）已经采取的措施； （六）其他应当报告的情况。 使用电话快报，应当包括下列内容： （一）事故发生单位的名称、地址、性质； （二）事故发生的时间、地点； （三）事故已经造成或者可能造成的伤亡人数（包括下落不明、涉险的人数）。"},{"i":11,"n":"第十一条","txt":"事故具体情况暂时不清楚的，负责事故报告的单位可以先报事故概况，随后补报事故全面情况。 事故信息报告后出现新情况的，负责事故报告的单位应当依照本办法第六条、第七条、第八条、第九条的规定及时续报。较大涉险事故、一般事故、较大事故每日至少续报1次；重大事故、特别重大事故每日至少续报2次。 自事故发生之日起30日内（道路交通、火灾事故自发生之日起7日内），事故造成的伤亡人数发生变化的，应于当日续报。"},{"i":12,"n":"第十二条","txt":"安全生产监督管理部门、煤矿安全监察机构接到任何单位或者个人的事故信息举报后，应当立即与事故单位或者下一级安全生产监督管理部门、煤矿安全监察机构联系，并进行调查核实。 下一级安全生产监督管理部门、煤矿安全监察机构接到上级安全生产监督管理部门、煤矿安全监察机构的事故信息举报核查通知后，应当立即组织查证核实，并在2个月内向上一级安全生产监督管理部门、煤矿安全监察机构报告核实结果。 对发生较大涉险事故的，安全生产监督管理部门、煤矿安全监察机构依照本条第二款规定向上一级安全生产监督管理部门、煤矿安全监察机构报告核实结果；对发生生产安全事故的，安全生产监督管理部门、煤矿安全监察机构应当在5日内对事故情况进行初步查证，并将事故初步查证的简要情况报告上一级安全生产监督管理部门、煤矿安全监察机构，详细核实结果在2个月内报告。"},{"i":13,"n":"第十三条","txt":"事故信息经初步查证后，负责查证的安全生产监督管理部门、煤矿安全监察机构应当立即报告本级人民政府和上一级安全生产监督管理部门、煤矿安全监察机构，并书面通知公安机关、劳动保障部门、工会、人民检察院和有关部门。"},{"i":14,"n":"第十四条","txt":"安全生产监督管理部门与煤矿安全监察机构之间，安全生产监督管理部门、煤矿安全监察机构与其他负有安全生产监督管理职责的部门之间，应当建立有关事故信息的通报制度，及时沟通事故信息。"},{"i":15,"n":"第十五条","txt":"对于事故信息的每周、每月、每年的统计报告，按照有关规定执行。"},{"i":16,"n":"第十六条","txt":"安全生产监督管理部门、煤矿安全监察机构应当建立事故信息处置责任制，做好事故信息的核实、跟踪、分析、统计工作。"},{"i":17,"n":"第十七条","txt":"发生生产安全事故或者较大涉险事故后，安全生产监督管理部门、煤矿安全监察机构应当立即研究、确定并组织实施相关处置措施。安全生产监督管理部门、煤矿安全监察机构负责人按照职责分工负责相关工作。"},{"i":18,"n":"第十八条","txt":"安全生产监督管理部门、煤矿安全监察机构接到生产安全事故报告后，应当按照下列规定派员立即赶赴事故现场： （一）发生一般事故的，县级安全生产监督管理部门、煤矿安全监察分局负责人立即赶赴事故现场； （二）发生较大事故的，设区的市级安全生产监督管理部门、省级煤矿安全监察局负责人应当立即赶赴事故现场； （三）发生重大事故的，省级安全监督管理部门、省级煤矿安全监察局负责人立即赶赴事故现场； （四）发生特别重大事故的，国家安全生产监督管理总局、国家煤矿安全监察局负责人立即赶赴事故现场。 上级安全生产监督管理部门、煤矿安全监察机构认为必要的，可以派员赶赴事故现场。"},{"i":19,"n":"第十九条","txt":"安全生产监督管理部门、煤矿安全监察机构负责人及其有关人员赶赴事故现场后，应当随时保持与本单位的联系。有关事故信息发生重大变化的，应当依照本办法有关规定及时向本单位或者上级安全生产监督管理部门、煤矿安全监察机构报告。"},{"i":20,"n":"第二十条","txt":"安全生产监督管理部门、煤矿安全监察机构应当依照有关规定定期向社会公布事故信息。 任何单位和个人不得擅自发布事故信息。"},{"i":21,"n":"第二十一条","txt":"安全生产监督管理部门、煤矿安全监察机构应当根据事故信息报告的情况，启动相应的应急救援预案，或者组织有关应急救援队伍协助地方人民政府开展应急救援工作。"},{"i":22,"n":"第二十二条","txt":"安全生产监督管理部门、煤矿安全监察机构按照有关规定组织或者参加事故调查处理工作。"},{"i":23,"n":"第二十三条","txt":"安全生产监督管理部门、煤矿安全监察机构及其工作人员未依法履行事故信息报告和处置职责的，依照有关规定予以处理。"},{"i":24,"n":"第二十四条","txt":"生产经营单位及其有关人员对生产安全事故迟报、漏报、谎报或者瞒报的，依照有关规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"生产经营单位对较大涉险事故迟报、漏报、谎报或者瞒报的，给予警告，并处3万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"本办法所称的较大涉险事故是指： （一）涉险10人以上的事故； （二）造成3人以上被困或者下落不明的事故； （三）紧急疏散人员500人以上的事故； （四）因生产安全事故对环境造成严重污染（人员密集场所、生活水源、农田、河流、水库、湖泊等）的事故； （五）危及重要场所和设施安全（电站、重要水利设施、危化品库、油气站和车站、码头、港口、机场及其他人员密集场所等）的事故； （六）其他较大涉险事故。"},{"i":27,"n":"第二十七条","txt":"省级安全生产监督管理部门、省级煤矿安全监察机构可以根据本办法的规定，制定具体的实施办法。"},{"i":28,"n":"第二十八条","txt":"本办法自2009年7月1日起施行。"}],"shengchananquanshiguyingjiyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范生产安全事故应急预案管理工作，迅速有效处置生产安全事故，依据《中华人民共和国突发事件应对法》《中华人民共和国安全生产法》《生产安全事故应急条例》等法律、行政法规和《突发事件应急预案管理办法》（国办发〔2013〕101号），制定本办法。"},{"i":2,"n":"第二条","txt":"生产安全事故应急预案（以下简称应急预案）的编制、评审、公布、备案、实施及监督管理工作，适用本办法。"},{"i":3,"n":"第三条","txt":"应急预案的管理实行属地为主、分级负责、分类指导、综合协调、动态管理的原则。"},{"i":4,"n":"第四条","txt":"应急管理部负责全国应急预案的综合协调管理工作。国务院其他负有安全生产监督管理职责的部门在各自职责范围内，负责相关行业、领域应急预案的管理工作。 县级以上地方各级人民政府应急管理部门负责本行政区域内应急预案的综合协调管理工作。县级以上地方各级人民政府其他负有安全生产监督管理职责的部门按照各自的职责负责有关行业、领域应急预案的管理工作。"},{"i":5,"n":"第五条","txt":"生产经营单位主要负责人负责组织编制和实施本单位的应急预案，并对应急预案的真实性和实用性负责；各分管负责人应当按照职责分工落实应急预案规定的职责。"},{"i":6,"n":"第六条","txt":"生产经营单位应急预案分为综合应急预案、专项应急预案和现场处置方案。 综合应急预案，是指生产经营单位为应对各种生产安全事故而制定的综合性工作方案，是本单位应对生产安全事故的总体工作程序、措施和应急预案体系的总纲。 专项应急预案，是指生产经营单位为应对某一种或者多种类型生产安全事故，或者针对重要生产设施、重大危险源、重大活动防止生产安全事故而制定的专项性工作方案。 现场处置方案，是指生产经营单位根据不同生产安全事故类型，针对具体场所、装置或者设施所制定的应急处置措施。"},{"i":7,"n":"第七条","txt":"应急预案的编制应当遵循以人为本、依法依规、符合实际、注重实效的原则，以应急处置为核心，明确应急职责、规范应急程序、细化保障措施。"},{"i":8,"n":"第八条","txt":"应急预案的编制应当符合下列基本要求： （一）有关法律、法规、规章和标准的规定； （二）本地区、本部门、本单位的安全生产实际情况； （三）本地区、本部门、本单位的危险性分析情况； （四）应急组织和人员的职责分工明确，并有具体的落实措施； （五）有明确、具体的应急程序和处置措施，并与其应急能力相适应； （六）有明确的应急保障措施，满足本地区、本部门、本单位的应急工作需要； （七）应急预案基本要素齐全、完整，应急预案附件提供的信息准确； （八）应急预案内容与相关应急预案相互衔接。"},{"i":9,"n":"第九条","txt":"编制应急预案应当成立编制工作小组，由本单位有关负责人任组长，吸收与应急预案有关的职能部门和单位的人员，以及有现场处置经验的人员参加。"},{"i":10,"n":"第十条","txt":"编制应急预案前，编制单位应当进行事故风险辨识、评估和应急资源调查。 事故风险辨识、评估，是指针对不同事故种类及特点，识别存在的危险危害因素，分析事故可能产生的直接后果以及次生、衍生后果，评估各种后果的危害程度和影响范围，提出防范和控制事故风险措施的过程。 应急资源调查，是指全面调查本地区、本单位第一时间可以调用的应急资源状况和合作区域内可以请求援助的应急资源状况，并结合事故风险辨识评估结论制定应急措施的过程。"},{"i":11,"n":"第十一条","txt":"地方各级人民政府应急管理部门和其他负有安全生产监督管理职责的部门应当根据法律、法规、规章和同级人民政府以及上一级人民政府应急管理部门和其他负有安全生产监督管理职责的部门的应急预案，结合工作实际，组织编制相应的部门应急预案。 部门应急预案应当根据本地区、本部门的实际情况，明确信息报告、响应分级、指挥权移交、警戒疏散等内容。"},{"i":12,"n":"第十二条","txt":"生产经营单位应当根据有关法律、法规、规章和相关标准，结合本单位组织管理体系、生产规模和可能发生的事故特点，与相关预案保持衔接，确立本单位的应急预案体系，编制相应的应急预案，并体现自救互救和先期处置等特点。"},{"i":13,"n":"第十三条","txt":"生产经营单位风险种类多、可能发生多种类型事故的，应当组织编制综合应急预案。 综合应急预案应当规定应急组织机构及其职责、应急预案体系、事故风险描述、预警及信息报告、应急响应、保障措施、应急预案管理等内容。"},{"i":14,"n":"第十四条","txt":"对于某一种或者多种类型的事故风险，生产经营单位可以编制相应的专项应急预案，或将专项应急预案并入综合应急预案。 专项应急预案应当规定应急指挥机构与职责、处置程序和措施等内容。"},{"i":15,"n":"第十五条","txt":"对于危险性较大的场所、装置或者设施，生产经营单位应当编制现场处置方案。 现场处置方案应当规定应急工作职责、应急处置措施和注意事项等内容。 事故风险单一、危险性小的生产经营单位，可以只编制现场处置方案。"},{"i":16,"n":"第十六条","txt":"生产经营单位应急预案应当包括向上级应急管理机构报告的内容、应急组织机构和人员的联系方式、应急物资储备清单等附件信息。附件信息发生变化时，应当及时更新，确保准确有效。"},{"i":17,"n":"第十七条","txt":"生产经营单位组织应急预案编制过程中，应当根据法律、法规、规章的规定或者实际需要，征求相关应急救援队伍、公民、法人或其他组织的意见。"},{"i":18,"n":"第十八条","txt":"生产经营单位编制的各类应急预案之间应当相互衔接，并与相关人民政府及其部门、应急救援队伍和涉及的其他单位的应急预案相衔接。"},{"i":19,"n":"第十九条","txt":"生产经营单位应当在编制应急预案的基础上，针对工作场所、岗位的特点，编制简明、实用、有效的应急处置卡。 应急处置卡应当规定重点岗位、人员的应急处置程序和措施，以及相关联络人员和联系方式，便于从业人员携带。"},{"i":20,"n":"第二十条","txt":"地方各级人民政府应急管理部门应当组织有关专家对本部门编制的部门应急预案进行审定；必要时，可以召开听证会，听取社会有关方面的意见。"},{"i":21,"n":"第二十一条","txt":"矿山、金属冶炼企业和易燃易爆物品、危险化学品的生产、经营（带储存设施的，下同）、储存、运输企业，以及使用危险化学品达到国家规定数量的化工企业、烟花爆竹生产、批发经营企业和中型规模以上的其他生产经营单位，应当对本单位编制的应急预案进行评审，并形成书面评审纪要。 前款规定以外的其他生产经营单位可以根据自身需要，对本单位编制的应急预案进行论证。"},{"i":22,"n":"第二十二条","txt":"参加应急预案评审的人员应当包括有关安全生产及应急管理方面的专家。 评审人员与所评审应急预案的生产经营单位有利害关系的，应当回避。"},{"i":23,"n":"第二十三条","txt":"应急预案的评审或者论证应当注重基本要素的完整性、组织体系的合理性、应急处置程序和措施的针对性、应急保障措施的可行性、应急预案的衔接性等内容。"},{"i":24,"n":"第二十四条","txt":"生产经营单位的应急预案经评审或者论证后，由本单位主要负责人签署，向本单位从业人员公布，并及时发放到本单位有关部门、岗位和相关应急救援队伍。 事故风险可能影响周边其他单位、人员的，生产经营单位应当将有关事故风险的性质、影响范围和应急防范措施告知周边的其他单位和人员。"},{"i":25,"n":"第二十五条","txt":"地方各级人民政府应急管理部门的应急预案，应当报同级人民政府备案，同时抄送上一级人民政府应急管理部门，并依法向社会公布。 地方各级人民政府其他负有安全生产监督管理职责的部门的应急预案，应当抄送同级人民政府应急管理部门。"},{"i":26,"n":"第二十六条","txt":"易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当在应急预案公布之日起20个工作日内，按照分级属地原则，向县级以上人民政府应急管理部门和其他负有安全生产监督管理职责的部门进行备案，并依法向社会公布。 前款所列单位属于中央企业的，其总部（上市公司）的应急预案，报国务院主管的负有安全生产监督管理职责的部门备案，并抄送应急管理部；其所属单位的应急预案报所在地的省、自治区、直辖市或者设区的市级人民政府主管的负有安全生产监督管理职责的部门备案，并抄送同级人民政府应急管理部门。 本条第一款所列单位不属于中央企业的，其中非煤矿山、金属冶炼和危险化学品生产、经营、储存、运输企业，以及使用危险化学品达到国家规定数量的化工企业、烟花爆竹生产、批发经营企业的应急预案，按照隶属关系报所在"},{"i":27,"n":"第二十七条","txt":"生产经营单位申报应急预案备案，应当提交下列材料： （一）应急预案备案申报表； （二）本办法第二十一条所列单位，应当提供应急预案评审意见； （三）应急预案电子文档； （四）风险评估结果和应急资源调查清单。"},{"i":28,"n":"第二十八条","txt":"受理备案登记的负有安全生产监督管理职责的部门应当在5个工作日内对应急预案材料进行核对，材料齐全的，应当予以备案并出具应急预案备案登记表；材料不齐全的，不予备案并一次性告知需要补齐的材料。逾期不予备案又不说明理由的，视为已经备案。 对于实行安全生产许可的生产经营单位，已经进行应急预案备案的，在申请安全生产许可证时，可以不提供相应的应急预案，仅提供应急预案备案登记表。"},{"i":29,"n":"第二十九条","txt":"各级人民政府负有安全生产监督管理职责的部门应当建立应急预案备案登记建档制度，指导、督促生产经营单位做好应急预案的备案登记工作。"},{"i":30,"n":"第三十条","txt":"各级人民政府应急管理部门、各类生产经营单位应当采取多种形式开展应急预案的宣传教育，普及生产安全事故避险、自救和互救知识，提高从业人员和社会公众的安全意识与应急处置技能。"},{"i":31,"n":"第三十一条","txt":"各级人民政府应急管理部门应当将本部门应急预案的培训纳入安全生产培训工作计划，并组织实施本行政区域内重点生产经营单位的应急预案培训工作。 生产经营单位应当组织开展本单位的应急预案、应急知识、自救互救和避险逃生技能的培训活动，使有关人员了解应急预案内容，熟悉应急职责、应急处置程序和措施。 应急培训的时间、地点、内容、师资、参加人员和考核结果等情况应当如实记入本单位的安全生产教育和培训档案。"},{"i":32,"n":"第三十二条","txt":"各级人民政府应急管理部门应当至少每两年组织一次应急预案演练，提高本部门、本地区生产安全事故应急处置能力。"},{"i":33,"n":"第三十三条","txt":"生产经营单位应当制定本单位的应急预案演练计划，根据本单位的事故风险特点，每年至少组织一次综合应急预案演练或者专项应急预案演练，每半年至少组织一次现场处置方案演练。 易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当至少每半年组织一次生产安全事故应急预案演练，并将演练情况报送所在地县级以上地方人民政府负有安全生产监督管理职责的部门。 县级以上地方人民政府负有安全生产监督管理职责的部门应当对本行政区域内前款规定的重点生产经营单位的生产安全事故应急救援预案演练进行抽查；发现演练不符合要求的，应当责令限期改正。"},{"i":34,"n":"第三十四条","txt":"应急预案演练结束后，应急预案演练组织单位应当对应急预案演练效果进行评估，撰写应急预案演练评估报告，分析存在的问题，并对应急预案提出修订意见。"},{"i":35,"n":"第三十五条","txt":"应急预案编制单位应当建立应急预案定期评估制度，对预案内容的针对性和实用性进行分析，并对应急预案是否需要修订作出结论。 矿山、金属冶炼、建筑施工企业和易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输企业、使用危险化学品达到国家规定数量的化工企业、烟花爆竹生产、批发经营企业和中型规模以上的其他生产经营单位，应当每三年进行一次应急预案评估。 应急预案评估可以邀请相关专业机构或者有关专家、有实际应急救援工作经验的人员参加，必要时可以委托安全生产技术服务机构实施。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，应急预案应当及时修订并归档： （一）依据的法律、法规、规章、标准及上位预案中的有关规定发生重大变化的； （二）应急指挥机构及其职责发生调整的； （三）安全生产面临的风险发生重大变化的； （四）重要应急资源发生重大变化的； （五）在应急演练和事故应急救援中发现需要修订预案的重大问题的； （六）编制单位认为应当修订的其他情况。"},{"i":37,"n":"第三十七条","txt":"应急预案修订涉及组织指挥体系与职责、应急处置程序、主要处置措施、应急响应分级等内容变更的，修订工作应当参照本办法规定的应急预案编制程序进行，并按照有关应急预案报备程序重新备案。"},{"i":38,"n":"第三十八条","txt":"生产经营单位应当按照应急预案的规定，落实应急指挥体系、应急救援队伍、应急物资及装备，建立应急物资、装备配备及其使用档案，并对应急物资、装备进行定期检测和维护，使其处于适用状态。"},{"i":39,"n":"第三十九条","txt":"生产经营单位发生事故时，应当第一时间启动应急响应，组织有关力量进行救援，并按照规定将事故信息及应急响应启动情况报告事故发生地县级以上人民政府应急管理部门和其他负有安全生产监督管理职责的部门。"},{"i":40,"n":"第四十条","txt":"生产安全事故应急处置和应急救援结束后，事故发生单位应当对应急预案实施情况进行总结评估。"},{"i":41,"n":"第四十一条","txt":"各级人民政府应急管理部门和煤矿安全监察机构应当将生产经营单位应急预案工作纳入年度监督检查计划，明确检查的重点内容和标准，并严格按照计划开展执法检查。"},{"i":42,"n":"第四十二条","txt":"地方各级人民政府应急管理部门应当每年对应急预案的监督管理工作情况进行总结，并报上一级人民政府应急管理部门。"},{"i":43,"n":"第四十三条","txt":"对于在应急预案管理工作中做出显著成绩的单位和人员，各级人民政府应急管理部门、生产经营单位可以给予表彰和奖励。"},{"i":44,"n":"第四十四条","txt":"生产经营单位有下列情形之一的，由县级以上人民政府应急管理等部门依照《中华人民共和国安全生产法》第九十四条的规定，责令限期改正，可以处5万元以下罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款： （一）未按照规定编制应急预案的； （二）未按照规定定期组织应急预案演练的。"},{"i":45,"n":"第四十五条","txt":"生产经营单位有下列情形之一的，由县级以上人民政府应急管理部门责令限期改正，可以处1万元以上3万元以下罚款： （一）在应急预案编制前未按照规定开展风险辨识、评估和应急资源调查的； （二）未按照规定开展应急预案评审的； （三）事故风险可能影响周边单位、人员的，未将事故风险的性质、影响范围和应急防范措施告知周边单位和人员的； （四）未按照规定开展应急预案评估的； （五）未按照规定进行应急预案修订的； （六）未落实应急预案规定的应急物资及装备的。 生产经营单位未按照规定进行应急预案备案的，由县级以上人民政府应急管理等部门依照职责责令限期改正；逾期未改正的，处3万元以上5万元以下的罚款，对直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款。"},{"i":46,"n":"第四十六条","txt":"《生产经营单位生产安全事故应急预案备案申报表》和《生产经营单位生产安全事故应急预案备案登记表》由应急管理部统一制定。"},{"i":47,"n":"第四十七条","txt":"各省、自治区、直辖市应急管理部门可以依据本办法的规定，结合本地区实际制定实施细则。"},{"i":48,"n":"第四十八条","txt":"对储存、使用易燃易爆物品、危险化学品等危险物品的科研机构、学校、医院等单位的安全事故应急预案的管理，参照本办法的有关规定执行。"},{"i":49,"n":"第四十九条","txt":"本办法自2016年7月1日起施行。"}],"shengchananquanshigufakuanchufaguiding":[{"i":1,"n":"第一条","txt":"为防止和减少生产安全事故，严格追究生产安全事故发生单位及其有关责任人员的法律责任，正确适用事故罚款的行政处罚，依照《安全生产法》、《生产安全事故报告和调查处理条例》（以下简称《条例》）的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"安全生产监督管理部门和煤矿安全监察机构对生产安全事故发生单位（以下简称事故发生单位）及其主要负责人、直接负责的主管人员和其他责任人员等有关责任人员依照《安全生产法》和《条例》实施罚款的行政处罚，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称事故发生单位是指对事故发生负有责任的生产经营单位。 本规定所称主要负责人是指有限责任公司、股份有限公司的董事长或者总经理或者个人经营的投资人，其他生产经营单位的厂长、经理、局长、矿长（含实际控制人）等人员。"},{"i":4,"n":"第四条","txt":"本规定所称事故发生单位主要负责人、直接负责的主管人员和其他直接责任人员的上一年年收入，属于国有生产经营单位的，是指该单位上级主管部门所确定的上一年年收入总额；属于非国有生产经营单位的，是指经财务、税务部门核定的上一年年收入总额。 生产经营单位提供虚假资料或者由于财务、税务部门无法核定等原因致使有关人员的上一年年收入难以确定的，按照下列办法确定： （一）主要负责人的上一年年收入，按照本省、自治区、直辖市上一年度职工平均工资的5倍以上10倍以下计算； （二）直接负责的主管人员和其他直接责任人员的上一年年收入，按照本省、自治区、直辖市上一年度职工平均工资的1倍以上5倍以下计算。"},{"i":5,"n":"第五条","txt":"《条例》所称的迟报、漏报、谎报和瞒报，依照下列情形认定： （一）报告事故的时间超过规定时限的，属于迟报； （二）因过失对应当上报的事故或者事故发生的时间、地点、类别、伤亡人数、直接经济损失等内容遗漏未报的，属于漏报； （三）故意不如实报告事故发生的时间、地点、初步原因、性质、伤亡人数和涉险人数、直接经济损失等有关内容的，属于谎报； （四）隐瞒已经发生的事故，超过规定时限未向安全监管监察部门和有关部门报告，经查证属实的，属于瞒报。"},{"i":6,"n":"第六条","txt":"对事故发生单位及其有关责任人员处以罚款的行政处罚，依照下列规定决定： （一）对发生特别重大事故的单位及其有关责任人员罚款的行政处罚，由国家安全生产监督管理总局决定； （二）对发生重大事故的单位及其有关责任人员罚款的行政处罚，由省级人民政府安全生产监督管理部门决定； （三）对发生较大事故的单位及其有关责任人员罚款的行政处罚，由设区的市级人民政府安全生产监督管理部门决定； （四）对发生一般事故的单位及其有关责任人员罚款的行政处罚，由县级人民政府安全生产监督管理部门决定。 上级安全生产监督管理部门可以指定下一级安全生产监督管理部门对事故发生单位及其有关责任人员实施行政处罚。"},{"i":7,"n":"第七条","txt":"对煤矿事故发生单位及其有关责任人员处以罚款的行政处罚，依照下列规定执行： （一）对发生特别重大事故的煤矿及其有关责任人员罚款的行政处罚，由国家煤矿安全监察局决定； （二）对发生重大事故和较大事故的煤矿及其有关责任人员罚款的行政处罚，由省级煤矿安全监察机构决定； （三）对发生一般事故的煤矿及其有关责任人员罚款的行政处罚，由省级煤矿安全监察机构所属分局决定。 上级煤矿安全监察机构可以指定下一级煤矿安全监察机构对事故发生单位及其有关责任人员实施行政处罚。"},{"i":8,"n":"第八条","txt":"特别重大事故以下等级事故，事故发生地与事故发生单位所在地不在同一个县级以上行政区域的，由事故发生地的安全生产监督管理部门或者煤矿安全监察机构依照本规定第六条或者第七条规定的权限实施行政处罚。"},{"i":9,"n":"第九条","txt":"安全生产监督管理部门和煤矿安全监察机构对事故发生单位及其有关责任人员实施罚款的行政处罚，依照《安全生产违法行为行政处罚办法》规定的程序执行。"},{"i":10,"n":"第十条","txt":"事故发生单位及其有关责任人员对安全生产监督管理部门和煤矿安全监察机构给予的行政处罚，享有陈述、申辩的权利；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。"},{"i":11,"n":"第十一条","txt":"事故发生单位主要负责人有《安全生产法》第一百零六条、《条例》第三十五条规定的下列行为之一的，依照下列规定处以罚款： （一）事故发生单位主要负责人在事故发生后不立即组织事故抢救的，处上一年年收入100％的罚款； （二）事故发生单位主要负责人迟报事故的，处上一年年收入60％至80％的罚款；漏报事故的，处上一年年收入40％至60％的罚款； （三）事故发生单位主要负责人在事故调查处理期间擅离职守的，处上一年年收入80％至100％的罚款。"},{"i":12,"n":"第十二条","txt":"事故发生单位有《条例》第三十六条规定行为之一的，依照《国家安全监管总局关于印发<安全生产行政处罚自由裁量标准>的通知》（安监总政法〔2010〕137号）等规定给予罚款。"},{"i":13,"n":"第十三条","txt":"事故发生单位的主要负责人、直接负责的主管人员和其他直接责任人员有《安全生产法》第一百零六条、《条例》第三十六条规定的下列行为之一的，依照下列规定处以罚款： （一）伪造、故意破坏事故现场，或者转移、隐匿资金、财产、销毁有关证据、资料，或者拒绝接受调查，或者拒绝提供有关情况和资料，或者在事故调查中作伪证，或者指使他人作伪证的，处上一年年收入80％至90％的罚款； （二）谎报、瞒报事故或者事故发生后逃匿的，处上一年年收入100％的罚款。"},{"i":14,"n":"第十四条","txt":"事故发生单位对造成3人以下死亡，或者3人以上10人以下重伤（包括急性工业中毒，下同），或者300万元以上1000万元以下直接经济损失的一般事故负有责任的，处20万元以上50万元以下的罚款。 事故发生单位有本条第一款规定的行为且有谎报或者瞒报事故情节的，处50万元的罚款。"},{"i":15,"n":"第十五条","txt":"事故发生单位对较大事故发生负有责任的，依照下列规定处以罚款： （一）造成3人以上6人以下死亡，或者10人以上30人以下重伤，或者1000万元以上3000万元以下直接经济损失的，处50万元以上70万元以下的罚款； （二）造成6人以上10人以下死亡，或者30人以上50人以下重伤，或者3000万元以上5000万元以下直接经济损失的，处70万元以上100万元以下的罚款。 事故发生单位对较大事故发生负有责任且有谎报或者瞒报情节的，处100万元的罚款。"},{"i":16,"n":"第十六条","txt":"事故发生单位对重大事故发生负有责任的，依照下列规定处以罚款： （一）造成10人以上15人以下死亡，或者50人以上70人以下重伤，或者5000万元以上7000万元以下直接经济损失的，处100万元以上300万元以下的罚款； （二）造成15人以上30人以下死亡，或者70人以上100人以下重伤，或者7000万元以上1亿元以下直接经济损失的，处300万元以上500万元以下的罚款。 事故发生单位对重大事故发生负有责任且有谎报或者瞒报情节的，处500万元的罚款。"},{"i":17,"n":"第十七条","txt":"事故发生单位对特别重大事故发生负有责任的，依照下列规定处以罚款： （一）造成30人以上40人以下死亡，或者100人以上120人以下重伤，或者1亿元以上1.2亿元以下直接经济损失的，处500万元以上1000万元以下的罚款； （二）造成40人以上50人以下死亡，或者120人以上150人以下重伤，或者1.2亿元以上1.5亿元以下直接经济损失的，处1000万元以上1500万元以下的罚款； （三）造成50人以上死亡，或者150人以上重伤，或者1.5亿元以上直接经济损失的，处1500万元以上2000万元以下的罚款。 事故发生单位对特别重大事故发生负有责任且有下列情形之一的，处2000万元的罚款： （一）谎报特别重大事故的； （二）瞒报特别重大事故的； （三）未依法取得有关行政审批或者证照擅自从事生产经营活动的； （四）拒绝、阻碍行政执法的； （五）拒不执行有关停产停业、停止施工、停止使用相关设备或"},{"i":18,"n":"第十八条","txt":"事故发生单位主要负责人未依法履行安全生产管理职责，导致事故发生的，依照下列规定处以罚款： （一）发生一般事故的，处上一年年收入30％的罚款； （二）发生较大事故的，处上一年年收入40％的罚款； （三）发生重大事故的，处上一年年收入60％的罚款； （四）发生特别重大事故的，处上一年年收入80％的罚款。"},{"i":19,"n":"第十九条","txt":"个人经营的投资人未依照《安全生产法》的规定保证安全生产所必需的资金投入，致使生产经营单位不具备安全生产条件，导致发生生产安全事故的，依照下列规定对个人经营的投资人处以罚款： （一）发生一般事故的，处2万元以上5万元以下的罚款； （二）发生较大事故的，处5万元以上10万元以下的罚款； （三）发生重大事故的，处10万元以上15万元以下的罚款； （四）发生特别重大事故的，处15万元以上20万元以下的罚款。"},{"i":20,"n":"第二十条","txt":"违反《条例》和本规定，事故发生单位及其有关责任人员有两种以上应当处以罚款的行为的，安全生产 监督管理部门或者煤矿安全监察机构应当分别裁量，合并作出处罚决定。"},{"i":21,"n":"第二十一条","txt":"对事故发生负有责任的其他单位及其有关责任人员处以罚款的行政处罚，依照相关法律、法规和规章的规定实施。"},{"i":22,"n":"第二十二条","txt":"本规定自公布之日起施行。"}],"shengchanjingyingdanweianquanpeixunguiding":[{"i":1,"n":"第一条","txt":"为加强和规范生产经营单位安全培训工作，提高从业人员安全素质，防范伤亡事故，减轻职业危害，根据安全生产法和有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"工矿商贸生产经营单位（以下简称生产经营单位）　从业人员的安全培训，适用本规定。"},{"i":3,"n":"第三条","txt":"生产经营单位负责本单位从业人员安全培训工作。 生产经营单位应当按照安全生产法和有关法律、行政法规和本规定，建立健全安全培训工作制度。"},{"i":4,"n":"第四条","txt":"生产经营单位应当进行安全培训的从业人员包括主要负责人、安全生产管理人员、特种作业人员和其他从业人员。 生产经营单位使用被派遣劳动者的，应当将被派遣劳动者纳入本单位从业人员统一管理，对被派遣劳动者进行岗位安全操作规程和安全操作技能的教育和培训。劳务派遣单位应当对被派遣劳动者进行必要的安全生产教育和培训。 生产经营单位接收中等职业学校、高等学校学生实习的，应当对实习学生进行相应的安全生产教育和培训，提供必要的劳动防护用品。学校应当协助生产经营单位对实习学生进行安全生产教育和培训。 生产经营单位从业人员应当接受安全培训，熟悉有关安全生产规章制度和安全操作规程，具备必要的安全生产知识，掌握本岗位的安全操作技能，了解事故应急处理措施，知悉自身在安全生产方面的权利和义务。 未经安全培训合格的从业人员，不得上岗作业。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局指导全国安全培训工作，依法对全国的安全培训工作实施监督管理。 国务院有关主管部门按照各自职责指导监督本行业安全培训工作，并按照本规定制定实施办法。 国家煤矿安全监察局指导监督检查全国煤矿安全培训工作。 各级安全生产监督管理部门和煤矿安全监察机构（以下简称安全生产监管监察部门）按照各自的职责，依法对生产经营单位的安全培训工作实施监督管理。"},{"i":6,"n":"第六条","txt":"生产经营单位主要负责人和安全生产管理人员应当接受安全培训，具备与所从事的生产经营活动相适应的安全生产知识和管理能力。"},{"i":7,"n":"第七条","txt":"生产经营单位主要负责人安全培训应当包括下列内容： （一）国家安全生产方针、政策和有关安全生产的法律、法规、规章及标准； （二）安全生产管理基本知识、安全生产技术、安全生产专业知识； （三）重大危险源管理、重大事故防范、应急管理和救援组织以及事故调查处理的有关规定； （四）职业危害及其预防措施； （五）国内外先进的安全生产管理经验； （六）典型事故和应急救援案例分析； （七）其他需要培训的内容。"},{"i":8,"n":"第八条","txt":"生产经营单位安全生产管理人员安全培训应当包括下列内容： （一）国家安全生产方针、政策和有关安全生产的法律、法规、规章及标准； （二）安全生产管理、安全生产技术、职业卫生等知识； （三）伤亡事故统计、报告及职业危害的调查处理方法； （四）应急管理、应急预案编制以及应急处置的内容和要求； （五）国内外先进的安全生产管理经验； （六）典型事故和应急救援案例分析； （七）其他需要培训的内容。"},{"i":9,"n":"第九条","txt":"生产经营单位主要负责人和安全生产管理人员初次安全培训时间不得少于32学时。每年再培训时间不得少于12学时。 煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位主要负责人和安全生产管理人员初次安全培训时间不得少于48学时，每年再培训时间不得少于16学时。"},{"i":10,"n":"第十条","txt":"生产经营单位主要负责人和安全生产管理人员的安全培训必须依照安全生产监管监察部门制定的安全培训大纲实施。 非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位主要负责人和安全生产管理人员的安全培训大纲及考核标准由国家安全生产监督管理总局统一制定。 煤矿主要负责人和安全生产管理人员的安全培训大纲及考核标准由国家煤矿安全监察局制定。 煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼以外的其他生产经营单位主要负责人和安全管理人员的安全培训大纲及考核标准，由省、自治区、直辖市安全生产监督管理部门制定。"},{"i":11,"n":"第十一条","txt":"煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位必须对新上岗的临时工、合同工、劳务工、轮换工、协议工等进行强制性安全培训，保证其具备本岗位安全操作、自救互救以及应急处置所需的知识和技能后，方能安排上岗作业。"},{"i":12,"n":"第十二条","txt":"加工、制造业等生产单位的其他从业人员，在上岗前必须经过厂（矿）、车间（工段、区、队）、班组三级安全培训教育。 生产经营单位应当根据工作性质对其他从业人员进行安全培训，保证其具备本岗位安全操作、应急处置等知识和技能。"},{"i":13,"n":"第十三条","txt":"生产经营单位新上岗的从业人员，岗前安全培训时间不得少于24学时。 煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位新上岗的从业人员安全培训时间不得少于72学时，每年再培训的时间不得少于20学时。"},{"i":14,"n":"第十四条","txt":"厂（矿）级岗前安全培训内容应当包括： （一）本单位安全生产情况及安全生产基本知识； （二）本单位安全生产规章制度和劳动纪律； （三）从业人员安全生产权利和义务； （四）有关事故案例等。 煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位厂（矿）级安全培训除包括上述内容外，应当增加事故应急救援、事故应急预案演练及防范措施等内容。"},{"i":15,"n":"第十五条","txt":"车间（工段、区、队）级岗前安全培训内容应当包括： （一）　工作环境及危险因素； （二）　所从事工种可能遭受的职业伤害和伤亡事故； （三）　所从事工种的安全职责、操作技能及强制性标准； （四）自救互救、急救方法、疏散和现场紧急情况的处理； （五）安全设备设施、个人防护用品的使用和维护； （六）本车间（工段、区、队）安全生产状况及规章制度； （七）预防事故和职业危害的措施及应注意的安全事项； （八）有关事故案例； （九）其他需要培训的内容。"},{"i":16,"n":"第十六条","txt":"班组级岗前安全培训内容应当包括： （一）岗位安全操作规程； （二）岗位之间工作衔接配合的安全与职业卫生事项； （三）有关事故案例； （四）其他需要培训的内容。"},{"i":17,"n":"第十七条","txt":"从业人员在本生产经营单位内调整工作岗位或离岗一年以上重新上岗时，应当重新接受车间（工段、区、队）和班组级的安全培训。 生产经营单位采用新工艺、新技术、新材料或者使用新设备时，应当对有关从业人员重新进行有针对性的安全培训。"},{"i":18,"n":"第十八条","txt":"生产经营单位的特种作业人员，必须按照国家有关法律、法规的规定接受专门的安全培训，经考核合格，取得特种作业操作资格证书后，方可上岗作业。 特种作业人员的范围和培训考核管理办法，另行规定。"},{"i":19,"n":"第十九条","txt":"生产经营单位从业人员的安全培训工作，由生产经营单位组织实施。 生产经营单位应当坚持以考促学、以讲促学，确保全体从业人员熟练掌握岗位安全生产知识和技能；煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位还应当完善和落实师傅带徒弟制度。"},{"i":20,"n":"第二十条","txt":"具备安全培训条件的生产经营单位，应当以自主培训为主；可以委托具备安全培训条件的机构，对从业人员进行安全培训。 不具备安全培训条件的生产经营单位，应当委托具备安全培训条件的机构，对从业人员进行安全培训。 生产经营单位委托其他机构进行安全培训的，保证安全培训的责任仍由本单位负责。"},{"i":21,"n":"第二十一条","txt":"生产经营单位应当将安全培训工作纳入本单位年度工作计划。保证本单位安全培训工作所需资金。 生产经营单位的主要负责人负责组织制定并实施本单位安全培训计划。"},{"i":22,"n":"第二十二条","txt":"生产经营单位应当建立健全从业人员安全生产教育和培训档案，由生产经营单位的安全生产管理机构以及安全生产管理人员详细、准确记录培训的时间、内容、参加人员以及考核结果等情况。"},{"i":23,"n":"第二十三条","txt":"生产经营单位安排从业人员进行安全培训期间，应当支付工资和必要的费用。"},{"i":24,"n":"第二十四条","txt":"煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位主要负责人和安全生产管理人员，自任职之日起6个月内，必须经安全生产监管监察部门对其安全生产知识和管理能力考核合格。"},{"i":25,"n":"第二十五条","txt":"安全生产监管监察部门依法对生产经营单位安全培训情况进行监督检查，督促生产经营单位按照国家有关法律法规和本规定开展安全培训工作。 县级以上地方人民政府负责煤矿安全生产监督管理的部门对煤矿井下作业人员的安全培训情况进行监督检查。煤矿安全监察机构对煤矿特种作业人员安全培训及其持证上岗的情况进行监督检查。"},{"i":26,"n":"第二十六条","txt":"各级安全生产监管监察部门对生产经营单位安全培训及其持证上岗的情况进行监督检查，主要包括以下内容： （一）安全培训制度、计划的制定及其实施的情况； （二）煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位主要负责人和安全生产管理人员安全培训以及安全生产知识和管理能力考核的情况；其他生产经营单位主要负责人和安全生产管理人员培训的情况； （三）特种作业人员操作资格证持证上岗的情况； （四）建立安全生产教育和培训档案，并如实记录的情况； （五）对从业人员现场抽考本职工作的安全生产知识； （六）其他需要检查的内容。"},{"i":27,"n":"第二十七条","txt":"安全生产监管监察部门对煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位的主要负责人、安全管理人员应当按照本规定严格考核。考核不得收费。 安全生产监管监察部门负责考核的有关人员不得玩忽职守和滥用职权。"},{"i":28,"n":"第二十八条","txt":"安全生产监管监察部门检查中发现安全生产教育和培训责任落实不到位、有关从业人员未经培训合格的，应当视为生产安全事故隐患，责令生产经营单位立即停止违法行为，限期整改，并依法予以处罚。"},{"i":29,"n":"第二十九条","txt":"生产经营单位有下列行为之一的，由安全生产监管监察部门责令其限期改正，可以处1万元以上3万元以下的罚款： （一）未将安全培训工作纳入本单位工作计划并保证安全培训工作所需资金的； （二）从业人员进行安全培训期间未支付工资并承担安全培训费用的。"},{"i":30,"n":"第三十条","txt":"生产经营单位有下列行为之一的，由安全生产监管监察部门责令其限期改正，可以处5万元以下的罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款： （一）煤矿、非煤矿山、危险化学品、烟花爆竹、金属冶炼等生产经营单位主要负责人和安全管理人员未按照规定经考核合格的； （二）未按照规定对从业人员、被派遣劳动者、实习学生进行安全生产教育和培训或者未如实告知其有关安全生产事项的； （三）未如实记录安全生产教育和培训情况的； （四）特种作业人员未按照规定经专门的安全技术培训并取得特种作业人员操作资格证书，上岗作业的。 县级以上地方人民政府负责煤矿安全生产监督管理的部门发现煤矿未按照本规定对井下作业人员进行安全培训的，责令限期改正，处10万元以上50万元以下的罚款；逾期未改正的，责令停产停业整顿。 煤矿安全监察机构发现"},{"i":31,"n":"第三十一条","txt":"安全生产监管监察部门有关人员在考核、发证工作中玩忽职守、滥用职权的，由上级安全生产监管监察部门或者行政监察部门给予记过、记大过的行政处分。"},{"i":32,"n":"第三十二条","txt":"生产经营单位主要负责人是指有限责任公司或者股份有限公司的董事长、总经理，其他生产经营单位的厂长、经理、（矿务局）局长、矿长（含实际控制人）等。 生产经营单位安全生产管理人员是指生产经营单位分管安全生产的负责人、安全生产管理机构负责人及其管理人员，以及未设安全生产管理机构的生产经营单位专、兼职安全生产管理人员等。 生产经营单位其他从业人员是指除主要负责人、安全生产管理人员和特种作业人员以外，该单位从事生产经营活动的所有人员，包括其他负责人、其他管理人员、技术人员和各岗位的工人以及临时聘用的人员。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市安全生产监督管理部门和省级煤矿安全监察机构可以根据本规定制定实施细则，报国家安全生产监督管理总局和国家煤矿安全监察局备案。"},{"i":34,"n":"第三十四条","txt":"本规定自2006年3月1日起施行。"}],"shehuixiaofangjishufuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为规范社会消防技术服务活动，维护消防技术服务市场秩序，促进提高消防技术服务质量，根据《中华人民共和国消防法》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事社会消防技术服务活动、对消防技术服务机构实施监督管理，适用本规定。 本规定所称消防技术服务机构是指从事消防设施维护保养检测、消防安全评估等社会消防技术服务活动的企业。"},{"i":3,"n":"第三条","txt":"消防技术服务机构及其从业人员开展社会消防技术服务活动应当遵循客观独立、合法公正、诚实信用的原则。 本规定所称消防技术服务从业人员，是指依法取得注册消防工程师资格并在消防技术服务机构中执业的专业技术人员，以及按照有关规定取得相应消防行业特有工种职业资格，在消防技术服务机构中从事社会消防技术服务活动的人员。"},{"i":4,"n":"第四条","txt":"消防技术服务行业组织应当加强行业自律管理，规范从业行为，促进提升服务质量。 消防技术服务行业组织不得从事营利性社会消防技术服务活动，不得从事或者通过消防技术服务机构进行行业垄断。"},{"i":5,"n":"第五条","txt":"从事消防设施维护保养检测的消防技术服务机构，应当具备下列条件： （一）取得企业法人资格； （二）工作场所建筑面积不少于200平方米； （三）消防技术服务基础设备和消防设施维护保养检测设备配备符合有关规定要求； （四）注册消防工程师不少于2人，其中一级注册消防工程师不少于1人； （五）取得消防设施操作员国家职业资格证书的人员不少于6人，其中中级技能等级以上的不少于2人； （六）健全的质量管理体系。"},{"i":6,"n":"第六条","txt":"从事消防安全评估的消防技术服务机构，应当具备下列条件： （一）取得企业法人资格； （二）工作场所建筑面积不少于100平方米； （三）消防技术服务基础设备和消防安全评估设备配备符合有关规定要求； （四）注册消防工程师不少于2人，其中一级注册消防工程师不少于1人； （五）健全的消防安全评估过程控制体系。"},{"i":7,"n":"第七条","txt":"同时从事消防设施维护保养检测、消防安全评估的消防技术服务机构，应当具备下列条件： （一）取得企业法人资格； （二）工作场所建筑面积不少于200平方米； （三）消防技术服务基础设备和消防设施维护保养检测、消防安全评估设备配备符合规定的要求； （四）注册消防工程师不少于2人，其中一级注册消防工程师不少于1人； （五）取得消防设施操作员国家职业资格证书的人员不少于6人，其中中级技能等级以上的不少于2人； （六）健全的质量管理和消防安全评估过程控制体系。"},{"i":8,"n":"第八条","txt":"消防技术服务机构可以在全国范围内从业。"},{"i":9,"n":"第九条","txt":"消防技术服务机构及其从业人员应当依照法律法规、技术标准和从业准则，开展下列社会消防技术服务活动，并对服务质量负责： （一）消防设施维护保养检测机构可以从事建筑消防设施维护保养、检测活动； （二）消防安全评估机构可以从事区域消防安全评估、社会单位消防安全评估、大型活动消防安全评估等活动，以及消防法律法规、消防技术标准、火灾隐患整改、消防安全管理、消防宣传教育等方面的咨询活动。 消防技术服务机构出具的结论文件，可以作为消防救援机构实施消防监督管理和单位（场所）开展消防安全管理的依据。"},{"i":10,"n":"第十条","txt":"消防设施维护保养检测机构应当按照国家标准、行业标准规定的工艺、流程开展维护保养检测，保证经维护保养的建筑消防设施符合国家标准、行业标准。"},{"i":11,"n":"第十一条","txt":"消防技术服务机构应当依法与从业人员签订劳动合同，加强对所属从业人员的管理。注册消防工程师不得同时在两个以上社会组织执业。"},{"i":12,"n":"第十二条","txt":"消防技术服务机构应当设立技术负责人，对本机构的消防技术服务实施质量监督管理，对出具的书面结论文件进行技术审核。技术负责人应当具备一级注册消防工程师资格。"},{"i":13,"n":"第十三条","txt":"消防技术服务机构承接业务，应当与委托人签订消防技术服务合同，并明确项目负责人。项目负责人应当具备相应的注册消防工程师资格。 消防技术服务机构不得转包、分包消防技术服务项目。"},{"i":14,"n":"第十四条","txt":"消防技术服务机构出具的书面结论文件应当由技术负责人、项目负责人签名并加盖执业印章，同时加盖消防技术服务机构印章。 消防设施维护保养检测机构对建筑消防设施进行维护保养后，应当制作包含消防技术服务机构名称及项目负责人、维护保养日期等信息的标识，在消防设施所在建筑的醒目位置上予以公示。"},{"i":15,"n":"第十五条","txt":"消防技术服务机构应当对服务情况作出客观、真实、完整的记录，按消防技术服务项目建立消防技术服务档案。 消防技术服务档案保管期限为6年。"},{"i":16,"n":"第十六条","txt":"消防技术服务机构应当在其经营场所的醒目位置公示营业执照、工作程序、收费标准、从业守则、注册消防工程师注册证书、投诉电话等事项。"},{"i":17,"n":"第十七条","txt":"消防技术服务机构收费应当遵守价格管理法律法规的规定。"},{"i":18,"n":"第十八条","txt":"消防技术服务机构在从事社会消防技术服务活动中，不得有下列行为： （一）不具备从业条件，从事社会消防技术服务活动； （二）出具虚假、失实文件； （三）消防设施维护保养检测机构的项目负责人或者消防设施操作员未到现场实地开展工作； （四）泄露委托人商业秘密； （五）指派无相应资格从业人员从事社会消防技术服务活动； （六）冒用其他消防技术服务机构名义从事社会消防技术服务活动； （七）法律、法规、规章禁止的其他行为。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府消防救援机构依照有关法律、法规和本规定，对本行政区域内的社会消防技术服务活动实施监督管理。 消防技术服务机构及其从业人员对消防救援机构依法进行的监督管理应当协助和配合，不得拒绝或者阻挠。"},{"i":20,"n":"第二十条","txt":"应急管理部消防救援局应当建立和完善全国统一的社会消防技术服务信息系统，公布消防技术服务机构及其从业人员的有关信息，发布从业、诚信和监督管理信息，并为社会提供有关信息查询服务。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府消防救援机构对社会消防技术服务活动开展监督检查的形式有： （一）结合日常消防监督检查工作，对消防技术服务质量实施监督抽查； （二）根据需要实施专项检查； （三）发生火灾事故后实施倒查； （四）对举报投诉和交办移送的消防技术服务机构及其从业人员的违法从业行为进行核查。 开展社会消防技术服务活动监督检查可以根据实际需要，通过网上核查、服务单位实地核查、机构办公场所现场检查等方式实施。"},{"i":22,"n":"第二十二条","txt":"消防救援机构在对单位（场所）实施日常消防监督检查时，可以对为该单位（场所）提供服务的消防技术服务机构的服务质量实施监督抽查。抽查内容为： （一）是否冒用其他消防技术服务机构名义从事社会消防技术服务活动； （二）从事相关社会消防技术服务活动的人员是否具有相应资格； （三）是否按照国家标准、行业标准维护保养、检测建筑消防设施，经维护保养的建筑消防设施是否符合国家标准、行业标准； （四）消防设施维护保养检测机构的项目负责人或者消防设施操作员是否到现场实地开展工作； （五）是否出具虚假、失实文件； （六）出具的书面结论文件是否由技术负责人、项目负责人签名、盖章，并加盖消防技术服务机构印章； （七）是否与委托人签订消防技术服务合同； （八）是否在经其维护保养的消防设施所在建筑的醒目位置公示消防技术服务信息。"},{"i":23,"n":"第二十三条","txt":"消防救援机构根据消防监督管理需要，可以对辖区内从业的消防技术服务机构进行专项检查。专项检查应当随机抽取检查对象，随机选派检查人员，检查情况及查处结果及时向社会公开。专项检查可以抽查下列内容： （一）是否具备从业条件； （二）所属注册消防工程师是否同时在两个以上社会组织执业； （三）从事相关社会消防技术服务活动的人员是否具有相应资格； （四）是否转包、分包消防技术服务项目； （五）是否出具虚假、失实文件； （六）是否设立技术负责人、明确项目负责人，出具的书面结论文件是否由技术负责人、项目负责人签名、盖章，并加盖消防技术服务机构印章； （七）是否与委托人签订消防技术服务合同； （八）是否在经营场所公示营业执照、工作程序、收费标准、从业守则、注册消防工程师注册证书、投诉电话等事项； （九）是否建立和保管消防技术服务档案。"},{"i":24,"n":"第二十四条","txt":"发生有人员死亡或者造成重大社会影响的火灾，消防救援机构开展火灾事故调查时，应当对为起火单位（场所）提供服务的消防技术服务机构实施倒查。 消防救援机构组织调查其他火灾，可以根据需要对为起火单位（场所）提供服务的消防技术服务机构实施倒查。 倒查按照本规定第二十二条、第二十三条的抽查内容实施。"},{"i":25,"n":"第二十五条","txt":"消防救援机构及其工作人员不得设立消防技术服务机构，不得参与消防技术服务机构的经营活动，不得指定或者变相指定消防技术服务机构，不得利用职务接受有关单位或者个人财物，不得滥用行政权力排除、限制竞争。"},{"i":26,"n":"第二十六条","txt":"消防技术服务机构违反本规定，冒用其他消防技术服务机构名义从事社会消防技术服务活动的，责令改正，处2万元以上3万元以下罚款。"},{"i":27,"n":"第二十七条","txt":"消防技术服务机构违反本规定，有下列情形之一的，责令改正，处1万元以上2万元以下罚款： （一）所属注册消防工程师同时在两个以上社会组织执业的； （二）指派无相应资格从业人员从事社会消防技术服务活动的； （三）转包、分包消防技术服务项目的。 对有前款第一项行为的注册消防工程师，处5000元以上1万元以下罚款。"},{"i":28,"n":"第二十八条","txt":"消防技术服务机构违反本规定，有下列情形之一的，责令改正，处1万元以下罚款： （一）未设立技术负责人、未明确项目负责人的； （二）出具的书面结论文件未经技术负责人、项目负责人签名、盖章，或者未加盖消防技术服务机构印章的； （三）承接业务未依法与委托人签订消防技术服务合同的； （四）消防设施维护保养检测机构的项目负责人或者消防设施操作员未到现场实地开展工作的； （五）未建立或者保管消防技术服务档案的； （六）未公示营业执照、工作程序、收费标准、从业守则、注册消防工程师注册证书、投诉电话等事项的。"},{"i":29,"n":"第二十九条","txt":"消防技术服务机构不具备从业条件从事社会消防技术服务活动或者出具虚假文件、失实文件的，或者不按照国家标准、行业标准开展社会消防技术服务活动的，由消防救援机构依照《中华人民共和国消防法》第六十九条的有关规定处罚。"},{"i":30,"n":"第三十条","txt":"消防设施维护保养检测机构未按照本规定要求在经其维护保养的消防设施所在建筑的醒目位置上公示消防技术服务信息的，责令改正，处5000元以下罚款。"},{"i":31,"n":"第三十一条","txt":"消防救援机构对消防技术服务机构及其从业人员实施积分信用管理，具体办法由应急管理部消防救援局制定。"},{"i":32,"n":"第三十二条","txt":"消防技术服务机构有违反本规定的行为，给他人造成损失的，依法承担赔偿责任；经维护保养的建筑消防设施不能正常运行，发生火灾时未发挥应有作用，导致伤亡、损失扩大的，从重处罚；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"本规定中的行政处罚由违法行为地设区的市级、县级人民政府消防救援机构决定。"},{"i":34,"n":"第三十四条","txt":"消防技术服务机构及其从业人员对消防救援机构在消防技术服务监督管理中作出的具体行政行为不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":35,"n":"第三十五条","txt":"消防救援机构的工作人员设立消防技术服务机构，或者参与消防技术服务机构的经营活动，或者指定、变相指定消防技术服务机构，或者利用职务接受有关单位、个人财物，或者滥用行政权力排除、限制竞争，或者有其他滥用职权、玩忽职守、徇私舞弊的行为，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"保修期内的建筑消防设施由施工单位进行维护保养的，不适用本规定。"},{"i":37,"n":"第三十七条","txt":"本规定所称虚假文件，是指消防技术服务机构未提供服务或者以篡改结果方式出具的消防技术文件，或者出具的与当时实际情况严重不符、结论定性严重偏离客观实际的消防技术文件。 本规定所称失实文件，是指消防技术服务机构出具的与当时实际情况部分不符、结论定性部分偏离客观实际的消防技术文件。"},{"i":38,"n":"第三十八条","txt":"本规定中的“以上”、“以下”均含本数。"},{"i":39,"n":"第三十九条","txt":"执行本规定所需要的文书式样，以及消防技术服务机构应当配备的仪器、设备、设施目录，由应急管理部制定。"},{"i":40,"n":"第四十条","txt":"本规定自2021年11月9日起施行。"}],"jinshuyufeijinshukuangchanziyuandizhikantananquans21b581":[{"i":1,"n":"第一条","txt":"为加强金属与非金属矿产资源地质勘探作业安全的监督管理，预防和减少生产安全事故，根据安全生产法等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"从事金属与非金属矿产资源地质勘探作业的安全生产及其监督管理，适用本规定。 生产矿山企业的探矿活动不适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称地质勘探作业，是指在依法批准的勘查作业区范围内从事金属与非金属矿产资源地质勘探的活动。 本规定所称地质勘探单位，是指依法取得地质勘查资质并从事金属与非金属矿产资源地质勘探活动的企事业单位。"},{"i":4,"n":"第四条","txt":"地质勘探单位对本单位地质勘探作业安全生产负主体责任，其主要负责人对本单位的安全生产工作全面负责。 国务院有关部门和省、自治区、直辖市人民政府所属从事矿产地质勘探及管理的企事业法人组织（以下统称地质勘探主管单位），负责对其所属地质勘探单位的安全生产工作进行监督和管理。"},{"i":5,"n":"第五条","txt":"国家安全生产监督管理总局对全国地质勘探作业的安全生产工作实施监督管理。 县级以上地方各级人民政府安全生产监督管理部门对本行政区域内地质勘探作业的安全生产工作实施监督管理。"},{"i":6,"n":"第六条","txt":"地质勘探单位应当遵守有关安全生产法律、法规、规章、国家标准以及行业标准的规定，加强安全生产管理，排查治理事故隐患，确保安全生产。"},{"i":7,"n":"第七条","txt":"从事钻探工程、坑探工程施工的地质勘探单位应当取得安全生产许可证。"},{"i":8,"n":"第八条","txt":"地质勘探单位从事地质勘探活动，应当持本单位地质勘查资质证书和地质勘探项目任务批准文件或者合同书，向工作区域所在地县级安全生产监督管理部门书面报告，并接受其监督检查。"},{"i":9,"n":"第九条","txt":"地质勘探单位应当建立健全下列安全生产制度和规程： （一）主要负责人、分管负责人、安全生产管理人员和职能部门、岗位的安全生产责任制度； （二）岗位作业安全规程和工种操作规程； （三）现场安全生产检查制度； （四）安全生产教育培训制度； （五）重大危险源检测监控制度； （六）安全投入保障制度； （七）事故隐患排查治理制度； （八）事故信息报告、应急预案管理和演练制度； （九）劳动防护用品、野外救生用品和野外特殊生活用品配备使用制度； （十）安全生产考核和奖惩制度； （十一）其他必须建立的安全生产制度。"},{"i":10,"n":"第十条","txt":"地质勘探单位及其主管单位应当按照下列规定设置安全生产管理机构或者配备专职安全生产管理人员： （一）地质勘探单位从业人员超过100人的，应当设置安全生产管理机构，并按不低于从业人员1%的比例配备专职安全生产管理人员；从业人员在100人以下的，应当配备不少于2名的专职安全生产管理人员； （二）所属地质勘探单位从业人员总数在3000人以上的地质勘探主管单位，应当设置安全生产管理机构，并按不低于从业人员总数1‰的比例配备专职安全生产管理人员；从业人员总数在3000人以下的，应当设置安全生产管理机构或者配备不少于1名的专职安全生产管理人员。 专职安全生产管理人员中应当有注册安全工程师。"},{"i":11,"n":"第十一条","txt":"地质勘探单位的主要负责人和安全生产管理人员应当具备与本单位所从事地质勘探活动相适应的安全生产知识和管理能力，并经安全生产监督管理部门考核合格。 地质勘探单位的特种作业人员必须经专门的安全技术培训并考核合格，取得特种作业操作证后，方可上岗作业。"},{"i":12,"n":"第十二条","txt":"地质勘探单位从事坑探工程作业的人员，首次上岗作业前应当接受不少于72小时的安全生产教育和培训，以后每年应当接受不少于20小时的安全生产再培训。"},{"i":13,"n":"第十三条","txt":"地质勘探单位应当按照国家有关规定提取和使用安全生产费用。安全生产费用列入生产成本，并实行专户存储、规范使用。"},{"i":14,"n":"第十四条","txt":"地质勘探工程的设计、施工和安全管理应当符合《地质勘探安全规程》（AQ2004-2005）的规定。"},{"i":15,"n":"第十五条","txt":"坑探工程的设计方案中应当设有安全专篇。安全专篇应当经所在地安全生产监督管理部门审查同意；未经审查同意的，有关单位不得施工。 坑探工程安全专篇的具体审查办法由省、自治区、直辖市人民政府安全生产监督管理部门制定。"},{"i":16,"n":"第十六条","txt":"地质勘探单位不得将其承担的地质勘探工程项目转包给不具备安全生产条件或者相应地质勘查资质的地质勘探单位，不得允许其他单位以本单位的名义从事地质勘探活动。"},{"i":17,"n":"第十七条","txt":"地质勘探单位不得以探矿名义从事非法采矿活动。"},{"i":18,"n":"第十八条","txt":"地质勘探单位应当为从业人员配备必要的劳动防护用品、野外救生用品和野外特殊生活用品。"},{"i":19,"n":"第十九条","txt":"地质勘探单位应当根据本单位实际情况制定野外作业突发事件等安全生产应急预案，建立健全应急救援组织或者与邻近的应急救援组织签订救护协议，配备必要的应急救援器材和设备，按照有关规定组织开展应急演练。 应急预案应当按照有关规定报安全生产监督管理部门和地质勘探主管单位备案。"},{"i":20,"n":"第二十条","txt":"地质勘探主管单位应当按照国家有关规定，定期检查所属地质勘探单位落实安全生产责任制和安全生产费用提取使用、安全生产教育培训、事故隐患排查治理等情况，并组织实施安全生产绩效考核。"},{"i":21,"n":"第二十一条","txt":"地质勘探单位发生生产安全事故后，应当按照有关规定向事故发生地县级以上安全生产监督管理部门和地质勘探主管单位报告。"},{"i":22,"n":"第二十二条","txt":"安全生产监督管理部门应当加强对地质勘探单位安全生产的监督检查，对检查中发现的事故隐患和安全生产违法违规行为，依法作出现场处理或者实施行政处罚。"},{"i":23,"n":"第二十三条","txt":"安全生产监督管理部门应当建立完善地质勘探单位管理制度，及时掌握本行政区域内地质勘探单位的作业情况。"},{"i":24,"n":"第二十四条","txt":"安全生产监督管理部门应当按照本规定的要求开展对坑探工程安全专篇的审查，建立安全专篇审查档案。"},{"i":25,"n":"第二十五条","txt":"地质勘探单位有下列情形之一的，责令限期改正，可以处5万元以下的罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款： （一）未按照本规定设立安全生产管理机构或者配备专职安全生产管理人员的； （二）特种作业人员未持证上岗作业的； （三）从事坑探工程作业的人员未按照规定进行安全生产教育和培训的。"},{"i":26,"n":"第二十六条","txt":"地质勘探单位有下列情形之一的，给予警告，并处3万元以下的罚款： （一）未按照本规定建立有关安全生产制度和规程的； （二）未按照规定提取和使用安全生产费用的； （三）坑探工程安全专篇未经安全生产监督管理部门审查同意擅自施工的。"},{"i":27,"n":"第二十七条","txt":"地质勘探单位未按照规定向工作区域所在地县级安全生产监督管理部门书面报告的，给予警告，并处2万元以下的罚款。"},{"i":28,"n":"第二十八条","txt":"地质勘探单位将其承担的地质勘探工程项目转包给不具备安全生产条件或者相应资质的地质勘探单位的，责令限期改正，没收违法所得；违法所得10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；导致发生生产安全事故给他人造成损害的，与承包方承担连带赔偿责任。"},{"i":29,"n":"第二十九条","txt":"本规定规定的行政处罚由县级以上安全生产监督管理部门实施。"},{"i":30,"n":"第三十条","txt":"本规定自2011年1月1日起施行。"}],"jinshufeijinshudixiakuangshanqiyelingdaodaibanxiaja02a59":[{"i":1,"n":"第一条","txt":"为落实金属非金属地下矿山企业领导带班下井制度，强化现场安全管理，及时发现和消除事故隐患，根据《国务院关于进一步加强企业安全生产工作的通知》（国发〔2010〕23号）和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"金属非金属地下矿山企业（以下简称矿山企业）领导带班下井和县级以上安全生产监督管理部门对其实施监督检查，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称的矿山企业，是指金属非金属地下矿山生产企业及其所属各独立生产系统的矿井和新建、改建、扩建、技术改造等建设矿井。 本规定所称的矿山企业领导，是指矿山企业的主要负责人、领导班子成员和副总工程师。"},{"i":4,"n":"第四条","txt":"矿山企业是落实领导带班下井制度的责任主体，必须确保每个班次至少有1名领导在井下现场带班，并与工人同时下井、同时升井。 矿山企业的主要负责人对落实领导带班下井制度全面负责。"},{"i":5,"n":"第五条","txt":"安全生产监督管理部门对矿山企业落实领导带班下井制度情况进行监督检查，并依法作出现场处理或者实施行政处罚。 有关行业主管部门应当根据《国务院关于进一步加强企业安全生产工作的通知》的要求，按照各自职责做好矿山企业领导带班下井制度的落实工作，配合安全生产监督管理部门开展矿山企业领导带班下井情况的监督检查和考核奖惩等工作。"},{"i":6,"n":"第六条","txt":"任何单位和个人发现矿山企业领导未按照规定执行带班下井制度或者弄虚作假的，均有权向安全生产监督管理部门举报和报告。对举报和报告属实的，给予奖励。"},{"i":7,"n":"第七条","txt":"矿山企业应当建立健全领导带班下井制度，制定领导带班下井考核奖惩办法和月度计划，建立和完善领导带班下井档案。"},{"i":8,"n":"第八条","txt":"矿山企业领导带班下井月度计划，应当明确每个工作班次带班下井的领导名单、下井及升井的时间以及特殊情况下的请假与调换人员审批程序等内容。 领导带班下井月度计划应当在本单位网站和办公楼及矿井井口予以公告，接受群众监督。"},{"i":9,"n":"第九条","txt":"矿山企业应当每月对领导带班下井情况进行考核。领导带班下井情况与其经济收入挂钩，对按照规定带班下井并认真履行职责的，给予奖励；对未按照规定带班下井、冒名顶替下井或者弄虚作假的，按照有关规定予以处理。 矿山企业领导带班下井的月度计划完成情况，应当在矿山企业公示栏公示，接受群众监督。"},{"i":10,"n":"第十条","txt":"矿山企业领导带班下井时，应当履行下列职责： （一）加强对井下重点部位、关键环节的安全检查及检查巡视，全面掌握井下的安全生产情况； （二）及时发现和组织消除事故隐患和险情，及时制止违章违纪行为，严禁违章指挥，严禁超能力组织生产； （三）遇到险情时，立即下达停产撤人命令，组织涉险区域人员及时、有序撤离到安全地点。"},{"i":11,"n":"第十一条","txt":"矿山企业领导应当认真填写带班下井交接班记录，并向接班的领导详细说明井下安全生产状况、存在的主要问题及其处理情况、需要注意的事项等。"},{"i":12,"n":"第十二条","txt":"矿山企业领导升井后，应当及时将下井及升井的时间、地点、经过路线、发现的问题及处理结果等有关情况进行登记，以存档备查。"},{"i":13,"n":"第十三条","txt":"矿山企业从业人员应当遵章守纪，服从带班下井领导的指挥和管理。 矿山企业没有领导带班下井的，矿山企业从业人员有权拒绝下井作业。从业人员在井下作业过程中，发现并确认带班下井领导无故提前升井的，经向班组长或者队长说明后有权提前升井。 矿山企业不得因从业人员依据前款规定拒绝下井或者提前升井而降低从业人员工资、福利等待遇或者解除与其订立的劳动合同。"},{"i":14,"n":"第十四条","txt":"安全生产监督管理部门应当将矿山企业领导带班下井制度的建立、执行、考核、奖惩等情况作为安全监管的重要内容，并将其纳入年度安全监管执法工作计划，定期进行检查。"},{"i":15,"n":"第十五条","txt":"安全生产监督管理部门应当充分发挥电视、广播、报纸、网络等新闻媒体的作用，加强对本行政区域内矿山企业领导带班下井情况的社会监督。"},{"i":16,"n":"第十六条","txt":"安全生产监督管理部门应当建立举报制度，公开举报电话、信箱或者电子邮件地址，受理有关举报；对于受理的举报，应当认真调查核实；经查证属实的，依法从重处罚。"},{"i":17,"n":"第十七条","txt":"安全生产监督管理部门应当定期将矿山企业领导带班下井制度监督检查结果和处罚情况予以公告，接受社会监督。"},{"i":18,"n":"第十八条","txt":"矿山企业未按照规定建立健全领导带班下井制度或者未制定领导带班下井月度计划的，给予警告，并处3万元的罚款；对其主要负责人给予警告，并处1万元的罚款；情节严重的，依法暂扣其安全生产许可证，责令停产整顿。"},{"i":19,"n":"第十九条","txt":"矿山企业存在下列行为之一的，责令限期整改，并处3万元的罚款；对其主要负责人给予警告，并处1万元的罚款： （一）未制定领导带班下井制度的； （二）未按照规定公告领导带班下井月度计划的； （三）未按照规定公示领导带班下井月度计划完成情况的。"},{"i":20,"n":"第二十条","txt":"矿山企业领导未按照规定填写带班下井交接班记录、带班下井登记档案，或者弄虚作假的，给予警告，并处1万元的罚款。"},{"i":21,"n":"第二十一条","txt":"矿山企业领导未按照规定带班下井的，对矿山企业给予警告，处3万元的罚款；情节严重的，依法责令停产整顿；对违反规定的矿山企业领导按照擅离职守处理，并处1万元的罚款。"},{"i":22,"n":"第二十二条","txt":"对发生生产安全事故而没有领导带班下井的矿山企业，依法责令停产整顿，暂扣或者吊销安全生产许可证，并依照下列规定处以罚款；情节严重的，提请有关人民政府依法予以关闭： （一）发生一般事故，处50万元的罚款； （二）发生较大事故，处100万元的罚款； （三）发生重大事故，处500万元的罚款； （四）发生特别重大事故，处2000万元的罚款。"},{"i":23,"n":"第二十三条","txt":"对发生生产安全事故而没有领导带班下井的矿山企业，对其主要负责人依法暂扣或者吊销其安全资格证，并依照下列规定处以罚款： （一）发生一般事故，处上一年年收入30%的罚款； （二）发生较大事故，处上一年年收入40%的罚款； （三）发生重大事故，处上一年年收入60%的罚款； （四）发生特别重大事故，处上一年年收入80%的罚款。 对重大、特别重大生产安全事故负有主要责任的矿山企业，其主要负责人终身不得担任任何矿山企业的矿长（董事长、总经理）。"},{"i":24,"n":"第二十四条","txt":"各省、自治区、直辖市人民政府安全生产监督管理部门可以根据实际情况制定实施细则，报国家安全生产监督管理总局备案。"},{"i":25,"n":"第二十五条","txt":"为矿山企业提供采掘工程服务的采掘施工企业领导带班下井，按照本规定执行。"},{"i":26,"n":"第二十六条","txt":"本办法自2010年11月15日起施行。"}],"jinshufeijinshukuangshanjianshexiangmuanquansheshie9ea18":[{"i":1,"n":"第一条","txt":"为规范和指导金属非金属矿山（以下简称矿山）建设项目安全设施设计、设计审查和竣工验收工作，根据《中华人民共和国安全生产法》和《中华人民共和国矿山安全法》，制定本目录。"},{"i":2,"n":"第二条","txt":"矿山采矿和尾矿库建设项目安全设施适用本目录。与煤共（伴）生的矿山建设项目安全设施，还应满足煤矿相关的规程和规范。 核工业矿山尾矿库建设项目安全设施不适用本目录。"},{"i":3,"n":"第三条","txt":"本目录中列出的安全设施不是所有矿山都必须设置的，矿山企业应根据生产工艺流程、相关安全标准和规定，结合矿山实际情况设置相关安全设施。"},{"i":4,"n":"第四条","txt":"矿山安全设施是矿山企业为了预防生产安全事故而设置的设备、设施、装置、构（建）筑物和其他技术措施的总称，为矿山生产服务、保证安全生产的保护性设施。安全设施既有依附于主体工程的形式，也有独立于主体工程之外的形式。本目录将矿山建设项目安全设施分为基本安全设施和专用安全设施两部分。"},{"i":5,"n":"第五条","txt":"基本安全设施是依附于主体工程而存在，属于主体工程一部分的安全设施。基本安全设施是矿山安全的基本保证。"},{"i":6,"n":"第六条","txt":"专用安全设施是指除基本安全设施以外的， 以相对独立于主体工程之外的形式而存在，不具备生产功能，专用于安全保护作用的安全设施。"},{"i":7,"n":"第七条","txt":"依附于主体工程，且对矿山的安全至关重要，能够为矿山提供基本性安全保护作用的设备、设施、装置、构（建）筑物和其他技术措施，列为基本安全设施。"},{"i":8,"n":"第八条","txt":"地相对独立存在且不具备生产功能，只为保护人员安全，防止造成人员伤亡而专门设置的保护性设备、设施、装置、构（建）筑物和其他技术措施，列为专用安全设施。"},{"i":9,"n":"第九条","txt":"保安矿柱作为矿山开采安全中的重要技术措施列入基本安全设施。"},{"i":10,"n":"第十条","txt":"主体设备自带的安全装置，不列入本目录。"},{"i":11,"n":"第十一条","txt":"为保持工作场所的工作环境，保护作业人员职业健康的设施，属于职业卫生范畴，不列入本目录。"},{"i":12,"n":"第十二条","txt":"地面总降压变电所不列入本目录。"},{"i":13,"n":"第十三条","txt":"井下爆破器材库按照《民用爆破物品安全管理条例》（国务院令第466号）等法规、标准的规定进行设计、建设、使用和监管，不列入本目录。"},{"i":14,"n":"第十四条","txt":"在矿山建设期，仅专用安全设施建设费用可列入建设项目安全投资；在矿山生产期，补充、改善基本安全设施和专用安全设施的投资都可在企业安全生产费用中列支。"},{"i":15,"n":"第十五条","txt":"安全出口。 （一）通地表的安全出口，包括由明井（巷）和盲井（巷）组合形成的通地表的安全出口； （二）中段和分段的安全出口； （三）采场的安全出口； （四）破碎站、装矿皮带道和粉矿回收水平的安全出口。"},{"i":16,"n":"第十六条","txt":"安全通道和独立回风道。 （一）动力油硐室的独立回风道； （二）爆破器材库的独立回风道； （三）主水泵房的安全通道； （四）破碎硐室、变（配）电硐室的安全通道或独立回风道； （五）主溜井的安全检查通道。"},{"i":17,"n":"第十七条","txt":"人行道和缓坡段。 （一）各类巷道（含平巷、斜巷、斜井、斜坡道等）的人行道； （二）斜坡道的缓坡段。"},{"i":18,"n":"第十八条","txt":"支护。 （一）井筒支护； （二）巷道（含平巷、斜巷、斜井、斜坡道等）支护； （三）采场支护（包括采场顶板和侧帮、底部结构等的支护）； （四）硐室支护。"},{"i":19,"n":"第十九条","txt":"保安矿柱。 （一）境界矿柱； （二）井筒保安矿柱； （三）中段（分段）保安矿柱； （四）采场点柱、保安间柱等。"},{"i":20,"n":"第二十条","txt":"防治水。 （一）河流改道工程（含导流堤、明沟、隧洞、桥涵等）及河床加固； （二）地表截水沟、排洪沟（渠）、防洪堤； （三）地下水疏/堵工程及设施（含疏干井、放水孔、疏干巷道、防水闸门、水仓、疏干设备、防水矿柱、防渗帷幕及截渗墙等）； （四）露天开采转地下开采的矿山露天坑底防洪水突然灌入井下的设施（包括露天坑底所做的假底、坑底回填等）； （五）热水充水矿床的疏水系统。"},{"i":21,"n":"第二十一条","txt":"竖井提升系统。 （一）提升装置，包括制动系统、控制系统、闭锁装置等； （二）钢丝绳（包括提升钢丝绳、平衡钢丝绳、罐道钢丝绳、制动钢丝绳、隔离钢丝绳）及其连接或固定装置； （三）罐道，包括木罐道、型钢罐道、钢轨罐道、钢木复合罐道等； （四）提升容器； （五）摇台或其他承接装置。"},{"i":22,"n":"第二十二条","txt":"斜井提升系统。 （一）提升装置，包括制动系统、控制系统； （二）提升钢丝绳及其连接装置； （三）提升容器（含箕斗、矿车和人车）。"},{"i":23,"n":"第二十三条","txt":"电梯井提升系统（包括钢丝绳、罐道、轿厢、控制系统等）。"},{"i":24,"n":"第二十四条","txt":"带式输送机系统的各种闭锁和机械、电气保护装置。"},{"i":25,"n":"第二十五条","txt":"排水系统。 （一）主水仓、井底水仓、接力排水水仓； （二）主水泵房、接力泵房、各种排水水泵、排水管路、控制系统； （三）排水沟。"},{"i":26,"n":"第二十六条","txt":"通风系统。 （一）专用进风井及专用进风巷道； （二）专用回风井及专用回风巷道； （三）主通风机、控制系统。"},{"i":27,"n":"第二十七条","txt":"供、配电设施。 （一）矿山供电电源、线路及总降压主变压器容量、地表向井下供电电缆； （二）井下各级配电电压等级； （三）电气设备类型； （四）高、低压供配电中性点接地方式； （五）高、低压电缆； （六）提升系统、通风系统、排水系统的供配电设施； （七）地表架空线转下井电缆处防雷设施； （八）高压供配电系统继电保护装置； （九）低压配电系统故障（间接接触）防护装置； （十）直流牵引变电所电气保护设施、直流牵引网络安全措施； （十一）爆炸危险场所电机车轨道电气的安全措施； （十二）设有带油设备的电气硐室的安全措施； （十三）照明设施； （十四）工业场地边坡的安全加固及防护措施。"},{"i":28,"n":"第二十八条","txt":"罐笼提升系统。 （一）梯子间及安全护栏； （二）井口和井下马头门的安全门、阻车器和安全护栏； （三）尾绳隔离保护设施； （四）防过卷、防过放、防坠设施； （五）钢丝绳罐道时各中段的稳罐装置； （六）提升机房内的盖板、梯子和安全护栏； （七）井口门禁系统。"},{"i":29,"n":"第二十九条","txt":"箕斗提升系统。 （一）井口、装载站、卸载站等处的安全护栏； （二）尾绳隔离保护设施； （三）防过卷、防过放设施； （四）提升机房内的盖板、梯子和安全护栏。"},{"i":30,"n":"第三十条","txt":"混合竖井提升系统。 （一）罐笼提升系统安全设施（见罐笼提升系统）； （二）箕斗提升系统安全设施（见箕斗提升系统）； （三）混合井筒中的安全隔离设施。"},{"i":31,"n":"第三十一条","txt":"斜井提升系统。 （一）防跑车装置； （二）井口和井下马头门的安全门、阻车器、安全护栏和挡车设施； （三）人行道与轨道之间的安全隔离设施； （四）梯子和扶手； （五）躲避硐室； （六）人车断绳保险器； （七）轨道防滑措施； （八）提升机房内的安全护栏和梯子； （九）井口门禁系统。"},{"i":32,"n":"第三十二条","txt":"斜坡道与无轨运输巷道。 （一）躲避硐室； （二）卸载硐室的安全挡车设施、护栏； （三）人行巷道的水沟盖板； （四）交通信号系统； （五）井口门禁系统。"},{"i":33,"n":"第三十三条","txt":"带式输送机系统。 （一）设备的安全护罩； （二）安全护栏； （三）梯子、扶手。"},{"i":34,"n":"第三十四条","txt":"电梯井提升系统。。 （一）梯子间及安全护栏； （二）电梯间和梯子间进口的安全防护网。"},{"i":35,"n":"第三十五条","txt":"有轨运输系统。 （一）装载站和卸载站的安全护栏； （二）人行巷道的水沟盖板。"},{"i":36,"n":"第三十六条","txt":"动力油储存硐室。 （一）硐室口的防火门； （二）栅栏门； （三）防静电措施； （四）防爆照明设施。"},{"i":37,"n":"第三十七条","txt":"破碎硐室。 （一）设备护罩、梯子和安全护栏； （二）自卸车卸矿点的安全挡车设施。"},{"i":38,"n":"第三十八条","txt":"采场。 （一）采空区及其他危险区域的探测、封闭、隔离或充填设施； （二）地下原地浸出采矿和原地爆破浸出采矿的防渗工程及对溶液渗透的监测系统； （三）原地浸出采矿引起地表塌陷、滑坡的防护及治理措施； （四）自动化作业采区的安全门； （五）爆破安全设施（含警示旗、报警器、警戒带等）； （六）工作面人机隔离设施。"},{"i":39,"n":"第三十九条","txt":"人行天井与溜井。 （一）梯子间及防护网、隔离栅栏； （二）井口安全护栏； （三）废弃井口的封闭或隔离设施； （四）溜井井口安全挡车设施； （五）溜井口格筛。"},{"i":40,"n":"第四十条","txt":"供、配电设施。 （一）避灾硐室应急供电设施； （二）裸带电体基本（直接接触）防护设施； （三）变配电硐室防水门、防火门、栅栏门； （四）保护接地及等电位联接设施； （五）牵引变电所接地设施； （六）变配电硐室应急照明设施； （七）地面建筑物防雷设施。"},{"i":41,"n":"第四十一条","txt":"通风和空气预热及制冷降温。 （一）主通风机的反风设施和备用电机及快速更换装置； （二）辅助通风机； （三）局部通风机； （四）风机进风口的安全护栏和防护网； （五）阻燃风筒； （六）通风构筑物（含风门、风墙、风窗、风桥等）； （七）风井内的梯子间； （八）风井井口和马头门处的安全护栏； （九）严寒地区，通地表的井口（如罐笼井、箕斗井、混合井和斜提升井等）设置的防冻设施；用于进风的井口和巷道硐口（如专用进风井、专用进风平硐、专用进风斜井、罐笼井、混合井、斜提升井、胶带斜井、斜坡道、运输巷道等）设置的空气预热设施； （十）地下高温矿山制冷降温设施，包括地表制冷站设施、地下制冷站设施、管路及分配设施等。"},{"i":42,"n":"第四十二条","txt":"排水系统。 （一）监测与控制设施； （二）水泵房及毗连的变电所（或中央变电所）入口的防水门及两者之间的防火门； （三）水泵房及变电所内的盖板、安全护栏（门）。"},{"i":43,"n":"第四十三条","txt":"充填系统。 （一）充填管路减压设施； （二）充填管路压力监测装置； （三）充填管路排气设施； （四）充填搅拌站内及井下的安全护栏及其他防护措施（包括物料输送机和其他相关设备、砂浆池、砂仓等的安全护栏及其他防护措施）； （五）充填系统事故池； （六）采场充填挡墙。"},{"i":44,"n":"第四十四条","txt":"地压、岩体位移监测系统。 （一）地表变形、塌陷监测系统； （二）坑内应力、应变监测系统。"},{"i":45,"n":"第四十五条","txt":"安全避险“六大系统”。 （一）监测监控系统； （二）人员定位系统； （三）紧急避险系统； （四）压风自救系统； （五）供水施救系统； （六）通信联络系统。"},{"i":46,"n":"第四十六条","txt":"消防系统。 （一）消防供水系统； （二）消防水池； （三）消防器材； （四）火灾报警系统； （五）防火门（除前面所述之外的防火门）； （六）有自然发火倾向区域的防火隔离设施。"},{"i":47,"n":"第四十七条","txt":"防治水。 （一）中段（分段）或采区的防水门； （二）地下水头（水位）、水质、中段涌水量监测设施； （三）探水孔、放水孔及探放水巷道，探、放水孔的孔口管和控制闸阀，探、放水设备； （四）降雨量观测站； （五）在有突水可能性的工作面设置的救生圈、安全绳等救生设施。"},{"i":48,"n":"第四十八条","txt":"崩落法、空场法开采时的地表塌陷或移动范围保护措施。"},{"i":49,"n":"第四十九条","txt":"水溶性开采。 （一）有毒有害气体积聚处（井口、卤池、取样阀等）采取的防毒措施； （二）井口的防喷装置； （三）排水和防止液体渗漏的设施； （四）地面防滑措施； （五）井盐矿山设立的地表水和地下水水质监测系统； （六）地表沉降和位移的监测设施； （七）不用的地质勘探井和生产报废井的封井措施。"},{"i":50,"n":"第五十条","txt":"矿山应急救援设备及器材。"},{"i":51,"n":"第五十一条","txt":"个人安全防护用品。"},{"i":52,"n":"第五十二条","txt":"矿山、交通、电气安全标志。"},{"i":53,"n":"第五十三条","txt":"其他设施。 （一）排土场（或废石场）安全设施参见露天矿山相关内容； （二）放射性矿山的防护措施； （三）地下原地浸出采矿：监测井（孔）、套管、气体站安全护栏、集液池、酸液池及二次缓冲池安全护栏、事故处理池和管路。"},{"i":54,"n":"第五十四条","txt":"露天采场。 （一）安全平台、清扫平台、运输平台； （二）运输道路的缓坡段； （三）露天采场边坡、道路边坡、破碎站和工业场地边坡的安全加固及防护措施； （四）溜井底放矿硐室的安全通道及井口的安全挡车设施、格筛； （五）设计规定保留的矿（岩）体或矿段； （六）边坡角； （七）爆破安全距离界线。"},{"i":55,"n":"第五十五条","txt":"防排水。 （一）河流改道工程（含导流堤、明沟、隧洞、桥涵等）及河床加固； （二）地表截水沟、排洪沟（渠）、防洪堤、拦水坝、台阶排水沟、截排水隧洞、沉砂池、消能池（坝）； （三）地下水疏/堵工程及设施（含疏干井、放水孔、疏干巷道、防水闸门、水仓、疏干设备、防水矿柱、防渗帷幕及截渗墙等）； （四）露天采场排水设施，包括水泵和管路。"},{"i":56,"n":"第五十六条","txt":"铁路运输。 （一）运输线路的安全线、避让线、制动检查所、线路两侧的界限架； （二）护轮轨、防溜车措施、减速器、阻车器。"},{"i":57,"n":"第五十七条","txt":"带式输送机系统的各种闭锁和电气保护装置。"},{"i":58,"n":"第五十八条","txt":"架空索道运输。 （一）架空索道的承载钢丝绳和牵引钢丝绳； （二）架空索道的制动系统； （三）架空索道的控制系统。"},{"i":59,"n":"第五十九条","txt":"斜坡卷扬运输。 （一）提升装置，包括制动系统、控制系统； （二）提升钢丝绳及其连接装置； （三）提升容器（包括箕斗、矿车和人车）。"},{"i":60,"n":"第六十条","txt":"供、配电设施。 （一）矿山供电电源、线路及总降压主变压器容量、向采矿场供电线路； （二）各级配电电压等级； （三）电气设备类型； （四）高、低压供配电中性点接地方式； （五）排水系统供配电设施； （六）采矿场供电线路、电缆及保护、避雷设施； （七）高压供配电系统继电保护装置； （八）低压配电系统故障（间接接触）防护装置； （九）直流牵引变电所的电气保护设施、直流牵引网络的安全措施； （十）爆炸危险场所电机车轨道的电气安全措施； （十一）变、配电室的金属丝网门； （十二）采场及排土场（废石场）正常照明设施。"},{"i":61,"n":"第六十一条","txt":"排土场（废石场）。 （一）安全平台； （二）运输道路缓坡段； （三）拦渣坝； （四）阶段高度、总堆置高度、安全平台宽度、总边坡角。"},{"i":62,"n":"第六十二条","txt":"通信系统。 （一）联络通信系统； （二）信号系统； （三）监视监控系统。"},{"i":63,"n":"第六十三条","txt":"露天采场。 （一）露天采场所设的边界安全护栏； （二）废弃巷道、采空区和溶洞的探测设备，充填、封堵措施或隔离设施； （三）溜井口的安全护栏、挡车设施、格筛； （四）爆破安全设施（含躲避设施、警示旗、报警器、警戒带等）； （五）水力开采运矿沟槽上的盖板或金属网； （六）挖掘船上的救护设备； （七）挖掘船开采时，作业人员穿戴的救生器材。"},{"i":64,"n":"第六十四条","txt":"铁路运输。 （一）运输线路的安全护栏、防护网、挡车设施、道口护栏； （二）道路岔口交通警示报警设施； （三）陡坡铁路运输时的线路防爬设施（含防爬器、抗滑桩等）； （四）曲线轨道加固措施。"},{"i":65,"n":"第六十五条","txt":"汽车运输。 （一）运输线路的安全护栏、挡车设施、错车道、避让道、紧急避险道、声光报警装置； （二）矿、岩卸载点的安全挡车设施。"},{"i":66,"n":"第六十六条","txt":"带式输送机运输。 （一）设备的安全护罩； （二）安全护栏； （三）梯子、扶手。"},{"i":67,"n":"第六十七条","txt":"架空索道运输。 （一）线路经过厂区、居民区、铁路、道路时的安全防护措施； （二）线路与电力、通讯架空线交叉时的安全防护措施； （三）站房安全护栏。"},{"i":68,"n":"第六十八条","txt":"斜坡卷扬运输。 （一）阻车器、安全挡车设施； （二）斜坡轨道两侧的堑沟、安全隔挡设施； （三）防止跑车装置； （四）防止钢轨及轨梁整体下滑的措施。"},{"i":69,"n":"第六十九条","txt":"破碎站。 （一）卸矿安全挡车设施； （二）设备运动部分的护罩、安全护栏； （三）安全护栏、盖板、扶手、防滑钢板。"},{"i":70,"n":"第七十条","txt":"排土场（废石场）。 （一）排土场（废石场）道路的安全护栏、挡车设施； （二）截（排）水设施（含截水沟、排水沟、排水隧洞、截洪坝等）； （三）底部排渗设施； （四）滚石或泥石流拦挡设施； （五）滑坡治理措施； （六）坍塌与沉陷防治措施； （七）地基处理。"},{"i":71,"n":"第七十一条","txt":"供、配电设施。 （一）裸带电体基本（直接接触）防护设施； （二）保护接地设施； （三）直流牵引变电所接地设施； （四）采场变、配电室应急照明设施； （五）地面建筑物防雷设施。"},{"i":72,"n":"第七十二条","txt":"监测设施。 （一）采场边坡监测设施； （二）排土场（废石场）边坡监测设施。"},{"i":73,"n":"第七十三条","txt":"为防治水而设的水位和流量监测系统。"},{"i":74,"n":"第七十四条","txt":"矿山应急救援器材及设备。"},{"i":75,"n":"第七十五条","txt":"个人安全防护用品。"},{"i":76,"n":"第七十六条","txt":"矿山、交通、电气安全标志。"},{"i":77,"n":"第七十七条","txt":"有井巷工程时其安全设施参见地下矿山相关内容。"},{"i":78,"n":"第七十八条","txt":"尾矿坝。 （一）初期坝（含库尾排矿干式尾矿库的拦挡坝）； （二）堆积坝； （三）副坝； （四）挡水坝； （五）一次性建坝的尾矿坝。"},{"i":79,"n":"第七十九条","txt":"尾矿库库内排水设施。 （一）排水井； （二）排水斜槽； （三）排水隧洞； （四）排水管； （五）溢洪道； （六）消力池。"},{"i":80,"n":"第八十条","txt":"尾矿库库周截排洪设施。 （一）拦洪坝； （二）截洪沟； （三）排水井； （四）排洪隧洞； （五）溢洪道； （六）消力池。"},{"i":81,"n":"第八十一条","txt":"堆积坝坝面防护设施。 （一）堆积坝护坡； （二）坝面排水沟； （三）坝肩截水沟。"},{"i":82,"n":"第八十二条","txt":"辅助设施。 （一）尾矿库交通道路； （二）尾矿库照明设施； （三）通信设施。"},{"i":83,"n":"第八十三条","txt":"尾矿库地质灾害与雪崩防护设施。 （一）尾矿库泥石流防护设施； （二）库区滑坡治理设施； （三）库区岩溶治理设施； （四）高寒地区的雪崩防护设施。"},{"i":84,"n":"第八十四条","txt":"尾矿库安全监测设施。 （一）库区气象监测设施； （二）地质灾害监测设施； （三）库水位监测设施； （四）干滩监测设施； （五）坝体表面位移监测设施； （六）坝体内部位移监测设施； （七）坝体渗流监测设施； （八）视频监控设施； （九）在线监测中心。"},{"i":85,"n":"第八十五条","txt":"尾矿坝坝体排渗设施。 （一）贴坡排渗； （二）自流式排渗管； （三）管井排渗； （四）垂直-水平联合自流排渗； （五）虹吸排渗； （六）辐射井； （七）排渗褥垫； （八）排渗盲沟（管）。"},{"i":86,"n":"第八十六条","txt":"干式尾矿汽车运输。 （一）运输线路的安全护栏、挡车设施； （二）汽车避让道； （三）卸料平台的安全挡车设施。"},{"i":87,"n":"第八十七条","txt":"干式尾矿带式输送机运输。 （一）输送机系统的各种闭锁和电气保护装置； （二）设备的安全护罩； （三）安全护栏； （四）梯子、扶手。"},{"i":88,"n":"第八十八条","txt":"库内回水浮船、运输船防护设施。 （一）安全护栏； （二）救生器材； （三）浮船固定设施； （四）电气设备接地措施。"},{"i":89,"n":"第八十九条","txt":"辅助设施。 （一）尾矿库管理站； （二）报警系统； （三）库区安全护栏； （四）矿山、交通、电气安全标志。"},{"i":90,"n":"第九十条","txt":"应急救援器材及设备。"},{"i":91,"n":"第九十一条","txt":"个人安全防护用品。"}],"feimeikuangshanwaibaogongchenganquanguanlizanxingbf1b284":[{"i":1,"n":"第一条","txt":"为了加强非煤矿山外包工程的安全管理和监督，明确安全生产责任，防止和减少生产安全事故（以下简称事故），依据《中华人民共和国安全生产法》、《中华人民共和国矿山安全法》和其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在依法批准的矿区范围内，以外包工程的方式从事金属非金属矿山的勘探、建设、生产、闭坑等工程施工作业活动，以及石油天然气的勘探、开发、储运等工程与技术服务活动的安全管理和监督，适用本办法。 从事非煤矿山各类房屋建筑及其附属设施的建造和安装，以及露天采矿场矿区范围以外地面交通建设的外包工程的安全管理和监督，不适用本办法。"},{"i":3,"n":"第三条","txt":"非煤矿山外包工程（以下简称外包工程）的安全生产，由发包单位负主体责任，承包单位对其施工现场的安全生产负责。 外包工程有多个承包单位的，发包单位应当对多个承包单位的安全生产工作实施统一协调、管理，定期进行安全检查，发现安全问题的，应当及时督促整改。"},{"i":4,"n":"第四条","txt":"承担外包工程的勘察单位、设计单位、监理单位、技术服务机构及其他有关单位应当依照法律、法规、规章和国家标准、行业标准的规定，履行各自的安全生产职责，承担相应的安全生产责任。"},{"i":5,"n":"第五条","txt":"非煤矿山企业应当建立外包工程安全生产的激励和约束机制，提升非煤矿山外包工程安全生产管理水平。"},{"i":6,"n":"第六条","txt":"发包单位应当依法设置安全生产管理机构或者配备专职安全生产管理人员，对外包工程的安全生产实施管理和监督。 发包单位不得擅自压缩外包工程合同约定的工期，不得违章指挥或者强令承包单位及其从业人员冒险作业。 发包单位应当依法取得非煤矿山安全生产许可证。"},{"i":7,"n":"第七条","txt":"发包单位应当审查承包单位的非煤矿山安全生产许可证和相应资质，不得将外包工程发包给不具备安全生产许可证和相应资质的承包单位。 承包单位的项目部承担施工作业的，发包单位除审查承包单位的安全生产许可证和相应资质外，还应当审查项目部的安全生产管理机构、规章制度和操作规程、工程技术人员、主要设备设施、安全教育培训和负责人、安全生产管理人员、特种作业人员持证上岗等情况。 承担施工作业的项目部不符合本办法第二十一条规定的安全生产条件的，发包单位不得向该承包单位发包工程。"},{"i":8,"n":"第八条","txt":"发包单位应当与承包单位签订安全生产管理协议，明确各自的安全生产管理职责。安全生产管理协议应当包括下列内容： （一）安全投入保障； （二）安全设施和施工条件； （三）隐患排查与治理； （四）安全教育与培训； （五）事故应急救援； （六）安全检查与考评； （七）违约责任。 安全生产管理协议的文本格式由国家安全生产监督管理总局另行制定。"},{"i":9,"n":"第九条","txt":"发包单位是外包工程安全投入的责任主体，应当按照国家有关规定和合同约定及时、足额向承包单位提供保障施工作业安全所需的资金，明确安全投入项目和金额，并监督承包单位落实到位。 对合同约定以外发生的隐患排查治理和地下矿山通风、支护、防治水等所需的费用，发包单位应当提供合同价款以外的资金，保障安全生产需要。"},{"i":10,"n":"第十条","txt":"石油天然气总发包单位、分项发包单位以及金属非金属矿山总发包单位，应当每半年对其承包单位的施工资质、安全生产管理机构、规章制度和操作规程、施工现场安全管理和履行本办法第二十七条规定的信息报告义务等情况进行一次检查；发现承包单位存在安全生产问题的，应当督促其立即整改。"},{"i":11,"n":"第十一条","txt":"金属非金属矿山分项发包单位，应当将承包单位及其项目部纳入本单位的安全管理体系，实行统一管理，重点加强对地下矿山领导带班下井、地下矿山从业人员出入井统计、特种作业人员、民用爆炸物品、隐患排查与治理、职业病防护等管理，并对外包工程的作业现场实施全过程监督检查。"},{"i":12,"n":"第十二条","txt":"金属非金属矿山总发包单位对地下矿山一个生产系统进行分项发包的，承包单位原则上不得超过3家，避免相互影响生产、作业安全。 前款规定的发包单位在地下矿山正常生产期间，不得将主通风、主提升、供排水、供配电、主供风系统及其设备设施的运行管理进行分项发包。"},{"i":13,"n":"第十三条","txt":"发包单位应当向承包单位进行外包工程的技术交底，按照合同约定向承包单位提供与外包工程安全生产相关的勘察、设计、风险评价、检测检验和应急救援等资料，并保证资料的真实性、完整性和有效性。"},{"i":14,"n":"第十四条","txt":"发包单位应当建立健全外包工程安全生产考核机制，对承包单位每年至少进行一次安全生产考核。"},{"i":15,"n":"第十五条","txt":"发包单位应当按照国家有关规定建立应急救援组织，编制本单位事故应急预案，并定期组织演练。 外包工程实行总发包的，发包单位应当督促总承包单位统一组织编制外包工程事故应急预案；实行分项发包的，发包单位应当将承包单位编制的外包工程现场应急处置方案纳入本单位应急预案体系，并定期组织演练。"},{"i":16,"n":"第十六条","txt":"发包单位在接到外包工程事故报告后，应当立即启动相关事故应急预案，或者采取有效措施，组织抢救，防止事故扩大，并依照《生产安全事故报告和调查处理条例》的规定，立即如实地向事故发生地县级以上人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门报告。 外包工程发生事故的，其事故数据纳入发包单位的统计范围。 发包单位和承包单位应当根据事故调查报告及其批复承担相应的事故责任。"},{"i":17,"n":"第十七条","txt":"承包单位应当依照有关法律、法规、规章和国家标准、行业标准的规定，以及承包合同和安全生产管理协议的约定，组织施工作业，确保安全生产。 承包单位有权拒绝发包单位的违章指挥和强令冒险作业。"},{"i":18,"n":"第十八条","txt":"外包工程实行总承包的，总承包单位对施工现场的安全生产负总责；分项承包单位按照分包合同的约定对总承包单位负责。总承包单位和分项承包单位对分包工程的安全生产承担连带责任。 总承包单位依法将外包工程分包给其他单位的，其外包工程的主体部分应当由总承包单位自行完成。 禁止承包单位转包其承揽的外包工程。禁止分项承包单位将其承揽的外包工程再次分包。"},{"i":19,"n":"第十九条","txt":"承包单位应当依法取得非煤矿山安全生产许可证和相应等级的施工资质，并在其资质范围内承包工程。 承包金属非金属矿山建设和闭坑工程的资质等级，应当符合《建筑业企业资质等级标准》的规定。 承包金属非金属矿山生产、作业工程的资质等级，应当符合下列要求： （一）总承包大型地下矿山工程和深凹露天、高陡边坡及地质条件复杂的大型露天矿山工程的，具备矿山工程施工总承包二级以上（含本级，下同）施工资质； （二）总承包中型、小型地下矿山工程的，具备矿山工程施工总承包三级以上施工资质； （三）总承包其他露天矿山工程和分项承包金属非金属矿山工程的，具备矿山工程施工总承包或者相关的专业承包资质，具体规定由省级人民政府安全生产监督管理部门制定。 承包尾矿库外包工程的资质，应当符合《尾矿库安全监督管理规定》。 承包金属非金属矿山地质勘探工程的资质等级，应当符合《金属与非金属矿产资源地质勘探安全生产监督管理暂行规定》。"},{"i":20,"n":"第二十条","txt":"承包单位应当加强对所属项目部的安全管理，每半年至少进行一次安全生产检查，对项目部人员每年至少进行一次安全生产教育培训与考核。 禁止承包单位以转让、出租、出借资质证书等方式允许他人以本单位的名义承揽工程。"},{"i":21,"n":"第二十一条","txt":"承包单位及其项目部应当根据承揽工程的规模和特点，依法健全安全生产责任体系，完善安全生产管理基本制度，设置安全生产管理机构，配备专职安全生产管理人员和有关工程技术人员。 承包地下矿山工程的项目部应当配备与工程施工作业相适应的专职工程技术人员，其中至少有1名注册安全工程师或者具有5年以上井下工作经验的安全生产管理人员。项目部具备初中以上文化程度的从业人员比例应当不低于50%。 项目部负责人应当取得安全生产管理人员安全资格证。承包地下矿山工程的项目部负责人不得同时兼任其他工程的项目部负责人。"},{"i":22,"n":"第二十二条","txt":"承包单位应当依照法律、法规、规章的规定以及承包合同和安全生产管理协议的约定，及时将发包单位投入的安全资金落实到位，不得挪作他用。"},{"i":23,"n":"第二十三条","txt":"承包单位应当依照有关规定制定施工方案，加强现场作业安全管理，及时发现并消除事故隐患，落实各项规章制度和安全操作规程。 承包单位发现事故隐患后应当立即治理；不能立即治理的应当采取必要的防范措施，并及时书面报告发包单位协商解决，消除事故隐患。 地下矿山工程承包单位及其项目部的主要负责人和领导班子其他成员应当严格依照《金属非金属地下矿山企业领导带班下井及监督检查暂行规定》执行带班下井制度。"},{"i":24,"n":"第二十四条","txt":"承包单位应当接受发包单位组织的安全生产培训与指导，加强对本单位从业人员的安全生产教育和培训，保证从业人员掌握必需的安全生产知识和操作技能。"},{"i":25,"n":"第二十五条","txt":"外包工程实行总承包的，总承包单位应当统一组织编制外包工程应急预案。总承包单位和分项承包单位应当按照国家有关规定和应急预案的要求，分别建立应急救援组织或者指定应急救援人员，配备救援设备设施和器材，并定期组织演练。 外包工程实行分项承包的，分项承包单位应当根据建设工程施工的特点、范围以及施工现场容易发生事故的部位和环节，编制现场应急处置方案，并配合发包单位定期进行演练。"},{"i":26,"n":"第二十六条","txt":"外包工程发生事故后，事故现场有关人员应当立即向承包单位及项目部负责人报告。 承包单位及项目部负责人接到事故报告后，应当立即如实地向发包单位报告，并启动相应的应急预案，采取有效措施，组织抢救，防止事故扩大。"},{"i":27,"n":"第二十七条","txt":"承包单位在登记注册地以外的省、自治区、直辖市从事施工作业的，应当向作业所在地的县级人民政府安全生产监督管理部门书面报告外包工程概况和本单位资质等级、主要负责人、安全生产管理人员、特种作业人员、主要安全设施设备等情况，并接受其监督检查。"},{"i":28,"n":"第二十八条","txt":"承包单位发生较大以上责任事故或者一年内发生三起以上一般事故的，事故发生地的省级人民政府安全生产监督管理部门应当向承包单位登记注册地的省级人民政府安全生产监督管理部门通报。 发生重大以上事故的，事故发生地省级人民政府安全生产监督管理部门应当邀请承包单位的安全生产许可证颁发机关参加事故调查处理工作。"},{"i":29,"n":"第二十九条","txt":"安全生产监督管理部门应当加强对外包工程的安全生产监督检查，重点检查下列事项： （一）发包单位非煤矿山安全生产许可证、安全生产管理协议、安全投入等情况； （二）承包单位的施工资质、应当依法取得的非煤矿山安全生产许可证、安全投入落实、承包单位及其项目部的安全生产管理机构、技术力量配备、相关人员的安全资格和持证等情况； （三）违法发包、转包、分项发包等行为。"},{"i":30,"n":"第三十条","txt":"安全生产监督管理部门应当建立外包工程安全生产信息平台，将承包单位取得有关许可、施工资质和承揽工程、发生事故等情况载入承包单位安全生产业绩档案，实施安全生产信誉评定和公告制度。"},{"i":31,"n":"第三十一条","txt":"外包工程发生事故的，事故数据应当纳入事故发生地的统计范围。"},{"i":32,"n":"第三十二条","txt":"发包单位违反本办法第六条的规定，违章指挥或者强令承包单位及其从业人员冒险作业的，责令改正，处2万元以上3万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":33,"n":"第三十三条","txt":"发包单位与承包单位、总承包单位与分项承包单位未依照本办法第八条规定签订安全生产管理协议的，责令限期改正，可以处5万元以下的罚款，对其直接负责的主管人员和其他直接责任人员可以处以1万元以下罚款；逾期未改正的，责令停产停业整顿。"},{"i":34,"n":"第三十四条","txt":"有关发包单位有下列行为之一的，责令限期改正，给予警告，并处1万元以上3万元以下的罚款： （一）违反本办法第十条、第十四条的规定，未对承包单位实施安全生产监督检查或者考核的； （二）违反本办法第十一条的规定，未将承包单位及其项目部纳入本单位的安全管理体系，实行统一管理的； （三）违反本办法第十三条的规定，未向承包单位进行外包工程技术交底，或者未按照合同约定向承包单位提供有关资料的。"},{"i":35,"n":"第三十五条","txt":"对地下矿山实行分项发包的发包单位违反本办法第十二条的规定，在地下矿山正常生产期间，将主通风、主提升、供排水、供配电、主供风系统及其设备设施的运行管理进行分项发包的，责令限期改正，处2万元以上3万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"承包地下矿山工程的项目部负责人违反本办法第二十一条的规定，同时兼任其他工程的项目部负责人的，责令限期改正，处5000元以上1万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"承包单位违反本办法第二十二条的规定，将发包单位投入的安全资金挪作他用的，责令限期改正，给予警告，并处1万元以上3万元以下罚款。 承包单位未按照本办法第二十三条的规定排查治理事故隐患的，责令立即消除或者限期消除；承包单位拒不执行的，责令停产停业整顿，并处10万元以上50万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"承包单位违反本办法第二十条规定对项目部疏于管理，未定期对项目部人员进行安全生产教育培训与考核或者未对项目部进行安全生产检查的，责令限期改正，可以处5万元以下的罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款。 承包单位允许他人以本单位的名义承揽工程的，移送有关部门依法处理。"},{"i":39,"n":"第三十九条","txt":"承包单位违反本办法第二十七条的规定，在登记注册的省、自治区、直辖市以外从事施工作业，未向作业所在地县级人民政府安全生产监督管理部门书面报告本单位取得有关许可和施工资质，以及所承包工程情况的，责令限期改正，处1万元以上3万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"安全生产监督管理部门的行政执法人员在外包工程安全监督管理过程中滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本办法规定的行政处罚，由县级人民政府以上安全生产监督管理部门实施。 有关法律、行政法规、规章对非煤矿山外包工程安全生产违法行为的行政处罚另有规定的，依照其规定。"},{"i":42,"n":"第四十二条","txt":"本办法下列用语的含义： （一）非煤矿山，是指金属矿、非金属矿、水气矿和除煤矿以外的能源矿，以及石油天然气管道储运（不含成品油管道）及其附属设施的总称； （二）金属非金属矿山，是指金属矿、非金属矿、水气矿和除煤矿、石油天然气以外的能源矿，以及选矿厂、尾矿库、排土场等矿山附属设施的总称； （三）外包工程，是指发包单位与本单位以外的承包单位签订合同，由承包单位承揽与矿产资源开采活动有关的工程、作业活动或者技术服务项目； （四）发包单位，是指将矿产资源开采活动有关的工程、作业活动或者技术服务项目，发包给外单位施工的非煤矿山企业； （五）分项发包，是指发包单位将矿产资源开采活动有关的工程、作业活动或者技术服务项目，分为若干部分发包给若干承包单位进行施工的行为； （六）总承包单位，是指整体承揽矿产资源开采活动或者独立生产系统的所有工程、作业活动或者技术服务项目的承包单位； （七）承包单位，是指承揽"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市人民政府安全生产监督管理部门可以根据本办法制定实施细则，并报国家安全生产监督管理总局备案。"},{"i":44,"n":"第四十四条","txt":"本办法自2013年10月1日起施行。"}],"feimeikuangkuangshanqiyeanquanshengchanxukezhengshf85212":[{"i":1,"n":"第一条","txt":"为了严格规范非煤矿矿山企业安全生产条件，做好非煤矿矿山企业安全生产许可证的颁发管理工作，根据《安全生产许可证条例》等法律、行政法规，制定本实施办法。"},{"i":2,"n":"第二条","txt":"非煤矿矿山企业必须依照本实施办法的规定取得安全生产许可证。 未取得安全生产许可证的，不得从事生产活动。"},{"i":3,"n":"第三条","txt":"非煤矿矿山企业安全生产许可证的颁发管理工作实行企业申请、两级发证、属地监管的原则。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局指导、监督全国非煤矿矿山企业安全生产许可证的颁发管理工作，负责海洋石油天然气企业安全生产许可证的颁发和管理。 省、自治区、直辖市人民政府安全生产监督管理部门（以下简称省级安全生产许可证颁发管理机关）负责本行政区域内除本条第一款规定以外的非煤矿矿山企业安全生产许可证的颁发和管理。 省级安全生产许可证颁发管理机关可以委托设区的市级安全生产监督管理部门实施非煤矿矿山企业安全生产许可证的颁发管理工作；但中央管理企业所属非煤矿矿山的安全生产许可证颁发管理工作不得委托实施。"},{"i":5,"n":"第五条","txt":"本实施办法所称的非煤矿矿山企业包括金属非金属矿山企业及其尾矿库、地质勘探单位、采掘施工企业、石油天然气企业。 金属非金属矿山企业，是指从事金属和非金属矿产资源开采活动的下列单位： 1.专门从事矿产资源开采的生产单位； 2.从事矿产资源开采、加工的联合生产企业及其矿山生产单位； 3.其他非矿山企业中从事矿山生产的单位。 尾矿库，是指筑坝拦截谷口或者围地构成的，用以贮存金属非金属矿石选别后排出尾矿的场所，包括氧化铝厂赤泥库，不包括核工业矿山尾矿库及电厂灰渣库。 地质勘探单位，是指采用钻探工程、坑探工程对金属非金属矿产资源进行勘探作业的单位。 采掘施工企业，是指承担金属非金属矿山采掘工程施工的单位。 石油天然气企业，是指从事石油和天然气勘探、开发生产、储运的单位。"},{"i":6,"n":"第六条","txt":"非煤矿矿山企业取得安全生产许可证，应当具备下列安全生产条件： （一）建立健全主要负责人、分管负责人、安全生产管理人员、职能部门、岗位安全生产责任制；制定安全检查制度、职业危害预防制度、安全教育培训制度、生产安全事故管理制度、重大危险源监控和重大隐患整改制度、设备安全管理制度、安全生产档案管理制度、安全生产奖惩制度等规章制度；制定作业安全规程和各工种操作规程； （二）安全投入符合安全生产要求，依照国家有关规定足额提取安全生产费用； （三）设置安全生产管理机构，或者配备专职安全生产管理人员； （四）主要负责人和安全生产管理人员经安全生产监督管理部门考核合格，取得安全资格证书； （五）特种作业人员经有关业务主管部门考核合格，取得特种作业操作资格证书； （六）其他从业人员依照规定接受安全生产教育和培训，并经考试合格； （七）依法参加工伤保险，为从业人员缴纳保险费； （八）制定防治职业危害的具体"},{"i":7,"n":"第七条","txt":"海洋石油天然气企业申请领取安全生产许可证，向国家安全生产监督管理总局提出申请。 本条第一款规定以外的其他非煤矿矿山企业申请领取安全生产许可证，向企业所在地省级安全生产许可证颁发管理机关或其委托的设区的市级安全生产监督管理部门提出申请。"},{"i":8,"n":"第八条","txt":"非煤矿矿山企业申请领取安全生产许可证，应当提交下列文件、资料： （一）安全生产许可证申请书； （二）工商营业执照复印件； （三）采矿许可证复印件； （四）各种安全生产责任制复印件； （五）安全生产规章制度和操作规程目录清单； （六）设置安全生产管理机构或者配备专职安全生产管理人员的文件复印件； （七）主要负责人和安全生产管理人员安全资格证书复印件； （八）特种作业人员操作资格证书复印件； （九）足额提取安全生产费用的证明材料； （十）为从业人员缴纳工伤保险费的证明材料；因特殊情况不能办理工伤保险的，可以出具办理安全生产责任保险的证明材料； （十一）涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备由具备相应资质的检测检验机构出具合格的检测检验报告，并取得安全使用证或者安全标志； （十二）事故应急救援预案，设立事故应急救援组织的文件或者与矿山救护队、其他应急救援组织签订的救"},{"i":9,"n":"第九条","txt":"非煤矿矿山企业总部申请领取安全生产许可证，不需要提交本实施办法第八条第（三）、（八）、（九）、（十）、（十一）、（十二）、（十三）项规定的文件、资料。"},{"i":10,"n":"第十条","txt":"金属非金属矿山企业从事爆破作业的，除应当依照本实施办法第八条的规定提交相应文件、资料外，还应当提交《爆破作业单位许可证》。"},{"i":11,"n":"第十一条","txt":"尾矿库申请领取安全生产许可证，不需要提交本实施办法第八条第（三）项规定的文件、资料。"},{"i":12,"n":"第十二条","txt":"地质勘探单位申请领取安全生产许可证，不需要提交本实施办法第八条第（三）、（九）、（十三）项规定的文件、资料，但应当提交地质勘查资质证书复印件；从事爆破作业的，还应当提交《爆破作业单位许可证》。"},{"i":13,"n":"第十三条","txt":"采掘施工企业申请领取安全生产许可证，不需要提交本实施办法第八条第（三）、（九）、（十三）项规定的文件、资料，但应当提交矿山工程施工相关资质证书复印件；从事爆破作业的，还应当提交《爆破作业单位许可证》。"},{"i":14,"n":"第十四条","txt":"石油天然气勘探单位申请领取安全生产许可证，不需要提交本实施办法第八条第（三）、（十三）项规定的文件、资料；石油天然气管道储运单位申请领取安全生产许可证不需要提交本实施办法第八条第（三）项规定的文件、资料。"},{"i":15,"n":"第十五条","txt":"非煤矿矿山企业应当对其向安全生产许可证颁发管理机关提交的文件、资料实质内容的真实性负责。 从事安全评价、检测检验的中介机构应当对其出具的安全评价报告、检测检验结果负责。"},{"i":16,"n":"第十六条","txt":"安全生产许可证颁发管理机关对非煤矿矿山企业提交的申请书及文件、资料，应当依照下列规定分别处理： （一）申请事项不属于本机关职权范围的，应当即时作出不予受理的决定，并告知申请人向有关机关申请； （二）申请材料存在可以当场更正的错误的，应当允许或者要求申请人当场更正，并即时出具受理的书面凭证； （三）申请材料不齐全或者不符合要求的，应当当场或者在5个工作日内一次性书面告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合要求或者依照要求全部补正的，自收到申请材料或者全部补正材料之日起为受理。"},{"i":17,"n":"第十七条","txt":"安全生产许可证颁发管理机关应当依照本实施办法规定的法定条件组织，对非煤矿矿山企业提交的申请材料进行审查，并在受理申请之日起45日内作出颁发或者不予颁发安全生产许可证的决定。安全生产许可证颁发管理机关认为有必要到现场对非煤矿矿山企业提交的申请材料进行复核的，应当到现场进行复核。复核时间不计算在本款规定的期限内。 对决定颁发的，安全生产许可证颁发管理机关应当自决定之日起10个工作日内送达或者通知申请人领取安全生产许可证；对决定不予颁发的，应当在10个工作日内书面通知申请人并说明理由。"},{"i":18,"n":"第十八条","txt":"安全生产许可证颁发管理机关应当依照下列规定颁发非煤矿矿山企业安全生产许可证： （一）对金属非金属矿山企业，向企业及其所属各独立生产系统分别颁发安全生产许可证；对于只有一个独立生产系统的企业，只向企业颁发安全生产许可证； （二）对中央管理的陆上石油天然气企业，向企业总部直接管理的分公司、子公司以及下一级与油气勘探、开发生产、储运直接相关的生产作业单位分别颁发安全生产许可证；对设有分公司、子公司的地方石油天然气企业，向企业总部及其分公司、子公司颁发安全生产许可证；对其他陆上石油天然气企业，向具有法人资格的企业颁发安全生产许可证； （三）对海洋石油天然气企业，向企业及其直接管理的分公司、子公司以及下一级与油气开发生产直接相关的生产作业单位、独立生产系统分别颁发安全生产许可证；对其他海洋石油天然气企业，向具有法人资格的企业颁发安全生产许可证； （四）对地质勘探单位，向最下级具有企事业法人资格的"},{"i":19,"n":"第十九条","txt":"安全生产许可证的有效期为3年。安全生产许可证有效期满后需要延期的，非煤矿矿山企业应当在安全生产许可证有效期届满前3个月向原安全生产许可证颁发管理机关申请办理延期手续，并提交下列文件、资料： （一）延期申请书； （二）安全生产许可证正本和副本； （三）本实施办法第二章规定的相应文件、资料。 金属非金属矿山独立生产系统和尾矿库，以及石油天然气独立生产系统和作业单位还应当提交由具备相应资质的中介服务机构出具的合格的安全现状评价报告。 金属非金属矿山独立生产系统和尾矿库在提出延期申请之前6个月内经考评合格达到安全标准化等级的，可以不提交安全现状评价报告，但需要提交安全标准化等级的证明材料。 安全生产许可证颁发管理机关应当依照本实施办法第十六条、第十七条的规定，对非煤矿矿山企业提交的材料进行审查，并作出是否准予延期的决定。决定准予延期的，应当收回原安全生产许可证，换发新的安全生产许可证；决定不准"},{"i":20,"n":"第二十条","txt":"非煤矿矿山企业符合下列条件的，当安全生产许可证有效期届满申请延期时，经原安全生产许可证颁发管理机关同意，不再审查，直接办理延期手续： （一）严格遵守有关安全生产的法律法规的； （二）取得安全生产许可证后，加强日常安全生产管理，未降低安全生产条件，并达到安全标准化等级二级以上的； （三）接受安全生产许可证颁发管理机关及所在地人民政府安全生产监督管理部门的监督检查的； （四）未发生死亡事故的。"},{"i":21,"n":"第二十一条","txt":"非煤矿矿山企业在安全生产许可证有效期内有下列情形之一的，应当自工商营业执照变更之日起30个工作日内向原安全生产许可证颁发管理机关申请变更安全生产许可证： （一）变更单位名称的； （二）变更主要负责人的； （三）变更单位地址的； （四）变更经济类型的； （五）变更许可范围的。"},{"i":22,"n":"第二十二条","txt":"非煤矿矿山企业申请变更安全生产许可证时，应当提交下列文件、资料： （一）变更申请书； （二）安全生产许可证正本和副本； （三）变更后的工商营业执照、采矿许可证复印件及变更说明材料。 变更本实施办法第二十一条第（二）项的，还应当提交变更后的主要负责人的安全资格证书复印件。 对已经受理的变更申请，安全生产许可证颁发管理机关对申请人提交的文件、资料审查无误后，应当在10个工作日内办理变更手续。"},{"i":23,"n":"第二十三条","txt":"安全生产许可证申请书、审查书、延期申请书和变更申请书由国家安全生产监督管理总局统一格式。"},{"i":24,"n":"第二十四条","txt":"非煤矿矿山企业安全生产许可证分为正本和副本，正本和副本具有同等法律效力，正本为悬挂式，副本为折页式。 非煤矿矿山企业安全生产许可证由国家安全生产监督管理总局统一印制和编号。"},{"i":25,"n":"第二十五条","txt":"非煤矿矿山企业取得安全生产许可证后，应当加强日常安全生产管理，不得降低安全生产条件，并接受所在地县级以上安全生产监督管理部门的监督检查。"},{"i":26,"n":"第二十六条","txt":"地质勘探单位、采掘施工单位在登记注册的省、自治区、直辖市以外从事作业的，应当向作业所在地县级以上安全生产监督管理部门书面报告。"},{"i":27,"n":"第二十七条","txt":"非煤矿矿山企业不得转让、冒用、买卖、出租、出借或者使用伪造的安全生产许可证。"},{"i":28,"n":"第二十八条","txt":"非煤矿矿山企业发现在安全生产许可证有效期内采矿许可证到期失效的，应当在采矿许可证到期前15日内向原安全生产许可证颁发管理机关报告，并交回安全生产许可证正本和副本。 采矿许可证被暂扣、撤销、吊销和注销的，非煤矿矿山企业应当在暂扣、撤销、吊销和注销后5日内向原安全生产许可证颁发管理机关报告，并交回安全生产许可证正本和副本。"},{"i":29,"n":"第二十九条","txt":"安全生产许可证颁发管理机关应当坚持公开、公平、公正的原则，严格依照本实施办法的规定审查、颁发安全生产许可证。 安全生产许可证颁发管理机关工作人员在安全生产许可证颁发、管理和监督检查工作中，不得索取或者接受非煤矿矿山企业的财物，不得谋取其他利益。"},{"i":30,"n":"第三十条","txt":"安全生产许可证颁发管理机关发现有下列情形之一的，应当撤销已经颁发的安全生产许可证： （一）超越职权颁发安全生产许可证的； （二）违反本实施办法规定的程序颁发安全生产许可证的； （三）不具备本实施办法规定的安全生产条件颁发安全生产许可证的； （四）以欺骗、贿赂等不正当手段取得安全生产许可证的。"},{"i":31,"n":"第三十一条","txt":"取得安全生产许可证的非煤矿矿山企业有下列情形之一的，安全生产许可证颁发管理机关应当注销其安全生产许可证： （一）终止生产活动的； （二）安全生产许可证被依法撤销的； （三）安全生产许可证被依法吊销的。"},{"i":32,"n":"第三十二条","txt":"非煤矿矿山企业隐瞒有关情况或者提供虚假材料申请安全生产许可证的，安全生产许可证颁发管理机关不予受理，该企业在1年内不得再次申请安全生产许可证。 非煤矿矿山企业以欺骗、贿赂等不正当手段取得安全生产许可证后被依法予以撤销的，该企业3年内不得再次申请安全生产许可证。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府安全生产监督管理部门负责本行政区域内取得安全生产许可证的非煤矿矿山企业的日常监督检查，并将监督检查中发现的问题及时报告安全生产许可证颁发管理机关。中央管理的非煤矿矿山企业由设区的市级以上地方人民政府安全生产监督管理部门负责日常监督检查。 国家安全生产监督管理总局负责取得安全生产许可证的中央管理的非煤矿矿山企业总部和海洋石油天然气企业的日常监督检查。"},{"i":34,"n":"第三十四条","txt":"安全生产许可证颁发管理机关每6个月向社会公布取得安全生产许可证的非煤矿矿山企业名单。"},{"i":35,"n":"第三十五条","txt":"安全生产许可证颁发管理机关应当将非煤矿矿山企业安全生产许可证颁发管理情况通报非煤矿矿山企业所在地县级以上地方人民政府及其安全生产监督管理部门。"},{"i":36,"n":"第三十六条","txt":"安全生产许可证颁发管理机关应当加强对非煤矿矿山企业安全生产许可证的监督管理，建立、健全非煤矿矿山企业安全生产许可证信息管理制度。 省级安全生产许可证颁发管理机关应当在安全生产许可证颁发之日起1个月内将颁发和管理情况录入到全国统一的非煤矿矿山企业安全生产许可证管理系统。"},{"i":37,"n":"第三十七条","txt":"任何单位或者个人对违反《安全生产许可证条例》和本实施办法规定的行为，有权向安全生产许可证颁发管理机关或者监察机关等有关部门举报。"},{"i":38,"n":"第三十八条","txt":"安全生产许可证颁发管理机关工作人员有下列行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任： （一）向不符合本实施办法规定的安全生产条件的非煤矿矿山企业颁发安全生产许可证的； （二）发现非煤矿矿山企业未依法取得安全生产许可证擅自从事生产活动，不依法处理的； （三）发现取得安全生产许可证的非煤矿矿山企业不再具备本实施办法规定的安全生产条件，不依法处理的； （四）接到对违反本实施办法规定行为的举报后，不及时处理的； （五）在安全生产许可证颁发、管理和监督检查工作中，索取或者接受非煤矿矿山企业的财物，或者谋取其他利益的。"},{"i":39,"n":"第三十九条","txt":"承担安全评价、认证、检测、检验工作的机构，出具虚假证明的，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与建设单位承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构，吊销其相应资质。"},{"i":40,"n":"第四十条","txt":"取得安全生产许可证的非煤矿矿山企业不再具备本实施办法第六条规定的安全生产条件之一的，应当暂扣或者吊销其安全生产许可证。"},{"i":41,"n":"第四十一条","txt":"取得安全生产许可证的非煤矿矿山企业有下列行为之一的，吊销其安全生产许可证： （一）倒卖、出租、出借或者以其他形式非法转让安全生产许可证的； （二）暂扣安全生产许可证后未按期整改或者整改后仍不具备安全生产条件的。"},{"i":42,"n":"第四十二条","txt":"非煤矿矿山企业有下列行为之一的，责令停止生产，没收违法所得，并处10万元以上50万元以下的罚款： （一）未取得安全生产许可证，擅自进行生产的； （二）接受转让的安全生产许可证的； （三）冒用安全生产许可证的； （四）使用伪造的安全生产许可证的。"},{"i":43,"n":"第四十三条","txt":"非煤矿矿山企业在安全生产许可证有效期内出现采矿许可证有效期届满和采矿许可证被暂扣、撤销、吊销、注销的情况，未依照本实施办法第二十八条的规定向安全生产许可证颁发管理机关报告并交回安全生产许可证的，处1万元以上3万元以下罚款。"},{"i":44,"n":"第四十四条","txt":"非煤矿矿山企业在安全生产许可证有效期内，出现需要变更安全生产许可证的情形，未按本实施办法第二十一条的规定申请、办理变更手续的，责令限期办理变更手续，并处1万元以上3万元以下罚款。 地质勘探单位、采掘施工单位在登记注册地以外进行跨省作业，未按照本实施办法第二十六条的规定书面报告的，责令限期办理书面报告手续，并处1万元以上3万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"非煤矿矿山企业在安全生产许可证有效期满未办理延期手续，继续进行生产的，责令停止生产，限期补办延期手续，没收违法所得，并处5万元以上10万元以下的罚款；逾期仍不办理延期手续，继续进行生产的，依照本实施办法第四十二条的规定处罚。"},{"i":46,"n":"第四十六条","txt":"非煤矿矿山企业转让安全生产许可证的，没收违法所得，并处10万元以上50万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"本实施办法规定的行政处罚，由安全生产许可证颁发管理机关决定。安全生产许可证颁发管理机关可以委托县级以上安全生产监督管理部门实施行政处罚。但撤销、吊销安全生产许可证和撤销有关资格的行政处罚除外。"},{"i":48,"n":"第四十八条","txt":"本实施办法所称非煤矿矿山企业独立生产系统，是指具有相对独立的采掘生产系统及通风、运输（提升）、供配电、防排水等辅助系统的作业单位。"},{"i":49,"n":"第四十九条","txt":"危险性较小的地热、温泉、矿泉水、卤水、砖瓦用粘土等资源开采活动的安全生产许可，由省级安全生产许可证颁发管理机关决定。"},{"i":50,"n":"第五十条","txt":"同时开采煤炭与金属非金属矿产资源且以煤炭、煤层气为主采矿种的煤系矿山企业应当申请领取煤矿企业安全生产许可证，不再申请领取非煤矿矿山企业安全生产许可证。"},{"i":51,"n":"第五十一条","txt":"本实施办法自公布之日起施行。2004年5月17日原国家安全生产监督管理局（国家煤矿安全监察局）公布的《非煤矿山企业安全生产许可证实施办法》同时废止。"}],"feiyaopinleiyizhiduhuaxuepinshengchanjingyingxukebbdae66":[{"i":1,"n":"第一条","txt":"为加强非药品类易制毒化学品管理，规范非药品类易制毒化学品生产、经营行为，防止非药品类易制毒化学品被用于制造毒品，维护经济和社会秩序，根据《易制毒化学品管理条例》（以下简称《条例》）和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称非药品类易制毒化学品，是指《条例》附表确定的可以用于制毒的非药品类主要原料和化学配剂。 非药品类易制毒化学品的分类和品种，见本办法附表《非药品类易制毒化学品分类和品种目录》。 《条例》附表《易制毒化学品的分类和品种目录》调整或者《危险化学品目录》调整涉及本办法附表时，《非药品类易制毒化学品分类和品种目录》随之进行调整并公布。"},{"i":3,"n":"第三条","txt":"国家对非药品类易制毒化学品的生产、经营实行许可制度。对第一类非药品类易制毒化学品的生产、经营实行许可证管理，对第二类、第三类易制毒化学品的生产、经营实行备案证明管理。 省、自治区、直辖市人民政府安全生产监督管理部门负责本行政区域内第一类非药品类易制毒化学品生产、经营的审批和许可证的颁发工作。 设区的市级人民政府安全生产监督管理部门负责本行政区域内第二类非药品类易制毒化学品生产、经营和第三类非药品类易制毒化学品生产的备案证明颁发工作。 县级人民政府安全生产监督管理部门负责本行政区域内第三类非药品类易制毒化学品经营的备案证明颁发工作。"},{"i":4,"n":"第四条","txt":"国家安全生产监督管理总局监督、指导全国非药品类易制毒化学品生产、经营许可和备案管理工作。 县级以上人民政府安全生产监督管理部门负责本行政区域内执行非药品类易制毒化学品生产、经营许可制度的监督管理工作。"},{"i":5,"n":"第五条","txt":"生产、经营第一类非药品类易制毒化学品的，必须取得非药品类易制毒化学品生产、经营许可证方可从事生产、经营活动。"},{"i":6,"n":"第六条","txt":"生产、经营第一类非药品类易制毒化学品的，应当分别符合《条例》第七条、第九条规定的条件。"},{"i":7,"n":"第七条","txt":"生产单位申请非药品类易制毒化学品生产许可证，应当向所在地的省级人民政府安全生产监督管理部门提交下列文件、资料，并对其真实性负责： （一）非药品类易制毒化学品生产许可证申请书（一式两份）； （二）生产设备、仓储设施和污染物处理设施情况说明材料； （三）易制毒化学品管理制度和环境突发事件应急预案； （四）安全生产管理制度； （五）单位法定代表人或者主要负责人和技术、管理人员具有相应安全生产知识的证明材料； （六）单位法定代表人或者主要负责人和技术、管理人员具有相应易制毒化学品知识的证明材料及无毒品犯罪记录证明材料； （七）工商营业执照副本（复印件）； （八）产品包装说明和使用说明书。 属于危险化学品生产单位的，还应当提交危险化学品生产企业安全生产许可证和危险化学品登记证（复印件），免于提交本条第（四）、（五）、（七）项所要求的文件、资料。"},{"i":8,"n":"第八条","txt":"经营单位申请非药品类易制毒化学品经营许可证，应当向所在地的省级人民政府安全生产监督管理部门提交下列文件、资料，并对其真实性负责： （一）非药品类易制毒化学品经营许可证申请书（一式两份）； （二）经营场所、仓储设施情况说明材料； （三）易制毒化学品经营管理制度和包括销售机构、销售代理商、用户等内容的销售网络文件； （四）单位法定代表人或者主要负责人和销售、管理人员具有相应易制毒化学品知识的证明材料及无毒品犯罪记录证明材料； （五）工商营业执照副本（复印件）； （六）产品包装说明和使用说明书。 属于危险化学品经营单位的，还应当提交危险化学品经营许可证（复印件），免于提交本条第（五）项所要求的文件、资料。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市人民政府安全生产监督管理部门对申请人提交的申请书及文件、资料，应当按照下列规定分别处理： （一）申请事项不属于本部门职权范围的，应当即时出具不予受理的书面凭证； （二）申请材料存在可以当场更正的错误的，应当允许或者要求申请人当场更正； （三）申请材料不齐全或者不符合要求的，应当当场或者在5个工作日内书面一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合要求或者按照要求全部补正的，自收到申请材料或者全部补正材料之日起为受理。"},{"i":10,"n":"第十条","txt":"对已经受理的申请材料，省、自治区、直辖市人民政府安全生产监督管理部门应当进行审查，根据需要可以进行实地核查。"},{"i":11,"n":"第十一条","txt":"自受理之日起，对非药品类易制毒化学品的生产许可证申请在60个工作日内、对经营许可证申请在30个工作日内，省、自治区、直辖市人民政府安全生产监督管理部门应当作出颁发或者不予颁发许可证的决定。 对决定颁发的，应当自决定之日起10个工作日内送达或者通知申请人领取许可证；对不予颁发的，应当在10个工作日内书面通知申请人并说明理由。"},{"i":12,"n":"第十二条","txt":"非药品类易制毒化学品生产、经营许可证有效期为3年。许可证有效期满后需继续生产、经营第一类非药品类易制毒化学品的，应当于许可证有效期满前3个月内向原许可证颁发管理部门提出换证申请并提交相应资料，经审查合格后换领新证。"},{"i":13,"n":"第十三条","txt":"第一类非药品类易制毒化学品生产、经营单位在非药品类易制毒化学品生产、经营许可证有效期内出现下列情形之一的，应当向原许可证颁发管理部门申请变更许可证： （一）单位法定代表人或者主要负责人改变； （二）单位名称改变； （三）许可品种主要流向改变； （四）需要增加许可品种、数量。 属于本条第（一）、（三）项的变更，应当自发生改变之日起20个工作日内提出申请；属于本条第（二）项的变更，应当自工商营业执照变更后提出申请。 申请本条第（一）项的变更，应当提供变更后的法定代表人或者主要负责人符合本办法第七条第（五）、（六）项或第八条第（四）项要求的有关证明材料；申请本条第（二）项的变更，应当提供变更后的工商营业执照副本（复印件）；申请本条第（三）项的变更，生产、经营单位应当分别提供主要流向改变说明、第八条第（三）项要求的有关资料；申请本条第（四）项的变更，应当提供本办法第七条第（二）、（三）、（八）"},{"i":14,"n":"第十四条","txt":"对已经受理的本办法第十三条第（一）、（二）、（三）项的变更申请，许可证颁发管理部门在对申请人提交的文件、资料审核后，即可办理非药品类易制毒化学品生产、经营许可证变更手续。 对已经受理的本办法第十三条第（四）项的变更申请，许可证颁发管理部门应当按照本办法第十条、第十一条的规定，办理非药品类易制毒化学品生产、经营许可证变更手续。"},{"i":15,"n":"第十五条","txt":"非药品类易制毒化学品生产、经营单位原有技术或者销售人员、管理人员变动的，变动人员应当具有相应的安全生产和易制毒化学品知识。"},{"i":16,"n":"第十六条","txt":"第一类非药品类易制毒化学品生产、经营单位不再生产、经营非药品类易制毒化学品时，应当在停止生产、经营后3个月内办理注销许可手续。"},{"i":17,"n":"第十七条","txt":"生产、经营第二类、第三类非药品类易制毒化学品的，必须进行非药品类易制毒化学品生产、经营备案。"},{"i":18,"n":"第十八条","txt":"生产第二类、第三类非药品类易制毒化学品的，应当自生产之日起30个工作日内，将生产的品种、数量等情况，向所在地的设区的市级人民政府安全生产监督管理部门备案。 经营第二类非药品类易制毒化学品的，应当自经营之日起30个工作日内，将经营的品种、数量、主要流向等情况，向所在地的设区的市级人民政府安全生产监督管理部门备案。 经营第三类非药品类易制毒化学品的，应当自经营之日起30个工作日内，将经营的品种、数量、主要流向等情况，向所在地的县级人民政府安全生产监督管理部门备案。"},{"i":19,"n":"第十九条","txt":"第二类、第三类非药品类易制毒化学品生产单位进行备案时，应当提交下列资料： （一）非药品类易制毒化学品品种、产量、销售量等情况的备案申请书； （二）易制毒化学品管理制度； （三）产品包装说明和使用说明书； （四）工商营业执照副本（复印件）。 属于危险化学品生产单位的，还应当提交危险化学品生产企业安全生产许可证和危险化学品登记证（复印件），免于提交本条第（四）项所要求的文件、资料。"},{"i":20,"n":"第二十条","txt":"第二类、第三类非药品类易制毒化学品经营单位进行备案时，应当提交下列资料： （一）非药品类易制毒化学品销售品种、销售量、主要流向等情况的备案申请书； （二）易制毒化学品管理制度； （三）产品包装说明和使用说明书； （四）工商营业执照副本（复印件）。 属于危险化学品经营单位的，还应当提交危险化学品经营许可证，免于提交本条第（四）项所要求的文件、资料。"},{"i":21,"n":"第二十一条","txt":"第二类、第三类非药品类易制毒化学品生产、经营备案主管部门收到本办法第十九条、第二十条规定的备案材料后，应当于当日发给备案证明。"},{"i":22,"n":"第二十二条","txt":"第二类、第三类非药品类易制毒化学品生产、经营备案证明有效期为3年。有效期满后需继续生产、经营的，应当在备案证明有效期满前3个月内重新办理备案手续。"},{"i":23,"n":"第二十三条","txt":"第二类、第三类非药品类易制毒化学品生产、经营单位的法定代表人或者主要负责人、单位名称、单位地址发生变化的，应当自工商营业执照变更之日起30个工作日内重新办理备案手续；生产或者经营的备案品种增加、主要流向改变的，在发生变化后30个工作日内重新办理备案手续。"},{"i":24,"n":"第二十四条","txt":"第二类、第三类非药品类易制毒化学品生产、经营单位不再生产、经营非药品类易制毒化学品时，应当在终止生产、经营后3个月内办理备案注销手续。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府安全生产监督管理部门应当加强非药品类易制毒化学品生产、经营的监督检查工作。 县级以上人民政府安全生产监督管理部门对非药品类易制毒化学品的生产、经营活动进行监督检查时，可以查看现场、查阅和复制有关资料、记录有关情况、扣押相关的证据材料和违法物品；必要时，可以临时查封有关场所。 被检查的单位或者个人应当如实提供有关情况和资料、物品，不得拒绝或者隐匿。"},{"i":26,"n":"第二十六条","txt":"生产、经营单位应当于每年3月31日前，向许可或者备案的安全生产监督管理部门报告本单位上年度非药品类易制毒化学品生产经营的品种、数量和主要流向等情况。 安全生产监督管理部门应当自收到报告后10个工作日内将本行政区域内上年度非药品类易制毒化学品生产、经营汇总情况报上级安全生产监督管理部门。"},{"i":27,"n":"第二十七条","txt":"各级安全生产监督管理部门应当建立非药品类易制毒化学品许可和备案档案并加强信息管理。"},{"i":28,"n":"第二十八条","txt":"安全生产监督管理部门应当及时将非药品类易制毒化学品生产、经营许可及吊销许可情况，向同级公安机关和工商行政管理部门通报；向商务主管部门通报许可证和备案证明颁发等有关情况。"},{"i":29,"n":"第二十九条","txt":"对于有下列行为之一的，县级以上人民政府安全生产监督管理部门可以自《条例》第三十八条规定的部门作出行政处罚决定之日起的3年内，停止受理其非药品类易制毒化学品生产、经营许可或备案申请： （一）未经许可或者备案擅自生产、经营非药品类易制毒化学品的； （二）伪造申请材料骗取非药品类易制毒化学品生产、经营许可证或者备案证明的； （三）使用他人的非药品类易制毒化学品生产、经营许可证或者备案证明的； （四）使用伪造、变造、失效的非药品类易制毒化学品生产、经营许可证或者备案证明的。"},{"i":30,"n":"第三十条","txt":"对于有下列行为之一的，由县级以上人民政府安全生产监督管理部门给予警告，责令限期改正，处1万元以上5万元以下的罚款；对违反规定生产、经营的非药品类易制毒化学品，可以予以没收；逾期不改正的，责令限期停产停业整顿；逾期整顿不合格的，吊销相应的许可证： （一）易制毒化学品生产、经营单位未按规定建立易制毒化学品的管理制度和安全管理制度的； （二）将许可证或者备案证明转借他人使用的； （三）超出许可的品种、数量，生产、经营非药品类易制毒化学品的； （四）易制毒化学品的产品包装和使用说明书不符合《条例》规定要求的； （五）生产、经营非药品类易制毒化学品的单位不如实或者不按时向安全生产监督管理部门报告年度生产、经营等情况的。"},{"i":31,"n":"第三十一条","txt":"生产、经营非药品类易制毒化学品的单位或者个人拒不接受安全生产监督管理部门监督检查的，由县级以上人民政府安全生产监督管理部门责令改正，对直接负责的主管人员以及其他直接责任人员给予警告；情节严重的，对单位处1万元以上5万元以下的罚款，对直接负责的主管人员以及其他直接责任人员处1000元以上5000元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"安全生产监督管理部门工作人员在管理工作中，有滥用职权、玩忽职守、徇私舞弊行为或泄露企业商业秘密的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"非药品类易制毒化学品生产许可证、经营许可证和备案证明由国家安全生产监督管理总局监制。 非药品类易制毒化学品年度报告表及许可、备案、变更申请书由国家安全生产监督管理总局规定式样。"},{"i":34,"n":"第三十四条","txt":"本办法自2006年4月15日起施行。 附表： 非药品类易制毒化学品分类和品种目录 第一类 1．1-苯基-2-丙酮 2．3，4-亚甲基二氧苯基-2-丙酮 3．胡椒醛 4．黄樟素 5．黄樟油 6．异黄樟素 7．N-乙酰邻氨基苯酸 8．邻氨基苯甲酸 第二类 1．苯乙酸 2．醋酸酐☆ 3．三氯甲烷☆ 4．乙醚☆ 5．哌啶☆ 第三类 1．甲苯☆ 2．丙酮☆ 3．甲基乙基酮☆ 4．高锰酸钾☆ 5．硫酸☆ 6．盐酸☆ 说明： 一、第一类、第二类所列物质可能存在的盐类，也纳入管制。 二、带有☆标记的品种为危险化学品。"}],"shipinshengchanqiyeanquanshengchanjianduguanlizanx517538":[{"i":1,"n":"第一条","txt":"为加强食品生产企业的安全生产工作，防止和减少生产安全事故，保障从业人员的生命和财产安全，根据《中华人民共和国安全生产法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"食品生产企业的安全生产及其监督管理，适用本规定。农副产品从种植养殖环节进入批发、零售市场或者生产加工企业前的安全生产及其监督管理，不适用本规定。 本规定所称食品生产企业，是指以农业、渔业、畜牧业、林业或者化学工业的产品、半成品为原料，通过工业化加工、制作，为人们提供食用或者饮用的物品的企业。"},{"i":3,"n":"第三条","txt":"国家安全生产监督管理总局对全国食品生产企业的安全生产工作实施监督管理。 县级以上地方人民政府安全生产监督管理部门和有关部门（以下统称负责食品生产企业安全生产监管的部门）根据本级人民政府规定的职责，按照属地监管、分级负责的原则，对本行政区域内食品生产企业的安全生产工作实施监督管理。 食品生产企业的工程建设安全、消防安全和特种设备安全，依照法律、行政法规的规定由县级以上地方人民政府相关部门负责专项监督管理。"},{"i":4,"n":"第四条","txt":"食品生产企业是安全生产的责任主体，其主要负责人对本企业的安全生产工作全面负责，分管安全生产工作的负责人和其他负责人对其职责范围内的安全生产工作负责。 集团公司对其所属或者控股的食品生产企业的安全生产工作负主管责任。"},{"i":5,"n":"第五条","txt":"食品生产企业应当严格遵守有关安全生产法律、行政法规和国家标准、行业标准的规定，建立健全安全生产责任制、安全生产规章制度和安全操作规程。"},{"i":6,"n":"第六条","txt":"从业人员超过100人的食品生产企业，应当设置安全生产管理机构或者配备3名以上专职安全生产管理人员，鼓励配备注册安全工程师从事安全生产管理工作。 前款规定以外的其他食品生产企业，应当配备专职或者兼职安全生产管理人员，或者委托安全生产中介机构提供安全生产服务。 委托安全生产中介机构提供安全生产技术、管理服务的，保证安全生产的责任仍由本企业负责。"},{"i":7,"n":"第七条","txt":"食品生产企业应当支持安全生产管理机构和安全生产管理人员履行管理职责，并保证其开展工作所必须的条件。 食品生产企业作出涉及安全生产的决策，应当听取安全生产管理机构以及安全生产管理人员的意见，不得因安全生产管理人员依法履行职责而降低其工资、福利等待遇或者解除与其订立的劳动合同。"},{"i":8,"n":"第八条","txt":"食品生产企业应当推进安全生产标准化建设，强化安全生产基础，做到安全管理标准化、设施设备标准化、作业现场标准化和作业行为标准化，并持续改进，不断提高企业本质安全水平。"},{"i":9,"n":"第九条","txt":"食品生产企业新建、改建和扩建建设项目（以下统称建设项目）的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"},{"i":10,"n":"第十条","txt":"食品生产企业应当委托具备国家规定资质的工程设计单位、施工单位和监理单位，对建设工程进行设计、施工和监理。 工程设计单位、施工单位和监理单位应当按照有关法律、行政法规、国家标准或者行业标准的规定进行设计、施工和监理，并对其工作成果负责。"},{"i":11,"n":"第十一条","txt":"食品生产企业应当按照有关法律、行政法规的规定，加强工程建设、消防、特种设备的安全管理；对于需要有关部门审批和验收的事项，应当依法向有关部门提出申请；未经有关部门依法批准或者验收合格的，不得投入生产和使用。"},{"i":12,"n":"第十二条","txt":"食品生产企业应当建立健全事故隐患排查治理制度，明确事故隐患治理的措施、责任、资金、时限和预案，采取技术、管理措施，及时发现并消除事故隐患。事故隐患排查治理情况应当如实记录，向从业人员通报，并按规定报告所在地负责食品生产企业安全生产监管的部门。"},{"i":13,"n":"第十三条","txt":"食品生产企业的加工、制作等项目有多个承包单位、承租单位，或者存在空间交叉的，应当对承包单位、承租单位的安全生产工作进行统一协调、管理。承包单位、承租单位应当服从食品生产企业的统一管理，并对作业现场的安全生产负责。"},{"i":14,"n":"第十四条","txt":"食品生产企业应当对新录用、季节性复工、调整工作岗位和离岗半年以上重新上岗的从业人员，进行相应的安全生产教育培训。未经安全生产教育培训合格的从业人员，不得上岗作业。"},{"i":15,"n":"第十五条","txt":"食品生产企业应当定期组织开展危险源辨识，并将其工作场所存在和作业过程中可能产生的危险因素、防范措施和事故应急措施等如实书面告知从业人员，不得隐瞒或者欺骗。 从业人员发现直接危及人身安全的紧急情况时，有权停止作业或者在采取可能的应急措施后撤离作业场所。食品生产企业不得因此降低其工资、福利待遇或者解除劳动合同。"},{"i":16,"n":"第十六条","txt":"食品生产企业的作业场所应当符合下列要求： （一）生产设施设备，按照国家有关规定配备有温度、压力、流量、液位以及粉尘浓度、可燃和有毒气体浓度等工艺指标的超限报警装置； （二）用电设备设施和场所，采取保护措施，并在配电设备设施上安装剩余电流动作保护装置或者其他防止触电的装置； （三）涉及烘制、油炸等高温的设施设备和岗位，采用必要的防过热自动报警切断和隔热板、墙等保护设施； （四）涉及淀粉等可燃性粉尘爆炸危险的场所、设施设备，采用惰化、抑爆、阻爆、泄爆等措施防止粉尘爆炸，现场安全管理措施和条件符合《粉尘防爆安全规程》（GB15577）等国家标准或者行业标准的要求； （五）油库（罐）、燃气站、除尘器、压缩空气站、压力容器、压力管道、电缆隧道（沟）等重点防火防爆部位，采取有效、可靠的监控、监测、预警、防火、防爆、防毒等安全措施。安全附件和联锁装置不得随意拆弃和解除，声、光报警等信号不得随意切断；"},{"i":17,"n":"第十七条","txt":"食品生产企业涉及生产、储存和使用危险化学品的，应当严格按照《危险化学品安全管理条例》等法律、行政法规、国家标准或者行业标准的规定，根据危险化学品的种类和危险特性，在生产、储存和使用场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤等安全设施设备，并对安全设施设备进行经常性维护保养，保证其正常运行。 食品生产企业的中间产品为危险化学品的，应当依照有关规定取得危险化学品安全生产许可证。"},{"i":18,"n":"第十八条","txt":"食品生产企业应当定期组织对作业场所、仓库、设备设施使用、从业人员持证、劳动防护用品配备和使用、危险源管理情况进行检查，对检查发现的问题应当立即整改；不能立即整改的，应当制定相应的防范措施和整改计划，限期整改。检查应当作好记录，并由有关人员签字。"},{"i":19,"n":"第十九条","txt":"食品生产企业应当加强日常消防安全管理，按照有关规定配置并保持消防设施完好有效。生产作业场所应当设有标志明显、符合要求的安全出口和疏散通道，禁止封堵、锁闭生产作业场所的安全出口和疏散通道。"},{"i":20,"n":"第二十条","txt":"食品生产企业应当使用符合安全技术规范要求的特种设备，并按照国家规定向有关部门登记，进行定期检验。 食品生产企业应当在有危险因素的场所和有关设施、设备上设置明显的安全警示标志和警示说明。"},{"i":21,"n":"第二十一条","txt":"食品生产企业进行高处作业、吊装作业、临近高压输电线路作业、电焊气焊等动火作业，以及在污水池等有限空间内作业的，应当实行作业审批制度，安排专门人员负责现场安全管理，落实现场安全管理措施。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府负责食品生产企业安全生产监管的部门及其行政执法人员应当在其职责范围内加强对食品生产企业安全生产的监督检查，对违反有关安全生产法律、行政法规、国家标准或者行业标准和本规定的违法行为，依法实施行政处罚。"},{"i":23,"n":"第二十三条","txt":"县级以上地方人民政府负责食品生产企业安全生产监管的部门应当将食品生产企业纳入年度执法工作计划，明确检查的重点企业、关键事项、时间和标准，对检查中发现的重大事故隐患实施挂牌督办。"},{"i":24,"n":"第二十四条","txt":"县级以上地方人民政府负责食品生产企业安全生产监管的部门接到食品生产企业报告的重大事故隐患后，应当根据需要，进行现场核查，督促食品生产企业按照治理方案排除事故隐患，防止事故发生；必要时，可以责令食品生产企业暂时停产停业或者停止使用；重大事故隐患治理后，经县级以上地方人民政府负责食品生产企业安全生产监管的部门审查同意，方可恢复生产经营和使用。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府负责食品生产企业安全生产监管的部门对食品生产企业进行监督检查时，发现其存在工程建设、消防和特种设备等方面的事故隐患或者违法行为的，应当及时移送本级人民政府有关部门处理。"},{"i":26,"n":"第二十六条","txt":"食品生产企业有下列行为之一的，责令限期改正，可以处5万元以下的罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款： （一）未按照规定设置安全生产管理机构或者配备安全生产管理人员的； （二）未如实记录安全生产教育和培训情况的； （三）未将事故隐患排查治理情况如实记录或者未向从业人员通报的。"},{"i":27,"n":"第二十七条","txt":"食品生产企业不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件，经停产整顿后仍不具备安全生产条件的，县级以上地方人民政府负责食品生产企业安全生产监管的部门应当提请本级人民政府依法予以关闭。"},{"i":28,"n":"第二十八条","txt":"监督检查人员在对食品生产企业进行监督检查时，滥用职权、玩忽职守、徇私舞弊的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本规定的行政处罚由县级以上地方人民政府负责食品生产企业安全生产监管的部门实施，有关法律、法规和规章对行政处罚的种类、幅度和决定机关另有规定的，依照其规定。"},{"i":30,"n":"第三十条","txt":"本规定自2014年3月1日起施行。"}],"gaocengminyongjianzhuxiaofanganquanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强高层民用建筑消防安全管理，预防火灾和减少火灾危害，根据《中华人民共和国消防法》等法律、行政法规和国务院有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于已经建成且依法投入使用的高层民用建筑（包括高层住宅建筑和高层公共建筑）的消防安全管理。"},{"i":3,"n":"第三条","txt":"高层民用建筑消防安全管理贯彻预防为主、防消结合的方针，实行消防安全责任制。 建筑高度超过100米的高层民用建筑应当实行更加严格的消防安全管理。"},{"i":4,"n":"第四条","txt":"高层民用建筑的业主、使用人是高层民用建筑消防安全责任主体，对高层民用建筑的消防安全负责。高层民用建筑的业主、使用人是单位的，其法定代表人或者主要负责人是本单位的消防安全责任人。 高层民用建筑的业主、使用人可以委托物业服务企业或者消防技术服务机构等专业服务单位（以下统称消防服务单位）提供消防安全服务，并应当在服务合同中约定消防安全服务的具体内容。"},{"i":5,"n":"第五条","txt":"同一高层民用建筑有两个及以上业主、使用人的，各业主、使用人对其专有部分的消防安全负责，对共有部分的消防安全共同负责。 同一高层民用建筑有两个及以上业主、使用人的，应当共同委托物业服务企业，或者明确一个业主、使用人作为统一管理人，对共有部分的消防安全实行统一管理，协调、指导业主、使用人共同做好整栋建筑的消防安全工作，并通过书面形式约定各方消防安全责任。"},{"i":6,"n":"第六条","txt":"高层民用建筑以承包、租赁或者委托经营、管理等形式交由承包人、承租人、经营管理人使用的，当事人在订立承包、租赁、委托管理等合同时，应当明确各方消防安全责任。委托方、出租方依照法律规定，可以对承包方、承租方、受托方的消防安全工作统一协调、管理。 实行承包、租赁或者委托经营、管理时，业主应当提供符合消防安全要求的建筑物，督促使用人加强消防安全管理。"},{"i":7,"n":"第七条","txt":"高层公共建筑的业主单位、使用单位应当履行下列消防安全职责： （一）遵守消防法律法规，建立和落实消防安全管理制度； （二）明确消防安全管理机构或者消防安全管理人员； （三）组织开展防火巡查、检查，及时消除火灾隐患； （四）确保疏散通道、安全出口、消防车通道畅通； （五）对建筑消防设施、器材定期进行检验、维修，确保完好有效； （六）组织消防宣传教育培训，制定灭火和应急疏散预案，定期组织消防演练； （七）按照规定建立专职消防队、志愿消防队（微型消防站）等消防组织； （八）法律、法规规定的其他消防安全职责。 委托物业服务企业，或者明确统一管理人实施消防安全管理的，物业服务企业或者统一管理人应当按照约定履行前款规定的消防安全职责，业主单位、使用单位应当督促并配合物业服务企业或者统一管理人做好消防安全工作。"},{"i":8,"n":"第八条","txt":"高层公共建筑的业主、使用人、物业服务企业或者统一管理人应当明确专人担任消防安全管理人，负责整栋建筑的消防安全管理工作，并在建筑显著位置公示其姓名、联系方式和消防安全管理职责。 高层公共建筑的消防安全管理人应当履行下列消防安全管理职责： （一）拟订年度消防工作计划，组织实施日常消防安全管理工作； （二）组织开展防火检查、巡查和火灾隐患整改工作； （三）组织实施对建筑共用消防设施设备的维护保养； （四）管理专职消防队、志愿消防队（微型消防站）等消防组织； （五）组织开展消防安全的宣传教育和培训； （六）组织编制灭火和应急疏散综合预案并开展演练。 高层公共建筑的消防安全管理人应当具备与其职责相适应的消防安全知识和管理能力。对建筑高度超过100米的高层公共建筑，鼓励有关单位聘用相应级别的注册消防工程师或者相关工程类中级及以上专业技术职务的人员担任消防安全管理人。"},{"i":9,"n":"第九条","txt":"高层住宅建筑的业主、使用人应当履行下列消防安全义务： （一）遵守住宅小区防火安全公约和管理规约约定的消防安全事项； （二）按照不动产权属证书载明的用途使用建筑； （三）配合消防服务单位做好消防安全工作； （四）按照法律规定承担消防服务费用以及建筑消防设施维修、更新和改造的相关费用； （五）维护消防安全，保护消防设施，预防火灾，报告火警，成年人参加有组织的灭火工作； （六）法律、法规规定的其他消防安全义务。"},{"i":10,"n":"第十条","txt":"接受委托的高层住宅建筑的物业服务企业应当依法履行下列消防安全职责： （一）落实消防安全责任，制定消防安全制度，拟订年度消防安全工作计划和组织保障方案； （二）明确具体部门或者人员负责消防安全管理工作； （三）对管理区域内的共用消防设施、器材和消防标志定期进行检测、维护保养，确保完好有效； （四）组织开展防火巡查、检查，及时消除火灾隐患； （五）保障疏散通道、安全出口、消防车通道畅通，对占用、堵塞、封闭疏散通道、安全出口、消防车通道等违规行为予以制止；制止无效的，及时报告消防救援机构等有关行政管理部门依法处理； （六）督促业主、使用人履行消防安全义务； （七）定期向所在住宅小区业主委员会和业主、使用人通报消防安全情况，提示消防安全风险； （八）组织开展经常性的消防宣传教育； （九）制定灭火和应急疏散预案，并定期组织演练； （十）法律、法规规定和合同约定的其他消防安全职责。"},{"i":11,"n":"第十一条","txt":"消防救援机构和其他负责消防监督检查的机构依法对高层民用建筑进行消防监督检查，督促业主、使用人、受委托的消防服务单位等落实消防安全责任；对监督检查中发现的火灾隐患，通知有关单位或者个人立即采取措施消除隐患。 消防救援机构应当加强高层民用建筑消防安全法律、法规的宣传，督促、指导有关单位做好高层民用建筑消防安全宣传教育工作。"},{"i":12,"n":"第十二条","txt":"村民委员会、居民委员会应当依法组织制定防火安全公约，对高层民用建筑进行防火安全检查，协助人民政府和有关部门加强消防宣传教育；对老年人、未成年人、残疾人等开展有针对性的消防宣传教育，加强消防安全帮扶。"},{"i":13,"n":"第十三条","txt":"供水、供电、供气、供热、通信、有线电视等专业运营单位依法对高层民用建筑内由其管理的设施设备消防安全负责，并定期进行检查和维护。"},{"i":14,"n":"第十四条","txt":"高层民用建筑施工期间，建设单位应当与施工单位明确施工现场的消防安全责任。施工期间应当严格落实现场防范措施，配置消防器材，指定专人监护，采取防火分隔措施，不得影响其他区域的人员安全疏散和建筑消防设施的正常使用。 高层民用建筑的业主、使用人不得擅自变更建筑使用功能、改变防火防烟分区，不得违反消防技术标准使用易燃、可燃装修装饰材料。"},{"i":15,"n":"第十五条","txt":"高层民用建筑的业主、使用人或者物业服务企业、统一管理人应当对动用明火作业实行严格的消防安全管理，不得在具有火灾、爆炸危险的场所使用明火；因施工等特殊情况需要进行电焊、气焊等明火作业的，应当按照规定办理动火审批手续，落实现场监护人，配备消防器材，并在建筑主入口和作业现场显著位置公告。作业人员应当依法持证上岗，严格遵守消防安全规定，清除周围及下方的易燃、可燃物，采取防火隔离措施。作业完毕后，应当进行全面检查，消除遗留火种。 高层公共建筑内的商场、公共娱乐场所不得在营业期间动火施工。 高层公共建筑内应当确定禁火禁烟区域，并设置明显标志。"},{"i":16,"n":"第十六条","txt":"高层民用建筑内电器设备的安装使用及其线路敷设、维护保养和检测应当符合消防技术标准及管理规定。 高层民用建筑业主、使用人或者消防服务单位，应当安排专业机构或者电工定期对管理区域内由其管理的电器设备及线路进行检查；对不符合安全要求的，应当及时维修、更换。"},{"i":17,"n":"第十七条","txt":"高层民用建筑内燃气用具的安装使用及其管路敷设、维护保养和检测应当符合消防技术标准及管理规定。禁止违反燃气安全使用规定，擅自安装、改装、拆除燃气设备和用具。 高层民用建筑使用燃气应当采用管道供气方式。禁止在高层民用建筑地下部分使用液化石油气。"},{"i":18,"n":"第十八条","txt":"禁止在高层民用建筑内违反国家规定生产、储存、经营甲、乙类火灾危险性物品。"},{"i":19,"n":"第十九条","txt":"设有建筑外墙外保温系统的高层民用建筑，其管理单位应当在主入口及周边相关显著位置，设置提示性和警示性标识，标示外墙外保温材料的燃烧性能、防火要求。对高层民用建筑外墙外保温系统破损、开裂和脱落的，应当及时修复。高层民用建筑在进行外墙外保温系统施工时，建设单位应当采取必要的防火隔离以及限制住人和使用的措施，确保建筑内人员安全。 禁止使用易燃、可燃材料作为高层民用建筑外墙外保温材料。禁止在其建筑内及周边禁放区域燃放烟花爆竹；禁止在其外墙周围堆放可燃物。对于使用难燃外墙外保温材料或者采用与基层墙体、装饰层之间有空腔的建筑外墙外保温系统的高层民用建筑，禁止在其外墙动火用电。"},{"i":20,"n":"第二十条","txt":"高层民用建筑的电缆井、管道井等竖向管井和电缆桥架应当在每层楼板处进行防火封堵，管井检查门应当采用防火门。 禁止占用电缆井、管道井，或者在电缆井、管道井等竖向管井堆放杂物。"},{"i":21,"n":"第二十一条","txt":"高层民用建筑的户外广告牌、外装饰不得采用易燃、可燃材料，不得妨碍防烟排烟、逃生和灭火救援，不得改变或者破坏建筑立面防火结构。 禁止在高层民用建筑外窗设置影响逃生和灭火救援的障碍物。 建筑高度超过50米的高层民用建筑外墙上设置的装饰、广告牌应当采用不燃材料并易于破拆。"},{"i":22,"n":"第二十二条","txt":"禁止在消防车通道、消防车登高操作场地设置构筑物、停车泊位、固定隔离桩等障碍物。 禁止在消防车通道上方、登高操作面设置妨碍消防车作业的架空管线、广告牌、装饰物等障碍物。"},{"i":23,"n":"第二十三条","txt":"高层公共建筑内餐饮场所的经营单位应当及时对厨房灶具和排油烟罩设施进行清洗，排油烟管道每季度至少进行一次检查、清洗。 高层住宅建筑的公共排油烟管道应当定期检查，并采取防火措施。"},{"i":24,"n":"第二十四条","txt":"除为满足高层民用建筑的使用功能所设置的自用物品暂存库房、档案室和资料室等附属库房外，禁止在高层民用建筑内设置其他库房。 高层民用建筑的附属库房应当采取相应的防火分隔措施，严格遵守有关消防安全管理规定。"},{"i":25,"n":"第二十五条","txt":"高层民用建筑内的锅炉房、变配电室、空调机房、自备发电机房、储油间、消防水泵房、消防水箱间、防排烟风机房等设备用房应当按照消防技术标准设置，确定为消防安全重点部位，设置明显的防火标志，实行严格管理，并不得占用和堆放杂物。"},{"i":26,"n":"第二十六条","txt":"高层民用建筑消防控制室应当由其管理单位实行24小时值班制度，每班不应少于2名值班人员。 消防控制室值班操作人员应当依法取得相应等级的消防行业特有工种职业资格证书，熟练掌握火警处置程序和要求，按照有关规定检查自动消防设施、联动控制设备运行情况，确保其处于正常工作状态。 消防控制室内应当保存高层民用建筑总平面布局图、平面布置图和消防设施系统图及控制逻辑关系说明、建筑消防设施维修保养记录和检测报告等资料。"},{"i":27,"n":"第二十七条","txt":"高层公共建筑内有关单位、高层住宅建筑所在社区居民委员会或者物业服务企业按照规定建立的专职消防队、志愿消防队（微型消防站）等消防组织，应当配备必要的人员、场所和器材、装备，定期进行消防技能培训和演练，开展防火巡查、消防宣传，及时处置、扑救初起火灾。"},{"i":28,"n":"第二十八条","txt":"高层民用建筑的疏散通道、安全出口应当保持畅通，禁止堆放物品、锁闭出口、设置障碍物。平时需要控制人员出入或者设有门禁系统的疏散门，应当保证发生火灾时易于开启，并在现场显著位置设置醒目的提示和使用标识。 高层民用建筑的常闭式防火门应当保持常闭，闭门器、顺序器等部件应当完好有效；常开式防火门应当保证发生火灾时自动关闭并反馈信号。 禁止圈占、遮挡消火栓，禁止在消火栓箱内堆放杂物，禁止在防火卷帘下堆放物品。"},{"i":29,"n":"第二十九条","txt":"高层民用建筑内应当在显著位置设置标识，指示避难层（间）的位置。 禁止占用高层民用建筑避难层（间）和避难走道或者堆放杂物，禁止锁闭避难层（间）和避难走道出入口。"},{"i":30,"n":"第三十条","txt":"高层公共建筑的业主、使用人应当按照国家标准、行业标准配备灭火器材以及自救呼吸器、逃生缓降器、逃生绳等逃生疏散设施器材。 高层住宅建筑应当在公共区域的显著位置摆放灭火器材，有条件的配置自救呼吸器、逃生绳、救援哨、疏散用手电筒等逃生疏散设施器材。 鼓励高层住宅建筑的居民家庭制定火灾疏散逃生计划，并配置必要的灭火和逃生疏散器材。"},{"i":31,"n":"第三十一条","txt":"高层民用建筑的消防车通道、消防车登高操作场地、灭火救援窗、灭火救援破拆口、消防车取水口、室外消火栓、消防水泵接合器、常闭式防火门等应当设置明显的提示性、警示性标识。消防车通道、消防车登高操作场地、防火卷帘下方还应当在地面标识出禁止占用的区域范围。消火栓箱、灭火器箱上应当张贴使用方法的标识。 高层民用建筑的消防设施配电柜电源开关、消防设备用房内管道阀门等应当标识开、关状态；对需要保持常开或者常闭状态的阀门，应当采取铅封等限位措施。"},{"i":32,"n":"第三十二条","txt":"不具备自主维护保养检测能力的高层民用建筑业主、使用人或者物业服务企业应当聘请具备从业条件的消防技术服务机构或者消防设施施工安装企业对建筑消防设施进行维护保养和检测；存在故障、缺损的，应当立即组织维修、更换，确保完好有效。 因维修等需要停用建筑消防设施的，高层民用建筑的管理单位应当严格履行内部审批手续，制定应急方案，落实防范措施，并在建筑入口处等显著位置公告。"},{"i":33,"n":"第三十三条","txt":"高层公共建筑消防设施的维修、更新、改造的费用，由业主、使用人按照有关法律规定承担，共有部分按照专有部分建筑面积所占比例承担。 高层住宅建筑的消防设施日常运行、维护和维修、更新、改造费用，由业主依照法律规定承担；委托消防服务单位的，消防设施的日常运行、维护和检测费用应当纳入物业服务或者消防技术服务专项费用。共用消防设施的维修、更新、改造费用，可以依法从住宅专项维修资金列支。"},{"i":34,"n":"第三十四条","txt":"高层民用建筑应当进行每日防火巡查，并填写巡查记录。其中，高层公共建筑内公众聚集场所在营业期间应当至少每2小时进行一次防火巡查，医院、养老院、寄宿制学校、幼儿园应当进行白天和夜间防火巡查，高层住宅建筑和高层公共建筑内的其他场所可以结合实际确定防火巡查的频次。 防火巡查应当包括下列内容： （一）用火、用电、用气有无违章情况； （二）安全出口、疏散通道、消防车通道畅通情况； （三）消防设施、器材完好情况，常闭式防火门关闭情况； （四）消防安全重点部位人员在岗在位等情况。"},{"i":35,"n":"第三十五条","txt":"高层住宅建筑应当每月至少开展一次防火检查，高层公共建筑应当每半个月至少开展一次防火检查，并填写检查记录。 防火检查应当包括下列内容： （一）安全出口和疏散设施情况； （二）消防车通道、消防车登高操作场地和消防水源情况； （三）灭火器材配置及有效情况； （四）用火、用电、用气和危险品管理制度落实情况； （五）消防控制室值班和消防设施运行情况； （六）人员教育培训情况； （七）重点部位管理情况； （八）火灾隐患整改以及防范措施的落实等情况。"},{"i":36,"n":"第三十六条","txt":"对防火巡查、检查发现的火灾隐患，高层民用建筑的业主、使用人、受委托的消防服务单位，应当立即采取措施予以整改。 对不能当场改正的火灾隐患，应当明确整改责任、期限，落实整改措施，整改期间应当采取临时防范措施，确保消防安全；必要时，应当暂时停止使用危险部位。"},{"i":37,"n":"第三十七条","txt":"禁止在高层民用建筑公共门厅、疏散走道、楼梯间、安全出口停放电动自行车或者为电动自行车充电。 鼓励在高层住宅小区内设置电动自行车集中存放和充电的场所。电动自行车存放、充电场所应当独立设置，并与高层民用建筑保持安全距离；确需设置在高层民用建筑内的，应当与该建筑的其他部分进行防火分隔。 电动自行车存放、充电场所应当配备必要的消防器材，充电设施应当具备充满自动断电功能。"},{"i":38,"n":"第三十八条","txt":"鼓励高层民用建筑推广应用物联网和智能化技术手段对电气、燃气消防安全和消防设施运行等进行监控和预警。 未设置自动消防设施的高层住宅建筑，鼓励因地制宜安装火灾报警和喷水灭火系统、火灾应急广播以及可燃气体探测、无线手动火灾报警、无线声光火灾警报等消防设施。"},{"i":39,"n":"第三十九条","txt":"高层民用建筑的业主、使用人或者消防服务单位、统一管理人应当每年至少组织开展一次整栋建筑的消防安全评估。消防安全评估报告应当包括存在的消防安全问题、火灾隐患以及改进措施等内容。"},{"i":40,"n":"第四十条","txt":"鼓励、引导高层公共建筑的业主、使用人投保火灾公众责任保险。"},{"i":41,"n":"第四十一条","txt":"高层公共建筑内的单位应当每半年至少对员工开展一次消防安全教育培训。 高层公共建筑内的单位应当对本单位员工进行上岗前消防安全培训，并对消防安全管理人员、消防控制室值班人员和操作人员、电工、保安员等重点岗位人员组织专门培训。 高层住宅建筑的物业服务企业应当每年至少对居住人员进行一次消防安全教育培训，进行一次疏散演练。"},{"i":42,"n":"第四十二条","txt":"高层民用建筑应当在每层的显著位置张贴安全疏散示意图，公共区域电子显示屏应当播放消防安全提示和消防安全知识。 高层公共建筑除遵守本条第一款规定外，还应当在首层显著位置提示公众注意火灾危险，以及安全出口、疏散通道和灭火器材的位置。 高层住宅小区除遵守本条第一款规定外，还应当在显著位置设置消防安全宣传栏，在高层住宅建筑单元入口处提示安全用火、用电、用气，以及电动自行车存放、充电等消防安全常识。"},{"i":43,"n":"第四十三条","txt":"高层民用建筑应当结合场所特点，分级分类编制灭火和应急疏散预案。 规模较大或者功能业态复杂，且有两个及以上业主、使用人或者多个职能部门的高层公共建筑，有关单位应当编制灭火和应急疏散总预案，各单位或者职能部门应当根据场所、功能分区、岗位实际编制专项灭火和应急疏散预案或者现场处置方案（以下统称分预案）。 灭火和应急疏散预案应当明确应急组织机构，确定承担通信联络、灭火、疏散和救护任务的人员及其职责，明确报警、联络、灭火、疏散等处置程序和措施。"},{"i":44,"n":"第四十四条","txt":"高层民用建筑的业主、使用人、受委托的消防服务单位应当结合实际，按照灭火和应急疏散总预案和分预案分别组织实施消防演练。 高层民用建筑应当每年至少进行一次全要素综合演练，建筑高度超过100米的高层公共建筑应当每半年至少进行一次全要素综合演练。编制分预案的，有关单位和职能部门应当每季度至少进行一次综合演练或者专项灭火、疏散演练。 演练前，有关单位应当告知演练范围内的人员并进行公告；演练时，应当设置明显标识；演练结束后，应当进行总结评估，并及时对预案进行修订和完善。"},{"i":45,"n":"第四十五条","txt":"高层公共建筑内的人员密集场所应当按照楼层、区域确定疏散引导员,负责在火灾发生时组织、引导在场人员安全疏散。"},{"i":46,"n":"第四十六条","txt":"火灾发生时，发现火灾的人员应当立即拨打119电话报警。 火灾发生后，高层民用建筑的业主、使用人、消防服务单位应当迅速启动灭火和应急疏散预案，组织人员疏散，扑救初起火灾。 火灾扑灭后，高层民用建筑的业主、使用人、消防服务单位应当组织保护火灾现场，协助火灾调查。"},{"i":47,"n":"第四十七条","txt":"违反本规定，有下列行为之一的，由消防救援机构责令改正，对经营性单位和个人处2000元以上10000元以下罚款，对非经营性单位和个人处500元以上1000元以下罚款： （一）在高层民用建筑内进行电焊、气焊等明火作业，未履行动火审批手续、进行公告，或者未落实消防现场监护措施的； （二）高层民用建筑设置的户外广告牌、外装饰妨碍防烟排烟、逃生和灭火救援，或者改变、破坏建筑立面防火结构的； （三）未设置外墙外保温材料提示性和警示性标识，或者未及时修复破损、开裂和脱落的外墙外保温系统的； （四）未按照规定落实消防控制室值班制度，或者安排不具备相应条件的人员值班的； （五）未按照规定建立专职消防队、志愿消防队等消防组织的； （六）因维修等需要停用建筑消防设施未进行公告、未制定应急预案或者未落实防范措施的； （七）在高层民用建筑的公共门厅、疏散走道、楼梯间、安全出口停放电动自行车或者为电动自行车充电，"},{"i":48,"n":"第四十八条","txt":"违反本规定的其他消防安全违法行为，依照《中华人民共和国消防法》第六十条、第六十一条、第六十四条、第六十五条、第六十六条、第六十七条、第六十八条、第六十九条和有关法律法规予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"消防救援机构及其工作人员在高层民用建筑消防监督检查中，滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"本规定下列用语的含义： （一）高层住宅建筑，是指建筑高度大于27米的住宅建筑。 （二）高层公共建筑，是指建筑高度大于24米的非单层公共建筑，包括宿舍建筑、公寓建筑、办公建筑、科研建筑、文化建筑、商业建筑、体育建筑、医疗建筑、交通建筑、旅游建筑、通信建筑等。 （三）业主，是指高层民用建筑的所有权人，包括单位和个人。 （四）使用人，是指高层民用建筑的承租人和其他实际使用人，包括单位和个人。"},{"i":51,"n":"第五十一条","txt":"本规定自2021年8月1日起施行。"}]};
